-- Migration: add_2023_summer_substantive_q1_to_q40
--
-- Source: 2024 winter substantive-law batch (פברואר 2024, חלק ג', דין מהותי).
-- Two .docx files from the LawPass Content Pipeline Drive folder:
--   * (דין מהותי) 1-20  JSON.docx
--   * (דין מהותי) 21-40.docx  (contains Q21–Q40, with one duplicate of Q23)
--
-- Pipeline: scripts/ingestion/{parse_docx,normalize,generate_migration}.py +
-- the per-batch classification at scripts/ingestion/classifications/
-- 2024_winter_substantive.json. Re-classifies every question against the
-- substantive taxonomy from migration 20260526000001 (the JSON's own
-- chapter/subtopic — procedural placeholders from a stale Nevo template —
-- is ignored). source_metadata is also derived from the folder path, not
-- from the JSON's stale 2019/summer default.
--
-- Drops:
--   * 2024-W-S-Q20 — exact-content dup of Q18 (same question_text + choices).
--   * 2024-W-S-Q27 — JSON structurally broken beyond automatic repair.
--   * one in-file Q23 duplicate (the second of two consecutive Q23 fences).
--
-- Idempotency: each DO $$ block early-returns (RAISE NOTICE) if its
-- external_id already exists. Safe to re-run.

-- ============================================================
-- Q01 — 2023-S-S-Q01 — chapter=torts subtopic=negligence
-- classifier_note: Medical negligence + autonomy violation (biopsy without consent during another procedure)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '47159128-653e-491f-be4f-0d116bf7732c'::uuid;
  v_group_id uuid := '856ef909-1795-4b30-a1b4-fa0c215c2543'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '64a7761c-ff44-41b3-8370-e4b61cf08a7a'::uuid;
  v_ang_1 uuid := '83838b45-05e0-48da-a591-d4d3f83af68b'::uuid;
  v_ang_2 uuid := '711d4a38-3dd6-4d09-88ee-f0853dc29b94'::uuid;
  v_ang_3 uuid := 'ed02e088-c8b2-4ff3-b6de-2a5c592a348c'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q01';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 1, '2023-S-S-Q01';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'torts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'torts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'negligence' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'negligence', 'torts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q01', v_chapter_id, v_subtopic_id, 'אגב ביצוע הליך רפואי אחד החליטו הרופאים לבצע בגופו של המטופל הליך רפואי נוסף של לקיחת דגימה של רקמה מגופו לשם בדיקתה מחשש למחלה (להלן: ביופסיה). עם כל חשיבותו של הליך הביופסיה, לא היה הכרח חיוני לבצעו באותו מעמד. הרופאים לא עדכנו את החולה בדבר כוונתם לבצע את הביופסיה ולא קיבלו את הסכמתו. בעקבות הליך הביופסיה נגרם נזק לחולה. הוכח בבית המשפט שלא הייתה כל רשלנות רפואית באופן שבו נלקחה הביופסיה, והנזק שאירע היה בגדר הסיכון הרגיל בהליך רפואי של ביופסיה מסוג זה. עוד הוכח כי אילו היה החולה נשאל מראש וכל המידע היה גלוי בפניו, היה מסכים ללקיחת הביופסיה. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 1}'::jsonb, 'השאלה עוסקת בדיני רשלנות רפואית, ובפרט בהבחנה בין עילת תביעה בגין היעדר הסכמה מדעת לבין ראש הנזק של פגיעה באוטונומיה. היא בוחנת את דרישת הקשר הסיבתי לנזק גוף ואת היקף הפיצויים במקרים בהם המטופל היה מסכים לטיפול גם אם היה מקבל את מלוא המידע.', 'השאלה מתייחסת למקרה בו בוצע הליך רפואי (ביופסיה) ללא הסכמת המטופל, אך הוכח כי המטופל היה מסכים לביצועו אילו קיבל את מלוא המידע. כמו כן, לא הוכחה רשלנות בביצוע הביופסיה עצמה, והנזק היה בגדר סיכון רגיל.
על פי הפסיקה, ובמיוחד הלכת דעקה, היעדר הסכמה מדעת לטיפול רפואי מהווה פגיעה בזכותו של המטופל לאוטונומיה על גופו. ע"א 2781/93 מיאסה עלי דעקה נ'' בית החולים "כרמל" חיפה (29.08.1999) עם זאת, יש להבחין בין פיצוי בגין נזק גוף שנגרם עקב היעדר הסכמה מדעת לבין פיצוי בגין פגיעה באוטונומיה.
כדי לזכות בפיצוי בגין נזק גוף עקב היעדר הסכמה מדעת, יש להוכיח קשר סיבתי בין אי-קבלת ההסכמה לבין הנזק, כלומר שהמטופל לא היה מסכים לטיפול אילו קיבל את המידע הנדרש. ת"א (שלום קריות) 42185-12-20 פלוני נ'' מדינת ישראל - משרד הבריאות (06.11.2022) במקרה הנדון, הוכח כי החולה היה מסכים לביופסיה גם אם היה מקבל את מלוא המידע. לכן, לא מתקיים קשר סיבתי בין אי-קבלת ההסכמה לבין נזק הגוף, והחולה אינו זכאי לפיצוי בגין נזק הגוף.
אולם, עצם שלילת כוח הבחירה מהמטופל, גם אם בדיעבד היה מסכים, מהווה פגיעה בזכותו לאוטונומיה. פגיעה זו מזכה בפיצוי, גם בהיעדר קשר סיבתי לנזק גוף. ת"א (שלום קריות) 42185-12-20 פלוני נ'' מדינת ישראל - משרד הבריאות (06.11.2022) פיצוי זה ניתן בגין הנזק הלא ממוני שנגרם למטופל עקב הפגיעה בכבודו ובחופש הבחירה שלו. ע"א 2781/93 מיאסה עלי דעקה נ'' בית החולים "כרמל" חיפה (29.08.1999)', 'הטעות הנפוצה היא לבלבל בין דרישת הקשר הסיבתי לנזק גוף (היעדר הסכמה מדעת) לבין העדר דרישה כזו לפיצוי על הפגיעה באוטונומיה, או לחשוב שאין כלל פיצוי אם החולה היה מסכים בכל מקרה.',
    '["הסכמה מדעת", "פגיעה באוטונומיה", "קשר סיבתי", "רשלנות רפואית", "נזק לא ממוני", "חוק זכויות החולה"]'::jsonb, '**וריאציה 1 — קשר סיבתי לנזק גוף:** האם היעדר הסכמה מדעת שגרם לנזק גוף מזכה בפיצוי על נזק הגוף? ← כן, אם החולה לא היה מסכים לטיפול אילו ידע. נבו - המתמחה, דיני נזיקין (2026) | פיצויים בגין טיפול רפואי שניתן ללא הסכמה מדעת
**וריאציה 2 — פגיעה באוטונומיה:** מתי נפסק פיצוי בגין פגיעה באוטונומיה? ← גם אם המטופל היה מסכים לטיפול, על עצם שלילת כוח הבחירה. ת"א (שלום קריות) 42185-12-20 פלוני נ'' מדינת ישראל - משרד הבריאות (06.11.2022)
**וריאציה 3 — כפל פיצוי:** האם ניתן לפסוק פיצוי נפרד בגין פגיעה באוטונומיה בנוסף לפיצוי על נזק גוף? ← לא, הפיצוי בגין אוטונומיה נבלע בדרך כלל בפיצוי הלא ממוני הכולל. רע"א 1081/21 פלונית נ'' שרותי בריאות כללית (01.09.2021)', 'היעדר הסכמה מדעת + החולה היה מסכים בכל מקרה + נזק גוף ← אין פיצוי על נזק גוף, אך יש פיצוי על פגיעה באוטונומיה (ראש נזק שיורי).', '["חוק זכויות החולה, תשנ\"ו-1996, סעיף 13", "ע\"א 2781/93 מיאסה עלי דעקה נ'' בית החולים \"כרמל\" חיפה (29.08.1999)", "ע\"א 4576/08 ליה עטרה בן-צבי נ'' פרופ'' יהודה היס (07.07.2011)", "רע\"א 1081/21 פלונית נ'' שרותי בריאות כללית (01.09.2021)", "ת\"א (שלום קריות) 42185-12-20 פלוני נ'' מדינת ישראל - משרד הבריאות (06.11.2022)"]'::jsonb,
    'classification_review: original chapter=''חוקתי + בינלאומי פרטי'' subtopic=''ביטול סמכות בג"ץ'' → mapped chapter=''torts'' subtopic=''negligence'' | classifier_note: Medical negligence + autonomy violation (biopsy without consent during another procedure) | source_review_note: השאלה עוסקת בדיני נזיקין, ובפרט ברשלנות רפואית ופיצוי בגין פגיעה באוטונומיה. תחום זה אינו נכלל ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''ביטול סמכות בג"ץ'' נבחר כברירת מחדל תחת ''חוקתי + בינלאומי פרטי'' בשל הקשר העקיף לזכויות יסוד, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני נזיקין'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'מאחר שהוכח שהחולה היה מסכים בכל מקרה, אין הוא זכאי לפיצוי כלשהו.', false, 'טענה זו שגויה, שכן גם אם החולה היה מסכים לטיפול, עצם הפגיעה בזכותו לאוטונומיה מזכה אותו בפיצוי, גם אם לא בגין נזק הגוף.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מאחר שהחולה לא הסכים לביצוע ביופסיה, הוא זכאי לפיצוי בגין נזק הגוף שנגרם לו אף שלא הוכחה רשלנות בביצוע הביופסיה.', false, 'טענה זו שגויה, שכן כדי לזכות בפיצוי בגין נזק גוף עקב היעדר הסכמה מדעת, יש להוכיח קשר סיבתי בין אי-קבלת ההסכמה לבין הנזק, כלומר שהחולה לא היה מסכים לטיפול אילו קיבל את המידע.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מאחר שהחולה לא הסכים לביצוע ביופסיה, הוא זכאי לפיצוי רק בגין הפגיעה בזכותו על גופו.', true, 'תשובה זו נכונה. מכיוון שהחולה היה מסכים לביופסיה גם אם היה מקבל את מלוא המידע, לא מתקיים קשר סיבתי בין אי-קבלת ההסכמה לבין נזק הגוף. עם זאת, עצם שלילת זכות הבחירה מהווה פגיעה באוטונומיה המזכה בפיצוי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'מאחר שהחולה לא הסכים לביצוע ביופסיה, הוא זכאי לפיצוי הן בגין נזק הגוף שנגרם לו הן בגין הפגיעה בזכותו על גופו.', false, 'טענה זו שגויה, שכן פיצוי בגין נזק גוף יינתן רק אם הוכח קשר סיבתי בין אי-קבלת ההסכמה לבין הנזק, מה שלא הוכח במקרה זה.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פיצוי בגין נזק גוף כתוצאה מהיעדר הסכמה מדעת',
    1, 'חולה עבר ניתוח ללא הסכמתו מדעת. הוכח כי הניתוח בוצע ללא רשלנות, אך אילו היה החולה מקבל את מלוא המידע אודות הסיכונים, הוא לא היה מסכים לניתוח. בעקבות הניתוח נגרם לחולה נזק גוף משמעותי. מה הדין לעניין זכאותו לפיצוי?', 'שאלה זו בוחנת את היקף הפיצויים בגין היעדר הסכמה מדעת כאשר קיים קשר סיבתי בין אי-קבלת ההסכמה לבין נזק גוף שנגרם. היא מדגישה את ההבחנה בין רשלנות בטיפול לבין רשלנות באי-קבלת הסכמה מדעת, ואת ההשלכות הפיצוייות של כל אחת מהן.', 'על פי חוק זכויות החולה, טיפול רפואי יינתן רק בהסכמה מדעת של המטופל. חוק זכויות החולה, תשנ"ו-1996, סעיף 13(א) כאשר טיפול רפואי ניתן ללא הסכמה מדעת, והוכח כי אילו היה המטופל מקבל את מלוא המידע הוא לא היה מסכים לטיפול, ובעקבות הטיפול נגרם לו נזק גוף, אזי קיים קשר סיבתי בין אי-קבלת ההסכמה לבין הנזק. במצב כזה, המטופל זכאי לפיצוי בגין כל הנזקים שנגרמו לו כתוצאה מהטיפול, לרבות נזקי גוף ממוניים ולא ממוניים. נבו - המתמחה, דיני נזיקין (2026) | פיצויים בגין טיפול רפואי שניתן ללא הסכמה מדעת הפיצוי בגין פגיעה באוטונומיה, במקרים אלו, נבלע בדרך כלל בתוך הפיצוי הכולל בגין הנזק הלא ממוני, כדי למנוע כפל פיצוי. רע"א 1081/21 פלונית נ'' שרותי בריאות כללית (01.09.2021)',
    'הטעות הנפוצה היא לחשוב שפיצוי בגין נזק גוף ניתן רק במקרה של רשלנות בביצוע הטיפול עצמו, ולא גם במקרה של היעדר הסכמה מדעת שגרמה לנזק.', '["הסכמה מדעת", "קשר סיבתי", "נזק גוף", "פיצויים ממוניים", "פיצויים לא ממוניים", "חוק זכויות החולה"]'::jsonb, '**וריאציה 1 — קשר סיבתי לנזק:** האם היעדר הסכמה מדעת שגרם לנזק גוף מזכה בפיצוי על נזק הגוף? ← כן, אם החולה לא היה מסכים לטיפול אילו ידע. נבו - המתמחה, דיני נזיקין (2026) | פיצויים בגין טיפול רפואי שניתן ללא הסכמה מדעת
**וריאציה 2 — כפל פיצוי:** האם ניתן לפסוק פיצוי נפרד בגין פגיעה באוטונומיה בנוסף לפיצוי על נזק גוף? ← לא, הפיצוי בגין אוטונומיה נבלע בדרך כלל בפיצוי הלא ממוני הכולל. רע"א 1081/21 פלונית נ'' שרותי בריאות כללית (01.09.2021)
**וריאציה 3 — בסיס חוקי:** מהו הבסיס החוקי לדרישת הסכמה מדעת? ← סעיף 13(א) לחוק זכויות החולה. חוק זכויות החולה, תשנ"ו-1996, סעיף 13(א)', 'היעדר הסכמה מדעת + קשר סיבתי לנזק גוף (המטופל לא היה מסכים) ← פיצוי על נזק גוף (ממוני ולא ממוני), פגיעה באוטונומיה נבלעת.',
    '["חוק זכויות החולה, תשנ\"ו-1996, סעיף 13(א)", "נבו - המתמחה, דיני נזיקין (2026), פיצויים בגין טיפול רפואי שניתן ללא הסכמה מדעת, עמ'' 68", "רע\"א 1081/21 פלונית נ'' שרותי בריאות כללית (01.09.2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'החולה זכאי לפיצוי בגין נזק הגוף שנגרם לו, וכן לפיצוי בגין הפגיעה באוטונומיה.', true, 'תשובה זו נכונה. במקרה זה, קיים קשר סיבתי בין אי-קבלת ההסכמה מדעת לבין נזק הגוף (החולה לא היה מסכים לניתוח אילו ידע), ולכן הוא זכאי לפיצוי בגין נזק הגוף. הפיצוי בגין פגיעה באוטונומיה ייכלל בדרך כלל בפיצוי הלא ממוני הכולל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'החולה זכאי לפיצוי רק בגין הפגיעה באוטונומיה, שכן לא הוכחה רשלנות בביצוע הניתוח.', false, 'טענה זו שגויה. במקרה זה, קיים קשר סיבתי בין אי-קבלת ההסכמה מדעת לבין נזק הגוף, ולכן החולה זכאי לפיצוי בגין נזק הגוף, ולא רק בגין הפגיעה באוטונומיה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'החולה אינו זכאי לפיצוי כלשהו, שכן הניתוח בוצע ללא רשלנות.', false, 'טענה זו שגויה. גם אם הניתוח לא היה רשלני, היעדר הסכמה מדעת שגרם לנזק גוף מזכה בפיצוי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'החולה זכאי לפיצוי בגין נזק הגוף רק אם יוכיח שהרופאים פעלו בזדון.', false, 'טענה זו שגויה. אין צורך להוכיח זדון; די בהיעדר הסכמה מדעת וקשר סיבתי לנזק גוף כדי לזכות בפיצוי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'ההבחנה בין היעדר הסכמה מדעת לפגיעה באוטונומיה',
    2, 'מהו ההבדל המרכזי בין עילת תביעה בגין היעדר הסכמה מדעת (המובילה לפיצוי על נזק גוף) לבין עילת תביעה בגין פגיעה באוטונומיה (כראש נזק עצמאי)?', 'שאלה זו עוסקת בהבחנה קריטית בדיני רשלנות רפואית: ההבדל בין עילת תביעה בגין היעדר הסכמה מדעת, הדורשת קשר סיבתי בין אי-הגילוי לנזק הגוף, לבין ראש הנזק של פגיעה באוטונומיה, המפצה על עצם שלילת כוח הבחירה של המטופל, גם ללא קשר סיבתי לנזק גוף.', 'ההבדל המרכזי בין היעדר הסכמה מדעת (כעילה לפיצוי על נזק גוף) לבין פגיעה באוטונומיה (כראש נזק עצמאי) טמון בשאלת הקשר הסיבתי. ת"א (שלום קריות) 42185-12-20 פלוני נ'' מדינת ישראל - משרד הבריאות (06.11.2022) לצורך ביסוס עוולת היעדר הסכמה מדעת, יש להצביע על קשר סיבתי בין הפרת חובת הגילוי לבין החלטת התובע אם להסכים לטיפול הרפואי אם לאו (המכונה ''סיבתיות ההחלטה''). ת"א (שלום קריות) 42185-12-20 פלוני נ'' מדינת ישראל - משרד הבריאות (06.11.2022) לעומת זאת, במקרים שבהם אין קשר סיבתי כזה (כלומר, המטופל היה מסכים לטיפול גם אם היה מקבל את מלוא המידע), עדיין ניתן לפסוק פיצוי בגין פגיעה באוטונומיה. ת"א (שלום קריות) 42185-12-20 פלוני נ'' מדינת ישראל - משרד הבריאות (06.11.2022) הפגיעה באוטונומיה היא ראש נזק לא ממוני המפצה על עצם שלילת כוח הבחירה של המטופל ועל הפגיעה בכבודו. ע"א 2781/93 מיאסה עלי דעקה נ'' בית החולים "כרמל" חיפה (29.08.1999)',
    'הטעות הנפוצה היא לבלבל בין דרישת הקשר הסיבתי לנזק גוף (היעדר הסכמה מדעת) לבין העדר דרישה כזו לפיצוי על הפגיעה באוטונומיה.', '["הסכמה מדעת", "פגיעה באוטונומיה", "קשר סיבתי", "סיבתיות ההחלטה", "נזק לא ממוני", "חוק זכויות החולה"]'::jsonb, '**וריאציה 1 — קשר סיבתי להחלטה:** מה נדרש להוכחת היעדר הסכמה מדעת לנזק גוף? ← קשר סיבתי בין אי-הגילוי להחלטת המטופל. ת"א (שלום קריות) 42185-12-20 פלוני נ'' מדינת ישראל - משרד הבריאות (06.11.2022)
**וריאציה 2 — פגיעה באוטונומיה:** מתי נפסק פיצוי בגין פגיעה באוטונומיה? ← גם אם המטופל היה מסכים לטיפול, על עצם שלילת כוח הבחירה. ת"א (שלום קריות) 42185-12-20 פלוני נ'' מדינת ישראל - משרד הבריאות (06.11.2022)
**וריאציה 3 — מהות הפיצוי:** מה מהות הפיצוי בגין פגיעה באוטונומיה? ← פיצוי על פגיעה בערך בלתי מוחשי, בכבוד ובחופש הבחירה. ע"א 2781/93 מיאסה עלי דעקה נ'' בית החולים "כרמל" חיפה (29.08.1999)', 'היעדר הסכמה מדעת (לנזק גוף) ← דורש קשר סיבתי להחלטה. פגיעה באוטונומיה ← לא דורש קשר סיבתי להחלטה, מפצה על שלילת כוח הבחירה.',
    '["ע\"א 2781/93 מיאסה עלי דעקה נ'' בית החולים \"כרמל\" חיפה (29.08.1999)", "ת\"א (שלום קריות) 42185-12-20 פלוני נ'' מדינת ישראל - משרד הבריאות (06.11.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'ההבדל המרכזי הוא בשאלת הקשר הסיבתי: היעדר הסכמה מדעת דורש קשר סיבתי בין אי-הגילוי להחלטת המטופל, בעוד שפגיעה באוטונומיה אינה דורשת קשר סיבתי כזה.', true, 'תשובה זו נכונה. ההבחנה המהותית בין שני ראשי הנזק טמונה בדרישת הקשר הסיבתי: פיצוי על נזק גוף עקב היעדר הסכמה מדעת דורש הוכחה שהמטופל היה מסרב לטיפול אילו קיבל את המידע, בעוד שפיצוי על פגיעה באוטונומיה ניתן על עצם שלילת כוח הבחירה, גם אם המטופל היה מסכים לטיפול.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'היעדר הסכמה מדעת מתייחס רק לנזקים ממוניים, ואילו פגיעה באוטונומיה מתייחסת רק לנזקים לא ממוניים.', false, 'טענה זו שגויה. היעדר הסכמה מדעת יכול לזכות בפיצויים ממוניים ולא ממוניים (אם קיים קשר סיבתי לנזק גוף), ופגיעה באוטונומיה היא ראש נזק לא ממוני.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'פגיעה באוטונומיה היא עוולה עצמאית, ואילו היעדר הסכמה מדעת הוא רק חלק מעוולת הרשלנות.', false, 'טענה זו שגויה. הפסיקה קבעה כי פגיעה באוטונומיה היא ראש נזק ולא עוולה עצמאית, והיעדר הסכמה מדעת יכול להקים עילת רשלנות או תקיפה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'אין הבדל מהותי, ושני המונחים מתייחסים לאותה עילת תביעה.', false, 'טענה זו שגויה. הפסיקה מבחינה באופן ברור בין שני ראשי הנזק, בעיקר בהקשר של דרישת הקשר הסיבתי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הגבלות על פיצוי בגין פגיעה באוטונומיה',
    3, 'באילו נסיבות הפסיקה נוטה לצמצם או לשלול פיצוי בגין פגיעה באוטונומיה?', 'שאלה זו בוחנת את המגמה בפסיקה לצמצם את היקף הפיצוי בגין פגיעה באוטונומיה, במיוחד כאשר כבר נפסק פיצוי בגין נזקים אחרים. היא מדגישה את הדרישה לפגיעה ''בליבת הזכות'' ואת הצורך ב''נזק תוצאתי סובייקטיבי'' כדי לזכות בפיצוי נפרד.', 'הפסיקה תחמה את זכות הפיצוי בגין פגיעה באוטונומיה במספר היבטים. ראשית, נקבע כי יינתן פיצוי בגין פגיעה באוטונומיה אך כאשר הפגיעה הייתה ''בליבת הזכות''. רע"א 1081/21 פלונית נ'' שרותי בריאות כללית (01.09.2021) שנית, כאשר שלילת כוח הבחירה של הנפגע גרמה ל''נזק תוצאתי סובייקטיבי'' המתבטא בתחושות של כעס, תסכול ותחושות שליליות אחרות. רע"א 1081/21 פלונית נ'' שרותי בריאות כללית (01.09.2021) בנוסף, הפיצוי בגין פגיעה באוטונומיה הוא חלק מהנזק הלא ממוני, ולכן, למעט במצבים חריגים, אין לפסוק פיצוי בגין פגיעה באוטונומיה בנוסף לפיצוי שנפסק בגין נזק לא ממוני בעילה של הסכמה שלא מדעת או התרשלות בטיפול, כדי למנוע כפל פיצוי. רע"א 1081/21 פלונית נ'' שרותי בריאות כללית (01.09.2021)',
    'הטעות הנפוצה היא לחשוב שכל פגיעה באוטונומיה, ללא קשר לחומרתה או לנזקים אחרים, מזכה תמיד בפיצוי נפרד ומשמעותי.', '["פגיעה באוטונומיה", "ליבת הזכות", "נזק תוצאתי סובייקטיבי", "כפל פיצוי", "נזק לא ממוני", "רשלנות רפואית"]'::jsonb, '**וריאציה 1 — כפל פיצוי:** מתי לא יינתן פיצוי נפרד בגין אוטונומיה? ← כאשר כבר נפסק פיצוי על נזק לא ממוני עקב רשלנות או היעדר הסכמה מדעת. רע"א 1081/21 פלונית נ'' שרותי בריאות כללית (01.09.2021)
**וריאציה 2 — תנאי לפיצוי:** מהם התנאים לפיצוי בגין אוטונומיה? ← פגיעה בליבת הזכות ונזק תוצאתי סובייקטיבי. רע"א 1081/21 פלונית נ'' שרותי בריאות כללית (01.09.2021)
**וריאציה 3 — עובר:** האם עובר זכאי לפיצוי בגין פגיעה באוטונומיה? ← לא, לעובר אין אוטונומיה שיכולה להיפגע. רע"א 1081/21 פלונית נ'' שרותי בריאות כללית (01.09.2021)', 'פיצוי בגין אוטונומיה מצומצם ← לא יינתן כפל פיצוי, דורש פגיעה בליבת הזכות ונזק תוצאתי סובייקטיבי.',
    '["רע\"א 1081/21 פלונית נ'' שרותי בריאות כללית (01.09.2021)", "ע\"א 2278/16 פלונית נ'' מדינת ישראל (12.03.2018)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כאשר המטופל זכאי לפיצויים בגין נזק גוף עקב רשלנות בטיפול או היעדר הסכמה מדעת, וכאשר הפגיעה באוטונומיה אינה בליבת הזכות או לא גרמה לנזק תוצאתי סובייקטיבי.', true, 'תשובה זו נכונה. הפסיקה נוטה לצמצם פיצוי נפרד בגין אוטונומיה כדי למנוע כפל פיצוי, וכאשר הפגיעה אינה מהותית או לא גרמה לתחושות שליליות ממשיות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'רק כאשר המטופל לא סבל כלל מנזק גופני או נפשי כתוצאה מהטיפול.', false, 'טענה זו שגויה. פיצוי בגין אוטונומיה יכול להינתן גם ללא נזק גופני, אך הוא נשלל או מצומצם בנסיבות אחרות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כאשר הרופא פעל בתום לב מוחלט, גם אם לא קיבל הסכמה מדעת.', false, 'טענה זו שגויה. תום ליבו של הרופא אינו שולל פגיעה באוטונומיה, אם לא נתקבלה הסכמה מדעת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'רק במקרים בהם המטופל ויתר מראש על זכותו לקבל מידע.', false, 'טענה זו שגויה. ויתור מראש על זכות לקבל מידע הוא מצב חריג, אך ישנן נסיבות נוספות לצמצום הפיצוי בגין אוטונומיה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'אופן מתן הסכמה מדעת וסייגים',
    4, 'מטופל נזקק לטיפול רפואי דחוף המנוי בתוספת הראשונה לחוק זכויות החולה, אך אינו מסוגל לתת הסכמה מדעת. מהו אופן קבלת ההסכמה במקרה זה?', 'שאלה זו עוסקת בסייגים לדרישת הסכמה מדעת, ובפרט במצב חירום רפואי, כפי שקבוע בחוק זכויות החולה. היא בוחנת את ההוראות הספציפיות לגבי אופן קבלת ההסכמה במקרים בהם המטופל אינו כשיר לתת אותה בעצמו.', 'חוק זכויות החולה קובע כי לא יינתן טיפול רפואי למטופל אלא אם כן נתן לכך המטופל הסכמה מדעת. חוק זכויות החולה, תשנ"ו-1996, סעיף 13(א) עם זאת, סעיף 15 לחוק קובע חריגים לדרישה זו. במצב חירום רפואי, רשאי מטפל לתת טיפול רפואי דחוף גם ללא הסכמתו מדעת של המטופל, אם בשל נסיבות החירום לא ניתן לקבל את הסכמתו מדעת. חוק זכויות החולה, תשנ"ו-1996, סעיף 15(3) כאשר מדובר בטיפול רפואי המנוי בתוספת הראשונה לחוק (טיפולים מורכבים או פולשניים), טיפול זה יינתן בהסכמת שלושה רופאים, אלא אם כן נסיבות החירום אינן מאפשרות זאת. חוק זכויות החולה, תשנ"ו-1996, סעיף 15(3) בנוסף, דבר ההסכמה חייב להיות מתועד בכתב סמוך ככל האפשר לאחר מכן. חוק זכויות החולה, תשנ"ו-1996, סעיף 14(ד)',
    'הטעות הנפוצה היא לחשוב שבמצב חירום אין צורך כלל בהסכמה, או לבלבל בין סוגי הטיפולים השונים והדרישות הספציפיות לכל אחד מהם.', '["הסכמה מדעת", "מצב חירום רפואי", "חוק זכויות החולה", "טיפול בתוספת הראשונה", "תיעוד בכתב", "הסכמת רופאים"]'::jsonb, '**וריאציה 1 — מצב חירום:** האם ניתן לטפל ללא הסכמה מדעת במצב חירום? ← כן, בתנאים מסוימים הקבועים בחוק. חוק זכויות החולה, תשנ"ו-1996, סעיף 15(3)

**וריאציה 2 — טיפול בתוספת הראשונה:** מה נדרש לטיפול בתוספת הראשונה במצב חירום? ← הסכמת שלושה רופאים (אלא אם נסיבות החירום אינן מאפשרות). חוק זכויות החולה, תשנ"ו-1996, סעיף 15(3)
**וריאציה 3 — תיעוד:** האם נדרש תיעוד בכתב במצב חירום? ← כן, סמוך ככל האפשר לאחר מכן. חוק זכויות החולה, תשנ"ו-1996, סעיף 14(ד)', 'מצב חירום + טיפול בתוספת הראשונה + מטופל לא כשיר ← הסכמת 3 רופאים + תיעוד בכתב (ס'' 15(3) ו-14(ד) לחוק זכויות החולה).',
    '["חוק זכויות החולה, תשנ\"ו-1996, סעיפים 13(א), 14(ד), 15(3)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'הטיפול יינתן בהסכמת שלושה רופאים, ובלבד שדבר ההסכמה יתועד בכתב סמוך ככל האפשר לאחר מכן.', true, 'תשובה זו נכונה. במצב חירום רפואי, כאשר המטופל אינו מסוגל לתת הסכמה מדעת לטיפול המנוי בתוספת הראשונה, נדרשת הסכמת שלושה רופאים, ותיעוד בכתב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'הטיפול יינתן ללא הסכמה כלל, שכן מדובר במצב חירום.', false, 'טענה זו שגויה. גם במצב חירום, חוק זכויות החולה קובע מנגנונים לקבלת הסכמה, ולא מאפשר טיפול ללא כל הסכמה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'הטיפול יינתן רק לאחר קבלת אישור מבית המשפט.', false, 'טענה זו שגויה. במצב חירום רפואי, אין צורך באישור בית משפט, אלא בהסכמת שלושה רופאים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'הטיפול יינתן בהסכמת בן משפחה מדרגה ראשונה בלבד.', false, 'טענה זו שגויה. הסכמת בן משפחה רלוונטית במקרים מסוימים, אך לא במצב חירום לטיפול המנוי בתוספת הראשונה, שם נדרשת הסכמת שלושה רופאים.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 1, '2023-S-S-Q01';
END
$$;

-- ============================================================
-- Q02 — 2023-S-S-Q02 — chapter=contracts subtopic=limitation
-- classifier_note: Statute of limitations — discovery rule (סעיף 9 חוק ההתיישנות, surgeon's apology by SMS 8 years later)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'f3f55438-36a2-42fa-873c-597c61498247'::uuid;
  v_group_id uuid := '9fd6d9c2-8875-4f01-b2ba-78e490032586'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '2bf00284-c6cb-4e5c-9242-02a22ca9ee8e'::uuid;
  v_ang_1 uuid := 'a66d0145-d84b-4a55-8e21-fbc31d8f2be1'::uuid;
  v_ang_2 uuid := '84c4db2e-8f61-4b12-a919-9447707200a4'::uuid;
  v_ang_3 uuid := '78392fc3-7ee4-460e-b6a2-8e37bf0ed853'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q02';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 2, '2023-S-S-Q02';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'limitation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'limitation', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q02', v_chapter_id, v_subtopic_id, 'יסמין עברה תאונה קשה. בבית החולים הצילו את חייה, אך רגליה נקטעו. 8 שנים אחר כך היא קיבלה מסרון לטלפון הנייד האישי שלה מהרופא שניתח אותה: "קטענו את רגלך הימנית בטעות. אני מתחרט כל יום מאז, אבל לא התנצלתי כי פחדתי שתתבעי. עכשיו כשעבר מספיק זמן אני מבקש את סליחתך". האם זכותה של יסמין לתבוע התיישנה?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 2}'::jsonb, 'השאלה עוסקת בדיני התיישנות, ובפרט בהוראת סעיף 9 לחוק ההתיישנות, התשי"ח-1958, הדנה בהודאה בקיום זכות המאפסת את מרוץ ההתיישנות. היא בוחנת את הדרישות הצורניות והמהותיות להודאה כזו, ואת השאלה האם מסרון יכול להיחשב ל"הודאה בכתב" לצורך סעיף זה.', 'תקופת ההתיישנות הכללית בתביעות שאינן במקרקעין היא 7 שנים, כקבוע בסעיף 5(1) לחוק ההתיישנות, תשי"ח-1958. חוק ההתיישנות, תשי"ח-1958, סעיף 5(1) במקרה הנדון, התאונה אירעה לפני 8 שנים, ולכן עילת התביעה התיישנה בחלוף 7 שנים ממועד התאונה. סעיף 9 לחוק ההתיישנות קובע כי הודאה של הנתבע, בכתב או בפני בית משפט, בקיום זכות התובע, תתחיל מחדש את מרוץ ההתיישנות מיום ההודאה. חוק ההתיישנות, תשי"ח-1958, סעיף 9 אולם, הפסיקה, ובפרט פסק הדין בעניין ע"א 811/23 עמנואל בן חיים נ'' תשרי רהיטים בע"מ, קבעה כי הקלטת דברים שנאמרו בעל פה (או תמלול שלהם), ובכלל זה מסרון, אינה נחשבת ל"הודאה בכתב" לצורך סעיף 9 לחוק ההתיישנות. ע"א 811/23 עמנואל בן חיים נ'' תשרי רהיטים בע"מ (17.03.2025) זאת, משום שדרישת הכתב בסעיף 9 היא דרישה מהותית, שמטרתה לוודא שההודאה ניתנה ברצינות ובשיקול דעת, ולא בחופזה או בתום לב. ת"א (מחוזי מרכז) 33371-01-22 עמנואל בן חיים נ'' תשרי רהיטים בע"מ (01.12.2022) לפיכך, המסרון ששלח הרופא אינו מאפס את מרוץ ההתיישנות, והתביעה התיישנה בחלוף 7 שנים ממועד התאונה.', 'הטעות הנפוצה היא להניח שמסרון, בהיותו תקשורת כתובה, עונה על דרישת "הודאה בכתב" שבסעיף 9 לחוק ההתיישנות, מבלי להתחשב בתכלית המהותית של דרישה זו ובפרשנותה בפסיקה.',
    '["התיישנות", "הודאה בקיום זכות", "הודאה בכתב", "חוק ההתיישנות", "מרוץ התיישנות", "דרישה מהותית"]'::jsonb, '**וריאציה 1 — מסרון כ"כתב":** האם מסרון נחשב ל"הודאה בכתב" לפי סעיף 9 לחוק ההתיישנות? ← לא, הפסיקה קבעה כי הקלטת דברים בעל פה (או תמלול) אינה עונה על דרישה זו. ע"א 811/23 עמנואל בן חיים נ'' תשרי רהיטים בע"מ (17.03.2025)
**וריאציה 2 — תכלית דרישת הכתב:** מהי תכלית דרישת הכתב בסעיף 9? ← לוודא שההודאה ניתנה ברצינות ובשיקול דעת, ולא בחופזה. ת"א (מחוזי מרכז) 33371-01-22 עמנואל בן חיים נ'' תשרי רהיטים בע"מ (01.12.2022)
**וריאציה 3 — מועד ההתיישנות הכללי:** מהי תקופת ההתיישנות הכללית בתביעות שאינן במקרקעין? ← 7 שנים. חוק ההתיישנות, תשי"ח-1958, סעיף 5(1)', 'תביעה התיישנה לאחר 7 שנים. מסרון אינו "הודאה בכתב" לפי סעיף 9 לחוק ההתיישנות, ולכן אינו מאפס את מרוץ ההתיישנות.', '["חוק ההתיישנות, תשי\"ח-1958, סעיפים 5, 9", "ע\"א 811/23 עמנואל בן חיים נ'' תשרי רהיטים בע\"מ (17.03.2025)", "ת\"א (מחוזי מרכז) 33371-01-22 עמנואל בן חיים נ'' תשרי רהיטים בע\"מ (01.12.2022)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''limitation'' | classifier_note: Statute of limitations — discovery rule (סעיף 9 חוק ההתיישנות, surgeon''s apology by SMS 8 years later) | source_review_note: השאלה עוסקת בדיני התיישנות, ובפרט בהוראת סעיף 9 לחוק ההתיישנות. תחום זה אינו נכלל ישירות ברשימת תתי הנושאים הספציפיים תחת ''סדר דין אזרחי''. תת-הנושא ''הליכים'' נבחר כברירת מחדל, אך יש לשקול הוספת תת-נושא ייעודי ל''התיישנות''.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'התביעה התיישנה 7 שנים אחרי הניתוח.', true, 'תשובה זו נכונה. תקופת ההתיישנות הכללית בתביעות שאינן במקרקעין היא 7 שנים. המסרון אינו נחשב ל"הודאה בכתב" כנדרש בסעיף 9 לחוק ההתיישנות, ולכן אינו מאפס את מרוץ ההתיישנות. משחלפו 8 שנים, התביעה התיישנה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'התביעה תתיישן שנה אחרי ההודאה.', false, 'טענה זו שגויה. גם אם המסרון היה נחשב להודאה, תקופת ההתיישנות שתתחיל מחדש היא 7 שנים, ולא שנה.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'התביעה תתיישן 7 שנים אחרי ההודאה.', false, 'טענה זו שגויה. המסרון אינו עומד בדרישות הפסיקה ל"הודאה בכתב" לפי סעיף 9 לחוק ההתיישנות, ולכן אינו מאפס את מרוץ ההתיישנות. התביעה התיישנה כבר לפני קבלת המסרון.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'התביעה תתיישן 10 שנים אחרי ההודאה.', false, 'טענה זו שגויה. תקופת התיישנות של 10 שנים רלוונטית במקרים חריגים (כגון נזק שנתגלה באיחור לפי פקודת הנזיקין), וגם אז, המסרון אינו מאפס את מרוץ ההתיישנות.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הודאה בכתב פורמלית',
    1, 'ראובן הלווה לשמעון סכום כסף. שמעון לא פרע את ההלוואה. 6 שנים לאחר מועד הפירעון, שלח שמעון לראובן מכתב חתום ובו נכתב במפורש: "אני מודה בחוב שלי כלפיך בסך 100,000 ש"ח, ואני מתכוון לפרוע אותו בהקדם". ראובן הגיש תביעה כנגד שמעון 3 שנים לאחר קבלת המכתב. האם התביעה התיישנה?', 'שאלה זו בוחנת את תחולת סעיף 9 לחוק ההתיישנות במקרה של הודאה מפורשת וברורה בכתב. היא מדגישה את התנאים הנדרשים להודאה שתאפס את מרוץ ההתיישנות, בניגוד למסרון שאינו עומד בדרישות הצורניות המחמירות.', 'סעיף 9 לחוק ההתיישנות, תשי"ח-1958, קובע כי "הודה הנתבע, בכתב או בפני בית משפט, בין בתוך תקופת ההתיישנות ובין לאחריה, בקיום זכות התובע, תתחיל תקופת ההתיישנות מיום ההודאה". חוק ההתיישנות, תשי"ח-1958, סעיף 9 במקרה זה, המכתב החתום המודה במפורש בחוב עונה על הדרישה הצורנית של "בכתב" ועל הדרישה המהותית של הודאה מפורשת וברורה בקיום הזכות. ת"א (מחוזי חי'') 17409-01-24 המוסד לביטוח לאומי נ'' עו"ד אלי הדס (19.05.2025) לפיכך, מרוץ ההתיישנות מתחיל מחדש מיום קבלת המכתב, והתביעה שהוגשה 3 שנים לאחר מכן אינה התיישנה.',
    'הטעות היא לחשוב שכל הודאה, ללא קשר לצורתה או לתוכנה, מאפסת את מרוץ ההתיישנות, או לבלבל בין דרישת הכתב המהותית לדרישה ראייתית גרידא.', '["התיישנות", "הודאה בכתב", "סעיף 9 לחוק ההתיישנות", "מרוץ התיישנות", "דרישה צורנית", "דרישה מהותית"]'::jsonb, '**וריאציה 1 — מכתב חתום:** האם מכתב חתום המודה בחוב מאפס התיישנות? ← כן, עונה על דרישת "בכתב" בסעיף 9. חוק ההתיישנות, תשי"ח-1958, סעיף 9

**וריאציה 2 — תוכן ההודאה:** מה נדרש מתוכן ההודאה? ← שתהיה מפורשת, מלאה ומפורטת ותודה בקיום זכות התובע. ת"א (מחוזי חי'') 17409-01-24 המוסד לביטוח לאומי נ'' עו"ד אלי הדס (19.05.2025)
**וריאציה 3 — מועד ההודאה:** האם הודאה יכולה להינתן גם לאחר תקופת ההתיישנות המקורית? ← כן, סעיף 9 חל גם אם ההודאה ניתנה לאחר תקופת ההתיישנות. חוק ההתיישנות, תשי"ח-1958, סעיף 9', 'הודאה בכתב (מפורשת ומלאה) ← מאפסת מרוץ התיישנות (7 שנים מיום ההודאה).',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 9", "ת\"א (מחוזי חי'') 17409-01-24 המוסד לביטוח לאומי נ'' עו\"ד אלי הדס (19.05.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'התביעה לא התיישנה, ומרוץ ההתיישנות החל מחדש מיום קבלת המכתב.', true, 'תשובה זו נכונה. מכתב חתום המודה במפורש בחוב עונה על דרישת "הודאה בכתב" בסעיף 9 לחוק ההתיישנות, ולכן מרוץ ההתיישנות מתחיל מחדש מיום ההודאה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'התביעה התיישנה, שכן חלפו 7 שנים ממועד הפירעון המקורי.', false, 'טענה זו שגויה. המכתב מהווה הודאה בכתב המאפסת את מרוץ ההתיישנות, ולכן אין למנות 7 שנים ממועד הפירעון המקורי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'התביעה התיישנה, שכן הודאה בכתב אינה מאריכה את תקופת ההתיישנות אם ניתנה לאחר חלוף 6 שנים.', false, 'טענה זו שגויה. סעיף 9 לחוק ההתיישנות קובע כי הודאה מאפסת את מרוץ ההתיישנות גם אם ניתנה בתוך תקופת ההתיישנות וגם לאחריה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'התביעה לא התיישנה, אך ראובן זכאי רק לפיצוי בגין הפגיעה באוטונומיה ולא בגין החוב עצמו.', false, 'טענה זו שגויה. אין קשר לפגיעה באוטונומיה. הודאה בחוב מאפשרת תביעה על החוב עצמו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני ההודאה בסעיף 9',
    2, 'מהם התנאים המצטברים הנדרשים על פי הפסיקה כדי שהודאה של נתבע תאפס את מרוץ ההתיישנות לפי סעיף 9 לחוק ההתיישנות?', 'שאלה זו מתמקדת במבחנים שנקבעו בפסיקה ליישום סעיף 9 לחוק ההתיישנות. היא מפרטת את הדרישות הצורניות והמהותיות להודאה, ומדגישה את החשיבות של היעדר טיעון התיישנות נלווה.', 'הפסיקה קבעה כי על מנת שהודאה תאפס את מרוץ ההתיישנות לפי סעיף 9 לחוק ההתיישנות, עליה לעמוד בשני מבחנים עיקריים: מבחן מהותי ומבחן צורני. ת"א (מחוזי מרכז) 33371-01-22 עמנואל בן חיים נ'' תשרי רהיטים בע"מ (01.12.2022) מבחינה מהותית, ההודאה צריכה להיות מפורשת, מלאה ומפורטת, באופן שהנתבע יודה לא רק בקיום העובדות הנדרשות, אלא גם בקיום זכותו של התובע. ת"א (מחוזי חי'') 17409-01-24 המוסד לביטוח לאומי נ'' עו"ד אלי הדס (19.05.2025) מבחינה צורנית, ההודאה חייבת להינתן "בכתב או בפני בית משפט". חוק ההתיישנות, תשי"ח-1958, סעיף 9 בנוסף, סעיף 9 קובע במפורש כי "הודאה" לעניין זה היא "למעט הודאה שהיה עמה טיעון התיישנות". חוק ההתיישנות, תשי"ח-1958, סעיף 9',
    'הטעות הנפוצה היא להתעלם מאחד מהתנאים (צורני, מהותי, או היעדר טיעון התיישנות) או לפרש אותם באופן מרחיב מדי.', '["התיישנות", "הודאה בקיום זכות", "מבחן מהותי", "מבחן צורני", "טיעון התיישנות", "חוק ההתיישנות"]'::jsonb, '**וריאציה 1 — דרישה מהותית:** מהי הדרישה המהותית להודאה? ← מפורשת, מלאה ומפורטת, המודה בקיום זכות התובע. ת"א (מחוזי חי'') 17409-01-24 המוסד לביטוח לאומי נ'' עו"ד אלי הדס (19.05.2025)
**וריאציה 2 — דרישה צורנית:** מהי הדרישה הצורנית להודאה? ← בכתב או בפני בית משפט. חוק ההתיישנות, תשי"ח-1958, סעיף 9
**וריאציה 3 — טיעון התיישנות:** מה קורה אם להודאה נלווה טיעון התיישנות? ← ההודאה לא תאפס את מרוץ ההתיישנות. חוק ההתיישנות, תשי"ח-1958, סעיף 9', 'הודאה מאפסת התיישנות ← מפורשת, מלאה, בכתב/בפני ביהמ"ש, ללא טיעון התיישנות.',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 9", "ת\"א (מחוזי מרכז) 33371-01-22 עמנואל בן חיים נ'' תשרי רהיטים בע\"מ (01.12.2022)", "ת\"א (מחוזי חי'') 17409-01-24 המוסד לביטוח לאומי נ'' עו\"ד אלי הדס (19.05.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הודאה מפורשת, מלאה ומפורטת בקיום זכות התובע, שניתנה בכתב או בפני בית משפט, וללא טיעון התיישנות.', true, 'תשובה זו נכונה. אלו הם התנאים המצטברים שנקבעו בפסיקה לצורך תחולת סעיף 9 לחוק ההתיישנות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הודאה משתמעת בקיום עובדות התביעה, שניתנה בכל דרך, ובלבד שלא נלווה אליה טיעון התיישנות.', false, 'טענה זו שגויה. ההודאה צריכה להיות מפורשת וברורה, לא משתמעת, וכן לעמוד בדרישה צורנית של כתב או בפני בית משפט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הודאה בקיום זכות התובע, שניתנה בכתב או בעל פה, ובלבד שניתנה בתוך תקופת ההתיישנות המקורית.', false, 'טענה זו שגויה. ההודאה יכולה להינתן גם לאחר תקופת ההתיישנות, ודרישת הכתב אינה כוללת הודעה בעל פה מחוץ לבית המשפט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הודאה בקיום זכות התובע, שניתנה בפני בית משפט בלבד, ואין חשיבות אם נלווה אליה טיעון התיישנות.', false, 'טענה זו שגויה. ההודאה יכולה להינתן גם בכתב, וחשוב מאוד שלא ילווה אליה טיעון התיישנות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הודאה עם טיעון התיישנות',
    3, 'חברה חייבת כסף לספק. 8 שנים לאחר מועד הפירעון, שלחה החברה מכתב לספק ובו נכתב: "אנו מודים בחוב כלפיכם בסך 50,000 ש"ח, אך התביעה בגינו התיישנה זה מכבר". הספק הגיש תביעה כנגד החברה שנה לאחר קבלת המכתב. האם התביעה התיישנה?', 'שאלה זו בוחנת את החריג המפורש בסעיף 9 לחוק ההתיישנות, הקובע כי הודאה שלווה לה טיעון התיישנות אינה נחשבת להודאה המאפסת את מרוץ ההתיישנות. היא מדגישה את חשיבות ניסוח ההודאה ואת ההשלכות המשפטיות של הכללת טיעון התיישנות בה.', 'סעיף 9 לחוק ההתיישנות קובע כי "הודאה" לעניין אתחול מרוץ ההתיישנות היא "למעט הודאה שהיה עמה טיעון התיישנות". חוק ההתיישנות, תשי"ח-1958, סעיף 9 במקרה זה, אף שהחברה הודתה בחוב בכתב, היא צירפה להודאה טיעון מפורש שהתביעה התיישנה. לכן, הודאה זו אינה עומדת בתנאי סעיף 9, ואינה מאפסת את מרוץ ההתיישנות. ע"א 7905/18 מיכאל מצפון נ'' אביחיל מושב עובדים של חיילים משוחררים להתיישבות שיתופית בע"מ (29.06.2020) משחלפו 8 שנים ממועד הפירעון המקורי, וההודאה לא אפסה את המרוץ, התביעה התיישנה.',
    'הטעות הנפוצה היא להתעלם מהסיפא של סעיף 9, הקובעת כי טיעון התיישנות נלווה מבטל את תוקף ההודאה.', '["התיישנות", "הודאה בקיום זכות", "טיעון התיישנות", "סעיף 9 לחוק ההתיישנות", "מרוץ התיישנות", "חריגים להתיישנות"]'::jsonb, '**וריאציה 1 — הודאה עם סייג:** האם הודאה בחוב שלווה לה טענת התיישנות מאפסת את המרוץ? ← לא, סעיף 9 לחוק ההתיישנות קובע במפורש שלא. חוק ההתיישנות, תשי"ח-1958, סעיף 9
**וריאציה 2 — רציונל:** מה הרציונל מאחורי סייג זה? ← לאפשר לנתבע להודות בחובו מבלי לוותר על טענת ההתיישנות. ע"א 7905/18 מיכאל מצפון נ'' אביחיל מושב עובדים של חיילים משוחררים להתיישבות שיתופית בע"מ (29.06.2020)
**וריאציה 3 — הודאה משתמעת:** האם הודאה משתמעת בכתב הגנה, שלווה לה טענת התיישנות, תאפס את המרוץ? ← לא, גם הודאה משתמעת בכתב הגנה לא תאפס אם נלווה לה טיעון התיישנות. רע"א (מחוזי חי'') 16017-06-18 המוסד לביטוח לאומי נ'' פלוני (21.08.2018)', 'הודאה + טיעון התיישנות ← לא מאפסת מרוץ התיישנות (ס'' 9 סיפא).',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 9", "ע\"א 7905/18 מיכאל מצפון נ'' אביחיל מושב עובדים של חיילים משוחררים להתיישבות שיתופית בע\"מ (29.06.2020)", "רע\"א (מחוזי חי'') 16017-06-18 המוסד לביטוח לאומי נ'' פלוני (21.08.2018)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'התביעה התיישנה, שכן ההודאה לוותה בטיעון התיישנות ולכן אינה מאפסת את מרוץ ההתיישנות.', true, 'תשובה זו נכונה. סעיף 9 לחוק ההתיישנות קובע במפורש כי הודאה שלווה לה טיעון התיישנות אינה נחשבת להודאה המאפסת את מרוץ ההתיישנות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'התביעה לא התיישנה, שכן ההודאה בכתב מאפסת את מרוץ ההתיישנות ללא קשר לטיעון נלווה.', false, 'טענה זו שגויה. סעיף 9 לחוק ההתיישנות קובע חריג מפורש להודאה שלווה לה טיעון התיישנות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'התביעה לא התיישנה, אך תקופת ההתיישנות תקוצר לשנה אחת מיום ההודאה.', false, 'טענה זו שגויה. אין הוראה כזו בחוק ההתיישנות. אם ההודאה תקפה, תקופת ההתיישנות היא 7 שנים מיום ההודאה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'התביעה התיישנה, שכן חלפו למעלה מ-7 שנים ממועד הפירעון המקורי, וההודאה אינה רלוונטית.', false, 'טענה זו שגויה חלקית. התביעה אכן התיישנה, אך לא בגלל שההודאה אינה רלוונטית, אלא בגלל שהיא לוותה בטיעון התיישנות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'מעשה שיש בו ביצוע מקצת הזכות',
    4, 'חברה חייבת כסף לספק. 6 שנים לאחר מועד הפירעון, העבירה החברה לספק תשלום חלקי על חשבון החוב, בצירוף מכתב המציין כי התשלום הוא "על חשבון החוב הקיים". הספק הגיש תביעה כנגד החברה 3 שנים לאחר קבלת התשלום החלקי. האם התביעה התיישנה?', 'שאלה זו עוסקת בחלופה נוספת לאתחול מרוץ ההתיישנות לפי סעיף 9 לחוק ההתיישנות: "מעשה שיש בו משום ביצוע מקצת הזכות". היא בוחנת מתי פעולה כזו נחשבת להודאה ומאפסת את מרוץ ההתיישנות, ומה היקף הזכות שהיא מאפסת.', 'סעיף 9 לחוק ההתיישנות קובע כי "מעשה שיש בו משום ביצוע מקצת הזכות, דינו כהודאה לענין סעיף זה". חוק ההתיישנות, תשי"ח-1958, סעיף 9 תשלום חלקי על חשבון חוב, בצירוף מכתב המציין זאת, נחשב ל"מעשה שיש בו משום ביצוע מקצת הזכות". ת"א (מחוזי מרכז) 18207-01-10 יעקב גזית נ'' פז חברת נפט בע"מ (04.11.2015) מעשה כזה מאפס את מרוץ ההתיישנות, והתקופה החדשה של 7 שנים מתחילה להימנות מיום ביצוע המעשה. ק"ג (אזורי ת"א) 64858-06-20 מבטחים מוסד לבטוח סוציאלי של העובדים בע"מ - נברוט דן קריסטוף (16.05.2021) במקרה זה, התשלום החלקי ניתן 6 שנים לאחר מועד הפירעון, כלומר בתוך תקופת ההתיישנות המקורית, והוא איפס את המרוץ. התביעה הוגשה 3 שנים לאחר מכן, ולכן היא לא התיישנה.',
    'הטעות היא לחשוב שרק הודאה מפורשת בכתב או בפני בית משפט מאפסת את מרוץ ההתיישנות, ולהתעלם מחלופת "ביצוע מקצת הזכות".', '["התיישנות", "ביצוע מקצת הזכות", "הודאה בקיום זכות", "סעיף 9 לחוק ההתיישנות", "מרוץ התיישנות", "תשלום חלקי"]'::jsonb, '**וריאציה 1 — תשלום חלקי:** האם תשלום חלקי על חשבון חוב מאפס התיישנות? ← כן, אם הוא מהווה "ביצוע מקצת הזכות". חוק ההתיישנות, תשי"ח-1958, סעיף 9
**וריאציה 2 — כוונת התשלום:** מה נדרש כדי שתשלום חלקי ייחשב כהודאה? ← שהמעשה יעיד בבירור שהעושה מודה במפורש בקיום זכות התובע. ת"א (שלום חי'') 1913-01-12 עירית שפרעם נ'' נביל סלאמה (19.09.2017)
**וריאציה 3 — היקף האיפוס:** האם ביצוע מקצת הזכות מאפס את מרוץ ההתיישנות רק לגבי החלק ששולם? ← לא, הוא מאפס את מרוץ ההתיישנות לגבי מלוא הזכות. תא"מ (שלום י-ם) 19763-10-15 חברת הגיחון בע"מ נ'' אברהם כהן פקשר (12.09.2017)', 'תשלום חלקי (על חשבון חוב) ← נחשב ל"ביצוע מקצת הזכות" ← מאפס התיישנות (7 שנים מיום התשלום).',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 9", "ת\"א (מחוזי מרכז) 18207-01-10 יעקב גזית נ'' פז חברת נפט בע\"מ (04.11.2015)", "ת\"א (שלום חי'') 1913-01-12 עירית שפרעם נ'' נביל סלאמה (19.09.2017)", "תא\"מ (שלום י-ם) 19763-10-15 חברת הגיחון בע\"מ נ'' אברהם כהן פקשר (12.09.2017)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'התביעה לא התיישנה, שכן התשלום החלקי מהווה "מעשה שיש בו משום ביצוע מקצת הזכות" המאפס את מרוץ ההתיישנות.', true, 'תשובה זו נכונה. סעיף 9 לחוק ההתיישנות קובע כי מעשה שיש בו ביצוע מקצת הזכות דינו כהודאה, ולכן הוא מאפס את מרוץ ההתיישנות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'התביעה התיישנה, שכן תשלום חלקי אינו נחשב להודאה בכתב.', false, 'טענה זו שגויה. סעיף 9 לחוק ההתיישנות כולל במפורש "מעשה שיש בו משום ביצוע מקצת הזכות" כחלופה להודאה בכתב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'התביעה התיישנה, שכן תשלום חלקי מאפס את מרוץ ההתיישנות רק אם ניתן בתוך 3 שנים ממועד הפירעון המקורי.', false, 'טענה זו שגויה. סעיף 9 לחוק ההתיישנות אינו קובע הגבלה כזו. הוא חל גם אם המעשה נעשה בתוך תקופת ההתיישנות וגם לאחריה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'התביעה לא התיישנה, אך הספק זכאי לתבוע רק את הסכום החלקי ששולם.', false, 'טענה זו שגויה. מעשה שיש בו ביצוע מקצת הזכות מאפס את מרוץ ההתיישנות לגבי מלוא הזכות, ולא רק לגבי החלק ששולם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 2, '2023-S-S-Q02';
END
$$;

