  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q03', v_chapter_id, v_subtopic_id, 'החברה הציבורית "שלבים בע"מ" עומדת לכנס אסיפה כללית שעל סדר יומה תיקון שתי הוראות קיימות בתקנון החברה. נוסח ההוראות המוצעות הינו כדלקמן: "סעיף 31. בדירקטוריון החברה יהיו 7 דירקטורים. החברה תהא רשאית לשנות סעיף זה רק בהחלטה שתתקבל בידי בעלי מניות המחזיקים ברוב של לפחות 75% מזכויות ההצבעה באסיפה כללית של בעלי המניות"; "סעיף 32. בדירקטוריון החברה ישב לפחות דירקטור אחד בעל מומחיות וניסיון בתחום מדעי הטבע. החברה תהא רשאית לשנות סעיף זה בהחלטה שתתקבל ברוב רגיל באסיפה כללית של בעלי המניות". טרם השינוי נקבע בתקנון כי ניתן לשנות את סעיף 32 לתקנון ברוב של 80% מזכויות ההצבעה בחברה, וכי את יתר ההוראות ניתן לשנות ברוב שנקבע בדין. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 3}'::jsonb, 'השאלה עוסקת בשינוי תקנון חברה, ובפרט ביישום סעיפים 20 ו-22 לחוק החברות, התשנ"ט-1999. היא בוחנת את הרוב הנדרש לשינוי הוראות תקנון, כולל הוראות משוריינות, ואת הכללים לשינוי הוראות שריון קיימות או לקביעת הוראות שריון חדשות.', 'השאלה עוסקת בשינוי שתי הוראות בתקנון חברה ציבורית. יש לבחון כל סעיף בנפרד:
1. **לגבי סעיף 31 (המוצע):** ההוראה המוצעת קובעת כי "החברה תהא רשאית לשנות סעיף זה רק בהחלטה שתתקבל בידי בעלי מניות המחזיקים ברוב של לפחות 75% מזכויות ההצבעה באסיפה כללית של בעלי המניות". זוהי הוראת שריון חדשה. סעיף 22(א) לחוק החברות קובע כי חברה רשאית להגביל בתקנון את סמכותה לשנות הוראה, אם נתקבלה על כך החלטה באסיפה כללית "ברוב הדרוש לשינוי הוראות התקנון". חוק החברות, תשנ"ט-1999, סעיף 22(א) הרוב הדרוש לשינוי "יתר ההוראות" (שסעיף 31 נכלל בהן) הוא "רוב שנקבע בדין". עבור חברה שהתאגדה לאחר חוק החברות (כפי שמשתמע מהשאלה שאינה מציינת אחרת), הרוב שנקבע בדין הוא רוב רגיל (סעיף 20(א) לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 20(א) עם זאת, הרוב המוצע לשינוי סעיף 31 הוא 75%. לפי סעיף 20(ב) לחוק החברות, כאשר משנים הוראה בתקנון לפיה דרוש רוב מסוים לשינוי הוראות התקנון, הרוב הדרוש הוא הרוב המסוים או הרוב המוצע, לפי הגבוה מבין השניים. חוק החברות, תשנ"ט-1999, סעיף 20(ב) במקרה זה, הרוב המוצע לשינוי סעיף 31 הוא 75%, והרוב הנדרש לשינוי התקנון הוא רוב רגיל. לכן, הרוב הדרוש לשינוי סעיף 31 הוא 75% (הגבוה מבין השניים).
2. **לגבי סעיף 32 (המוצע):** ההוראה המוצעת קובעת כי "החברה תהא רשאית לשנות סעיף זה בהחלטה שתתקבל ברוב רגיל באסיפה הכללית". אולם, "טרם השינוי נקבע בתקנון כי ניתן לשנות את סעיף 32 לתקנון ברוב של 80% מזכויות ההצבעה בחברה". כלומר, סעיף 32 משוריין כיום ברוב של 80%. החברה מבקשת לשנות את הוראת השריון הזו לרוב רגיל. לפי סעיף 20(ב) לחוק החברות, כאשר משנים הוראה בתקנון לפיה דרוש רוב מסוים לשינוי הוראות התקנון, הרוב הדרוש הוא הרוב המסוים (80%) או הרוב המוצע (רוב רגיל), לפי הגבוה מבין השניים. חוק החברות, תשנ"ט-1999, סעיף 20(ב) לכן, הרוב הדרוש לשינוי סעיף 32 הוא 80%. נבו - המתמחה, דיני תאגידים (2026) | שינוי תקנון', 'הטעות הנפוצה היא לבלבל בין הרוב הנדרש כדי לקבוע הוראת שריון חדשה (לרוב רוב רגיל) לבין הרוב הנדרש כדי לשנות הוראת שריון קיימת (הרוב הגבוה מבין הקיים והמוצע).',
    '["שינוי תקנון", "הוראות שריון", "רוב רגיל", "רוב מיוחס", "סעיף 20 לחוק החברות", "סעיף 22 לחוק החברות", "אסיפה כללית"]'::jsonb, '**וריאציה 1 — קביעת שריון חדש:** מה הרוב הדרוש כדי לקבוע הוראת שריון חדשה (כמו סעיף 31 המוצע)? ← הרוב הדרוש לשינוי התקנון (רוב רגיל), אך הרוב המוצע לשינוי סעיף 31 הוא 75%, ולכן 75%. חוק החברות, תשנ"ט-1999, סעיף 20(ב)
**וריאציה 2 — שינוי שריון קיים:** מה הרוב הדרוש כדי לשנות הוראת שריון קיימת (כמו סעיף 32)? ← הרוב הקיים (80%) או הרוב המוצע (רוב רגיל), לפי הגבוה מבין השניים, כלומר 80%. חוק החברות, תשנ"ט-1999, סעיף 20(ב)
**וריאציה 3 — תכלית השריון:** מהי תכלית הוראות השריון בתקנון? ← לאזן בין צרכי החברה המשתנים לבין הגנה על המיעוט מפני ניצול כוח הרוב. ה"פ (מחוזי תל אביב-יפו) 986/07 עו"ד אליהוד יערי נ'' חב'' מעוז הכרך (27.05.2009)', 'שינוי תקנון: סעיף 31 (קביעת שריון חדש) דורש 75% (הרוב המוצע). סעיף 32 (שינוי שריון קיים מ-80% לרוב רגיל) דורש 80% (הרוב הגבוה מבין הקיים והמוצע).', '["חוק החברות, תשנ\"ט-1999, סעיפים 20, 22", "ה\"פ (מחוזי תל אביב-יפו) 986/07 עו\"ד אליהוד יערי נ'' חב'' מעוז הכרך (27.05.2009)", "נבו - המתמחה, דיני תאגידים (2026), שינוי תקנון, עמ'' 20", "יוסף גרוס, חוק החברות (2016), פרק ח: מסמכי ההתאגדות - התקנון, עמ'' 11"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''companies_formation'' | classifier_note: Public company articles amendment — entrenched provisions, weighted majority', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'החברה רשאית לשנות את סעיף 31 ואת סעיף 32 בהחלטה שתתקבל ברוב רגיל באסיפה הכללית.', false, 'טענה זו שגויה. סעיף 32 משוריין ברוב של 80%, ולכן שינויו דורש רוב גבוה יותר מרוב רגיל. גם סעיף 31 המוצע כולל שריון של 75% לשינויים עתידיים, וקביעתו דורשת את הרוב הדרוש לשינוי התקנון, אשר במקרה זה הוא רוב רגיל, אך הרוב המוצע לשינוי סעיף 31 הוא 75%.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'החברה רשאית לשנות את סעיף 31 ברוב המוצע, ואת סעיף 32 ברוב הדרוש כיום לשינוי התקנון.', true, 'תשובה זו נכונה. סעיף 31 המוצע כולל הוראת שריון של 75% לשינויים עתידיים, וקביעתו דורשת את הרוב הדרוש לשינוי התקנון (רוב רגיל), אך הרוב המוצע לשינוי סעיף 31 הוא 75%. סעיף 32 משוריין כיום ברוב של 80%, והחברה מבקשת לשנותו לרוב רגיל. לפי סעיף 20(ב) לחוק החברות, שינוי הוראת שריון דורש את הרוב הקיים (80%) או את הרוב המוצע (רוב רגיל), לפי הגבוה מבין השניים, כלומר 80%.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'החברה רשאית לשנות את סעיף 31 ואת סעיף 32 ברוב המוצע בכל אחד מהם.', false, 'טענה זו שגויה. הרוב המוצע לשינוי סעיף 32 הוא רוב רגיל, אך מכיוון שהסעיף משוריין ב-80%, שינויו דורש 80% לפי סעיף 20(ב) לחוק החברות.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'החברה רשאית לשנות את סעיף 31 ואת סעיף 32 ברוב הדרוש כיום על פי התקנון לשינוי.', false, 'טענה זו שגויה. הרוב הדרוש כיום לשינוי סעיף 31 (כחלק מ''יתר ההוראות'') הוא רוב רגיל, אך הרוב המוצע לשינוי סעיף 31 הוא 75%. הרוב הדרוש כיום לשינוי סעיף 32 הוא 80%, והוא אכן הרוב הנדרש לשינוי.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'שינוי תקנון בחברה שהתאגדה לפני חוק החברות',
    1, 'חברת "ותיקים בע"מ" התאגדה בשנת 1990. תקנונה אינו קובע רוב מיוחד לשינוי הוראותיו. האסיפה הכללית של החברה מעוניינת לשנות הוראה בתקנון. מהו הרוב הדרוש לשינוי זה?', 'שאלה זו בוחנת את הוראות המעבר הקבועות בחוק החברות לגבי חברות שהתאגדו לפני כניסתו לתוקף. היא מתמקדת ברוב הנדרש לשינוי תקנון בחברות אלו, בהיעדר הוראת שריון ספציפית בתקנון.', 'חוק החברות, תשנ"ט-1999, קובע בסעיף 20(א) כי חברה רשאית לשנות את תקנונה בהחלטה שהתקבלה ברוב רגיל באסיפה הכללית, אלא אם כן נקבע בתקנון כי דרוש רוב אחר. חוק החברות, תשנ"ט-1999, סעיף 20(א) עם זאת, סעיף 24 לחוק החברות קובע הוראות מעבר לחברות שהתאגדו לפני תחילתו של החוק. סעיף 24(3) קובע כי חברה כזו רשאית לשנות את ההוראות הקבועות בתקנונה בהחלטה שנתקבלה באסיפה הכללית ברוב של שבעים וחמישה אחוזים מן המשתתפים בהצבעה, למעט הנמנעים, או ברוב אחר אם נקבע בתזכיר החברה או בתקנונה. חוק החברות, תשנ"ט-1999, סעיף 24(3) במקרה הנדון, חברת "ותיקים בע"מ" התאגדה בשנת 1990, לפני חוק החברות, ותקנונה אינו קובע רוב מיוחד. לכן, הרוב הדרוש לשינוי תקנונה הוא 75% מן המשתתפים בהצבעה, למעט הנמנעים. ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (18.08.2022)',
    'הטעות הנפוצה היא ליישם את הכלל של רוב רגיל (סעיף 20(א)) גם על חברות שהתאגדו לפני חוק החברות, מבלי להתייחס להוראות המעבר שבסעיף 24(3).', '["שינוי תקנון", "חוק החברות", "הוראות מעבר", "רוב מיוחס", "אסיפה כללית", "חברה ותיקה"]'::jsonb, '**וריאציה 1 — חברה ותיקה ללא שריון:** מה הרוב לשינוי תקנון בחברה שהתאגדה לפני חוק החברות וללא שריון? ← 75% מהמשתתפים בהצבעה (למעט נמנעים). חוק החברות, תשנ"ט-1999, סעיף 24(3)
**וריאציה 2 — חברה חדשה ללא שריון:** מה הרוב לשינוי תקנון בחברה שהתאגדה לאחר חוק החברות וללא שריון? ← רוב רגיל. חוק החברות, תשנ"ט-1999, סעיף 20(א)
**וריאציה 3 — תכלית הוראות המעבר:** מדוע קיימות הוראות מעבר לשינוי תקנון? ← כדי להתאים את הדין לחברות שהוקמו תחת משטר משפטי קודם. נבו - המתמחה, דיני תאגידים (2026) | הוראות מעבר לגבי תזכיר', 'חברה ותיקה (לפני 1999) ללא שריון בתקנון ← שינוי תקנון ברוב של 75% מהמשתתפים (ס'' 24(3) לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 20(א), 24(3)", "ע\"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע\"מ (18.08.2022)", "נבו - המתמחה, דיני תאגידים (2026), הוראות מעבר לגבי תזכיר, עמ'' 22"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'רוב רגיל באסיפה הכללית.', false, 'טענה זו שגויה. רוב רגיל הוא הכלל לחברות שהתאגדו לאחר חוק החברות. לחברות ותיקות חלות הוראות מעבר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'רוב של 75% מן המשתתפים בהצבעה באסיפה הכללית, למעט הנמנעים.', true, 'תשובה זו נכונה. לפי סעיף 24(3) לחוק החברות, חברה שהתאגדה לפני חוק החברות ואין בתקנונה הוראה אחרת, רשאית לשנות את תקנונה ברוב של 75% מן המשתתפים בהצבעה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'רוב של 75% מכלל בעלי המניות בחברה.', false, 'טענה זו שגויה. הרוב הנדרש הוא מן המשתתפים בהצבעה, לא מכלל בעלי המניות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'הסכמה פה אחד של כל בעלי המניות בחברה.', false, 'טענה זו שגויה. הסכמה פה אחד נדרשת רק במקרים חריגים ביותר, כגון שינוי המגדיל את אחריות בעל המניות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'שינוי הוראה המגדילה אחריות בעל מניות',
    2, 'האסיפה הכללית של חברת "אחריות בע"מ" מעוניינת לשנות את התקנון באופן שיחייב את בעלי המניות לרכוש מניות נוספות בחברה. מהו הרוב הדרוש לשינוי זה?', 'שאלה זו עוסקת בחריג חשוב לכלל שלטון הרוב בשינוי תקנון חברה, הקבוע בסעיף 20(ד) לחוק החברות. היא מדגישה את ההגנה על בעלי מניות מפני שינויים המגדילים את אחריותם או מחייבים אותם לרכוש מניות נוספות.', 'סעיף 20(ד) לחוק החברות קובע חריג לכלל שלטון הרוב בשינוי תקנון: "על אף הוראות סעיף זה, שינוי בתקנון המחייב בעל מניה לרכוש מניות נוספות או להגדיל את היקף אחריותו, לא יחייב את בעל המניה ללא הסכמתו". חוק החברות, תשנ"ט-1999, סעיף 20(ד) כלומר, במקרים אלו, נדרשת הסכמה פרטנית של כל בעל מניה שמושפע מהשינוי, ולא די בהחלטת רוב באסיפה הכללית. נבו - המתמחה, דיני תאגידים (2026) | שינוי תקנון זאת, משום ששינוי כזה פוגע באופן מהותי בזכויות הקניין של בעל המניות ובבסיס ההסכמה עליו התאגד בחברה. ע"א 524/88 "פרי העמק" - אגודה חקלאית שיתופית בע"מ ו- 30אח'' נ'' שדה יעקב - מושב עובדים של הפועל המזרחי להתיישבות (15.08.1991)',
    'הטעות הנפוצה היא ליישם את כלל שלטון הרוב גם במקרים בהם החוק דורש הסכמה פרטנית של בעלי המניות, כגון הגדלת אחריותם.', '["שינוי תקנון", "הגדלת אחריות בעל מניות", "הסכמה פרטנית", "סעיף 20(ד) לחוק החברות", "בסיס ההסכמה", "זכויות קניין"]'::jsonb, '**וריאציה 1 — רכישת מניות נוספות:** האם ניתן לחייב בעל מניות לרכוש מניות נוספות ברוב רגיל? ← לא, נדרשת הסכמתו. חוק החברות, תשנ"ט-1999, סעיף 20(ד)
**וריאציה 2 — הגדלת אחריות:** האם ניתן להגדיל את היקף אחריותו של בעל מניות ברוב רגיל? ← לא, נדרשת הסכמתו. חוק החברות, תשנ"ט-1999, סעיף 20(ד)
**וריאציה 3 — בסיס ההסכמה:** מה הרציונל מאחורי דרישת ההסכמה הפרטנית? ← שינוי מהותי בבסיס ההסכמה של בעל המניות. ע"א 524/88 "פרי העמק" - אגודה חקלאית שיתופית בע"מ ו- 30אח'' נ'' שדה יעקב - מושב עובדים של הפועל המזרחי להתיישבות (15.08.1991)', 'שינוי תקנון המגדיל אחריות או מחייב רכישת מניות ← דורש הסכמת כל בעל מניות נפגע (ס'' 20(ד) לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 20(ד)", "נבו - המתמחה, דיני תאגידים (2026), שינוי תקנון, עמ'' 21", "ע\"א 524/88 \"פרי העמק\" - אגודה חקלאית שיתופית בע\"מ ו- 30אח'' נ'' שדה יעקב - מושב עובדים של הפועל המזרחי להתיישבות (15.08.1991)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'רוב רגיל באסיפה הכללית.', false, 'טענה זו שגויה. שינוי המגדיל את אחריות בעל מניות דורש הסכמה מיוחדת, ולא רוב רגיל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'רוב של 75% מן המשתתפים בהצבעה באסיפה הכללית.', false, 'טענה זו שגויה. רוב של 75% אינו מספיק במקרה של הגדלת אחריות בעל מניות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הסכמה של כל בעלי המניות הנפגעים מהשינוי.', true, 'תשובה זו נכונה. סעיף 20(ד) לחוק החברות קובע כי שינוי בתקנון המחייב בעל מניה לרכוש מניות נוספות או להגדיל את היקף אחריותו, לא יחייב את בעל המניה ללא הסכמתו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'אישור בית המשפט בלבד.', false, 'טענה זו שגויה. אישור בית המשפט אינו נדרש לשינוי כזה, אלא הסכמת בעלי המניות הנפגעים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שינוי הפוגע בזכויות סוג',
    3, 'חברת "סוגים בע"מ" מחולקת למניות רגילות ומניות בכורה. תקנון החברה קובע כי מינוי דירקטורים ייעשה על ידי בעלי מניות הבכורה. האסיפה הכללית מעוניינת לשנות את התקנון ולקבוע כי מינוי הדירקטורים ייעשה על ידי כל בעלי המניות בחברה. מהו הרוב הדרוש לשינוי זה?', 'שאלה זו עוסקת בהגנה על זכויות סוג של בעלי מניות בעת שינוי תקנון, כפי שקבוע בסעיף 20(ג) לחוק החברות. היא מדגישה את הדרישה לאישור כפול – הן של האסיפה הכללית והן של אסיפת הסוג הנפגע – כדי להבטיח שזכויות המיעוט לא ייפגעו על ידי הרוב.', 'סעיף 20(ג) לחוק החברות קובע כי "היו מניות החברה מחולקות לסוגים, לא ייעשה שינוי בתקנון שיפגע בזכויותיו של סוג מניות ללא אישור אסיפת אותו סוג, אלא אם כן נקבע אחרת בתקנון". חוק החברות, תשנ"ט-1999, סעיף 20(ג) במקרה הנדון, שינוי התקנון כך שמינוי הדירקטורים ייעשה על ידי כל בעלי המניות, פוגע בזכות הייחודית של בעלי מניות הבכורה למנות דירקטורים. לכן, נדרש אישור כפול: הן של האסיפה הכללית ברוב הדרוש לשינוי התקנון (רוב רגיל, אלא אם נקבע אחרת בתקנון), והן אישור אסיפת סוג של בעלי מניות הבכורה ברוב הדרוש לשינוי התקנון. נבו - המתמחה, דיני תאגידים (2026) | שינוי תקנון',
    'הטעות הנפוצה היא להתעלם מהדרישה לאישור אסיפת הסוג כאשר שינוי תקנון פוגע בזכויות סוג מסוים של מניות.', '["שינוי תקנון", "זכויות סוג", "אסיפת סוג", "סעיף 20(ג) לחוק החברות", "רוב רגיל", "רוב מיוחס"]'::jsonb, '**וריאציה 1 — פגיעה בזכויות סוג:** מה נדרש לשינוי תקנון הפוגע בזכויות סוג? ← אישור אסיפה כללית + אישור אסיפת הסוג. חוק החברות, תשנ"ט-1999, סעיף 20(ג)
**וריאציה 2 — רוב באסיפת סוג:** מהו הרוב הדרוש באסיפת הסוג? ← הרוב הדרוש לשינוי התקנון (לרוב רוב רגיל, אלא אם שוריין). נבו - המתמחה, דיני תאגידים (2026) | שינוי תקנון
**וריאציה 3 — תכלית ההגנה:** מהי תכלית ההגנה על זכויות סוג? ← למנוע קיפוח מיעוט ופגיעה בזכויות קניין. יוסף גרוס, חוק החברות (2016) | שינוי בזכויות סוג', 'שינוי תקנון הפוגע בזכויות סוג ← אישור אסיפה כללית + אישור אסיפת סוג (ס'' 20(ג) לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 20(ג)", "נבו - המתמחה, דיני תאגידים (2026), שינוי תקנון, עמ'' 21", "יוסף גרוס, חוק החברות (2016), פרק ח: מסמכי ההתאגדות - התקנון, עמ'' 13"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'אישור האסיפה הכללית ברוב רגיל בלבד.', false, 'טענה זו שגויה. כאשר מניות מחולקות לסוגים ושינוי פוגע בזכויות סוג, נדרש אישור אסיפת הסוג בנוסף לאישור האסיפה הכללית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'אישור האסיפה הכללית ברוב הדרוש לשינוי התקנון וכן אישור אסיפת סוג של בעלי מניות הבכורה ברוב הדרוש לשינוי התקנון.', true, 'תשובה זו נכונה. סעיף 20(ג) לחוק החברות קובע כי שינוי בתקנון הפוגע בזכויותיו של סוג מניות דורש אישור אסיפת אותו סוג, בנוסף לאישור האסיפה הכללית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'הסכמה פה אחד של כל בעלי מניות הבכורה.', false, 'טענה זו שגויה. סעיף 20(ג) דורש אישור אסיפת הסוג ברוב הדרוש לשינוי התקנון, ולא הסכמה פה אחד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'אישור בית המשפט בלבד.', false, 'טענה זו שגויה. אישור בית המשפט אינו נדרש ככלל לשינוי כזה, אלא אישור האסיפות הרלוונטיות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הגבלת סמכות לשינוי תקנון',
    4, 'חברת "שריון בע"מ" מעוניינת להגביל בתקנונה את סמכותה לשנות הוראה מסוימת, כך ששינוי עתידי של הוראה זו יחייב רוב של 90% מזכויות ההצבעה. מהו הרוב הדרוש באסיפה הכללית כדי לקבוע הגבלה זו?', 'שאלה זו עוסקת בסמכות החברה לשריין הוראות בתקנונה, כלומר להגביל את יכולתה לשנות אותן בעתיד, כפי שקבוע בסעיף 22 לחוק החברות. היא בוחנת את הרוב הנדרש כדי לקבוע שריון כזה מלכתחילה.', 'סעיף 22(א) לחוק החברות קובע כי "חברה רשאית להגביל בתקנון או בחוזה אחר את סמכותה לשנות את התקנון או הוראה מהוראותיו, אם נתקבלה על כך החלטה באסיפה כללית, ברוב הדרוש לשינוי הוראות התקנון". חוק החברות, תשנ"ט-1999, סעיף 22(א) ה"רוב הדרוש לשינוי הוראות התקנון" הוא הרוב הכללי הקבוע בסעיף 20(א) לחוק, שהוא רוב רגיל, אלא אם כן נקבע אחרת בתקנון. יוסף גרוס, חוק החברות (2016) | הרוב הדרוש לשינוי לכן, כדי לקבוע הגבלה (שריון) הדורשת 90% לשינוי עתידי, נדרש רוב רגיל באסיפה הכללית, בהנחה שאין הוראת שריון קיימת לגבי שינוי התקנון עצמו. אירית חביב-סגל, דיני חברות - כרך א (2007) | מבוא',
    'הטעות הנפוצה היא לבלבל בין הרוב הנדרש כדי לקבוע הוראת שריון (הרוב הכללי לשינוי תקנון) לבין הרוב שיידרש בעתיד כדי לשנות את ההוראה המשוריינת.', '["הגבלת סמכות", "שריון הוראות", "סעיף 22 לחוק החברות", "רוב רגיל", "רוב מיוחס", "אסיפה כללית"]'::jsonb, '**וריאציה 1 — קביעת שריון:** מה הרוב הדרוש כדי לקבוע הוראת שריון בתקנון? ← הרוב הדרוש לשינוי התקנון (לרוב רוב רגיל). חוק החברות, תשנ"ט-1999, סעיף 22(א)
**וריאציה 2 — שינוי הוראה משוריינת:** מה הרוב הדרוש כדי לשנות הוראה שכבר שוריינה? ← הרוב שנקבע בשריון או הרוב המוצע, לפי הגבוה מבין השניים. חוק החברות, תשנ"ט-1999, סעיף 20(ב)
**וריאציה 3 — אי-יכולת להתנות:** האם ניתן להתנות על עצם היכולת לשנות תקנון? ← לא, לא ניתן לחסום את דרכם של בעלי מניות לשנות את התקנון. ע"א 6041/15 האמה בע"מ נ'' אורנה מולר (25.09.2016)', 'קביעת שריון בתקנון ← רוב הדרוש לשינוי תקנון (לרוב רוב רגיל). שינוי הוראה משוריינת ← הרוב שנקבע בשריון או המוצע, הגבוה מביניהם.',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 20(ב), 22(א)", "יוסף גרוס, חוק החברות (2016), פרק ח: מסמכי ההתאגדות - התקנון, עמ'' 11", "אירית חביב-סגל, דיני חברות - כרך א (2007), מבוא, עמ'' 27", "ע\"א 6041/15 האמה בע\"מ נ'' אורנה מולר (25.09.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'רוב רגיל באסיפה הכללית.', true, 'תשובה זו נכונה. לפי סעיף 22(א) לחוק החברות, החלטה להגביל את סמכות החברה לשנות את התקנון דורשת את הרוב הדרוש לשינוי הוראות התקנון, שהוא רוב רגיל בהיעדר הוראה אחרת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'רוב של 90% מזכויות ההצבעה, כפי שהחברה מבקשת לשריין.', false, 'טענה זו שגויה. הרוב של 90% הוא הרוב שיידרש לשינוי ההוראה בעתיד, לא הרוב הנדרש כדי לקבוע את השריון מלכתחילה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'הסכמה פה אחד של כל בעלי המניות.', false, 'טענה זו שגויה. הסכמה פה אחד נדרשת רק במקרים חריגים ביותר, כגון הגדלת אחריות בעל מניות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'אישור בית המשפט בלבד.', false, 'טענה זו שגויה. אישור בית המשפט אינו נדרש ככלל לקביעת שריון בתקנון.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 3, '2023-S-S-Q03';
END
$$;

