-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'eb8cb9b2-9f9a-46e3-a070-3b5198c1e53b'::uuid;
  v_group_id uuid := '6deb36e9-d9c3-4a46-9641-8bf6dc7b509e'::uuid;
  v_chapter_id uuid;
