  v_existing_id uuid;
  v_ang_0 uuid := '4bca0a4a-b023-4cf5-8350-bd8c5f8330e7'::uuid;
  v_ang_1 uuid := '33346521-80d7-41ca-9751-60a67c371d34'::uuid;
  v_ang_2 uuid := '956968af-8474-4b38-a446-f237f0fdbab5'::uuid;
  v_ang_3 uuid := 'ae98fe8f-2100-4944-8ad3-3a37d5c71629'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q04';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 4, '2023-S-S-Q04';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'piercing_veil' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'piercing_veil', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q04', v_chapter_id, v_subtopic_id, 'באיזה מן המקרים הבאים רשאי בית המשפט להורות על הרמת מסך?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 4}'::jsonb, 'השאלה עוסקת בדוקטרינת הרמת מסך ההתאגדות, המהווה חריג לעקרון האישיות המשפטית הנפרדת של חברה. היא בוחנת את התנאים המצטברים הקבועים בסעיף 6(א) לחוק החברות, התשנ"ט-1999, המאפשרים לבית המשפט לייחס חוב של חברה לבעל מניה בה.', 'עקרון האישיות המשפטית הנפרדת של חברה, הקבוע בסעיף 4 לחוק החברות, הוא עמוד תווך בדיני החברות. חוק החברות, תשנ"ט-1999, סעיף 4 אולם, סעיף 6 לחוק קובע חריג לכלל זה, ומאפשר לבית המשפט להרים את מסך ההתאגדות במקרים חריגים. סע"ש (אזורי חי'') 75828-07-19 חוסאם מסארווה - ריווא פארם בע"מ (09.11.2021)
על פי סעיף 6(א)(1) לחוק החברות, בית המשפט רשאי לייחס חוב של חברה לבעל מניה בה אם מתקיימים מספר תנאים מצטברים:
1. **שיקול דעת שיפוטי**: בית המשפט מצא כי בנסיבות העניין "צודק ונכון לעשות כן". חוק החברות, תשנ"ט-1999, סעיף 6(א)(1) דרישה זו היא תנאי מצטבר המאפשר לבית המשפט להימנע מהרמת מסך גם אם התקיימו יתר התנאים. זוהר גושן אסף אקשטיין דיני חברות (2023) | פרק ח הרמת מסך
2. **מקרה חריג**: השימוש באישיות המשפטית הנפרדת נעשה באחד משני אופנים:
א. באופן שיש בו כדי להונות אדם או לקפח נושה של החברה. חוק החברות, תשנ"ט-1999, סעיף 6(א)(1)(א)
ב. באופן הפוגע בתכלית החברה ותוך נטילת סיכון בלתי סביר באשר ליכולתה לפרוע את חובותיה. חוק החברות, תשנ"ט-1999, סעיף 6(א)(1)(ב)
3. **מודעות בעל המניה**: בעל המניה היה מודע לשימוש כאמור, או למצער חשד בדבר טיב ההתנהגות או אפשרות קיום הנסיבות ונמנע מלבררן (עצימת עיניים), למעט אם נהג ברשלנות בלבד. חוק החברות, תשנ"ט-1999, סעיף 6(א)(1) וכן חוק החברות, תשנ"ט-1999, סעיף 6(א)(2)
התשובה הנכונה (ב) משקפת את כל התנאים המצטברים הללו: מציאת בית המשפט כי "נכון וצודק", קיומו של מקרה חריג (קיפוח נושה), ושימוש מודע באישיות המשפטית הנפרדת.', 'הטעות הנפוצה היא להתעלם מהדרישה המצטברת של "צודק ונכון לעשות כן" או לבלבל בין העילות השונות להרמת מסך, או לחשוב שדי ברשלנות של בעל המניות כדי להרים מסך.',
    '["הרמת מסך", "אישיות משפטית נפרדת", "חוק החברות", "קיפוח נושה", "מודעות בעל מניות", "שיקול דעת שיפוטי"]'::jsonb, '**וריאציה 1 — תנאי מצטבר:** האם הדרישה ש"צודק ונכון לעשות כן" היא תנאי מצטבר? ← כן, היא תנאי מצטבר ליתר העילות. חוק החברות, תשנ"ט-1999, סעיף 6(א)(1)
**וריאציה 2 — מודעות:** מהי רמת המודעות הנדרשת מבעל המניות? ← מודעות בפועל או עצימת עיניים (חשד והימנעות מבירור), למעט רשלנות בלבד. חוק החברות, תשנ"ט-1999, סעיף 6(א)(2)
**וריאציה 3 — עילות חריגות:** מהן העילות החריגות לשימוש באישיות המשפטית הנפרדת? ← הונאה/קיפוח נושה, או פגיעה בתכלית החברה תוך נטילת סיכון בלתי סביר. חוק החברות, תשנ"ט-1999, סעיף 6(א)(1)(א)-(ב)', 'הרמת מסך דורשת: 1. "צודק ונכון לעשות כן". 2. מקרה חריג (הונאה/קיפוח נושה או פגיעה בתכלית וסיכון בלתי סביר). 3. מודעות בעל המניות (לא רשלנות בלבד).', '["חוק החברות, תשנ\"ט-1999, סעיפים 4, 6", "סע\"ש (אזורי חי'') 75828-07-19 חוסאם מסארווה - ריווא פארם בע\"מ (09.11.2021)", "זוהר גושן אסף אקשטיין, דיני חברות (2023), פרק ח הרמת מסך, עמ'' 5"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''piercing_veil'' | classifier_note: Exact match — when may court pierce the veil | source_review_note: השאלה עוסקת בדיני חברות, ובפרט בדוקטרינת הרמת מסך. תחום זה אינו נכלל ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''הליכים'' נבחר כברירת מחדל תחת ''סדר דין אזרחי'' בשל הקשר העקיף להליכים משפטיים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני תאגידים'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'במקרה שבו ייקבע כי גם אם הדבר אינו צודק, הרי שנכון להורות על הרמת מסך היות שנעשה שימוש מודע וחריג באישיות המשפטית של החברה כדי להונות נושה של החברה.', false, 'טענה זו שגויה. סעיף 6(א)(1) לחוק החברות דורש שבית המשפט ימצא כי "צודק ונכון לעשות כן" כתנאי מצטבר, ולא רק "נכון" או "צודק" בנפרד.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'במקרה שבו ייקבע כי נכון וצודק להורות על הרמת מסך וכי מדובר במקרה חריג שבו נעשה שימוש מודע באישיות המשפטית של החברה כדי לקפח נושה של החברה.', true, 'תשובה זו נכונה. היא משקפת את התנאים המצטברים הקבועים בסעיף 6(א)(1)(א) לחוק החברות: מציאת בית המשפט כי "צודק ונכון לעשות כן", קיומו של מקרה חריג של שימוש באישיות המשפטית הנפרדת באופן שיש בו כדי לקפח נושה, ומודעות בעל המניה לשימוש זה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'במקרה שבו ייקבע כי גם אם לא נכון להורות על הרמת מסך, הרי שצודק לעשות כן היות שנעשה שימוש חריג ומודע באישיות המשפטית של החברה כדי לקפח אדם.', false, 'טענה זו שגויה. סעיף 6(א)(1) לחוק החברות דורש שבית המשפט ימצא כי "צודק ונכון לעשות כן" כתנאי מצטבר. בנוסף, העילה היא קיפוח נושה של החברה, ולא קיפוח "אדם" באופן כללי.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'במקרה שבו ייקבע כי די בכך שהשימוש באישיות הנפרדת של החברה נעשה במודע ובאופן חריג וכן במטרה להונות נושה של החברה, ואין זה משנה אם הדבר צודק או נכון.', false, 'טענה זו שגויה. סעיף 6(א)(1) לחוק החברות קובע במפורש את הדרישה המצטברת שבית המשפט ימצא כי "צודק ונכון לעשות כן", ואין די בקיום העילות האחרות בלבד.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'מימון דק והרמת מסך',
    1, 'חברת "השקעות בסיכון בע"מ" הוקמה עם הון עצמי נמוך מאוד, ופעלה בעיקר באמצעות הלוואות בעלים מבעל המניות היחיד שלה. החברה נקלעה לקשיים כלכליים ולא הצליחה לפרוע את חובותיה לנושים חיצוניים. בעל המניות דורש כעת את פירעון הלוואות הבעלים. האם ניתן להרים את מסך ההתאגדות במקרה זה?', 'שאלה זו בוחנת את הקשר בין מימון דק (Thin Capitalization) והלוואות בעלים לבין הרמת מסך ההתאגדות. היא מדגישה כי אף שמימון דק אינו עילה עצמאית מפורשת בחוק החברות, הוא יכול להוות אינדיקציה לשימוש לרעה באישיות המשפטית הנפרדת של החברה, ולהצדיק הרמת מסך או השעיית חובות בעל המניות.', 'הפסיקה הכירה במימון דק (Thin Capitalization) כעילה אפשרית להרמת מסך עוד לפני תיקון מס'' 3 לחוק החברות. ע"א 2223/99 ויטלי קריספי נ'' ח. אלקטרוניקה (1988) בע"מ (09.07.2003) אף שהתיקון צמצם את העילות המפורשות, מימון דק בהיקף משמעותי ומתן הלוואות בעלים בחברת מעטים עשויים, במשולב ובנסיבות מתאימות, להקים הנחה לכאורה בדבר שימוש לא ראוי באישיות המשפטית הנפרדת של החברה ובעקרון הגבלת האחריות, במיוחד כאשר החברה נכנסת לקשיי פירעון. ע"א 4263/04 קיבוץ משמר העמק נ'' עו"ד טומי מנור, מפרק אפרוחי הצפון בע"מ (21.01.2009) במקרים כאלה, הנטל הראייתי עשוי לעבור לבעלי המניות לשכנע מדוע אין לראות בכך ניהול בלתי ראוי ומדוע מוצדק שלא להרים את המסך או להשעות את זכותם לפירעון הלוואות הבעלים. ע"א 4263/04 קיבוץ משמר העמק נ'' עו"ד טומי מנור, מפרק אפרוחי הצפון בע"מ (21.01.2009)',
    'הטעות הנפוצה היא לחשוב שמימון דק אינו רלוונטי כלל לאחר תיקון חוק החברות, או להתעלם מהאפשרות של השעיית חובות בעלים כסעד חלופי להרמת מסך מלאה.', '["הרמת מסך", "מימון דק", "הלוואות בעלים", "השעיית חובות", "נטל הוכחה", "אישיות משפטית נפרדת"]'::jsonb, '**וריאציה 1 — מימון דק כעילה:** האם מימון דק יכול להצדיק הרמת מסך? ← כן, כאינדיקציה לשימוש לא ראוי באישיות המשפטית הנפרדת. ע"א 4263/04 קיבוץ משמר העמק נ'' עו"ד טומי מנור, מפרק אפרוחי הצפון בע"מ (21.01.2009)
**וריאציה 2 — נטל הוכחה:** מי נושא בנטל ההוכחה במקרה של מימון דק? ← בעלי המניות, להוכיח שלא נעשה שימוש בלתי ראוי. ע"א 4263/04 קיבוץ משמר העמק נ'' עו"ד טומי מנור, מפרק אפרוחי הצפון בע"מ (21.01.2009)
**וריאציה 3 — סעד חלופי:** מהו סעד חלופי להרמת מסך במקרים אלו? ← השעיית זכותו של בעל המניות לפירעון חובו (סעיף 6(ג) לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 6(ג)', 'מימון דק והלוואות בעלים ← עשוי להצדיק הרמת מסך או השעיית חובות בעלים (נטל הוכחה על בעל המניות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 6(ג)", "ע\"א 2223/99 ויטלי קריספי נ'' ח. אלקטרוניקה (1988) בע\"מ (09.07.2003)", "ע\"א 4263/04 קיבוץ משמר העמק נ'' עו\"ד טומי מנור, מפרק אפרוחי הצפון בע\"מ (21.01.2009)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מימון דק והלוואות בעלים עשויים להקים הנחה לכאורה לשימוש לא ראוי באישיות המשפטית הנפרדת, ולהצדיק הרמת מסך או השעיית חובות בעל המניות.', true, 'תשובה זו נכונה. הפסיקה קבעה כי מימון דק והלוואות בעלים עשויים, בנסיבות מתאימות, להעביר את הנטל הראייתי לבעלי המניות להוכיח שלא נעשה שימוש בלתי ראוי באישיות התאגידית, ולבסוף להצדיק הרמת מסך או השעיית חובות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מימון דק אינו עילה עצמאית להרמת מסך לפי חוק החברות המתוקן.', false, 'טענה זו שגויה. אף שמימון דק אינו עילה עצמאית מפורשת, הוא יכול להוות אינדיקציה לנטילת סיכון בלתי סביר או קיפוח נושים, ובכך להצדיק הרמת מסך.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם יוכח שבעל המניות פעל בזדון כדי להונות את הנושים.', false, 'טענה זו שגויה. אין צורך להוכיח זדון; די בנטילת סיכון בלתי סביר או קיפוח נושים, בתוספת מודעות או עצימת עיניים, כדי להצדיק הרמת מסך.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, שכן בעל המניות זכאי להיפרע את חובו ככל נושה אחר של החברה.', false, 'טענה זו שגויה. במקרים של מימון דק והלוואות בעלים, ניתן להשעות את זכותו של בעל המניות לפירעון חובו עד לאחר פירעון חובות הנושים האחרים, או אף להרים מסך.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי הסף והשיקולים להרמת מסך',
    2, 'מהם תנאי הסף והשיקולים המצטברים שבית המשפט בוחן בטרם יחליט על הרמת מסך ההתאגדות לפי סעיף 6(א) לחוק החברות?', 'שאלה זו מפרטת את המבחן התלת-שלבי להרמת מסך ההתאגדות לפי סעיף 6(א) לחוק החברות, כפי שגובש בפסיקה. היא מדגישה את התנאים המצטברים: תנאי סף (מקרה חריג ומודעות), שיקולים נוספים, ולבסוף שיקול הדעת השיפוטי אם "צודק ונכון לעשות כן".', 'הסמכות להרים את מסך ההתאגדות היא סמכות בשיקול דעת, קרי "אם נכון וצודק לעשות כן". סע"ש (אזורי ת"א) 37497-04-22 עבד אלבאסט צאלח - שירן מהדרין בע"מ (29.05.2025) שיקול הדעת מותנה בשני תנאי סף: הראשון, התקיימות המקרים החריגים המנויים בסעיף 6(א) לחוק החברות (ניצול לרעה של עקרון האישיות המשפטית הנפרדת באופן שיש בו כדי להונות אדם או לקפח נושה, או פגיעה בתכלית החברה תוך נטילת סיכון בלתי סביר). סע"ש (אזורי חי'') 75828-07-19 חוסאם מסארווה - ריווא פארם בע"מ (09.11.2021) השני, מודעות או למצער חשד של בעל המניות בדבר שימוש פסול כאמור באישיות הנפרדת של החברה. סע"ש (אזורי חי'') 75828-07-19 חוסאם מסארווה - ריווא פארם בע"מ (09.11.2021) מעבר לתנאי סף אלו, המחוקק קבע שלושה שיקולים שיש לתת עליהם את הדעת: היקף האחזקות של בעל המניות, המידה בה מילא בעל המניות חובותיו כלפי החברה לפי סעיפים 192 ו-193 לחוק, ויכולת החברה לפרוע את חובותיה. סע"ש (אזורי חי'') 75828-07-19 חוסאם מסארווה - ריווא פארם בע"מ (09.11.2021)',
    'הטעות הנפוצה היא להתעלם מהדרישה המצטברת של "צודק ונכון לעשות כן" או לבלבל בין תנאי הסף לבין השיקולים הנוספים.', '["הרמת מסך", "תנאי סף", "שיקול דעת שיפוטי", "מודעות בעל מניות", "קיפוח נושה", "סיכון בלתי סביר"]'::jsonb, '**וריאציה 1 — תנאי סף:** מהם שני תנאי הסף להרמת מסך? ← מקרה חריג (הונאה/קיפוח או פגיעה בתכלית החברה וסיכון בלתי סביר) ומודעות בעל המניות. סע"ש (אזורי חי'') 75828-07-19 חוסאם מסארווה - ריווא פארם בע"מ (09.11.2021)
**וריאציה 2 — שיקולים נוספים:** אילו שיקולים נוספים נבחנים? ← היקף אחזקות, מילוי חובות לפי סעיפים 192 ו-193, ויכולת החברה לפרוע חובותיה. סע"ש (אזורי חי'') 75828-07-19 חוסאם מסארווה - ריווא פארם בע"מ (09.11.2021)
**וריאציה 3 — שיקול דעת:** האם בית המשפט חייב להרים מסך אם התנאים מתקיימים? ← לא, עדיין מסור לבית הדין שיקול דעת להחליט אם "צודק ונכון לעשות כן". סע"ש (אזורי חי'') 75828-07-19 חוסאם מסארווה - ריווא פארם בע"מ (09.11.2021)', 'הרמת מסך דורשת: 1. "צודק ונכון". 2. מקרה חריג (הונאה/קיפוח או פגיעה בתכלית וסיכון בלתי סביר). 3. מודעות בעל המניות. 4. שיקולים נוספים (אחזקות, חובות, יכולת פירעון).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 6(א)", "סע\"ש (אזורי חי'') 75828-07-19 חוסאם מסארווה - ריווא פארם בע\"מ (09.11.2021)", "סע\"ש (אזורי ת\"א) 37497-04-22 עבד אלבאסט צאלח - שירן מהדרין בע\"מ (29.05.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'שני תנאי סף (מקרה חריג ומודעות בעל המניות) ושלושה שיקולים (היקף אחזקות, מילוי חובות, יכולת פירעון החברה), בתוספת שיקול דעת בית המשפט אם "צודק ונכון לעשות כן".', true, 'תשובה זו נכונה. היא מפרטת את כלל המרכיבים הנדרשים להרמת מסך לפי סעיף 6(א) לחוק החברות, כפי שפורש בפסיקה: תנאי סף, שיקולים ושיקול דעת שיפוטי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'קיומו של מקרה חריג בלבד, כגון הונאת נושה, ללא צורך במודעות בעל המניות או בשיקולים נוספים.', false, 'טענה זו שגויה. נדרשת מודעות בעל המניות (או עצימת עיניים) וכן שיקול דעת בית המשפט אם "צודק ונכון לעשות כן", בנוסף למקרה החריג.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מודעות בעל המניות לשימוש פסול באישיות הנפרדת של החברה, ובלבד שהדבר צודק ונכון, ללא צורך במקרה חריג מוגדר.', false, 'טענה זו שגויה. נדרש קיומו של אחד המקרים החריגים המנויים בסעיף 6(א) (הונאה/קיפוח או פגיעה בתכלית החברה וסיכון בלתי סביר), בנוסף למודעות ולשיקול הדעת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'די בכך שבית המשפט ימצא כי "צודק ונכון לעשות כן", ואין צורך בתנאי סף או שיקולים נוספים.', false, 'טענה זו שגויה. הדרישה ש"צודק ונכון לעשות כן" היא תנאי מצטבר, אך לא מספיק לבדו. יש לעמוד גם בתנאי הסף של המקרים החריגים ומודעות בעל המניות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הרמת מסך בדיני עבודה',
    3, 'חברת "עובדים מרוצים בע"מ" לא שילמה שכר לעובדיה במשך מספר חודשים, ורוקנה את קופתה מנכסים. בעל המניות היחיד של החברה טוען כי אין לחייבו אישית בחובות השכר, שכן החברה היא אישיות משפטית נפרדת. האם בתי הדין לעבודה יטו להרים את מסך ההתאגדות במקרה זה?', 'שאלה זו בוחנת את הגישה המיוחדת של בתי הדין לעבודה לדוקטרינת הרמת מסך ההתאגדות. היא מדגישה את ההתאמה של הכללים למאפיינים הייחודיים של יחסי עבודה, תוך התחשבות בחוסר האיזון המובנה ובמעמדם המיוחד של העובדים כנושים לא רצוניים, אך עדיין דורשת הוכחת שימוש לרעה במסך ההתאגדות.', 'בתי הדין לעבודה, אף שהם כפופים לתנאים שבסעיף 6 לחוק החברות, פיתחו דינים ספציפיים המותאמים למאפיינים הייחודיים של משפט העבודה. סע"ש (אזורי ב"ש) 39951-01-18 רגבי עזיז נ'' מובילי שמרוך בע"מ (07.03.2022) הרחבת השימוש בדוקטרינה נועדה לפצות על חוסר האיזון הבסיסי ביחסים בין העובד למעסיק ועל מנת להתחשב במעמדו המיוחד של העובד כנושה של החברה, אשר נושאת כלפיו באחריות מוגברת ובחובת אמון מיוחדת. סע"ש (אזורי ב"ש) 39951-01-18 רגבי עזיז נ'' מובילי שמרוך בע"מ (07.03.2022) נסיבות כמו ריקון חברה מנכסים מבלי ששולם שכר העובדים, או היעדר תום לב של בעלי המניות והרצון להונות את העובדים, מצדיקות את הרמת מסך ההתאגדות. סע"ש (אזורי ב"ש) 39951-01-18 רגבי עזיז נ'' מובילי שמרוך בע"מ (07.03.2022) עם זאת, גם בבתי הדין לעבודה, הרמת מסך נחשבת לסעד קיצוני ומרחיק לכת, ואין די ב"תמונה מדאיגה" בלבד כדי להצדיק אותה, אלא יש להוכיח שימוש לרעה במסך ההתאגדות. סע"ש (אזורי חי'') 75828-07-19 חוסאם מסארווה - ריווא פארם בע"מ (09.11.2021)',
    'הטעות הנפוצה היא לחשוב שכל פגיעה בזכויות עובדים מובילה אוטומטית להרמת מסך, מבלי להוכיח שימוש לרעה באישיות המשפטית הנפרדת של החברה.', '["הרמת מסך", "דיני עבודה", "נושה לא רצוני", "חוסר איזון", "ריקון נכסים", "חובת אמון מוגברת"]'::jsonb, '**וריאציה 1 — עובדים כנושים:** האם עובדים נחשבים לנושים רגילים? ← לא, הם ''נושים לא רצוניים'' עם הגנה מוגברת. סע"ש (אזורי ת"א) 34094-01-19 אלון מוקתדר - פלנט שוקולד בע"מ (27.07.2023)
**וריאציה 2 — נסיבות מצדיקות:** אילו נסיבות מצדיקות הרמת מסך בדיני עבודה? ← היעדר תום לב, ריקון נכסים, הונאת עובדים, שימוש לרעה באישיות המשפטית. סע"ש (אזורי ב"ש) 39951-01-18 רגבי עזיז נ'' מובילי שמרוך בע"מ (07.03.2022)
**וריאציה 3 — ''תמונה מדאיגה'':** האם ''תמונה מדאיגה'' מספיקה להרמת מסך? ← לא, נדרשת תשתית ראייתית לשימוש לרעה במסך ההתאגדות. סע"ש (אזורי חי'') 75828-07-19 חוסאם מסארווה - ריווא פארם בע"מ (09.11.2021)', 'בתי הדין לעבודה מרחיבים הרמת מסך במקרים של פגיעה בעובדים (נושים לא רצוניים), אך עדיין דורשים הוכחת שימוש לרעה במסך ההתאגדות (חוסר תום לב, ריקון נכסים).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 6", "סע\"ש (אזורי ב\"ש) 39951-01-18 רגבי עזיז נ'' מובילי שמרוך בע\"מ (07.03.2022)", "סע\"ש (אזורי חי'') 75828-07-19 חוסאם מסארווה - ריווא פארם בע\"מ (09.11.2021)", "סע\"ש (אזורי ת\"א) 34094-01-19 אלון מוקתדר - פלנט שוקולד בע\"מ (27.07.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, בתי הדין לעבודה מרחיבים את השימוש בהרמת מסך במקרים של פגיעה בזכויות עובדים, במיוחד כאשר יש חוסר תום לב, ריקון נכסים או הונאה.', true, 'תשובה זו נכונה. בתי הדין לעבודה מתאימים את כללי הרמת המסך למאפיינים הייחודיים של יחסי עבודה, ונוטים להרחיב את השימוש בה במקרים של פגיעה בזכויות עובדים, במיוחד בשילוב עם חוסר תום לב או ריקון נכסים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, גם בתי הדין לעבודה רואים בהרמת מסך סעד קיצוני ומרחיק לכת, ואינם מרימים מסך רק בשל אי-תשלום שכר.', false, 'טענה זו שגויה. אף שבתי הדין לעבודה רואים בהרמת מסך סעד קיצוני, הם נוטים להרחיב את השימוש בו במקרים של פגיעה בזכויות עובדים, במיוחד כאשר ישנם סימני חוסר תום לב או ריקון נכסים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם יוכח שבעל המניות פעל בזדון כדי להונות את העובדים.', false, 'טענה זו שגויה. אין צורך להוכיח זדון; די בהיעדר תום לב, ריקון נכסים או שימוש לרעה באישיות המשפטית של החברה כדי לקפח עובדים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, שכן עובדים נחשבים לנושים וולונטריים, ואינם זכאים להגנה מיוחדת.', false, 'טענה זו שגויה. הפסיקה קבעה שעובדים אינם ''נושים וולונטריים'' אלא נושים מסוג מיוחד, כלפיהם מוטלת על החברה אחריות מוגברת וחובת אמון מיוחדת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סוגי הרמת מסך לפי חוק החברות',
    4, 'אילו סוגים של הרמת מסך ההתאגדות קבועים במפורש בסעיף 6 לחוק החברות, התשנ"ט-1999?', 'שאלה זו מתמקדת בסיווג ובתיאור שלוש צורות הרמת המסך המעוגנות בסעיף 6 לחוק החברות: הרמת מסך מלאה (סעיף 6(א)), הרמת מסך מדומה (סעיף 6(ב)), והרמת מסך חלקית (סעיף 6(ג)). היא מדגישה את ההבחנה בין סוגי הרמת המסך השונים ואת מטרת כל אחד מהם.', 'סעיף 6 לחוק החברות, בנוסחו דהיום, כולל שלוש צורות של הרמת מסך. רע"א 66369-02-25 תאי השקעות וסחר בע"מ נ'' גדעון פישמן ו-29 אח'' (02.07.2025)
1. **הרמת מסך מלאה (סעיף 6(א))**: עוסקת בייחוס חוב של החברה לבעל מניה בה. זוהי הצורה הקיצונית ביותר, המבטלת את ההפרדה בין החברה לבעל המניה ומתעלמת מהאחריות המוגבלת. רע"א 66369-02-25 תאי השקעות וסחר בע"מ נ'' גדעון פישמן ו-29 אח'' (02.07.2025)
2. **הרמת מסך מדומה (סעיף 6(ב))**: מאפשרת לבית המשפט לייחס תכונה, זכות או חובה של בעל מניה לחברה, או זכות של החברה לבעל מניה. צורה זו אינה מתעלמת מהאישיות המשפטית הנפרדת או מהגבלת האחריות, אלא מייחסת תכונות. זוהר גושן אסף אקשטיין דיני חברות (2023) | פרק ח הרמת מסך
3. **הרמת מסך חלקית (סעיף 6(ג))**: מאפשרת לבית המשפט להשעות את זכותו של בעל מניה לפירעון חובו מהחברה עד לאחר שהחברה פרעה במלואן את כל התחייבויותיה כלפי נושים אחרים. חוק החברות, תשנ"ט-1999, סעיף 6(ג)',
    'הטעות הנפוצה היא לבלבל בין סוגי הרמת המסך השונים, או לחשוב שקיימת רק הרמת מסך מלאה.', '["הרמת מסך מלאה", "הרמת מסך מדומה", "הרמת מסך חלקית", "סעיף 6 לחוק החברות", "אישיות משפטית נפרדת", "אחריות מוגבלת"]'::jsonb, '**וריאציה 1 — הרמת מסך מלאה:** מהי הרמת מסך מלאה? ← ייחוס חוב של חברה לבעל מניה (סעיף 6(א)). חוק החברות, תשנ"ט-1999, סעיף 6(א)(1)
**וריאציה 2 — הרמת מסך מדומה:** מהי הרמת מסך מדומה? ← ייחוס תכונה, זכות או חובה של בעל מניה לחברה או להיפך (סעיף 6(ב)). חוק החברות, תשנ"ט-1999, סעיף 6(ב)
**וריאציה 3 — הרמת מסך חלקית:** מהי הרמת מסך חלקית? ← השעיית זכותו של בעל מניה לפירעון חובו מהחברה (סעיף 6(ג)). חוק החברות, תשנ"ט-1999, סעיף 6(ג)', 'סעיף 6 לחוק החברות קובע 3 סוגי הרמת מסך: מלאה (6(א)), מדומה (6(ב)), וחלקית (6(ג)).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 6", "רע\"א 66369-02-25 תאי השקעות וסחר בע\"מ נ'' גדעון פישמן ו-29 אח'' (02.07.2025)", "זוהר גושן אסף אקשטיין, דיני חברות (2023), פרק ח הרמת מסך, עמ'' 5, 21"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'הרמת מסך מלאה (ייחוס חוב של חברה לבעל מניה), הרמת מסך מדומה (ייחוס תכונה/זכות/חובה של בעל מניה לחברה או להיפך), והרמת מסך חלקית (השעיית זכות פירעון של בעל מניה).', true, 'תשובה זו נכונה. סעיף 6 לחוק החברות כולל במפורש את שלושת צורות הרמת המסך הללו: סעיף 6(א) להרמת מסך מלאה, סעיף 6(ב) להרמת מסך מדומה, וסעיף 6(ג) להרמת מסך חלקית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'הרמת מסך מלאה והרמת מסך הפוכה בלבד.', false, 'טענה זו שגויה. סעיף 6 כולל גם הרמת מסך מדומה וחלקית. הרמת מסך הפוכה אינה מפורשת בסעיף 6, אלא נדונה לעיתים במסגרת 6(ב).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'הרמת מסך חלקית והרמת מסך הפוכה בלבד.', false, 'טענה זו שגויה. סעיף 6 כולל גם הרמת מסך מלאה ומדומה. הרמת מסך הפוכה אינה מפורשת בסעיף 6.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'רק הרמת מסך מלאה, שכן היא הצורה היחידה המצמצמת את עקרון האחריות המוגבלת.', false, 'טענה זו שגויה. סעיף 6 כולל שלוש צורות שונות של הרמת מסך, כל אחת עם מטרתה ותנאיה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 4, '2023-S-S-Q04';
END
$$;

