-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '4872f23e-5d40-4f63-83b5-c3ce59d2b2ff'::uuid;
  v_group_id uuid := 'd2621171-7782-4ff5-a12d-2b661745a7c7'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'a2f9c42e-fbfe-40b9-894a-b0b22c8a70a4'::uuid;
  v_ang_1 uuid := 'dd4a7cb5-40f7-4d00-8fc8-dad12951fb97'::uuid;
  v_ang_2 uuid := '549a2f7b-6f78-4e6b-a508-81ba7bcb1d97'::uuid;
  v_ang_3 uuid := '7fd3f242-6736-4fb6-8354-570b10798d08'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q05';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 5, '2023-S-S-Q05';
