    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'fiduciary_duties', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q05', v_chapter_id, v_subtopic_id, 'מר מלמד מכהן כמנכ"ל בחברה ציבורית, ומאחר שיו"ר הדירקטוריון בחברה נאלץ מיוזמתו לסיים את תפקידו לאלתר הוחלט כי מר מלמד יכהן גם כיו"ר הדירקטוריון בחברה. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 5}'::jsonb, 'השאלה עוסקת בסוגיית כהונה כפולה של מנכ"ל ויו"ר דירקטוריון בחברה ציבורית, נושא המוסדר בסעיף 95 לחוק החברות, התשנ"ט-1999. היא בוחנת את הכלל האוסר כהונה כפולה בחברה ציבורית ואת החריג לכלל זה, הדורש אישורים מיוחדים של ועדת הביקורת, הדירקטוריון והאסיפה הכללית, וכן את תנאי השנתיים.', 'סעיף 95(א) לחוק החברות קובע כלל עקרוני: "בחברה ציבורית לא יכהן אותו אדם כיושב ראש הדירקטוריון וכמנהל הכללי". חוק החברות, תשנ"ט-1999, סעיף 95(א) כלל זה נועד למנוע ריכוז כוח רב מדי בידי אדם אחד, ולהבטיח פיקוח אפקטיבי של הדירקטוריון על הניהול השוטף של החברה. יוסף גרוס, חוק החברות (2016) | יו"ר הדירקטוריון
עם זאת, סעיף 95(ב) לחוק קובע חריג לכלל זה, המאפשר כהונה כפולה בחברה ציבורית אם מתקיימים כל התנאים המצטברים הבאים:
1. ועדת הביקורת אישרה זאת.
2. הדירקטוריון אישר זאת.
3. האסיפה הכללית אישרה זאת ברוב מיוחד, כאמור בסעיף 121(ב) לחוק החברות. רוב זה דורש שרוב מקרב בעלי המניות שאינם בעלי עניין אישי באישור העסקה, ישתתפו בהצבעה, וכי מניין קולותיהם יהווה לפחות שליש מכלל קולות בעלי המניות האמורים. חוק החברות, תשנ"ט-1999, סעיף 121(ב)
4. חלפו שנתיים ממועד סיום כהונתו הקודמת כיו"ר הדירקטוריון, אם כיהן כיו"ר הדירקטוריון. חוק החברות, תשנ"ט-1999, סעיף 95(ב)(4)
במקרה הנדון, מר מלמד נאלץ לסיים את תפקידו כיו"ר לאלתר, ואין מידע על כך שחלפו שנתיים ממועד סיום כהונתו הקודמת כיו"ר (אם כיהן). גם אם לא כיהן בעבר, עדיין נדרשים אישורים של ועדת הביקורת, הדירקטוריון והאסיפה הכללית ברוב מיוחד. התשובה הנכונה משקפת את הצורך באישור האסיפה הכללית בהתאם לתנאים הקבועים בחוק, הכוללים את כלל האישורים והתנאים המפורטים בסעיף 95(ב).', 'הטעות הנפוצה היא להתעלם מהדרישות המצטברות והמחמירות לאישור כהונה כפולה בחברה ציבורית, או לבלבל בין הכלל לחריג, או בין חברה ציבורית לפרטית.',
    '["כהונה כפולה", "חברה ציבורית", "יו\"ר דירקטוריון", "מנכ\"ל", "ועדת ביקורת", "דירקטוריון", "אסיפה כללית", "רוב מיוחד", "סעיף 95 לחוק החברות", "סעיף 121 לחוק החברות"]'::jsonb, '**וריאציה 1 — הכלל בחברה ציבורית:** האם מנכ"ל יכול לכהן כיו"ר בחברה ציבורית? ← ככלל, לא. סעיף 95(א) לחוק החברות אוסר זאת. חוק החברות, תשנ"ט-1999, סעיף 95(א)
**וריאציה 2 — החריג:** מתי מנכ"ל יכול לכהן כיו"ר בחברה ציבורית? ← אם אושר על ידי ועדת ביקורת, דירקטוריון ואסיפה כללית ברוב מיוחד, וחלפו שנתיים (אם רלוונטי). חוק החברות, תשנ"ט-1999, סעיף 95(ב)
**וריאציה 3 — רציונל האיסור:** מה הרציונל לאיסור כהונה כפולה בחברה ציבורית? ← למנוע ריכוז כוח רב מדי בידי אדם אחד ולהבטיח פיקוח אפקטיבי. יוסף גרוס, חוק החברות (2016) | יו"ר הדירקטוריון', 'בחברה ציבורית, מנכ"ל לא יכהן כיו"ר (ס'' 95(א)), אלא אם אושר ע"י ועדת ביקורת, דירקטוריון ואסיפה כללית ברוב מיוחד (ס'' 95(ב) ו-121(ב)), וחלפו שנתיים (אם רלוונטי).', '["חוק החברות, תשנ\"ט-1999, סעיפים 95, 121", "יוסף גרוס, חוק החברות (2016), פרק י: הדירקטוריון, עמ'' 10"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''fiduciary_duties'' | classifier_note: CEO + Chairman of the board dual role — officer duties and combined-role rules | source_review_note: השאלה עוסקת בדיני חברות, ובפרט בכהונה כפולה של מנכ"ל ויו"ר דירקטוריון. תחום זה אינו נכלל ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''הליכים'' נבחר כברירת מחדל תחת ''סדר דין אזרחי'' בשל הקשר העקיף להליכים משפטיים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני תאגידים'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'מר מלמד אשר משמש כמנכ"ל בחברה ציבורית לעולם אינו רשאי לשמש בו זמנית גם כיו"ר דירקטוריון החברה.', false, 'טענה זו שגויה. סעיף 95(ב) לחוק החברות קובע חריג לכלל זה, המאפשר כהונה כפולה בחברה ציבורית בתנאים מסוימים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מר מלמד רשאי לכהן בו זמנית כיו"ר דירקטוריון החברה וכמנכ"ל החברה במקרה שבו הדבר אושר על ידי האסיפה הכללית בהתאם לתנאים הקבועים בחוק.', true, 'תשובה זו נכונה. סעיף 95(ב) לחוק החברות קובע כי בחברה ציבורית, מנכ"ל רשאי לכהן כיו"ר דירקטוריון אם הדבר אושר על ידי ועדת הביקורת, הדירקטוריון והאסיפה הכללית ברוב מיוחד, ובלבד שחלפו שנתיים ממועד סיום כהונתו הקודמת כיו"ר (אם כיהן). סעיף 121 לחוק החברות קובע את הרוב המיוחד הנדרש באסיפה הכללית לאישור עסקה עם בעל שליטה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מר מלמד רשאי לכהן בו זמנית כיו"ר דירקטוריון החברה וכמנכ"ל החברה רק אם הדבר הוגבל לשנתיים.', false, 'טענה זו שגויה. ההגבלה לשנתיים מתייחסת למצב שבו המנכ"ל כיהן בעבר כיו"ר, ונדרש שיעברו שנתיים מסיום כהונתו הקודמת כיו"ר. אין זו הגבלה על משך הכהונה הכפולה עצמה.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אין כל מניעה שמר מלמד יכהן בו זמנית כיו"ר דירקטוריון החברה וכמנכ"ל החברה, ולא נדרש אישור כלשהו לכך.', false, 'טענה זו שגויה. סעיף 95(א) לחוק החברות קובע איסור עקרוני על כהונה כפולה בחברה ציבורית, וסעיף 95(ב) קובע חריג הדורש אישורים מיוחדים.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'כהונה כפולה בחברה פרטית',
    1, 'מר כהן מכהן כמנכ"ל בחברה פרטית. האם הוא רשאי לכהן בו זמנית גם כיו"ר הדירקטוריון של החברה?', 'שאלה זו בוחנת את ההבחנה בין חברה ציבורית לחברה פרטית לעניין כהונה כפולה של מנכ"ל ויו"ר דירקטוריון. היא מדגישה את החריג הקבוע בסעיף 95(א) לחוק החברות, הפוטר חברות פרטיות מהאיסור על כהונה כפולה.', 'סעיף 95(א) לחוק החברות, התשנ"ט-1999, קובע כי "בחברה ציבורית לא יכהן אותו אדם כיושב ראש הדירקטוריון וכמנהל הכללי". חוק החברות, תשנ"ט-1999, סעיף 95(א) אולם, הסיפא של סעיף קטן זה מבהירה כי "הוראה זו לא תחול על חברה פרטית". חוק החברות, תשנ"ט-1999, סעיף 95(א) לפיכך, בחברה פרטית, אין כל מניעה חוקית שאותו אדם יכהן במקביל הן כמנכ"ל והן כיו"ר הדירקטוריון. נבו - המתמחה, דיני תאגידים (2026) | יו"ר הדירקטוריון',
    'הטעות הנפוצה היא להחיל את הכללים הנוקשים של חברה ציבורית על חברה פרטית, מבלי לשים לב להבחנה המפורשת בחוק.', '["כהונה כפולה", "חברה ציבורית", "חברה פרטית", "יו\"ר דירקטוריון", "מנכ\"ל", "חוק החברות"]'::jsonb, '**וריאציה 1 — חברה פרטית:** האם מנכ"ל יכול להיות יו"ר בחברה פרטית? ← כן, סעיף 95(א) לחוק החברות קובע שהאיסור לא חל על חברה פרטית. חוק החברות, תשנ"ט-1999, סעיף 95(א)
**וריאציה 2 — רציונל:** מה הרציונל להבחנה בין חברה ציבורית לפרטית? ← בחברה פרטית אין חשש לניגוד עניינים מובנה כמו בחברה ציבורית, בה יש ציבור בעלי מניות שאינו מעורב בניהול השוטף. יוסף גרוס, חוק החברות (2016) | יו"ר הדירקטוריון
**וריאציה 3 — חברה ממשלתית:** האם האיסור חל על חברה ממשלתית? ← כן, חברה ממשלתית נחשבת כחברה ציבורית לעניין זה. נבו - המתמחה, דיני תאגידים (2026) | יו"ר הדירקטוריון', 'בחברה פרטית ← מנכ"ל יכול לכהן כיו"ר דירקטוריון (ס'' 95(א) לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 95(א)", "נבו - המתמחה, דיני תאגידים (2026), יו\"ר הדירקטוריון, עמ'' 10", "יוסף גרוס, חוק החברות (2016), פרק י: הדירקטוריון, עמ'' 10"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, בחברה פרטית אין מניעה לכהונה כפולה של מנכ"ל ויו"ר דירקטוריון.', true, 'תשובה זו נכונה. סעיף 95(א) לחוק החברות קובע במפורש כי האיסור על כהונה כפולה אינו חל על חברה פרטית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, האיסור על כהונה כפולה חל על כל סוגי החברות, ציבוריות ופרטיות כאחד.', false, 'טענה זו שגויה. סעיף 95(א) לחוק החברות מבחין בין חברה ציבורית לפרטית לעניין זה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם הדבר אושר על ידי האסיפה הכללית ברוב מיוחד.', false, 'טענה זו שגויה. אישור ברוב מיוחד נדרש בחברה ציבורית, לא בחברה פרטית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן חלפו שנתיים ממועד סיום כהונתו הקודמת כיו"ר.', false, 'טענה זו שגויה. הגבלת השנתיים רלוונטית לחברה ציבורית, וגם אז, רק אם המנכ"ל כיהן בעבר כיו"ר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי האישור לכהונה כפולה בחברה ציבורית',
    2, 'מהם התנאים המצטברים הנדרשים לאישור כהונה כפולה של מנכ"ל ויו"ר דירקטוריון בחברה ציבורית, לפי סעיף 95(ב) לחוק החברות?', 'שאלה זו מתמקדת בתנאים המצטברים והמחמירים לאישור כהונה כפולה של מנכ"ל ויו"ר דירקטוריון בחברה ציבורית, כפי שנקבעו בסעיף 95(ב) לחוק החברות. היא מדגישה את חשיבות האישורים של ועדת הביקורת, הדירקטוריון והאסיפה הכללית, ואת הרוב המיוחד הנדרש באסיפה הכללית.', 'סעיף 95(ב) לחוק החברות קובע את התנאים המצטברים לאישור כהונה כפולה של מנכ"ל ויו"ר דירקטוריון בחברה ציבורית: חוק החברות, תשנ"ט-1999, סעיף 95(ב)
התנאים הם:
1. אישור ועדת הביקורת.
2. אישור הדירקטוריון.
3. אישור האסיפה הכללית ברוב מיוחד, כאמור בסעיף 121(ב) לחוק החברות. רוב זה דורש שרוב מקרב בעלי המניות שאינם בעלי עניין אישי באישור העסקה, ישתתפו בהצבעה, וכי מניין קולותיהם יהווה לפחות שליש מכלל קולות בעלי המניות האמורים. חוק החברות, תשנ"ט-1999, סעיף 121(ב)
4. חלפו שנתיים ממועד סיום כהונתו הקודמת כיו"ר הדירקטוריון, אם כיהן כיו"ר הדירקטוריון. נבו - המתמחה, דיני תאגידים (2026) | יו"ר הדירקטוריון',
    'הטעות הנפוצה היא להתעלם מאחד האישורים הנדרשים (ועדת ביקורת, דירקטוריון, אסיפה כללית) או מהדרישה לרוב מיוחד באסיפה הכללית, או לבלבל בין תנאי השנתיים לבין משך הכהונה.', '["כהונה כפולה", "חברה ציבורית", "ועדת ביקורת", "דירקטוריון", "אסיפה כללית", "רוב מיוחד", "סעיף 95 לחוק החברות", "סעיף 121 לחוק החברות"]'::jsonb, '**וריאציה 1 — גופי האישור:** אילו גופים צריכים לאשר כהונה כפולה בחברה ציבורית? ← ועדת ביקורת, דירקטוריון, אסיפה כללית. חוק החברות, תשנ"ט-1999, סעיף 95(ב)

**וריאציה 2 — רוב באסיפה:** מהו הרוב הנדרש באסיפה הכללית? ← רוב מיוחד לפי סעיף 121(ב) לחוק החברות. חוק החברות, תשנ"ט-1999, סעיף 121(ב)
**וריאציה 3 — תנאי השנתיים:** מתי חל תנאי השנתיים? ← אם המנכ"ל כיהן בעבר כיו"ר, נדרש שיעברו שנתיים מסיום כהונתו הקודמת. חוק החברות, תשנ"ט-1999, סעיף 95(ב)(4)', 'כהונה כפולה בחברה ציבורית ← אישור ועדת ביקורת, דירקטוריון, אסיפה כללית (רוב מיוחד ס'' 121(ב)), ותנאי שנתיים (אם כיהן בעבר).',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 95(ב), 121(ב)", "נבו - המתמחה, דיני תאגידים (2026), יו\"ר הדירקטוריון, עמ'' 10"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'אישור ועדת הביקורת, הדירקטוריון והאסיפה הכללית ברוב רגיל, ובלבד שחלפו שנתיים ממועד סיום כהונתו הקודמת כיו"ר.', false, 'טענה זו שגויה. נדרש רוב מיוחד באסיפה הכללית, ולא רוב רגיל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'אישור ועדת הביקורת, הדירקטוריון והאסיפה הכללית ברוב מיוחד, ובלבד שחלפו שנתיים ממועד סיום כהונתו הקודמת כיו"ר (אם כיהן).', true, 'תשובה זו נכונה. אלו הם התנאים המצטברים הקבועים בסעיף 95(ב) לחוק החברות, בתוספת הרוב המיוחד הנדרש לפי סעיף 121 לחוק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'אישור הדירקטוריון בלבד, ובלבד שחלפו שנתיים ממועד סיום כהונתו הקודמת כיו"ר.', false, 'טענה זו שגויה. נדרשים אישורים של שלושה גופים: ועדת ביקורת, דירקטוריון ואסיפה כללית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'אישור האסיפה הכללית ברוב מיוחד, ללא צורך באישור ועדת הביקורת או הדירקטוריון.', false, 'טענה זו שגויה. נדרשים אישורים של שלושה גופים: ועדת ביקורת, דירקטוריון ואסיפה כללית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'כהונה כפולה בחברה ציבורית קטנה',
    3, 'חברת "סטארט-אפ ציבורי בע"מ" היא חברה ציבורית קטנה, שאינה חייבת למנות ועדת ביקורת. האם מנכ"ל החברה רשאי לכהן כיו"ר הדירקטוריון, ומהם התנאים לכך?', 'שאלה זו בוחנת את החריג לכלל האיסור על כהונה כפולה של מנכ"ל ויו"ר דירקטוריון בחברה ציבורית, החל על חברות ציבוריות קטנות שאינן חייבות למנות ועדת ביקורת. היא מדגישה את ההתאמה של דרישות האישור למבנה הארגוני של חברות אלו, תוך שמירה על עקרון הפיקוח.', 'סעיף 95(ג) לחוק החברות קובע חריג ספציפי לחברות ציבוריות קטנות: "על אף הוראות סעיף קטן (ב)(1), בחברה ציבורית שאינה חייבת למנות ועדת ביקורת, יראו את תנאי סעיף קטן (ב)(1) מתקיים אם הדירקטוריון אישר זאת". חוק החברות, תשנ"ט-1999, סעיף 95(ג) כלומר, במקרה כזה, דרישת אישור ועדת הביקורת מתייתרת, ודי באישור הדירקטוריון והאסיפה הכללית ברוב מיוחד, בתוספת תנאי השנתיים (אם רלוונטי). נבו - המתמחה, דיני תאגידים (2026) | יו"ר הדירקטוריון',
    'הטעות הנפוצה היא להתעלם מהחריג לחברות ציבוריות קטנות, או לחשוב שחריג זה פוטר מכל דרישות האישור האחרות.', '["כהונה כפולה", "חברה ציבורית קטנה", "ועדת ביקורת", "דירקטוריון", "אסיפה כללית", "רוב מיוחד", "סעיף 95 לחוק החברות"]'::jsonb, '**וריאציה 1 — חברה קטנה ללא ועדת ביקורת:** מה נדרש לאישור כהונה כפולה בחברה ציבורית קטנה ללא ועדת ביקורת? ← אישור דירקטוריון, אסיפה כללית ברוב מיוחד, ותנאי שנתיים (אם רלוונטי). חוק החברות, תשנ"ט-1999, סעיף 95(ג)
**וריאציה 2 — תכלית החריג:** מהי תכלית החריג לחברות ציבוריות קטנות? ← התאמת דרישות הפיקוח למבנה הארגוני של חברות אלו, תוך שמירה על עקרון הפיקוח. יוסף גרוס, חוק החברות (2016) | יו"ר הדירקטוריון
**וריאציה 3 — חברה ציבורית שאינה קטנה:** האם חברה ציבורית שאינה קטנה יכולה לוותר על ועדת ביקורת? ← לא, חברה ציבורית שאינה קטנה חייבת למנות ועדת ביקורת. חוק החברות, תשנ"ט-1999, סעיף 114', 'חברה ציבורית קטנה (ללא ועדת ביקורת) ← כהונה כפולה דורשת אישור דירקטוריון, אסיפה כללית (רוב מיוחד), ותנאי שנתיים (אם רלוונטי) (ס'' 95(ג) לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 95(ג), 114", "נבו - המתמחה, דיני תאגידים (2026), יו\"ר הדירקטוריון, עמ'' 10", "יוסף גרוס, חוק החברות (2016), פרק י: הדירקטוריון, עמ'' 10"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, האיסור על כהונה כפולה חל גם על חברות ציבוריות קטנות, ללא חריגים.', false, 'טענה זו שגויה. סעיף 95(ג) לחוק החברות קובע חריג מיוחד לחברות ציבוריות קטנות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, אם הדבר אושר על ידי הדירקטוריון והאסיפה הכללית ברוב מיוחד, ובלבד שחלפו שנתיים ממועד סיום כהונתו הקודמת כיו"ר (אם כיהן).', true, 'תשובה זו נכונה. סעיף 95(ג) לחוק החברות קובע כי בחברה ציבורית שאינה חייבת למנות ועדת ביקורת, די באישור הדירקטוריון והאסיפה הכללית ברוב מיוחד, בתוספת תנאי השנתיים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם הדבר אושר על ידי הדירקטוריון בלבד.', false, 'טענה זו שגויה. נדרש גם אישור האסיפה הכללית ברוב מיוחד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, ללא צורך באישור כלשהו, שכן החברה קטנה ואינה חייבת למנות ועדת ביקורת.', false, 'טענה זו שגויה. גם בחברה ציבורית קטנה נדרשים אישורים מיוחדים, אף אם ועדת הביקורת אינה קיימת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'תפקידי יו"ר הדירקטוריון',
    4, 'מהם תפקידיו העיקריים של יו"ר הדירקטוריון בחברה ציבורית, וכיצד הם נבדלים מתפקידי המנכ"ל?', 'שאלה זו עוסקת בהפרדת התפקידים בין יו"ר הדירקטוריון למנכ"ל בחברה ציבורית, כפי שמשתקף מסעיפים 92 ו-93 לחוק החברות. היא מדגישה את הרציונל שמאחורי איסור הכהונה הכפולה – מניעת ריכוז כוח והבטחת פיקוח אפקטיבי על הניהול השוטף.', 'חוק החברות מבחין באופן ברור בין תפקידי הדירקטוריון לבין תפקידי המנכ"ל. הדירקטוריון, ובראשו היו"ר, אחראי על קביעת מדיניות החברה ופיקוח על ביצועיה. סעיף 92 לחוק החברות קובע כי "הדירקטוריון יתווה את מדיניות החברה ויפקח על ביצוע תפקידי המנהל הכללי ופעולותיו". חוק החברות, תשנ"ט-1999, סעיף 92 סעיף 93 לחוק מפרט את תפקידי יו"ר הדירקטוריון, הכוללים ניהול ישיבות הדירקטוריון, קביעת סדר יומן, ודאגה לביצוע החלטות הדירקטוריון. חוק החברות, תשנ"ט-1999, סעיף 93 לעומת זאת, המנכ"ל אחראי על ניהול ענייני החברה השוטפים. חוק החברות, תשנ"ט-1999, סעיף 92 הפרדה זו נועדה למנוע ריכוז כוח רב מדי בידי אדם אחד, ולהבטיח פיקוח אפקטיבי של הדירקטוריון על הניהול השוטף. יוסף גרוס, חוק החברות (2016) | יו"ר הדירקטוריון',
    'הטעות הנפוצה היא לבלבל בין תחומי האחריות של יו"ר הדירקטוריון (פיקוח ומדיניות) לבין אלה של המנכ"ל (ניהול שוטף).', '["יו\"ר דירקטוריון", "מנכ\"ל", "הפרדת סמכויות", "פיקוח", "ניהול שוטף", "קביעת מדיניות", "חוק החברות"]'::jsonb, '**וריאציה 1 — תפקיד היו"ר:** מהו תפקידו העיקרי של יו"ר הדירקטוריון? ← ניהול ישיבות הדירקטוריון וקביעת סדר יומן. חוק החברות, תשנ"ט-1999, סעיף 93
**וריאציה 2 — תפקיד המנכ"ל:** מהו תפקידו העיקרי של המנכ"ל? ← ניהול ענייני החברה השוטפים. חוק החברות, תשנ"ט-1999, סעיף 92
**וריאציה 3 — רציונל ההפרדה:** מדוע קיימת הפרדה בין התפקידים? ← למנוע ריכוז כוח ולהבטיח פיקוח אפקטיבי. יוסף גרוס, חוק החברות (2016) | יו"ר הדירקטוריון', 'יו"ר דירקטוריון ← פיקוח ומדיניות (ס'' 93). מנכ"ל ← ניהול שוטף (ס'' 92). הפרדה למניעת ריכוז כוח.',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 92, 93", "יוסף גרוס, חוק החברות (2016), פרק י: הדירקטוריון, עמ'' 10"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'יו"ר הדירקטוריון מנהל את ענייני החברה השוטפים, ואילו המנכ"ל אחראי על קביעת מדיניות החברה.', false, 'טענה זו שגויה. תפקידי היו"ר והמנכ"ל הפוכים: המנכ"ל מנהל את ענייני החברה השוטפים, והיו"ר אחראי על ניהול ישיבות הדירקטוריון וקביעת מדיניות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'יו"ר הדירקטוריון מנהל את ישיבות הדירקטוריון וקובע את סדר יומן, ואילו המנכ"ל אחראי על ניהול ענייני החברה השוטפים.', true, 'תשובה זו נכונה. סעיף 93 לחוק החברות מגדיר את תפקידי יו"ר הדירקטוריון, וסעיף 92 מגדיר את תפקידי המנכ"ל, תוך הפרדה ברורה בין ניהול שוטף לפיקוח וקביעת מדיניות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'יו"ר הדירקטוריון והמנכ"ל חולקים באחריות לניהול השוטף ולקביעת המדיניות באופן שווה.', false, 'טענה זו שגויה. חוק החברות מבחין באופן ברור בין תפקידי הניהול השוטף (מנכ"ל) לבין תפקידי הפיקוח וקביעת המדיניות (דירקטוריון ויו"ר).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'יו"ר הדירקטוריון אחראי על קשרי החברה עם בעלי המניות, ואילו המנכ"ל אחראי על קשרי החברה עם הדירקטוריון.', false, 'טענה זו שגויה. תפקידי היו"ר והמנכ"ל רחבים יותר ומתמקדים בניהול ופיקוח פנימיים, ולא רק בקשרי חוץ.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 5, '2023-S-S-Q05';
END
$$;

-- ============================================================
-- Q06 — 2023-S-S-Q06 — chapter=contracts subtopic=limitation
-- classifier_note: Statute of limitations — accident + phone damage timeline; pure limitation-period question per the source review_note
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'a0f2cd9d-78d8-43d2-9d4c-f3814f2d2788'::uuid;
  v_group_id uuid := '1e261596-b736-4d85-95e8-e35832d3b633'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '3bb3249b-d170-4314-9780-e0e61205413d'::uuid;
  v_ang_1 uuid := 'c84ce2c3-ebbc-4f50-ba50-71c097ac28c4'::uuid;
  v_ang_2 uuid := '49e223b5-5fe6-470c-9b69-d714f5464eb6'::uuid;
  v_ang_3 uuid := '7ad5a690-4b86-4902-9eed-70046b761776'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q06';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 6, '2023-S-S-Q06';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'limitation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'limitation', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q06', v_chapter_id, v_subtopic_id, 'ביום 20.8.2015, החליקה לימור בקניון, וכתוצאה מכך איבדה את הכרתה ל-10 ימים, שברה את ידה ואת כף רגלה. הטלפון הנייד שאחזה ביד נפל והמסך נסדק. ביום 5.9.2015 הפסיק הטלפון הנייד של לימור לפעול כליל, ובחנות הטלפונים נאמר לה שהדבר נגרם מהנפילה. לימור מעוניינת להגיש תביעה נגד הקניון בגין נזקי הגוף והרכוש שנגרמו לה. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 6}'::jsonb, 'השאלה עוסקת במועד תחילת מרוץ ההתיישנות בתביעות נזיקין, ובפרט ביישום כלל הגילוי המאוחר הקבוע בסעיף 89(2) לפקודת הנזיקין [נוסח חדש]. היא בוחנת מצב שבו הנזק (הן הגופני והן הרכושי) לא התגלה באופן מיידי עקב נסיבות אובייקטיביות (איבוד הכרה), וכיצד הדבר משפיע על חישוב תקופת ההתיישנות.', 'הכלל הבסיסי בדיני התיישנות קובע כי תקופת ההתיישנות לתביעה שאינה במקרקעין היא 7 שנים (סעיף 5 לחוק ההתיישנות, תשי"ח-1958). ת"א (שלום ראשל"צ) 26915-10-21 יוחאי מילוא נ'' אל חנן סולומון (02.01.2023) מרוץ ההתיישנות מתחיל ביום שבו נולדה עילת התובענה (סעיף 6 לחוק ההתיישנות). ת"א (שלום נצרת) 16438-04-23 בוקי בועז נ'' בן ציון ליכטמן (18.08.2023)
בתביעות נזיקין, סעיף 89(2) לפקודת הנזיקין [נוסח חדש] קובע כלל מיוחד לגילוי מאוחר של נזק: "מקום שעילת התובענה היא נזק שנגרם על ידי מעשה או מחדל היום שבו אירע אותו נזק; לא נתגלה הנזק ביום שאירע היום שבו נתגלה הנזק, אלא שבמקרה אחרון זה תתיישן התובענה אם לא הוגשה תוך עשר שנים מיום אירוע הנזק". ע"א 8172/12 פלוני נ'' אגד-אגודה שיתופית לתחבורה בישראל בע"מ (18.01.2018)
במקרה של לימור:
1. **נזקי גוף**: התאונה אירעה ב-20.8.2015. לימור איבדה את הכרתה ל-10 ימים. משמעות הדבר היא שנזקי הגוף (שבר ביד וברגל, איבוד הכרה) לא יכלו להתגלות לה ביום האירוע. מועד גילוי הנזק, או לכל הפחות היכולת לגלות אותו, הוא ביום התעוררותה, כלומר 30.8.2015. מרוץ ההתיישנות יחל במועד זה. תקופת ההתיישנות היא 7 שנים, ולכן התביעה תתיישן ב-30.8.2022.
2. **נזקי רכוש (טלפון)**: הטלפון נפל והמסך נסדק ב-20.8.2015. גם אם המסך נסדק מיד, לימור לא יכלה לגלות זאת בהיותה מחוסרת הכרה. לכן, גילוי הנזק (המסך הסדוק) נדחה אף הוא ל-30.8.2015. הפסיקה קובעת כי מרוץ ההתיישנות מתחיל עם גילוי נזק פיזי כלשהו, ואין צורך להמתין לגיבושו השלם במלוא היקפו. ת"א (מחוזי ת"א) 4193-03-22 SPACEGROVE HOLDING LIMITED נ'' י. מנדלברג חב'' לעבודות בנין בע"מ (12.02.2023) העובדה שהטלפון הפסיק לפעול כליל ב-5.9.2015 והקשר הסיבתי אושר אז, אינה דוחה את תחילת מרוץ ההתיישנות, שכן נזק (מסך סדוק) כבר התגלה קודם לכן. לכן, גם תביעת נזקי הרכוש תתיישן ב-30.8.2022.
התשובה הנכונה היא ב'', שכן מועד גילוי הנזק עבור שני סוגי הנזקים (גוף ורכוש) הוא 30.8.2015, ומכאן שתקופת ההתיישנות של 7 שנים מסתיימת ב-30.8.2022.
', 'הטעות הנפוצה היא לחשב את מרוץ ההתיישנות מיום האירוע (20.8.2015) או להמתין לגילוי מלוא היקף הנזק או הקשר הסיבתי המלא (5.9.2015), במקום להתחשב במועד גילוי הנזק בפועל או בכוח (30.8.2015) בהתאם לכלל הגילוי המאוחר.',
    '["התיישנות בנזיקין", "כלל הגילוי המאוחר", "סעיף 89(2) לפקודת הנזיקין", "סעיף 5 לחוק ההתיישנות", "סעיף 6 לחוק ההתיישנות", "נזק של מה בכך"]'::jsonb, '**וריאציה 1 — איבוד הכרה:** מתי מתחיל מרוץ ההתיישנות אם התובע איבד הכרה ביום האירוע? ← ביום שבו התעורר והיה יכול לגלות את הנזק. ע"א 2919/07 מדינת ישראל - הוועדה לאנרגיה אטומית נ'' עדנה גיא-ליפל, סד(2) 82 (19.09.2010)
**וריאציה 2 — נזק רכוש מתפתח:** מתי מתחיל מרוץ ההתיישנות אם נזק רכוש התגלה בהדרגה? ← ביום גילוי הנזק הראשון שאינו ''מה בכך'', ולא ביום גילוי מלוא היקפו. ת"א (מחוזי ת"א) 4193-03-22 SPACEGROVE HOLDING LIMITED נ'' י. מנדלברג חב'' לעבודות בנין בע"מ (12.02.2023)
**וריאציה 3 — נטל ההוכחה:** על מי מוטל הנטל להוכיח גילוי מאוחר? ← על התובע הטוען לגילוי מאוחר. ע"א 7680/13 רבקה פרי נ'' שירותי בריאות כללית (11.02.2015)', 'בתביעת נזיקין, מרוץ ההתיישנות (7 שנים) מתחיל ביום גילוי הנזק (ס'' 89(2) לפקודת הנזיקין), אם לא נתגלה ביום האירוע. גילוי נזק פיזי כלשהו, שאינו ''מה בכך'', מתחיל את המרוץ, גם אם היקפו המלא לא ידוע.', '["חוק ההתיישנות, תשי\"ח-1958, סעיפים 5, 6", "פקודת הנזיקין [נוסח חדש], סעיף 89(2)", "ע\"א 2919/07 מדינת ישראל - הוועדה לאנרגיה אטומית נ'' עדנה גיא-ליפל, סד(2) 82 (19.09.2010)", "ע\"א 220/84 בועז אגיוף נ'' קיבוץ גבת - אגודה שיתופית, מ(1) 528 (10.03.1986)", "ע\"א 1254/99 אבידור המאירי נ'' הכשרת הישוב – חברה לביטוח בע\"מ, נד(2) 535 (07.06.2000)", "ע\"א 4338369 פלוני נ'' אגד-אגודה שיתופית לתחבורה בישראל בע\"מ (18.01.2018)", "ע\"א 7680/13 רבקה פרי נ'' שירותי בריאות כללית (11.02.2015)", "ת\"א (מחוזי ת\"א) 4193-03-22 SPACEGROVE HOLDING LIMITED נ'' י. מנדלברג חב'' לעבודות בנין בע\"מ (12.02.2023)", "ת\"א (שלום נצרת) 16438-04-23 בוקי בועז נ'' בן ציון ליכטמן (18.08.2023)", "ת\"א (שלום פ\"ת) 20794-11-22 מועצה מקומית ג''לג''וליה נ'' ע.ע. אבו ראס חברה לעבודות בניין ופיתוח בע\"מ (19.01.2025)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''limitation'' | classifier_note: Statute of limitations — accident + phone damage timeline; pure limitation-period question per the source review_note | source_review_note: השאלה עוסקת בדיני התיישנות, שהם חלק מהדין המהותי אך בעלי השלכות דיוניות משמעותיות. תת-הנושא ''הליכים'' נבחר כברירת מחדל תחת ''סדר דין אזרחי'' בשל הקשר העקיף להליכים משפטיים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני נזיקין'' או ''דיני חיובים'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בנסיבות העניין תביעתה של לימור התיישנה ביום 20.8.2022.', false, 'טענה זו שגויה. מועד האירוע הוא 20.8.2015, אך לימור איבדה את הכרתה ל-10 ימים, ולכן לא יכלה לדעת על הנזקים במועד זה. מרוץ ההתיישנות נדחה למועד גילוי הנזק.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בנסיבות העניין תביעתה של לימור התיישנה ביום 30.8.2022.', true, 'תשובה זו נכונה. לימור איבדה את הכרתה ל-10 ימים, ולכן גילוי נזקי הגוף והרכוש (לפחות המסך הסדוק) נדחה למועד התעוררותה, כלומר 30.8.2015. מרוץ ההתיישנות מתחיל ביום גילוי הנזק (סעיף 89(2) לפקודת הנזיקין), ותקופת ההתיישנות היא 7 שנים (סעיף 5 לחוק ההתיישנות). לכן, התביעה התיישנה ביום 30.8.2022.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בנסיבות העניין תביעתה של לימור התיישנה ביום 5.9.2022.', false, 'טענה זו שגויה. אף שנזק הטלפון המלא התגלה ב-5.9.2015, נזקי הגוף התגלו מוקדם יותר, ב-30.8.2015. כמו כן, הפסיקה קובעת כי מרוץ ההתיישנות מתחיל עם גילוי נזק פיזי כלשהו, ואין צורך להמתין לגיבושו השלם במלוא היקפו.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בנסיבות העניין תביעתה של לימור לנזקי גוף התיישנה ביום 30.8.2022 ותביעתה לנזקי רכוש התיישנה ביום 5.9.2022.', false, 'טענה זו שגויה. אף שנזקי הגוף התיישנו ב-30.8.2022, נזק הרכוש (המסך הסדוק) התגלה לכל המאוחר ב-30.8.2015 (עם התעוררותה של לימור), ולכן גם תביעת הרכוש התיישנה ב-30.8.2022. אין צורך להמתין לגילוי מלוא היקף הנזק או הקשר הסיבתי המלא.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'גילוי מאוחר של קשר סיבתי',
    1, 'ראובן נפגע בתאונת דרכים קלה ביום 1.1.2010, וסבל מכאבי גב קלים. ביום 1.1.2016, לאחר שהכאבים החמירו משמעותית, אובחן אצלו פריצת דיסק חמורה, ומומחה רפואי קבע כי קיים קשר סיבתי ודאי בין התאונה לפריצת הדיסק. ראובן מעוניין להגיש תביעה נגד הנהג הפוגע. מתי תתיישן תביעתו?', 'שאלה זו עוסקת בהבחנה בין גילוי מאוחר של רכיב הנזק לבין גילוי מאוחר של רכיב הקשר הסיבתי בעוולת הרשלנות. היא מדגישה כי בעוד שעל גילוי מאוחר של הנזק חל סעיף 89(2) לפקודת הנזיקין (עם מגבלת 10 השנים), על גילוי מאוחר של הקשר הסיבתי חל סעיף 8 לחוק ההתיישנות, ללא מגבלת 10 השנים.', 'דיני ההתיישנות בנזיקין מורכבים משתי מערכות דינים משלימות: חוק ההתיישנות, תשי"ח-1958, וסעיף 89 לפקודת הנזיקין [נוסח חדש]. תמ"ש (משפחה טבריה) 38977-12-14 פלוני נ'' פלונים (30.04.2020) סעיף 89(2) לפקודת הנזיקין קובע כי אם הנזק לא נתגלה ביום שאירע, מרוץ ההתיישנות יחל ביום שבו נתגלה הנזק, אך התביעה תתיישן אם לא הוגשה תוך 10 שנים מיום אירוע הנזק. ע"א 8172/12 פלוני נ'' אגד-אגודה שיתופית לתחבורה בישראל בע"מ (18.01.2018) הוראה זו חלה על גילוי מאוחר של רכיב הנזק בלבד. ת"א (שלום נצ'') 28440-06-21 פלוני נ'' ועדת השחרורים בכלא שיטה (05.01.2022) לעומת זאת, על גילוי מאוחר של רכיבים אחרים בעילת התביעה, כגון הקשר הסיבתי או ההתרשלות, חל סעיף 8 לחוק ההתיישנות. ת"א (שלום ת"א) 26995-10-10 אסתר קריספין, עו"ד נ'' נסקה לוי (05.01.2011) סעיף 8 קובע כי אם נעלמו מן התובע העובדות המהוות את עילת התובענה, מסיבות שלא היו תלויות בו ושאף בזהירות סבירה לא יכול היה למנוע אותן, תתחיל תקופת ההתיישנות ביום שבו נודעו לתובע עובדות אלה, ללא מגבלת 10 השנים. ע"א 7680/13 רבקה פרי נ'' שירותי בריאות כללית (11.02.2015) במקרה זה, הנזק (כאבי גב קלים) התגלה ב-1.1.2010, אך הקשר הסיבתי לפריצת הדיסק החמורה התגלה רק ב-1.1.2016. לכן, מרוץ ההתיישנות יחל ב-1.1.2016, והתביעה תתיישן 7 שנים לאחר מכן, ב-1.1.2023.',
    'הטעות הנפוצה היא להחיל את מגבלת 10 השנים שבסעיף 89(2) לפקודת הנזיקין גם על גילוי מאוחר של הקשר הסיבתי, במקום להחיל את סעיף 8 לחוק ההתיישנות.', '["התיישנות בנזיקין", "גילוי מאוחר", "קשר סיבתי", "סעיף 8 לחוק ההתיישנות", "סעיף 89(2) לפקודת הנזיקין", "תקופת התיישנות"]'::jsonb, '**וריאציה 1 — גילוי מאוחר של נזק:** מתי מתחיל מרוץ ההתיישנות אם הנזק התגלה באיחור? ← ביום גילוי הנזק, אך לא יאוחר מ-10 שנים מיום אירוע הנזק (סעיף 89(2) לפקודת הנזיקין). ע"א 8172/12 פלוני נ'' אגד-אגודה שיתופית לתחבורה בישראל בע"מ (18.01.2018)
**וריאציה 2 — גילוי מאוחר של קשר סיבתי:** מתי מתחיל מרוץ ההתיישנות אם הקשר הסיבתי התגלה באיחור? ← ביום גילוי הקשר הסיבתי, לפי סעיף 8 לחוק ההתיישנות, ללא מגבלת 10 שנים. ת"א (שלום ת"א) 26995-10-10 אסתר קריספין, עו"ד נ'' נסקה לוי (05.01.2011)
**וריאציה 3 — נטל ההוכחה:** על מי מוטל הנטל להוכיח גילוי מאוחר? ← על התובע הטוען לגילוי מאוחר. ע"א 7680/13 רבקה פרי נ'' שירותי בריאות כללית (11.02.2015)', 'גילוי מאוחר של נזק ← ס'' 89(2) לפקודת הנזיקין (עד 10 שנים מיום האירוע). גילוי מאוחר של קשר סיבתי/התרשלות ← ס'' 8 לחוק ההתיישנות (מיום הגילוי, ללא מגבלת 10 שנים).',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיפים 5, 6, 8", "פקודת הנזיקין [נוסח חדש], סעיף 89(2)", "ע\"א 2919/07 מדינת ישראל - הוועדה לאנרגיה אטומית נ'' עדנה גיא-ליפל, סד(2) 82 (19.09.2010)", "ע\"א 8172/12 פלוני נ'' אגד-אגודה שיתופית לתחבורה בישראל בע\"מ (18.01.2018)", "ע\"א 7680/13 רבקה פרי נ'' שירותי בריאות כללית (11.02.2015)", "ת\"א (שלום ת\"א) 26995-10-10 אסתר קריספין, עו\"ד נ'' נסקה לוי (05.01.2011)", "תמ\"ש (משפחה טבריה) 38977-12-14 פלוני נ'' פלונים (30.04.2020)", "ת\"א (שלום נצ'') 28440-06-21 פלוני נ'' ועדת השחרורים בכלא שיטה (05.01.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'התביעה התיישנה ביום 1.1.2017, שכן מרוץ ההתיישנות החל ביום התאונה.', false, 'טענה זו שגויה. במקרה של נזק שנגרם על ידי מעשה או מחדל, אם הנזק לא נתגלה ביום שאירע, מרוץ ההתיישנות מתחיל ביום שבו נתגלה הנזק, ולא ביום האירוע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'התביעה התיישנה ביום 1.1.2023, שכן מרוץ ההתיישנות החל ביום גילוי הקשר הסיבתי.', true, 'תשובה זו נכונה. סעיף 8 לחוק ההתיישנות חל על גילוי מאוחר של רכיב הקשר הסיבתי. מרוץ ההתיישנות יחל ביום שבו נודעו לתובע העובדות המהוות את עילת התובענה, כולל הקשר הסיבתי, אם אלה נעלמו ממנו מסיבות שלא היו תלויות בו ובזהירות סבירה לא יכול היה למנוע אותן. במקרה זה, הקשר הסיבתי נודע ב-1.1.2016, ולכן התביעה תתיישן ב-1.1.2023.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'התביעה התיישנה ביום 1.1.2020, שכן חלה מגבלת 10 השנים מיום אירוע הנזק.', false, 'טענה זו שגויה. מגבלת 10 השנים שבסעיף 89(2) לפקודת הנזיקין חלה על גילוי מאוחר של רכיב הנזק, אך לא על גילוי מאוחר של רכיב הקשר הסיבתי, עליו חל סעיף 8 לחוק ההתיישנות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'התביעה לא התיישנה, שכן נזקי גוף אינם מתיישנים לעולם.', false, 'טענה זו שגויה. גם תביעות נזיקין בגין נזקי גוף כפופות לדיני ההתיישנות, עם חריגים מסוימים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן הגילוי המאוחר',
    2, 'מהו המבחן לקביעת מועד תחילת מרוץ ההתיישנות במקרים של גילוי מאוחר של נזק, לפי סעיף 89(2) לפקודת הנזיקין?', 'שאלה זו מתמקדת במבחן האובייקטיבי של ''אדם סביר'' ו''נזק של מה בכך'' בקביעת מועד תחילת מרוץ ההתיישנות במקרים של גילוי מאוחר של נזק, לפי סעיף 89(2) לפקודת הנזיקין. היא מדגישה כי אין צורך בגילוי מלוא היקף הנזק, אלא די בגילוי נזק משמעותי שאינו זניח.', 'הפסיקה קבעה כי המבחן לקביעת מועד תחילת מרוץ ההתיישנות במקרים של גילוי מאוחר של נזק, לפי סעיף 89(2) לפקודת הנזיקין, הוא מבחן אובייקטיבי של ''אדם סביר''. ע"א 8172/12 פלוני נ'' אגד-אגודה שיתופית לתחבורה בישראל בע"מ (18.01.2018) אין די בהתגלות נזק כלשהו, אלא התגלות הנזק תחל את ההתיישנות אם הניזוק, כאדם סביר, היה מגיש תביעה בגינו. אם הנזק הוא ''נזק של מה בכך'', שאדם בר-דעת ומזג רגיל לא היה מתלונן עליו, אזי אין לראות בהתגלות זו כמועד תחילת ההתיישנות. ת"א (שלום פ"ת) 20794-11-22 מועצה מקומית ג''לג''וליה נ'' ע.ע. אבו ראס חברה לעבודות בניין ופיתוח בע"מ (19.01.2025) כמו כן, מרוץ ההתיישנות מתחיל עם גילוי הנזק ולא במועד בו קיימת אפשרות לעמוד על מלוא היקפו. ת"א (מחוזי ת"א) 4193-03-22 SPACEGROVE HOLDING LIMITED נ'' י. מנדלברג חב'' לעבודות בנין בע"מ (12.02.2023) די ב''קצה חוט'' או חשד סביר כדי להתחיל את מרוץ ההתיישנות. ת"א (שלום נצרת) 16438-04-23 בוקי בועז נ'' בן ציון ליכטמן (18.08.2023)',
    'הטעות הנפוצה היא לחשוב שמרוץ ההתיישנות מתחיל רק כאשר התובע יודע את מלוא היקף הנזק או כאשר הוא אוסף את כל הראיות, במקום להבין שדי ב''קצה חוט'' ובנזק שאינו ''מה בכך''.', '["גילוי מאוחר", "מבחן אובייקטיבי", "אדם סביר", "נזק של מה בכך", "קצה חוט", "סעיף 89(2) לפקודת הנזיקין"]'::jsonb, '**וריאציה 1 — נזק של מה בכך:** האם גילוי ''נזק של מה בכך'' מתחיל את מרוץ ההתיישנות? ← לא, רק נזק שאדם סביר היה מגיש בגינו תביעה. ת"א (שלום פ"ת) 20794-11-22 מועצה מקומית ג''לג''וליה נ'' ע.ע. אבו ראס חברה לעבודות בניין ופיתוח בע"מ (19.01.2025)
**וריאציה 2 — מלוא היקף הנזק:** האם יש להמתין לגילוי מלוא היקף הנזק? ← לא, מרוץ ההתיישנות מתחיל עם גילוי הנזק ולא במועד בו קיימת אפשרות לעמוד על מלוא היקפו. ת"א (מחוזי ת"א) 4193-03-22 SPACEGROVE HOLDING LIMITED נ'' י. מנדלברג חב'' לעבודות בנין בע"מ (12.02.2023)
**וריאציה 3 — קצה חוט:** מהו הסטנדרט הנדרש לגילוי? ← די ב''קצה חוט'' או חשד סביר כדי להתחיל את מרוץ ההתיישנות. ת"א (שלום נצרת) 16438-04-23 בוקי בועז נ'' בן ציון ליכטמן (18.08.2023)', 'מבחן הגילוי המאוחר (ס'' 89(2) לפקודת הנזיקין) הוא אובייקטיבי: נזק שאינו ''מה בכך'' ו''קצה חוט'' מספיקים לתחילת מרוץ ההתיישנות.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 89(2)", "ע\"א 165/83 בוכריס נ'' דיור לעולה בע\"מ, פ\"ד לח(4) 554 (1984)", "ע\"א 8172/12 פלוני נ'' אגד-אגודה שיתופית לתחבורה בישראל בע\"מ (18.01.2018)", "ת\"א (שלום פ\"ת) 20794-11-22 מועצה מקומית ג''לג''וליה נ'' ע.ע. אבו ראס חברה לעבודות בניין ופיתוח בע\"מ (19.01.2025)", "ת\"א (מחוזי ת\"א) 4193-03-22 SPACEGROVE HOLDING LIMITED נ'' י. מנדלברג חב'' לעבודות בנין בע\"מ (12.02.2023)", "ת\"א (שלום נצרת) 16438-04-23 בוקי בועז נ'' בן ציון ליכטמן (18.08.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מבחן סובייקטיבי, לפיו מרוץ ההתיישנות יחל רק כאשר התובע ידע בפועל את מלוא היקף הנזק והקשר הסיבתי.', false, 'טענה זו שגויה. הפסיקה קבעה מבחן אובייקטיבי של ''אדם סביר'' ו''קצה חוט'', ואין צורך בידיעה מלאה של מלוא היקף הנזק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'מבחן אובייקטיבי של ''אדם סביר'', לפיו מרוץ ההתיישנות יחל כאשר התגלה נזק שאינו ''נזק של מה בכך'', ואדם סביר היה מגיש בגינו תביעה.', true, 'תשובה זו נכונה. הפסיקה קבעה כי המבחן לגילוי הנזק לצורך סעיף 89(2) לפקודת הנזיקין הוא אובייקטיבי, ודי בגילוי נזק משמעותי שאינו ''נזק של מה בכך'' כדי להתחיל את מרוץ ההתיישנות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מבחן מעורב, לפיו מרוץ ההתיישנות יחל כאשר התובע ידע בפועל על הנזק, ובלבד שאדם סביר היה מגיש תביעה בגינו.', false, 'טענה זו שגויה. המבחן הוא אובייקטיבי בעיקרו, ומתמקד ביכולת הגילוי הסבירה, ולא בידיעה בפועל בלבד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מרוץ ההתיישנות יחל רק כאשר התובע אסף את כל הראיות הדרושות להוכחת תביעתו.', false, 'טענה זו שגויה. הפסיקה קבעה כי אין צורך בידיעה מלאה או באיסוף כל הראיות; די ב''קצה חוט'' או חשד סביר כדי להתחיל את מרוץ ההתיישנות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'התיישנות במקרה של תרמית',
    3, 'יוסי רכש דירה מקבלן ביום 1.1.2010. ביום 1.1.2018 גילה יוסי כי הקבלן הטעה אותו במכוון לגבי גודל הדירה, וכי הדירה קטנה ב-10 מ"ר מהמוצהר. יוסי מעוניין להגיש תביעה נגד הקבלן בגין תרמית. מתי תתיישן תביעתו?', 'שאלה זו עוסקת בכלל ההתיישנות המיוחד החל במקרה של תרמית, כפי שקבוע בסעיף 7 לחוק ההתיישנות. היא מדגישה את ההבחנה בין סעיף 7 (תרמית) לסעיף 8 (התיישנות שלא מדעת), ובפרט את דרישת הידיעה הסובייקטיבית שהייתה קיימת בנוסחו הישן של סעיף 7, הרלוונטי לאירועים שקדמו לתיקון החוק ב-2015.', 'סעיף 7 לחוק ההתיישנות, בנוסחו הישן (הרלוונטי לאירועים שקדמו לתיקון מס'' 5 בשנת 2015), קבע כי "הייתה עילת התובענה תרמית או אונאה מצד הנתבע, תתחיל תקופת ההתיישנות ביום שבו נודעה לתובע התרמית או האונאה". רע"א 6938/19 דני אילני נ'' פייר ברוך (20.08.2020) הפסיקה פירשה סעיף זה כדורש "ידיעה ממשית וסובייקטיבית של אודות התרמית", ואין די בידיעה שהייתה זמינה לו נקט התובע בזהירות סבירה. ת"א (שלום ת"א) 48752-04 טוביאס קאופמן נ'' דורי זאב (07.11.2010) במקרה זה, התרמית נודעה ליוסי ב-1.1.2018. תקופת ההתיישנות לתביעה שאינה במקרקעין היא 7 שנים (סעיף 5 לחוק ההתיישנות). לכן, מרוץ ההתיישנות יחל ב-1.1.2018, והתביעה תתיישן ב-1.1.2025. יש לציין כי סעיף 7 תוקן בשנת 2015, אך התיקון אינו חל רטרואקטיבית על אירועים שקדמו לו. תמ"ש (כלכלית ) 34060-09-15 ר.ר נ'' מ.ר. ז"ל (16.03.2021)',
    'הטעות הנפוצה היא לבלבל בין סעיף 7 (תרמית) לסעיף 8 (התיישנות שלא מדעת) או להחיל את נוסחו החדש של סעיף 7 על אירועים שקדמו לתיקון החוק.', '["התיישנות", "תרמית", "אונאה", "סעיף 7 לחוק ההתיישנות", "ידיעה סובייקטיבית", "תיקון חוק"]'::jsonb, '**וריאציה 1 — תרמית (נוסח ישן):** מתי מתחיל מרוץ ההתיישנות בתביעת תרמית לפי סעיף 7 הישן? ← ביום שבו נודעה לתובע התרמית בפועל (ידיעה סובייקטיבית). רע"א 6938/19 דני אילני נ'' פייר ברוך (20.08.2020)
**וריאציה 2 — תרמית (נוסח חדש):** מתי מתחיל מרוץ ההתיישנות בתביעת תרמית לפי סעיף 7 החדש? ← מרוץ ההתיישנות יושעה כל עוד נמנע התובע מלהגיש תובענה בשל הטעיה ביודעין מצד הנתבע. ע"א 4773/21 פלונית נ'' קופת חולים כללית שרותי בריאות (21.10.2021)
**וריאציה 3 — תחולה רטרואקטיבית:** האם נוסח סעיף 7 החדש חל רטרואקטיבית? ← לא, ככלל, אין תחולה רטרואקטיבית לתיקון סעיף 7. תמ"ש (כלכלית ) 34060-09-15 ר.ר נ'' מ.ר. ז"ל (16.03.2021)', 'תרמית (לפני 2015) ← התיישנות מיום ידיעה סובייקטיבית של התרמית (ס'' 7 ישן). תרמית (אחרי 2015) ← השעיית מרוץ ההתיישנות כל עוד התובע נמנע מהגשה עקב הטעיה ביודעין (ס'' 7 חדש).',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 7", "רע\"א 6938/19 דני אילני נ'' פייר ברוך (20.08.2020)", "ת\"א (שלום ת\"א) 48752-04 טוביאס קאופמן נ'' דורי זאב (07.11.2010)", "תמ\"ש (כלכלית ) 34060-09-15 ר.ר נ'' מ.ר. ז\"ל (16.03.2021)", "ע\"א 4773/21 פלונית נ'' קופת חולים כללית שרותי בריאות (21.10.2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'התביעה התיישנה ביום 1.1.2017, שכן חלפו 7 שנים מיום הרכישה.', false, 'טענה זו שגויה. במקרה של תרמית, מרוץ ההתיישנות מתחיל ביום שבו נודעה התרמית לתובע, ולא ביום האירוע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'התביעה התיישנה ביום 1.1.2025, שכן מרוץ ההתיישנות החל ביום גילוי התרמית.', true, 'תשובה זו נכונה. סעיף 7 לחוק ההתיישנות (בנוסחו הישן, הרלוונטי לאירוע מ-2010) קובע כי במקרה של תרמית, תקופת ההתיישנות תתחיל ביום שבו נודעה התרמית לתובע. התרמית נודעה ב-1.1.2018, ולכן התביעה תתיישן 7 שנים לאחר מכן, ב-1.1.2025.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'התביעה התיישנה ביום 1.1.2020, שכן חלה מגבלת 10 השנים מיום הרכישה.', false, 'טענה זו שגויה. מגבלת 10 השנים חלה על גילוי מאוחר של נזק בנזיקין (סעיף 89(2) לפקודת הנזיקין), ולא על תרמית לפי סעיף 7 לחוק ההתיישנות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'התביעה לא התיישנה, שכן תרמית היא עילה חמורה שאינה מתיישנת לעולם.', false, 'טענה זו שגויה. גם תביעות בגין תרמית כפופות לדיני ההתיישנות, אך עם כללי גילוי מאוחר מיוחדים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השעיית התיישנות לקטינים ופסולי דין',
    4, 'ילד בן 5 נפגע בתאונת דרכים קשה ביום 1.1.2010, ונותר נכה לצמיתות. הוריו לא הגישו תביעה בשמו. ביום 1.1.2023, כשהיה בן 18, החליט הילד להגיש תביעה בעצמו. האם תביעתו התיישנה?', 'שאלה זו עוסקת בכללי השעיית מרוץ ההתיישנות עבור קטינים ופסולי דין, כפי שקבועים בסעיפים 10 ו-11 לחוק ההתיישנות, ובסעיף 10(א) לפקודת הנזיקין. היא מדגישה את ההגנה המיוחדת הניתנת לאוכלוסיות אלו, המאפשרת להן להגיש תביעה גם שנים רבות לאחר אירוע הנזק.', 'סעיף 10 לחוק ההתיישנות קובע כי "בחישוב תקופת ההתיישנות לא יבוא במניין הזמן שבו התובע היה קטין". ת"א (שלום ת"א) 28405-03-11 אלברט מיטרני נ'' מקס פיין (31.10.2011) כלומר, מרוץ ההתיישנות מושעה כל עוד התובע קטין. סעיף 10(2) לחוק ההתיישנות מוסיף וקובע כי "תביעה שהתיישנה תוך תקופת הקטינות, או שהתקופה נסתיימה תוך שנה לאחר מכן, לא תתיישן לפני שעברה שנה אחת מהיום שבו חדל התובע להיות קטין". ת"א (שלום ת"א) 28405-03-11 אלברט מיטרני נ'' מקס פיין (31.10.2011) בנוסף, סעיף 10(א) לפקודת הנזיקין [נוסח חדש] קובע הוראה ספציפית לתביעות נזיקין של קטינים: "תביעת קטין בנזיקין לא תתיישן לפני שימלאו לו 25 שנים". בע"מ 8098/04 פלונית נ'' פלונים (04.11.2004) (הפסיקה מתייחסת לתיקון סעיף 354(א) לחוק העונשין, אך הרציונל דומה). במקרה זה, הילד נפגע ב-1.1.2010 (בהיותו בן 5). מרוץ ההתיישנות הושעה עד הגיעו לבגרות (גיל 18), כלומר עד 1.1.2023. לפי סעיף 10(א) לפקודת הנזיקין, תביעתו לא תתיישן לפני שימלאו לו 25 שנים, כלומר עד 1.1.2030. לכן, תביעתו שהוגשה ב-1.1.2023 לא התיישנה.',
    'הטעות הנפוצה היא לחשב את תקופת ההתיישנות הרגילה (7 שנים) מיום הבגרות, מבלי להתחשב בהוראה המיוחדת שבסעיף 10(א) לפקודת הנזיקין המאריכה את התקופה עד גיל 25.', '["התיישנות קטינים", "השעיית מרוץ התיישנות", "סעיף 10 לחוק ההתיישנות", "סעיף 10(א) לפקודת הנזיקין", "נזקי גוף", "בגרות"]'::jsonb, '**וריאציה 1 — קטין בנזיקין:** מתי מתיישנת תביעת נזיקין של קטין? ← לא לפני שימלאו לו 25 שנים (סעיף 10(א) לפקודת הנזיקין). בע"מ 8098/04 פלונית נ'' פלונים (04.11.2004)
**וריאציה 2 — קטין (כללי):** מתי מתיישנת תביעה כללית של קטין? ← לא לפני שעברה שנה אחת מהיום שבו חדל התובע להיות קטין (סעיף 10(2) לחוק ההתיישנות). ת"א (שלום ת"א) 28405-03-11 אלברט מיטרני נ'' מקס פיין (31.10.2011)
**וריאציה 3 — פסול דין:** מתי מתיישנת תביעה של פסול דין? ← לא יבוא במניין הזמן שבו התובע לא היה מסוגל לדאוג לענייניו מחמת ליקוי נפשי או שכלי, ולא היה עליו אפוטרופוס. ת"א (שלום ת"א) 18007-02-23 פלונית נ'' שירותי בריאות כללית (24.12.2023)', 'התיישנות קטינים: מרוץ מושעה עד גיל 18 (ס'' 10 לחוק ההתיישנות). בנזיקין, לא תתיישן לפני גיל 25 (ס'' 10(א) לפקודת הנזיקין).',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיפים 10, 11", "פקודת הנזיקין [נוסח חדש], סעיף 10(א)", "בע\"מ 8098/04 פלונית נ'' פלונים, נט(3) 111 (04.11.2004)", "ת\"א (שלום ת\"א) 28405-03-11 אלברט מיטרני נ'' מקס פיין (31.10.2011)", "ת\"א (שלום ת\"א) 18007-02-23 פלונית נ'' שירותי בריאות כללית (24.12.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, התביעה התיישנה ביום 1.1.2017, שכן חלפו 7 שנים מיום התאונה.', false, 'טענה זו שגויה. סעיף 10 לחוק ההתיישנות משעה את מרוץ ההתיישנות כל עוד התובע קטין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, התביעה לא התיישנה, שכן מרוץ ההתיישנות הושעה עד הגיעו לבגרות, והוא רשאי להגיש תביעה עד יום הולדתו ה-25.', true, 'תשובה זו נכונה. סעיף 10 לחוק ההתיישנות קובע כי תקופת ההתיישנות לא תבוא במניין הזמן שבו התובע היה קטין. סעיף 10(2) קובע כי התביעה לא תתיישן לפני שעברה שנה אחת מהיום שבו חדל התובע להיות קטין. בנוסף, סעיף 10(א) לפקודת הנזיקין קובע כי תביעת קטין בנזיקין לא תתיישן לפני שימלאו לו 25 שנים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, התביעה התיישנה ביום 1.1.2018, שכן חלפו 7 שנים מיום הגיעו לבגרות.', false, 'טענה זו שגויה. סעיף 10(2) לחוק ההתיישנות קובע כי התביעה לא תתיישן לפני שעברה שנה אחת מהיום שבו חדל התובע להיות קטין, אך סעיף 10(א) לפקודת הנזיקין מאריך זאת עד גיל 25.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, התביעה לא התיישנה, שכן נזקי גוף של קטינים אינם מתיישנים לעולם.', false, 'טענה זו שגויה. גם תביעות של קטינים כפופות לדיני ההתיישנות, אך עם כללי השעיה מיוחדים.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 6, '2023-S-S-Q06';
END
$$;

