-- classifier_note: Board delegation re bond issuance under employee comp plan — securities issuance
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '834a737c-a6a5-4c47-8d51-05ab8f86b441'::uuid;
  v_group_id uuid := '42bca98a-7055-43ad-a502-fd400308c315'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'a42a215c-de29-41cd-96fd-76b997b23120'::uuid;
  v_ang_1 uuid := 'edca9a38-0407-4539-ae62-7ec87a3b3aaf'::uuid;
  v_ang_2 uuid := '8e310b0e-ac54-4f07-a0c4-39967ed23cfc'::uuid;
  v_ang_3 uuid := 'b4a711f1-1638-48d6-994b-4bee824f32fa'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q07';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 7, '2023-S-S-Q07';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'securities_disclosure' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'securities_disclosure', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q07', v_chapter_id, v_subtopic_id, 'דירקטוריון החברה מעוניין להאציל את סמכויותיו להחליט על הנפקה של סדרת איגרות חוב במסגרת תוכנית תגמול לעובדים. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 7}'::jsonb, 'השאלה עוסקת בסמכות הדירקטוריון להאציל את סמכויותיו, ובפרט את הסמכות להחליט על הנפקה של סדרת איגרות חוב במסגרת תוכנית תגמול לעובדים. היא בוחנת את הוראות חוק החברות, התשנ"ט-1999, המבחינות בין סוגי סמכויות שונות וקובעות כללים שונים לאצילתן, תוך שמירה על עקרון הפרדת הסמכויות בין אורגני החברה.', 'הדירקטוריון הוא אחד האורגנים המרכזיים של החברה, ותפקידו להתוות את מדיניות החברה ולפקח על ביצוע תפקידי המנהל הכללי ופעולותיו. חוק החברות, תשנ"ט-1999, סעיף 92(א) בין סמכויותיו של הדירקטוריון נכללת גם הסמכות להחליט על הנפקה של סדרת איגרות חוב (סעיף 92(א)(4) וסעיף 289(א) לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 92(א)(4)
הכלל הוא שסמכויות הדירקטוריון אינן ניתנות לאצילה למנהל הכללי, למעט חריגים מפורשים. חוק החברות, תשנ"ט-1999, סעיף 92(ב) כמו כן, סעיף 112(א) לחוק החברות מונה רשימה של סמכויות שאינן ניתנות לאצילה לוועדת דירקטוריון, ובכלל זה הנפקה או הקצאה של מניות או ניירות ערך המירים למניות, או של סדרת איגרות חוב (סעיף 112(א)(5)). חוק החברות, תשנ"ט-1999, סעיף 112(א)(5)
אולם, סעיף 288(ב) לחוק החברות קובע חריגים לכלל זה, המאפשרים אצילת סמכויות מסוימות. סעיף 288(ב)(1) מתייחס ספציפית למצב שבו מדובר בהנפקה או בהקצאה של ניירות ערך במסגרת תכנית תגמול עובדים או הסכמי העסקה או שכר. במקרה כזה, הסמכות ניתנת לאצילה "לועדת דירקטוריון" בלבד, ובלבד שההנפקה או ההקצאה היא לפי תכנית הכוללת אמות מידה מפורטות, שהתווה ואישר הדירקטוריון. חוק החברות, תשנ"ט-1999, סעיף 288(ב)(1)
לכן, במקרה הנדון, הדירקטוריון יכול להאציל את סמכותו להחליט על הנפקה של סדרת איגרות חוב במסגרת תוכנית תגמול לעובדים, אך ורק לוועדת דירקטוריון, ובתנאים המפורטים בסעיף 288(ב)(1).', 'הטעות הנפוצה היא לבלבל בין הכלל האוסר אצילת סמכויות (סעיפים 92(ב) ו-112(א)) לבין החריגים המפורשים המאפשרים אצילה במקרים ספציפיים (כמו סעיף 288(ב)), או לטעות בזיהוי הגורם שאליו מותרת האצילה בכל חריג.',
    '["אצילת סמכויות", "דירקטוריון", "ועדת דירקטוריון", "הנפקת איגרות חוב", "תוכנית תגמול לעובדים", "חוק החברות", "סמכויות קוגנטיות"]'::jsonb, '**וריאציה 1 — כלל איסור האצילה:** האם הדירקטוריון יכול לאצול את סמכותו להנפיק איגרות חוב למנכ"ל? ← לא, סעיף 92(ב) לחוק החברות אוסר על אצילת סמכויות אלו למנכ"ל, למעט חריגים ספציפיים שאינם רלוונטיים להנפקת סדרת איגרות חוב. חוק החברות, תשנ"ט-1999, סעיף 92(ב)
**וריאציה 2 — חריג לתכנית תגמול:** למי ניתן לאצול סמכות הנפקת ניירות ערך במסגרת תכנית תגמול לעובדים? ← לוועדת דירקטוריון בלבד, ובתנאים מסוימים (סעיף 288(ב)(1) לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 288(ב)(1)
**וריאציה 3 — סמכות הנפקת איגרות חוב:** מי מוסמך להחליט על הנפקת סדרת איגרות חוב? ← הדירקטוריון (סעיף 92(א)(4) וסעיף 289(א) לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 289(א)', 'הדירקטוריון מוסמך להחליט על הנפקת סדרת איגרות חוב (ס'' 92(א)(4), 289(א) לחוק החברות). ככלל, סמכות זו אינה ניתנת לאצילה (ס'' 92(ב), 112(א)(5)), אך במקרה של תכנית תגמול לעובדים, ניתן לאצול אותה לוועדת דירקטוריון בלבד, ובתנאים מסוימים (ס'' 288(ב)(1)).', '["חוק החברות, תשנ\"ט-1999, סעיפים 92, 112, 288, 289", "בג\"ץ 6432/02 איגוד קופות הגמל הענפיות נ'' שר האוצר, נז(3) 918 (28.04.2003)", "יוסף גרוס, חוק החברות (2016), פרק יב: מניות ואגרות חוב של חברה, עמ'' 7", "יוסף גרוס, חוק החברות (2016), פרק כט: הדירקטוריון - תפקידים וסמכויות, עמ'' 8", "נבו - המתמחה, דיני תאגידים (2026), חוק החברות, התשנ\"ט-1999, עמ'' 37, 91"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''securities_disclosure'' | classifier_note: Board delegation re bond issuance under employee comp plan — securities issuance | source_review_note: השאלה עוסקת בדיני חברות, ובפרט בסמכויות דירקטוריון ואצילתן. תחום זה אינו נכלל ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''הליכים'' נבחר כברירת מחדל תחת ''סדר דין אזרחי'' בשל הקשר העקיף להליכים משפטיים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני תאגידים'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'דירקטוריון החברה יוכל להאציל את סמכויותיו לוועדת הדירקטוריון בלבד.', true, 'תשובה זו נכונה. סעיף 112(א)(5) לחוק החברות אוסר על אצילת סמכות הנפקת סדרת איגרות חוב לוועדת דירקטוריון, למעט כמפורט בסעיף 288(ב). סעיף 288(ב)(1) מתיר אצילה לוועדת דירקטוריון בלבד, כאשר מדובר בהנפקה או הקצאה של ניירות ערך במסגרת תכנית תגמול עובדים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'דירקטוריון החברה יוכל להאציל את סמכויותיו לוועדת הדירקטוריון או למנהל הכללי של החברה.', false, 'טענה זו שגויה. סעיף 288(ב)(1) לחוק החברות מתיר אצילה לוועדת דירקטוריון בלבד במקרה של תכנית תגמול לעובדים. אצילה למנהל הכללי מותרת רק במקרה של הקצאת מניות עקב מימוש או המרה של ניירות ערך (סעיף 288(ב)(2)).', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'דירקטוריון החברה יוכל להאציל את סמכויותיו לוועדת הדירקטוריון או למנהל הכללי של החברה או למי שהסמיך לכך.', false, 'טענה זו שגויה. אצילה למנהל הכללי או למי שהמליץ עליו המנהל הכללי מותרת רק במקרה של הקצאת מניות עקב מימוש או המרה של ניירות ערך (סעיף 288(ב)(2)), ולא במקרה של הנפקת סדרת איגרות חוב במסגרת תכנית תגמול לעובדים.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'דירקטוריון החברה לא יוכל להאציל סמכות כאמור.', false, 'טענה זו שגויה. סעיף 288(ב)(1) לחוק החברות קובע חריג מפורש המאפשר אצילת סמכות זו לוועדת דירקטוריון, בתנאים מסוימים.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'אצילת סמכות להקצאת מניות עקב המרה',
    1, 'דירקטוריון החברה מעוניין להאציל את סמכויותיו להקצות מניות עקב מימוש או המרה של ניירות ערך של החברה. מה הדין?', 'שאלה זו בוחנת את האפשרות לאצול סמכויות דירקטוריון להקצאת מניות הנובעת ממימוש או המרה של ניירות ערך. היא מדגישה את ההבחנה בין סוגי האצילה השונים המותרים בחוק החברות, בהתאם לסוג הפעולה התאגידית.', 'סעיף 288(א) לחוק החברות קובע כי הדירקטוריון רשאי להנפיק או להקצות מניות וניירות ערך אחרים, המירים או ניתנים למימוש למניות, עד גבול הון המניות הרשום של החברה. חוק החברות, תשנ"ט-1999, סעיף 288(א) סעיף 288(ב) מפרט את האפשרויות לאצילת סמכות זו. סעיף 288(ב)(2) קובע במפורש כי סמכות הדירקטוריון להקצאת מניות עקב מימוש או המרה של ניירות ערך של החברה ניתנת לאצילה "לועדת דירקטוריון, למנהל הכללי או לממלא תפקיד כאמור (בסעיף זה - המנהל הכללי), או לאדם אחר שהמנהל הכללי המליץ עליו". חוק החברות, תשנ"ט-1999, סעיף 288(ב)(2) חשוב להבחין בין החלטה על הנפקת ניירות ערך המירים למניות לבין החלטה על הקצאת המניות עקב המרה של ניירות ערך. הקצאת מניות עקב המרה היא פעולה נפרדת המחייבת החלטה נפרדת של הדירקטוריון או מי שהוסמך לכך על ידו. ת"א (כלכלית ) 17248-05-19 טכנופלס ונצ''רס בע"מ נ'' Bioville Corporation N.V (02.09.2023)',
    'הטעות הנפוצה היא לבלבל בין סעיף 288(ב)(1) לסעיף 288(ב)(2) לחוק החברות, ולהחיל את כללי האצילה של האחד על השני.', '["אצילת סמכויות", "הקצאת מניות", "ניירות ערך המירים", "דירקטוריון", "מנהל כללי", "ועדת דירקטוריון", "חוק החברות"]'::jsonb, '**וריאציה 1 — אצילה למנכ"ל:** האם ניתן לאצול למנכ"ל סמכות להקצות מניות עקב המרה? ← כן, לפי סעיף 288(ב)(2) לחוק החברות. חוק החברות, תשנ"ט-1999, סעיף 288(ב)(2)
**וריאציה 2 — פעולה נפרדת:** האם הקצאת מניות עקב המרה היא פעולה נפרדת מהנפקת ניירות ערך המירים? ← כן, היא פעולה נפרדת המחייבת החלטה נפרדת. ת"א (כלכלית ) 17248-05-19 טכנופלס ונצ''רס בע"מ נ'' Bioville Corporation N.V (02.09.2023)
**וריאציה 3 — יו"ר דירקטוריון:** האם יו"ר הדירקטוריון מוסמך לבצע הקצאת מניות עקב המרה ללא הסמכה מפורשת? ← לא, בהיעדר הסמכה מפורשת, דירקטור יחיד אינו מוסמך לבצע פעולות אלו. ת"א (כלכלית ) 17248-05-19 טכנופלס ונצ''רס בע"מ נ'' Bioville Corporation N.V (02.09.2023)', 'הקצאת מניות עקב המרה ← ניתנת לאצילה לוועדת דירקטוריון, למנכ"ל או למי שהמליץ עליו המנכ"ל (ס'' 288(ב)(2) לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 288(ב)(2)", "ת\"א (כלכלית ) 17248-05-19 טכנופלס ונצ''רס בע\"מ נ'' Bioville Corporation N.V (02.09.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'דירקטוריון החברה יוכל להאציל את סמכויותיו לוועדת הדירקטוריון בלבד.', false, 'טענה זו שגויה. סעיף 288(ב)(2) לחוק החברות מתיר אצילה גם למנהל הכללי או לאדם אחר שהמנהל הכללי המליץ עליו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'דירקטוריון החברה לא יוכל להאציל סמכות כאמור.', false, 'טענה זו שגויה. סעיף 288(ב)(2) לחוק החברות קובע במפורש כי סמכות זו ניתנת לאצילה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'דירקטוריון החברה יוכל להאציל את סמכויותיו לוועדת הדירקטוריון, למנהל הכללי או לאדם אחר שהמנהל הכללי המליץ עליו.', true, 'תשובה זו נכונה. סעיף 288(ב)(2) לחוק החברות קובע כי סמכות הדירקטוריון להקצות מניות עקב מימוש או המרה של ניירות ערך ניתנת לאצילה לוועדת דירקטוריון, למנהל הכללי או לאדם אחר שהמנהל הכללי המליץ עליו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'דירקטוריון החברה יוכל להאציל את סמכויותיו רק באישור האסיפה הכללית.', false, 'טענה זו שגויה. סעיף 288(ב)(2) לחוק החברות אינו דורש אישור של האסיפה הכללית לאצילת סמכות זו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'סמכויות שאינן ניתנות לאצילה לוועדת דירקטוריון',
    2, 'אילו מבין הסמכויות הבאות של הדירקטוריון אינן ניתנות לאצילה לוועדת דירקטוריון, למעט חריגים מפורשים בחוק?', 'שאלה זו עוסקת בסמכויות הדירקטוריון שאינן ניתנות לאצילה לוועדות דירקטוריון, כפי שנקבעו בסעיף 112 לחוק החברות. היא מדגישה את חשיבותן של סמכויות אלו, הנחשבות לליבת תפקידו של הדירקטוריון כגוף המתווה מדיניות ומפקח.', 'סעיף 112(א) לחוק החברות מונה רשימה של נושאים שבהם הדירקטוריון אינו רשאי להאציל מסמכויותיו לוועדת דירקטוריון. בין היתר, נכללים ברשימה זו: קביעת מדיניות כללית לחברה (סעיף 112(א)(1)), חלוקה (סעיף 112(א)(2)), קביעת עמדת הדירקטוריון בעניין הטעון אישור האסיפה הכללית (סעיף 112(א)(3)), מינוי דירקטורים (סעיף 112(א)(4)), הנפקה או הקצאה של מניות או ניירות ערך המירים (למעט חריגים בסעיף 288(ב)) (סעיף 112(א)(5)), אישור דוחות כספיים (סעיף 112(א)(6)), ואישור דירקטוריון לעסקאות ופעולות הקשורות בעסקאות בעלי עניין (סעיף 112(א)(7)). חוק החברות, תשנ"ט-1999, סעיף 112(א) הוראות אלו הן קוגנטיות, כלומר, החברה אינה יכולה להתנות עליהן בתקנונה. חוק החברות, תשנ"ט-1999, סעיף 112(ב)',
    'הטעות הנפוצה היא לחשוב שכל סמכויות הדירקטוריון ניתנות לאצילה לוועדות, או לבלבל בין סמכויות שאינן ניתנות לאצילה כלל לבין סמכויות שניתנות לאצילה לוועדה לצורך המלצה בלבד.', '["אצילת סמכויות", "ועדת דירקטוריון", "סמכויות קוגנטיות", "מדיניות חברה", "חלוקה", "אישור דוחות כספיים", "חוק החברות"]'::jsonb, '**וריאציה 1 — סמכויות לא ניתנות לאצילה:** אילו סמכויות דירקטוריון אינן ניתנות לאצילה לוועדה? ← קביעת מדיניות כללית, חלוקה, אישור דוחות כספיים ועוד (סעיף 112(א) לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 112(א)
**וריאציה 2 — אצילה להמלצה:** האם ניתן להקים ועדה לנושאים אלו לצורך המלצה בלבד? ← כן, הדירקטוריון רשאי להקים ועדות בנושאים אלו לשם המלצה בלבד (סעיף 112(ג) לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 112(ג)
**וריאציה 3 — קוגנטיות:** האם ניתן להתנות בתקנון על איסור האצילה? ← לא, החברה אינה רשאית להתנות בתקנונה על הוראות סעיף 112(א) (סעיף 112(ב) לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 112(ב)', 'סמכויות ליבה של הדירקטוריון (כגון קביעת מדיניות כללית, חלוקה, אישור דוחות כספיים) אינן ניתנות לאצילה לוועדת דירקטוריון (ס'' 112(א) לחוק החברות), אך ניתן להקים ועדות להמלצה בלבד.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 112", "יוסף גרוס, חוק החברות (2016), פרק כט: הדירקטוריון - תפקידים וסמכויות, עמ'' 8"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'קביעת מדיניות כללית לחברה.', true, 'תשובה זו נכונה. סעיף 112(א)(1) לחוק החברות קובע כי קביעת מדיניות כללית לחברה אינה ניתנת לאצילה לוועדת דירקטוריון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'קביעת המבנה הארגוני ומדיניות השכר.', false, 'טענה זו שגויה. סעיף 92(א)(3) לחוק החברות קובע כי הדירקטוריון יקבע את המבנה הארגוני ואת מדיניות השכר והתגמול, אך סעיף 112(א) אינו אוסר על אצילת סמכות זו לוועדת דירקטוריון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מינוי המנהל הכללי.', false, 'טענה זו שגויה. סעיף 92(א)(7) לחוק החברות קובע כי הדירקטוריון ימנה ויפטר את המנהל הכללי, אך סעיף 112(א) אינו אוסר על אצילת סמכות זו לוועדת דירקטוריון (סעיף 112(א)(4) מתייחס למינוי דירקטורים).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'בדיקת מצבה הכספי של החברה.', false, 'טענה זו שגויה. סעיף 92(א)(2) לחוק החברות קובע כי הדירקטוריון יבדוק את מצבה הכספי של החברה, אך סעיף 112(א) אינו אוסר על אצילת סמכות זו לוועדת דירקטוריון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'נטילת סמכויות המנכ"ל על ידי הדירקטוריון',
    3, 'באילו נסיבות רשאי הדירקטוריון ליטול לעצמו סמכויות הנתונות למנהל הכללי?', 'שאלה זו בוחנת את היחסים המורכבים בין הדירקטוריון למנהל הכללי בחברה, ובפרט את המקרים שבהם הדירקטוריון רשאי ליטול לעצמו סמכויות הנתונות למנהל הכללי. היא מדגישה את ההבחנה בין נטילת סמכויות מכוח הוראה בתקנון לבין נטילת סמכויות במקרה של אי-ציות להוראה ספציפית.', 'חוק החברות מבקש לשמור על הפרדה בין קביעת המדיניות (הנתונה לדירקטוריון) לבין הביצוע השוטף (הנתון למנהל הכללי). בג"ץ 6432/02 איגוד קופות הגמל הענפיות נ'' שר האוצר, נז(3) 918 (28.04.2003) עם זאת, קיימים מקרים חריגים בהם הדירקטוריון רשאי ליטול לעצמו סמכויות של המנהל הכללי. סעיף 50(א) לחוק החברות מאפשר לחברה לקבוע בתקנונה הוראה לפיה סמכויות הנתונות למנהל הכללי יועברו לסמכות הדירקטוריון, לעניין מסוים או לפרק זמן מסוים. חוק החברות, תשנ"ט-1999, סעיף 50(א) בנוסף, סעיף 51 לחוק החברות קובע הסדר חריג ומיוחד: "דירקטוריון רשאי להורות למנהל הכללי כיצד לפעול לעניין מסוים; לא קיים המנהל הכללי את ההוראה, רשאי הדירקטוריון להפעיל את הסמכות הנדרשת לביצוע ההוראה במקומו, אף אם לא נקבעה לכך הוראה בתקנון". חוק החברות, תשנ"ט-1999, סעיף 51 הוראה זו נועדה לפתור בעיות מעשיות ולאפשר לדירקטוריון להוציא את סמכותו מן הכוח אל הפועל במקרה של אי-ציות המנכ"ל. פ"ה (אזורי ת"א) 39034-04-21 החברה הכלכלית של לשכת עורכי הדין בע"מ - עו"ד פרי כהן (20.05.2025)',
    'הטעות הנפוצה היא לחשוב שהדירקטוריון יכול ליטול סמכויות מהמנכ"ל רק אם הדבר קבוע בתקנון, מבלי להכיר את החריג שבסעיף 51 לחוק החברות.', '["נטילת סמכויות", "מנהל כללי", "דירקטוריון", "הפרדת סמכויות", "סעיף 50 לחוק החברות", "סעיף 51 לחוק החברות"]'::jsonb, '**וריאציה 1 — אי-ציות המנכ"ל:** האם הדירקטוריון יכול ליטול סמכות אם המנכ"ל לא קיים הוראה ספציפית? ← כן, גם ללא הוראה בתקנון (סעיף 51 לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 51
**וריאציה 2 — הוראה בתקנון:** האם ניתן לקבוע בתקנון שהדירקטוריון יטול סמכויות מהמנכ"ל? ← כן, לעניין מסוים או לפרק זמן מסוים (סעיף 50(א) לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 50(א)
**וריאציה 3 — נבצרות המנכ"ל:** מה קורה אם נבצר מהמנכ"ל למלא את תפקידו? ← הדירקטוריון רשאי להפעיל את סמכויותיו במקומו (סעיף 52(ב) לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 52(ב)', 'הדירקטוריון רשאי ליטול סמכויות מהמנכ"ל אם נקבע בתקנון (ס'' 50(א)) או אם המנכ"ל לא קיים הוראה ספציפית (ס'' 51).',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 50(א), 51, 52(ב)", "בג\"ץ 6432/02 איגוד קופות הגמל הענפיות נ'' שר האוצר, נז(3) 918 (28.04.2003)", "פ\"ה (אזורי ת\"א) 39034-04-21 החברה הכלכלית של לשכת עורכי הדין בע\"מ - עו\"ד פרי כהן (20.05.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'רק אם נקבעה לכך הוראה מפורשת בתקנון החברה.', false, 'טענה זו שגויה. סעיף 51 לחוק החברות מאפשר לדירקטוריון ליטול סמכויות המנכ"ל גם ללא הוראה בתקנון, במקרה של אי-ציות להוראה ספציפית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'אם המנהל הכללי לא קיים הוראה ספציפית של הדירקטוריון, גם אם לא נקבעה לכך הוראה בתקנון.', true, 'תשובה זו נכונה. סעיף 51 לחוק החברות קובע כי אם המנהל הכללי לא קיים הוראה ספציפית של הדירקטוריון, רשאי הדירקטוריון להפעיל את הסמכות במקומו, אף אם לא נקבעה לכך הוראה בתקנון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'בכל עת, לפי שיקול דעתו הבלעדי של הדירקטוריון, ללא צורך בהוראה בתקנון או בהפרה מצד המנכ"ל.', false, 'טענה זו שגויה. חוק החברות שומר על הפרדה בין סמכויות הדירקטוריון למנכ"ל, והדירקטוריון אינו יכול ליטול את סמכויות המנכ"ל באופן שרירותי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'רק אם נבצר מהמנהל הכללי למלא את תפקידו, וזאת באישור האסיפה הכללית.', false, 'טענה זו שגויה. סעיף 52(ב) לחוק החברות עוסק במצב שבו נבצר מהמנכ"ל למלא את תפקידו, ומאפשר לדירקטוריון להפעיל את סמכויותיו במקומו, ללא צורך באישור האסיפה הכללית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סמכות שיורית של הדירקטוריון',
    4, 'מהו הכלל לגבי הפעלת סמכות של החברה שלא הוקנתה בחוק או בתקנון לאורגן אחר?', 'שאלה זו עוסקת בסמכות השיורית של הדירקטוריון, כפי שקבועה בסעיף 49 לחוק החברות. היא מדגישה את תפקידו של הדירקטוריון כגוף המרכזי המפעיל את סמכויות החברה כאשר אין הוראה מפורשת אחרת בחוק או בתקנון.', 'סעיף 49 לחוק החברות קובע את הסמכות השיורית של הדירקטוריון: "סמכות של החברה שלא הוקנתה בחוק או בתקנון לאורגן אחר, רשאי הדירקטוריון להפעילה". חוק החברות, תשנ"ט-1999, סעיף 49 כלומר, הדירקטוריון הוא ברירת המחדל להפעלת סמכויות החברה כאשר אין אורגן אחר שהוסמך לכך במפורש. ע"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע"מ (18.08.2022) לעומת זאת, למנהל הכללי נתונות כל סמכויות הניהול והביצוע השיוריות, שלא הוקנו בחוק או בתקנון לאורגן אחר. חוק החברות, תשנ"ט-1999, סעיף 121(א) האסיפה הכללית מפעילה סמכות שיורית רק במקרים שבהם נבצר מהדירקטוריון להפעיל את סמכויותיו והפעלתן חיונית לניהולה התקין של החברה. חוק החברות, תשנ"ט-1999, סעיף 52(א)',
    'הטעות הנפוצה היא לבלבל בין הסמכות השיורית הכללית של הדירקטוריון לבין הסמכות השיורית של המנהל הכללי (סמכויות ניהול וביצוע) או הסמכות השיורית של האסיפה הכללית (במקרה של נבצרות הדירקטוריון).', '["סמכות שיורית", "דירקטוריון", "מנהל כללי", "אסיפה כללית", "חלוקת סמכויות", "חוק החברות"]'::jsonb, '**וריאציה 1 — סמכות שיורית כללית:** למי נתונה סמכות של החברה שלא הוקנתה לאורגן אחר? ← לדירקטוריון (סעיף 49 לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 49
**וריאציה 2 — סמכות שיורית של המנכ"ל:** אילו סמכויות שיוריות נתונות למנכ"ל? ← כל סמכויות הניהול והביצוע שלא הוקנו לאורגן אחר (סעיף 121(א) לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 121(א)
**וריאציה 3 — סמכות שיורית של האסיפה הכללית:** מתי האסיפה הכללית מפעילה סמכות שיורית? ← כאשר נבצר מהדירקטוריון להפעיל את סמכויותיו והפעלתן חיונית לניהול התקין של החברה (סעיף 52(א) לחוק החברות). חוק החברות, תשנ"ט-1999, סעיף 52(א)', 'הסמכות השיורית הכללית של החברה נתונה לדירקטוריון (ס'' 49 לחוק החברות). למנכ"ל סמכויות ניהול וביצוע שיוריות (ס'' 121(א)). האסיפה הכללית מפעילה סמכות שיורית רק במקרה של נבצרות הדירקטוריון (ס'' 52(א)).',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 49, 52(א), 121(א)", "בג\"ץ 6432/02 איגוד קופות הגמל הענפיות נ'' שר האוצר, נז(3) 918 (28.04.2003)", "ע\"א 94/20 טוביה לוסקין נ'' גבעות עולם נפט בע\"מ (18.08.2022)", "ע\"א 3998/07 צ. בכור ניהול ואחזקות בע\"מ נ'' ממשל ירושלים התשנ\"ה בע\"מ (06.01.2011)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'האסיפה הכללית רשאית להפעילה, שכן היא הגוף העליון בחברה.', false, 'טענה זו שגויה. הסמכות השיורית הראשונית נתונה לדירקטוריון, והאסיפה הכללית מפעילה סמכות שיורית רק במקרים של נבצרות הדירקטוריון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'הדירקטוריון רשאי להפעילה.', true, 'תשובה זו נכונה. סעיף 49 לחוק החברות קובע כי סמכות של החברה שלא הוקנתה בחוק או בתקנון לאורגן אחר, רשאי הדירקטוריון להפעילה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'המנהל הכללי רשאי להפעילה, שכן הוא אחראי על הניהול השוטף.', false, 'טענה זו שגויה. למנהל הכללי נתונות סמכויות הניהול והביצוע השיוריות, אך לא הסמכות השיורית הכללית של החברה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'החברה אינה רשאית להפעיל סמכות שלא הוקנתה במפורש לאף אורגן.', false, 'טענה זו שגויה. סעיף 49 לחוק החברות קובע מנגנון להפעלת סמכויות כאלו על ידי הדירקטוריון.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 7, '2023-S-S-Q07';
END
$$;

