DO $$
DECLARE
  v_sq_id uuid := 'cf3ab858-828b-4aed-b248-ed381f2f3971'::uuid;
  v_group_id uuid := '27ce24fd-eabf-4174-875f-fd951be355a6'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'c59726fc-9a80-4900-88fe-f8bd2607ae9f'::uuid;
  v_ang_1 uuid := 'b3f7cba6-c92b-4759-a9fd-0ffa8a2603c5'::uuid;
  v_ang_2 uuid := 'abe933bf-acae-4b90-b935-dfce2e9d198e'::uuid;
  v_ang_3 uuid := 'f3ddd6eb-1b3f-47b7-8855-061e41b65cff'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q08';
