  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q08', v_chapter_id, v_subtopic_id, 'בתקנון החברה הציבורית "החברמנים בע"מ" ישנה הוראה הפוטרת את נושאי המשרה שלה מאחריות בגין הפרת חובת הזהירות כלפיה. אחד הנושים של החברה מעוניין להגיש תובענה נגד הדירקטורים של החברה על רקע חלוקה אסורה לטענתו. מה על החברה לעשות כדי שהפטור יגונן על הדירקטורים מפני חבות?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 8}'::jsonb, 'השאלה עוסקת בסוגיית הפטור מאחריות של דירקטורים בחברה ציבורית, ובפרט בהקשר של חלוקה אסורה. היא בוחנת את הוראות סעיף 259 לחוק החברות, התשנ"ט-1999, הקובע את הכללים למתן פטור מראש בגין הפרת חובת זהירות, ואת החריג המפורש האוסר מתן פטור כזה כאשר מדובר בחלוקה אסורה.', 'חוק החברות, תשנ"ט-1999, מבחין בין חובת אמונים לחובת זהירות של נושאי משרה. סעיף 258(א) לחוק קובע כי חברה אינה רשאית לפטור נושא משרה מאחריותו בשל הפרת חובת האמונים כלפיה. חוק החברות, תשנ"ט-1999, סעיף 258(א) לעומת זאת, סעיף 258(ב) לחוק קובע כי חברה רשאית לפטור נושא משרה מאחריותו בשל הפרת חובת הזהירות כלפיה, אך זאת "בהתאם לקבוע בפרק זה בלבד". חוק החברות, תשנ"ט-1999, סעיף 258(ב)
ההוראה המרכזית לעניין פטור בגין הפרת חובת זהירות היא סעיף 259 לחוק. סעיף 259(א) קובע כי "חברה רשאית לפטור, מראש, נושא משרה בה מאחריותו, כולה או מקצתה, בשל נזק עקב הפרת חובת הזהירות כלפיה, אם נקבעה הוראה לכך בתקנון". חוק החברות, תשנ"ט-1999, סעיף 259(א) הוראה זו מאפשרת לחברה להגן על נושאי משרה מפני תביעות בגין רשלנות גרידא, במטרה לעודד אותם ליטול סיכונים עסקיים סבירים לטובת החברה. צפורה כהן, נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023) | הגבלת הפטור לפיצויים
אולם, סעיף 259(ב) לחוק קובע חריג מפורש וקוגנטי לכלל זה: "על אף הוראות סעיף קטן (א), חברה אינה רשאית לפטור מראש דירקטור מאחריותו כלפיה עקב הפרת חובת הזהירות בחלוקה". חוק החברות, תשנ"ט-1999, סעיף 259(ב) איסור זה נובע מהחשיבות הרבה של שמירת הון החברה והגנה על נושיה, שכן חלוקה אסורה פוגעת ישירות בכרית הביטחון של הנושים. זוהר גושן אסף אקשטיין, דיני חברות (2023) | אחריות דירקטורים לחלוקה אסורה
במקרה הנדון, הנושה מעוניין להגיש תובענה נגד הדירקטורים על רקע חלוקה אסורה. למרות שבתקנון החברה קיימת הוראה הפוטרת נושאי משרה מאחריות בגין הפרת חובת הזהירות, הוראה זו אינה תקפה לעניין חלוקה אסורה, בהתאם לסעיף 259(ב) לחוק. לכן, הדירקטורים אינם יכולים לזכות בפטור בנסיבות אלו.
', 'הטעות הנפוצה היא להתעלם מהחריג המפורש שבסעיף 259(ב) לחוק החברות, המונע מתן פטור מראש לדירקטורים בגין הפרת חובת הזהירות בחלוקה אסורה, ולחשוב שהוראה כללית בתקנון מספיקה כדי להגן עליהם.',
    '["פטור מראש", "חלוקה אסורה", "חובת זהירות", "אחריות דירקטורים", "חוק החברות", "קוגנטיות", "הגנה על נושים"]'::jsonb, '**וריאציה 1 — איסור מפורש:** האם חברה רשאית לפטור דירקטור מראש מאחריות בחלוקה אסורה? ← לא, סעיף 259(ב) לחוק החברות אוסר זאת במפורש. חוק החברות, תשנ"ט-1999, סעיף 259(ב)
**וריאציה 2 — רציונל האיסור:** מהי הסיבה לאיסור מתן פטור בחלוקה אסורה? ← חלוקה אסורה פוגעת בנושים, ולכן אין מקום לוותר על כספים המגיעים לחברה ומשמשים ככרית ביטחון לנושים. זוהר גושן אסף אקשטיין, דיני חברות (2023) | אחריות דירקטורים לחלוקה אסורה
**וריאציה 3 — אחריות דירקטורים לחלוקה אסורה:** מהי אחריות דירקטורים לחלוקה אסורה? ← חזקה שהם הפרו את חובת הזהירות או האמונים, אלא אם יוכיחו את אחד החריגים שבסעיף 311 לחוק החברות. חוק החברות, תשנ"ט-1999, סעיף 311', 'חברה אינה רשאית לפטור מראש דירקטור מאחריותו בגין הפרת חובת הזהירות בחלוקה אסורה (ס'' 259(ב) לחוק החברות), שכן חלוקה כזו פוגעת בנושים.', '["חוק החברות, תשנ\"ט-1999, סעיפים 258, 259, 311", "ת\"א (כלכלית ) 30851-01-16 חבס השקעות (1960) בע\"מ נ'' ברוך חבס ייזום (2005) בע\"מ (30.07.2020)", "צפורה כהן, נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023), פרק רביעי סמכות לפטור מאחריות בגין הפרת חובת זהירות, עמ'' 12", "זוהר גושן אסף אקשטיין, דיני חברות (2023), פרק י הון החברה ושמירתו, עמ'' 13, 17"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''fiduciary_duties'' | classifier_note: Articles exempting officers from breach-of-care; unlawful distribution; creditor suing directors | source_review_note: השאלה עוסקת בדיני חברות, ובפרט בפטור ושיפוי נושאי משרה. תחום זה אינו נכלל ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''הליכים'' נבחר כברירת מחדל תחת ''סדר דין אזרחי'' בשל הקשר העקיף להליכים משפטיים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני תאגידים'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'על החברה לתקן את מדיניות התגמול של החברה כך שהיא תכלול הסדר לעניין פטור.', false, 'טענה זו שגויה. סעיף 259(ב) לחוק החברות אוסר במפורש על מתן פטור מראש לדירקטורים בגין הפרת חובת הזהירות בחלוקה אסורה, ללא קשר למדיניות התגמול.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על החברה לקבל החלטה בדירקטוריון החברה, וכן לתקן את מדיניות התגמול של החברה כך שהיא תכלול הסדר לעניין פטור.', false, 'טענה זו שגויה. גם אם הדירקטוריון יקבל החלטה ויתקן את מדיניות התגמול, החוק אוסר על מתן פטור מראש לדירקטורים בגין הפרת חובת הזהירות בחלוקה אסורה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על החברה לקבל החלטה בדירקטוריון החברה לתקן את מדיניות התגמול של החברה כך שהיא תכלול הסדר לעניין פטור, וכן לקבל אישור של ועדת תגמול ודירקטוריון החברה.', false, 'טענה זו שגויה. גם אישורים נוספים של ועדת תגמול ודירקטוריון לא יכשירו פטור מראש בגין חלוקה אסורה, שכן החוק אוסר זאת באופן קוגנטי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'הדירקטורים אינם יכולים לזכות בפטור בנסיבות המתוארות בשאלה.', true, 'תשובה זו נכונה. סעיף 259(ב) לחוק החברות קובע במפורש כי "על אף הוראות סעיף קטן (א), חברה אינה רשאית לפטור מראש דירקטור מאחריותו כלפיה עקב הפרת חובת הזהירות בחלוקה".', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פטור בדיעבד מול פטור מראש',
    1, 'חברה מעוניינת להעניק פטור בדיעבד לנושא משרה בה בגין הפרת חובת זהירות שנעשתה בעבר. האם החברה רשאית לעשות כן?', 'שאלה זו בוחנת את ההבחנה הקריטית בין פטור מראש לפטור בדיעבד לנושאי משרה בחברה בגין הפרת חובת זהירות. היא מדגישה את לשונו המפורשת של סעיף 259(א) לחוק החברות, המאפשר פטור ''מראש'' בלבד, ואת הפרשנות המשפטית הרואה בכך הסדר שלילי המונע פטור בדיעבד.', 'סעיף 259(א) לחוק החברות, תשנ"ט-1999, קובע כי "חברה רשאית לפטור, מראש, נושא משרה בה מאחריותו, כולה או מקצתה, בשל נזק עקב הפרת חובת הזהירות כלפיה, אם נקבעה הוראה לכך בתקנון". חוק החברות, תשנ"ט-1999, סעיף 259(א) לשון החוק, המדגישה את המילים "מראש", פורשה בפסיקה ובספרות המשפטית כהסדר שלילי, לפיו חברה אינה רשאית להעניק פטור בדיעבד לנושא משרה בגין הפרת חובת זהירות. רע"א 5296/13 יוסי אנטורג נ'' יעקב שטבינסקי (24.12.2013) צפורה כהן, נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023) | פטור בדיעבד - האם אפשרי? הרציונל לכך הוא שתכלית הפטור היא לעודד נושאי משרה ליטול סיכונים עסקיים סבירים לטובת החברה, וזאת באמצעות הגנה מפני תביעות עתידיות, ולא לשחרר אותם מאחריות למעשים שכבר נעשו. רע"א 5296/13 יוסי אנטורג נ'' יעקב שטבינסקי (24.12.2013) צפורה כהן, נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023) | פטור בדיעבד - האם אפשרי? יש להבחין בין פטור לבין שיפוי, שכן שיפוי יכול להינתן גם בדיעבד, בהתאם לסעיף 260(ב)(2) לחוק החברות. חוק החברות, תשנ"ט-1999, סעיף 260(ב)(2)',
    'הטעות הנפוצה היא לבלבל בין פטור לשיפוי, או לחשוב שניתן להעניק פטור בדיעבד בדומה לשיפוי, למרות לשונו המפורשת של החוק.', '["פטור מראש", "פטור בדיעבד", "חובת זהירות", "חוק החברות", "שיפוי", "הסדר שלילי"]'::jsonb, '**וריאציה 1 — לשון החוק:** האם סעיף 259(א) לחוק החברות מתיר פטור בדיעבד? ← לא, הסעיף מתיר פטור ''מראש'' בלבד. חוק החברות, תשנ"ט-1999, סעיף 259(א)
**וריאציה 2 — רציונל הפטור:** מהי תכלית הפטור מראש? ← לעודד נושאי משרה ליטול סיכונים עסקיים סבירים לטובת החברה, תוך צפייה פני עתיד. רע"א 5296/13 יוסי אנטורג נ'' יעקב שטבינסקי (24.12.2013)
**וריאציה 3 — שיפוי בדיעבד:** האם שיפוי יכול להינתן בדיעבד? ← כן, סעיף 260(ב)(2) לחוק החברות מתיר זאת. חוק החברות, תשנ"ט-1999, סעיף 260(ב)(2)', 'פטור לנושא משרה בגין הפרת חובת זהירות אפשרי רק ''מראש'' (ס'' 259(א) לחוק החברות), ולא בדיעבד. שיפוי, לעומת זאת, יכול להינתן גם בדיעבד (ס'' 260(ב)(2)).',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 259(א), 260(ב)(2)", "רע\"א 5296/13 יוסי אנטורג נ'' יעקב שטבינסקי (24.12.2013)", "צפורה כהן, נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023), פרק רביעי סמכות לפטור מאחריות בגין הפרת חובת זהירות, עמ'' 28"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, החברה רשאית להעניק פטור בדיעבד, ובלבד שהדבר אושר על ידי האסיפה הכללית.', false, 'טענה זו שגויה. סעיף 259(א) לחוק החברות מתיר פטור ''מראש'' בלבד, והפסיקה והספרות המשפטית מפרשות זאת כהסדר שלילי המונע פטור בדיעבד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, החברה אינה רשאית להעניק פטור בדיעבד לנושא משרה בגין הפרת חובת זהירות, שכן החוק מתיר פטור מראש בלבד.', true, 'תשובה זו נכונה. סעיף 259(א) לחוק החברות קובע כי חברה רשאית לפטור ''מראש'' נושא משרה מאחריותו. הפסיקה והספרות מפרשות זאת כהסדר שלילי, לפיו לא ניתן להעניק פטור בדיעבד.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, החברה רשאית להעניק פטור בדיעבד, אך רק אם נושא המשרה פעל בתום לב והיה לו יסוד סביר להניח שהפעולה לא תפגע בטובת החברה.', false, 'טענה זו שגויה. תנאים אלו רלוונטיים לביטוח אחריות בגין הפרת חובת אמונים (סעיף 261(2) לחוק החברות), ולא למתן פטור בדיעבד בגין הפרת חובת זהירות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן מדובר בחברה פרטית, שאז אין מניעה למתן פטור בדיעבד.', false, 'טענה זו שגויה. סעיף 259(א) לחוק החברות אינו מבחין בין חברה ציבורית לפרטית לעניין זה, והאיסור על פטור בדיעבד חל על כלל החברות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'כלל שיקול הדעת העסקי בחלוקה אסורה',
    2, 'האם כלל שיקול הדעת העסקי יכול להגן על דירקטורים מפני אחריות בגין חלוקה אסורה?', 'שאלה זו בוחנת את גבולות תחולתו של כלל שיקול הדעת העסקי, ובפרט את העיקרון לפיו כלל זה אינו מגן על דירקטורים שהפרו הוראה חוקית מפורשת. היא מדגישה כי חלוקה אסורה, המהווה הפרת חובה סטטוטורית, אינה יכולה להיות מוכשרת באמצעות טענת שיקול דעת עסקי.', 'כלל שיקול הדעת העסקי, שאומץ כהלכה מחייבת, קובע כי בית המשפט לא יבחן החלטות עסקיות לגופן כל עוד נושאי המשרה קיבלו אותן באופן מיודע, בהיעדר ניגוד עניינים ובתום לב, היינו לטובתה של החברה. ת"א (כלכלית ) 30851-01-16 חבס השקעות (1960) בע"מ נ'' ברוך חבס ייזום (2005) בע"מ (30.07.2020) אולם, הפסיקה קבעה כי כלל זה אינו יכול להגן על דירקטורים שהפרו הוראה חוקית. תנ"ג (כלכלית ) 47621-07-16 אמוץ חורב נ'' בי קומיוניקיישנס בע"מ (18.07.2019) חלוקה אסורה, כהגדרתה בחוק החברות, מהווה הפרה של חובה חוקית, ולכן כלל שיקול הדעת העסקי אינו יכול להכשיר אותה. תנ"ג (כלכלית ) 47621-07-16 אמוץ חורב נ'' בי קומיוניקיישנס בע"מ (18.07.2019) זוהר גושן אסף אקשטיין, דיני חברות (2023) | אחריות דירקטורים לחלוקה אסורה סעיף 311 לחוק החברות קובע חזקה סטטוטורית לפיה דירקטורים שאישרו חלוקה אסורה, הפרו את חובת הזהירות או חובת האמונים שלהם. חוק החברות, תשנ"ט-1999, סעיף 311',
    'הטעות הנפוצה היא להרחיב את תחולת כלל שיקול הדעת העסקי גם למקרים של הפרת חוק מפורשת, מבלי להבין שכלל זה מגן רק על החלטות עסקיות שנעשו במסגרת החוק.', '["כלל שיקול הדעת העסקי", "חלוקה אסורה", "אחריות דירקטורים", "הפרת חובה חוקית", "חובת זהירות", "חובת אמונים", "חוק החברות"]'::jsonb, '**וריאציה 1 — גבולות הכלל:** האם כלל שיקול הדעת העסקי מגן מפני הפרת חוק? ← לא, הכלל אינו יכול להגן על דירקטורים שהפרו הוראה חוקית. תנ"ג (כלכלית ) 47621-07-16 אמוץ חורב נ'' בי קומיוניקיישנס בע"מ (18.07.2019)
**וריאציה 2 — חלוקה אסורה:** האם חלוקה אסורה היא הפרת חוק? ← כן, חלוקה אסורה היא הפרת חובה חוקית המוטלת על דירקטורים. חוק החברות, תשנ"ט-1999, סעיף 311
**וריאציה 3 — רציונל הכלל:** מהי מטרת כלל שיקול הדעת העסקי? ← להגן על דירקטורים מפני סיכונים עסקיים שנטלו בתום לב, בהיעדר ניגוד עניינים ובאופן מיודע. תנ"ג (כלכלית ) 47621-07-16 אמוץ חורב נ'' בי קומיוניקיישנס בע"מ (18.07.2019)', 'כלל שיקול הדעת העסקי אינו מגן על דירקטורים שהפרו הוראה חוקית, כגון ביצוע חלוקה אסורה (ס'' 311 לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 311", "ת\"א (כלכלית ) 30851-01-16 חבס השקעות (1960) בע\"מ נ'' ברוך חבס ייזום (2005) בע\"מ (30.07.2020)", "תנ\"ג (כלכלית ) 47621-07-16 אמוץ חורב נ'' בי קומיוניקיישנס בע\"מ (18.07.2019)", "זוהר גושן אסף אקשטיין, דיני חברות (2023), פרק י הון החברה ושמירתו, עמ'' 17"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, אם הדירקטורים פעלו בתום לב, בהיעדר ניגוד עניינים ובאופן מיודע.', false, 'טענה זו שגויה. כלל שיקול הדעת העסקי אינו חל כאשר הדירקטורים הפרו הוראה חוקית מפורשת, כגון ביצוע חלוקה אסורה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, כלל שיקול הדעת העסקי אינו יכול להגן על דירקטורים שהפרו הוראה חוקית, וחלוקה אסורה אינה הופכת למותרת בגלל הפעלת שיקול דעת עסקי.', true, 'תשובה זו נכונה. הפסיקה קבעה כי כלל שיקול הדעת העסקי אינו מגן על דירקטורים שהפרו הוראה חוקית, וחלוקה אסורה היא הפרה כזו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, אך רק אם החלוקה האסורה לא גרמה נזק לחברה ולא הופקה ממנה טובת הנאה אישית על ידי הדירקטורים.', false, 'טענה זו שגויה. גם אם לא נגרם נזק או לא הופקה טובת הנאה, עצם ביצוע חלוקה אסורה מהווה הפרת חובה חוקית שאינה מכוסה על ידי כלל שיקול הדעת העסקי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, אלא אם כן הדירקטורים קיבלו אישור מבית המשפט לחלוקה, שאז היא הופכת למותרת.', false, 'טענה זו שגויה. אישור בית המשפט הופך חלוקה שאינה עומדת במבחן הרווח למותרת (סעיף 303 לחוק החברות), אך אינו מכשיר חלוקה אסורה שנעשתה ללא אישור כזה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פטור מראש בחברה לתועלת הציבור',
    3, 'האם חברה לתועלת הציבור (חל"צ) רשאית לפטור מראש נושא משרה בה מאחריותו בגין הפרת חובת זהירות כלפיה?', 'שאלה זו עוסקת בחריג לכלל מתן הפטור לנושאי משרה, החל על חברות לתועלת הציבור (חל"צ). היא מדגישה את ההגבלה המיוחדת המוטלת על חל"צ, השוללת מהן את היכולת לפטור נושאי משרה מאחריות, וזאת בשל אופיין הציבורי והשאיפה להגן על כספי הציבור.', 'סעיף 258(ב) לחוק החברות קובע כי "חברה רשאית לפטור נושא משרה מאחריותו בשל הפרת חובת הזהירות כלפיה, בהתאם לקבוע בפרק זה בלבד". חוק החברות, תשנ"ט-1999, סעיף 258(ב) אולם, קיימים חריגים לכלל זה. אחד החריגים המרכזיים הוא בחברה לתועלת הציבור (חל"צ). סעיף 345יג לחוק החברות (המוזכר בספרות המשפטית) קובע במפורש כי חל"צ אינה רשאית לפטור נושאי משרה מאחריות. צפורה כהן, נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023) | רקע היסטורי איסור זה נובע מהאופי המיוחד של חל"צ, שנועדה לשרת מטרות ציבוריות, ומהצורך להבטיח את אחריותם של נושאי המשרה כלפי הציבור והתורמים. צפורה כהן, נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023) | רקע היסטורי',
    'הטעות הנפוצה היא להחיל את הכללים הכלליים של חוק החברות על חל"צ, מבלי לשים לב להוראות הספציפיות והמחמירות יותר החלות עליהן.', '["חברה לתועלת הציבור (חל\"צ)", "פטור מראש", "חובת זהירות", "אחריות נושאי משרה", "חוק החברות", "סעיף 345יג לחוק החברות"]'::jsonb, '**וריאציה 1 — איסור בחל"צ:** האם חל"צ רשאית לפטור נושאי משרה מאחריות? ← לא, סעיף 345יג לחוק החברות שולל זאת. צפורה כהן, נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023) | רקע היסטורי
**וריאציה 2 — רציונל האיסור:** מה הרציונל לאיסור זה? ← הגנה על כספי הציבור והבטחת אחריות נושאי המשרה בחל"צ. צפורה כהן, נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023) | רקע היסטורי
**וריאציה 3 — חובת זהירות בחל"צ:** האם נושאי משרה בחל"צ חבים חובת זהירות? ← כן, חובת הזהירות חלה על נושאי משרה בכל סוגי החברות, אך בחל"צ לא ניתן לפטור מהפרתה. חוק לעידוד מחקר, פיתוח וחדשנות טכנולוגית בתעשיה, תשמ"ד-1984, סעיף 15ח', 'חל"צ אינה רשאית לפטור נושאי משרה מאחריות בגין הפרת חובת זהירות (ס'' 345יג לחוק החברות), בשל אופייה הציבורי.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 258(ב)", "צפורה כהן, נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023), פרק רביעי סמכות לפטור מאחריות בגין הפרת חובת זהירות, עמ'' 7", "חוק לעידוד מחקר, פיתוח וחדשנות טכנולוגית בתעשיה, תשמ\"ד-1984, סעיף 15ח"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, חל"צ רשאית לפטור נושא משרה, בדומה לחברה רגילה, ובלבד שהדבר נקבע בתקנון.', false, 'טענה זו שגויה. חוק החברות קובע הוראה מפורשת השוללת מחל"צ את היכולת לפטור נושאי משרה מאחריות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, חל"צ אינה רשאית לפטור נושאי משרה מאחריותם, שכן החוק שולל אפשרות זו במפורש.', true, 'תשובה זו נכונה. סעיף 345יג לחוק החברות (המוזכר בספרות) קובע כי חל"צ אינה רשאית לפטור נושאי משרה מאחריות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם הפטור אושר על ידי בית המשפט.', false, 'טענה זו שגויה. אין בחוק הוראה המאפשרת לבית המשפט לאשר פטור לנושאי משרה בחל"צ.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן מדובר בחל"צ קטנה, שאז ניתן לפטור נושאי משרה.', false, 'טענה זו שגויה. אין בחוק החברות הבחנה בין חל"צ קטנה לגדולה לעניין זה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'אחריות חברי ועד לחלוקה אסורה בעמותה',
    4, 'ועד עמותה אישר חלוקה אסורה של כספים. האם חברי הוועד יישאו באחריות אישית, ומהם תנאי הפטור מאחריות זו?', 'שאלה זו עוסקת באחריותם האישית של חברי ועד בעמותה בגין חלוקה אסורה, ומשווה אותה לאחריות דירקטורים בחברה. היא מדגישה את הדמיון והשוני בין הוראות חוק העמותות לחוק החברות לעניין זה, ובפרט את החזקה הסטטוטורית והחריגים לה.', 'סעיף 34ד לחוק העמותות, תש"ם-1980, קובע הסדר דומה לזה שבחוק החברות לעניין אחריות חברי ועד לחלוקה אסורה. הסעיף קובע כי "בוצעה בעמותה חלוקה אסורה יראו כל מי שהיה חבר ועד במועד החלוקה כמי שהפר בכך את חובותיו כלפי העמותה, אלא אם כן הוכיח אחד מאלה: (1) שהתנגד לחלוקה האסורה ונקט את כל האמצעים הסבירים כדי למנעה; (2) שבנסיבות העניין, לא ידע ולא היה עליו לדעת על החלוקה האסורה". חוק העמותות, תש"ם-1980, סעיף 34ד הוראה זו מטילה חזקה על חברי הוועד שהפרו את חובותיהם, אך מאפשרת להם לסתור חזקה זו באמצעות הוכחת אחד מהחריגים המנויים. יש לציין כי סעיף 34ד לחוק העמותות אינו כולל את החריג של "הסתמכות בתום לב הסתמכות סבירה על מידע שאלולא היה מטעה היתה החלוקה מותרת", הקיים בסעיף 311(2) לחוק החברות. חוק החברות, תשנ"ט-1999, סעיף 311(2)',
    'הטעות הנפוצה היא להחיל את כל החריגים שבסעיף 311 לחוק החברות גם על חברי ועד בעמותה, מבלי לשים לב להבדלים הספציפיים שבסעיף 34ד לחוק העמותות.', '["עמותה", "חברי ועד", "חלוקה אסורה", "אחריות אישית", "חוק העמותות", "חזקה סטטוטורית"]'::jsonb, '**וריאציה 1 — חזקת אחריות:** האם חברי ועד בעמותה נושאים באחריות לחלוקה אסורה? ← כן, קיימת חזקה שהם הפרו את חובותיהם (סעיף 34ד לחוק העמותות). חוק העמותות, תש"ם-1980, סעיף 34ד
**וריאציה 2 — חריגי פטור:** מהם החריגים לפטור מאחריות לחברי ועד בעמותה? ← התנגדות לחלוקה ונקיטת אמצעים סבירים למנעה, או אי-ידיעה על החלוקה האסורה (סעיף 34ד לחוק העמותות). חוק העמותות, תש"ם-1980, סעיף 34ד
**וריאציה 3 — הסתמכות על מידע:** האם הסתמכות על מידע מטעה מהווה חריג לפטור בעמותה? ← לא, חריג זה אינו מופיע בסעיף 34ד לחוק העמותות, בניגוד לחוק החברות. חוק החברות, תשנ"ט-1999, סעיף 311(2)', 'חברי ועד בעמותה נושאים באחריות אישית לחלוקה אסורה (חזקה), אלא אם התנגדו או לא ידעו עליה (ס'' 34ד לחוק העמותות). אין חריג של הסתמכות על מידע מטעה.',
    '["חוק העמותות, תש\"ם-1980, סעיף 34ד", "חוק החברות, תשנ\"ט-1999, סעיף 311"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'חברי הוועד יישאו באחריות אישית, אלא אם כן יוכיחו שהתנגדו לחלוקה ונקטו אמצעים סבירים למנעה, או שלא ידעו ולא היה עליהם לדעת על החלוקה האסורה.', true, 'תשובה זו נכונה. סעיף 34ד לחוק העמותות קובע חזקה דומה לזו שבחוק החברות, לפיה חברי ועד יישאו באחריות אישית, אלא אם כן יוכיחו את אחד החריגים המנויים בחוק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'חברי הוועד לא יישאו באחריות אישית, שכן עמותה אינה חברה ואין לה דירקטורים.', false, 'טענה זו שגויה. חוק העמותות מטיל אחריות אישית על חברי ועד בגין חלוקה אסורה, בדומה לדירקטורים בחברה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'חברי הוועד יישאו באחריות אישית, ואין להם כל אפשרות לפטור עצמם מאחריות זו.', false, 'טענה זו שגויה. סעיף 34ד לחוק העמותות קובע חריגים המאפשרים לחברי ועד לפטור עצמם מאחריות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'חברי הוועד יישאו באחריות אישית, אלא אם כן יוכיחו שהסתמכו בתום לב על מידע מטעה.', false, 'טענה זו שגויה. סעיף 34ד לחוק העמותות אינו כולל את החריג של הסתמכות בתום לב על מידע מטעה, בניגוד לסעיף 311 לחוק החברות.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 8, '2023-S-S-Q08';
END
$$;

