  v_ang_1 uuid := 'f85c6396-5ea4-445d-bcaa-1d1d68e78040'::uuid;
  v_ang_2 uuid := '1a6fbc46-721e-4999-a688-f5cfbc631464'::uuid;
  v_ang_3 uuid := '41273b96-c6a6-43e9-a6cd-bf94883f7171'::uuid;
BEGIN
