  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q11', v_chapter_id, v_subtopic_id, 'יעקב סייע לדן לזהם את מי הכינרת שנועדו לשתייה, והאחרון עשה זאת. מה יהיה עונשו של יעקב?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 11}'::jsonb, 'השאלה עוסקת באחריות פלילית של מסייע (accessory) לעבירה, ובפרט ביישום הוראות הענישה הקבועות בסעיף 32 לחוק העונשין, תשל"ז-1977. היא בוחנת את העונש המוטל על מסייע לעבירה שדינה מאסר עולם חובה, תוך התייחסות להבחנה בין סוגי העונשים השונים הקבועים בחוק.', 'הפתיח לשאלה קובע שלוש עבירות חדשות הנוגעות לזיהום מקורות מים, עם עונשים ספציפיים. במקרה זה, יעקב סייע לדן לזהם את מי הכינרת שנועדו לשתייה, ודן אכן ביצע את הזיהום. על פי הפתיח, העונש על זיהום מקור מים לשתייה הוא "מאסר עולם חובה".
סעיף 31 לחוק העונשין, תשל"ז-1977, מגדיר "מסייע" כמי שעשה מעשה לפני עשיית העבירה או בשעת עשייתה, כדי לאפשר את הביצוע, להקל עליו או לאבטח אותו, או כדי לתרום בדרך אחרת ליצירת תנאים לשם עשיית העבירה. חוק העונשין, תשל"ז-1977, סעיף 31
סעיף 32 לחוק העונשין קובע את העונש על סיוע לעבור עבירה. הכלל הוא שעונשו של המסייע הוא מחצית העונש שנקבע בחיקוק בשל ביצועה העיקרי. אולם, קיימים חריגים לכלל זה. סעיף 32(1) קובע במפורש כי "אם נקבע לה [לעבירה העיקרית] עונש מיתה או מאסר עולם חובה - עונשו [של המסייע] מאסר עשרים שנה". חוק העונשין, תשל"ז-1977, סעיף 32(1)
במקרה הנדון, העבירה העיקרית (זיהום מי שתייה) דינה מאסר עולם חובה. לכן, בהתאם לסעיף 32(1) לחוק העונשין, עונשו של יעקב, כמי שסייע לביצוע העבירה, יהיה מאסר עשרים שנה. ע"פ 11131/02 אנג''ליקה יוסופוב נ'' מדינת ישראל (15.03.2004)', 'הטעות הנפוצה היא ליישם את הכלל הכללי של מחצית העונש גם במקרים בהם קיימת הוראה ספציפית בסעיף 32 לחוק העונשין, כגון במקרה של מאסר עולם חובה, או לבלבל בין עונש למסייע לעבירה שדינה מאסר עולם חובה לבין עונש למסייע לעבירה שדינה מאסר עולם שאינו חובה.',
    '["סיוע", "אחריות פלילית", "חוק העונשין", "מאסר עולם חובה", "עונש מאסר", "עבירה עיקרית"]'::jsonb, '**וריאציה 1 — עונש על סיוע לעבירה שדינה מאסר עולם (לא חובה):** מה יהיה עונשו של יעקב אם העבירה שדינה מאסר עולם אינה חובה? ← מאסר 10 שנים (סעיף 32(2) לחוק העונשין). חוק העונשין, תשל"ז-1977, סעיף 32(2)
**וריאציה 2 — עונש על סיוע לעבירה שדינה מאסר קצוב:** מה יהיה עונשו של יעקב אם העבירה שדינה מאסר 5 שנים? ← מחצית העונש, כלומר 2.5 שנות מאסר (סעיף 32 לחוק העונשין). נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | ההבחנה בין עבירת השידול לעבירת הסיוע
**וריאציה 3 — עונש על סיוע לעבירה שדינה עונש מזערי:** מה יהיה עונשו של יעקב אם העבירה שדינה מאסר 5 שנים ולא פחות מ-3 חודשים? ← העונש המרבי יהיה 2.5 שנים, והעונש המזערי לא יפחת מ-1.5 חודשים (סעיף 32(3) לחוק העונשין). חוק העונשין, תשל"ז-1977, סעיף 32(3)', 'מסייע לעבירה שדינה מאסר עולם חובה ← עונשו מאסר 20 שנים (ס'' 32(1) לחוק העונשין).', '["חוק העונשין, תשל\"ז-1977, סעיפים 31, 32", "ע\"פ 11131/02 אנג''ליקה יוסופוב נ'' מדינת ישראל (15.03.2004)", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026), חוק העונשין, התשל\"ז-1977, עמ'' 44"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''חזרה מאישום'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Accomplice liability (Yaakov aiding Dan to pollute Kinneret water) — criminal general part / parties to offense | source_review_note: השאלה עוסקת בדיני עונשין מהותיים, תחום שאינו נכלל ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''חזרה מאישום'' נבחר כברירת מחדל תחת ''סדר דין פלילי'' בשל הקשר העקיף להליכים פליליים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני עונשין'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'מאסר שלא יפחת ממאסר עולם.', false, 'טענה זו שגויה. עונש מאסר עולם חובה חל על מבצע העבירה העיקרי, ולא על המסייע, אשר עונשו מופחת בהתאם לסעיף 32 לחוק העונשין.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מאסר שלא יפחת ממחצית מאסר עולם.', false, 'טענה זו שגויה. עונש זה אינו תואם את הוראות סעיף 32(1) לחוק העונשין, הקובע עונש ספציפי למסייע לעבירה שדינה מאסר עולם חובה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מאסר 20 שנים.', true, 'תשובה זו נכונה. סעיף 32(1) לחוק העונשין קובע כי אם לעבירה העיקרית נקבע עונש מיתה או מאסר עולם חובה, עונשו של המסייע הוא מאסר עשרים שנה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'מאסר 10 שנים.', false, 'טענה זו שגויה. עונש מאסר 10 שנים חל על מסייע לעבירה שדינה מאסר עולם שאינו חובה, בהתאם לסעיף 32(2) לחוק העונשין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הבחנה בין מבצע בצוותא למסייע',
    1, 'ראובן ודן פעלו יחד לזיהום מי הכינרת שנועדו לשתייה, כאשר ראובן היה שותף פעיל בתכנון ובביצוע. מה יהיה עונשו של ראובן?', 'שאלה זו בוחנת את ההבחנה בין מבצע בצוותא לבין מסייע, ואת השלכותיה על העונש. היא מדגישה כי מבצע בצוותא נחשב למבצע עיקרי ונושא באחריות מלאה לעבירה, בניגוד למסייע שעונשו מופחת.', 'סעיף 29(ב) לחוק העונשין, תשל"ז-1977, קובע כי "המשתתפים בביצוע עבירה תוך עשיית מעשים לביצועה, הם מבצעים בצוותא, ואין נפקה מינה אם כל המעשים נעשו ביחד, או אם נעשו מקצתם בידי אחד ומקצתם בידי אחר". תפ"ח (מחוזי ירושלים) 7028/06 מדינת ישראל נ'' חמדי קורעאן (07.01.2008) מבצע בצוותא נחשב למבצע עיקרי של העבירה, ודינו כדין מבצע העבירה. ע"פ 4186/13 ע''אלב מחמד ע''נאים נ'' מדינת ישראל (13.04.2015) במקרה זה, ראובן היה שותף פעיל בתכנון ובביצוע זיהום מי הכינרת, ולכן הוא מבצע בצוותא. על פי הפתיח לשאלה, העונש על זיהום מקור מים לשתייה הוא מאסר עולם חובה. לפיכך, עונשו של ראובן יהיה מאסר עולם חובה. אסף הרדוף אשמים: טרילוגיה של משפט פלילי ‏- כרך ‏I דיני עונשין (2025) | פרק 42: צדדים לעבירה',
    'הטעות הנפוצה היא לבלבל בין מבצע בצוותא למסייע, ולייחס למבצע בצוותא עונש מופחת, למרות שהוא נושא באחריות מלאה ככל מבצע עיקרי.', '["מבצע בצוותא", "מסייע", "אחריות פלילית", "חוק העונשין", "מאסר עולם חובה", "שותפות לעבירה"]'::jsonb, '**וריאציה 1 — מבחן השליטה הפונקציונלית:** מהו המבחן המרכזי להבחנה בין מבצע בצוותא למסייע? ← מבחן השליטה הפונקציונלית, לפיו המבצע בצוותא שולט על הפעילות העבריינית כולה. ע"פ 4186/13 ע''אלב מחמד ע''נאים נ'' מדינת ישראל (13.04.2015)
**וריאציה 2 — תרומה פנימית מול חיצונית:** מה ההבדל בין תרומת מבצע בצוותא לתרומת מסייע? ← תרומת מבצע בצוותא היא ''פנימית'' למשימה העבריינית, בעוד תרומת המסייע היא ''חיצונית''. תפ"ח (מחוזי ירושלים) 7028/06 מדינת ישראל נ'' חמדי קורעאן (07.01.2008)
**וריאציה 3 — הרחבת הגדרת המבצע:** האם המגמה הפרשנית הרחיבה את הגדרת המבצע? ← כן, המגמה הפרשנית לאחר תיקון 39 לחוק העונשין היא להרחיב את תחום התפרסותו של המבצע על חשבון המסייע. תפ"ח (מחוזי ירושלים) 7028/06 מדינת ישראל נ'' חמדי קורעאן (07.01.2008)', 'מבצע בצוותא ← דינו כדין מבצע העבירה העיקרי (ס'' 29(ב) לחוק העונשין), כולל מאסר עולם חובה אם זה העונש על העבירה.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 29(ב)", "תפ\"ח (מחוזי ירושלים) 7028/06 מדינת ישראל נ'' חמדי קורעאן (07.01.2008)", "ע\"פ 4186/13 ע''אלב מחמד ע''נאים נ'' מדינת ישראל (13.04.2015)", "אסף הרדוף, אשמים: טרילוגיה של משפט פלילי ‏- כרך ‏I דיני עונשין (2025), פרק 42: צדדים לעבירה, עמ'' 14"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'מאסר עולם חובה.', true, 'תשובה זו נכונה. ראובן, כמבצע בצוותא, דינו כדין מבצע העבירה העיקרי, שעונשה מאסר עולם חובה, בהתאם לסעיף 29(ב) לחוק העונשין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'מאסר 20 שנים.', false, 'טענה זו שגויה. עונש זה חל על מסייע לעבירה שדינה מאסר עולם חובה, ולא על מבצע בצוותא.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'מאסר 10 שנים.', false, 'טענה זו שגויה. עונש זה חל על מסייע לעבירה שדינה מאסר עולם שאינו חובה, ולא על מבצע בצוותא.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'מאסר 5 שנים.', false, 'טענה זו שגויה. עונש זה מתייחס לזיהום מקור מים שלא נועד לשימוש אדם, ולא לזיהום מי שתייה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'יסודות עבירת הסיוע',
    2, 'מהם היסודות העובדתיים והנפשיים הנדרשים להוכחת עבירת סיוע לפי חוק העונשין?', 'שאלה זו מתמקדת ביסודות העבירה של סיוע, כפי שהיא מוגדרת בחוק העונשין ובפסיקה. היא דורשת הבנה של היסוד העובדתי (מעשה המסייע) והיסוד הנפשי (מודעות לסיוע ומטרה לסייע) הנדרשים להרשעה בעבירה זו.', 'סעיף 31 לחוק העונשין, תשל"ז-1977, מגדיר את היסוד העובדתי של עבירת הסיוע: "מי אשר, לפני עשיית העבירה או בשעת עשייתה, עשה מעשה כדי לאפשר את הביצוע, להקל עליו או לאבטח אותו, או למנוע את תפיסת המבצע, גילוי העבירה או שללה, או כדי לתרום בדרך אחרת ליצירת תנאים לשם עשיית העבירה, הוא מסייע". חוק העונשין, תשל"ז-1977, סעיף 31 באשר ליסוד הנפשי, הפסיקה קבעה כי נדרשת מודעות לטיב ההתנהגות המסייעת ולכך שהמבצע העיקרי מבצע, או עומד לבצע, עבירה, וכן עמידתה של המטרה לסייע לנגד עיני המסייע. ע"פ 11131/02 אנג''ליקה יוסופוב נ'' מדינת ישראל (15.03.2004) כלומר, המסייע צריך להיות מודע למעשיו ולכך שהם מסייעים לעבירה, וכן שתהיה לו מטרה לסייע למבצע העיקרי. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | ההבחנה בין עבירת השידול לעבירת הסיוע',
    'הטעות הנפוצה היא לבלבל בין היסוד הנפשי של סיוע (מטרה לסייע) לבין היסוד הנפשי של שידול (כוונה להביא לביצוע העבירה), או לחשוב שדי במודעות בלבד לביצוע העבירה העיקרית.', '["סיוע", "יסוד עובדתי", "יסוד נפשי", "מודעות", "מטרה לסייע", "חוק העונשין"]'::jsonb, '**וריאציה 1 — תרומה אפקטיבית:** האם נדרשת תרומה אפקטיבית של המסייע לביצוע העבירה? ← לא, אין הכרח כי בהתנהגותו ירים המסייע תרומה אפקטיבית, אלא די בהתנהגות הנושאת פוטנציאל לסייע. ע"פ 11131/02 אנג''ליקה יוסופוב נ'' מדינת ישראל (15.03.2004)
**וריאציה 2 — סיוע לעבירה תוצאתית:** האם נדרש יסוד נפשי מיוחד מהמסייע בעבירה תוצאתית כמו רצח? ← לא, אין צורך שהמסייע יפעל בכוונה לגרום למות הקורבן או באדישות לכך, אלא רק במודעות ובכוונה לסייע למבצע העיקרי. יוסף אלרון, עומר רזין עבירות המתה: החוק והפסיקה (2025) | סיוע לרצח - סעיף 31 לחוק העונשין בשילוב עבירת המתה
**וריאציה 3 — סיוע לעבירה שלא בוצעה:** האם ניתן להרשיע בסיוע אם העבירה העיקרית לא בוצעה? ← לא, עבירת הסיוע מותנית בכך שהמבצע העיקרי החל לבצע את העבירה העיקרית. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | ההבחנה בין עבירת השידול לעבירת הסיוע', 'יסודות הסיוע ← יסוד עובדתי: מעשה המאפשר/מקל/מאבטח ביצוע (ס'' 31 לחוק העונשין). יסוד נפשי: מודעות למעשה המסייע ומטרה לסייע.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 31", "ע\"פ 11131/02 אנג''ליקה יוסופוב נ'' מדינת ישראל (15.03.2004)", "יוסף אלרון, עומר רזין, עבירות המתה: החוק והפסיקה (2025), פרק י: נגזרות לעבירות הרצח, עמ'' 166", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026), חוק העונשין, התשל\"ז-1977, עמ'' 42"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'יסוד עובדתי של מעשה המאפשר, מקל או מאבטח את הביצוע, ויסוד נפשי של מודעות לטיב ההתנהגות המסייעת ומטרה לסייע.', true, 'תשובה זו נכונה. סעיף 31 לחוק העונשין מגדיר את היסוד העובדתי, והפסיקה קבעה את היסוד הנפשי הנדרש: מודעות לסיוע ומטרה לסייע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'יסוד עובדתי של מעשה המאפשר את הביצוע, ויסוד נפשי של מודעות בלבד לביצוע העבירה העיקרית.', false, 'טענה זו שגויה. היסוד הנפשי לסיוע דורש מטרה לסייע, ולא רק מודעות לביצוע העבירה העיקרית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'יסוד עובדתי של מעשה המאפשר את הביצוע, ויסוד נפשי של כוונה שהעבירה העיקרית תבוצע.', false, 'טענה זו שגויה. היסוד הנפשי לסיוע אינו דורש כוונה שהעבירה העיקרית תבוצע, אלא מטרה לסייע למבצע העיקרי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'יסוד עובדתי של מעשה המאפשר את הביצוע, ללא צורך ביסוד נפשי כלשהו.', false, 'טענה זו שגויה. עבירת הסיוע, כמו רוב העבירות הפליליות, דורשת יסוד נפשי בנוסף ליסוד העובדתי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פטור עקב חרטה למסייע',
    3, 'יעקב סייע לדן לזהם את מי הכינרת, אך לפני ביצוע הזיהום, יעקב הודיע לרשויות על העבירה ועשה כמיטב יכולתו למנעה. מה דינו של יעקב?', 'שאלה זו עוסקת בפטור מאחריות פלילית עקב חרטה, כפי שנקבע בסעיף 34 לחוק העונשין. היא מדגישה את התנאים שבהם מסייע יכול להיפטר מאחריות פלילית, ואת ההבחנה בין פטור מאחריות לסיוע לבין אחריות לעבירות אחרות שבוצעו.', 'סעיף 34(א) לחוק העונשין, תשל"ז-1977, קובע כי "משדל או מסייע לא יישא באחריות פלילית לשידול או לסיוע, או לנסיון לשידול, אם מנע את עשיית העבירה או את השלמתה, או אם הודיע בעוד מועד לרשויות על העבירה לשם מניעת עשייתה או השלמתה ועשה למטרה זו כמיטב יכולתו בדרך אחרת; ואולם, אין באמור כדי לגרוע מאחריות פלילית לעבירה מושלמת אחרת שבמעשה". חוק העונשין, תשל"ז-1977, סעיף 34(א) במקרה זה, יעקב סייע לדן, אך התחרט והודיע לרשויות ופעל למנוע את הזיהום. לכן, הוא ייהנה מפטור מאחריות פלילית לסיוע. חשוב לציין כי הפטור חל רק על עבירת הסיוע עצמה, ואינו גורע מאחריות פלילית לעבירה מושלמת אחרת שבמעשה, אם כזו בוצעה. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | ההבחנה בין עבירת השידול לעבירת הסיוע',
    'הטעות הנפוצה היא לחשוב שחרטה אינה פוטרת מאחריות פלילית כלל, או שהיא פוטרת מכל אחריות פלילית, גם לעבירות אחרות שבוצעו במסגרת אותו מעשה.', '["פטור עקב חרטה", "סיוע", "אחריות פלילית", "חוק העונשין", "מניעת עבירה", "הודעה לרשויות"]'::jsonb, '**וריאציה 1 — תנאי הפטור:** מהם התנאים לפטור עקב חרטה למסייע? ← מניעת עשיית העבירה או השלמתה, או הודעה בעוד מועד לרשויות ופעולה כמיטב היכולת למניעה (סעיף 34(א) לחוק העונשין). חוק העונשין, תשל"ז-1977, סעיף 34(א)
**וריאציה 2 — פטור למבצע:** האם מבצע בצוותא יכול ליהנות מפטור עקב חרטה? ← לא, סעיף 34 לחוק העונשין חל רק על משדל או מסייע, ולא על מבצע בצוותא. אסף הרדוף אשמים: טרילוגיה של משפט פלילי ‏- כרך ‏I דיני עונשין (2025) | הצדדים לעבירה וההבחנות החקיקתיות ביניהם
**וריאציה 3 — אחריות לעבירות אחרות:** האם הפטור גורע מאחריות לעבירות אחרות? ← לא, אין באמור כדי לגרוע מאחריות פלילית לעבירה מושלמת אחרת שבמעשה (סעיף 34(א) לחוק העונשין). חוק העונשין, תשל"ז-1977, סעיף 34(א)', 'מסייע שהתחרט ופעל למניעת העבירה ← פטור מאחריות פלילית לסיוע (ס'' 34(א) לחוק העונשין), אך לא לעבירות אחרות.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34(א)", "אסף הרדוף, אשמים: טרילוגיה של משפט פלילי ‏- כרך ‏I דיני עונשין (2025), פרק 42: צדדים לעבירה, עמ'' 6", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026), חוק העונשין, התשל\"ז-1977, עמ'' 44"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'יעקב יישא באחריות פלילית מלאה, שכן מעשה הסיוע כבר בוצע.', false, 'טענה זו שגויה. סעיף 34 לחוק העונשין קובע פטור מאחריות פלילית למסייע שהתחרט ופעל למניעת העבירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'יעקב לא יישא באחריות פלילית לסיוע, אך ייתכן שיישא באחריות לעבירה מושלמת אחרת שבמעשה.', true, 'תשובה זו נכונה. סעיף 34(א) לחוק העונשין קובע פטור מאחריות פלילית לסיוע במקרה של חרטה, אך מסייג כי אין בכך כדי לגרוע מאחריות פלילית לעבירה מושלמת אחרת שבמעשה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'יעקב יישא באחריות פלילית מופחתת, בדומה לניסיון לסיוע.', false, 'טענה זו שגויה. החוק קובע פטור מלא מאחריות פלילית לסיוע במקרה של חרטה, ולא אחריות מופחתת. אין עבירה של ניסיון לסיוע.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'יעקב יישא באחריות פלילית רק אם העבירה בוצעה בסופו של דבר על ידי דן.', false, 'טענה זו שגויה. הפטור חל גם אם העבירה לא בוצעה, וגם אם בוצעה אך יעקב פעל למנעה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'עונש על סיוע לעבירת רצח בנסיבות מחמירות',
    4, 'מהו העונש המרבי למסייע לעבירת רצח בנסיבות מחמירות, לאחר הרפורמה בעבירות ההמתה?', 'שאלה זו עוסקת בעונשו של מסייע לעבירת רצח בנסיבות מחמירות, תוך התייחסות לרפורמה בעבירות ההמתה. היא מדגישה את יישום סעיף 32(1) לחוק העונשין, הקובע עונש ספציפי למסייע לעבירה שדינה מאסר עולם חובה, ומבחינה בינו לבין עונש למסייע לרצח בסיסי.', 'הרפורמה בעבירות ההמתה חילקה את עבירת הרצח לשתי עבירות עיקריות: רצח בנסיבות מחמירות (סעיף 301א(א) לחוק העונשין), שדינה מאסר עולם חובה, ועבירת הרצח הבסיסית (סעיף 300(א) לחוק העונשין), שדינה מאסר עולם שאינו חובה. ע"פ 230/24 נאסר אלעמרני נ'' מדינת ישראל (15.09.2024) סעיף 32 לחוק העונשין קובע את העונש למסייע. סעיף 32(1) קובע כי אם לעבירה העיקרית נקבע עונש מיתה או מאסר עולם חובה, עונשו של המסייע הוא מאסר עשרים שנה. חוק העונשין, תשל"ז-1977, סעיף 32(1) מאחר שעבירת רצח בנסיבות מחמירות דינה מאסר עולם חובה, הרי שעונשו המרבי של המסייע לעבירה זו הוא 20 שנות מאסר. יוסף אלרון, עומר רזין עבירות המתה: החוק והפסיקה (2025) | סיוע לרצח - סעיף 31 לחוק העונשין בשילוב עבירת המתה לעומת זאת, עונשו המרבי של מסייע לעבירת רצח בסיסית (שדינה מאסר עולם שאינו חובה) הוא 10 שנות מאסר, בהתאם לסעיף 32(2) לחוק. ע"פ 230/24 נאסר אלעמרני נ'' מדינת ישראל (15.09.2024)',
    'הטעות הנפוצה היא לבלבל בין העונש למסייע לרצח בנסיבות מחמירות לבין העונש למסייע לרצח בסיסי, או לחשוב שהעונש למסייע הוא תמיד מחצית העונש של המבצע, מבלי להתחשב בחריגים שבסעיף 32 לחוק העונשין.', '["סיוע", "רצח בנסיבות מחמירות", "מאסר עולם חובה", "חוק העונשין", "רפורמה בעבירות ההמתה", "עונש מרבי"]'::jsonb, '**וריאציה 1 — עונש למסייע לרצח בסיסי:** מהו העונש המרבי למסייע לעבירת רצח בסיסית? ← מאסר 10 שנים (סעיף 32(2) לחוק העונשין). חוק העונשין, תשל"ז-1977, סעיף 32(2)
**וריאציה 2 — פער עונשי:** האם קיים פער עונשי בין מסייע לרצח בסיסי למסייע לרצח בנסיבות מחמירות? ← כן, קיים פער ניכר (10 שנים מול 20 שנים), אשר מעורר קשיים נורמטיביים. ע"פ 230/24 נאסר אלעמרני נ'' מדינת ישראל (15.09.2024)
**וריאציה 3 — עונש חובה כלשהו:** מה דינו של מסייע לעבירה שנקבע לה עונש חובה כלשהו (שאינו מאסר עולם חובה)? ← עונש החובה יהיה העונש המרבי, ומחציתו תהא העונש המזערי (סעיף 32(4) לחוק העונשין). חוק העונשין, תשל"ז-1977, סעיף 32(4)', 'מסייע לרצח בנסיבות מחמירות (שדינה מאסר עולם חובה) ← עונש מרבי של 20 שנות מאסר (ס'' 32(1) לחוק העונשין).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 32(1), 32(2), 32(4)", "ע\"פ 230/24 נאסר אלעמרני נ'' מדינת ישראל (15.09.2024)", "יוסף אלרון, עומר רזין, עבירות המתה: החוק והפסיקה (2025), פרק י: נגזרות לעבירות הרצח, עמ'' 166"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'מאסר עולם חובה.', false, 'טענה זו שגויה. מאסר עולם חובה הוא עונשו של מבצע עבירת רצח בנסיבות מחמירות, ולא של המסייע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'מאסר 20 שנים.', true, 'תשובה זו נכונה. סעיף 32(1) לחוק העונשין קובע כי אם לעבירה העיקרית נקבע עונש מיתה או מאסר עולם חובה, עונשו של המסייע הוא מאסר עשרים שנה. רצח בנסיבות מחמירות דינו מאסר עולם חובה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'מאסר 15 שנים.', false, 'טענה זו שגויה. 15 שנות מאסר הוצעו כעונש למסייע לרצח בסיסי, אך הצעה זו לא הבשילה לכדי חקיקה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'מאסר 10 שנים.', false, 'טענה זו שגויה. עונש מאסר 10 שנים חל על מסייע לעבירת רצח בסיסית (שדינה מאסר עולם שאינו חובה), ולא על רצח בנסיבות מחמירות.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 11, '2023-S-S-Q11';
END
$$;

