-- classifier_note: Attempted offense + voluntary withdrawal (חזרה מכוונת מן הניסיון)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '73923179-da34-4dc1-8d70-68b2ea8a4e13'::uuid;
  v_group_id uuid := 'c4f51cea-49ab-41f5-81ce-6816979c1bb1'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '93618198-4c7a-4561-92b1-a108c917a831'::uuid;
  v_ang_1 uuid := '07f1644e-6d87-4723-84f0-a163d584420a'::uuid;
  v_ang_2 uuid := '1e1fe016-7264-4c2f-8902-32d19114442f'::uuid;
  v_ang_3 uuid := '0b1271e1-5529-4886-9a39-d41c24323590'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q12';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 12, '2023-S-S-Q12';
