  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part_elements' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part_elements', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q12', v_chapter_id, v_subtopic_id, 'בהגיעו לחוף הים כשבידו מכל עם חומר מזהם האסור בהחזקה, וממש טרם שזיהם את המים שנועדו לרחצה, שמע דן את ניידות המשטרה מתקרבות, נבהל והחליט להימנע מזיהום מקור המים. דן השליך את המכל על החוף וברח מן המקום. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 12}'::jsonb, 'השאלה עוסקת באחריות פלילית לניסיון לביצוע עבירה ובפטור עקב חרטה, כפי שנקבע בסעיפים 25 ו-28 לחוק העונשין, תשל"ז-1977. היא בוחנת את התנאים המצטברים הנדרשים לקבלת פטור עקב חרטה, ובפרט את הדרישה שהחדילה מביצוע העבירה תהיה ''מחפץ נפשו בלבד'' ולא עקב גורמים חיצוניים. בנוסף, השאלה מתייחסת לאחריות פלילית לעבירה מושלמת נפרדת (החזקת חומר מזהם) שאינה מושפעת מהפטור על הניסיון.', 'השאלה מתארת מצב שבו דן הגיע לחוף הים עם חומר מזהם אסור בהחזקה, וממש טרם זיהום המים, שמע ניידות משטרה מתקרבות, נבהל והחליט להימנע מהזיהום. הוא השליך את המכל וברח.
1. אחריות לניסיון לזיהום מקור מים לרחצה:
* ניסיון: סעיף 25 לחוק העונשין, תשל"ז-1977, מגדיר ניסיון כ"אדם מנסה לעבור עבירה אם, במטרה לבצעה, עשה מעשה שאין בו הכנה בלבד והעבירה לא הושלמה". חוק העונשין, תשל"ז-1977, סעיף 25 הגעתו של דן לחוף עם המכל המזהם, ממש טרם הזיהום, עולה כדי ניסיון לביצוע העבירה, שכן הוא חרג ממעשי הכנה בלבד.
* פטור עקב חרטה: סעיף 28 לחוק העונשין קובע פטור מאחריות פלילית לניסיון אם הנאשם הוכיח שלושה תנאים מצטברים: (1) חדל מהשלמת המעשה או תרם תרומה של ממש למניעת התוצאות; (2) עשה זאת ''מחפץ נפשו בלבד''; (3) עשה זאת ''מתוך חרטה''. חוק העונשין, תשל"ז-1977, סעיף 28
* במקרה זה, דן חדל מביצוע הזיהום עקב התקרבות ניידות המשטרה. חדילה זו אינה נחשבת ל''מחפץ נפשו בלבד'' אלא נובעת מגורם חיצוני (חשש מתפיסה). ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015) ע"פ 8457/15 מדינת ישראל נ'' עומר בן גאזי ווזווז (01.11.2018) לכן, דן לא ייהנה מפטור עקב חרטה ויישא באחריות פלילית על ניסיון לזיהום מקור מים לרחצה.
2. אחריות להחזקת החומר המזהם:
* החזקת חומר מזהם האסור בהחזקה היא עבירה מושלמת נפרדת. סעיף 28 לחוק העונשין קובע במפורש כי הפטור עקב חרטה אינו גורע מאחריות פלילית בשל עבירה מושלמת אחרת שבמעשה. חוק העונשין, תשל"ז-1977, סעיף 28 לכן, דן יישא באחריות פלילית גם בגין החזקת החומר המזהם.
לאור האמור, דן יישא באחריות פלילית על ניסיון לזיהום מקור מים לרחצה ובאחריות פלילית בגין החזקת החומר המזהם.', 'הטעות הנפוצה היא ליישם את הפטור עקב חרטה גם כאשר החדילה מביצוע העבירה נבעה מגורמים חיצוניים, או להתעלם מכך שהפטור חל רק על עבירת הניסיון ואינו פוטר מאחריות לעבירות מושלמות אחרות שבוצעו.',
    '["ניסיון", "פטור עקב חרטה", "מחפץ נפשו בלבד", "גורם חיצוני", "עבירה מושלמת אחרת", "חוק העונשין"]'::jsonb, '**וריאציה 1 — חרטה לאחר השלמת העבירה:** דן זיהם את המים, ורק לאחר מכן התחרט והודיע למשטרה. האם יקבל פטור? ← לא, הפטור עקב חרטה חל רק על ניסיון, ולא על עבירה מושלמת. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | ב. המעשה הנדרש לצורך חרטה

**וריאציה 2 — נטל ההוכחה:** מי נושא בנטל ההוכחה לקיומו של פטור עקב חרטה? ← הנטל מוטל על הנאשם, ברמת הוכחה של מאזן הסתברויות. ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)
**וריאציה 3 — תכלית הפטור:** מהי תכלית הפטור עקב חרטה? ← טעם מוסרי (שינוי נפשי של הנאשם) וטעם תועלתני (עידוד עבריינים לחדול ממעשיהם). ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)', 'דן יישא באחריות פלילית על ניסיון לזיהום מים (כי חדילתו לא הייתה ''מחפץ נפשו בלבד'' אלא עקב גורם חיצוני) וכן על החזקת החומר המזהם (עבירה מושלמת נפרדת, ס'' 28 לחוק העונשין).', '["חוק העונשין, תשל\"ז-1977, סעיפים 25, 28", "ע\"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)", "ע\"פ 8457/15 מדינת ישראל נ'' עומר בן גאזי ווזווז (01.11.2018)", "ע\"פ 5233721 עלי אבו חסן נ'' מדינת ישראל (18.10.2020)", "ע\"פ 297/11 מחסן סעיד נ'' מדינת ישראל (22.07.2013)", "ע\"פ 10110/03 עופר גמליאל נ'' מדינת ישראל (11.12.2006)", "ע\"פ 5268/04 ליודמילה מינין נ'' מדינת ישראל (07.11.2005)", "ע\"פ 401/99 עאמר מצארווה נ'' מדינת ישראל, נג(3) 561 (11.07.1999)", "תפ\"ח (מחוזי ב\"ש) 49445-11-20 מדינת ישראל פמ\"ד נ'' ואליד אבו מדיעם (27.01.2022)", "יורם רבין, יניב ואקי, דיני עונשין - כרך א (2014), פרק 17 - עבירת הניסיון, עמ'' 36, 38, 40, 41, 43", "יורם רבין, יניב ואקי, דיני עונשין - כרך א (2014), פרק 18 - צדדים לעבירה, עמ'' 102", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026), חוק העונשין, התשל\"ז-1977, עמ'' 36", "יוסף אלרון, עומר רזין, עבירות המתה: החוק והפסיקה (2025), פרק י: נגזרות לעבירות הרצח, עמ'' 153"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''חזרה מאישום'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Attempted offense + voluntary withdrawal (חזרה מכוונת מן הניסיון) | source_review_note: השאלה עוסקת בדיני עונשין מהותיים, תחום שאינו נכלל ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''חזרה מאישום'' נבחר כברירת מחדל תחת ''סדר דין פלילי'' בשל הקשר העקיף להליכים פליליים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני עונשין'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'דן לא יישא בכל אחריות פלילית.', false, 'טענה זו שגויה. דן ביצע מעשים העולים כדי ניסיון לזיהום, ולא עמד בתנאי הפטור עקב חרטה, וכן החזיק בחומר מזהם האסור בהחזקה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'דן לא יישא באחריות פלילית על זיהום מקור מים לרחצה, אך יישא באחריות פלילית בגין החזקת החומר המזהם.', false, 'טענה זו שגויה. דן יישא באחריות פלילית גם על ניסיון לזיהום מקור מים לרחצה, שכן חדילתו לא נבעה מחרטה פנימית אלא מגורם חיצוני (התקרבות המשטרה).', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'דן לא יישא באחריות פלילית על זיהום מקור מים לרחצה, אך יישא באחריות פלילית בגין ניסיון להחזקת החומר המזהם.', false, 'טענה זו שגויה. החזקת חומר מזהם היא עבירה מושלמת, ולא ניסיון לעבירה. בנוסף, דן יישא באחריות פלילית גם על ניסיון לזיהום מקור מים לרחצה.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'דן יישא באחריות פלילית על ניסיון לזיהום מקור מים לרחצה ובאחריות פלילית בגין החזקת החומר המזהם.', true, 'תשובה זו נכונה. דן ביצע ניסיון לזיהום מים, ולא עמד בתנאי הפטור עקב חרטה (שכן חדילתו נבעה מגורם חיצוני). בנוסף, החזקת חומר מזהם היא עבירה מושלמת נפרדת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פטור עקב חרטה: תנאי ''מחפץ נפשו בלבד''',
    1, 'דן הגיע לחוף הים כשבידו מכל עם חומר מזהם האסור בהחזקה, וממש טרם שזיהם את המים שנועדו לרחצה, החליט להימנע מזיהום מקור המים לאחר שהבין כי החומר מסוכן מדי עבורו ועלול לפגוע בו עצמו. דן השליך את המכל על החוף וברח מן המקום. מה הדין?', 'שאלה זו בוחנת את תנאי הפטור עקב חרטה, ובפרט את הדרישה כי החדילה מביצוע העבירה תהיה ''מחפץ נפשו בלבד''. היא מדגישה את ההבחנה בין חרטה הנובעת משיקולים פנימיים (גם אם תועלתניים) לבין חרטה הנובעת מגורמים חיצוניים, ואת השלכותיה על האחריות הפלילית.', 'סעיף 28 לחוק העונשין, תשל"ז-1977, קובע פטור מאחריות פלילית לניסיון אם הנאשם הוכיח שלושה תנאים מצטברים: חדילה מהשלמת המעשה או תרומה למניעת התוצאות; ''מחפץ נפשו בלבד''; ו''מתוך חרטה''. חוק העונשין, תשל"ז-1977, סעיף 28 התנאי ''מחפץ נפשו בלבד'' משמעו שהחזרה מהשלמת העבירה תהא מיוזמתו של העושה, וללא השפעה של גורם חיצוני. ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015) במקרה זה, דן חדל מביצוע הזיהום כי הבין שהחומר מסוכן לו עצמו. זוהי חדילה הנובעת משיקול פנימי, גם אם תועלתני, ולא מגורם חיצוני כמו התקרבות המשטרה. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | א. הלך הנפש הנדרש לצורך חרטה לכן, דן עשוי ליהנות מפטור עקב חרטה לעניין הניסיון לזיהום. עם זאת, סעיף 28 מסייג כי הפטור אינו גורע מאחריות פלילית בשל עבירה מושלמת אחרת שבמעשה. חוק העונשין, תשל"ז-1977, סעיף 28 החזקת החומר המזהם היא עבירה מושלמת נפרדת, ולכן דן יישא באחריות בגינה.',
    'הטעות הנפוצה היא לחשוב שכל חרטה, ללא קשר למניעיה, מזכה בפטור, או להתעלם מהדרישה ל''מחפץ נפשו בלבד'' כהבחנה בין מניעים פנימיים לחיצוניים.', '["פטור עקב חרטה", "ניסיון", "מחפץ נפשו בלבד", "חרטה", "עבירה מושלמת אחרת", "חוק העונשין"]'::jsonb, '**וריאציה 1 — חרטה מוסרית:** דן התחרט מתוך תחושה מוסרית עמוקה. האם יקבל פטור? ← כן, חרטה מוסרית היא המקרה הקלאסי לפטור עקב חרטה, שכן היא נובעת מחפץ נפשו בלבד ומתוך חרטה אמיתית. ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)
**וריאציה 2 — חרטה תועלתנית:** דן התחרט כי חשש מהשלכות המעשה (למשל, עונש כבד). האם יקבל פטור? ← כן, הפסיקה המאוחרת קבעה כי אין צורך בחרטה ''רגשית-מוסרית'' ודי בחזרה מהכוונה לבצע את העבירה, גם אם מטעמים תועלתניים, כל עוד היא מחפץ נפשו בלבד. ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)
**וריאציה 3 — חרטה חלקית:** דן חדל מזיהום מי הרחצה, אך תכנן לזהם מקור מים אחר. האם יקבל פטור? ← לא, חזרה מביצוע המעשה אינה שלמה אם הכוונה היא לדחות את המעשה הפלילי לזמן מתאים יותר, או להעביר את המאמץ הפלילי לאובייקט אחר. ע"פ 8457/15 מדינת ישראל נ'' עומר בן גאזי ווזווז (01.11.2018)', 'פטור עקב חרטה (ס'' 28 לחוק העונשין) ← דורש חדילה מחפץ נפשו בלבד ומתוך חרטה (גם תועלתנית), ולא עקב גורם חיצוני. הפטור אינו חל על עבירה מושלמת אחרת.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 28", "ע\"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)", "ע\"פ 8457/15 מדינת ישראל נ'' עומר בן גאזי ווזווז (01.11.2018)", "יורם רבין, יניב ואקי, דיני עונשין - כרך א (2014), פרק 17 - עבירת הניסיון, עמ'' 38, 40"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'דן לא יישא באחריות פלילית על ניסיון לזיהום מקור מים לרחצה, אך יישא באחריות פלילית בגין החזקת החומר המזהם.', true, 'תשובה זו נכונה. חדילתו של דן נבעה משיקול פנימי (הבנה שהחומר מסוכן לו), ולכן הוא עשוי ליהנות מפטור עקב חרטה לעניין הניסיון לזיהום. עם זאת, החזקת החומר המזהם היא עבירה מושלמת נפרדת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'דן יישא באחריות פלילית על ניסיון לזיהום מקור מים לרחצה ובאחריות פלילית בגין החזקת החומר המזהם.', false, 'טענה זו שגויה. במקרה זה, חדילתו של דן נבעה משיקול פנימי, ולכן הוא עשוי ליהנות מפטור עקב חרטה לעניין הניסיון לזיהום.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'דן לא יישא בכל אחריות פלילית.', false, 'טענה זו שגויה. גם אם יקבל פטור על הניסיון לזיהום, הוא עדיין יישא באחריות פלילית בגין החזקת החומר המזהם, שהיא עבירה מושלמת נפרדת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'דן יישא באחריות פלילית רק על ניסיון לזיהום מקור מים לרחצה.', false, 'טענה זו שגויה. אם יקבל פטור על הניסיון לזיהום, הוא לא יישא באחריות עליו. בנוסף, הוא יישא באחריות על החזקת החומר המזהם.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי ''חדל מהשלמת המעשה'' בניסיון',
    2, 'מה נדרש מדן כדי לעמוד בתנאי ''חדל מהשלמת המעשה'' לצורך פטור עקב חרטה, אם הניסיון לזיהום היה ניסיון מושלם (כלומר, דן עשה את כל הפעולות הנדרשות לזיהום, אך התוצאה טרם התרחשה)?', 'שאלה זו מתמקדת בדרישה העובדתית של הפטור עקב חרטה – ''חדל מהשלמת המעשה או תרם תרומה של ממש למניעת התוצאות''. היא מבחינה בין ניסיון בלתי מושלם לניסיון מושלם, ומדגישה את הדרישה לפעולה אקטיבית במקרה של ניסיון מושלם כדי לזכות בפטור.', 'סעיף 28 לחוק העונשין קובע את התנאי הראשון לפטור עקב חרטה: ''חדל מהשלמת המעשה או תרם תרומה של ממש למניעת התוצאות שבהן מותנית השלמת העבירה''. חוק העונשין, תשל"ז-1977, סעיף 28 טיב המעשה הנדרש תלוי בשלב שאליו הגיע הניסיון. אם טרם השלים המנסה את כל הפעולות התלויות בו להשלמת העבירה (ניסיון בלתי מושלם), די שיחדל מהשלמת המעשה. ואולם, אם מדובר בניסיון מושלם, היינו כזה שהנאשם עשה את כל אשר תלוי בו להשלמת העבירה אך העבירה טרם הושלמה (שכן היא תלויה בגורמים חיצוניים לנאשם), דורש הסעיף מהנאשם לתרום ''תרומה של ממש למניעת התוצאות שבהן מותנית השלמת העבירה''. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | ב. המעשה הנדרש לצורך חרטה כלומר, נדרשת פעולה אקטיבית של הנאשם למניעת התוצאה המזיקה העלולה להיגרם מהתנהגותו ומניעת השלמת העבירה. ע"פ 8263/18 עלי אבו חסן נ'' מדינת ישראל (18.10.2020)',
    'הטעות הנפוצה היא לחשוב שדי בחדילה פסיבית ממעשה גם בניסיון מושלם, או לא להבחין בין הדרישות השונות לניסיון מושלם ובלתי מושלם.', '["פטור עקב חרטה", "ניסיון מושלם", "ניסיון בלתי מושלם", "חדל מהשלמת המעשה", "תרומה של ממש", "חוק העונשין"]'::jsonb, '**וריאציה 1 — ניסיון בלתי מושלם:** דן החל לערבב את החומר המזהם, אך טרם הגיע לחוף. הוא התחרט וחדל ממעשיו. האם יקבל פטור? ← כן, בניסיון בלתי מושלם די בחדילה ממעשה. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | ב. המעשה הנדרש לצורך חרטה
**וריאציה 2 — תרומה אפקטיבית:** האם ''תרומה של ממש'' מחייבת הצלחה במניעת התוצאה? ← ישנן גישות שונות, אך פרשנות מחמירה דורשת שהמנסה יצליח למנוע את השלמת העבירה. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | ב. המעשה הנדרש לצורך חרטה
**וריאציה 3 — פעולה חיצונית:** האם תחושת חרטה פנימית מספיקה? ← לא, כדי לעמוד בתנאי ''חדל מהשלמת המעשה'' על העושה לנקוט בפעולה חיצונית שתמנע את השלמת העבירה. ע"פ 8263/18 עלי אבו חסן נ'' מדינת ישראל (18.10.2020)', 'תנאי ''חדל מהשלמת המעשה'' (ס'' 28 לחוק העונשין) ← בניסיון בלתי מושלם: די בחדילה. בניסיון מושלם: נדרשת תרומה של ממש למניעת התוצאות (פעולה אקטיבית).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 28", "ע\"פ 5233721 עלי אבו חסן נ'' מדינת ישראל (18.10.2020)", "יורם רבין, יניב ואקי, דיני עונשין - כרך א (2014), פרק 17 - עבירת הניסיון, עמ'' 41"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'די שיחדל מלהמשיך בפעולותיו לזיהום.', false, 'טענה זו שגויה. במקרה של ניסיון מושלם, אין די בחדילה מפעולות, אלא נדרשת פעולה אקטיבית למניעת התוצאה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'עליו לתרום תרומה של ממש למניעת התוצאות שבהן מותנית השלמת העבירה.', true, 'תשובה זו נכונה. במקרה של ניסיון מושלם, סעיף 28 לחוק העונשין דורש מהנאשם לתרום ''תרומה של ממש למניעת התוצאות שבהן מותנית השלמת העבירה'', כלומר פעולה אקטיבית למניעת הנזק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'עליו להודיע לרשויות על כוונתו לזיהום.', false, 'טענה זו שגויה. הודעה לרשויות היא תנאי לפטור עקב חרטה למשדל או מסייע (סעיף 34), אך לא למבצע ניסיון (סעיף 28), במיוחד בניסיון מושלם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'אין הוא יכול ליהנות מפטור עקב חרטה, שכן הניסיון כבר הושלם.', false, 'טענה זו שגויה. גם בניסיון מושלם ניתן ליהנות מפטור עקב חרטה, אם הנאשם פעל באופן אקטיבי למניעת התוצאות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פטור עקב חרטה למשדל או מסייע',
    3, 'יעקב שידל את דן לזהם את מי חוף הים שנועדו לרחצה. דן ביצע את הזיהום. לאחר מכן, יעקב התחרט והודיע לרשויות על מעשיו של דן, אך לא הצליח למנוע את התוצאה. מה דינו של יעקב?', 'שאלה זו עוסקת בפטור עקב חרטה למשדל או מסייע, כפי שנקבע בסעיף 34 לחוק העונשין. היא מדגישה את ההבדלים בין פטור זה לבין הפטור למבצע ניסיון (סעיף 28), ובפרט את העובדה שהפטור למשדל/מסייע יכול להינתן גם אם העבירה הושלמה, ואינו דורש חרטה פנימית דווקא.', 'סעיף 34 לחוק העונשין, תשל"ז-1977, קובע פטור עקב חרטה למשדל או מסייע. חוק העונשין, תשל"ז-1977, סעיף 34(א) בניגוד לפטור למבצע ניסיון (סעיף 28), הפטור למשדל ולמסייע יכול להינתן גם כאשר העבירה הושלמה, אם ''הודיע בעוד מועד לרשויות לשם מניעתה או השלמתה ועשה למטרה זו כמיטב יכולתו בדרך אחרת''. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | א. פטור עקב חרטה הטעם לכך הוא כי המשדל והמסייע הם שותפים משניים הנמצאים במעגל החיצוני של השותפות, ואין השליטה והיכולת להפסיק את העבירה מסורות בידיהם אלא בידי המבצע. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | א. פטור עקב חרטה במקרה זה, יעקב שידל את דן, ודן ביצע את הזיהום. יעקב התחרט והודיע לרשויות ועשה כמיטב יכולתו למנוע את התוצאה. לכן, הוא ייהנה מפטור מאחריות פלילית לשידול, למרות שהעבירה הושלמה. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | א. פטור עקב חרטה',
    'הטעות הנפוצה היא להחיל את תנאי הפטור של סעיף 28 (למבצע ניסיון) על משדל או מסייע, או לחשוב שחרטה פנימית היא תנאי הכרחי לפטור למשדל/מסייע.', '["פטור עקב חרטה", "שידול", "סיוע", "הודעה לרשויות", "עבירה מושלמת", "חוק העונשין"]'::jsonb, '**וריאציה 1 — חרטה פנימית למסייע:** האם נדרש שהמסייע יתחרט מתוך מפנה נפשי? ← לא, סעיף 34 אינו מחייב חרטה פנימית, אלא מתמקד במעשים שנוקט המתחרט. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | א. פטור עקב חרטה
**וריאציה 2 — הודעה ''בעוד מועד'':** מהי הודעה ''בעוד מועד'' לרשויות? ← הודעה בעתוי שהותיר לרשויות די זמן למנוע את העבירה, גם אם בפועל לא מנעו. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | א. פטור עקב חרטה
**וריאציה 3 — אחריות לעבירה מושלמת אחרת:** יעקב, בנוסף לשידול, גם החזיק בחומר מזהם. האם הפטור יחול על החזקה? ← לא, הפטור אינו גורע מאחריות פלילית לעבירה מושלמת אחרת שבמעשה. חוק העונשין, תשל"ז-1977, סעיף 34(א)', 'פטור עקב חרטה למשדל/מסייע (ס'' 34 לחוק העונשין) ← ניתן גם אם העבירה הושלמה, אם מנע או הודיע לרשויות בעוד מועד ועשה כמיטב יכולתו. אינו דורש חרטה פנימית.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34", "יורם רבין, יניב ואקי, דיני עונשין - כרך א (2014), פרק 18 - צדדים לעבירה, עמ'' 102", "יורם רבין, יניב ואקי, דיני עונשין - כרך א (2014), פרק 17 - עבירת הניסיון, עמ'' 43"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'יעקב יישא באחריות פלילית מלאה לשידול, שכן העבירה הושלמה.', false, 'טענה זו שגויה. סעיף 34 לחוק העונשין מאפשר פטור למשדל או מסייע גם אם העבירה הושלמה, בתנאים מסוימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'יעקב לא יישא באחריות פלילית לשידול, שכן הודיע לרשויות על העבירה.', true, 'תשובה זו נכונה. סעיף 34 לחוק העונשין קובע פטור למשדל או מסייע אם הודיע בעוד מועד לרשויות על העבירה לשם מניעתה או השלמתה ועשה למטרה זו כמיטב יכולתו, גם אם העבירה הושלמה בפועל.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'יעקב יישא באחריות פלילית מופחתת לשידול, בדומה לניסיון לשידול.', false, 'טענה זו שגויה. סעיף 34 לחוק העונשין קובע פטור מלא מאחריות פלילית לשידול, ולא אחריות מופחתת, אם התקיימו תנאיו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'יעקב לא יישא באחריות פלילית רק אם הצליח למנוע את השלמת העבירה.', false, 'טענה זו שגויה. למשדל או מסייע, הפטור יכול להינתן גם אם העבירה הושלמה, ובלבד שהודיע לרשויות ועשה כמיטב יכולתו למנוע.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הבחנה בין ניסיון להכנה',
    4, 'דן רכש את החומר המזהם האסור בהחזקה, ותכנן לנסוע לחוף הים כדי לזהם את המים. בדרכו לחוף, הוא נעצר על ידי המשטרה. מה הדין?', 'שאלה זו עוסקת בהבחנה קריטית בדיני עונשין בין מעשי הכנה לביצוע עבירה לבין ניסיון לביצוע עבירה. היא בוחנת את הגדרת הניסיון בסעיף 25 לחוק העונשין, הקובעת כי ניסיון הוא ''מעשה שאין בו הכנה בלבד'', ואת ההשלכות של הבחנה זו על האחריות הפלילית.', 'סעיף 25 לחוק העונשין, תשל"ז-1977, מגדיר ניסיון כ"אדם מנסה לעבור עבירה אם, במטרה לבצעה, עשה מעשה שאין בו הכנה בלבד והעבירה לא הושלמה". חוק העונשין, תשל"ז-1977, סעיף 25 ההבחנה בין הכנה לניסיון היא קריטית, שכן מעשי הכנה אינם ברי ענישה כניסיון (למעט חריגים בחוקים ספציפיים, כמו חוק המאבק בטרור). יוסף אלרון, עומר רזין עבירות המתה: החוק והפסיקה (2025) | א. עבירת ניסיון לרצח עד הרפורמה בעבירות ההמתה רכישת החומר המזהם ותכנון הנסיעה לחוף, בטרם הגיע לחוף והחל בפעולות ממשיות לזיהום, נחשבים בדרך כלל למעשי הכנה. לכן, דן לא יישא באחריות פלילית על ניסיון לזיהום מקור מים לרחצה. עם זאת, החזקת החומר המזהם היא עבירה מושלמת נפרדת, ואין קשר בינה לבין הניסיון לזיהום. לכן, דן יישא באחריות פלילית בגין החזקת החומר המזהם. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | ב. המעשה הנדרש לצורך חרטה',
    'הטעות הנפוצה היא לבלבל בין מעשי הכנה לניסיון, ולייחס אחריות פלילית לניסיון כבר בשלב ההכנה, או להתעלם מקיומה של עבירה מושלמת נפרדת (החזקת החומר המזהם).', '["ניסיון", "הכנה", "חוק העונשין", "אחריות פלילית", "עבירה מושלמת", "יסוד עובדתי"]'::jsonb, '**וריאציה 1 — מבחן הקרבה לביצוע:** מהו המבחן המרכזי להבחנה בין הכנה לניסיון? ← מבחן הקרבה לביצוע, הבוחן עד כמה המעשה קרוב להשלמת העבירה. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | פטור עקב חרטה
**וריאציה 2 — ניסיון בלתי צליח:** דן ניסה לזהם את המים בחומר שלמעשה לא היה מזהם. האם יישא באחריות לניסיון? ← כן, אין נפקא מינה אם עשיית העבירה לא הייתה אפשרית מחמת מצב דברים שהמנסה לא היה מודע לו או טעה לגביו (ניסיון בלתי צליח). צו בדבר הוראות ביטחון [נוסח משולב] (יהודה והשומרון) (מס'' 1651), תש"ע-2009, סעיף 199
**וריאציה 3 — עונש על ניסיון:** מהו העונש על ניסיון לזיהום מים לרחצה? ← העונש על הניסיון זהה לעונש על ביצוע העבירה המושלמת, אלא אם נאמר בחיקוק אחרת. ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)', 'הכנה (רכישת חומר ותכנון) ← אינה ברת ענישה כניסיון (ס'' 25 לחוק העונשין). החזקת חומר אסור ← עבירה מושלמת נפרדת.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 25", "צו בדבר הוראות ביטחון [נוסח משולב] (יהודה והשומרון) (מס'' 1651), תש\"ע-2009, סעיף 199", "ע\"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)", "יוסף אלרון, עומר רזין, עבירות המתה: החוק והפסיקה (2025), פרק י: נגזרות לעבירות הרצח, עמ'' 153", "יורם רבין, יניב ואקי, דיני עונשין - כרך א (2014), פרק 17 - עבירת הניסיון, עמ'' 43", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026), חוק העונשין, התשל\"ז-1977, עמ'' 36"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'דן יישא באחריות פלילית על ניסיון לזיהום מקור מים לרחצה ועל החזקת החומר המזהם.', false, 'טענה זו שגויה. רכישת החומר ותכנון הנסיעה נחשבים בדרך כלל למעשי הכנה, ולא לניסיון, אלא אם כן הם חורגים ממעשי הכנה בלבד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'דן יישא באחריות פלילית על החזקת החומר המזהם בלבד.', true, 'תשובה זו נכונה. רכישת החומר ותכנון הנסיעה נחשבים למעשי הכנה שאינם ברי ענישה כניסיון. עם זאת, החזקת החומר המזהם היא עבירה מושלמת נפרדת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'דן לא יישא בכל אחריות פלילית, שכן מעשיו לא הגיעו לכדי ניסיון.', false, 'טענה זו שגויה. גם אם מעשיו לא הגיעו לכדי ניסיון לזיהום, הוא עדיין יישא באחריות פלילית בגין החזקת החומר המזהם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'דן יישא באחריות פלילית על ניסיון לזיהום מקור מים לרחצה בלבד.', false, 'טענה זו שגויה. מעשיו של דן במקרה זה הם בגדר הכנה, ולא ניסיון. בנוסף, הוא יישא באחריות על החזקת החומר המזהם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 12, '2023-S-S-Q12';
END
$$;

-- ============================================================
-- Q15 — 2023-S-S-Q15 — chapter=criminal_substantive subtopic=general_part_elements
-- classifier_note: Interpretation of an offense element under חוק טיפול בחולי נפש (general principles of criminal interpretation)
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '95615c27-cb9f-4ad8-ae90-1d404f29e529'::uuid;
  v_group_id uuid := '43293b8d-ed1a-4eca-b16c-e2b0269c108c'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'c7fafb2e-c476-4525-8af5-4149b18e4df3'::uuid;
  v_ang_1 uuid := 'd5d96704-c25d-4f5e-9383-5a43a2b22ed7'::uuid;
  v_ang_2 uuid := '05ff8f73-dfa1-415a-9f25-3736d5b71d42'::uuid;
  v_ang_3 uuid := '86afa522-6cf6-4bb5-a106-28e7ddee5b31'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q15';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 15, '2023-S-S-Q15';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part_elements' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part_elements', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q15', v_chapter_id, v_subtopic_id, 'התעורר ספק באשר לאופן בו יש לפרש את אחד מיסודות העבירה לפי חוק טיפול בחולי נפש של גרימת אישפוז אדם ללא צורך בבית חולים לחולי נפש. הנח כי אין בחוק הטיפול בחולי נפש הוראה סותרת. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 15}'::jsonb, 'השאלה עוסקת בכלל הפירוש המקל (Rule of Lenity) במשפט הפלילי, הקבוע בסעיף 34כא לחוק העונשין, תשל"ז-1977. כלל זה קובע כי במקרה של ספק סביר באשר לקיומה של עבירה או לאחריותו של אדם, יוכרע הספק לטובת הנאשם. עם זאת, הכלל אינו בלתי מוגבל, והוא חל רק מבין הפירושים הסבירים מבחינת לשון החוק ותכליתו.', 'סעיף 34כא לחוק העונשין, תשל"ז-1977, קובע את כלל הפירוש המקל: "היה ספק סביר אם עבירה היא, או אם פלוני עבר אותה, יוכרע הספק לטובת הנאשם; ואולם אין הוראה זו גורעת מהוראות סעיף 34כב". חוק העונשין, תשל"ז-1977, סעיף 34כא
הפסיקה פירשה את סעיף 34כא כקובע כי כלל הפירוש המקל חל רק בתוך מתחם הפירושים הסבירים מבחינת לשון החוק ותכליתו. ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015) המשמעות היא שבית המשפט אינו רשאי לבחור בפירוש המקל עם הנאשם אם פירוש זה אינו עולה בקנה אחד עם לשון החוק או סותר את תכליתו. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל
במקרה הנדון, התעורר ספק באשר לאופן פירוש אחד מיסודות העבירה. על פי סעיף 34כא, יש לבחור בפירוש המקל ביותר עם המואשם, אך זאת מבין הפירושים הסבירים מבחינת לשון החוק ותכליתו. לכן, התשובה הנכונה היא ד''.', 'הטעות הנפוצה היא לחשוב שכלל הפירוש המקל הוא כלל מוחלט המצדיק כל פירוש המקל עם הנאשם, מבלי להתחשב במגבלות של לשון החוק ותכליתו.',
    '["פירוש מקל", "חוק העונשין", "ספק סביר", "לשון החוק", "תכלית החוק", "פרשנות תכליתית"]'::jsonb, '**וריאציה 1 — ספק בעובדות:** התעורר ספק סביר אם הנאשם ביצע את המעשה. מה הדין? ← יוכרע הספק לטובת הנאשם (סעיף 34כא לחוק העונשין). חוק העונשין, תשל"ז-1977, סעיף 34כא
**וריאציה 2 — ספק בעונש:** התעורר ספק סביר לגבי גובה העונש שיש להטיל על הנאשם. מה הדין? ← יוכרע הספק לטובת הנאשם, כלומר ייבחר העונש המקל יותר (סעיף 34כא לחוק העונשין). נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל
**וריאציה 3 — חוק ספציפי:** האם כלל הפירוש המקל חל גם אם בחוק הספציפי (כמו חוק טיפול בחולי נפש) יש הוראה סותרת? ← לא, סעיף 34כא קובע ''אין הוראה זו גורעת מהוראות סעיף 34כב'', וכן ''הנח כי אין בחוק הטיפול בחולי נפש הוראה סותרת''. כלומר, אם יש הוראה סותרת בחוק ספציפי, היא גוברת. חוק העונשין, תשל"ז-1977, סעיף 34כא', 'ספק בפירוש יסוד עבירה ← יוכרע לטובת הנאשם, מבין הפירושים הסבירים מבחינת לשון החוק ותכליתו (ס'' 34כא לחוק העונשין).', '["חוק העונשין, תשל\"ז-1977, סעיפים 34כא, 34כג", "ע\"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026), חוק העונשין, התשל\"ז-1977, עמ'' 10"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''חזרה מאישום'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Interpretation of an offense element under חוק טיפול בחולי נפש (general principles of criminal interpretation) | source_review_note: השאלה עוסקת בדיני עונשין מהותיים, תחום שאינו נכלל ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''חזרה מאישום'' נבחר כברירת מחדל תחת ''סדר דין פלילי'' בשל הקשר העקיף להליכים פליליים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני עונשין'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'יש לבחור בפירוש המקל ביותר עם המואשם בעבירה.', false, 'טענה זו שגויה. הפירוש המקל עם המואשם אינו בלתי מוגבל, אלא כפוף למגבלות של לשון החוק ותכליתו, כפי שנקבע בסעיף 34כא לחוק העונשין.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'יש לבחור בפירוש המקל ביותר עם המואשם בעבירה מבין הפירושים האפשריים מבחינת לשון החוק.', false, 'טענה זו שגויה. הפירוש המקל אינו כפוף רק ללשון החוק, אלא גם לתכלית החוק, כפי שנקבע בסעיף 34כא לחוק העונשין.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'יש לבחור בפירוש המקל ביותר עם קרבן העבירה מבין הפירושים הסבירים מבחינת תכלית החוק.', false, 'טענה זו שגויה. כלל הפירוש המקל (Rule of Lenity) נועד להגן על הנאשם, ולא על קורבן העבירה, כפי שקובע סעיף 34כא לחוק העונשין.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'יש לבחור בפירוש המקל ביותר עם המואשם בעבירה מבין הפירושים הסבירים מבחינת תכלית החוק.', true, 'תשובה זו נכונה. סעיף 34כא לחוק העונשין קובע כי במקרה של ספק בפירוש הוראת חיקוק, יש לבחור בפירוש המקל ביותר עם מי שאמור לשאת באחריות פלילית, וזאת מבין הפירושים הסבירים מבחינת לשון החוק ותכליתו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פירוש חוק שאינו עונשי המשפיע על אחריות פלילית',
    1, 'התעורר ספק באשר לאופן בו יש לפרש סעיף בחוק מס הכנסה, כאשר פירוש הסעיף ישפיע על קיומו של יסוד עובדתי בעבירת העלמת מס. הנח כי אין בחוק מס הכנסה הוראה סותרת. מה הדין?', 'שאלה זו בוחנת את היקף תחולתו של כלל הפירוש המקל, כפי שנקבע בסעיף 34כג לחוק העונשין. היא מדגישה כי הכלל חל לא רק על הוראות עונשיות מובהקות, אלא גם על הוראות בחיקוקים אחרים (כגון חוקי מס) המגדירות יסוד מיסודות העבירה הפלילית.', 'סעיף 34כא לחוק העונשין, תשל"ז-1977, קובע את כלל הפירוש המקל: "היה ספק סביר אם עבירה היא, או אם פלוני עבר אותה, יוכרע הספק לטובת הנאשם". סעיף 34כג מרחיב את תחולת הכלל וקובע: "הוראות סעיפים 34כא ו-34כב יחולו גם לענין פירוש הוראת חיקוק שאינה עונשית, אם היא מגדירה יסוד מיסודות העבירה". חוק העונשין, תשל"ז-1977, סעיף 34כג במקרה זה, פירוש סעיף בחוק מס הכנסה משפיע על קיומו של יסוד עובדתי בעבירת העלמת מס. לכן, למרות שחוק מס הכנסה אינו חוק עונשי, כלל הפירוש המקל יחול על פירוש הסעיף, ויש לבחור בפירוש המקל ביותר עם המואשם, מבין הפירושים הסבירים מבחינת תכלית חוק מס הכנסה. ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)',
    'הטעות הנפוצה היא לחשוב שכלל הפירוש המקל חל רק על חוקים עונשיים מובהקים, ולא להכיר בהרחבת תחולתו באמצעות סעיף 34כג לחוק העונשין.', '["פירוש מקל", "חוק העונשין", "יסודות עבירה", "חוק שאינו עונשי", "תכלית החוק", "אחריות פלילית"]'::jsonb, '**וריאציה 1 — יסוד נפשי:** האם כלל הפירוש המקל חל גם על פירוש יסוד נפשי של עבירה המוגדר בחוק שאינו עונשי? ← כן, סעיף 34כג חל על כל יסוד מיסודות העבירה, בין אם עובדתי ובין אם נפשי. חוק העונשין, תשל"ז-1977, סעיף 34כג
**וריאציה 2 — חוקי עזר:** האם כלל הפירוש המקל חל על פירוש חוקי עזר עירוניים המגדירים עבירות? ← כן, חוקי עזר הם בגדר ''חיקוק'' וכלל הפירוש המקל חל גם עליהם. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל
**וריאציה 3 — ספק סביר:** מהו ''ספק סביר'' לעניין כלל הפירוש המקל? ← ספק סביר הוא ספק שאינו מופרך או דחוק, אלא כזה שיש לו אחיזה בלשון החוק ובתכליתו. ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)', 'כלל הפירוש המקל (ס'' 34כא, 34כג לחוק העונשין) ← חל גם על פירוש יסודות עבירה המוגדרים בחוקים שאינם עונשיים, מבין הפירושים הסבירים מבחינת תכלית החוק.',
    '["חוק העונשין, תשל\"ז-1977, סעיפים 34כא, 34כג", "ע\"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026), חוק העונשין, התשל\"ז-1977, עמ'' 10"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'יש לבחור בפירוש המקל ביותר עם המואשם בעבירה מבין הפירושים הסבירים מבחינת תכלית חוק מס הכנסה.', true, 'תשובה זו נכונה. סעיף 34כג לחוק העונשין מרחיב את תחולת כלל הפירוש המקל גם להוראות חיקוק שאינן עונשיות, אם הן מגדירות יסוד מיסודות העבירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'יש לבחור בפירוש המקל ביותר עם המואשם בעבירה מבין הפירושים האפשריים מבחינת לשון חוק מס הכנסה.', false, 'טענה זו שגויה. הפירוש המקל כפוף גם לתכלית החוק, ולא רק ללשונו, כפי שנקבע בסעיף 34כא לחוק העונשין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'יש לבחור בפירוש המקל ביותר עם המדינה, שכן חוק מס הכנסה אינו חוק עונשי.', false, 'טענה זו שגויה. סעיף 34כג לחוק העונשין קובע במפורש כי כלל הפירוש המקל חל גם על הוראות חיקוק שאינן עונשיות, אם הן מגדירות יסוד מיסודות העבירה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'יש לבחור בפירוש המקל ביותר עם המואשם בעבירה רק אם חוק מס הכנסה מפנה במפורש לחוק העונשין.', false, 'טענה זו שגויה. סעיף 34כג לחוק העונשין אינו דורש הפניה מפורשת, אלא קובע תחולה כללית לכלל הפירוש המקל על יסודות עבירה המוגדרים בחיקוקים אחרים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תכלית החוק כגבול לפירוש המקל',
    2, 'התעורר ספק באשר לאופן בו יש לפרש את אחד מיסודות העבירה. פירוש אחד מקל עם המואשם, אך סותר באופן מובהק את תכלית החוק. פירוש שני מחמיר עם המואשם, אך עולה בקנה אחד עם תכלית החוק. מה הדין?', 'שאלה זו מדגישה את המגבלות על כלל הפירוש המקל, ובפרט את חשיבותה של תכלית החוק. היא מבהירה כי הפירוש המקל אינו בלתי מוגבל, אלא חייב להיות ''סביר'' מבחינת לשון החוק ותכליתו, ופירוש הסותר באופן מובהק את תכלית החוק לא ייבחר, גם אם הוא מקל עם הנאשם.', 'סעיף 34כא לחוק העונשין קובע כי במקרה של ספק, יש לבחור בפירוש המקל ביותר עם הנאשם, אך זאת ''מבין הפירושים הסבירים מבחינת לשון החוק ותכליתו''. חוק העונשין, תשל"ז-1977, סעיף 34כא המשמעות היא שתכלית החוק מהווה גבול עליון לפירוש המקל. אם פירוש מסוים, אף אם הוא מקל עם הנאשם, סותר באופן מובהק את תכלית החוק, הוא אינו נחשב ''סביר'' ולכן לא ניתן לבחור בו. ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015) במצב כזה, יש לבחור בפירוש הסביר האחר, גם אם הוא מחמיר עם המואשם, כל עוד הוא עולה בקנה אחד עם תכלית החוק. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל',
    'הטעות הנפוצה היא להתעלם מהמגבלה של ''תכלית החוק'' על כלל הפירוש המקל, ולחשוב שכל פירוש המקל עם הנאשם הוא קביל, גם אם הוא מרוקן את החוק מתוכנו או סותר את מטרתו.', '["פירוש מקל", "תכלית החוק", "לשון החוק", "פירוש סביר", "חוק העונשין", "הלכת הפרשנות התכליתית"]'::jsonb, '**וריאציה 1 — סתירה ללשון החוק:** פירוש אחד מקל עם המואשם, אך סותר באופן מובהק את לשון החוק. האם ייבחר? ← לא, הפירוש המקל חייב להיות סביר גם מבחינת לשון החוק. חוק העונשין, תשל"ז-1977, סעיף 34כא
**וריאציה 2 — תכלית עונשית:** האם תכלית עונשית (הרתעה, גמול) יכולה להצדיק פירוש מחמיר? ← כן, תכלית החוק כוללת גם תכליות עונשיות, והן חלק ממכלול השיקולים בבחירת הפירוש הסביר. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל
**וריאציה 3 — ספק בתכלית:** אם יש ספק לגבי תכלית החוק עצמה, האם עדיין חל הכלל? ← כן, אם יש ספק סביר לגבי תכלית החוק, יש לבחור בתכלית המצמצמת את היקף האחריות הפלילית. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל', 'פירוש מקל (ס'' 34כא לחוק העונשין) ← מוגבל לפירושים הסבירים מבחינת לשון החוק ותכליתו. פירוש הסותר תכלית אינו סביר.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34כא", "ע\"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026), חוק העונשין, התשל\"ז-1977, עמ'' 10"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'יש לבחור בפירוש המקל ביותר עם המואשם, גם אם הוא סותר את תכלית החוק, שכן זהו כלל יסוד במשפט הפלילי.', false, 'טענה זו שגויה. כלל הפירוש המקל כפוף למגבלת תכלית החוק, ואינו מאפשר פירוש הסותר אותה באופן מובהק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'יש לבחור בפירוש המחמיר עם המואשם, שכן הוא עולה בקנה אחד עם תכלית החוק, וכלל הפירוש המקל חל רק בתוך מתחם הפירושים הסבירים מבחינת תכלית החוק.', true, 'תשובה זו נכונה. כלל הפירוש המקל חל רק בתוך מתחם הפירושים הסבירים מבחינת לשון החוק ותכליתו. פירוש הסותר באופן מובהק את תכלית החוק אינו נחשב ''סביר'', ולכן לא ניתן לבחור בו, גם אם הוא מקל עם הנאשם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'יש להעדיף את הפירוש המקל, אלא אם כן המחוקק קבע במפורש כי תכלית החוק גוברת על כלל הפירוש המקל.', false, 'טענה זו שגויה. תכלית החוק היא חלק אינטגרלי ממגבלות הפירוש המקל, ואין צורך בהוראה מפורשת של המחוקק כדי שתגביל אותו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'יש להכריע את הספק לטובת המדינה, שכן תכלית החוק גוברת על כלל הפירוש המקל.', false, 'טענה זו שגויה. כלל הפירוש המקל אינו נדחה אוטומטית לטובת המדינה, אלא הוא מוגבל לפירושים הסבירים מבחינת תכלית החוק. אם אין פירוש סביר המקל עם הנאשם, אז הפירוש המחמיר יותר הוא זה שייבחר, אך לא בגלל עדיפות גורפת למדינה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פירוש חוק עונשין המשפיע על זכויות קורבן',
    3, 'התעורר ספק באשר לאופן בו יש לפרש סעיף בחוק העונשין הקובע את היקף הפיצויים שניתן לפסוק לקורבן עבירה. פירוש אחד מקל עם הנאשם (ומפחית את הפיצוי), ופירוש שני מחמיר עם הנאשם (ומגדיל את הפיצוי). מה הדין?', 'שאלה זו בוחנת את גבולות תחולתו של כלל הפירוש המקל. היא מדגישה כי הכלל חל על שאלות הנוגעות לאחריות פלילית ולעונש, אך אינו חל באופן אוטומטי על סוגיות אזרחיות במהותן, כגון היקף הפיצויים לקורבן עבירה, גם אם הן מוגדרות בחוק עונשי. במקרים אלו, יש לפרש את החוק בהתאם לתכליתו הספציפית.', 'כלל הפירוש המקל, הקבוע בסעיף 34כא לחוק העונשין, נועד להגן על הנאשם מפני הרשעה או ענישה שאינן ודאיות. הוא חל על שאלות הנוגעות לקיומה של עבירה, ליסודותיה, ולשאלת אחריותו הפלילית של אדם. חוק העונשין, תשל"ז-1977, סעיף 34כא לעומת זאת, סוגיית הפיצויים לקורבן עבירה, גם אם היא מוסדרת בחוק העונשין (כגון סעיף 77 לחוק העונשין), היא סוגיה אזרחית במהותה. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל במקרים אלו, יש לפרש את החוק בהתאם לתכליתו הספציפית, שהיא בדרך כלל הגנה על קורבנות ופיצויים על נזקיהם. לכן, יש לבחור בפירוש המקל ביותר עם קורבן העבירה (המגדיל את הפיצוי), מבין הפירושים הסבירים מבחינת תכלית החוק. ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)',
    'הטעות הנפוצה היא להחיל את כלל הפירוש המקל באופן גורף על כל סעיף בחוק העונשין, מבלי להבחין בין סוגיות פליליות מובהקות (אחריות ועונש) לבין סוגיות אזרחיות (פיצויים לקורבן) המוסדרות בו.', '["פירוש מקל", "זכויות קורבן", "פיצויים", "אחריות פלילית", "תכלית החוק", "חוק העונשין"]'::jsonb, '**וריאציה 1 — סעיף 77 לחוק העונשין:** האם כלל הפירוש המקל חל על סעיף 77 לחוק העונשין (פיצויים לנפגע עבירה)? ← לא, סעיף 77 הוא בעל אופי אזרחי, וכלל הפירוש המקל אינו חל עליו. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל
**וריאציה 2 — חוק זכויות נפגעי עבירה:** האם כלל הפירוש המקל חל על חוק זכויות נפגעי עבירה? ← לא, חוק זה נועד להגן על זכויות הקורבן, ופירושו ייעשה בהתאם לתכלית זו, ולא לטובת הנאשם. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל
**וריאציה 3 — ספק בעונש:** אם יש ספק לגבי גובה העונש שיש להטיל על הנאשם, האם חל כלל הפירוש המקל? ← כן, סעיף 34כא קובע כי ספק יוכרע לטובת הנאשם גם לעניין העונש. חוק העונשין, תשל"ז-1977, סעיף 34כא', 'כלל הפירוש המקל (ס'' 34כא לחוק העונשין) ← חל על אחריות פלילית ועונש. לא חל על פיצויים לקורבן; שם יש לפרש לטובת הקורבן בהתאם לתכלית החוק.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34כא", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026), חוק העונשין, התשל\"ז-1977, עמ'' 11"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'יש לבחור בפירוש המקל ביותר עם הנאשם, שכן זהו כלל יסוד במשפט הפלילי.', false, 'טענה זו שגויה. כלל הפירוש המקל חל על שאלת האחריות הפלילית והעונש, ולא על היקף הפיצויים לקורבן, שהיא סוגיה אזרחית במהותה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'יש לבחור בפירוש המקל ביותר עם קורבן העבירה, שכן תכלית החוק היא להגן על קורבנות.', true, 'תשובה זו נכונה. כלל הפירוש המקל חל על שאלת האחריות הפלילית והעונש. כאשר מדובר בפיצויים לקורבן, יש לפרש את החוק בהתאם לתכליתו להגן על קורבנות, ולכן יש להעדיף את הפירוש המקל עם הקורבן (המגדיל את הפיצוי).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'יש להכריע את הספק לטובת המדינה, שכן מדובר בחוק עונשי.', false, 'טענה זו שגויה. כלל הפירוש המקל אינו נדחה לטובת המדינה, אלא הוא מוגבל לתחום האחריות הפלילית והעונש. סוגיית הפיצויים לקורבן נבחנת לפי עקרונות אחרים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'יש לבחור בפירוש המקל ביותר עם הנאשם מבין הפירושים הסבירים מבחינת תכלית החוק, גם אם זה פוגע בקורבן.', false, 'טענה זו שגויה. כלל הפירוש המקל אינו חל על סוגיית הפיצויים לקורבן, שכן זו אינה שאלה של אחריות פלילית או עונש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'תפקיד דברי ההסבר בחוק עונשין',
    4, 'התעורר ספק באשר לאופן בו יש לפרש את אחד מיסודות העבירה. דברי ההסבר להצעת החוק מבהירים את כוונת המחוקק לפירוש מחמיר עם המואשם, אך לשון החוק מאפשרת גם פירוש מקל. מה הדין?', 'שאלה זו עוסקת בתפקידם של דברי ההסבר להצעת חוק בתהליך הפרשנות של חוק עונשי, ובפרט ביחסם לכלל הפירוש המקל. היא מדגישה כי דברי ההסבר הם כלי חשוב לקביעת תכלית החוק, אשר מגבילה את מתחם הפירושים הסבירים שמהם ניתן לבחור את הפירוש המקל עם הנאשם.', 'הפרשנות התכליתית היא שיטת הפרשנות הדומיננטית במשפט הישראלי, והיא חלה גם על חוקי עונשין. ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015) דברי ההסבר להצעת חוק הם כלי פרשני מרכזי לקביעת תכלית החוק. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל כלל הפירוש המקל, הקבוע בסעיף 34כא לחוק העונשין, קובע כי יש לבחור בפירוש המקל ביותר עם הנאשם, אך זאת ''מבין הפירושים הסבירים מבחינת לשון החוק ותכליתו''. חוק העונשין, תשל"ז-1977, סעיף 34כא אם דברי ההסבר מבהירים את תכלית החוק באופן שמוביל לפירוש מחמיר, ופירוש זה עולה בקנה אחד עם לשון החוק, הרי שהוא ייחשב לפירוש הסביר מבחינת תכלית החוק. במצב כזה, הפירוש המקל שאינו עולה בקנה אחד עם תכלית זו לא ייבחר, שכן הוא אינו ''סביר''. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל',
    'הטעות הנפוצה היא להתעלם מתפקידם של דברי ההסבר ככלי לקביעת תכלית החוק, או לחשוב שכלל הפירוש המקל גובר תמיד על כל אינדיקציה אחרת לכוונת המחוקק, גם אם היא עולה מדברי ההסבר.', '["פירוש מקל", "דברי הסבר", "תכלית החוק", "לשון החוק", "פרשנות תכליתית", "חוק העונשין"]'::jsonb, '**וריאציה 1 — דברי הסבר סותרים:** אם דברי ההסבר סותרים את לשון החוק באופן מובהק, מה גובר? ← לשון החוק גוברת, שכן דברי ההסבר אינם חלק מהחוק עצמו. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל
**וריאציה 2 — תכלית סובייקטיבית מול אובייקטיבית:** האם תכלית החוק היא רק כוונת המחוקק הסובייקטיבית? ← לא, תכלית החוק כוללת גם תכלית אובייקטיבית, המבטאת את ערכי היסוד של השיטה. ע"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)
**וריאציה 3 — חוקים ישנים:** האם דברי הסבר לחוקים ישנים עדיין רלוונטיים? ← כן, אך משקלם עשוי להיות נמוך יותר ככל שהחוק ישן יותר, וייתכן שיתפתחו תכליות אובייקטיביות חדשות. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | כלל הפירוש המקל', 'דברי הסבר ← כלי לקביעת תכלית החוק. תכלית זו מגבילה את הפירוש המקל (ס'' 34כא לחוק העונשין). אם דברי ההסבר מובילים לפירוש מחמיר שהוא סביר, הוא ייבחר.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34כא", "ע\"פ 5767/14 פלוני נ'' מדינת ישראל (16.06.2015)", "נבו - המתמחה, דיני עונשין ודרכי ענישה (2026), חוק העונשין, התשל\"ז-1977, עמ'' 10"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'יש לבחור בפירוש המקל ביותר עם המואשם, שכן דברי ההסבר אינם מחייבים כאשר לשון החוק מאפשרת פירוש אחר.', false, 'טענה זו שגויה. דברי ההסבר הם כלי פרשני חשוב לקביעת תכלית החוק, והם יכולים להשפיע על קביעת מתחם הפירושים הסבירים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'יש לבחור בפירוש המחמיר עם המואשם, שכן דברי ההסבר מבטאים את תכלית החוק, וכלל הפירוש המקל חל רק בתוך מתחם הפירושים הסבירים מבחינת תכלית החוק.', true, 'תשובה זו נכונה. דברי ההסבר הם כלי פרשני מרכזי לקביעת תכלית החוק. אם תכלית החוק, כפי שהיא עולה מדברי ההסבר, מובילה לפירוש מחמיר, ופירוש זה סביר מבחינת לשון החוק, הרי שהוא ייבחר, שכן הפירוש המקל חייב להיות סביר מבחינת תכלית החוק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'יש להכריע את הספק לטובת המדינה, שכן דברי ההסבר משקפים את כוונת המחוקק.', false, 'טענה זו שגויה. דברי ההסבר אינם גוברים באופן אוטומטי על כלל הפירוש המקל, אלא משמשים ככלי לקביעת תכלית החוק, המגבילה את הפירוש המקל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'יש לבחור בפירוש המקל ביותר עם המואשם, אלא אם כן דברי ההסבר אומצו במפורש בחוק עצמו.', false, 'טענה זו שגויה. דברי ההסבר אינם דורשים אימוץ מפורש בחוק כדי לשמש ככלי פרשני לקביעת תכלית החוק.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 15, '2023-S-S-Q15';
END
$$;

