-- Q16 — 2023-S-S-Q16 — chapter=administrative subtopic=planning_building  [needs_review]
-- classifier_note: Section 197 claim for plan damage to property — primarily planning law; tort/nuisance overlap noted in source review_note
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'a2cf4f9d-ed3c-48df-bb6f-f24e618ff8d7'::uuid;
  v_group_id uuid := '8799c18e-a685-43be-85ec-5620ceadeebe'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '7cc5c000-2c0e-4bd1-9eb9-a09d60f46169'::uuid;
  v_ang_1 uuid := 'a8e487ac-e449-4478-a4e9-c3781144a3a9'::uuid;
  v_ang_2 uuid := '1c0e4c71-3b51-4e3f-b361-7a4c62e20a54'::uuid;
  v_ang_3 uuid := 'c8eef259-fb8b-4b0e-a10a-80910baa6600'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q16';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 16, '2023-S-S-Q16';
