  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'administrative';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'administrative';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'planning_building' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'planning_building', 'administrative';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q16', v_chapter_id, v_subtopic_id, 'ביום 1.1.2021 אושרה תוכנית לסלילת כביש רב-נתיבים וסואן. העבודות הסתיימו, והכביש נפתח לתנועה ביום 1.1.2022. ביתו של משה מצוי במגרש הגובל בתחום התוכנית. ביתו של יהודה מצוי במגרש שאינו גובל בתחום התוכנית. משה ויהודה מבקשים לתבוע כעת את הרשות המקומית בתביעה נזיקית שתוגש לבית המשפט המוסמך בגין המטרד שיוצר הרעש העולה מן הכביש. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 16}'::jsonb, 'השאלה עוסקת ביחס שבין תביעת פיצויים מכוח סעיף 197 לחוק התכנון והבניה, תשכ"ה-1965, לבין תביעה נזיקית כללית בגין מטרד. היא בוחנת את הלכת בית המשפט העליון בעניין ''נתיבי ישראל נ'' קטן'', אשר קבעה כי סעיף 197 מהווה הסדר ייחודי ובלעדי למי שמקרקעיו נפגעו על ידי תכנית ונמצאים בתחומה או גובלים עמה, אך אינו חוסם תביעה נזיקית למי שאינו בא בשעריו.', 'סעיף 197(א) לחוק התכנון והבניה, תשכ"ה-1965, קובע כי ''נפגעו על ידי תכנית, שלא בדרך הפקעה, מקרקעין הנמצאים בתחום התכנית או גובלים עמו, מי שביום תחילתה של התכנית היה בעל המקרקעין או בעל זכות בהם זכאי לפיצויים מהוועדה המקומית''. חוק התכנון והבניה, תשכ"ה-1965, סעיף 197(א)

הלכת בית המשפט העליון בעניין רע"א 6483/15 נתיבי ישראל החברה הלאומית לתשתיות תחבורה בע"מ נ'' רות קטן (להלן: ''עניין קטן'') קבעה כי סעיף 197 הוא הסדר ייחודי וממצה. ת"א (שלום חי'') 56313-01-18 דינה סבית יעקוב נ'' חברת י. מאנע ושות בע"מ (02.05.2018)
1. לגבי משה: ביתו של משה מצוי במגרש הגובל בתחום התוכנית. לכן, משה נכנס בגדרי סעיף 197. הפסיקה קבעה כי מי שזכאי לתבוע פיצוי במסגרת סעיף 197, אינו רשאי לבחור אם לתבוע את הוועדה המקומית בהליך נזיקי רגיל או בהליך על-פי סעיף 197; הוא חייב לילך בדרך השנייה, זו שהמחוקק התווה באופן ספציפי. ת"א (שלום חי'') 56313-01-18 דינה סבית יעקוב נ'' חברת י. מאנע ושות בע"מ (02.05.2018) נזק הנובע במישרין מהתכנית (כגון רעש מכביש שאושר בתכנית) אינו יכול להיתבע בתביעה נזיקית על בסיס עוולת המטרד. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018) לכן, משה אינו זכאי לתבוע בתביעה נזיקית.
2. לגבי יהודה: ביתו של יהודה מצוי במגרש שאינו גובל בתחום התוכנית. לכן, יהודה אינו בא בשערי סעיף 197. הפסיקה קבעה כי מי שכלל אינו זכאי להגיש תובענה לפי סעיף 197, פתוחה בפניו האפשרות להגיש תובענה אזרחית על בסיס טענה לקיומו של מטרד. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018) לכן, יהודה זכאי לתבוע בתביעה נזיקית בגין מטרד הרעש.
התוצאה היא שיהודה זכאי לתבוע בתביעה נזיקית, ואילו משה אינו זכאי.
', 'הטעות הנפוצה היא לא להבחין בין בעלי מקרקעין הגובלים בתחום התכנית לבין אלו שאינם גובלים, ולכן ליישם את כלל ייחוד העילה של סעיף 197 באופן גורף על כולם, או לחלופין, לא להכיר כלל בייחוד העילה.',
    '["חוק התכנון והבניה", "סעיף 197", "תביעת פיצויים", "תביעה נזיקית", "עוולת מטרד ליחיד", "מקרקעין גובלים", "הסדר ייחודי", "הלכת רות קטן"]'::jsonb, '**וריאציה 1 — מקרקעין בתוך התכנית:** מה הדין אם ביתו של משה היה מצוי בתוך תחום התכנית? ← הדין זהה למצב של מקרקעין גובלים; משה כפוף להסדר סעיף 197 ואינו יכול לתבוע בנזיקין. חוק התכנון והבניה, תשכ"ה-1965, סעיף 197(א)
**וריאציה 2 — תכנית לצורך פרטי:** מה הדין אם התכנית אושרה לטובת יזם פרטי ולא לצורך ציבורי מובהק? ← כאשר הנהנה המרכזי מאישור התכנית הוא אדם פרטי או יזם עסקי, פוחתת ההצדקה להטיל את חובת הפיצוי על רשות התכנון, ויש היגיון בהסדרת היחסים בין הניזוק והנהנה בפועל באמצעות דיני המטרדים. ת"א (שלום ת"א) 44580-11-13 יורם קלוד אנקרי נ'' מיכאל כהן (15.02.2017)
**וריאציה 3 — נזק שאינו מטרד:** מה הדין אם הנזק ליהודה אינו מטרד אלא נזק אחר שאינו קנייני? ← ניתן לתבוע בתביעה נזיקית פיצוי עבור נזק שסעיף 197 אינו מעניק פיצוי בגינו, אם העוולה הנזיקית אינה עוולה קניינית, אלא מבוססת על התנהגות מעוולת של המזיק, כגון רשלנות או הפרת חובה חקוקה. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018)', 'סעיף 197 לחוק התכנון והבניה הוא הסדר ייחודי למי שמקרקעיו גובלים בתכנית (כמו משה), ומונע תביעה נזיקית על נזקים הנובעים במישרין מהתכנית. למי שאינו גובל (כמו יהודה), פתוחה הדרך לתבוע בנזיקין.', '["חוק התכנון והבניה, תשכ\"ה-1965, סעיף 197", "רע\"א 6483/15 נתיבי ישראל החברה הלאומית לתשתיות תחבורה בע\"מ נ'' רות קטן ואח'' (02.08.2016)", "ת\"א (מחוזי ת\"א) 9310-09-16 בר בריאות ואח'' נ'' נת\"ע - נתיבי תחבורה עירוניים להסעת המונים בע\"מ (12.06.2018)", "ת\"א (שלום חי'') 63418-03-24 הורביץ גרשון נ'' ברק דוד לביא (29.04.2025)", "ת\"א (שלום חי'') 56313-01-18 דינה סבית יעקוב נ'' חברת י. מאנע ושות בע\"מ (02.05.2018)", "ת\"א (שלום ת\"א) 44580-11-13 יורם קלוד אנקרי נ'' מיכאל כהן (15.02.2017)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''administrative'' subtopic=''planning_building'' | classifier_note: Section 197 claim for plan damage to property — primarily planning law; tort/nuisance overlap noted in source review_note | source_review_note: השאלה עוסקת בדיני תכנון ובניה ונזיקין, תחומים שאינם נכללים ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''הליכים'' נבחר כברירת מחדל תחת ''סדר דין אזרחי'' בשל הקשר העקיף להליכים אזרחיים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני תכנון ובניה'' או ''דיני נזיקין'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'משה זכאי לתבוע בתביעה כאמור, ואילו יהודה אינו זכאי.', false, 'טענה זו שגויה. משה, שמקרקעיו גובלים בתחום התכנית, כפוף להסדר הייחודי של סעיף 197 לחוק התכנון והבניה, ואינו יכול לתבוע בנזיקין בגין מטרד הנובע במישרין מהתכנית.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'יהודה זכאי לתבוע בתביעה כאמור, ואילו משה אינו זכאי.', true, 'תשובה זו נכונה. יהודה, שמקרקעיו אינם גובלים בתחום התכנית, אינו בא בשערי סעיף 197 לחוק התכנון והבניה, ולכן פתוחה בפניו האפשרות להגיש תובענה אזרחית על בסיס טענה לקיומו של מטרד. משה, לעומת זאת, כפוף להסדר סעיף 197.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'הן משה הן יהודה זכאים לתבוע בתביעה כאמור.', false, 'טענה זו שגויה. משה, שמקרקעיו גובלים בתחום התכנית, כפוף להסדר הייחודי של סעיף 197 לחוק התכנון והבניה, ואינו יכול לתבוע בנזיקין בגין מטרד הנובע במישרין מהתכנית.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'הן משה הן יהודה אינם זכאים לתבוע בתביעה כאמור.', false, 'טענה זו שגויה. יהודה, שמקרקעיו אינם גובלים בתחום התכנית, אינו בא בשערי סעיף 197 לחוק התכנון והבניה, ולכן פתוחה בפניו האפשרות להגיש תובענה אזרחית על בסיס טענה לקיומו של מטרד.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פיצוי על פגיעה כלכלית עקיפה',
    1, 'לצד ביתו של משה, המצוי במגרש הגובל בתחום התוכנית, פועל עסק למכירת ציוד מיוחד למוזיקאים. עקב הרעש העולה מהכביש, ירדו הכנסות העסק באופן משמעותי. האם משה זכאי לתבוע את הרשות המקומית בתביעה נזיקית בגין אובדן הכנסות העסק?', 'שאלה זו בוחנת את היקף תחולתו של סעיף 197 לחוק התכנון והבניה, ובפרט את ההבחנה בין פגיעה קניינית במקרקעין (ירידת ערך) לבין פגיעה כלכלית או אישית. היא מדגישה כי סעיף 197 אינו מהווה הסדר שלילי המונע תביעה נזיקית בגין נזקים שאינם ברי פיצוי מכוחו, כגון אובדן הכנסות של עסק.', 'סעיף 197 לחוק התכנון והבניה, תשכ"ה-1965, מעניק פיצוי קנייני במהותו על פגיעת הרשות התכנונית בזכות הקניין של בעל מקרקעין, כתוצאה מירידת ערך המקרקעין. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018) הפסיקה קבעה כי סעיף 197 עוסק בפגיעה במקרקעין (בתכונותיהם או בערכם) ולא בפגיעה באדם. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018) נזק כלכלי גרידא, כמו אובדן הכנסות של עסק, אינו מהווה פגיעה במקרקעין במובן סעיף 197. עמ"נ (מינהליים חי'') 73012-10-21 עדו שיפורי רכב בע"מ נ'' ועדה מקומית לתכנון ובנייה פרדס חנה - כרכור (24.03.2022) בעניין ''קטן'' נקבע, שכאשר עילת התביעה אינה מתייחסת לפגיעה קניינית, סעיף 197 אינו מהווה הסדר שלילי המונע את הגשת התובענה. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018) לכן, משה זכאי לתבוע בנזיקין בגין אובדן הכנסות העסק, שכן נזק זה אינו בר פיצוי מכוח סעיף 197. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018)',
    'הטעות הנפוצה היא להניח שסעיף 197 חוסם כל תביעה נזיקית הנובעת מתכנית, גם אם הנזק אינו קנייני במהותו ואינו בר פיצוי מכוח הסעיף.', '["סעיף 197 לחוק התכנון והבניה", "פגיעה במקרקעין", "נזק כלכלי", "אובדן הכנסות", "תביעה נזיקית", "הסדר שלילי"]'::jsonb, '**וריאציה 1 — פגיעה אישית:** מה הדין אם משה סובל מבעיות בריאותיות עקב הרעש? ← סעיף 197 אינו נועד לפצות על פגיעה באדם, ולכן ניתן לתבוע בנזיקין בגין נזקי גוף. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018)
**וריאציה 2 — נזק עקיף מהתכנית:** האם מטרד רעש נחשב לפגיעה עקיפה המזכה בפיצוי לפי סעיף 197? ← כן, מטרד רעש עשוי לפגוע במקרקעין ולהוריד את ערכם, ולכן עשוי לזכות בפיצוי לפי סעיף 197. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018)
**וריאציה 3 — נזק זמני במהלך העבודות:** מה הדין אם הנזק הכלכלי נגרם רק בתקופת סלילת הכביש? ← מטרדים ארעיים שנגרמו בתקופת הוצאת התכנית לפועל אינם זהים למטרדים שהתכנית יוצרת, וניתן לתבוע בגינם בתביעה נזיקית. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018)', 'סעיף 197 לחוק התכנון והבניה מפצה על פגיעה קניינית במקרקעין (ירידת ערך), לא על נזק כלכלי או אישי. בגין נזקים אלו, ניתן לתבוע בנזיקין.',
    '["חוק התכנון והבניה, תשכ\"ה-1965, סעיף 197", "ת\"א (מחוזי ת\"א) 9310-09-16 בר בריאות ואח'' נ'' נת\"ע - נתיבי תחבורה עירוניים להסעת המונים בע\"מ (12.06.2018)", "עמ\"נ (מינהליים חי'') 73012-10-21 עדו שיפורי רכב בע\"מ נ'' ועדה מקומית לתכנון ובנייה פרדס חנה - כרכור (24.03.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'משה אינו זכאי לתבוע, שכן סעיף 197 לחוק התכנון והבניה מהווה הסדר שלילי המונע תביעה נזיקית בגין כל נזק הנובע מהתכנית.', false, 'טענה זו שגויה. סעיף 197 אינו מהווה הסדר שלילי המונע תביעה נזיקית כאשר עילת התביעה אינה מתייחסת לפגיעה קניינית במקרקעין, אלא לנזק כלכלי או אישי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'משה זכאי לתבוע, שכן סעיף 197 לחוק התכנון והבניה אינו מעניק פיצוי בגין נזק כלכלי לאובדן הכנסות, ולכן אינו חוסם תביעה נזיקית בגין ראש נזק זה.', true, 'תשובה זו נכונה. סעיף 197 לחוק התכנון והבניה נועד לפצות על פגיעה קניינית במקרקעין (ירידת ערך), ולא על פגיעה באדם או נזק כלכלי גרידא כמו אובדן הכנסות. לכן, בגין נזקים אלו, סעיף 197 אינו מהווה הסדר שלילי, וניתן לתבוע בנזיקין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'משה זכאי לתבוע, אך רק אם יוכיח שהרשות פעלה ברשלנות חמורה באישור התכנית.', false, 'טענה זו שגויה. הזכאות לתבוע בגין אובדן הכנסות אינה תלויה בהוכחת רשלנות חמורה באישור התכנית, אלא בכך שסעיף 197 אינו מכסה ראש נזק זה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'משה אינו זכאי לתבוע, שכן היה עליו להגיש התנגדות לתכנית במועד, ומשלא עשה כן, הוא מנוע מלתבוע.', false, 'טענה זו שגויה. חובת הגשת התנגדות לתכנית רלוונטית לטענות על עצם אישור התכנית, אך אינה חוסמת תביעה בגין נזקים שאינם ברי פיצוי לפי סעיף 197, כמו אובדן הכנסות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן ''מקרקעין גובלים'' בסעיף 197',
    2, 'ביתו של ראובן מופרד מתחום התוכנית על ידי שטח פתוח צר ברוחב 2 מטרים. האם מקרקעיו של ראובן ייחשבו כ''גובלים'' בתחום התוכנית לצורך סעיף 197 לחוק התכנון והבניה?', 'שאלה זו עוסקת בפרשנות המונח ''מקרקעין גובלים'' בסעיף 197(א) לחוק התכנון והבניה, שהוא תנאי סף לזכאות לפיצוי מכוח הסעיף. היא מתמקדת בהלכה הפסוקה, ובפרט בהלכת ויטנר, שהרחיבה את הפרשנות מעבר להשקה פיזית ישירה, וכללה גם מקרים של הפרעה על ידי שטח פתוח צר או כביש שכונתי צר.', 'סעיף 197(א) לחוק התכנון והבניה קובע זכאות לפיצויים למי שנפגעו מקרקעיו על ידי תכנית, כאשר המקרקעין ''נמצאים בתחום התכנית או גובלים עמו''. חוק התכנון והבניה, תשכ"ה-1965, סעיף 197(א) בית המשפט העליון, בשבתו כערכאת ערעור מנהלי, קבע במסגרת עע"מ 2775/01 שרגא ויטנר נ'' הוועדה המקומית לתכנון ובנייה ''שרונים'' (להלן: ''פסק דין ויטנר'') כי ככלל, מקרקעין ייחשבו כגובלים כאשר הם משיקים פיזית ל''קו הכחול'' של התכנית. עם זאת, נקבע חריג לפיו ''כאשר ההשקה בין התכנית למקרקעין מופרעת על ידי שטח פתוח צר, בדרך כלל בן מטרים ספורים בלבד, או על ידי כביש שכונתי צר, לא יהא בכך כדי לשלול את מעמדם של המקרקעין כ''מקרקעין גובלים'' בתכנית''. ת"א (שלום ת"א) 44000-02-23 אברהם ציון נ'' מדינת ישראל משרד התחבורה, התשתיות הלאומיות והבטיחות דרכים (17.01.2024) במקרה הנדון, שטח פתוח צר ברוחב 2 מטרים מפריד בין ביתו של ראובן לתחום התוכנית. מרחק זה נופל להגדרה של ''מטרים ספורים'' כפי שנקבע בפסק דין ויטנר. לכן, מקרקעיו של ראובן ייחשבו כגובלים בתחום התוכנית לצורך סעיף 197.',
    'הטעות הנפוצה היא לפרש את המונח ''גובלים'' באופן דווקני וצר, כדורש השקה פיזית ישירה, מבלי להכיר בחריגים שנקבעו בפסיקה לעניין שטחים פתוחים צרים או כבישים שכונתיים צרים.', '["סעיף 197 לחוק התכנון והבניה", "מקרקעין גובלים", "הקו הכחול", "שטח פתוח צר", "כביש שכונתי צר", "הלכת ויטנר"]'::jsonb, '**וריאציה 1 — כביש רחב:** מה הדין אם כביש רב-נתיבים רחב מפריד בין המקרקעין לתכנית? ← במקרה כזה, המקרקעין לא ייחשבו כגובלים, שכן החריג חל רק על כביש שכונתי צר. ת"א (שלום ת"א) 44000-02-23 אברהם ציון נ'' מדינת ישראל משרד התחבורה, התשתיות הלאומיות והבטיחות דרכים (17.01.2024)
**וריאציה 2 — שטח פתוח רחב:** מה הדין אם שטח פתוח רחב (למשל, פארק) מפריד בין המקרקעין לתכנית? ← במקרה כזה, המקרקעין לא ייחשבו כגובלים, שכן החריג חל רק על שטח פתוח צר. ת"א (שלום ת"א) 44000-02-23 אברהם ציון נ'' מדינת ישראל משרד התחבורה, התשתיות הלאומיות והבטיחות דרכים (17.01.2024)
**וריאציה 3 — מקרקעין בתוך התכנית:** מה הדין אם המקרקעין נמצאים בתוך תחום התכנית עצמה? ← מקרקעין הנמצאים בתחום התכנית זכאים לפיצוי לפי סעיף 197, ללא קשר לשאלת הגבול. חוק התכנון והבניה, תשכ"ה-1965, סעיף 197(א)', 'מקרקעין ''גובלים'' (ס'' 197 לחוק התכנון והבניה) ← כוללים השקה פיזית ל''קו הכחול'', וגם מקרים בהם מפריד שטח פתוח צר או כביש שכונתי צר.',
    '["חוק התכנון והבניה, תשכ\"ה-1965, סעיף 197", "ת\"א (שלום ת\"א) 44000-02-23 אברהם ציון נ'' מדינת ישראל משרד התחבורה, התשתיות הלאומיות והבטיחות דרכים (17.01.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'לא, שכן ''גובלים'' משמעו השקה פיזית ישירה ל''קו הכחול'' של התוכנית.', false, 'טענה זו שגויה. הפסיקה הרחיבה את הפרשנות ל''גובלים'' וכללה גם מקרים של הפרעה על ידי שטח פתוח צר או כביש שכונתי צר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כן, שכן הפסיקה קבעה כי שטח פתוח צר או כביש שכונתי צר אינם שוללים את מעמד המקרקעין כ''גובלים''.', true, 'תשובה זו נכונה. בית המשפט העליון קבע בהלכת ויטנר כי מקרקעין ייחשבו כגובלים גם כאשר ההשקה מופרעת על ידי שטח פתוח צר (מטרים ספורים) או כביש שכונתי צר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'לא, אלא אם כן שר הפנים יאשר במפורש כי מדובר במקרקעין גובלים.', false, 'טענה זו שגויה. שר הפנים מוסמך להאריך את תקופת ההתיישנות להגשת תביעה לפי סעיף 197, אך לא לקבוע את הגדרת ''מקרקעין גובלים''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'כן, אך רק אם יוכיח ראובן כי נגרם לו נזק חמור במיוחד.', false, 'טענה זו שגויה. הגדרת ''מקרקעין גובלים'' היא עניין עובדתי-משפטי שאינו תלוי בחומרת הנזק, אלא בקרבה הפיזית ובהלכה הפסוקה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'תביעה נזיקית במקרה של רשלנות הרשות',
    3, 'נניח שביתה של שרה גובל בתחום התוכנית. הרעש מהכביש נגרם לא רק מעצם סלילתו, אלא גם עקב רשלנות חמורה של הרשות המקומית בביצוע עבודות הסלילה (למשל, אי-הקמת קירות אקוסטיים שהובטחו). האם שרה זכאית לתבוע את הרשות המקומית בתביעה נזיקית בגין מטרד הרעש?', 'שאלה זו עוסקת בחריג לכלל ייחוד העילה של סעיף 197 לחוק התכנון והבניה, המאפשר הגשת תביעה נזיקית במקרים בהם הנזק אינו נובע במישרין מהתכנית עצמה, אלא מהתנהגות מעוולת של הרשות, כגון רשלנות או הפרת חובה חקוקה, באופן ביצוע התכנית. היא מדגישה את ההבחנה בין ''נזק תכנוני'' ל''נזק ביצועי''.', 'הכלל הוא שמי שיכול היה לתבוע פיצוי במסגרת סעיף 197 לחוק התכנון והבניה ולא עשה כן, מנוע מלתבוע אותו פיצוי בתביעה נזיקית. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018) אולם, הפסיקה קבעה חריגים לכלל זה. ניתן לתבוע בתביעה נזיקית פיצוי עבור נזק שסעיף 197 אינו מעניק פיצוי בגינו, אם העוולה הנזיקית אינה עוולה קניינית, אלא מבוססת על התנהגות מעוולת של המזיק, כגון רשלנות או הפרת חובה חקוקה. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018) במקרה הנדון, הרעש נובע לא רק מעצם סלילת הכביש (הנובע מהתכנית), אלא גם מרשלנות בביצוע העבודות (אי-הקמת קירות אקוסטיים). נזקים אלו אינם נובעים במישרין מהתכנית, אלא מאופן יישומה. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018) לכן, שרה זכאית לתבוע את הרשות המקומית בתביעה נזיקית בגין רשלנות בביצוע העבודות. ע"א (מחוזי י-ם) 26856-12-18 בני כהן נכסים בניין ופיתוח 1999 בע"מ נ'' שלמה ירדני (21.11.2019)',
    'הטעות הנפוצה היא לא להבחין בין נזקים הנובעים מעצם אישור התכנית (הכפופים לסעיף 197) לבין נזקים הנובעים מרשלנות בביצוע התכנית, אשר פתוחים לתביעה נזיקית.', '["סעיף 197 לחוק התכנון והבניה", "תביעה נזיקית", "רשלנות", "הפרת חובה חקוקה", "אופן ביצוע התכנית", "נזק תכנוני", "נזק ביצועי"]'::jsonb, '**וריאציה 1 — רשלנות באישור התכנית:** מה הדין אם הרשלנות הייתה באישור התכנית עצמה? ← ככלל, יש להעלות טענות בדבר רשלנות בהליך התכנון במסגרת ההליך התכנוני (התנגדות), ורק במקרים חריגים תותר העלאת טענה ממין זה במסגרת הליך נזיקי מאוחר. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018)
**וריאציה 2 — אי-יידוע על התכנית:** מה הדין אם הרשות לא יידעה את שרה על התכנית, ובשל כך היא לא יכלה להגיש תביעה לפי סעיף 197? ← במקרה כזה, קמה לשרה הזכות להגיש תביעה נזיקית עצמאית, בין השאר בעילה של הפרת חובה חקוקה. ת"א (מחוזי חי'') 27142-06-18 עיזבון המנוח נואף אבראהים נ'' הוועדה המקומית לתכנון ובניה בקעת בית הכרם (10.11.2019)
**וריאציה 3 — נזק שאינו בר פיצוי לפי סעיף 197:** מה הדין אם הנזק שנגרם לשרה אינו בר פיצוי לפי סעיף 197 (למשל, נזק כלכלי גרידא)? ← ניתן לתבוע בתביעה נזיקית פיצוי עבור נזק שסעיף 197 אינו מעניק פיצוי בגינו. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018)', 'נזקים הנובעים מרשלנות בביצוע תכנית (ולא מאישורה) ← אינם נכללים בהסדר סעיף 197 לחוק התכנון והבניה, וניתן לתבוע בגינם בתביעה נזיקית.',
    '["חוק התכנון והבניה, תשכ\"ה-1965, סעיף 197", "ת\"א (מחוזי ת\"א) 9310-09-16 בר בריאות ואח'' נ'' נת\"ע - נתיבי תחבורה עירוניים להסעת המונים בע\"מ (12.06.2018)", "ע\"א (מחוזי י-ם) 26856-12-18 בני כהן נכסים בניין ופיתוח 1999 בע\"מ נ'' שלמה ירדני (21.11.2019)", "ת\"א (מחוזי חי'') 27142-06-18 עיזבון המנוח נואף אבראהים נ'' הוועדה המקומית לתכנון ובניה בקעת בית הכרם (10.11.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, שכן סעיף 197 לחוק התכנון והבניה מהווה הסדר ייחודי ומונע כל תביעה נזיקית בגין נזקים הנובעים מתכנית שאושרה.', false, 'טענה זו שגויה. סעיף 197 חוסם תביעות נזיקיות בגין נזקים הנובעים במישרין מהתכנית עצמה, אך לא בגין נזקים הנובעים מרשלנות בביצועה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, שכן נזקים הנובעים מרשלנות בביצוע התכנית אינם נכללים בהסדר סעיף 197, וניתן לתבוע בגינם בנזיקין.', true, 'תשובה זו נכונה. הפסיקה מבחינה בין נזקים הנובעים במישרין מהתכנית (הכפופים לסעיף 197) לבין נזקים הנובעים מהתרשלות באופן ביצוע התכנית. בגין האחרונים, ניתן להגיש תביעה נזיקית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם שרה הוכיחה כי הגישה התנגדות לתכנית במועד, וזו נדחתה שלא כדין.', false, 'טענה זו שגויה. הזכאות לתבוע בגין רשלנות בביצוע אינה תלויה בהגשת התנגדות לתכנית, שכן ההתנגדות מתייחסת לעצם אישור התכנית ולא לאופן ביצועה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן הרשלנות של הרשות המקומית הגיעה לכדי הפרת חובה חקוקה.', false, 'טענה זו שגויה. רשלנות כשלעצמה היא עוולה נזיקית המאפשרת תביעה, ואין צורך להוכיח הפרת חובה חקוקה בנוסף.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'התיישנות בתביעות לפי סעיף 197',
    4, 'ביתו של משה גובל בתחום התוכנית. התוכנית אושרה ביום 1.1.2021. משה הגיש תביעה נזיקית בגין מטרד הרעש ביום 1.2.2024. האם תביעתו של משה תידחה על הסף מחמת התיישנות?', 'שאלה זו עוסקת בתקופת ההתיישנות הייחודית הקבועה בסעיף 197(ב) לחוק התכנון והבניה, ובמשמעותה לעניין הגשת תביעות פיצויים. היא מדגישה כי תקופה זו קצרה יותר מתקופת ההתיישנות הכללית בדיני הנזיקין, וכי חלוף המועד חוסם הגשת תביעה נזיקית על אותם נזקים, למעט חריגים מסוימים.', 'סעיף 197(ב) לחוק התכנון והבניה קובע כי ''התביעה לפיצויים תוגש למשרדי הוועדה המקומית תוך שלוש שנים מיום תחילת תקפה של התכנית''. חוק התכנון והבניה, תשכ"ה-1965, סעיף 197(ב) תקופה זו נועדה לאזן בין זכות הקניין של הפרט לבין הצורך בוודאות תקציבית של רשויות התכנון. ת"א (מחוזי י-ם) 17861-02-18 חיים שטרן נ'' הועדה המקומית לתכנון ולבניה הראל (12.04.2022) הפסיקה קבעה כי מי שיכול היה לתבוע פיצוי במסגרת סעיף 197 ולא עשה כן, מנוע מלתבוע אותו פיצוי בתביעה נזיקית, גם בחלוף תקופת ההתיישנות. ת"א (שלום חי'') 56313-01-18 דינה סבית יעקוב נ'' חברת י. מאנע ושות בע"מ (02.05.2018) במקרה הנדון, התכנית אושרה ב-1.1.2021, ומשה הגיש תביעה ב-1.2.2024. תקופת 3 השנים חלפה, ולכן תביעתו תידחה מחמת התיישנות. ת"א (מחוזי י-ם) 17861-02-18 חיים שטרן נ'' הועדה המקומית לתכנון ולבניה הראל (12.04.2022)',
    'הטעות הנפוצה היא להחיל את תקופת ההתיישנות הכללית של דיני הנזיקין (7 שנים) על תביעות הנופלות בגדר סעיף 197, או לחשוב שמטרד רעש הוא תמיד עוולה מתמשכת המאריכה את תקופת ההתיישנות.', '["סעיף 197 לחוק התכנון והבניה", "התיישנות", "תקופת התיישנות", "מיצוי עילה", "תביעה נזיקית", "עוולה מתמשכת"]'::jsonb, '**וריאציה 1 — הארכת מועד:** האם ניתן להאריך את תקופת ההתיישנות? ← כן, שר הפנים רשאי להאריך את התקופה מטעמים מיוחדים שיירשמו, אף אם כבר עברה התקופה. חוק התכנון והבניה, תשכ"ה-1965, סעיף 197(ב)
**וריאציה 2 — אי-ידיעה על התכנית:** מה הדין אם משה לא ידע ולא יכול היה לדעת על התכנית? ← גם במקרה זה, המזור יימצא בהארכת תקופת ההתיישנות הנקובה בסעיף, ולא בהגשת תביעה נזיקית במסלול עוקף. ת"א (שלום נצ'') 29908-10-14 חסן עלם אלדין אבו סאלח נ'' אחמד סבאע ובניו בע"מ (08.04.2020)
**וריאציה 3 — נזק שאינו בר פיצוי לפי סעיף 197:** מה הדין אם הנזק שנגרם למשה אינו בר פיצוי לפי סעיף 197 (למשל, נזק כלכלי גרידא)? ← ניתן לתבוע בתביעה נזיקית פיצוי עבור נזק שסעיף 197 אינו מעניק פיצוי בגינו, ועל נזק זה לא תחול תקופת ההתיישנות של סעיף 197. ת"א (מחוזי ת"א) 9310-09-16 בר בריאות ואח'' נ'' נת"ע - נתיבי תחבורה עירוניים להסעת המונים בע"מ (12.06.2018)', 'תקופת ההתיישנות לפי סעיף 197(ב) לחוק התכנון והבניה היא 3 שנים מיום תחילת תוקף התכנית. חלוף המועד חוסם תביעה נזיקית על אותם נזקים, למעט חריגים (כגון נזקים שאינם ברי פיצוי לפי הסעיף או מחדל הרשות ליידע).',
    '["חוק התכנון והבניה, תשכ\"ה-1965, סעיף 197", "ת\"א (מחוזי י-ם) 17861-02-18 חיים שטרן נ'' הועדה המקומית לתכנון ולבניה הראל (12.04.2022)", "ת\"א (שלום חי'') 56313-01-18 דינה סבית יעקוב נ'' חברת י. מאנע ושות בע\"מ (02.05.2018)", "ת\"א (מחוזי ת\"א) 9310-09-16 בר בריאות ואח'' נ'' נת\"ע - נתיבי תחבורה עירוניים להסעת המונים בע\"מ (12.06.2018)", "ת\"א (שלום נצ'') 29908-10-14 חסן עלם אלדין אבו סאלח נ'' אחמד סבאע ובניו בע\"מ (08.04.2020)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, שכן תקופת ההתיישנות בתביעות נזיקין היא 7 שנים, וטרם חלפה.', false, 'טענה זו שגויה. כאשר הנזק בר פיצוי לפי סעיף 197, חלה תקופת ההתיישנות הקצרה של סעיף זה, ולא תקופת ההתיישנות הכללית של דיני הנזיקין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, שכן תקופת ההתיישנות להגשת תביעה לפי סעיף 197 לחוק התכנון והבניה היא 3 שנים מיום תחילת תוקף התכנית, ומועד זה חלף.', true, 'תשובה זו נכונה. סעיף 197(ב) קובע תקופת התיישנות של 3 שנים. משה, שמקרקעיו גובלים בתחום התכנית, כפוף להסדר זה, ומשחלפו 3 שנים מיום אישור התכנית, תביעתו תידחה מחמת התיישנות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, שכן מטרד רעש נחשב לעוולה מתמשכת, ולכן תקופת ההתיישנות מתחדשת מדי יום.', false, 'טענה זו שגויה. הפסיקה קבעה כי נזק הנובע במישרין מתכנית שאושרה אינו נחשב לעוולה מתמשכת לעניין סעיף 197, אלא מתגבש עם אישור התכנית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם הרשות המקומית תוכיח כי משה ידע על התכנית במועד אישורה.', false, 'טענה זו שגויה. תקופת ההתיישנות לפי סעיף 197(ב) היא מוחלטת ואינה תלויה בידיעת הנפגע על התכנית, אלא אם כן מדובר בחריג של מחדל הרשות ליידע.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 16, '2023-S-S-Q16';
END
$$;

-- ============================================================
-- Q17 — 2023-S-S-Q17 — chapter=criminal_substantive subtopic=sentencing
-- classifier_note: Criminal court ordering compensation to victim's children under פקודת העונשין — restitution/sentencing
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'd8f70a2e-5777-4b2c-9374-7ac6a3cd2671'::uuid;
  v_group_id uuid := 'e6156577-7712-4ac7-bff8-5928cbe41727'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '8bfb6b15-7be5-400a-8f64-a83bd2e0ca73'::uuid;
  v_ang_1 uuid := '7d54d72c-1fc6-49da-9736-4ecee51af708'::uuid;
  v_ang_2 uuid := '51d55f6b-c41c-4e5c-9c81-bcf08b0214c3'::uuid;
  v_ang_3 uuid := '0a64b1df-1ddb-4be3-8ed7-cb7c1431a96c'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q17';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 17, '2023-S-S-Q17';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'sentencing' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'sentencing', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q17', v_chapter_id, v_subtopic_id, 'שמעון הורשע ברצח משה. מותו של משה גרם נזק נפשי ניכר לילדיו. במסגרת התיק הפלילי דרשה התביעה שכל אחד מן הילדים יקבל את הפיצוי המקסימלי שמאפשר חוק העונשין למי שניזוק מעבירה. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 17}'::jsonb, 'השאלה עוסקת בפרשנות סעיף 77 לחוק העונשין, תשל"ז-1977, העוסק בפסיקת פיצויים לנפגעי עבירה במסגרת ההליך הפלילי. היא מתמקדת בסוגיית תקרת הפיצוי במצב של ריבוי ניזוקים עקיפים, ובפרט בהלכה שנקבעה ב`דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה`, לפיה עבור ניזוקים עקיפים שהם בני משפחה מדרגה ראשונה, תקרת הפיצוי חלה על כלל הניזוקים יחד, והסכום מתחלק ביניהם.', 'סעיף 77(א) לחוק העונשין, תשל"ז-1977, קובע כי ''הורשע אדם, רשאי בית המשפט לחייבו, בשל כל אחת מן העבירות שהורשע בהן, לשלם לאדם שניזוק על ידי העבירה סכום שלא יעלה על 258,000 שקלים חדשים לפיצוי הנזק או הסבל שנגרם לו''. חוק העונשין, תשל"ז-1977, סעיף 77(א)
השאלה המרכזית שנדונה ב`דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה` (להלן: דנ"פ טווק) הייתה האם תקרת הפיצוי הקבועה בסעיף 77 חלה על כל ניזוק בנפרד, או על כלל הניזוקים יחד. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)
בית המשפט העליון, ברוב דעות (מפי השופטת א'' חיות, בהסכמת השופטים י'' עמית, א'' שהם וד'' ברק-ארז), קבע כי יש להרחיב את מעגל הזכאים לפיצוי בהליך הפלילי מכוח סעיף 77 לחוק העונשין כך שיכלול גם ניזוקים עקיפים שהם בני משפחה מדרגה ראשונה ובכל סוגי העבירות. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017) עם זאת, נקבע כי סכום הפיצוי שניזוקים עקיפים אלה זכאים לקבל, כולם יחד, יוגבל לכדי סכום התקרה הסטטוטורית הקבועה בסעיף (כיום 258,000 ש"ח). דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)
במקרה הנדון, ילדיו של משה הם ניזוקים עקיפים שהם בני משפחה מדרגה ראשונה. לכן, הם יקבלו יחד את סכום הפיצוי המקסימלי שמאפשר חוק העונשין (258,000 ש"ח), והוא יתחלק ביניהם. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ח. תקרת הפיצוי במצב של ריבוי נפגעים', 'הטעות הנפוצה היא להניח שתקרת הפיצוי חלה על כל ניזוק בנפרד, גם כאשר מדובר בניזוקים עקיפים, ובכך להתעלם מההבחנה שנקבעה בפסיקה בין ניזוקים ישירים לעקיפים לעניין זה.',
    '["סעיף 77 לחוק העונשין", "פיצוי לנפגע עבירה", "תקרת פיצוי", "ניזוק ישיר", "ניזוק עקיף", "בני משפחה מדרגה ראשונה", "דנ\"פ טווק", "תקרה נחלקת"]'::jsonb, '**וריאציה 1 — ניזוק ישיר:** מה הדין אם משה היה נשאר בחיים וסבל מנזק נפשי, והיו לו גם ילדים שסבלו? ← משה כניזוק ישיר היה זכאי לפיצוי עד לתקרה, וילדיו כניזוקים עקיפים היו זכאים יחד לסכום נוסף עד לתקרה, אך רק בעבירות המתה. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)
**וריאציה 2 — ילדים קטינים:** האם יש חריג לכלל התקרה הנחלקת במקרה של ילדים קטינים? ← כן, במצב בו המנוח השאיר אחריו ילדים קטינים, ניתן לשלם לכל ילד קטין, בנוסף לסכום שניתן לפסוק לזכות המשפחה, סכום שלא יעלה על הסכום המקסימלי הקבוע בסעיף. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)
**וריאציה 3 — תביעה אזרחית:** האם פסיקת פיצוי בהליך הפלילי מונעת הגשת תביעה אזרחית? ← לא, הפיצוי בהליך הפלילי הוא ראשוני ואינו מונע הגשת תביעה אזרחית, אך סכום הפיצוי הפלילי יקוזז מהפיצוי האזרחי. ע"פ 1076/15 אבנר טווק נ'' מדינת ישראל (07.06.2016)', 'במקרה של ריבוי ניזוקים עקיפים (בני משפחה מדרגה ראשונה) מעבירת המתה, סכום הפיצוי המקסימלי לפי סעיף 77 לחוק העונשין חל על כולם יחד ומתחלק ביניהם (תקרה נחלקת), למעט חריג של ילדים קטינים.', '["חוק העונשין, תשל\"ז-1977, סעיף 77", "דנ\"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)", "ע\"פ 1076/15 אבנר טווק נ'' מדינת ישראל (07.06.2016)", "יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ח. תקרת הפיצוי במצב של ריבוי נפגעים"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''חזרה מאישום'' → mapped chapter=''criminal_substantive'' subtopic=''sentencing'' | classifier_note: Criminal court ordering compensation to victim''s children under פקודת העונשין — restitution/sentencing | source_review_note: השאלה עוסקת בדיני עונשין מהותיים, תחום שאינו נכלל ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''חזרה מאישום'' נבחר כברירת מחדל תחת ''סדר דין פלילי'' בשל הקשר העקיף להליכים פליליים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני עונשין'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ילדיו של משה יקבלו יחד פעם אחת את סכום הפיצוי המקסימלי שמאפשר חוק העונשין למי שניזוק מעבירה והוא יתחלק ביניהם.', true, 'תשובה זו נכונה. על פי הלכת דנ"פ טווק, כאשר מדובר בניזוקים עקיפים (כמו ילדי הנרצח), תקרת הפיצוי הקבועה בסעיף 77 לחוק העונשין חלה על כלל הניזוקים העקיפים יחד, והסכום מתחלק ביניהם.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'כל אחד מילדיו של משה יקבל את סכום הפיצוי המקסימלי שמאפשר חוק העונשין למי שניזוק מעבירה.', false, 'טענה זו שגויה. הלכת דנ"פ טווק קבעה כי תקרת הפיצוי חלה על כלל הניזוקים העקיפים יחד, ולא על כל אחד מהם בנפרד.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'חוק העונשין מעניק פיצוי רק למי שניזוק באופן ישיר מעבירה, ומאחר שמשה מת לא ניתן לפסוק פיצוי זה.', false, 'טענה זו שגויה. הפסיקה הרחיבה את מעגל הזכאים לפיצוי לפי סעיף 77 גם לניזוקים עקיפים שהם בני משפחה מדרגה ראשונה, וכן לעזבון במקרה של עבירת המתה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'חוק העונשין מעניק פיצוי רק למי שניזוק באופן ישיר מעבירה, ולפיכך ניתן לפסוק פיצוי רק לטובת עזבונו של משה.', false, 'טענה זו שגויה. בעבירות המתה, ניתן לפסוק פיצוי הן לעזבון והן לניזוקים עקיפים שהם בני משפחה מדרגה ראשונה, בכפוף למגבלת התקרה הכוללת לניזוקים העקיפים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'מעגל הזכאים לפיצוי: ניזוקים עקיפים שאינם בני משפחה מדרגה ראשונה',
    1, 'ראובן הורשע בגרימת חבלה חמורה לשמעון. חבר קרוב של שמעון, לוי, סבל מנזק נפשי קשה בעקבות האירוע. האם לוי זכאי לפיצוי מכוח סעיף 77 לחוק העונשין?', 'שאלה זו בוחנת את היקף מעגל הזכאים לפיצוי מכוח סעיף 77 לחוק העונשין, ובפרט את הגבולות שנקבעו בפסיקה לעניין ניזוקים עקיפים. היא מדגישה כי למרות הרחבת מעגל הזכאים, הוא עדיין מוגבל לבני משפחה מדרגה ראשונה של קורבן העבירה.', 'סעיף 77(א) לחוק העונשין, תשל"ז-1977, מאפשר לבית המשפט לחייב נאשם שהורשע לשלם פיצוי ל''אדם שניזוק על ידי העבירה''. חוק העונשין, תשל"ז-1977, סעיף 77(א) הפסיקה, ובפרט דעת הרוב ב`דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה` (להלן: דנ"פ טווק), הרחיבה את מעגל הזכאים לפיצוי כך שיכלול גם ניזוקים עקיפים שהם בני משפחה מדרגה ראשונה של קורבן העבירה, ובכל סוגי העבירות. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017) עם זאת, הרחבה זו אינה בלתי מוגבלת. השופט י'' עמית, שהצטרף לדעת הרוב בדנ"פ טווק, הבהיר כי ככלל, ראוי להכיר בבני משפחה מדרגה ראשונה כניזוקים עקיפים, אך ניתן להכיר במקרים חריגים גם בניזוקים עקיפים שאינם משתייכים למעגל המשפחתי הראשון. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017) במקרה הנדון, לוי הוא חבר קרוב של שמעון, אך אינו בן משפחה מדרגה ראשונה. לכן, הוא אינו נכלל במעגל הזכאים לפיצוי כניזוק עקיף מכוח סעיף 77 לחוק העונשין, אלא אם כן יוכח מקרה חריג במיוחד. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ד. הסמכות לפסוק פיצוי',
    'הטעות הנפוצה היא להניח שכל מי שסבל מנזק נפשי עקב עבירה זכאי לפיצוי לפי סעיף 77, מבלי להכיר במגבלת הקרבה המשפחתית שנקבעה בפסיקה.', '["סעיף 77 לחוק העונשין", "ניזוק עקיף", "בני משפחה מדרגה ראשונה", "מעגל זכאים", "דנ\"פ טווק", "נזק נפשי"]'::jsonb, '**וריאציה 1 — בן זוג:** ראובן הורשע בתקיפת שמעון. בת זוגו של שמעון סבלה מנזק נפשי. האם היא זכאית לפיצוי? ← כן, בת זוג נחשבת לבן משפחה מדרגה ראשונה וזכאית לפיצוי כניזוק עקיף. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)
**וריאציה 2 — עבירת המתה:** ראובן הורשע ברצח שמעון. חבר קרוב של שמעון סבל מנזק נפשי. האם הוא זכאי לפיצוי? ← לא, גם בעבירות המתה, מעגל הניזוקים העקיפים מוגבל לבני משפחה מדרגה ראשונה. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)
**וריאציה 3 — ניזוק עקיף חריג:** באילו מקרים חריגים ניתן להכיר בניזוקים עקיפים שאינם בני משפחה מדרגה ראשונה? ← הפסיקה לא פירטה מקרים אלו, אך השאירה פתח למקרים חריגים במיוחד, תוך איזון בין הצורך להרחיב את מעגל הזכאים לבין הפגיעה בנאשם. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)', 'מעגל הניזוקים העקיפים הזכאים לפיצוי לפי סעיף 77 לחוק העונשין ← מוגבל לבני משפחה מדרגה ראשונה בלבד (למעט חריגים נדירים).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 77", "דנ\"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)", "יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ד. הסמכות לפסוק פיצוי"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, שכן סעיף 77 לחוק העונשין מאפשר פסיקת פיצוי לכל אדם שניזוק מהעבירה, ללא הגבלת קרבה משפחתית.', false, 'טענה זו שגויה. הפסיקה הגבילה את מעגל הניזוקים העקיפים הזכאים לפיצוי לפי סעיף 77 לבני משפחה מדרגה ראשונה בלבד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, שכן מעגל הניזוקים העקיפים הזכאים לפיצוי לפי סעיף 77 מוגבל לבני משפחה מדרגה ראשונה בלבד.', true, 'תשובה זו נכונה. על פי הלכת דנ"פ טווק, מעגל הניזוקים העקיפים הזכאים לפיצוי מכוח סעיף 77 לחוק העונשין הורחב לבני משפחה מדרגה ראשונה בלבד, ולא כולל חברים קרובים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם יוכיח לוי כי נגרמה לו נכות נפשית קבועה בשיעור גבוה.', false, 'טענה זו שגויה. הזכאות לפיצוי לפי סעיף 77 אינה מחייבת הוכחת נכות נפשית קבועה, אך מעגל הזכאים מוגבל לבני משפחה מדרגה ראשונה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן לוי היה תלוי כלכלית בשמעון.', false, 'טענה זו שגויה. תלות כלכלית רלוונטית לתביעות אזרחיות של תלויים, אך אינה תנאי לזכאות כניזוק עקיף לפי סעיף 77, שמעגל הזכאים בו מוגבל לבני משפחה מדרגה ראשונה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'אופי הפיצוי לפי סעיף 77: אזרחי או עונשי?',
    2, 'מהו האופי המרכזי של הפיצוי הנפסק מכוח סעיף 77 לחוק העונשין?', 'שאלה זו מתמקדת באופי הפיצוי הנפסק מכוח סעיף 77 לחוק העונשין. היא בוחנת את ההבחנה בין אופיו האזרחי של הפיצוי (פיצוי הנפגע) לבין ההקשר הפלילי שבו הוא ניתן, ומדגישה את תכליתו כסעד מהיר ויעיל לנפגע העבירה.', 'הפיצוי לפי סעיף 77 לחוק העונשין, אף שהוא נפסל במסגרת הליך פלילי, הוא בעל אופי ''מעין אזרחי'' או ''אזרחי במהותו''. ע"פ 2858/23 שרון שיר נ'' מדינת ישראל (01.04.2024) תכליתו המרכזית היא מתן סעד מהיר ויעיל לאדם שניזוק מן העבירה בגין הנזק והסבל שנגרמו לו כתוצאה ממנה, ובכך לחסוך ממנו את הצורך לנהל הליך אזרחי יקר ומתיש. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017) הפיצוי נועד לסייע לקרבן במסלול שיקומו. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ב. סעיף 77 לחוק ותכליתו הוא מהווה פיצוי ראשוני, שאינו מחייב הוכחת נזק מדויקת, ונפסק על דרך האומדנה, תוך הכרה במגבלות ההליך הפלילי. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ז. תקרת הפיצוי',
    'הטעות הנפוצה היא לראות בפיצוי לפי סעיף 77 עונש גרידא, או לחשוב שהוא נועד להעניק פיצוי מלא לנפגע, בדומה לפיצוי בתביעה אזרחית.', '["סעיף 77 לחוק העונשין", "אופי הפיצוי", "פיצוי אזרחי", "פיצוי עונשי", "תכלית החוק", "סעד מהיר", "אומדנה"]'::jsonb, '**וריאציה 1 — הוכחת נזק:** האם הפיצוי לפי סעיף 77 מחייב הוכחת נזק מדויקת? ← לא, הפיצוי נפסל ללא הוכחת נזק מדויקת, על דרך האומדנה. ע"פ 2858/23 שרון שיר נ'' מדינת ישראל (01.04.2024)
**וריאציה 2 — פיצוי מלא:** האם הפיצוי לפי סעיף 77 נועד לתת פיצוי מלא לנפגע? ← לא, מטרת פיצויים אלו אינה מתן פיצוי מלא לנזקם של נפגעי עבירה, אשר עומדת להם הזכות להגיש תביעה אזרחית בגין מלוא נזקם. ע"פ 2796/23 שמעון לוי נ'' מדינת ישראל (17.04.2024)
**וריאציה 3 — גביית הפיצוי:** כיצד נגבה הפיצוי שנפסק לפי סעיף 77? ← לעניין גבייה, דין פיצויים לפי סעיף זה כדין קנס, והוא נגבה באמצעות המרכז לגביית קנסות. חוק העונשין, תשל"ז-1977, סעיף 77(ג)', 'הפיצוי לפי סעיף 77 לחוק העונשין ← בעל אופי מעין אזרחי, נועד לסייע לנפגע בשיקומו כסעד מהיר וראשוני, ללא הוכחת נזק מלאה.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 77", "דנ\"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)", "ע\"פ 2858/23 שרון שיר נ'' מדינת ישראל (01.04.2024)", "ע\"פ 2796/23 שמעון לוי נ'' מדינת ישראל (17.04.2024)", "יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ב. סעיף 77 לחוק ותכליתו", "ציפי יגלניק-פרישטיק אלימות כלכלית בין בני זוג – במשפט הפרטי, בדיני משפחה ובמשפט הפלילי (2024) | 3.3.3 בהליך הנזיקי הפיצוי משולם לניזוק ובהליך הפלילי הקנס משולם למדינה, למעט סעיף 77 לחוק העונשין"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'פיצוי עונשי במהותו, שנועד להרתיע את הנאשם ולגמול לו על מעשיו.', false, 'טענה זו שגויה. למרות שהפיצוי נפסל בהליך פלילי, אופיו המרכזי הוא אזרחי, ונועד לפצות את הנפגע, ולא להעניש את הנאשם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'פיצוי בעל אופי מעין אזרחי, שנועד לסייע לנפגע העבירה בשיקומו ולחסוך ממנו הליך אזרחי.', true, 'תשובה זו נכונה. הפסיקה קבעה כי הפיצוי לפי סעיף 77 הוא בעל אופי אזרחי, שמטרתו לסייע לנפגע העבירה ומהווה סעד מהיר ויעיל, תוך חיסכון בצורך בהליך אזרחי נפרד.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'פיצוי משולב, בעל אופי עונשי ואזרחי כאחד, ללא עדיפות לאחד מהם.', false, 'טענה זו שגויה. למרות שיש לפיצוי היבטים משולבים, הפסיקה מדגישה את אופיו האזרחי המרכזי, המכוון לפיצוי הנפגע.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'פיצוי סמלי, שנועד להכיר בסבלו של הנפגע, אך אינו מהווה פיצוי מהותי על נזקיו.', false, 'טענה זו שגויה. הפיצוי אינו סמלי, אלא נועד לתת מענה ריאלי ומהותי לנזקי הנפגע, גם אם הוא מוגבל בתקרה ואינו פיצוי מלא.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'ריבוי ניזוקים ישירים מאותה עבירה',
    3, 'ראובן הורשע בהצתת בניין, וכתוצאה מכך נפגעו ישירות עשרה אנשים. כל אחד מהנפגעים סבל מנזקי גוף חמורים. האם כל אחד מהנפגעים זכאי לפיצוי עד לתקרה הקבועה בסעיף 77 לחוק העונשין?', 'שאלה זו עוסקת ביישום תקרת הפיצוי הקבועה בסעיף 77 לחוק העונשין במצב של ריבוי ניזוקים ישירים. היא מדגישה את ההבחנה המרכזית שנקבעה בדנ"פ טווק בין ניזוקים ישירים לניזוקים עקיפים לעניין אופן הפעלת התקרה הסטטוטורית.', 'סעיף 77(א) לחוק העונשין קובע תקרת פיצוי שאותה ניתן לפסוק במסגרת ההליך הפלילי. חוק העונשין, תשל"ז-1977, סעיף 77(א) הלכת דנ"פ טווק קבעה כי יש להבחין בין ניזוקים ישירים לניזוקים עקיפים לעניין אופן הפעלת התקרה. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ח. תקרת הפיצוי במצב של ריבוי נפגעים כאשר כתוצאה ממעשי הנאשם נפגעו באופן ישיר מספר קרבנות, זכאי כל אחד מהם לפיצוי, שעבור כל קרבן יכול להגיע עד מלוא הסכום הנקוב בחוק. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017) כל ניזוק ישיר מהווה ''יחידה'' אחת, והפיצוי לכל יחידה כזו מוגבל לסכום המקסימלי, אך סך כל דמי הפיצויים לכל הניזוקים הישירים יכול לעלות עליו. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017) לכן, במקרה של הצתת בניין שפגעה ישירות בעשרה אנשים, כל אחד מהם זכאי לפיצוי עד לתקרה הקבועה בסעיף 77. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ח. תקרת הפיצוי במצב של ריבוי נפגעים',
    'הטעות הנפוצה היא להחיל את כלל ''התקרה הנחלקת'' (החלה על ניזוקים עקיפים) גם על ניזוקים ישירים, ובכך להגביל את סך הפיצוי הכולל לכלל הנפגעים הישירים לסכום התקרה הסטטוטורית.', '["סעיף 77 לחוק העונשין", "ניזוק ישיר", "תקרת פיצוי", "תקרה נפרדת", "ריבוי נפגעים", "דנ\"פ טווק"]'::jsonb, '**וריאציה 1 — עבירת המתה ועזבון:** ראובן הורשע ברצח שמעון. האם עזבונו של שמעון זכאי לפיצוי עד לתקרה? ← כן, העזבון נחשב לניזוק ישיר במקרה של עבירת המתה וזכאי לפיצוי עד לתקרה. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)
**וריאציה 2 — ניזוק ישיר וניזוק עקיף:** ראובן תקף את שמעון וגרם לו חבלה. אשתו של שמעון סבלה מנזק נפשי. האם שניהם יקבלו פיצוי עד לתקרה בנפרד? ← לא, במקרה כזה, הניזוק הישיר (שמעון) זכאי עד לתקרת הפיצוי, ואין להוסיף ולפסוק פיצוי מעבר לתקרה גם לניזוק העקיף של הניזוק הישיר. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)
**וריאציה 3 — ריבוי עבירות כלפי אותו ניזוק:** ראובן הורשע בתקיפה וגם בגרימת נזק לרכוש של שמעון באותו אירוע. האם שמעון זכאי לפיצוי כפול? ← הדבר תלוי נסיבות. יש עבירות שיהיו טפלות לעבירה העיקרית ולא יפוצו בנפרד, אך אם הנזק הנגרם מכל עבירה שונה (כגון תקיפה ונזק לרכוש), ייתכן פיצול הפיצוי. ע"פ 1076/15 אבנר טווק נ'' מדינת ישראל (07.06.2016)', 'ריבוי ניזוקים ישירים מאותה עבירה ← כל אחד מהם זכאי לפיצוי עד לתקרה הקבועה בסעיף 77 לחוק העונשין (תקרה נפרדת).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 77", "דנ\"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)", "ע\"פ 1076/15 אבנר טווק נ'' מדינת ישראל (07.06.2016)", "יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ח. תקרת הפיצוי במצב של ריבוי נפגעים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, שכן תקרת הפיצוי חלה על כלל הניזוקים יחד, והסכום יתחלק ביניהם.', false, 'טענה זו שגויה. כלל התקרה הנחלקת חל על ניזוקים עקיפים, אך לא על ניזוקים ישירים, שלגביהם התקרה חלה על כל אחד בנפרד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, כאשר יש מספר ניזוקים ישירים מאותה עבירה, כל אחד מהם זכאי לפיצוי עד לתקרה הקבועה בסעיף 77.', true, 'תשובה זו נכונה. על פי הלכת דנ"פ טווק, כאשר מדובר בניזוקים ישירים, תקרת הפיצוי הקבועה בסעיף 77 לחוק העונשין חלה על כל ניזוק בנפרד, וניתן לפסוק לכל אחד מהם פיצוי עד לגובה התקרה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם סך הפיצוי הכולל לכל הנפגעים אינו עולה על התקרה המקסימלית כפול מספר הנפגעים.', false, 'טענה זו שגויה. אין הגבלה כזו. סך הפיצוי הכולל לניזוקים ישירים יכול לעלות על התקרה הסטטוטורית, שכן היא חלה על כל אחד בנפרד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן בית המשפט קבע במפורש כי מדובר בעבירות נפרדות כלפי כל נפגע.', false, 'טענה זו שגויה. הזכאות לפיצוי לכל ניזוק ישיר בנפרד אינה תלויה בקביעה של עבירות נפרדות, אלא במעמדו כניזוק ישיר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'ריבוי פוגעים מול ניזוק אחד',
    4, 'ראובן ושמעון הורשעו שניהם בתקיפה חמורה של לוי. לוי סבל מנזקי גוף קשים. האם בית המשפט רשאי לחייב כל אחד מהם בפיצוי עד לתקרה הקבועה בסעיף 77 לחוק העונשין, כך שסך הפיצוי שיקבל לוי יעלה על התקרה?', 'שאלה זו עוסקת בסוגיה מורכבת של יישום סעיף 77 לחוק העונשין במצב של ריבוי פוגעים (נאשמים) מול ניזוק אחד. היא בוחנת את המחלוקת בפסיקה בשאלה האם תקרת הפיצוי חלה על כל פוגע בנפרד או על סך הפיצוי הכולל לנפגע, ומציגה את הגישה המרחיבה המאפשרת לחייב כל פוגע עד לתקרה.', 'סעיף 77(א) לחוק העונשין קובע כי בית המשפט רשאי לחייב ''אדם'' שהורשע לשלם פיצוי. חוק העונשין, תשל"ז-1977, סעיף 77(א) בשאלת ריבוי פוגעים מול ניזוק אחד, קיימות דעות שונות בפסיקה. בעניין רגבי, השופטת ברק-ארז קבעה שיש לגזור גזירה שווה בין ריבוי נאשמים מול נפגע אחד לבין ריבוי נפגעים מול נאשם אחד, ולכן אין להטיל על נאשמים יחד פיצוי העולה על התקרה הסטטוטורית. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ט. תקרת הפיצוי במצב של ריבוי פוגעים לעומת זאת, בעניין סוליימנוב, השופט מזוז סבר כי הלכת טווק לעניין ריבוי נפגעים אינה רלוונטית לסוגיה של ריבוי פוגעים, וכי החיוב בפיצוי והמגבלה על שיעורו מתייחסים לכל אדם שהורשע בנפרד. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ט. תקרת הפיצוי במצב של ריבוי פוגעים גישה זו מאפשרת לחייב כל אחד מהפוגעים בפיצוי עד לתקרה, כך שסך הפיצוי הכולל שיקבל לוי יעלה על התקרה הסטטוטורית. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ט. תקרת הפיצוי במצב של ריבוי פוגעים',
    'הטעות הנפוצה היא להניח כי תקרת הפיצוי היא אבסולוטית ואינה יכולה לעלות על הסכום הסטטוטורי, גם כאשר יש מספר פוגעים שחויבו בפיצוי.', '["סעיף 77 לחוק העונשין", "ריבוי פוגעים", "תקרת פיצוי", "אחריות משותפת", "פיצוי לנפגע עבירה", "הלכת טווק"]'::jsonb, '**וריאציה 1 — פוגעים שונים באותה עבירה:** ראובן ושמעון הורשעו בתקיפה. ראובן הורשע כמבצע עיקרי ושמעון כמסייע. האם שניהם יכולים להיות מחויבים בפיצוי עד לתקרה? ← כן, החיוב בפיצוי מתייחס לכל אדם שהורשע, ללא קשר לתפקידו המדויק בעבירה. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ט. תקרת הפיצוי במצב של ריבוי פוגעים
**וריאציה 2 — פיצוי וקנס:** ראובן חויב בפיצוי וגם בקנס. מה קודם בגבייה? ← סכום ששולם או נגבה על חשבון קנס שיש בצדו חובת פיצויים, ייזקף תחילה על חשבון הפיצויים. חוק העונשין, תשל"ז-1977, סעיף 77(ג)
**וריאציה 3 — ערעור על הפיצוי:** האם נאשם יכול לערער על גובה הפיצוי בלבד? ← כן, סעיף 78 לחוק העונשין מקנה אפשרות בידי הנאשם לערער על ההחלטה בעניין הפיצוי כחלק מערעור על פסק הדין הפלילי, או כערעור אזרחי על רכיב הפיצוי בלבד. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | יד. סוגיות דיוניות', 'ריבוי פוגעים מול ניזוק אחד ← ניתן לחייב כל פוגע בנפרד בפיצוי עד לתקרה הקבועה בסעיף 77 לחוק העונשין, כך שסך הפיצוי הכולל יכול לעלות על התקרה.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 77", "יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ט. תקרת הפיצוי במצב של ריבוי פוגעים", "יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | יד. סוגיות דיוניות"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, שכן סך הפיצוי הכולל שיקבל לוי מכל הפוגעים יחד אינו יכול לעלות על התקרה הקבועה בסעיף 77.', false, 'טענה זו שגויה. הפסיקה נוטה לפרש את סעיף 77 כך שהתקרה חלה על כל פוגע בנפרד, ולא על סך הפיצוי הכולל לנפגע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, הפסיקה קבעה כי במקרה של ריבוי פוגעים, ניתן לחייב כל אחד מהם בפיצוי עד לתקרה, כך שסך הפיצוי הכולל יעלה על התקרה.', true, 'תשובה זו נכונה. על פי גישה בפסיקה, במקרה של ריבוי פוגעים, החיוב בפיצוי והמגבלה על שיעורו מתייחסים לכל אדם שהורשע בנפרד, ולכן ניתן לחייב כל אחד מהם עד לתקרה, גם אם סך הפיצוי הכולל עולה על התקרה הסטטוטורית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם בית המשפט קבע כי כל אחד מהפוגעים אחראי לנזק נפרד שנגרם ללוי.', false, 'טענה זו שגויה. הזכאות לחייב כל פוגע בנפרד אינה תלויה בנזק נפרד, אלא בפרשנות סעיף 77 לעניין ריבוי פוגעים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן לוי יוותר על זכותו לתבוע פיצויים בהליך אזרחי.', false, 'טענה זו שגויה. הזכות לפיצוי לפי סעיף 77 אינה תלויה בויתור על תביעה אזרחית, אלא היא סעד עצמאי שניתן במסגרת ההליך הפלילי.', 4);

