  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q18', v_chapter_id, v_subtopic_id, 'בתום שנה א'' ממוצע הציונים של בילי באוניברסיטה היה 75. אליוט, אביו של בילי, הבטיח לו כי אם יעלה את ממוצע ציוניו בסמסטר הבא ב-10 נקודות לפחות, הוא יקנה לו טלפון נייד משוכלל. לבקשתו של בילי, אליוט העלה את הבטחתו על הכתב. בילי שהיה בטוח ביכולתו לשפר את ציוניו החליט לוותר על רכישת טלפון נייד בהנחה גדולה במסגרת מבצע פתיחת שנת הלימודים. בתום הסמסטר עלה ממוצע ציוניו של בילי ל-90. על אף האמור, מכיוון שאליוט נקלע לקשיים פיננסיים משמעותיים, החליט אליוט שלא לקנות לבילי את הטלפון. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 18}'::jsonb, 'השאלה עוסקת בזכותו של נותן מתנה לחזור בו מהתחייבותו לתת מתנה, בהתאם להוראות חוק המתנה, תשכ"ח-1968. היא מתמקדת בסעיף 5(ג) לחוק, המאפשר חזרה מהתחייבות במקרה של הרעה ניכרת במצבו הכלכלי של הנותן, וזאת גם אם מקבל המתנה שינה את מצבו בהסתמך על ההתחייבות.', 'חוק המתנה, תשכ"ח-1968, מבחין בין ''מתנה שהושלמה'' (סעיף 2) לבין ''התחייבות לתת מתנה'' (סעיף 5). במקרה הנדון, מדובר בהתחייבות לתת מתנה, שכן הטלפון טרם נמסר. התחייבות זו הועלתה על הכתב, כנדרש בסעיף 5(א) לחוק. חוק המתנה, תשכ"ח-1968, סעיף 5(א)
סעיף 5(ב) לחוק קובע כי נותן המתנה רשאי לחזור בו מהתחייבותו כל עוד מקבל המתנה לא שינה את מצבו בהסתמך על ההתחייבות, אלא אם ויתר בכתב על רשות זו. חוק המתנה, תשכ"ח-1968, סעיף 5(ב) במקרה זה, בילי שינה את מצבו בהסתמך על ההבטחה (ויתר על רכישת טלפון בהנחה גדולה), ולכן, לכאורה, אליוט לא היה רשאי לחזור בו מכוח סעיף 5(ב). ע"א 879/14 עמוס נחשון נ'' יהודה נחשון (05.05.2016)
אולם, סעיף 5(ג) לחוק המתנה קובע עילות נוספות לחזרה, הגוברות על סעיף 5(ב): ''מלבד האמור בסעיף קטן (ב), רשאי הנותן לחזור בו מהתחייבותו אם היתה החזרה מוצדקת בהתנהגות מחפירה של מקבל המתנה כלפי הנותן או כלפי בן-משפחתו או בהרעה ניכרת שחלה במצבו הכלכלי של הנותן''. חוק המתנה, תשכ"ח-1968, סעיף 5(ג) הפסיקה קבעה כי הוראת סעיף 5(ג) היא הגורפת ביותר ומאפשרת למתחייב לחזור בו אף אם ויתר בכתב על זכות החזרה ואפילו אם המקבל שינה את מצבו בהסתמך על המתנה. ע"א 1516/99 מרים לוי נ'' נזיה חיג''אזי (04.07.2001)
במקרה הנדון, אליוט נקלע לקשיים פיננסיים משמעותיים, המהווים ''הרעה ניכרת שחלה במצבו הכלכלי של הנותן''. ת"א (מחוזי ת"א) 28110-04-22 אנדרי סלאבו נ'' ראומה חרזי (18.06.2023) לכן, אליוט רשאי לחזור בו מהתחייבותו, למרות שבילי שינה את מצבו בהסתמך על ההבטחה. נבו - המתמחה דיני חוזים וחיובים (2026) | חוק המתנה, התשכ"ח-1968', 'הטעות הנפוצה היא להתמקד רק בסעיף 5(ב) לחוק המתנה ולהסיק ששינוי מצב של המקבל חוסם את זכות החזרה, מבלי להכיר בעדיפותן של העילות המנויות בסעיף 5(ג).',
    '["חוק המתנה", "התחייבות לתת מתנה", "חזרה ממתנה", "שינוי מצב", "הרעה ניכרת במצב כלכלי", "סעיף 5(ב)", "סעיף 5(ג)"]'::jsonb, '**וריאציה 1 — ויתור בכתב:** מה הדין אם אליוט היה מוותר בכתב על זכותו לחזור בו? ← גם במקרה של ויתור בכתב, אליוט היה רשאי לחזור בו בשל הרעה ניכרת במצבו הכלכלי, שכן סעיף 5(ג) גובר על ויתור בכתב. ע"א 350/96 אבי וייסר נ'' בלהה שביט (19.01.1999)
**וריאציה 2 — מתנה שהושלמה:** מה הדין אם אליוט כבר היה קונה את הטלפון ומוסר אותו לבילי? ← מרגע שהמתנה הושלמה (במסירת הטלפון), אליוט לא היה יכול לחזור בו, גם אם מצבו הכלכלי הורע. מרדכי ראבילו חוק המתנה (1997) | ב. חזרה מהתחייבות על־פי סעיף 5(ב) 1. חזרה — אימתי?
**וריאציה 3 — הרעה ניכרת:** מה נחשב ל''הרעה ניכרת'' במצב הכלכלי? ← הרעה ניכרת יכולה להתרחש עקב מחלה רצינית (הגורמת להוצאות מרובות וחוסר הכנסות), גירעון מסחרי, ולפעמים אף לידת ילד. הדגש הוא על כך שמילוי ההתחייבות יהפוך לנטל כבד מדי. מרדכי ראבילו חוק המתנה (1997) | 3. הרעה ניכרת במצבו של הנותן', 'אליוט רשאי לחזור בו מהתחייבותו לתת מתנה, שכן חלה הרעה ניכרת במצבו הכלכלי. זכות זו (ס'' 5(ג) לחוק המתנה) גוברת על שינוי מצב של המקבל (ס'' 5(ב)).', '["חוק המתנה, תשכ\"ח-1968, סעיף 5", "ע\"א 1516/99 מרים לוי נ'' נזיה חיג''אזי, נה(4) 730 (04.07.2001)", "ע\"א 350/96 אבי וייסר נ'' בלהה שביט, נב(5) 797 (19.01.1999)", "ע\"א 879/14 עמוס נחשון נ'' יהודה נחשון (05.05.2016)", "ת\"א (מחוזי ת\"א) 28110-04-22 אנדרי סלאבו נ'' ראומה חרזי (18.06.2023)", "נבו - המתמחה, דיני חוזים וחיובים (2026), חוק המתנה, התשכ\"ח-1968, עמ'' 87", "מרדכי ראבילו, חוק המתנה (1997), ב. חזרה מהתחייבות על־פי סעיף 5(ב) 1. חזרה — אימתי?, עמ'' 25", "מרדכי ראבילו, חוק המתנה (1997), 3. הרעה ניכרת במצבו של הנותן, עמ'' 54"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''gift'' | classifier_note: Father''s written promise of a phone to son if grades improve — חוק המתנה (gift law) formation | source_review_note: השאלה עוסקת בדיני חוזים וקניין (חוק המתנה), תחומים שאינם נכללים ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''הליכים'' נבחר כברירת מחדל תחת ''סדר דין אזרחי'' בשל הקשר העקיף להליכים אזרחיים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני חוזים'' או ''דיני קניין'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'אליוט לא רשאי לחזור בו מהתחייבותו, שכן בילי שינה את מצבו בהסתמך על ההבטחה.', false, 'טענה זו שגויה. אף שבילי שינה את מצבו בהסתמך על ההבטחה, סעיף 5(ג) לחוק המתנה מאפשר חזרה מהתחייבות לתת מתנה במקרה של הרעה ניכרת במצב הכלכלי של הנותן, וזאת גם אם המקבל שינה את מצבו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'אליוט לא רשאי לחזור בו מהתחייבותו, שכן בילי לא התנהג בצורה מחפירה כלפיו.', false, 'טענה זו שגויה. התנהגות מחפירה היא רק אחת משתי העילות המנויות בסעיף 5(ג) לחוק המתנה המאפשרות חזרה. העילה השנייה, הרעה ניכרת במצב הכלכלי, מתקיימת במקרה זה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'אליוט רשאי לחזור בו מהתחייבותו, היות שחלה הרעה ניכרת במצבו הכלכלי.', true, 'תשובה זו נכונה. סעיף 5(ג) לחוק המתנה קובע כי נותן המתנה רשאי לחזור בו מהתחייבותו אם חלה הרעה ניכרת במצבו הכלכלי, וזכות זו עומדת לו גם אם מקבל המתנה שינה את מצבו בהסתמך על ההתחייבות.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אליוט רשאי לחזור בו מהתחייבותו, היות שמדובר באב ובנו.', false, 'טענה זו שגויה. חוק המתנה אינו קובע עילה מיוחדת לחזרה ממתנה בשל יחסי קרבה משפחתיים, אלא חל על כל התחייבות לתת מתנה בכפוף לתנאים המפורטים בו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חזרה ממתנה לאחר ויתור בכתב על זכות החזרה',
    1, 'דן התחייב לתת לניר דירה במתנה וחתם על ייפוי כוח בלתי חוזר לטובתו. ניר, בהסתמך על ההתחייבות, מכר את דירתו הקודמת. לאחר מכן, ניר התנהג כלפי דן באופן מחפיר. האם דן רשאי לחזור בו מהתחייבותו לתת את הדירה?', 'שאלה זו בוחנת את היחס בין סעיף 5(ב) לסעיף 5(ג) לחוק המתנה, ומדגישה כי העילות לחזרה המנויות בסעיף 5(ג) (התנהגות מחפירה או הרעה ניכרת במצב הכלכלי) גוברות על המגבלות שבסעיף 5(ב) (ויתור בכתב או שינוי מצב של המקבל).', 'סעיף 5(ב) לחוק המתנה, תשכ"ח-1968, קובע כי נותן המתנה רשאי לחזור בו מהתחייבותו כל עוד מקבל המתנה לא שינה את מצבו בהסתמך על ההתחייבות, אלא אם ויתר בכתב על רשות זו. חוק המתנה, תשכ"ח-1968, סעיף 5(ב) ייפוי כוח בלתי חוזר נחשב כוויתור בכתב על זכות החזרה. ע"א 7323/18 סאמר מוחמד בשר נ'' עומר חסן בשר (06.08.2020) אולם, סעיף 5(ג) לחוק המתנה קובע כי ''מלבד האמור בסעיף קטן (ב), רשאי הנותן לחזור בו מהתחייבותו אם היתה החזרה מוצדקת בהתנהגות מחפירה של מקבל המתנה כלפי הנותן או כלפי בן-משפחתו או בהרעה ניכרת שחלה במצבו הכלכלי של הנותן''. חוק המתנה, תשכ"ח-1968, סעיף 5(ג) הפסיקה מפרשת את סעיף 5(ג) כגובר על סעיף 5(ב), כלומר, נותן המתנה רשאי לחזור בו גם אם ויתר בכתב על זכות החזרה וגם אם המקבל שינה את מצבו בהסתמך על המתנה, וזאת אם מתקיימת התנהגות מחפירה של המקבל. ע"א 1516/99 מרים לוי נ'' נזיה חיג''אזי (04.07.2001) לכן, במקרה זה, דן רשאי לחזור בו מהתחייבותו בשל התנהגות מחפירה של ניר. נבו - המתמחה דיני חוזים וחיובים (2026) | חוק המתנה, התשכ"ח-1968',
    'הטעות הנפוצה היא לחשוב שוויתור בכתב (כמו ייפוי כוח בלתי חוזר) או שינוי מצב של המקבל חוסמים באופן מוחלט את זכות החזרה, מבלי להכיר בעדיפותן של העילות שבסעיף 5(ג).', '["חוק המתנה", "התחייבות לתת מתנה", "חזרה ממתנה", "ייפוי כוח בלתי חוזר", "ויתור בכתב", "שינוי מצב", "התנהגות מחפירה", "סעיף 5(ב)", "סעיף 5(ג)"]'::jsonb, '**וריאציה 1 — הרעה כלכלית לאחר ויתור:** דן ויתר בכתב על זכות החזרה, אך מצבו הכלכלי הורע ניכרת. האם רשאי לחזור בו? ← כן, סעיף 5(ג) מאפשר חזרה גם במקרה של הרעה ניכרת במצב הכלכלי, וזאת גם אם הנותן ויתר בכתב על זכות החזרה. ע"א 350/96 אבי וייסר נ'' בלהה שביט (19.01.1999)
**וריאציה 2 — התנהגות מחפירה לאחר השלמת המתנה:** ניר התנהג באופן מחפיר כלפי דן, אך הדירה כבר נרשמה על שמו. האם דן רשאי לחזור בו? ← לא, זכות החזרה לפי סעיף 5(ג) קיימת רק כל עוד המתנה לא הושלמה (ברישום במקרקעין). עמ"ש (מחוזי מרכז) 32367-08-22 א.ב. נ'' צ. נ (30.01.2023)
**וריאציה 3 — ויתור מפורש על 5(ג):** האם דן יכול לוותר מראש גם על זכות החזרה לפי סעיף 5(ג)? ← סעיף 5(ג) קובע זכות חזרה ''מלבד האמור בסעיף קטן (ב)'', ומשמעות הדבר היא שזכות זו עומדת לנותן גם אם ויתר על זכות החזרה לפי 5(ב). הפסיקה לא הכירה באפשרות לוותר מראש על זכות החזרה לפי 5(ג). מרדכי ראבילו חוק המתנה (1997) | ג. זכות החזרה על־פי סעיף 5(ג) 1. מה בין הזכות שבסעיף קטן (ב) לזכות שבסעיף קטן (ג)?', 'סעיף 5(ג) לחוק המתנה מאפשר חזרה ממתנה בשל התנהגות מחפירה או הרעה כלכלית, וזאת גם אם הנותן ויתר בכתב על זכות החזרה (ייפוי כוח בלתי חוזר) וגם אם המקבל שינה את מצבו בהסתמך על ההתחייבות.',
    '["חוק המתנה, תשכ\"ח-1968, סעיף 5", "ע\"א 1516/99 מרים לוי נ'' נזיה חיג''אזי, נה(4) 730 (04.07.2001)", "ע\"א 350/96 אבי וייסר נ'' בלהה שביט, נב(5) 797 (19.01.1999)", "ע\"א 7323/18 סאמר מוחמד בשר נ'' עומר חסן בשר (06.08.2020)", "עמ\"ש (מחוזי מרכז) 32367-08-22 א.ב. נ'' צ. נ (30.01.2023)", "נבו - המתמחה, דיני חוזים וחיובים (2026), חוק המתנה, התשכ\"ח-1968, עמ'' 88", "מרדכי ראבילו, חוק המתנה (1997), סעיף 5 - התחייבות לתת מתנה, עמ'' 52"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, שכן דן ויתר בכתב על זכותו לחזור בו מהמתנה באמצעות ייפוי הכוח הבלתי חוזר.', false, 'טענה זו שגויה. ייפוי כוח בלתי חוזר מהווה ויתור בכתב על זכות החזרה לפי סעיף 5(ב), אך סעיף 5(ג) מאפשר חזרה גם במקרה של ויתור כזה, אם מתקיימת התנהגות מחפירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, שכן ניר שינה את מצבו בהסתמך על ההתחייבות, ולכן דן אינו רשאי לחזור בו.', false, 'טענה זו שגויה. שינוי מצב של המקבל מונע חזרה לפי סעיף 5(ב), אך סעיף 5(ג) מאפשר חזרה גם במקרה של שינוי מצב, אם מתקיימת התנהגות מחפירה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, דן רשאי לחזור בו מהתחייבותו בשל התנהגות מחפירה של ניר, שכן סעיף 5(ג) לחוק המתנה גובר על ויתור בכתב ועל שינוי מצב של המקבל.', true, 'תשובה זו נכונה. סעיף 5(ג) לחוק המתנה קובע כי נותן המתנה רשאי לחזור בו מהתחייבותו אם החזרה מוצדקת בהתנהגות מחפירה של מקבל המתנה, וזכות זו עומדת לו גם אם ויתר בכתב על זכות החזרה וגם אם המקבל שינה את מצבו בהסתמך על ההתחייבות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אך רק אם דן יוכיח כי התנהגותו המחפירה של ניר גרמה לו נזק כלכלי ניכר.', false, 'טענה זו שגויה. התנהגות מחפירה אינה דורשת הוכחת נזק כלכלי לנותן, אלא היא עילה עצמאית לחזרה מהמתנה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן ''שינוי מצב'' בסעיף 5(ב)',
    2, 'שרה הבטיחה לראובן מתנה יקרת ערך. ראובן, בהסתמך על ההבטחה, קנה כרטיס הגרלה בתקווה לזכות בפרס גדול. האם קניית כרטיס ההגרלה נחשבת ל''שינוי מצב'' מהותי המונע משרה לחזור בה מהתחייבותה?', 'שאלה זו מתמקדת בפרשנות המונח ''שינה את מצבו בהסתמך על ההתחייבות'' בסעיף 5(ב) לחוק המתנה. היא מדגישה כי לא כל שינוי, אלא רק שינוי מהותי ומשמעותי, יחסום את זכות החזרה של נותן המתנה.', 'סעיף 5(ב) לחוק המתנה קובע כי נותן המתנה רשאי לחזור בו מהתחייבותו כל עוד מקבל המתנה לא שינה את מצבו בהסתמך על ההתחייבות. חוק המתנה, תשכ"ח-1968, סעיף 5(ב) הפסיקה והספרות המשפטית הבהירו כי לא כל שינוי שולי וקל-ערך חוסם חזרה מן המתנה. עמ"ש (מחוזי מרכז) 62373-11-15 ר. י נ'' א.י (22.07.2016) שינוי המצב צריך להיות מהותי וכן מן ההכרח שיהיה תוצאה של ההבטחה. ת"א (מחוזי חי'') 9616-05-17 ח''שיבון ויליאם נ'' הכונס הרשמי מחוז חיפה (03.09.2020) קריטריון נוסף הוא מבחן הדירות של השינוי: ככל שהשינוי ניתן לחזרה לקדמותו בדרך קלה והוגנת, מצטמצמת הנטייה לראות את ההתחייבות כבלתי הדירה. מרדכי ראבילו חוק המתנה (1997) | (א) המקבל "שינה את מצבו בהסתמך על ההתחייבות" קניית כרטיס הגרלה, שהיא פעולה ספקולטיבית ואינה יוצרת התחייבות כספית משמעותית או שינוי בלתי הפיך, אינה עונה על דרישת המהותיות. ה"פ (מחוזי חי'') 45613-08-17 סאמר מוחמד בשר נ'' עומר חסן בשר (05.08.2018)',
    'הטעות הנפוצה היא לפרש את המונח ''שינה את מצבו'' באופן רחב מדי, ולכלול בו כל פעולה שנעשתה בהסתמך על ההבטחה, גם אם היא שולית או ספקולטיבית.', '["חוק המתנה", "התחייבות לתת מתנה", "שינוי מצב", "הסתמכות", "מהותיות השינוי", "מבחן הדירות", "סעיף 5(ב)"]'::jsonb, '**וריאציה 1 — השקעת כספים בנכס:** ראובן השקיע כספים רבים בשיפוץ דירה שהובטחה לו במתנה, אך טרם נרשמה על שמו. האם זה שינוי מצב? ← כן, השקעת כספים בבניית בית על קרקע שאינה רשומה בשם המשקיע היא שינוי מצב. מרדכי ראבילו חוק המתנה (1997) | (א) המקבל "שינה את מצבו בהסתמך על ההתחייבות"
**וריאציה 2 — הימנעות ממעשה:** ראובן נמנע מלמכור נכס אחר שהיה בבעלותו, בהסתמך על הבטחת המתנה. האם זו נחשבת לשינוי מצב? ← כן, לעיתים גם הימנעות ממעשה יכולה להיות שינוי מצב, אם היא מהותית ונגרמה כתוצאה מההבטחה. מרדכי ראבילו חוק המתנה (1997) | (א) המקבל "שינה את מצבו בהסתמך על ההתחייבות"
**וריאציה 3 — נטל ההוכחה:** על מי מוטל הנטל להוכיח ששינוי מצב התרחש? ← הנטל להוכיח כי מקבל המתנה שינה את מצבו בהסתמך על ההבטחה מוטל על מקבל המתנה. ת"א (מחוזי חי'') 9616-05-17 ח''שיבון ויליאם נ'' הכונס הרשמי מחוז חיפה (03.09.2020)', 'שינוי מצב (ס'' 5(ב) לחוק המתנה) ← צריך להיות מהותי, תוצאה של ההבטחה, ולא ניתן לחזרה בקלות. קניית כרטיס הגרלה אינה נחשבת לשינוי מצב מהותי.',
    '["חוק המתנה, תשכ\"ח-1968, סעיף 5", "עמ\"ש (מחוזי מרכז) 62373-11-15 ר. י נ'' א.י (22.07.2016)", "ה\"פ (מחוזי חי'') 45613-08-17 סאמר מוחמד בשר נ'' עומר חסן בשר (05.08.2018)", "ת\"א (מחוזי חי'') 9616-05-17 ח''שיבון ויליאם נ'' הכונס הרשמי מחוז חיפה (03.09.2020)", "מרדכי ראבילו, חוק המתנה (1997), סעיף 5 - התחייבות לתת מתנה, עמ'' 32"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, שכן כל פעולה שנעשתה בהסתמך על ההבטחה, גם אם היא קטנה, נחשבת לשינוי מצב.', false, 'טענה זו שגויה. הפסיקה דורשת ששינוי המצב יהיה מהותי ומשמעותי, ולא כל שינוי שולי וקל-ערך יחסום חזרה מן המתנה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, שכן שינוי מצב צריך להיות מהותי וקניית כרטיס הגרלה אינה עונה על דרישה זו.', true, 'תשובה זו נכונה. הפסיקה קבעה כי שינוי מצב צריך להיות מהותי ומשמעותי, ופעולה ספקולטיבית כמו קניית כרטיס הגרלה, שאינה יוצרת התחייבות כספית משמעותית או שינוי בלתי הפיך, אינה נחשבת לשינוי מצב מהותי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, אך רק אם ראובן יוכיח כי לא היה קונה את כרטיס ההגרלה אלמלא הבטחתה של שרה.', false, 'טענה זו שגויה. הוכחת קשר סיבתי בין ההבטחה לשינוי המצב נדרשת, אך אין די בכך. השינוי עצמו צריך להיות מהותי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, אלא אם כן שרה ויתרה בכתב על זכותה לחזור בה מהמתנה.', false, 'טענה זו שגויה. ויתור בכתב הוא חריג נפרד לזכות החזרה לפי סעיף 5(ב), ואינו קשור לשאלת מהותיות שינוי המצב.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פרשנות ''התנהגות מחפירה''',
    3, 'אב הבטיח לבנו דירה במתנה. לאחר ההבטחה, הבן החל לדבר אל אביו בזלזול, להטיח בו עלבונות ולהתעלם מבקשותיו לעזרה. האם התנהגות זו עולה כדי ''התנהגות מחפירה'' המצדיקה חזרה מהמתנה לפי סעיף 5(ג) לחוק המתנה?', 'שאלה זו עוסקת בפרשנות המונח ''התנהגות מחפירה'' בסעיף 5(ג) לחוק המתנה. היא מדגישה את הגישה המרחיבה של הפסיקה למונח זה, המאפשרת לנותן המתנה לחזור בו גם במקרים של פגיעה בכבוד, זלזול או כפיות טובה, ולא רק במקרים של פגיעה פיזית או כלכלית.', 'סעיף 5(ג) לחוק המתנה מאפשר לנותן לחזור בו מהתחייבותו אם החזרה מוצדקת ב''התנהגות מחפירה של מקבל המתנה כלפי הנותן או כלפי בן-משפחתו''. חוק המתנה, תשכ"ח-1968, סעיף 5(ג) הפסיקה פירשה את הביטוי ''התנהגות מחפירה'' באופן רחב, המקל על נותן המתנה לחזור בו מהתחייבותו אם מקבל המתנה לא נהג בו כראוי. עמ"ש (מחוזי מרכז) 62373-11-15 ר. י נ'' א.י (22.07.2016) נקבע כי לאור אופיה המיוחד של המתנה וחובת תום הלב של המקבל, אין לפרש את הביטוי לפי משמעותו הרגילה, אלא לפי המשמעות שיש לתת לו על רקע מערכת היחסים שבין נותן המתנה ומקבל המתנה. ע"א 1516/99 מרים לוי נ'' נזיה חיג''אזי (04.07.2001) כך, מילת גנאי, אמירה של זלזול ואפילו עקימת פרצוף, שייחשבו עניין של מה בכך על רקע מערכת יחסים אחרת, משמעותן רעה וחמורה כאשר מדובר בנותן מתנה ומקבלה. ע"א 1516/99 מרים לוי נ'' נזיה חיג''אזי (04.07.2001) במקרה הנדון, דיבור בזלזול, הטחת עלבונות והתעלמות מבקשות עזרה עולים כדי התנהגות מחפירה המצדיקה חזרה מהמתנה. ע"א 350/96 אבי וייסר נ'' בלהה שביט (19.01.1999)',
    'הטעות הנפוצה היא לפרש את המונח ''התנהגות מחפירה'' באופן מצומצם, כדורש מעשים חמורים במיוחד, ולא להכיר בכך שגם פגיעה בכבוד או זלזול יכולים להיכלל בו.', '["חוק המתנה", "התחייבות לתת מתנה", "התנהגות מחפירה", "פרשנות רחבה", "כפיות טובה", "זלזול", "סעיף 5(ג)"]'::jsonb, '**וריאציה 1 — התערערות יחסים:** האם כל התערערות במערכת היחסים בין הנותן למקבל נחשבת להתנהגות מחפירה? ← לא, לא כל התערערות במערכת היחסים תוכר בהכרח כהתנהגות בלתי ראויה מצד המקבל. עמ"ש (מחוזי מרכז) 62373-11-15 ר. י נ'' א.י (22.07.2016)
**וריאציה 2 — התנהגות מחפירה של הנותן:** מה הדין אם ההתנהגות המחפירה של המקבל נגרמה כתוצאה מהתנהגותו של הנותן עצמו? ← אם ההתנהגות המחפירה נגרמה כתוצאה מהתנהגותו של הנותן, הוא לא יהיה רשאי לחזור בו מהבטחתו. עמ"ש (מחוזי מרכז) 62373-11-15 ר. י נ'' א.י (22.07.2016)
**וריאציה 3 — נטל ההוכחה:** על מי מוטל הנטל להוכיח התנהגות מחפירה? ← הנטל להוכיח את ההתנהגות המחפירה מוטל על נותן המתנה. עמ"ש (מחוזי מרכז) 62373-11-15 ר. י נ'' א.י (22.07.2016)', '''התנהגות מחפירה'' (ס'' 5(ג) לחוק המתנה) ← מפורשת באופן רחב, כוללת כפיות טובה, זלזול ופגיעה בכבוד, ולא רק מעשים אלימים. לא כל התערערות יחסים נחשבת לכך.',
    '["חוק המתנה, תשכ\"ח-1968, סעיף 5", "ע\"א 1516/99 מרים לוי נ'' נזיה חיג''אזי, נה(4) 730 (04.07.2001)", "ע\"א 350/96 אבי וייסר נ'' בלהה שביט, נב(5) 797 (19.01.1999)", "עמ\"ש (מחוזי מרכז) 62373-11-15 ר. י נ'' א.י (22.07.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, שכן ''התנהגות מחפירה'' מתייחסת רק למעשים פליליים או אלימים כלפי הנותן.', false, 'טענה זו שגויה. הפסיקה פירשה את המונח ''התנהגות מחפירה'' באופן רחב, שאינו מוגבל למעשים פליליים או אלימים, אלא כולל גם פגיעה בכבוד ובדרך ארץ.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, התנהגות זו עשויה להיחשב כהתנהגות מחפירה, שכן הפסיקה מפרשת מונח זה באופן רחב, הכולל כפיות טובה וזלזול.', true, 'תשובה זו נכונה. הפסיקה פירשה את הביטוי ''התנהגות מחפירה'' באופן רחב, המקל על נותן המתנה לחזור בו, וכוללת בו התנהגות המצביעה על כפיות טובה, התנכלות, פגיעה בכבודו או רכושו של הנותן, או זלזול.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, אלא אם כן האב יוכיח כי התנהגות הבן גרמה לו נזק כלכלי ניכר.', false, 'טענה זו שגויה. התנהגות מחפירה היא עילה עצמאית לחזרה, ואינה דורשת הוכחת נזק כלכלי. נזק כלכלי ניכר הוא עילה נפרדת בסעיף 5(ג).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, אך רק אם הבן ויתר בכתב על זכותו לקבל את המתנה.', false, 'טענה זו שגויה. ויתור של המקבל על זכותו לקבל את המתנה אינו רלוונטי לשאלת התנהגות מחפירה של המקבל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השלמת מתנה במקרקעין',
    4, 'דנה התחייבה להעניק לאחותה, רונית, דירה במתנה. הן חתמו על תצהירי מתנה, אך הדירה טרם נרשמה על שם רונית בטאבו. האם דנה רשאית לחזור בה מהמתנה ללא כל סיבה, בהנחה שלא ויתרה בכתב על זכות החזרה ורונית לא שינתה את מצבה בהסתמך על ההתחייבות?', 'שאלה זו עוסקת בהבחנה המהותית בין ''מתנה שהושלמה'' לבין ''התחייבות לתת מתנה'', ובפרט בהקשר של מקרקעין. היא מדגישה כי מתנה במקרקעין מושלמת רק עם הרישום בטאבו, ועד אז חלים עליה הכללים המאפשרים חזרה מהתחייבות לתת מתנה, בכפוף לסייגים שבסעיף 5 לחוק המתנה.', 'סעיף 6 לחוק המתנה קובע כי ''בעלות בדבר-המתנה עוברת למקבל במסירת הדבר לידו... והכל כשאין בדין אחר הוראות מיוחדות לענין הנדון''. חוק המתנה, תשכ"ח-1968, סעיף 6 במקרקעין, ההוראה המיוחדת היא סעיף 7(א) לחוק המקרקעין, תשכ"ט-1969, הקובע כי ''עסקה במקרקעין טעונה רישום. העסקה נגמרת ברישום''. עמ"ש (מחוזי מרכז) 32367-08-22 א.ב. נ'' צ. נ (30.01.2023) מכאן, שמתנה במקרקעין מושלמת רק עם רישום הבעלות על שם המקבל בטאבו. כל עוד הרישום לא הושלם, מדובר בהתחייבות לתת מתנה, ולא במתנה שהושלמה. עמ"ש (מחוזי מרכז) 32367-08-22 א.ב. נ'' צ. נ (30.01.2023) על התחייבות לתת מתנה חל סעיף 5 לחוק המתנה. עמ"ש (מחוזי מרכז) 32367-08-22 א.ב. נ'' צ. נ (30.01.2023) סעיף 5(ב) קובע כי נותן המתנה רשאי לחזור בו ממנה, כל עוד מקבל המתנה לא שינה את מצבו בהסתמך על ההתחייבות, וזאת זולת אם ויתר בכתב על רשות זו. חוק המתנה, תשכ"ח-1968, סעיף 5(ב) במקרה הנדון, בהנחה שדנה לא ויתרה בכתב על זכות החזרה ורונית לא שינתה את מצבה בהסתמך על ההתחייבות, דנה רשאית לחזור בה מהמתנה ללא כל סיבה. ע"א 879/14 עמוס נחשון נ'' יהודה נחשון (05.05.2016)',
    'הטעות הנפוצה היא לבלבל בין חתימה על תצהירי מתנה לבין השלמת המתנה במקרקעין, ולחשוב שחתימה על התצהירים הופכת את המתנה לבלתי חוזרת, מבלי להבין את דרישת הרישום בטאבו.', '["חוק המתנה", "חוק המקרקעין", "התחייבות לתת מתנה", "מתנה שהושלמה", "רישום בטאבו", "זכות חזרה", "סעיף 5(ב)", "סעיף 7(א) לחוק המקרקעין"]'::jsonb, '**וריאציה 1 — ייפוי כוח בלתי חוזר:** מה הדין אם דנה חתמה גם על ייפוי כוח בלתי חוזר? ← ייפוי כוח בלתי חוזר מהווה ויתור בכתב על זכות החזרה לפי סעיף 5(ב), ולכן דנה לא תוכל לחזור בה, אלא אם כן יתקיימו עילות החזרה שבסעיף 5(ג). ע"א 7323/18 סאמר מוחמד בשר נ'' עומר חסן בשר (06.08.2020)
**וריאציה 2 — שינוי מצב של המקבל:** מה הדין אם רונית שינתה את מצבה בהסתמך על ההתחייבות (למשל, מכרה את דירתה)? ← אם רונית שינתה את מצבה בהסתמך על ההתחייבות, דנה לא תוכל לחזור בה לפי סעיף 5(ב), אלא אם כן יתקיימו עילות החזרה שבסעיף 5(ג). חוק המתנה, תשכ"ח-1968, סעיף 5(ב)
**וריאציה 3 — מתנה שהושלמה:** מה הדין אם הדירה כבר נרשמה על שם רונית בטאבו? ← מרגע שהמתנה הושלמה ברישום, הנותן אינו יכול עוד לחזור בו מהמתנה, גם אם יתקיימו עילות החזרה שבסעיף 5(ג). מרדכי ראבילו חוק המתנה (1997) | ב. חזרה מהתחייבות על־פי סעיף 5(ב) 1. חזרה — אימתי?', 'מתנה במקרקעין ← מושלמת רק ברישום בטאבו. עד אז, זו התחייבות לתת מתנה, וניתן לחזור ממנה לפי סעיף 5(ב) לחוק המתנה, אלא אם הנותן ויתר בכתב או המקבל שינה מצבו.',
    '["חוק המתנה, תשכ\"ח-1968, סעיף 5", "חוק המתנה, תשכ\"ח-1968, סעיף 6", "עמ\"ש (מחוזי מרכז) 32367-08-22 א.ב. נ'' צ. נ (30.01.2023)", "ע\"א 879/14 עמוס נחשון נ'' יהודה נחשון (05.05.2016)", "ע\"א 7323/18 סאמר מוחמד בשר נ'' עומר חסן בשר (06.08.2020)", "מרדכי ראבילו, חוק המתנה (1997), ב. חזרה מהתחייבות על־פי סעיף 5(ב) 1. חזרה — אימתי?, עמ'' 28"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, שכן חתימה על תצהירי מתנה הופכת את המתנה לבלתי חוזרת.', false, 'טענה זו שגויה. חתימה על תצהירי מתנה היא שלב בהתחייבות לתת מתנה, אך אינה משלימה את המתנה במקרקעין, אשר דורשת רישום בטאבו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, כל עוד הדירה לא נרשמה בטאבו, זוהי התחייבות לתת מתנה, ודנה רשאית לחזור בה ללא סיבה, בהתקיים תנאי סעיף 5(ב) לחוק המתנה.', true, 'תשובה זו נכונה. מתנה במקרקעין נגמרת רק ברישום. כל עוד הרישום לא הושלם, זוהי התחייבות לתת מתנה, ובהיעדר ויתור בכתב או שינוי מצב של המקבל, הנותן רשאי לחזור בו ללא סיבה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, שכן מדובר במתנה בין אחיות, ולכן חלות עליה הוראות מיוחדות המונעות חזרה.', false, 'טענה זו שגויה. חוק המתנה אינו קובע הוראות מיוחדות למתנות בין אחיות, והכללים הכלליים חלים גם עליהן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם דנה תוכיח כי רונית התנהגה כלפיה באופן מחפיר.', false, 'טענה זו שגויה. התנהגות מחפירה היא עילה לחזרה לפי סעיף 5(ג), אך לפי סעיף 5(ב), אם לא התקיימו החריגים (ויתור בכתב או שינוי מצב), הנותן רשאי לחזור בו ללא צורך בסיבה מיוחדת.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 18, '2023-S-S-Q18';
END
$$;

-- ============================================================
-- Q19 — 2023-S-S-Q19 — chapter=property subtopic=chattels_lost_found  [needs_review]
-- classifier_note: Market overt (תקנת השוק) on a used piano — falls under chattels chapter; the dedicated 'market overt' framing isn't a subtopic
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'd4f08e6d-be31-4bc4-871f-aac95da66407'::uuid;
  v_group_id uuid := 'cdb4edaf-9afa-4fcd-9c75-e7a4b51b752e'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '698ccb4c-6d69-4782-b2b0-cd94f7651450'::uuid;
  v_ang_1 uuid := 'f2216ae7-58e5-4beb-b4f6-0ac2b2dd514e'::uuid;
  v_ang_2 uuid := '6ccabdc8-2f50-4f3c-a490-b76a1c8168d4'::uuid;
  v_ang_3 uuid := 'fb11ff72-73e0-4d16-a807-17ea7277e1f1'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q19';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 19, '2023-S-S-Q19';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'property';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'property';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'chattels_lost_found' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'chattels_lost_found', 'property';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q19', v_chapter_id, v_subtopic_id, 'שמשון רצה לרכוש פסנתר יד שנייה. שמשון שמע כי יואב, העובד בחברת החשמל, מציע למכירה פסנתר משומש במגרש הנמצא מאחורי האתר שבו הוא עובד. שמשון פנה ליואב, וכעבור זמן קצר רכש את הפסנתר במחיר הנמוך בכ-30% מהמחיר הנמוך ביותר שמצא עד כה עבור פסנתר משומש מאותו הדגם. כעבור חודש פנתה גילה לשמשון והודיעה לו כי הפסנתר שרכש נגנב ממנה והיא דורשת אותו בחזרה. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 19}'::jsonb, 'השאלה עוסקת בתקנת השוק במיטלטלין, הקבועה בסעיף 34 לחוק המכר, תשכ"ח-1968. תקנת השוק מהווה חריג לכלל הקנייני הבסיסי שלפיו אין אדם יכול להקנות לאחר יותר זכויות משיש לו, ומטרתה לאזן בין הגנה על זכות הקניין של הבעלים המקורי לבין הצורך בתקינות חיי המסחר. תחולתה מותנית בקיומם של שישה תנאים מצטברים, כפי שפורשו בהרחבה בהלכת כנען.', 'הכלל הבסיסי בדיני קניין הוא שאין אדם יכול להקנות לאחר יותר זכויות משיש לו (nemo dat quod non habet). דנ"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003) תקנת השוק, הקבועה בסעיף 34 לחוק המכר, תשכ"ח-1968, מהווה חריג לכלל זה. חוק המכר, תשכ"ח-1968, סעיף 34 מטרתה לאפשר סחר חופשי ושוטף במיטלטלין, תוך איזון בין זכות הקניין לבין תקינות חיי המסחר. ת"א (שלום פ"ת) 10049-11-16 יונתן צ''יפר נ'' אלין קאר בע"מ (21.01.2019)
תחולת תקנת השוק מותנית בקיומם של שישה תנאים מצטברים, כפי שפורטו בהלכת כנען: דנ"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003)
במקרה הנדון:
1. **כריתת חוזה מכר:** שמשון רכש את הפסנתר, כך שתנאי זה מתקיים.
2. **נכס נד:** פסנתר הוא נכס נד (מיטלטלין).
3. **מוכר העוסק במכירת נכסים מסוגו של הממכר:** יואב הוא עובד חברת החשמל, לא סוחר פסנתרים. תנאי זה אינו מתקיים. ה"ת (שלום ת"א) 61744-08-22 אליהו חדד ניאזוב נ'' משטרת ישראל/תחנת נתניה (02.02.2023)
4. **המכירה היא במהלך העסקים הרגיל:** מכירת פסנתר במגרש מאחורי אתר העבודה של יואב אינה מהלך עסקיו הרגיל. תנאי זה אינו מתקיים. ה"ת (שלום ת"א) 61744-08-22 אליהו חדד ניאזוב נ'' משטרת ישראל/תחנת נתניה (02.02.2023)
5. **קבלת הנכס לחזקת הקונה:** שמשון קיבל את הפסנתר לחזקתו.
6. **תום לב:** מחיר נמוך ב-30% מהמחיר הנמוך ביותר בשוק היה צריך לעורר חשד אצל שמשון, וייתכן ששולל את תום לבו (עצימת עיניים). דנ"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003)
מאחר שלא התקיימו כל התנאים המצטברים (לפחות תנאים 3 ו-4), תקנת השוק אינה חלה. לכן, הבעלות בפסנתר נשארת בידי הבעלים המקורי, גילה, ועל שמשון להשיב לה את הפסנתר. ת"א (שלום עכו) 7657-02-25 בועז אפגין נ'' ג''אבר אבו פארס (27.07.2025)', 'הטעות הנפוצה היא להתמקד רק בתום לבו של הקונה ובתשלום התמורה, מבלי לבחון בקפדנות את כל ששת התנאים המצטברים של תקנת השוק, ובפרט את התנאים הנוגעים לזהות המוכר ולאופי המכירה.',
    '["תקנת השוק", "סעיף 34 לחוק המכר", "נכס נד", "מוכר העוסק במכירת נכסים מסוגו", "מהלך עסקים רגיל", "תום לב", "תנאים מצטברים", "nemo dat quod non habet"]'::jsonb, '**וריאציה 1 — רכישה ממוכר פרטי במחיר שוק:** מה הדין אם שמשון רכש את הפסנתר ממוכר פרטי במחיר שוק מלא? ← תקנת השוק לא תחול, שכן המוכר אינו עוסק במכירת נכסים מסוגו של הממכר, וזו אינה מכירה במהלך עסקיו הרגיל. ע"א (מחוזי תל אביב-יפו) 3059/05 אברהמי לאה נ'' אריה חברה לביטוח בע"מ (20.02.2008)
**וריאציה 2 — רכישה מגלריה מוכרת במחיר נמוך:** מה הדין אם שמשון רכש את הפסנתר מגלריה מוכרת (סוחרת פסנתרים) במחיר נמוך ב-30%? ← במקרה כזה, תנאי המוכר ומהלך העסקים הרגיל מתקיימים, אך מחיר נמוך משמעותית עלול לשלול את תום לבו של הקונה או את דרישת התמורה הממשית. ע"ק (שלום ראשל"צ) 74107-05-25 פאדי אבו קישק נ'' משטרת ישראל (03.09.2025)
**וריאציה 3 — נכס שאינו נד:** מה הדין אם שמשון רכש מגרש חניה שנגנב מבעליו? ← תקנת השוק שבסעיף 34 לחוק המכר חלה רק על ''נכס נד'' (מיטלטלין), ולא על מקרקעין. ע"א 4052/19 י.ש.מ לבניין בע"מ נ'' תדביק בע"מ (13.09.2020)', 'תקנת השוק (ס'' 34 לחוק המכר) דורשת 6 תנאים מצטברים, כולל רכישה ממוכר העוסק במכירת נכסים מסוגו של הממכר ובמהלך עסקיו הרגיל. אי-קיום אחד מהם, כמו רכישה מאדם פרטי שאינו סוחר, שולל את תחולתה ומחייב השבת הנכס לבעליו המקורי.', '["חוק המכר, תשכ\"ח-1968, סעיף 34", "דנ\"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003)", "ע\"א (מחוזי תל אביב-יפו) 3059/05 אברהמי לאה נ'' אריה חברה לביטוח בע\"מ (20.02.2008)", "ת\"א (שלום פ\"ת) 10049-11-16 יונתן צ''יפר נ'' אלין קאר בע\"מ (21.01.2019)", "ת\"א (שלום ת\"א) 57984-10-17 אס.אר. אקורד בע\"מ נ'' יורודרייב ניהול ציי רכב והשכרה בע\"מ (04.03.2020)", "ת\"א (שלום נצ'') 41703-07-18 עמית יצחק נ'' מהיטבאל יזמות בע\"מ (28.12.2020)", "ה\"ת (שלום ת\"א) 61744-08-22 אליהו חדד ניאזוב נ'' משטרת ישראל/תחנת נתניה (02.02.2023)", "ת\"א (שלום עכו) 7657-02-25 בועז אפגין נ'' ג''אבר אבו פארס (27.07.2025)", "ע\"ק (שלום ראשל\"צ) 74107-05-25 פאדי אבו קישק נ'' משטרת ישראל (03.09.2025)", "ע\"א 4052/19 י.ש.מ לבניין בע\"מ נ'' תדביק בע\"מ (13.09.2020)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''property'' subtopic=''chattels_lost_found'' | classifier_note: Market overt (תקנת השוק) on a used piano — falls under chattels chapter; the dedicated ''market overt'' framing isn''t a subtopic | source_review_note: השאלה עוסקת בדיני קניין (תקנת השוק), תחום שאינו נכלל ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''הליכים'' נבחר כברירת מחדל תחת ''סדר דין אזרחי'' בשל הקשר העקיף להליכים אזרחיים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני קניין'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'שמשון רשאי להשאיר את הפסנתר בחזקתו כי אין חולק שהוא לא גנב אותו.', false, 'טענה זו שגויה. העובדה ששמשון לא גנב את הפסנתר אינה מקנה לו בעלות נקייה, שכן הכלל הבסיסי בדיני קניין הוא שאין אדם יכול להקנות לאחר יותר זכויות משיש לו, אלא אם מתקיימים תנאי תקנת השוק.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על שמשון להשיב את הפסנתר לגילה.', true, 'תשובה זו נכונה. תקנת השוק אינה חלה במקרה זה, שכן הפסנתר לא נרכש ממי שעוסק במכירת נכסים מסוגו של הממכר, והמכירה לא הייתה במהלך העסקים הרגיל של המוכר. לכן, הבעלות נשארת בידי הבעלים המקורי, גילה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'שמשון רשאי להשאיר את הפסנתר בחזקתו, היות ששמשון שילם תמורה והוא תם לב.', false, 'טענה זו שגויה. תשלום תמורה ותום לב הם תנאים הכרחיים לתחולת תקנת השוק, אך אינם מספיקים. יש להוכיח את קיומם של כל ששת התנאים המצטברים, ובענייננו לא התקיימו תנאי המוכר ומהלך העסקים הרגיל.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'על שמשון להשיב את הפסנתר לגילה, היות שסחורה גנובה שאותרה יש תמיד להשיב לבעליה.', false, 'טענה זו שגויה. הכלל הוא אכן השבת סחורה גנובה לבעליה, אך תקנת השוק (סעיף 34 לחוק המכר) מהווה חריג לכלל זה, המאפשר לקונה תם לב לרכוש בעלות נקייה גם בנכס גנוב, אם מתקיימים כל תנאיה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'רכישה ממוכר שאינו סוחר',
    1, 'ראובן רכש רכב משומש מיוסי, אדם פרטי שאינו סוחר רכבים, במחיר שוק הוגן. הרכב נמסר לראובן, והוא פעל בתום לב מוחלט. כעבור זמן התברר שהרכב נגנב מבעליו המקורי, שמעון. מה הדין?', 'שאלה זו בוחנת את תנאי תקנת השוק במיטלטלין, ובפרט את הדרישה שהמוכר יהיה עוסק במכירת נכסים מסוגו של הממכר ושהמכירה תהיה במהלך עסקיו הרגיל. היא מדגישה כי רכישה מאדם פרטי שאינו סוחר, גם אם בתום לב ובתמורה, אינה מקנה הגנה מכוח תקנת השוק.', 'הכלל הבסיסי בדיני קניין הוא שאין אדם יכול להקנות לאחר יותר זכויות משיש לו (nemo dat quod non habet). דנ"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003) תקנת השוק שבסעיף 34 לחוק המכר, תשכ"ח-1968, מהווה חריג לכלל זה, ומאפשרת לקונה לרכוש בעלות נקייה גם ממי שאינו הבעלים, אם מתקיימים שישה תנאים מצטברים. חוק המכר, תשכ"ח-1968, סעיף 34 שניים מתנאים אלה הם שהנכס נקנה ממוכר העוסק במכירת נכסים מסוגו של הממכר, ושהמכירה הייתה במהלך העסקים הרגיל. דנ"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003) הפסיקה קבעה כי תנאים אלה מהווים מבחן אובייקטיבי לחובת תום הלב הנדרשת מהקונה, שכן מכירת נכס על ידי אדם שאינו רגיל בכך צריכה להדליק נורה אדומה אצל הקונה. ע"א (מחוזי תל אביב-יפו) 3059/05 אברהמי לאה נ'' אריה חברה לביטוח בע"מ (20.02.2008) במקרה הנדון, יוסי הוא אדם פרטי שאינו סוחר רכבים, ולכן תנאים אלה אינם מתקיימים. משלא התקיימו כל התנאים המצטברים, תקנת השוק אינה חלה, והבעלות ברכב נשארת בידי הבעלים המקורי, שמעון. ת"א (שלום נצ'') 41703-07-18 עמית יצחק נ'' מהיטבאל יזמות בע"מ (28.12.2020)',
    'הטעות הנפוצה היא להניח שתום לב ותמורה מספיקים לתחולת תקנת השוק, מבלי לתת משקל מספק לתנאים האובייקטיביים הנוגעים לזהות המוכר ולאופי המכירה.', '["תקנת השוק", "סעיף 34 לחוק המכר", "נכס נד", "מוכר העוסק במכירת נכסים", "מהלך עסקים רגיל", "nemo dat quod non habet", "תנאים מצטברים"]'::jsonb, '**וריאציה 1 — רכישה ממגרש רכבים:** מה הדין אם ראובן רכש את הרכב ממגרש רכבים מוכר? ← במקרה כזה, תנאי ''מוכר העוסק במכירת נכסים מסוגו של הממכר'' ו''מכירה במהלך העסקים הרגיל'' עשויים להתקיים, ויהיה צורך לבחון את יתר התנאים. ת"א (שלום פ"ת) 10049-11-16 יונתן צ''יפר נ'' אלין קאר בע"מ (21.01.2019)
**וריאציה 2 — רכישה מחברה שאינה עוסקת ברכבים:** מה הדין אם ראובן רכש את הרכב מחברה העוסקת בבניה ושיפוצים? ← במקרה כזה, לא יתקיים התנאי שהמוכר עוסק במכירת נכסים מסוגו של הממכר, ותקנת השוק לא תחול. ת"א (שלום ת"א) 57984-10-17 אס.אר. אקורד בע"מ נ'' יורודרייב ניהול ציי רכב והשכרה בע"מ (04.03.2020)
**וריאציה 3 — רכישה ממוכר פרטי שהציג עצמו כסוחר:** מה הדין אם יוסי הציג עצמו כסוחר רכבים, אך בפועל אינו כזה? ← תקנת השוק דורשת שהמוכר *יהיה* עוסק במכירת נכסים מסוגו של הממכר, ולא רק *יציג עצמו* ככזה. מדובר בתנאי אובייקטיבי. ע"א (מחוזי תל אביב-יפו) 3059/05 אברהמי לאה נ'' אריה חברה לביטוח בע"מ (20.02.2008)', 'רכישת נכס ממוכר שאינו סוחר או שלא במהלך עסקיו הרגיל ← אינה מקנה הגנה מכוח תקנת השוק, גם אם הקונה תם לב ושילם תמורה.',
    '["חוק המכר, תשכ\"ח-1968, סעיף 34", "דנ\"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003)", "ע\"א (מחוזי תל אביב-יפו) 3059/05 אברהמי לאה נ'' אריה חברה לביטוח בע\"מ (20.02.2008)", "ת\"א (שלום פ\"ת) 10049-11-16 יונתן צ''יפר נ'' אלין קאר בע\"מ (21.01.2019)", "ת\"א (שלום ת\"א) 57984-10-17 אס.אר. אקורד בע\"מ נ'' יורודרייב ניהול ציי רכב והשכרה בע\"מ (04.03.2020)", "ת\"א (שלום נצ'') 41703-07-18 עמית יצחק נ'' מהיטבאל יזמות בע\"מ (28.12.2020)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'ראובן יזכה בבעלות על הרכב מכוח תקנת השוק, שכן הוא פעל בתום לב ושילם תמורה הוגנת.', false, 'טענה זו שגויה. תום לב ותמורה אינם מספיקים. תקנת השוק דורשת שהמוכר יהיה עוסק במכירת נכסים מסוגו של הממכר ושהמכירה תהיה במהלך עסקיו הרגיל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'על ראובן להשיב את הרכב לשמעון, שכן לא התקיימו כל תנאי תקנת השוק.', true, 'תשובה זו נכונה. תקנת השוק אינה חלה במקרה זה, שכן יוסי אינו עוסק במכירת רכבים, והמכירה לא הייתה במהלך עסקיו הרגיל. לכן, הבעלות נשארת בידי הבעלים המקורי, שמעון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'ראובן יזכה בבעלות על הרכב, אך יהיה עליו לפצות את שמעון על הנזק שנגרם לו.', false, 'טענה זו שגויה. אם תקנת השוק חלה, הקונה זוכה בבעלות נקייה ללא צורך בפיצוי הבעלים המקורי. אם אינה חלה, הקונה אינו זוכה בבעלות כלל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'שמעון יקבל את הרכב בחזרה, אך יהיה עליו לפצות את ראובן על התמורה ששילם.', false, 'טענה זו שגויה. הדין הישראלי אינו קובע הסדר של ''פדיון'' (כמו במשפט העברי) במקרה שתקנת השוק אינה חלה, אלא אם כן מדובר בנסיבות חריגות ביותר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'דרישת התמורה הממשית בתקנת השוק',
    2, 'לוי רכש תמונה עתיקה מגלריה מוכרת, העוסקת במכירת יצירות אמנות, במהלך עסקיה הרגיל. לוי שילם תמורה סמלית בלבד, מתוך הנחה שהתמונה חסרת ערך. כעבור זמן התברר שהתמונה גנובה ובעלת ערך רב. האם לוי יזכה בבעלות על התמונה מכוח תקנת השוק?', 'שאלה זו מתמקדת בדרישת התמורה הממשית כתנאי לתחולת תקנת השוק לפי סעיף 34 לחוק המכר. היא מדגישה את חשיבותה של דרישה זו, כפי שפורשה בהלכת כנען, למניעת התעשרות שלא כדין ולהבטחת תום לבו של הקונה, במיוחד במקרים של פער ניכר בין התמורה ששולמה לבין ערכו האמיתי של הנכס.', 'אחד התנאים המצטברים לתחולת תקנת השוק, אף שאינו מופיע במפורש בסעיף 34 לחוק המכר, הוא דרישת התמורה. דרישה זו נלמדת מהגדרת ''מכר'' בסעיף 1 לחוק המכר כ''הקניית נכס תמורת מחיר'', וכן נועדה להעיד על תום לבו של הקונה. ה"פ (שלום י-ם) 10262-04-20 אדוה חדד נ'' פאדי עבדו (19.03.2021) הלכת כנען קבעה כי התמורה לעניין תקנת השוק אינה יכולה להיות תמורה סמלית, אלא נדרשת ''תמורה ממשית''. דנ"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003) דרישה זו נועדה לשרת את תכליתה הכפולה של תקנת השוק: למנוע מראש את היווצרות העימות בין הבעלים לקונה, ולהבטיח פתרון שיגרור מינימום נזקים. ע"ק (שלום ראשל"צ) 74107-05-25 פאדי אבו קישק נ'' משטרת ישראל (03.09.2025) במקרה הנדון, לוי שילם תמורה סמלית בלבד עבור התמונה העתיקה. תמורה זו אינה עומדת בדרישת ''התמורה הממשית'' כפי שפורשה בהלכת כנען, במיוחד כאשר מתברר שהנכס בעל ערך רב. לכן, תקנת השוק לא תחול, ולוי לא יזכה בבעלות על התמונה. ע"א 8922/22 מכון ז''בוטינסקי בישראל נ'' המלך דוד מכירות פומביות בע"מ (25.02.2026)',
    'הטעות הנפוצה היא לחשוב שכל תמורה, גם אם סמלית, מספיקה לצורך תקנת השוק, מבלי להבין את הדרישה לתמורה ''ממשית'' ואת תכליתה.', '["תקנת השוק", "סעיף 34 לחוק המכר", "תמורה ממשית", "תמורה סמלית", "הלכת כנען", "תום לב", "התעשרות שלא כדין"]'::jsonb, '**וריאציה 1 — תמורה נמוכה אך לא סמלית:** מה הדין אם לוי שילם מחיר נמוך משמעותית ממחיר השוק, אך לא סמלי? ← פער ניכר בתמורה עשוי לשמש יסוד למסקנה כי היה יסוד בלתי כשר בעסקה ועל חוסר תום לב, ובכך לשלול את תחולת תקנת השוק. ע"ק (שלום ראשל"צ) 74107-05-25 פאדי אבו קישק נ'' משטרת ישראל (03.09.2025)
**וריאציה 2 — תמורה מלאה אך הנכס גנוב:** מה הדין אם לוי שילם תמורה מלאה והוגנת, אך התמונה גנובה? ← אם כל יתר תנאי תקנת השוק מתקיימים, תשלום תמורה מלאה והוגנת יחזק את תום לבו של הקונה ויאפשר את תחולת תקנת השוק. דנ"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003)
**וריאציה 3 — תמורה שאינה כספית:** האם תמורה שאינה כספית (למשל, החלפת נכסים) יכולה להיחשב תמורה ממשית? ← כן, תמורה אינה חייבת להיות כספית, אך עליה להיות בעלת ערך ממשי. ה"פ (שלום עכו) 222/97 מחיאלדין דבאח נ'' מגדל חברה לביטוח בע"מ (21.08.1998)', 'תקנת השוק דורשת תמורה ממשית (ולא סמלית) כדי להבטיח את תום לבו של הקונה ולמנוע התעשרות שלא כדין, במיוחד כאשר קיים פער ניכר בין התמורה לערך הנכס.',
    '["חוק המכר, תשכ\"ח-1968, סעיף 34", "דנ\"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003)", "ה\"פ (שלום י-ם) 10262-04-20 אדוה חדד נ'' פאדי עבדו (19.03.2021)", "ע\"א 8922/22 מכון ז''בוטינסקי בישראל נ'' המלך דוד מכירות פומביות בע\"מ (25.02.2026)", "ע\"ק (שלום ראשל\"צ) 74107-05-25 פאדי אבו קישק נ'' משטרת ישראל (03.09.2025)", "ה\"פ (שלום עכו) 222/97 מחיאלדין דבאח נ'' מגדל חברה לביטוח בע\"מ (21.08.1998)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, שכן כל התנאים האחרים של תקנת השוק התקיימו, ותמורה סמלית מספיקה.', false, 'טענה זו שגויה. הפסיקה קבעה כי תקנת השוק דורשת תמורה ממשית, ולא תמורה סמלית, כדי להבטיח את תום הלב של הקונה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, שכן תקנת השוק דורשת תמורה ממשית, ולא תמורה סמלית, כדי להבטיח את תום לבו של הקונה.', true, 'תשובה זו נכונה. הלכת כנען קבעה כי תמורה סמלית אינה מספקת לצורך תקנת השוק, שכן דרישת התמורה הממשית נועדה להבטיח את תום לבו של הקונה ולמנוע התעשרות שלא כדין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, אך רק אם לוי יוכיח שלא ידע על ערכה האמיתי של התמונה בעת הרכישה.', false, 'טענה זו שגויה. ידיעה על ערך הנכס קשורה לתום הלב, אך גם אם הקונה לא ידע, תמורה סמלית עדיין שוללת את תחולת תקנת השוק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, שכן תקנת השוק אינה חלה על יצירות אמנות עתיקות.', false, 'טענה זו שגויה. תקנת השוק חלה על ''נכס נד'' (מיטלטלין), ויצירות אמנות נכללות בכך. אין חריג ספציפי ליצירות אמנות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'תום לב אובייקטיבי מול סובייקטיבי',
    3, 'דנה רכשה שעון יוקרתי בשוק פשפשים במחיר זעום, ממוכר אקראי שאינו סוחר שעונים. דנה לא ידעה שהשעון גנוב, אך גם לא טרחה לבדוק את מקורו, מתוך מחשבה שמדובר בחיקוי זול. האם דנה נחשבת תמת לב לצורך תקנת השוק?', 'שאלה זו עוסקת בדרישת תום הלב כתנאי לתחולת תקנת השוק במיטלטלין. היא בוחנת את ההבחנה בין תום לב סובייקטיבי לבין ''עצימת עיניים'', ומדגישה כי תום לב סובייקטיבי נשלל כאשר נסיבות העסקה מעוררות חשד סביר, והקונה נמנע מלבררו, גם אם לא ידע בפועל על הפגם בבעלות.', 'תום הלב הוא אחד מששת התנאים המצטברים לתחולת תקנת השוק, והוא תנאי סובייקטיבי. ת"א (שלום פ"ת) 10049-11-16 יונתן צ''יפר נ'' אלין קאר בע"מ (21.01.2019) עם זאת, תום הלב של הקונה יישלל לא רק בידיעה בפועל שהמוכר אינו הבעלים, אלא גם בנסיבות של ''עצימת עיניים'', כלומר קיומו של חשד שהקונה נמנע בכוונה מלבררו. ת"א (שלום פ"ת) 10049-11-16 יונתן צ''יפר נ'' אלין קאר בע"מ (21.01.2019) הפסיקה קבעה כי נסיבות כגון רכישת נכס במחיר זעום, במיוחד בשוק פשפשים או ממוכר אקראי, צריכות לעורר חשד אצל הקונה הסביר. דנ"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003) במקרה הנדון, רכישת שעון יוקרתי במחיר זעום ממוכר אקראי בשוק פשפשים, גם אם דנה חשבה שמדובר בחיקוי, הייתה צריכה לעורר חשד. אי-בדיקה בנסיבות אלו מהווה ''עצימת עיניים'' השוללת את תום לבה, ולכן תקנת השוק לא תחול. ת"א (שלום ת"א) 5143-06-18 אלדר גנזל נ'' עדנאן עינאש (15.01.2023)',
    'הטעות הנפוצה היא לפרש את תום הלב כדרישה לידיעה בפועל בלבד, מבלי להכיר בכך ש''עצימת עיניים'' (התעלמות מחשד סביר) שוללת אף היא את תום הלב הנדרש.', '["תקנת השוק", "סעיף 34 לחוק המכר", "תום לב סובייקטיבי", "עצימת עיניים", "חשד סביר", "מחיר זעום", "מוכר אקראי"]'::jsonb, '**וריאציה 1 — רשלנות מול עצימת עיניים:** האם רשלנות בבדיקה שוללת תום לב? ← רשלנות כשלעצמה אינה שוללת תום לב, אך רשלנות רבתי, המצביעה על חשד שהקונה נמנע מלבררו, יכולה להיחשב כעצימת עיניים ולשלול תום לב. ה"פ (שלום חד'') 11300-09-10 סמי אביטן נ'' אמל סגייר לסחר והשקעות בע"מ (07.03.2013)
**וריאציה 2 — תום לב מתמשך:** עד מתי נדרש תום לבו של הקונה? ← תום הלב נדרש להימשך משלב הקנייה ועד קבלת הנכס לחזקתו. ע"א 8922/22 מכון ז''בוטינסקי בישראל נ'' המלך דוד מכירות פומביות בע"מ (25.02.2026)
**וריאציה 3 — סטנדרט מחמיר לנכסי תרבות:** האם יש סטנדרט תום לב מחמיר יותר לנכסי קניין תרבותי? ← כן, בנסיבות של רכישת נכס קניין תרבותי שידוע כי היה בעבר ברשות ארכיון ציבורי, מוצדק לאמץ סטנדרט מחמיר במיוחד של תום לב, שיחייב את הקונה לדרוש ולחקור בזמן הרכישה אחר נסיבות הגעתו של הפריט לידי המוכר. ע"א 8922/22 מכון ז''בוטינסקי בישראל נ'' המלך דוד מכירות פומביות בע"מ (25.02.2026)', 'תום הלב הנדרש בתקנת השוק הוא סובייקטיבי, אך הוא נשלל במקרה של ''עצימת עיניים'' (התעלמות מחשד סביר), כגון רכישת נכס במחיר זעום ממוכר אקראי.',
    '["חוק המכר, תשכ\"ח-1968, סעיף 34", "דנ\"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003)", "ת\"א (שלום פ\"ת) 10049-11-16 יונתן צ''יפר נ'' אלין קאר בע\"מ (21.01.2019)", "ת\"א (שלום ת\"א) 5143-06-18 אלדר גנזל נ'' עדנאן עינאש (15.01.2023)", "ה\"פ (שלום חד'') 11300-09-10 סמי אביטן נ'' אמל סגייר לסחר והשקעות בע\"מ (07.03.2013)", "ע\"א 8922/22 מכון ז''בוטינסקי בישראל נ'' המלך דוד מכירות פומביות בע\"מ (25.02.2026)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, שכן תום הלב הנדרש הוא סובייקטיבי, ודנה לא ידעה בפועל שהשעון גנוב.', false, 'טענה זו שגויה. אף שתום הלב הוא סובייקטיבי, הוא נשלל במקרה של ''עצימת עיניים'', כלומר קיום חשד שהקונה נמנע בכוונה מלבררו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, שכן בנסיבות אלו, מחיר זעום ממוכר אקראי היה צריך לעורר חשד, ואי-בדיקה מהווה עצימת עיניים השוללת תום לב.', true, 'תשובה זו נכונה. תום הלב הסובייקטיבי נשלל במקרה של ''עצימת עיניים'', כאשר נסיבות העסקה (מחיר זעום, מוכר אקראי) היו צריכות לעורר חשד סביר, והקונה נמנע מלבררו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם דנה תוכיח כי לא הייתה לה כל דרך לברר את מקור השעון.', false, 'טענה זו שגויה. הנטל הוא על הקונה להוכיח תום לב, ואי-בדיקה בנסיבות מחשידות שוללת אותו, גם אם לא הייתה דרך קלה לברר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, שכן תקנת השוק דורשת תום לב אובייקטיבי, ודנה לא עמדה בו.', false, 'טענה זו שגויה. תום הלב הנדרש בסעיף 34 לחוק המכר הוא סובייקטיבי, אך הוא נשלל במקרה של עצימת עיניים, שאינה זהה לתום לב אובייקטיבי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'נטל ההוכחה בתקנת השוק',
    4, 'ראובן רכש נכס נד ממוכר העוסק במכירת נכסים מסוגו, במהלך עסקיו הרגיל, וקיבל את החזקה בנכס. הבעלים המקורי של הנכס טוען כי הנכס נגנב ממנו ודורש את השבתו. ראובן טוען לתחולת תקנת השוק. על מי מוטל נטל ההוכחה לקיום תנאי תקנת השוק, ומהו רף ההוכחה הנדרש?', 'שאלה זו עוסקת בנטל ההוכחה וברף ההוכחה הנדרשים לצורך תחולת תקנת השוק במיטלטלין. היא מדגישה כי בשל התוצאה הדרסטית של תקנת השוק (שלילת בעלות מהבעלים המקורי), נטל ההוכחה מוטל על הקונה הטוען לתחולתה, ועליו לעמוד ברף דרישות גבוה במיוחד.', 'תקנת השוק שבסעיף 34 לחוק המכר, תשכ"ח-1968, היא חריג לכלל הבסיסי בדיני קניין לפיו אין אדם יכול להקנות לאחר יותר זכויות משיש לו. דנ"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003) בשל התוצאות הדרסטיות של תקנת השוק, שהיא שלילת בעלות מהבעלים המקורי, נטל ההוכחה לקיום כל ששת התנאים המצטברים מוטל על הקונה הטוען לתחולתה. ה"פ (שלום י-ם) 10262-04-20 אדוה חדד נ'' פאדי עבדו (19.03.2021) הפסיקה, ובפרט הלכת כנען, קבעה כי יש למקם את רף הדרישות שבאותו סעיף ''גבוה ככל שניתן'', במידה שתצדיק את הקניית הנכס לקונה. דנ"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003) במקרה הנדון, ראובן הוא הקונה הטוען לתחולת תקנת השוק, ולכן עליו מוטל הנטל להוכיח את קיומם של כל ששת התנאים המצטברים, ועליו לעמוד ברף הוכחה גבוה זה. ה"ת (שלום י-ם) 47003-02-21 תומר אחיאל נ'' מדינת ישראל (31.05.2021)',
    'הטעות הנפוצה היא להניח שנטל ההוכחה בתקנת השוק הוא כבכל הליך אזרחי (מאזן הסתברויות רגיל), מבלי להכיר ברף ההוכחה הגבוה המיוחד הנדרש בשל אופייה של התקנה.', '["תקנת השוק", "סעיף 34 לחוק המכר", "נטל ההוכחה", "רף הוכחה גבוה", "הלכת כנען", "nemo dat quod non habet", "זכות קניין"]'::jsonb, '**וריאציה 1 — נטל הוכחת תום לב:** על מי מוטל נטל הוכחת תום לבו של הקונה? ← נטל הראיה בשאלה אם הקונה קיבל את החזקה בנכס בתום לב חל על הקונה המסתמך על הוראת סעיף 34 לחוק המכר. ה"פ (שלום נצרת) 160/06 סוזן בן יאיר נ'' בנק הפועלים בע"מ (27.05.2007)
**וריאציה 2 — נטל הוכחת תמורה:** על מי מוטל נטל הוכחת התמורה? ← נטל ההוכחה לקיום התמורה מוטל על הקונה הטוען לתחולת תקנת השוק. ת"א (שלום אשד'') 32316-06-17 הידקו - גבעתי בע"מ נ'' יהודה לוי (25.10.2021)
**וריאציה 3 — השפעת אשם תורם של הבעלים המקורי:** האם אשם תורם של הבעלים המקורי משפיע על נטל ההוכחה? ← שאלת קיומו של אשם תורם מצד הבעלים החוקי תתעורר רק כאשר אין תחולה לתקנת השוק, שהרי אם הוכיח הקונה כי הוא נהנה מתקנת השוק תישלל ממילא זכות הבעלים החוקי, ולעניין זה אין נפקא מינה אם היה אשם מצדו, אם לאו. ת"א (שלום אי'') 25732-02-13 דרבי יוסי-חברה להשקעות להשכרה ולבניה (1989) בע"מ נ'' יוסף עייש (03.07.2015)', 'נטל ההוכחה לקיום כל תנאי תקנת השוק מוטל על הקונה הטוען לתחולתה, ועליו לעמוד ברף הוכחה גבוה במיוחד, בשל התוצאה הדרסטית של שלילת בעלות מהבעלים המקורי.',
    '["חוק המכר, תשכ\"ח-1968, סעיף 34", "דנ\"א 2568/97 זהבה כנען נ'' ממשלת ארצות-הברית, נז(2) 632 (20.02.2003)", "ה\"פ (שלום י-ם) 10262-04-20 אדוה חדד נ'' פאדי עבדו (19.03.2021)", "ה\"ת (שלום י-ם) 47003-02-21 תומר אחיאל נ'' מדינת ישראל (31.05.2021)", "ת\"א (שלום אשד'') 32316-06-17 הידקו - גבעתי בע\"מ נ'' יהודה לוי (25.10.2021)", "ה\"פ (שלום נצרת) 160/06 סוזן בן יאיר נ'' בנק הפועלים בע\"מ (27.05.2007)", "ת\"א (שלום אי'') 25732-02-13 דרבי יוסי-חברה להשקעות להשכרה ולבניה (1989) בע\"מ נ'' יוסף עייש (03.07.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'נטל ההוכחה מוטל על הבעלים המקורי, שכן הוא הטוען לגניבה, ורף ההוכחה הוא מאזן הסתברויות.', false, 'טענה זו שגויה. הבעלים המקורי צריך להוכיח את בעלותו, אך נטל ההוכחה לקיום תנאי תקנת השוק מוטל על הקונה הטוען לתחולתה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'נטל ההוכחה מוטל על ראובן (הקונה), ועליו להוכיח את קיום כל התנאים ברף דרישות גבוה ככל שניתן.', true, 'תשובה זו נכונה. תקנת השוק היא חריג לכלל הקנייני הבסיסי, ולכן נטל ההוכחה לקיום כל תנאיה מוטל על הקונה הטוען לתחולתה, ורף ההוכחה הנדרש הוא גבוה, כפי שנקבע בהלכת כנען.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'נטל ההוכחה מוטל על ראובן, ורף ההוכחה הוא מאזן הסתברויות רגיל, כבכל הליך אזרחי.', false, 'טענה זו שגויה. אף שההליך הוא אזרחי, הפסיקה קבעה רף הוכחה גבוה במיוחד לתחולת תקנת השוק, בשל תוצאותיה הדרסטיות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'נטל ההוכחה מוטל על הבעלים המקורי, ועליו להוכיח את אי-קיום תנאי תקנת השוק ברף דרישות גבוה.', false, 'טענה זו שגויה. נטל ההוכחה לקיום התנאים מוטל על הקונה, ולא על הבעלים המקורי להוכיח את אי-קיומם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 19, '2023-S-S-Q19';
END
$$;

-- ============================================================
-- Q20 — 2023-S-S-Q20 — chapter=contracts subtopic=general_part
-- classifier_note: Pre-contractual good faith / breakdown of apartment negotiations — חוזים חלק כללי
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '16e4065c-6d70-4dab-9b7e-e48a94b170b0'::uuid;
  v_group_id uuid := 'cbaaaf01-13e6-4417-a5f0-9a67afa62125'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '229935f8-6039-4249-912f-648dc1ebdcfd'::uuid;
  v_ang_1 uuid := '9b60a009-9041-41e2-85e4-bbdc96d723b8'::uuid;
  v_ang_2 uuid := 'bf9ad693-04b7-4d19-ab3a-3ae95710d312'::uuid;
  v_ang_3 uuid := '18337c74-1642-4c70-be94-307fc6286b64'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q20';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 20, '2023-S-S-Q20';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q20', v_chapter_id, v_subtopic_id, 'רינת, אשר חיפשה לרכוש דירה למגורים ברחוב שקט באזור המרכז, נענתה למודעה שפרסמו בני הזוג דן באינטרנט לדירה ברחוב רביבים בגבעתיים. רינת הגיעה במועד שנקבע להציג את הדירה, התרשמה מאוד ומיד הביעה נכונות ורצינות לנהל משא ומתן על המחיר. המשא ומתן נערך מול גבי, המתווך של בני הזוג דן. רינת סיפרה לבני הזוג דן ולגבי כי חשוב לה לגור במקום שקט. גבי, אשר ידע כי בעתיד הקרוב מתוכנן לקום ברחוב רביבים קניון חדש, סיפר על כך לבני הזוג דן אך לא גילה זאת לרינת. כעבור כמה חודשים גילתה רינת בעקבות פרסומים בעיתון על הקמת הקניון החדש, והיא מעוניינת לבטל את החוזה באופן מיידי ואף לתבוע פיצויים. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 20}'::jsonb, 'השאלה עוסקת בחובת תום הלב במשא ומתן לקראת כריתתו של חוזה, הקבועה בסעיף 12 לחוק החוזים (חלק כללי), תשל"ג-1973. היא מתמקדת בחובת הגילוי של מידע מהותי, ובאחריותם של צדדים לחוזה ושל שלוחיהם (כגון מתווך) בגין הפרת חובה זו, כפי שנקבעה בהלכת פנידר ובפסיקה מאוחרת יותר.', 'חובת תום הלב במשא ומתן, הקבועה בסעיף 12(א) לחוק החוזים (חלק כללי), תשל"ג-1973, מחייבת אדם לנהוג בדרך מקובלת ובתום לב. חוק החוזים (חלק כללי), תשל"ג-1973, סעיף 12(א) חובה זו כוללת חובת גילוי של עובדות מהותיות, גם אם הצד השני יכול היה לגלותן בעצמו, כאשר גילוי זה מתחייב ממהות העסקה ומנסיבות המקרה. ע"א 8227/20 ערן קסירר נ'' חיים אמסלם (12.07.2023) ת"א (שלום חי'') 8567-03-21 פוצקר בע"מ נ'' עזבון המנוח נתנאל סילס (01.12.2024)
הלכת ד"נ 7/81 פנידר נ'' קסטרו קבעה כי חובת תום הלב חלה על כל מי שנוטל חלק במשא ומתן, ולא רק על הצדדים העתידיים לחוזה. ע"א 8910/05 א. אדמון בע"מ נ'' זלמה וינבלט (20.09.2007) נבו - המתמחה דיני חוזים וחיובים (2026) | תום לב במשא ומתן לפיכך, גם שלוח (כמו מתווך) יכול לחוב באחריות אישית בגין הפרת חובת תום הלב. זוהר גושן אסף אקשטיין דיני חברות (2023) | 3.3.2.1 השלב הטרום-חוזי
במקרה הנדון, רינת הדגישה את חשיבות השקט עבורה. גבי המתווך ידע על תוכנית הקמת הקניון החדש, מידע מהותי שסותר את ציפייתה של רינת לשקט, ולא גילה לה זאת. אי-גילוי זה מהווה הפרה של חובת הגילוי הנגזרת מתום הלב במשא ומתן. ת"א (שלום חי'') 56908-07-19 דורון לוי נ'' אלמוג ב. ז. בניה והשקעות בע"מ (29.01.2023) ת"א (מחוזי ב"ש) 7137-09-18 נתנאל אטיאס נ'' אלון גורן (16.11.2025)
הפרת חובת הגילוי על ידי גבי, המתווך, מהווה גם הטעיה במחדל (סעיף 15 לחוק החוזים), המזכה את רינת בביטול החוזה. ת"א (מחוזי מרכז) 970-09-09 ישפאר הום טק בע"מ נ'' אלקטרה מוצרי צריכה (1951) בע"מ (04.09.2017) בנוסף, רינת זכאית לפיצויים (פיצויי הסתמכות) הן מבני הזוג דן (המוכרים) והן מגבי (המתווך) באופן אישי, שכן שניהם הפרו את חובת תום הלב. ת"א (שלום ת"א) 8029-06-19 דור-אלון אנרגיה בישראל (1988) בע"מ נ'' אבגור אביזרי מיזוג אויר בע"מ (17.09.2024) צפורה כהן נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023) | 1. אחריות אזרחית', 'הטעות הנפוצה היא להניח שחובת הגילוי חלה רק על הצדדים הישירים לחוזה, או שאי-גילוי מידע אינו מהווה הפרה של חובת תום הלב, ובכך להתעלם מהיקפה הרחב של חובה זו ומהאחריות האישית של שלוחים.',
    '["חובת תום לב במשא ומתן", "סעיף 12 לחוק החוזים", "חובת גילוי", "אחריות אישית של שלוח/מתווך", "הטעיה במחדל", "ביטול חוזה", "פיצויי הסתמכות", "ד\"נ פנידר נ'' קסטרו"]'::jsonb, '**וריאציה 1 — גבי לא ידע:** מה הדין אם גבי לא ידע על הקניון המתוכנן? ← אם גבי לא ידע, לא ניתן להטיל עליו אחריות אישית בגין אי-גילוי, שכן חובת הגילוי חלה על מידע המצוי בידיעתו. ת"א (שלום חי'') 56908-07-19 דורון לוי נ'' אלמוג ב. ז. בניה והשקעות בע"מ (29.01.2023)
**וריאציה 2 — רינת יכלה לגלות:** מה הדין אם רינת יכלה לגלות בקלות על הקניון? ← גם אם רינת יכלה לגלות בעצמה, חובת הגילוי עדיין חלה על גבי והמוכרים, שכן מדובר במידע מהותי וקיים פער מידע. ע"א 8227/20 ערן קסירר נ'' חיים אמסלם (12.07.2023)
**וריאציה 3 — המוכרים לא ידעו:** מה הדין אם בני הזוג דן לא ידעו על הקניון? ← אם המוכרים לא ידעו, לא ניתן להטיל עליהם אחריות בגין אי-גילוי, אך הם עדיין יכולים להיות כפופים לביטול החוזה עקב הטעיה שנגרמה על ידי שלוחם (המתווך). ת"א (שלום חי'') 8567-03-21 פוצקר בע"מ נ'' עזבון המנוח נתנאל סילס (01.12.2024)', 'אי-גילוי מידע מהותי על ידי מתווך, בידיעת המוכרים, מהווה הפרת חובת תום הלב במשא ומתן (סעיף 12 לחוק החוזים) והטעיה במחדל. רינת זכאית לבטל את החוזה ולתבוע פיצויים הן מהמוכרים והן מהמתווך באופן אישי.', '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "ד\"נ 7/81 פנידר חברה להשקעות פיתוח ובנין בע\"מ נ'' קסטרו, פ\"ד לז(4) 673 (14.12.1983)", "ע\"א 7721/22 ד\"ר עופר ולטר נ'' עו\"ד יוסף שטבהולץ (24.12.2024)", "ע\"א 8910/05 א. אדמון בע\"מ נ'' זלמה וינבלט (20.09.2007)", "ע\"א 8227/20 ערן קסירר נ'' חיים אמסלם (12.07.2023)", "ת\"א (שלום חי'') 8567-03-21 פוצקר בע\"מ נ'' עזבון המנוח נתנאל סילס (01.12.2024)", "ת\"א (שלום חי'') 56908-07-19 דורון לוי נ'' אלמוג ב. ז. בניה והשקעות בע\"מ (29.01.2023)", "ת\"א (מחוזי מרכז) 970-09-09 ישפאר הום טק בע\"מ נ'' אלקטרה מוצרי צריכה (1951) בע\"מ (04.09.2017)", "נבו - המתמחה דיני חוזים וחיובים (2026) | תום לב במשא ומתן", "צפורה כהן נושאי משרה בחברה – דרכים לשחרורם מאחריות (2023) | 1. אחריות אזרחית"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''general_part'' | classifier_note: Pre-contractual good faith / breakdown of apartment negotiations — חוזים חלק כללי | source_review_note: השאלה עוסקת בדיני חוזים, תחום שאינו נכלל ישירות ברשימת הפרקים הדיוניים הקיימת. תת-הנושא ''הליכים'' נבחר כברירת מחדל תחת ''סדר דין אזרחי'' בשל הקשר העקיף להליכים אזרחיים, אך אינו משקף את מהות השאלה. יש לשקול הוספת פרק ''דיני חוזים'' ותתי נושאים רלוונטיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'רינת זכאית לבטל את החוזה, אך לא תוכל לתבוע פיצויים.', false, 'טענה זו שגויה. הפרת חובת תום הלב במשא ומתן, ובכלל זה אי-גילוי מידע מהותי, מזכה את הנפגע הן בביטול החוזה (אם מדובר בהטעיה) והן בפיצויים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'רינת זכאית לבטל את החוזה ואף לתבוע פיצויים מבני הזוג דן, אך לא מגבי.', false, 'טענה זו שגויה. חובת תום הלב חלה על כל מי שנוטל חלק במשא ומתן, לרבות שלוח או מתווך, ולכן ניתן להטיל אחריות אישית גם על גבי המתווך.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'רינת זכאית לבטל את החוזה ואף לתבוע פיצויים מבני הזוג דן ומגבי.', true, 'תשובה זו נכונה. אי-גילוי מידע מהותי על ידי המתווך, בידיעת המוכרים, מהווה הפרה של חובת תום הלב במשא ומתן. הפרה זו מזכה את רינת בביטול החוזה (עקב הטעיה) ובפיצויים הן מהמוכרים והן מהמתווך באופן אישי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'רינת לא זכאית לבטל את החוזה, על פי הכלל של "ייזהר הקונה".', false, 'טענה זו שגויה. הכלל של "ייזהר הקונה" נסוג מפני חובת תום הלב במשא ומתן, המחייבת גילוי יזום של מידע מהותי, במיוחד כאשר קיים פער מידע בין הצדדים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'אחריות אישית של מנהל חברה בגין אי-גילוי במשא ומתן',
    1, 'חברה קבלנית ניהלה משא ומתן למכירת דירה באמצעות מנהלה, יוסי. יוסי ידע כי בתוכנית המתאר העירונית קיימת הגבלה משמעותית על אפשרויות הבנייה העתידיות במגרש הסמוך לדירה, אך לא גילה זאת לקונה, שחיפש דירה עם פוטנציאל השבחה. החוזה נחתם. האם ניתן להטיל אחריות אישית על יוסי בגין הפרת חובת הגילוי?', 'שאלה זו בוחנת את היקף האחריות האישית של אורגן (מנהל) בחברה בגין הפרת חובת תום הלב במשא ומתן טרום-חוזי. היא מדגישה את ההבחנה שנקבעה בפסיקה בין סטנדרט תום הלב האובייקטיבי החל על החברה לבין הסטנדרט הסובייקטיבי המחמיר הנדרש להטלת אחריות אישית על האורגן.', 'חובת תום הלב במשא ומתן, הקבועה בסעיף 12(א) לחוק החוזים (חלק כללי), תשל"ג-1973, חלה על כל מי שנוטל חלק במשא ומתן, לרבות אורגן של חברה המנהל משא ומתן בשמה. חוק החוזים (חלק כללי), תשל"ג-1973, סעיף 12(א) ע"א 7721/22 ד"ר עופר ולטר נ'' עו"ד יוסף שטבהולץ (24.12.2024) הפסיקה קבעה כי ניתן להטיל אחריות אישית על אורגן של חברה בגין הפרת חובת תום הלב במשא ומתן. ת"א (מחוזי ת"א) 2169-09-21 יגאל שלו סעדון נ'' 1 מ.י.ד.ר פסגות דורמ בע"מ (16.04.2026) עם זאת, בעוד שהחברה עצמה חבה בחובת תום לב אובייקטיבית, לצורך הטלת אחריות אישית על האורגן, נדרש סטנדרט מחמיר יותר של חוסר תום לב סובייקטיבי, כלומר אשם אישי במעשים או במחדלים. ע"א 7721/22 ד"ר עופר ולטר נ'' עו"ד יוסף שטבהולץ (24.12.2024) נבו - המתמחה דיני חוזים וחיובים (2026) | תום לב במשא ומתן במקרה הנדון, יוסי ידע על הגבלת הבנייה ולא גילה אותה. אי-גילוי זה מהווה הפרה של חובת הגילוי הנגזרת מתום הלב. כדי להטיל עליו אחריות אישית, יש להוכיח כי פעל בחוסר תום לב סובייקטיבי, כלומר שהיה לו אשם אישי במחדל הגילוי. ת"א (מחוזי ת"א) 2169-09-21 יגאל שלו סעדון נ'' 1 מ.י.ד.ר פסגות דורמ בע"מ (16.04.2026)',
    'הטעות הנפוצה היא לבלבל בין סטנדרט תום הלב האובייקטיבי החל על החברה לבין הסטנדרט הסובייקטיבי המחמיר הנדרש להטלת אחריות אישית על האורגן.', '["סעיף 12 לחוק החוזים", "חובת גילוי", "אחריות אישית", "אורגן חברה", "תום לב אובייקטיבי", "תום לב סובייקטיבי", "אשם אישי", "ד\"נ פנידר"]'::jsonb, '**וריאציה 1 — אי-ידיעה של המנהל:** מה הדין אם יוסי לא ידע על הגבלת הבנייה? ← אם יוסי לא ידע על הגבלת הבנייה, לא ניתן להטיל עליו אחריות אישית בגין חוסר תום לב סובייקטיבי, שכן לא התקיים אשם אישי. ע"א 7721/22 ד"ר עופר ולטר נ'' עו"ד יוסף שטבהולץ (24.12.2024)
**וריאציה 2 — מצג שווא אקטיבי:** מה הדין אם יוסי הצהיר במפורש שאין הגבלות בנייה? ← מצג שווא אקטיבי מחזק את הטענה לחוסר תום לב סובייקטיבי ולאשם אישי, ומקל על הטלת אחריות אישית. ע"א 214/23 פרוספריטי סאל נדל"ן ייעוץ השקעות ושיווק נכסים בע"מ נ'' הבניין ברח'' יפו 21 ירושלים בע"מ (21.07.2024)
**וריאציה 3 — אחריות החברה:** האם החברה תהיה חייבת בפיצויים גם אם יוסי לא יחויב אישית? ← כן, החברה יכולה להיות חייבת בפיצויים מכוח הפרת חובת תום הלב האובייקטיבית, גם אם לא הוכח אשם אישי של יוסי. נבו - המתמחה דיני חוזים וחיובים (2026) | תום לב במשא ומתן', 'אחריות אישית של אורגן חברה בגין אי-גילוי במשא ומתן ← דורשת הוכחת חוסר תום לב סובייקטיבי (אשם אישי) של האורגן, ולא רק הפרת חובת תום לב אובייקטיבית.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "ע\"א 7721/22 ד\"ר עופר ולטר נ'' עו\"ד יוסף שטבהולץ (24.12.2024)", "ת\"א (מחוזי ת\"א) 2169-09-21 יגאל שלו סעדון נ'' 1 מ.י.ד.ר פסגות דורמ בע\"מ (16.04.2026)", "ע\"א 214/23 פרוספריטי סאל נדל\"ן ייעוץ השקעות ושיווק נכסים בע\"מ נ'' הבניין ברח'' יפו 21 ירושלים בע\"מ (21.07.2024)", "נבו - המתמחה דיני חוזים וחיובים (2026) | תום לב במשא ומתן"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, שכן יוסי פעל כשלוח של החברה, והאחריות מוטלת רק על החברה.', false, 'טענה זו שגויה. חובת תום הלב חלה על כל מי שנוטל חלק במשא ומתן, לרבות אורגן של חברה, וניתן להטיל עליו אחריות אישית בנוסף לאחריות החברה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, אם יוכיח הקונה שיוסי פעל בחוסר תום לב סובייקטיבי.', true, 'תשובה זו נכונה. הפסיקה קבעה כי לצורך הטלת אחריות אישית על אורגן של חברה בגין הפרת חובת תום הלב במשא ומתן, נדרש להוכיח סטנדרט מחמיר יותר של חוסר תום לב סובייקטיבי, כלומר אשם אישי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, שכן יוסי הפר את חובת תום הלב האובייקטיבית המוטלת על כל צד למשא ומתן.', false, 'טענה זו שגויה. חובת תום הלב האובייקטיבית חלה על החברה, אך לצורך הטלת אחריות אישית על האורגן נדרש סטנדרט סובייקטיבי מחמיר יותר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן הוכח שיוסי ביצע תרמית.', false, 'טענה זו שגויה. חוסר תום לב סובייקטיבי אינו מוגבל רק למקרי תרמית, אלא כולל גם מקרים של אשם אישי במעשים או מחדלים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'היקף חובת הגילוי: מידע שניתן לגלות עצמאית',
    2, 'ראובן רכש דירה משמעון. שמעון לא גילה לראובן כי הדירה ממוקמת בסמוך למפעל מזהם, מידע שראובן יכול היה לגלות בקלות באמצעות בדיקה פשוטה ברשויות התכנון. האם אי-גילוי זה מהווה הפרה של חובת תום הלב במשא ומתן?', 'שאלה זו עוסקת בהיקף חובת הגילוי המוטלת על צדדים למשא ומתן מכוח סעיף 12 לחוק החוזים, ובפרט בשאלה האם חובה זו חלה גם על מידע שהצד השני יכול היה לגלות בעצמו. הפסיקה המודרנית נוטה לפרש חובה זו באופן רחב, במיוחד כאשר קיים פער מידע בין הצדדים.', 'חובת תום הלב במשא ומתן, הקבועה בסעיף 12 לחוק החוזים (חלק כללי), תשל"ג-1973, כוללת חובה לגלות לצד השני עובדות מהותיות. חוק החuזים (חלק כללי), תשל"ג-1973, סעיף 12(א) ת"א (שלום חי'') 8567-03-21 פוצקר בע"מ נ'' עזבון המנוח נתנאל סילס (01.12.2024) הפסיקה התפתחה וקבעה כי חובת הגילוי חלה גם על עובדות שהצד השני יכול היה לגלותן בכוחות עצמו, כאשר גילוי זה מתחייב ממהות העסקה ומנסיבות המקרה. ע"א 8227/20 ערן קסירר נ'' חיים אמסלם (12.07.2023) ת"א (מחוזי ת"א) 15794-12-13 יסעור פרו בע"מ נ'' iOption Group Ltd (28.05.2019) במיוחד תגבר הנטייה להטיל חובת גילוי כאשר לצד אחד גישה עדיפה למידע, וככל שהמידע מתייחס לעניין הגורע באופן ניכר מן הציפיות הסבירות של הצד שכנגד מן העסקה. ע"א 8227/20 ערן קסירר נ'' חיים אמסלם (12.07.2023) מיקום דירה בסמוך למפעל מזהם הוא מידע מהותי שעשוי להשפיע על החלטת הקונה, ולכן אי-גילויו מהווה הפרה של חובת תום הלב, גם אם ראובן יכול היה לגלותו בעצמו. גבריאלה שלו ואפי צמח דיני חוזים (2019) | (ד) אי-גילוי',
    'הטעות הנפוצה היא להניח שחובת הגילוי אינה חלה על מידע שהצד השני יכול היה לגלות בעצמו, מבלי להכיר בגישה המרחיבה של הפסיקה המודרנית.', '["סעיף 12 לחוק החוזים", "חובת גילוי", "מידע מהותי", "פער מידע", "הסתמכות", "עצימת עיניים", "ד\"נ פנידר"]'::jsonb, '**וריאציה 1 — מידע לא מהותי:** מה הדין אם המידע על המפעל המזהם לא היה מהותי לעסקה? ← אם המידע אינו מהותי, לא קמה חובת גילוי, גם אם הצד השני לא ידע עליו. ת"א (שלום חי'') 8567-03-21 פוצקר בע"מ נ'' עזבון המנוח נתנאל סילס (01.12.2024)
**וריאציה 2 — קונה מקצועי:** מה הדין אם ראובן היה מתווך מקרקעין מנוסה? ← במקרה של קונה מקצועי, פער המידע קטן יותר, ולכן חובת הגילוי של המוכר עשויה להיות מצומצמת יותר. ת"א (מחוזי ב"ש) 7137-09-18 נתנאל אטיאס נ'' אלון גורן (16.11.2025)
**וריאציה 3 — הטעיה אקטיבית:** מה הדין אם שמעון הצהיר במפורש שאין מפעלים מזהמים בסביבה? ← הצהרה כוזבת מהווה הטעיה אקטיבית, שהיא הפרה חמורה יותר של חובת תום הלב, ואינה תלויה בשאלת יכולת הגילוי העצמי של הצד השני. גבריאלה שלו ואפי צמח דיני חוזים (2019) | (ד) אי-גילוי', 'חובת הגילוי לפי סעיף 12 לחוק החוזים חלה גם על מידע מהותי שהצד השני יכול היה לגלות בעצמו, במיוחד כאשר קיים פער מידע בין הצדדים.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "ת\"א (שלום חי'') 8567-03-21 פוצקר בע\"מ נ'' עזבון המנוח נתנאל סילס (01.12.2024)", "ע\"א 8227/20 ערן קסירר נ'' חיים אמסלם (12.07.2023)", "ת\"א (מחוזי ת\"א) 15794-12-13 יסעור פרו בע\"מ נ'' iOption Group Ltd (28.05.2019)", "ת\"א (מחוזי ב\"ש) 7137-09-18 נתנאל אטיאס נ'' אלון גורן (16.11.2025)", "גבריאלה שלו ואפי צמח דיני חוזים (2019) | (ד) אי-גילוי"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'לא, שכן חובת הגילוי אינה חלה על מידע שהצד השני יכול היה לגלות בעצמו.', false, 'טענה זו משקפת גישה מצמצמת שאינה מקובלת בפסיקה המודרנית, אשר מרחיבה את חובת הגילוי גם למידע שהצד השני יכול היה לגלות בעצמו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כן, חובת הגילוי חלה גם על מידע שהצד השני יכול היה לגלות בעצמו, אם הוא מהותי לעסקה.', true, 'תשובה זו נכונה. הפסיקה המודרנית קבעה כי חובת הגילוי מכוח סעיף 12 לחוק החוזים חלה גם על עובדות שהצד השני יכול היה לגלותן בכוחות עצמו, כאשר גילוי זה מתחייב ממהות העסקה ומנסיבות המקרה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'לא, אלא אם כן ראובן שאל במפורש על מפעלים מזהמים בסביבה.', false, 'טענה זו שגויה. חובת הגילוי לפי סעיף 12 לחוק החוזים היא חובה אקטיבית, המחייבת מסירת פרטים יזומה של מידע חיוני, ולא רק בתגובה לשאלות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'כן, אך רק אם שמעון ידע שראובן אינו מודע למידע זה.', false, 'טענה זו שגויה. ידיעת המוכר על אי-ידיעת הקונה היא גורם מחזק לחובת הגילוי, אך אינה תנאי בלעדי. חובת הגילוי יכולה לקום גם ללא ידיעה פוזיטיבית כזו, אם המידע מהותי וקיים פער מידע.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חובת גילוי מוגברת במכר דירה ''על הנייר''',
    3, 'חברה קבלנית מכרה לזוג צעיר דירה ''על הנייר''. החברה לא גילתה לזוג כי הדירה תהיה חסומה באופן משמעותי על ידי מבנה עתידי לרווחת הדיירים, מידע שהיה ידוע לחברה. הזוג גילה זאת רק לאחר חתימת החוזה. האם החברה הפרה את חובת הגילוי כלפי הזוג?', 'שאלה זו עוסקת בחובת הגילוי המוגברת החלה על קבלנים ו יזמי מקרקעין המוכרים דירות ''על הנייר''. היא מדגישה את פערי המידע והכוחות המשמעותיים בין הצדדים בעסקאות מסוג זה, ואת הנגזרת מכך לעניין היקף חובת הגילוי מכוח סעיף 12 לחוק החוזים.', 'במכר דירה ''על הנייר'', קיימים פערי מידע ופערי כוחות משמעותיים בין אדם מן השורה הרוכש דירה לבין קבלן או יזם מקרקעין. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023) מפערים אלו, ומחובת תום הלב במשא ומתן המעוגנת בסעיף 12(א) לחוק החוזים (חלק כללי), נגזרת חובת גילוי מוגברת החלה על הקבלן. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023) תכלית חובה זו היא לגרום לכך שהקבלן יידע את רוכש הדירה על כל הפרטים החשובים בנוגע לדירה, באופן מדויק וממצה ככל שניתן, כדי שהסכמת הרוכש תהיה מודעת. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023) מידע בדבר חסימת נוף משמעותית על ידי מבנה עתידי הוא מידע מהותי, ומחובת החברה היה לגלותו לזוג מיוזמתה. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023) אי-גילוי כזה מהווה הפרה של חובת תום הלב במשא ומתן. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)',
    'הטעות הנפוצה היא להחיל את הכלל הרגיל של ''ייזהר הקונה'' גם על עסקאות מכר דירה ''על הנייר'', מבלי להכיר בחובת הגילוי המוגברת החלה על קבלנים בעסקאות אלו.', '["סעיף 12 לחוק החוזים", "חובת גילוי מוגברת", "דירה על הנייר", "פערי מידע", "פערי כוחות", "הטעיה", "תום לב במשא ומתן"]'::jsonb, '**וריאציה 1 — מידע על תכנון עתידי:** האם חובת הגילוי המוגברת חלה גם על מידע תכנוני עתידי? ← כן, חובת הגילוי המוגברת חלה גם על מידע תכנוני עתידי מהותי, שכן רוכש דירה ''על הנייר'' אינו יכול לבחון פיזית את הממכר. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)
**וריאציה 2 — סעדים:** אילו סעדים עומדים לזוג במקרה של הפרת חובת גילוי מוגברת? ← הזוג זכאי לביטול החוזה (עקב הטעיה) ולפיצויים, שיכולים להיות פיצויי הסתמכות (להעמיד את הנפגע במקום בו היה אלמלא נכרת החוזה) ואף פיצויי קיום במקרים מסוימים. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023)
**וריאציה 3 — חובת גילוי ספציפית בחוק:** האם קיימות חובות גילוי ספציפיות לקבלנים? ← כן, חוק המכר (דירות) וצו מכר דירות קובעים חובות מסירת מידע ספציפיות לקבלנים, והפרתן יכולה להוות הטעיה במחדל. איל זמיר חוק המכר (דירות) (2002) | 2. דיני הפגמים בכריתת חוזה, תום-לב במשא ומתן', 'קבלן המוכר דירה ''על הנייר'' חב בחובת גילוי מוגברת מכוח סעיף 12 לחוק החוזים, המחייבת אותו לגלות מידע מהותי באופן יזום, בשל פערי המידע והכוחות מול הרוכש.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "ע\"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע\"מ (01.01.2023)", "חוק המכר (דירות) (הבטחת השקעות של רוכשי דירות), תשל\"ה-1974, סעיפים 2, 3, 6(א)", "איל זמיר חוק המכר (דירות) (2002) | 2. דיני הפגמים בכריתת חוזה, תום-לב במשא ומתן"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, שכן הקונה בדירה ''על הנייר'' צריך לבדוק את התוכניות בעצמו, וחל עליו הכלל ''ייזהר הקונה''.', false, 'טענה זו שגויה. במכר דירה ''על הנייר'' חלה על הקבלן חובת גילוי מוגברת, והכלל ''ייזהר הקונה'' נסוג מפניה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, שכן על קבלן המוכר דירה ''על הנייר'' חלה חובת גילוי מוגברת, המחייבת אותו לגלות מידע מהותי כזה מיוזמתו.', true, 'תשובה זו נכונה. הפסיקה קבעה כי במכר דירה ''על הנייר'' קיימים פערי מידע וכוחות משמעותיים בין הקבלן לרוכש, ולכן חלה על הקבלן חובת גילוי מוגברת לגלות מידע מהותי באופן יזום.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, אלא אם כן הזוג שאל במפורש על חסימות נוף עתידיות.', false, 'טענה זו שגויה. חובת הגילוי המוגברת על קבלן היא יזומה ואינה תלויה בשאלות ספציפיות של הרוכש.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, אך רק אם החסימה נגרמה כתוצאה משינוי תכנוני שנעשה לאחר חתימת החוזה.', false, 'טענה זו שגויה. חובת הגילוי חלה על מידע שהיה ידוע לקבלן בעת המשא ומתן, גם אם הוא נוגע למצב עתידי שטרם התממש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעדים בגין הפרת חובת תום הלב במשא ומתן',
    4, 'ראובן ניהל משא ומתן עם שמעון לרכישת עסק. שמעון הפר את חובת תום הלב במשא ומתן בכך שניהל משא ומתן מקביל בחוסר תום לב, וגרם לראובן להוציא הוצאות רבות ולהפסיד הזדמנויות עסקיות אחרות. בסופו של דבר, החוזה לא נכרת. אילו פיצויים ראובן זכאי לתבוע משמעון?', 'שאלה זו עוסקת בסעדים הניתנים בגין הפרת חובת תום הלב במשא ומתן, כאשר החוזה לא נכרת. היא מתמקדת בהבחנה בין פיצויי הסתמכות (אינטרס שלילי) לבין פיצויי קיום (אינטרס חיובי), ומדגישה כי הכלל הוא פסיקת פיצויי הסתמכות, למעט חריגים מסוימים.', 'סעיף 12(ב) לחוק החוזים (חלק כללי), תשל"ג-1973, קובע כי צד שלא נהג בתום לב במשא ומתן חייב לצד השני פיצויים בעד הנזק שנגרם לו עקב המשא ומתן או עקב כריתת החוזה. חוק החוזים (חלק כללי), תשל"ג-1973, סעיף 12(ב) הפסיקה פירשה הוראה זו כמעניקה, ככלל, ''פיצויים שליליים'' או ''פיצויי הסתמכות'' בלבד. תא"ק (שלום חי'') 4604-04-15 דוד ביטון נ'' גדעון בן שלמה (25.03.2021) מטרת פיצויים אלה היא להעמיד את הצד הנפגע באותו מצב שבו היה נתון אלמלא נכנס למשא ומתן כלל. תא"ק (שלום חי'') 4604-04-15 דוד ביטון נ'' גדעון בן שלמה (25.03.2021) פיצויי הסתמכות כוללים הוצאות שהוצאו במהלך המשא ומתן, אובדן הזדמנויות עסקיות אחרות וכדומה. ע"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע"מ (01.01.2023) במקרים חריגים של חוסר תום לב קיצוני, כאשר המשא ומתן הגיע לשלב מתקדם מאוד ורק חוסר תום הלב מנע את כריתת החוזה, עשויה הפסיקה לפסוק פיצויי קיום (אינטרס חיובי), שיעמידו את הנפגע במצב כאילו החוזה נכרת וקוים (הלכת קל בניין). ע"א 434/07 אריק פרינץ נ'' אמירים מושב עובדים של צמחונים וטבעונים להתיישבות חקלאית שיתופית בע"מ (14.06.2009) במקרה הנדון, ראובן זכאי לתבוע פיצויי הסתמכות בגין ההוצאות שהוציא ואובדן ההזדמנויות. ת"א (שלום ת"א) 8029-06-19 דור-אלון אנרגיה בישראל (1988) בע"מ נ'' אבגור אביזרי מיזוג אויר בע"מ (17.09.2024)',
    'הטעות הנפוצה היא לבלבל בין פיצויי הסתמכות לפיצויי קיום, ולהניח שפיצויי קיום הם הסעד הסטנדרטי להפרת חובת תום הלב במשא ומתן, גם כאשר החוזה לא נכרת.', '["סעיף 12 לחוק החוזים", "פיצויי הסתמכות", "פיצויי קיום", "אינטרס שלילי", "אינטרס חיובי", "הלכת קל בניין", "אובדן הזדמנויות"]'::jsonb, '**וריאציה 1 — חוזה שנכרת:** מה הדין אם החוזה נכרת, אך הופר עקב חוסר תום לב במשא ומתן? ← במקרה כזה, הנפגע זכאי לפיצויי קיום (אינטרס חיובי) בגין הפרת החוזה, בנוסף לפיצויי הסתמכות בגין חוסר תום הלב. חוק החוזים (חלק כללי), תשל"ג-1973, סעיף 12(ב)
**וריאציה 2 — ביטול חוזה:** האם הפרת חובת תום הלב במשא ומתן יכולה להוביל לביטול החוזה? ← כן, אם חוסר תום הלב עולה כדי הטעיה (סעיף 15 לחוק החוזים), הנפגע זכאי לבטל את החוזה. תא"ק (שלום חי'') 4604-04-15 דוד ביטון נ'' גדעון בן שלמה (25.03.2021)
**וריאציה 3 — פיצויים בגין אובדן רווח:** האם ראובן יכול לתבוע פיצויים בגין הרווח שהיה מפיק מהעסק לו נכרת החוזה? ← ככלל, לא. פיצויים בגין אובדן רווחים (פיצויי קיום) נפסקים רק במקרים חריגים של חוסר תום לב קיצוני, כאשר המשא ומתן הגיע לשלב מתקדם מאוד ורק חוסר תום הלב מנע את כריתת החוזה. ע"א 434/07 אריק פרינץ נ'' אמירים מושב עובדים של צמחונים וטבעונים להתיישבות חקלאית שיתופית בע"מ (14.06.2009)', 'הפרת חובת תום הלב במשא ומתן שלא הוביל לחוזה ← מזכה בפיצויי הסתמכות (אינטרס שלילי), שמטרתם להשיב את הנפגע למצב כאילו לא נכנס למשא ומתן כלל, למעט חריגים של חוסר תום לב קיצוני המצדיקים פיצויי קיום.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "תא\"ק (שלום חי'') 4604-04-15 דוד ביטון נ'' גדעון בן שלמה (25.03.2021)", "ע\"א 2274/21 נטע מור נ'' אלעד ישראל מגורים בע\"מ (01.01.2023)", "ע\"א 434/07 אריק פרינץ נ'' אמירים מושב עובדים של צמחונים וטבעונים להתיישבות חקלאית שיתופית בע\"מ (14.06.2009)", "ת\"א (שלום ת\"א) 8029-06-19 דור-אלון אנרגיה בישראל (1988) בע\"מ נ'' אבגור אביזרי מיזוג אויר בע\"מ (17.09.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'פיצויי קיום (אינטרס חיובי), שיעמידו אותו במצב כאילו החוזה נכרת וקוים.', false, 'טענה זו שגויה. ככלל, הפרת חובת תום הלב במשא ומתן כאשר החוזה לא נכרת, מזכה בפיצויי הסתמכות (אינטרס שלילי), ולא בפיצויי קיום.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'פיצויי הסתמכות (אינטרס שלילי), שיעמידו אותו במצב כאילו לא נכנס למשא ומתן כלל.', true, 'תשובה זו נכונה. סעיף 12(ב) לחוק החוזים מזכה את הנפגע בפיצויים בעד הנזק שנגרם לו עקב המשא ומתן, כלומר פיצויי הסתמכות, שמטרתם להשיב את המצב לקדמותו כאילו המשא ומתן לא התקיים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'פיצויי קיום או פיצויי הסתמכות, לפי בחירתו של ראובן.', false, 'טענה זו שגויה. הבחירה בין פיצויי קיום להסתמכות קיימת במקרים של הפרת חוזה, אך בהפרת חובת תום לב במשא ומתן שלא הוביל לחוזה, הכלל הוא פיצויי הסתמכות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'פיצויים עונשיים, בשל חוסר תום הלב החמור של שמעון.', false, 'טענה זו שגויה. הדין הישראלי אינו מכיר בפיצויים עונשיים בגין הפרת חובת תום הלב במשא ומתן, אלא בפיצויים שמטרתם השבת המצב לקדמותו או פיצוי על נזק שנגרם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 20, '2023-S-S-Q20';
END
$$;

-- ============================================================
-- Q21 — 2023-S-S-Q21 — chapter=tax subtopic=real_estate_tax
-- classifier_note: Capital-gains tax (מס שבח) on multiple apartments + linear computation
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'a749de32-ab17-4e43-a331-e030e35d3744'::uuid;
  v_group_id uuid := '251f7fc9-cf7c-4743-81da-b96b5b5a17fc'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '7c0a2b84-645f-4c42-a5d3-73e149c2db27'::uuid;
  v_ang_1 uuid := 'ac51becd-3e44-46aa-bd5a-86a17c17d8c6'::uuid;
  v_ang_2 uuid := 'c73c12eb-8fda-4421-8451-cbb10cd6dbd7'::uuid;
  v_ang_3 uuid := '623f00b5-fa97-486a-815e-cdc6c79a0d8b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q21';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 21, '2023-S-S-Q21';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'tax';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'tax';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'real_estate_tax' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'real_estate_tax', 'tax';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q21', v_chapter_id, v_subtopic_id, 'בבעלות יסמין 2 דירות מגורים, אחת בגבעתיים והשנייה ברמת גן. ביום 1.1.2022 מכרה יסמין את דירתה בגבעתיים בפטור ממס שבח מקרקעין. סכום המכירה היה 800,000 ש"ח. ביום 1.11.2022 מכרה יסמין את דירתה השנייה ברמת גן וחתמה על חוזה לרכישת דירת מגורים גדולה יותר בקריית אונו. שווי הדירה ברמת גן הוא 1,000,000 ש"ח, ומחיר הדירה בקריית אונו הוא 1,500,000 ש"ח. האם זכאית יסמין לפטור ממס שבח מקרקעין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 21}'::jsonb, 'השאלה עוסקת בפטור ממס שבח מקרקעין במכירת דירת מגורים חלופית, לפי סעיף 49ה לחוק מיסוי מקרקעין. פטור זה מאפשר למוכר דירת מגורים לרכוש דירה אחרת במקומה, תוך קבלת פטור ממס שבח, גם אם בבעלותו יותר מדירה אחת, וזאת בניגוד לפטורים אחרים המוגבלים לדירה יחידה או לתקופות המתנה ארוכות יותר.', 'סעיף 49ה לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963, קובע פטור ממס שבח במכירת דירת מגורים, בתנאי שהמוכר רכש דירת מגורים חלופית בתוך 12 חודשים (לפני או אחרי המכירה), ושווי הדירה החלופית אינו נמוך מ-75% משווי הדירה הנמכרת (או גבוה יותר). במקרה של יסמין, היא מכרה את דירתה ברמת גן ורכשה דירה יקרה יותר בקריית אונו בתוך פרק הזמן הנדרש. העובדה שמכרה דירה קודמת בפטור אינה שוללת את הפטור לפי סעיף 49ה, שכן פטור זה אינו כפוף למגבלת 4 השנים החלה על פטור לפי סעיף 49ב(1).', 'בלבול בין הפטור לפי סעיף 49ה (דירת מגורים חלופית) לבין הפטור לפי סעיף 49ב(1) (דירת מגורים מזכה), ובפרט יישום שגוי של מגבלת 4 השנים או דרישת ''דירה יחידה'' על סעיף 49ה.',
    '["מס שבח", "דירת מגורים חלופית", "פטור ממס שבח", "חוק מיסוי מקרקעין", "תנאים מצטברים"]'::jsonb, '**וריאציה 1 — פטור 49ה:** האם פטור 49ה מוגבל למכירה אחת ל-4 שנים? ← לא, מגבלת 4 השנים חלה על 49ב(1) בלבד.
**וריאציה 2 — בעלות על מספר דירות:** האם בעלות על 2 דירות שוללת פטור 49ה? ← לא, הפטור נועד לאפשר החלפת דירה גם למי שבבעלותו יותר מדירה אחת.
**וריאציה 3 — תנאי השווי:** האם הדירה החלופית חייבת להיות יקרה יותר? ← לא, מספיק ששווי הדירה החלופית לא יפחת מ-75% משווי הדירה הנמכרת (סעיף 49ה(1)(ב)).', 'פטור 49ה ← מאפשר החלפת דירה (מכירה ורכישה במועד ובשווי מתאים) ← גם לבעל יותר מדירה אחת ← ללא מגבלת 4 שנים.', '["חוק מיסוי מקרקעין (שבח ורכישה), התשכ\"ג-1963, סעיף 49ה"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''tax'' subtopic=''real_estate_tax'' | classifier_note: Capital-gains tax (מס שבח) on multiple apartments + linear computation | source_review_note: שאלת המקור עוסקת בדיני מיסוי מקרקעין מהותיים ואינה משתלבת באופן ישיר באף אחד מהפרקים או תתי-הנושאים הקיימים בדין הדיוני. סווגה תחת ''סדר דין אזרחי'' ו''הליכים'' כהצבת מקום זמנית.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'כן.', true, 'יסמין זכאית לפטור ממס שבח לפי סעיף 49ה לחוק מיסוי מקרקעין, שכן היא עומדת בתנאים הנדרשים לפטור זה, לרבות מכירת דירת מגורים ורכישת דירת מגורים חלופית בתוך פרק הזמן הקבוע בחוק ובשווי מתאים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לא, שכן היו בבעלותה 2 דירות.', false, 'החזקה בשתי דירות אינה שוללת אוטומטית את הזכאות לפטור לפי סעיף 49ה, אשר נועד לאפשר החלפת דירת מגורים גם למי שבבעלותו יותר מדירה אחת, כל עוד התנאים הספציפיים לפטור זה מתקיימים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לא, היות שיסמין כבר מכרה דירת מגורים בפטור ממס שבח ב-4 השנים האחרונות.', false, 'ההגבלה של מכירה בפטור אחת ל-4 שנים רלוונטית לפטור לפי סעיף 49ב(1) לחוק, אך אינה חלה על פטור לפי סעיף 49ה, המאפשר מכירה ורכישת דירה חלופית ללא קשר לפטורים קודמים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לא, היות שיסמין כבר מיצתה את תקרת הפטור ממס שבח.', false, 'סעיף 49ה אינו קובע ''תקרת פטור'' במובן של הגבלה על מספר הפעמים שניתן ליהנות ממנו, כל עוד התנאים הספציפיים לפטור זה מתקיימים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תנאי שווי דירה חלופית',
    1, 'יסמין מכרה את דירתה ברמת גן בשווי 1,000,000 ש"ח. בתוך 12 חודשים מיום המכירה, רכשה דירת מגורים חדשה בקריית אונו בשווי 700,000 ש"ח. האם יסמין זכאית לפטור ממס שבח לפי סעיף 49ה לחוק מיסוי מקרקעין?', 'שאלה זו בוחנת את הבנת התנאים המצטברים לפטור ממס שבח במכירת דירת מגורים חלופית, ובפרט את דרישת השווי של הדירה הנרכשת ביחס לדירה הנמכרת.', 'סעיף 49ה(1)(ב) לחוק מיסוי מקרקעין קובע כי אחד התנאים לפטור הוא ששווי הדירה הנרכשת לא יפחת מ-75% משווי הדירה הנמכרת, או שיהיה גבוה יותר. במקרה זה, שווי הדירה הנמכרת הוא 1,000,000 ש"ח, ו-75% ממנו הם 750,000 ש"ח. שווי הדירה הנרכשת הוא 700,000 ש"ח, ולכן הוא נמוך מהסף הנדרש, ויסמין אינה זכאית לפטור זה.',
    'התעלמות מתנאי השווי הספציפיים הקבועים בסעיף 49ה(1)(ב) והתמקדות רק בלוחות הזמנים לרכישה.', '["מס שבח", "דירת מגורים חלופית", "תנאי פטור", "שווי דירה", "חוק מיסוי מקרקעין"]'::jsonb, '**וריאציה 1 — שווי נמוך מ-75%:** מה קורה אם הדירה החלופית זולה משמעותית? ← אין פטור לפי 49ה, כי לא עומד בתנאי 49ה(1)(ב).
**וריאציה 2 — שווי זהה:** מה קורה אם הדירה החלופית באותו שווי? ← יש פטור, כי התנאי הוא ''לא יפחת מ-75% או יהיה גבוה יותר''.
**וריאציה 3 — שווי גבוה:** מה קורה אם הדירה החלופית יקרה יותר? ← יש פטור, כי זה עומד בתנאי ''או יהיה גבוה יותר''.', 'פטור 49ה ← דורש שווי דירה חלופית שלא יפחת מ-75% משווי הדירה הנמכרת, או שיהיה גבוה יותר.',
    '["חוק מיסוי מקרקעין (שבח ורכישה), התשכ\"ג-1963, סעיף 49ה(1)(ב)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, כי רכשה דירה חלופית בתוך המועד הקבוע בחוק.', false, 'רכישת דירה חלופית במועד היא אכן תנאי לפטור, אך אינה התנאי היחיד. יש לבחון גם את יחס השווי בין הדירות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, כי שווי הדירה החלופית נמוך מ-75% משווי הדירה הנמכרת.', true, 'אחד התנאים לפטור לפי סעיף 49ה(1)(ב) הוא ששווי הדירה הנרכשת לא יפחת מ-75% משווי הדירה הנמכרת, או שיהיה גבוה יותר. במקרה זה, 700,000 ש"ח נמוכים מ-75% מ-1,000,000 ש"ח (שהם 750,000 ש"ח).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, בתנאי שתמכור את הדירה בגבעתיים בתוך 12 חודשים.', false, 'תנאי זה אינו רלוונטי לפטור לפי סעיף 49ה, העוסק במכירת דירה אחת ורכישת דירה חלופית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, כי כבר ניצלה פטור ממס שבח בעבר.', false, 'כפי שהוסבר בשאלת המקור, ניצול פטור קודם אינו שולל את הזכאות לפטור לפי סעיף 49ה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני הזכאות לפטור 49ה',
    2, 'מהם התנאים המצטברים העיקריים לזכאות לפטור ממס שבח במכירת דירת מגורים חלופית לפי סעיף 49ה לחוק מיסוי מקרקעין?', 'שאלה זו בוחנת את הידע הכללי והמקיף של התלמיד אודות התנאים המצטברים הנדרשים לקבלת פטור ממס שבח במכירת דירת מגורים חלופית לפי סעיף 49ה.', 'סעיף 49ה לחוק מיסוי מקרקעין קובע מספר תנאים מצטברים לפטור ממס שבח במכירת דירת מגורים חלופית: א. מכירת דירת מגורים. ב. רכישת דירת מגורים חלופית בתוך 12 חודשים (לפני או אחרי המכירה). ג. שווי הדירה החלופית אינו נמוך מ-75% משווי הדירה הנמכרת (או גבוה יותר). ד. מגורים בדירה החלופית למשך תקופה מסוימת (בהתאם לנסיבות).',
    'בלבול בין התנאים של סעיף 49ה לבין תנאים של פטורים אחרים, או אי-זכירת כל התנאים המצטברים.', '["מס שבח", "דירת מגורים חלופית", "תנאים מצטברים", "לוחות זמנים", "חוק מיסוי מקרקעין"]'::jsonb, '**וריאציה 1 — תנאי בסיסי:** מהם התנאים העיקריים לפטור 49ה? ← מכירה, רכישה במועד, שווי מתאים, מגורים (סעיף 49ה).
**וריאציה 2 — חשיבות השווי:** האם שווי הדירה החלופית תמיד חייב להיות גבוה יותר? ← לא, מספיק שלא יפחת מ-75% (סעיף 49ה(1)(ב)).
**וריאציה 3 — לוחות זמנים:** מהם לוחות הזמנים לרכישת הדירה החלופית? ← 12 חודשים לפני או אחרי המכירה (סעיף 49ה(1)(א)).', 'פטור 49ה ← מכירה + רכישה חלופית (במועד ובשווי מתאים) + מגורים.',
    '["חוק מיסוי מקרקעין (שבח ורכישה), התשכ\"ג-1963, סעיף 49ה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מכירת דירת מגורים ורכישת דירת מגורים חלופית בתוך 12 חודשים, ומגורים בדירה החלופית.', false, 'תשובה זו כוללת חלק מהתנאים, אך אינה מקיפה את כולם, כגון תנאי השווי של הדירה החלופית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'מכירת דירת מגורים, רכישת דירת מגורים חלופית בתוך 12 חודשים, שווי הדירה החלופית אינו נמוך מ-75% משווי הדירה הנמכרת, ומגורים בדירה החלופית.', true, 'תשובה זו מפרטת את כל התנאים המצטברים העיקריים הנדרשים בסעיף 49ה לחוק מיסוי מקרקעין לצורך קבלת הפטור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מכירת דירת מגורים, רכישת דירת מגורים חלופית בתוך 24 חודשים, ואי ניצול פטור אחר ב-4 השנים האחרונות.', false, 'תשובה זו כוללת פרטים שגויים (24 חודשים במקום 12) ומתייחסת לתנאי שאינו רלוונטי לפטור 49ה (אי ניצול פטור אחר).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מכירת דירת מגורים יחידה, רכישת דירת מגורים חלופית בתוך 18 חודשים, ומגורים בדירה החלופית.', false, 'תשובה זו כוללת פרטים שגויים (דירת מגורים יחידה אינה תנאי לפטור 49ה, ו-18 חודשים במקום 12) ואינה מקיפה את כל התנאים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חריגים לפטור דירת מגורים חלופית',
    3, 'יסמין מכרה את דירתה ברמת גן בשווי 1,000,000 ש"ח. בתוך 12 חודשים מיום המכירה, רכשה חנות מסחרית בקריית אונו בשווי 1,500,000 ש"ח. האם יסמין זכאית לפטור ממס שבח לפי סעיף 49ה לחוק מיסוי מקרקעין?', 'שאלה זו בוחנת את ההבנה כי הפטור לפי סעיף 49ה מוגבל לרכישת ''דירת מגורים חלופית'' בלבד, ואינו חל על רכישת נכסים אחרים, גם אם הם יקרים יותר.', 'סעיף 49ה לחוק מיסוי מקרקעין מתייחס במפורש למכירת ''דירת מגורים'' ורכישת ''דירת מגורים חלופית''. הגדרת ''דירת מגורים'' בחוק היא ספציפית ואינה כוללת נכסים מסחריים כגון חנות. לכן, גם אם יסמין עמדה בתנאי המועד והשווי, היא אינה זכאית לפטור זה מכיוון שהנכס הנרכש אינו דירת מגורים.',
    'התמקדות בתנאי השווי והמועד בלבד, והתעלמות מהדרישה המהותית שהנכס הנרכש יהיה ''דירת מגורים''.', '["מס שבח", "דירת מגורים חלופית", "הגדרת דירת מגורים", "נכס מסחרי", "חוק מיסוי מקרקעין"]'::jsonb, '**וריאציה 1 — רכישת משרד:** האם פטור 49ה חל על רכישת משרד? ← לא, כי אינו ''דירת מגורים'' (סעיף 49ה).

**וריאציה 2 — רכישת קרקע:** האם פטור 49ה חל על רכישת מגרש לבנייה? ← לא, כי אינו ''דירת מגורים'' (סעיף 49ה).
**וריאציה 3 — רכישת דירה בחו"ל:** האם פטור 49ה חל על רכישת דירה בחו"ל? ← לא, הפטור מתייחס לדירות בישראל (סעיף 49ה והגדרת ''דירת מגורים'').', 'פטור 49ה ← חל רק על רכישת ''דירת מגורים'' חלופית, לא על נכסים אחרים.',
    '["חוק מיסוי מקרקעין (שבח ורכישה), התשכ\"ג-1963, סעיף 49ה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, כי רכשה נכס בשווי גבוה יותר בתוך המועד הקבוע בחוק.', false, 'אף שרכישת נכס בשווי גבוה יותר ובמועד היא תנאי, הנכס הנרכש חייב להיות ''דירת מגורים'' ולא נכס מסחרי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, כי הנכס החלופי אינו ''דירת מגורים''.', true, 'סעיף 49ה דורש במפורש רכישת ''דירת מגורים חלופית''. רכישת חנות מסחרית אינה עונה על הגדרה זו, ולכן הפטור אינו חל.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, בתנאי שתשכיר את החנות למגורים.', false, 'השכרת נכס מסחרי למגורים אינה הופכת אותו ל''דירת מגורים'' לצורך הפטור, אשר דורש שהנכס יהיה מיועד למגורים על פי טיבו והיתרי הבנייה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, כי כבר ניצלה פטור ממס שבח בעבר.', false, 'כפי שהוסבר, ניצול פטור קודם אינו שולל את הזכאות לפטור לפי סעיף 49ה, אך הסיבה לאי-זכאות כאן היא אחרת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'חלופות לפטור ממס שבח',
    4, 'יסמין מכרה את דירתה ברמת גן, אך לא עמדה בתנאים לקבלת פטור לפי סעיף 49ה לחוק מיסוי מקרקעין. מהי האפשרות העיקרית הנוספת שעשויה להיות רלוונטית עבורה לקבלת פטור ממס שבח?', 'שאלה זו בוחנת את היכרות התלמיד עם חלופות פטור ממס שבח, ובפרט את ההבחנה בין פטור ''דירת מגורים חלופית'' (49ה) לבין פטור ''דירת מגורים מזכה'' (49ב(1)).', 'כאשר מוכר אינו עומד בתנאי הפטור לפי סעיף 49ה (דירת מגורים חלופית), עליו לבחון אפשרויות פטור אחרות. האפשרות העיקרית והנפוצה ביותר היא פטור לפי סעיף 49ב(1) לחוק מיסוי מקרקעין, המאפשר פטור ממס שבח במכירת דירת מגורים מזכה אחת ל-4 שנים, בתנאי שלא נמכרה דירה אחרת בפטור באותה תקופה. ישנם פטורים נוספים, אך הם ספציפיים יותר (כגון מכירה לקרוב או ליורש).',
    'בלבול בין תנאי הפטורים השונים או אי-היכרות עם מגוון הפטורים הקיימים בחוק.', '["מס שבח", "פטור ממס שבח", "דירת מגורים מזכה", "דירת מגורים חלופית", "חוק מיסוי מקרקעין"]'::jsonb, '**וריאציה 1 — פטור 49ב(1):** מהו התנאי העיקרי לפטור 49ב(1)? ← מכירת דירת מגורים מזכה אחת ל-4 שנים (סעיף 49ב(1)).
**וריאציה 2 — פטור 49ה מול 49ב(1):** מה ההבדל המהותי בין 49ה ל-49ב(1)? ← 49ה מאפשר החלפת דירה גם לבעל יותר מדירה אחת, ללא הגבלת 4 שנים, בעוד 49ב(1) מוגבל לדירה יחידה (בדרך כלל) ולתקופת 4 שנים.
**וריאציה 3 — פטורים נוספים:** אילו פטורים נוספים קיימים? ← פטור ליורשים (סעיף 62), פטור למכירה לקרוב (סעיף 49ב(2)), ועוד.', 'אם אין פטור 49ה ← לבדוק פטור 49ב(1) (אחת ל-4 שנים) או פטורים ספציפיים אחרים.',
    '["חוק מיסוי מקרקעין (שבח ורכישה), התשכ\"ג-1963, סעיף 49ב(1)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'פטור ממס שבח לפי סעיף 49ב(1) לחוק, אם עברו 4 שנים ממכירה קודמת בפטור.', true, 'זוהי אפשרות פטור נפוצה נוספת, המאפשרת פטור ממס שבח במכירת דירת מגורים מזכה אחת ל-4 שנים, בתנאי שהמוכר לא מכר דירה אחרת בפטור באותה תקופה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'פטור ממס שבח לפי סעיף 49ב(2) לחוק, אם הדירה נמכרה לקרוב.', false, 'פטור זה רלוונטי רק למכירה לקרוב, ואינו פטור כללי למקרה של אי-עמידה בתנאי 49ה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'פטור ממס שבח לפי סעיף 62 לחוק, אם הדירה נמכרה ליורש.', false, 'סעיף 62 עוסק בפטור ליורשים, ואינו רלוונטי למכירה רגילה של דירה על ידי הבעלים בחייו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'הפחתה אוטומטית של 50% ממס השבח אם הדירה הוחזקה מעל 10 שנים.', false, 'אין הוראה בחוק המעניקה הפחתה אוטומטית של 50% ממס השבח לאחר 10 שנים, אלא חישוב ליניארי או פטורים ספציפיים.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 21, '2023-S-S-Q21';
END
$$;

-- ============================================================
-- Q22 — 2023-S-S-Q22 — chapter=contracts subtopic=general_part
-- classifier_note: Standard for good-faith review in pre-contract negotiations — objective vs subjective
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '23a75e51-93b3-47a8-aff7-e3f8702cb872'::uuid;
  v_group_id uuid := 'df06c5f5-3c86-400d-86db-ee3704de2096'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'c0b6a5e0-b971-4d75-9403-c1848abcb901'::uuid;
  v_ang_1 uuid := 'e7dce95a-8926-45cf-a230-ff8882751765'::uuid;
  v_ang_2 uuid := 'ea60375a-120b-4e14-b710-38a025fae45e'::uuid;
  v_ang_3 uuid := '0848996d-f9d4-4664-828e-48cf01ca495b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q22';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 22, '2023-S-S-Q22';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q22', v_chapter_id, v_subtopic_id, 'משה ניהל משא ומתן לקראת כריתתו של חוזה. מהי אמת המידה לבחינת תום הלב של משה?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 22}'::jsonb, 'השאלה עוסקת באמת המידה לבחינת חובת תום הלב במשא ומתן, הקבועה בסעיף 12 לחוק החוזים (חלק כללי). חובה זו מטילה על הצדדים לנהוג בדרך מקובלת ובתום לב, והיא נבחנת בעיקר במבחן אובייקטיבי, המשקף סטנדרט התנהגות ראוי בחברה, ללא תלות בהכרח בכוונה או מודעות סובייקטיבית של הצד המפר.', 'סעיף 12(א) לחוק החוזים (חלק כללי), התשל"ג-1973, קובע כי ''במשא ומתן לקראת כריתתו של חוזה חייב אדם לנהוג בדרך מקובלת ובתום לב''. הפסיקה קבעה כי המבחן לתום לב הוא מבחן אובייקטיבי בעיקרו, הבוחן את ההתנהגות לפי אמות מידה כלליות של הגינות ויושר, כפי שמצופה מהאדם הסביר בנסיבות נתונות. מבחן זה כולל גם מרכיבים סובייקטיביים, כגון טיב העסקה ואופי הצדדים, אך אינו דורש כוונה או מודעות סובייקטיבית לחוסר תום לב. כלומר, סטייה מסטנדרט ההתנהגות המצופה תיחשב לחוסר תום לב גם אם לא הייתה לצד כל כוונה לסטות או מודעות לכך.', 'הטעות הנפוצה היא לחשוב שמבחן תום הלב הוא סובייקטיבי טהור, הדורש כוונה רעה או מודעות לחוסר תום לב, במקום המבחן האובייקטיבי-מעורב שנקבע בפסיקה.',
    '["תום לב במשא ומתן", "סעיף 12 לחוק החוזים", "מבחן אובייקטיבי", "מבחן סובייקטיבי", "דרך מקובלת", "אחריות טרום-חוזית"]'::jsonb, '**וריאציה 1 — כוונה רעה:** האם נדרשת כוונה רעה כדי לקבוע חוסר תום לב? ← לא, המבחן אובייקטיבי ואינו דורש כוונה רעה (ת"א (מחוזי ת"א) 45111-01-12 M15 Consultants LTD נ'' ורינט מערכות בע"מ).
**וריאציה 2 — אדם סביר:** לפי איזה סטנדרט נבחנת ההתנהגות? ← לפי סטנדרט האדם הסביר בנסיבות העניין (ת"א (מחוזי ת"א) 27470-02-12 אן גורביץ'' נ'' אסותא מרכזים רפואיים בע"מ).
**וריאציה 3 — חופש החוזים:** האם חובת תום הלב פוגעת בחופש החוזים? ← חובת תום הלב מאזנת בין חופש החוזים לבין ערכים של הגינות ויושר, ואינה שוללת את הזכות לפרוש ממשא ומתן, אך דורשת שהפרישה תיעשה בתום לב (ת"א (שלום בת ים) 28581-01-23 נעימה סקא נ'' אדנץ'' עלם).', 'תום לב (סעיף 12) ← מבחן אובייקטיבי בעיקרו ← לא דורש כוונה/מודעות סובייקטיבית ← סטנדרט האדם הסביר.', '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "ת\"א (מחוזי ת\"א) 45111-01-12 M15 Consultants LTD נ'' ורינט מערכות בע\"מ", "ת\"א (מחוזי ת\"א) 27470-02-12 אן גורביץ'' נ'' אסותא מרכזים רפואיים בע\"מ", "ת\"א (מחוזי חי'') 35338-02-18 דינו גלילוביץ נ'' זהבה עלון אזרזר", "ת\"א (שלום בת ים) 28581-01-23 נעימה סקא נ'' אדנץ'' עלם"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''general_part'' | classifier_note: Standard for good-faith review in pre-contract negotiations — objective vs subjective | source_review_note: השאלה עוסקת בדיני חוזים מהותיים ואינה משתלבת באופן ישיר באף אחד מהפרקים או תתי-הנושאים הקיימים בדין הדיוני. סווגה תחת ''סדר דין אזרחי'' ו''הליכים'' כהצבת מקום זמנית.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'כחוסר תום לב תיחשב סטייה מסטנדרט ההתנהגות המצופה מאדם בעל מאפיינים כשל משה המנהל משא ומתן לקראת כריתתו של חוזה, גם באותם המקרים שבהם לא הייתה למשה כל כוונה לסטות מן ההתנהגות המצופה או מודעות לכך.', true, 'אמת המידה לבחינת תום הלב במשא ומתן היא אובייקטיבית בעיקרה, ואינה דורשת כוונה או מודעות סובייקטיבית לחוסר תום לב. הסטייה נבחנת לפי סטנדרט התנהגות ראוי ומקובל בחברה הישראלית.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'כחוסר תום לב תיחשב סטייה מסטנדרט ההתנהגות המצופה מאדם בעל מאפיינים כשל משה בנסיבות המקרה המנהל משא ומתן לקראת כריתתו של חוזה, אך לא באותם המקרים שבהם לא הייתה למשה כל כוונה לסטות מן ההתנהגות המצופה או מודעות לכך.', false, 'הטענה כי חוסר תום לב אינו חל במקרים של היעדר כוונה או מודעות סובייקטיבית אינה נכונה, שכן המבחן הוא אובייקטיבי בעיקרו ואינו תלוי ביסוד נפשי זה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'כחוסר תום לב תיחשב סטייה מסטנדרט ההתנהגות המצופה בנסיבות המקרה ממשה באופן אישי המנהל משא ומתן לקראת כריתתו של חוזה, גם באותם המקרים שבהם לא הייתה מצידו כל כוונה לסטות מן ההתנהגות המצופה ממנו או מודעות לכך.', false, 'הבחירה ב''משה באופן אישי'' במקום ''אדם בעל מאפיינים כשל משה'' מטעה, שכן המבחן אינו סובייקטיבי טהור המתמקד בסטנדרטים האישיים של הצד, אלא בסטנדרט אובייקטיבי של האדם הסביר בנסיבות דומות.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'כחוסר תום לב תיחשב סטייה מסטנדרט ההתנהגות המצופה בנסיבות המקרה ממשה באופן אישי המנהל משא ומתן לקראת כריתתו של חוזה, אך לא באותם המקרים שבהם לא הייתה מצידו כל כוונה לסטות מן ההתנהגות המצופה ממנו או מודעות לכך.', false, 'שילוב של הטעויות שבסעיפים ב'' ו-ג'': המבחן אינו סובייקטיבי טהור ואינו דורש כוונה או מודעות סובייקטיבית לחוסר תום לב.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חובת גילוי במשא ומתן',
    1, 'חברה א'' ניהלה משא ומתן מתקדם עם חברה ב'' לרכישת מפעל. חברה א'' ידעה על פגם מהותי בציוד המרכזי של המפעל, אך לא גילתה זאת לחברה ב'', אשר לא שאלה על כך במפורש. בסופו של דבר נחתם חוזה. האם התנהלותה של חברה א'' עולה כדי חוסר תום לב במשא ומתן?', 'שאלה זו בוחנת את היקף חובת הגילוי המוטלת על צדדים למשא ומתן מכוח עקרון תום הלב שבסעיף 12 לחוק החוזים, ובפרט את אופייה האקטיבי של חובה זו.', 'אחד מתחומי התחולה השכיחים של חובת תום הלב הוא תחום הגילוי. כאשר על פי הנסיבות היה מקום לצפות לכך שצד המנהל משא ומתן יגלה עובדות מסוימות לצד השני, תחול החובה לנהוג בדרך מקובלת ובתום לב מכוח סעיף 12 לחוק החוזים. מדובר בחובה אקטיבית לגלות עובדות חשובות ועקרוניות המשפיעות על הליך כריתת החוזה, ואין היא מותנית בשאלה מפורשת של הצד השני.',
    'הטעות הנפוצה היא לחשוב שחובת הגילוי היא פסיבית ותלויה בשאלות הצד השני, ולא חובה אקטיבית לגלות מידע מהותי.', '["תום לב במשא ומתן", "חובת גילוי", "סעיף 12 לחוק החוזים", "עובדות מהותיות", "אחריות טרום-חוזית"]'::jsonb, '**וריאציה 1 — אי-גילוי פגם נסתר:** האם אי-גילוי פגם נסתר בדירה מהווה חוסר תום לב? ← כן, אם הפגם מהותי והיה על המוכר לדעת ולגלות (ע"א 838/75 ספקטור נ'' צרפתי).
**וריאציה 2 — אי-גילוי מידע משפטי:** האם אי-גילוי מידע משפטי רלוונטי (כגון בעיות רישום) מהווה חוסר תום לב? ← כן, חובת הגילוי חלה גם על מידע משפטי מהותי (ת"א (מחוזי חי'') 35338-02-18 דינו גלילוביץ נ'' זהבה עלון אזרזר).
**וריאציה 3 — גילוי חלקי:** האם גילוי חלקי ומטעה של מידע מהווה חוסר תום לב? ← כן, גילוי חלקי שיוצר מצג שווא נחשב לחוסר תום לב (ע"א 1810-07 דוד סימן טוב נ'' נפתלי ניסני).', 'חובת גילוי ← אקטיבית ← עובדות מהותיות ← גם ללא שאלה מפורשת.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "ת\"א (מחוזי ת\"א) 45111-01-12 M15 Consultants LTD נ'' ורינט מערכות בע\"מ", "ע\"א 434/07 אריק פרינץ נ'' אמירים מושב עובדים של צמחונים וטבעונים להתיישבות חקלאית שיתופית בע\"מ", "ת\"א (מחוזי חי'') 35338-02-18 דינו גלילוביץ נ'' זהבה עלון אזרזר", "ת\"א (מחוזי ת\"א) 1810-07 דוד סימן טוב נ'' נפתלי ניסני"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, חובת תום הלב כוללת חובת גילוי אקטיבית של עובדות מהותיות, גם אם הצד השני לא שאל עליהן.', true, 'חובת הגילוי היא גילוי מובהק של עקרון תום הלב, והיא חובה אקטיבית המוטלת על צדדים למשא ומתן לגלות עובדות חשובות ועקרוניות המשפיעות על הליך כריתת החוזה, גם ללא שאלה מפורשת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, חובת הגילוי חלה רק אם הצד השני שאל במפורש על המידע.', false, 'הפסיקה קבעה כי חובת הגילוי אינה מותנית בשאלה מפורשת של הצד השני, אלא היא חובה אקטיבית לגלות מידע חיוני כאשר על פי הנסיבות היה מקום לצפות לכך.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, כי חברה ב'' הייתה יכולה לגלות את הפגם בעצמה בבדיקה סבירה.', false, 'אף שקיימת חובה לבדוק, חובת הגילוי של הצד השני אינה מתבטלת אוטומטית רק משום שהצד הנפגע יכול היה לגלות את המידע בעצמו, במיוחד כשמדובר בפגם מהותי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אך רק אם חברה א'' ידעה שהפגם יגרום נזק משמעותי לחברה ב''.', false, 'חובת הגילוי אינה מותנית בידיעה על נזק עתידי, אלא בעצם מהותיות המידע והשפעתו על הליך כריתת החוזה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן תום הלב - אובייקטיבי או סובייקטיבי',
    2, 'מהו המבחן העיקרי לבחינת חובת תום הלב במשא ומתן לפי סעיף 12 לחוק החוזים?', 'שאלה זו מתמקדת באופי המבחן המשפטי לקביעת חוסר תום לב במשא ומתן, ומבהירה את היחס בין המרכיבים האובייקטיביים והסובייקטיביים שבמבחן זה.', 'המבחן לבחינת תום הלב לפי סעיף 12 לחוק החוזים הוא אובייקטיבי בעיקרו, וכולל בתוכו גם מרכיבים סובייקטיביים. המבחן האובייקטיבי בוחן את ההתנהגות לפי אמות מידה כלליות של הגינות ויושר, כפי שמצופה מהאדם הסביר בנסיבות נתונות. המרכיבים הסובייקטיביים מתחשבים בטיב העסקה ובאופי הצדדים, אך אינם הופכים את המבחן לסובייקטיבי טהור.',
    'הבלבול בין מבחן אובייקטיבי למבחן סובייקטיבי, או אי-הבנת הדומיננטיות של המרכיב האובייקטיבי במבחן המעורב.', '["תום לב במשא ומתן", "מבחן אובייקטיבי", "מבחן סובייקטיבי", "אדם סביר", "סעיף 12 לחוק החוזים"]'::jsonb, '**וריאציה 1 — מבחן אובייקטיבי טהור:** האם תום הלב נבחן רק לפי מה שהצד חשב? ← לא, המבחן הוא אובייקטיבי בעיקרו, לפי אמות מידה כלליות (ת"א (מחוזי ת"א) 45111-01-12 M15 Consultants LTD נ'' ורינט מערכות בע"מ).
**וריאציה 2 — מבחן סובייקטיבי טהור:** האם תום הלב נבחן רק לפי כוונת הצד? ← לא, גם אם הצד האמין שהוא פועל ביושר, ייתכן שסטנדרט ההתנהגות האובייקטיבי לא קוים (צפורה כהן, בעלי מניות בחברה - זכויות תביעה ותרופות, 2006).
**וריאציה 3 — מבחן מעורב:** מהם המרכיבים הסובייקטיביים הנלקחים בחשבון? ← טיב העסקה, אופי הצדדים, והיסוד הנפשי והתנהגותם של הצדדים למשא ומתן (ת"א (מחוזי ת"א) 45111-01-12 M15 Consultants LTD נ'' ורינט מערכות בע"מ).', 'מבחן תום לב (סעיף 12) ← אובייקטיבי בעיקרו ← משלב סובייקטיבי (טיב עסקה, אופי צדדים).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "ת\"א (מחוזי ת\"א) 45111-01-12 M15 Consultants LTD נ'' ורינט מערכות בע\"מ", "ת\"א (מחוזי ת\"א) 27470-02-12 אן גורביץ'' נ'' אסותא מרכזים רפואיים בע\"מ", "ת\"א (מחוזי חי'') 35338-02-18 דינו גלילוביץ נ'' זהבה עלון אזרזר", "צפורה כהן בעלי מניות בחברה - זכויות תביעה ותרופות - כרך א'' (2006) | פרק ארבעה-עשר תביעה על-פי סעיף 12 לחוק החוזים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מבחן סובייקטיבי, הבוחן את כוונתו ומודעותו של הצד הספציפי.', false, 'מבחן סובייקטיבי טהור אינו המבחן העיקרי, שכן הוא אינו משקף את הסטנדרט הערכי הראוי הנדרש בחברה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'מבחן אובייקטיבי, הבוחן את ההתנהגות לפי אמות מידה כלליות של האדם הסביר.', true, 'המבחן העיקרי לתום לב הוא אובייקטיבי, הבוחן את ההתנהגות לפי אמות מידה כלליות של הגינות ויושר, כפי שמצופה מהאדם הסביר בנסיבות העניין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מבחן מעורב, הכולל מרכיבים אובייקטיביים וסובייקטיביים, אך עם דומיננטיות למרכיב הסובייקטיבי.', false, 'המבחן אכן מעורב, אך הדומיננטיות היא למרכיב האובייקטיבי, ולא לסובייקטיבי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מבחן מעורב, הכולל מרכיבים אובייקטיביים וסובייקטיביים, אך עם דומיננטיות למרכיב האובייקטיבי.', false, 'למרות שהמבחן הוא מעורב עם דומיננטיות אובייקטיבית, תשובה ב'' מדויקת יותר בהגדרת המבחן העיקרי, שכן היא מתארת את הליבה האובייקטיבית של המבחן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'אחריות אישית של אורגן בחברה',
    3, 'מנהל בחברה ניהל משא ומתן בשם החברה, ובמהלכו הפר את חובת תום הלב. האם ניתן להטיל עליו אחריות אישית בגין הפרת חובת תום הלב, ומהו המבחן לכך?', 'שאלה זו עוסקת בסוגיית הטלת אחריות אישית על אורגן או נושא משרה בתאגיד בגין הפרת חובת תום הלב במשא ומתן, ומבהירה את המבחן המיוחד והמחמיר יותר החל במקרים אלו.', 'על אף שככלל סטנדרט ההתנהגות הנדרש מצד למשא ומתן הוא תום לב אובייקטיבי, הפסיקה קבעה אמת מידה מצמצמת לצורך הטלת אחריות אישית על נושא משרה או אורגן בתאגיד. במקרים אלו, הסטנדרט שיוחל יהיה סובייקטיבי, ולפיו רק כאשר דבק פגם אישי בהתנהלותו של נושא המשרה, כגון כאשר הוא הטעה ביודעין את הצד האחר, נכון להטיל עליו אחריות אישית.',
    'החלת המבחן האובייקטיבי הכללי על אורגן בחברה, במקום המבחן הסובייקטיבי המחמיר הנדרש להטלת אחריות אישית עליו.', '["אחריות אישית", "אורגן בחברה", "תום לב סובייקטיבי", "סעיף 12 לחוק החוזים", "הטעיה ביודעין"]'::jsonb, '**וריאציה 1 — מנהל הטעה ביודעין:** האם מנהל שהטעה ביודעין יישא באחריות אישית? ← כן, זו דוגמה לחוסר תום לב סובייקטיבי המצדיק אחריות אישית (ע"א 7721/22 ד"ר עופר ולטר נ'' עו"ד יוסף שטבהולץ).
**וריאציה 2 — מנהל התרשל:** האם מנהל שהתרשל ולא גילה מידע יישא באחריות אישית? ← לא בהכרח, רשלנות לבדה אינה מספיקה להטלת אחריות אישית על אורגן, אלא נדרש יסוד נפשי מחמיר יותר (ע"א 7721/22 ד"ר עופר ולטר נ'' עו"ד יוסף שטבהולץ).
**וריאציה 3 — מנהל פעל בתום לב:** האם מנהל שפעל בתום לב אך החברה הפרה את חובת הגילוי תישא באחריות אישית? ← לא, אם לא הוכח חוסר תום לב סובייקטיבי של המנהל, לא תוטל עליו אחריות אישית (ע"א 7721/22 ד"ר עופר ולטר נ'' עו"ד יוסף שטבהולץ).', 'אחריות אישית אורגן ← דורשת חוסר תום לב סובייקטיבי ← פגם אישי (כגון הטעיה ביודעין).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "ע\"א 7721/22 ד\"ר עופר ולטר נ'' עו\"ד יוסף שטבהולץ", "ד\"נ 7/81 פנידר, חברה להשקעות פתוח ובנין בע\"מ נ'' קסטרו, פ\"ד לז(4) 673 (1983)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, ניתן להטיל עליו אחריות אישית במבחן אובייקטיבי, כפי שחל על כל צד למשא ומתן.', false, 'אף שעל צד למשא ומתן חל מבחן אובייקטיבי, הפסיקה קבעה מבחן מחמיר יותר להטלת אחריות אישית על אורגן בחברה, משיקולי מדיניות משפטית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, אורגן בחברה אינו יכול לשאת באחריות אישית בגין הפרת תום לב במשא ומתן שניהל בשם החברה.', false, 'הטענה כי אורגן אינו יכול לשאת באחריות אישית אינה נכונה. הפסיקה מכירה באפשרות זו, אך בתנאים מסוימים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, ניתן להטיל עליו אחריות אישית רק אם הוכח לגביו חוסר תום לב סובייקטיבי, כלומר פגם אישי בהתנהלותו.', true, 'הפסיקה קבעה כי להטלת אחריות אישית על אורגן בחברה בגין הפרת תום לב במשא ומתן, נדרש סטנדרט מחמיר יותר של חוסר תום לב סובייקטיבי, כלומר פגם אישי בהתנהלותו, כגון הטעיה ביודעין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, אך רק אם החברה עצמה לא יכולה לשאת באחריות בגין הפרת תום הלב.', false, 'האחריות האישית של האורגן אינה תלויה בהכרח בחוסר יכולת של החברה לשאת באחריות, אלא בפגם אישי בהתנהלותו של האורגן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעדים בגין הפרת תום לב במשא ומתן',
    4, 'ראובן ניהל משא ומתן עם שמעון לרכישת נכס, אך שמעון פרש מהמשא ומתן בחוסר תום לב, והחוזה לא נכרת. איזה סעד עיקרי זכאי ראובן לתבוע משמעון בגין הפרת חובת תום הלב?', 'שאלה זו בוחנת את הסעדים הניתנים בגין הפרת חובת תום הלב במשא ומתן, ובפרט את ההבחנה בין פיצויי הסתמכות (שליליים) לפיצויי קיום (חיוביים) ואת נסיבות פסיקתם.', 'סעיף 12(ב) לחוק החוזים קובע כי צד שלא נהג בתום לב חייב לצד השני פיצויים בעד הנזק שנגרם לו עקב המשא ומתן. ההלכה הפסוקה קבעה כי הסעד הרגיל והטבעי במקרה של הפרת תום לב במשא ומתן שלא הבשיל לחוזה הוא פיצויי הסתמכות (פיצויים שליליים), שמטרתם להחזיר את הנפגע למצב בו היה אילו המשא ומתן לא התקיים. פיצויי קיום (פיצויים חיוביים) ייפסקו רק במקרים נדירים וחריגים, כאשר המשא ומתן הגיע לשלב מתקדם מאוד וגמירת הדעת הייתה ברורה, וכל שנותר הוא אישור טכני.',
    'הנחה שכל הפרת תום לב מזכה בפיצויי קיום, או בלבול בין פיצויי הסתמכות לפיצויי קיום.', '["סעדים", "פיצויי הסתמכות", "פיצויי קיום", "סעיף 12 לחוק החוזים", "פרישה ממשא ומתן"]'::jsonb, '**וריאציה 1 — משא ומתן מוקדם:** מהו הסעד אם הפרישה בחוסר תום לב הייתה בשלב מוקדם? ← פיצויי הסתמכות, שכן לא נוצרה ציפייה לחוזה (גבריאלה שלו ואפי צמח, דיני חוזים, 2019).
**וריאציה 2 — משא ומתן מתקדם מאוד:** מהו הסעד אם הפרישה בחוסר תום לב הייתה בשלב מתקדם מאוד, כמעט לפני חתימה? ← במקרים חריגים, פיצויי קיום, אם גמירת הדעת הייתה ברורה וכל שנותר הוא טכני (ע"א 6370/00 קל בנין בע"מ נ'' ע.ר.מ. רעננה לבניה והשכרה בע"מ).
**וריאציה 3 — נזק עקיף:** האם ניתן לתבוע נזקים עקיפים שנגרמו עקב המשא ומתן? ← כן, פיצויי הסתמכות יכולים לכלול גם נזקים עקיפים שנגרמו עקב המשא ומתן (סעיף 12(ב) לחוק החוזים).', 'הפרת תום לב (סעיף 12) ← סעד עיקרי: פיצויי הסתמכות ← סעד חריג: פיצויי קיום (במקרים נדירים).',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "ע\"א 6370/00 קל בנין בע\"מ נ'' ע.ר.מ. רעננה לבניה והשכרה בע\"מ, נו(3) 289 (2002)", "גבריאלה שלו ואפי צמח דיני חוזים (2019) | פרק 4 משא ומתן טרום-חוזי"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'אכיפת החוזה, שכן חוסר תום לב מונע פרישה מהמשא ומתן.', false, 'אכיפת חוזה שלא נכרת היא סעד חריג ביותר, ואינה הסעד העיקרי בגין הפרת תום לב במשא ומתן שלא הבשיל לחוזה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'פיצויי קיום (פיצויים חיוביים), המעמידים את ראובן במצב כאילו החוזה נכרת וקויים.', false, 'פיצויי קיום הם סעד חריג ביותר בגין הפרת תום לב במשא ומתן שלא הבשיל לחוזה, וייפסקו רק במקרים נדירים שבהם גמירת הדעת הייתה ברורה וכל שנותר הוא אישור טכני.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'פיצויי הסתמכות (פיצויים שליליים), המעמידים את ראובן במצב כאילו המשא ומתן לא התקיים.', true, 'הסעד הרגיל והטבעי בגין הפרת חובת תום הלב במשא ומתן שלא הבשיל לחוזה הוא פיצויי הסתמכות, שמטרתם להחזיר את הנפגע למצב בו היה אילו המשא ומתן לא התקיים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'פיצויים עונשיים, בגין התנהגותו הפסולה של שמעון.', false, 'המשפט הישראלי אינו מכיר בפיצויים עונשיים כסעד בגין הפרת חובת תום הלב במשא ומתן.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 22, '2023-S-S-Q22';
END
$$;

