-- Q23 — 2023-S-S-Q23 — chapter=contracts subtopic=sale
-- classifier_note: Real estate sale 'As Is' clause, hidden permit issue — sale-of-goods/real-property + disclosure
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'bb1087ef-61a9-4829-b4dd-2747b5e3447f'::uuid;
  v_group_id uuid := 'e5988298-c175-46e3-8880-e2f6c8d7eaed'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '8eae8939-0dff-4402-9b56-cd6a5124eb90'::uuid;
  v_ang_1 uuid := '25637262-cb2e-4712-92ef-70280aa4ddc9'::uuid;
  v_ang_2 uuid := '5ed5917b-5133-4a23-8006-5cc03d4609d1'::uuid;
  v_ang_3 uuid := 'dcb06ee5-09a7-4959-bc8a-f43631c10e12'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q23';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 23, '2023-S-S-Q23';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'sale' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'sale', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q23', v_chapter_id, v_subtopic_id, 'ראובן מכר את ביתו לשמעון. בחוזה המכר נכתב שהבית נבנה כדין על פי היתר בנייה. כמו כן, נכתב כי הקונה רוכש את הבית כמות שהוא (As Is) ומצהיר שבדק את הבית ואת תוכניותיו ורישומו ברשויות השונות. זמן מה לאחר השלמת העסקה התברר שהקומה השנייה בבית נבנתה ללא היתר. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 23}'::jsonb, 'השאלה עוסקת באחריות המוכר לאי-התאמה בממכר, ובפרט בהתנגשות בין הוראת סעיף 16 לחוק המכר, המטילה אחריות על המוכר גם אם הקונה לא בדק את הנכס, לבין תניות חוזיות כגון ''As Is'' או הצהרת הקונה על בדיקה. הפסיקה קבעה כי סעיף 16 הוא קוגנטי וגובר על תניות אלו.', 'סעיף 16 לחוק המכר, התשכ"ח-1968, קובע כי ''היתה אי-ההתאמה נובעת מעובדות שהמוכר ידע או היה עליו לדעת עליהן בעת גמירת החוזה ולא גילה אותן לקונה, זכאי הקונה להסתמך עליה על אף האמור בסעיפים 14 ו-15 או בכל הסכם אחר''. הפסיקה, ובראשה ע"א 8060/11 אורי עיני נ'' חן שיפריס, קבעה כי סעיף זה הוא קוגנטי (כופה) וגובר על כל תניה בחוזה המכר המנסה לפטור את המוכר מאחריות לאי-התאמה שהיה עליו לדעת עליה. בניית קומה ללא היתר היא אי-התאמה מהותית, והמוכר, כבעל הנכס, היה עליו לדעת עליה. לכן, גם אם החוזה כלל תניית ''As Is'' או הצהרת בדיקה, לשמעון עומדת טענה תקפה נגד ראובן.', 'הטעות הנפוצה היא לחשוב שתניית ''As Is'' או הצהרת הקונה על בדיקה פוטרות את המוכר מאחריות לאי-התאמה, ובכך להתעלם מאופיו הקוגנטי של סעיף 16 לחוק המכר.',
    '["חוק המכר", "אי-התאמה", "סעיף 16 לחוק המכר", "As Is", "ייזהר הקונה", "הוראה קוגנטית", "חובת גילוי"]'::jsonb, '**וריאציה 1 — As Is:** האם סעיף ''As Is'' בחוזה פוטר את המוכר מאחריות? ← לא, סעיף 16 לחוק המכר גובר על תניית ''As Is'' (ע"א 8060/11 שיפריס נ'' עיני).
**וריאציה 2 — הצהרת בדיקה:** האם הצהרת הקונה שבדק את הנכס פוטרת את המוכר? ← לא, גם הצהרה כזו אינה גוברת על סעיף 16 לחוק המכר.
**וריאציה 3 — ייזהר הקונה:** האם הכלל ''ייזהר הקונה'' חל במקרה זה? ← לא, הכלל נסוג מפני הוראת סעיף 16 לחוק המכר, המטילה אחריות על המוכר לאי-התאמה שהיה עליו לדעת עליה.', 'אי-התאמה (סעיף 16) ← מוכר אחראי ← גם אם As Is או הקונה בדק ← כי סעיף 16 קוגנטי.', '["חוק המכר, התשכ\"ח-1968, סעיף 16", "ע\"א 8060/11 אורי עיני נ'' חן שיפריס, פ\"ד סו(4) 85 (2013)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''sale'' | classifier_note: Real estate sale ''As Is'' clause, hidden permit issue — sale-of-goods/real-property + disclosure | source_review_note: השאלה עוסקת בדיני מכר מהותיים ואינה משתלבת באופן ישיר באף אחד מהפרקים או תתי-הנושאים הקיימים בדין הדיוני. סווגה תחת ''סדר דין אזרחי'' ו''הליכים'' כהצבת מקום זמנית.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לאור הכלל של "ייזהר הקונה" אין לשמעון טענה תקפה נגד ראובן.', false, 'הכלל ''ייזהר הקונה'' נסוג מפני הוראות חוק המכר, ובפרט סעיף 16, המטיל אחריות על המוכר לאי-התאמה גם אם הקונה לא בדק או יכול היה לגלות את הפגם.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לאור האמור בחוזה שהקונה רוכש את הבית כמות שהוא (As Is) ומצהיר שבדק את הבית ואת תוכניותיו ורישומו ברשויות השונות אין לשמעון טענה תקפה נגד ראובן.', false, 'התנייה בחוזה מסוג ''As Is'' או הצהרת הקונה על בדיקה אינה גוברת על הוראת סעיף 16 לחוק המכר, הקובעת אחריות המוכר לאי-התאמה גם אם הקונה ידע או היה עליו לדעת עליה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לשמעון טענה תקפה נגד ראובן לאור אי-התאמה בין הממכר לבין מה שעליו הוסכם.', true, 'בניית קומה ללא היתר מהווה אי-התאמה מהותית בין הבית שנמכר לבין התיאור בחוזה (''נבנה כדין על פי היתר בנייה''), ועל כן לשמעון עומדת טענה תקפה נגד ראובן מכוח סעיף 16 לחוק המכר.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לשמעון טענה תקפה נגד ראובן לאור אי-התאמה בין הממכר לבין מה שעליו הוסכם, אך לראובן עומדת טענה של אשם תורם כלפי שמעון.', false, 'סעיף 16 לחוק המכר קובע כי על המוכר לא ניתן להטיל אשם תורם במקרה של אי-התאמה, גם אם הקונה לא בדק את הנכס או יכול היה לגלות את הפגם.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'אי-התאמה נסתרת וגילוי מאוחר',
    1, 'ראובן מכר לשמעון דירה. בחוזה לא צוין דבר לגבי מצב הריצוף. שמעון בדק את הדירה לפני הרכישה ולא גילה כל פגם. חודשיים לאחר קבלת החזקה, התגלה כי הריצוף בדירה סדוק באופן נרחב מתחת לשטיחים, פגם שלא ניתן היה לגלותו בבדיקה סבירה. ראובן לא ידע על הפגם. האם לשמעון טענה תקפה נגד ראובן?', 'שאלה זו בוחנת את היקף אחריות המוכר לאי-התאמה נסתרת לפי סעיף 16 לחוק המכר, גם כאשר המוכר לא ידע בפועל על הפגם, וזאת אל מול חובת הבדיקה של הקונה.', 'סעיף 16 לחוק המכר קובע כי ''היתה אי-ההתאמה נובעת מעובדות שהמוכר ידע או היה עליו לדעת עליהן בעת גמירת החוזה ולא גילה אותן לקונה, זכאי הקונה להסתמך עליה על אף האמור בסעיפים 14 ו-15 או בכל הסכם אחר, ובלבד שנתן למוכר הודעה עליה מיד לאחר שגילה אותה''. הפסיקה מפרשת ''היה עליו לדעת'' ככולל גם פגמים נסתרים שלא ניתן היה לגלותם בבדיקה סבירה על ידי הקונה, גם אם המוכר עצמו לא ידע עליהם בפועל, אך היה עליו לדעת עליהם כבעל הנכס. במקרה זה, הריצוף הסדוק הוא אי-התאמה נסתרת שלא ניתן היה לגלותה בבדיקה סבירה, ולכן שמעון זכאי לטעון לאי-התאמה.',
    'הנחה שחובת הבדיקה של הקונה (סעיף 14) או אי-ידיעת המוכר על הפגם, שוללות את אחריות המוכר לפי סעיף 16.', '["אי-התאמה נסתרת", "חוק המכר", "סעיף 16 לחוק המכר", "חובת בדיקה", "אחריות המוכר"]'::jsonb, '**וריאציה 1 — פגם גלוי:** מה הדין אם הפגם היה גלוי בבדיקה סבירה? ← הקונה לא יכול להסתמך על אי-ההתאמה (סעיף 14 לחוק המכר).
**וריאציה 2 — מוכר ידע והסתיר:** מה הדין אם המוכר ידע על הפגם והסתיר אותו? ← הקונה זכאי להסתמך על אי-ההתאמה מכוח סעיף 16, ללא קשר לבדיקה.
**וריאציה 3 — פגם נסתר, מוכר לא ידע:** מה הדין אם הפגם נסתר, המוכר לא ידע, אך היה עליו לדעת? ← הקונה זכאי להסתמך על אי-ההתאמה מכוח סעיף 16, אם לא יכול היה לגלותה בבדיקה סבירה.', 'אי-התאמה נסתרת ← מוכר אחראי (סעיף 16) ← גם אם לא ידע בפועל ← אם היה עליו לדעת ← והקונה לא יכול היה לגלות.',
    '["חוק המכר, התשכ\"ח-1968, סעיפים 14, 16", "ע\"א 8060/11 אורי עיני נ'' חן שיפריס, פ\"ד סו(4) 85 (2013)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, כי ראובן לא ידע על הפגם, ועל כן לא הפר את חובת הגילוי.', false, 'סעיף 16 לחוק המכר מטיל אחריות על המוכר לאי-התאמה גם אם לא ידע עליה, כל עוד הקונה לא ידע עליה ולא יכול היה לגלותה בבדיקה סבירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, כי שמעון רכש את הדירה ''כמות שהיא'' (As Is) והיה עליו לבדוק היטב.', false, 'התנייה ''As Is'' אינה גוברת על סעיף 16 לחוק המכר, במיוחד כאשר מדובר בפגם נסתר שלא ניתן היה לגלותו בבדיקה סבירה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, כי מדובר באי-התאמה נסתרת שלא ניתן היה לגלותה בבדיקה סבירה, וסעיף 16 לחוק המכר חל.', true, 'סעיף 16 לחוק המכר קובע כי אם אי-ההתאמה נובעת מעובדות שהמוכר ידע או היה עליו לדעת עליהן בעת כריתת החוזה, ולא גילה אותן לקונה, זכאי הקונה להסתמך עליה, וזאת על אף האמור בסעיפים 14 ו-15 לחוק (חובת בדיקה ואי-הודעה על אי-התאמה).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אך רק אם יוכיח שראובן פעל בחוסר תום לב.', false, 'אחריות המוכר לפי סעיף 16 אינה מותנית בהוכחת חוסר תום לב מצדו, אלא בעצם קיומה של אי-התאמה שהמוכר ידע או היה עליו לדעת עליה, והקונה לא ידע ולא יכול היה לדעת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן אי-התאמה לפי חוק המכר',
    2, 'מהו המבחן העיקרי לקביעת ''אי-התאמה'' בממכר, לפי חוק המכר?', 'שאלה זו מתמקדת בהגדרת המונח ''אי-התאמה'' בחוק המכר, ובמבחנים לקביעתה, כפי שנקבעו בסעיף 11 לחוק.', 'סעיף 11 לחוק המכר, התשכ"ח-1968, מגדיר אי-התאמה במספר חלופות, שהעיקריות שבהן הן: א. הממכר אינו מתאים למה שהוסכם בין הצדדים (למשל, תיאור בחוזה). ב. הממכר אינו מתאים למטרה שלשמה נועדו נכסים מאותו סוג. ג. הממכר אינו בעל התכונות, האיכות והטיב של נכסים מאותו סוג ושל דוגמה או מודל שהוצגו לקונה. המבחן הוא אפוא סטייה מהמוסכם או מהמקובל, ולא כל פגם אקראי.',
    'בלבול בין המבחן לקיומה של אי-התאמה (סעיף 11) לבין שאלת אחריות המוכר עליה (סעיף 16) או חובת הקונה לבדוק (סעיף 14).', '["אי-התאמה", "חוק המכר", "סעיף 11 לחוק המכר", "הסכם מכר", "תכונות רגילות"]'::jsonb, '**וריאציה 1 — תיאור שגוי:** מה קורה אם התיאור בחוזה שגוי? ← אי-התאמה לפי סעיף 11(1) לחוק המכר.
**וריאציה 2 — איכות ירודה:** מה קורה אם איכות המוצר נמוכה מהמקובל? ← אי-התאמה לפי סעיף 11(3) לחוק המכר.
**וריאציה 3 — אי-התאמה למטרה:** מה קורה אם המוצר לא מתאים למטרה שלשמה נועד? ← אי-התאמה לפי סעיף 11(2) לחוק המכר.', 'אי-התאמה (סעיף 11) ← סטייה מהמוסכם ← או מהמקובל ← או מהתכונות הרגילות.',
    '["חוק המכר, התשכ\"ח-1968, סעיף 11"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'סטייה מהמוסכם בחוזה או מהמקובל לגבי נכסים מאותו סוג.', true, 'סעיף 11 לחוק המכר קובע כי אי-התאמה מתקיימת כאשר הממכר אינו מתאים למה שהוסכם בין הצדדים, או כאשר הוא אינו מתאים למטרה שלשמה נועדו נכסים מאותו סוג, או שאין בו את התכונות הרגילות של נכסים מאותו סוג.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כל פגם או ליקוי בממכר, ללא קשר לציפיות הצדדים או לתיאורו.', false, 'לא כל פגם נחשב לאי-התאמה. המבחן הוא האם הפגם מהווה סטייה מהמוסכם או מהמקובל, ולא כל ליקוי אקראי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'האם המוכר ידע על הפגם והסתיר אותו מהקונה.', false, 'ידיעת המוכר רלוונטית לשאלת אחריותו לאי-התאמה (סעיף 16), אך אינה המבחן לקיומה של אי-התאמה מלכתחילה (סעיף 11).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'האם הקונה יכול היה לגלות את הפגם בבדיקה סבירה.', false, 'יכולת הגילוי של הקונה רלוונטית לחובת הבדיקה שלו (סעיף 14), אך אינה המבחן לקיומה של אי-התאמה מלכתחילה (סעיף 11).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'התנייה על חוק המכר',
    3, 'האם צדדים לחוזה מכר יכולים להתנות על הוראת סעיף 16 לחוק המכר, כך שהמוכר לא יהיה אחראי לאי-התאמה שהיה עליו לדעת עליה?', 'שאלה זו עוסקת באופי הנורמטיבי של סעיף 16 לחוק המכר – האם הוא דיספוזיטיבי (ניתן להתניה) או קוגנטי (כופה), ובכך בוחנת את גבולות חופש החוזים אל מול עקרונות הגנת הצרכן והגינות.', 'הפסיקה בישראל, ובראשה פסק הדין בעניין שיפריס (ע"א 8060/11), קבעה כי סעיף 16 לחוק המכר הוא הוראה קוגנטית (כופה) ולא דיספוזיטיבית. משמעות הדבר היא שלא ניתן להתנות עליה בחוזה, גם באמצעות סעיפים כמו ''הקונה רוכש את הנכס As Is'' או ''הקונה מצהיר שבדק את הנכס''. מטרת הסעיף היא להגן על הקונה מפני אי-התאמה שהמוכר ידע או היה עליו לדעת עליה ולא גילה, וזאת מתוך תפיסה של עליונות חובת הגילוי של המוכר על פני חובת הבדיקה של הקונה.',
    'הנחה שכל הוראות חוק המכר הן דיספוזיטיביות, או אי-הבנת המשמעות של הוראה קוגנטית בהקשר של חופש החוזים.', '["קוגנטי", "דיספוזיטיבי", "סעיף 16 לחוק המכר", "חופש החוזים", "הגנת הצרכן", "As Is"]'::jsonb, '**וריאציה 1 — התניה מפורשת:** האם התניה מפורשת בחוזה על סעיף 16 תהיה תקפה? ← לא, סעיף 16 הוא קוגנטי ולא ניתן להתנות עליו (ע"א 8060/11 אורי עיני נ'' חן שיפריס).
**וריאציה 2 — התניה משתמעת:** האם התניה משתמעת (למשל, דרך התנהגות) על סעיף 16 תהיה תקפה? ← לא, ודאי שלא, שכן גם התניה מפורשת אינה תקפה.
**וריאציה 3 — חוק המכר (דירות):** האם סעיף דומה בחוק המכר (דירות) הוא קוגנטי? ← כן, חוק המכר (דירות) הוא חוק צרכני קוגנטי, וסעיפים דומים בו נועדו להגן על רוכשי דירות (חוק המכר (דירות), תשל"ג-1973).', 'סעיף 16 לחוק המכר ← קוגנטי ← לא ניתן להתנות עליו ← מגן על הקונה.',
    '["חוק המכר, התשכ\"ח-1968, סעיף 16", "ע\"א 8060/11 אורי עיני נ'' חן שיפריס, פ\"ד סו(4) 85 (2013)", "חוק המכר (דירות), תשל\"ג-1973"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, חוק המכר הוא דיספוזיטיבי וניתן להתנות על הוראותיו.', false, 'אף שחוק המכר הוא ברובו דיספוזיטיבי, סעיף 16 נחשב להוראה קוגנטית שלא ניתן להתנות עליה, במיוחד במקרים של אי-התאמה שהמוכר ידע או היה עליו לדעת עליה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, סעיף 16 לחוק המכר הוא הוראה קוגנטית (כופה) שלא ניתן להתנות עליה.', true, 'הפסיקה קבעה כי סעיף 16 לחוק המכר הוא הוראה קוגנטית, שנועדה להגן על הקונה מפני הטעיה או הסתרת מידע מהותי, ולכן לא ניתן להתנות עליה בחוזה, גם באמצעות סעיפים כמו ''As Is''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם ההתניה נעשית במפורש ובכתב, ולא באופן משתמע.', false, 'גם התניה מפורשת בכתב לא תגבר על אופיו הקוגנטי של סעיף 16, שכן מטרתו להגן על הקונה מפני אי-התאמה שהמוכר ידע או היה עליו לדעת עליה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן מדובר בעסקת מכר בין שני סוחרים מנוסים.', false, 'אף שקיימת גמישות מסוימת בעסקאות בין סוחרים, הפסיקה קבעה כי סעיף 16 הוא קוגנטי גם בעסקאות כאלה, אם כי ייתכן ש''היה עליו לדעת'' יפורש באופן שונה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעדים בגין אי-התאמה',
    4, 'שמעון גילה אי-התאמה מהותית בבית שרכש מראובן, וראובן אחראי לה לפי חוק המכר. איזה סעד עיקרי זכאי שמעון לדרוש מראובן?', 'שאלה זו בוחנת את מגוון הסעדים העומדים לרשות קונה שגילה אי-התאמה בממכר, ואת ההבחנה בין הסעדים השונים הקבועים בחוק המכר ובדיני החוזים הכלליים.', 'כאשר מתגלה אי-התאמה בממכר, והמוכר אחראי לה, עומדים לרשות הקונה מספר סעדים, בהתאם לנסיבות ולמהות הפגם. הסעדים העיקריים כוללים: א. הפחתת מחיר הממכר (סעיף 28 לחוק המכר). ב. דרישה לתיקון אי-ההתאמה (סעיף 28 לחוק המכר). ג. פיצויים בגין הנזק שנגרם (סעיף 31 לחוק המכר, בשילוב עם סעיף 10 לחוק החוזים (תרופות בשל הפרת חוזה)). ד. במקרים מסוימים, ביטול החוזה והשבה (סעיף 28 לחוק המכר בשילוב עם חוק החוזים (תרופות)). הבחירה בסעד תלויה בנסיבות המקרה ובשיקול דעת בית המשפט.',
    'הנחה שביטול החוזה הוא הסעד היחיד או האוטומטי, או אי-היכרות עם מגוון הסעדים האחרים.', '["סעדים", "אי-התאמה", "חוק המכר", "הפחתת מחיר", "תיקון", "פיצויים", "ביטול חוזה"]'::jsonb, '**וריאציה 1 — פגם קל:** מהו הסעד המועדף לפגם קל? ← תיקון או הפחתת מחיר (סעיף 28 לחוק המכר).
**וריאציה 2 — פגם חמור:** מהו הסעד לפגם חמור המונע שימוש? ← ביטול החוזה והשבה, או פיצויים (סעיף 28 לחוק המכר וחוק החוזים (תרופות)).
**וריאציה 3 — נזקים עקיפים:** האם ניתן לתבוע פיצויים על נזקים עקיפים שנגרמו מהפגם? ← כן, פיצויים לפי סעיף 31 לחוק המכר בשילוב עם סעיף 10 לחוק החוזים (תרופות).', 'אי-התאמה ← סעדים: הפחתת מחיר, תיקון, פיצויים ← ביטול (במקרים מתאימים).',
    '["חוק המכר, התשכ\"ח-1968, סעיפים 28, 31", "חוק החוזים (תרופות בשל הפרת חוזה), התשל\"א-1970, סעיף 10"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'ביטול החוזה והשבת התמורה ששולמה.', false, 'ביטול החוזה הוא סעד אפשרי, אך הוא אינו הסעד העיקרי או היחיד, ובמקרים רבים בית המשפט יעדיף סעדים אחרים כמו הפחתת מחיר או תיקון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'הפחתת מחיר הממכר, תיקון אי-ההתאמה או פיצויים בגין הנזק שנגרם.', true, 'אלו הם הסעדים העיקריים והנפוצים ביותר הניתנים לקונה במקרה של אי-התאמה, בהתאם לנסיבות ולמהות הפגם, כפי שקבוע בחוק המכר ובדיני החוזים הכלליים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'אכיפת החוזה ודרישה מראובן לבנות את הקומה השנייה כחוק.', false, 'אכיפה במובן של בנייה מחדש היא סעד אפשרי, אך לא תמיד מעשי או רצוי, ואינה הסעד העיקרי במקרים רבים של אי-התאמה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'פיצויים עונשיים בגין התנהגותו של ראובן.', false, 'המשפט הישראלי אינו מכיר בפיצויים עונשיים כסעד בגין אי-התאמה בחוזה מכר, אלא אם כן מדובר במקרים חריגים ביותר של עוולה נזיקית נפרדת.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 23, '2023-S-S-Q23';
END
$$;

-- ============================================================
-- Q25 — 2023-S-S-Q25 — chapter=torts subtopic=nuisance_trespass  [needs_review]
-- classifier_note: Trespass + unjust enrichment combo (company dumped earth on Ehud's land). Primary cause of action is trespass; UE overlap
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '232752af-363d-4b0f-a2e9-6eeabf9554e0'::uuid;
  v_group_id uuid := '1963e906-a6a1-4da4-860f-e5ffb231a01a'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '69cff5f3-8c14-4e9b-98f6-01daf3565ee4'::uuid;
  v_ang_1 uuid := 'b0cfaaed-09d9-49f8-945d-dc505fde05a9'::uuid;
  v_ang_2 uuid := 'c30b0dbf-5876-4272-9ac1-434e28669b5a'::uuid;
  v_ang_3 uuid := 'b9be5b76-9829-4d85-a551-5daa1fa3709e'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q25';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 25, '2023-S-S-Q25';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'torts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'torts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'nuisance_trespass' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'nuisance_trespass', 'torts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q25', v_chapter_id, v_subtopic_id, 'חברה הופקדה על ביצוע עבודות עפר הדרושות לצורך סלילת כביש. כחלק מהעבודות כרתה החברה כמויות עפר עצומות ובחרה להשליכן על המקרקעין הפרטיים שנמצאים כולם בבעלות אהוד, בלי שקיבלה את הסכמתו. משנתגלה הדבר דרש אהוד את סילוק עודפי העפר מהמקרקעין לאלתר. החברה לא חלקה על חובתה לפנות את עודפי העפר מהמקרקעין, אך נדרשו לה 3 שנים להשלים את ביצוע הפינוי. אהוד מגיש תביעה נגד החברה לדמי שימוש ראויים ולהשבת הרווח שצמח לחברה במסגרת דיני עשיית עושר ולא במשפט. אהוד מעוניין למצות את כל זכויותיו במסגרת תביעה אחת שיגיש. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 25}'::jsonb, 'השאלה עוסקת ביחסי הגומלין בין עילות תביעה שונות, ובפרט בין עילת הסגת גבול (נזיקין) לעילת עשיית עושר ולא במשפט, כאשר שתיהן נובעות מאותה מסכת עובדתית של שימוש שלא כדין במקרקעין. הדין מאפשר לתבוע בשתי העילות, אך אוסר על כפל פיצוי, ומאפשר לתובע לזכות בסעד הגבוה מבין השניים.', 'השלכת עודפי עפר על מקרקעין פרטיים ללא הסכמה מהווה הן הסגת גבול במקרקעין (עוולה נזיקית לפי סעיף 29 לפקודת הנזיקין) והן התעשרות שלא כדין על חשבון בעל המקרקעין (עילה לפי סעיף 1 לחוק עשיית עושר ולא במשפט). הפסיקה קבעה כי כאשר אותה מסכת עובדתית מקימה לתובע עילות תביעה שונות, הוא רשאי לצרף אותן בתביעה אחת. עם זאת, קיים איסור על כפל פיצוי, כלומר, התובע לא יזכה בסעדים מצטברים בגין אותו נזק או אותה התעשרות. במקום זאת, הוא יוכל לבחור בסעד הגבוה מבין הפיצוי הנזיקי (בגין הנזק שנגרם לו) וההשבה בעשיית עושר (בגין הרווח שצמח לנתבע).', 'הטעות הנפוצה היא לחשוב שניתן לקבל פיצויים והשבה במצטבר, או שחייבים לבחור בעילה אחת בלבד. יש לזכור את עקרון איסור כפל פיצוי ואת האפשרות לצרף עילות ולבחור בסעד הגבוה.',
    '["עשיית עושר ולא במשפט", "הסגת גבול", "צירוף עילות", "כפל פיצוי", "דמי שימוש ראויים", "התעשרות שלא כדין"]'::jsonb, '**וריאציה 1 — נזק נמוך מהרווח:** אם הנזק שנגרם לאהוד נמוך מהרווח שצמח לחברה, מה יקבל אהוד? ← את הרווח שצמח לחברה, שכן הוא הגבוה מבין השניים (ת"א (מחוזי חי'') 47154-06-14 ויקטור שושן יחיאל נ'' י.ו טירת הכרמל בע"מ).
**וריאציה 2 — נזק גבוה מהרווח:** אם הנזק שנגרם לאהוד גבוה מהרווח שצמח לחברה, מה יקבל אהוד? ← את הנזק שנגרם לו, שכן הוא הגבוה מבין השניים (ת"א (מחוזי חי'') 47154-06-14 ויקטור שושן יחיאל נ'' י.ו טירת הכרמל בע"מ).

**וריאציה 3 — תכלית איסור כפל פיצוי:** מדוע אסור כפל פיצוי? ← כדי למנוע התעשרות שלא כדין של התובע עצמו (ד"נ 20/82 אדרס חמרי בנין בע"מ נ'' הרלו אנד גונ''ס).', 'שימוש שלא כדין במקרקעין ← עילות נזיקין ועשיית עושר ← ניתן לצרף ← אסור כפל פיצוי ← יזכה בגבוה מבין הסעדים.', '["פקודת הנזיקין [נוסח חדש], סעיף 29", "חוק עשיית עושר ולא במשפט, תשל\"ט-1979, סעיף 1", "ד\"נ 20/82 אדרס חמרי בנין בע\"מ נ'' הרלו אנד גונ''ס ג.מ.ב.ה., מב(1) 221 (1988)", "ת\"א (מחוזי חי'') 47154-06-14 ויקטור שושן יחיאל נ'' י.ו טירת הכרמל בע\"מ (3.4.2024)", "דניאל פרידמן, אלרן שפירא בר-אור דיני עשיית עושר ולא במשפט - כרך א (2015) | שער שלישי רווח שהופק מרכוש הזולת או מהפרת חובה כלפיו"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''torts'' subtopic=''nuisance_trespass'' | classifier_note: Trespass + unjust enrichment combo (company dumped earth on Ehud''s land). Primary cause of action is trespass; UE overlap | source_review_note: השאלה עוסקת בדיני עשיית עושר ולא במשפט ודיני נזיקין מהותיים ואינה משתלבת באופן ישיר באף אחד מהפרקים או תתי-הנושאים הקיימים בדין הדיוני. סווגה תחת ''סדר דין אזרחי'' ו''הליכים'' כהצבת מקום זמנית.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'אהוד רשאי לתבוע בכל אחת מהעילות ואף בשתיהן, ויוכל לזכות במצטבר הן בפיצוי על הנזק הן בהשבת טובת ההנאה מכיוון שזו תביעה בעילות נפרדות: של נזיקין ושל עשיית עושר ולא במשפט.', false, 'הטענה כי ניתן לזכות במצטבר הן בפיצוי על הנזק והן בהשבת טובת ההנאה היא שגויה, שכן הדבר מהווה כפל פיצוי ואף התעשרות שלא כדין של התובע.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'אהוד רשאי לתבוע בכל אחת מהעילות ואף בשתיהן, אך לא יוכל לזכות במצטבר הן בפיצוי על הנזק הן בהשבת טובת ההנאה. עם זאת, יוכל לבחור בגבוה מבין שני סעדים אלה.', true, 'הלכה פסוקה היא כי כאשר עומדות לתובע עילות תביעה שונות (כגון נזיקין ועשיית עושר) בגין אותה מסכת עובדתית, הוא רשאי לתבוע על פיהן, אך לא יזכה בכפל פיצוי. עליו לבחור בסעד הגבוה מבין השניים, או שבית המשפט יפסוק לו את הגבוה מביניהם.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'אהוד רשאי לתבוע בכל אחת מהעילות בלבד, אך לא בשתיהן, מכיוון שהוא מגיש תביעה אחת בלבד.', false, 'התובע רשאי לצרף עילות תביעה שונות באותה תביעה, גם אם הן חלופיות או משלימות, ואין עליו לבחור מראש בעילה אחת בלבד.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אהוד רשאי לתבוע בכל אחת מהעילות ואף בשתיהן, ויוכל לזכות במצטבר הן בפיצוי על הנזק הן בהשבת טובת ההנאה מכיוון שזו תביעה בעילות נפרדות: של נזיקין ושל עשיית עושר ולא במשפט, רק אם שתי העילות יכולות להימצא יחדיו בסמכותו העניינית של בית המשפט שדן בתביעה.', false, 'הטענה כי ניתן לזכות במצטבר בפיצוי ובהשבה היא שגויה. שאלת הסמכות העניינית רלוונטית לדיון, אך אינה משנה את הכלל בדבר איסור כפל פיצוי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'דמי שימוש ראויים במקרקעין',
    1, 'ראובן החזיק במקרקעין של שמעון במשך שנתיים ללא הסכמתו, לאחר שחוזה השכירות ביניהם פקע. שמעון תובע מראובן דמי שימוש ראויים בגין תקופה זו. מהי העילה העיקרית לתביעה זו, ומהם יסודותיה?', 'שאלה זו בוחנת את העילות המשפטיות לתביעת דמי שימוש ראויים בגין החזקה ושימוש שלא כדין במקרקעין, ובפרט את עילת עשיית עושר ולא במשפט כעילה מרכזית במקרים אלו.', 'כאשר אדם מחזיק או משתמש במקרקעין של אחר ללא הסכמתו, הוא מתעשר שלא כדין על חשבון בעל המקרקעין. התעשרות זו מקימה עילה לתביעת דמי שימוש ראויים לפי חוק עשיית עושר ולא במשפט, התשל"ט-1979. עילה זו אינה דורשת הוכחת נזק לבעל המקרקעין, אלא רק הוכחת התעשרות של המחזיק שלא כדין. בנוסף, יכולה לקום גם עילת הסגת גבול לפי סעיף 29 לפקודת הנזיקין, אך זו דורשת הוכחת נזק ממון. במקרים רבים, דמי השימוש הראויים משקפים הן את הנזק והן את ההתעשרות.',
    'הבלבול בין עילת הסגת גבול (הדורשת נזק) לעילת עשיית עושר (הדורשת התעשרות שלא כדין), או הנחה שחייבים להוכיח נזק בכל מקרה של שימוש שלא כדין.', '["דמי שימוש ראויים", "עשיית עושר ולא במשפט", "הסגת גבול", "התעשרות שלא כדין", "מקרקעין"]'::jsonb, '**וריאציה 1 — פלישה למקרקעין:** האם פלישה למקרקעין מקימה עילת עשיית עושר? ← כן, פלישה היא שימוש שלא כדין המקים חובת השבה (ע"א 290/80 ש.ג.מ. חניונים בע"מ נ'' מדינת ישראל).
**וריאציה 2 — חישוב דמי שימוש:** כיצד מחושבים דמי שימוש ראויים? ← לרוב לפי שווי שכירות בשוק החופשי, אך בית המשפט רשאי להתחשב בנסיבות (ת"א (שלום ת"א) 13961-04-11 גיטה פת נ'' דן קטלן אסן).
**וריאציה 3 — אי-הוכחת נזק:** האם אי-הוכחת נזק שוללת תביעה לדמי שימוש ראויים? ← לא, בעילת עשיית עושר אין צורך להוכיח נזק, אלא התעשרות (ע"א 588/87 כהן נ'' שמש).', 'שימוש שלא כדין במקרקעין ← עילת עשיית עושר ← דמי שימוש ראויים ← לא דורש נזק.',
    '["חוק עשיית עושר ולא במשפט, תשל\"ט-1979, סעיף 1", "פקודת הנזיקין [נוסח חדש], סעיף 29", "ע\"א 290/80 ש.ג.מ. חניונים בע\"מ נ'' מדינת ישראל, לז(2) 633 (1983)", "ע\"א 588/87 אליעזר כהן נ'' צבי שמש, מה(5) 297 (1991)", "ת\"א (שלום ת\"א) 13961-04-11 גיטה פת נ'' דן קטלן אסן (21.5.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'עילת הסגת גבול בנזיקין, הדורשת הוכחת נזק ממון שנגרם לשמעון.', false, 'עילת הסגת גבול אכן קיימת, אך היא דורשת הוכחת נזק ממון. תביעה לדמי שימוש ראויים מתבססת לרוב על עשיית עושר ולא במשפט, שאינה דורשת הוכחת נזק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'עילת עשיית עושר ולא במשפט, הדורשת הוכחת התעשרות של ראובן שלא כדין על חשבון שמעון.', true, 'החזקה ושימוש במקרקעין ללא הסכמה לאחר פקיעת חוזה מהווה התעשרות שלא כדין, המקימה עילת השבה לדמי שימוש ראויים לפי חוק עשיית עושר ולא במשפט, ואינה דורשת הוכחת נזק לשמעון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'עילת הפרת חוזה, הדורשת הוכחת קיומו של חוזה תקף שהופר על ידי ראובן.', false, 'במקרה זה, חוזה השכירות פקע, ולכן לא ניתן לתבוע בגין הפרת חוזה. השימוש נעשה ללא הסכמה חוזית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'עילת הסגת גבול בנזיקין או עילת עשיית עושר ולא במשפט, לבחירת שמעון, וניתן לזכות בשתיהן במצטבר.', false, 'אף שניתן לתבוע בשתי העילות, לא ניתן לזכות בשתיהן במצטבר, אלא יש לבחור בסעד הגבוה מביניהן כדי למנוע כפל פיצוי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'היחס בין עילות נזיקין לעשיית עושר',
    2, 'כאשר אותה מסכת עובדתית מקימה לתובע הן עילה נזיקית והן עילה בעשיית עושר ולא במשפט, מהו הכלל לגבי צירוף סעדים?', 'שאלה זו עוסקת ביחסי הגומלין בין עילות תביעה שונות, ובפרט בין עילות נזיקיות לעילות בעשיית עושר ולא במשפט, תוך התמקדות בעקרון איסור כפל פיצוי.', 'הפסיקה בישראל קבעה כי אין מניעה עקרונית לתחולתם של דיני נזיקין ודיני עשיית עושר ולא במשפט במקביל על אותה מסכת עובדתית. התובע רשאי לצרף את שתי העילות בתביעתו, ואף לתבוע סעדים חלופיים. עם זאת, קיים סייג מהותי: התובע לא יזכה בכפל פיצוי. כלומר, הוא לא יקבל פיצוי הן בגין הנזק שנגרם לו והן בגין טובת ההנאה שצמחה לנתבע, אלא יקבל את הסעד הגבוה מבין השניים. מטרת הכלל היא למנוע התעשרות שלא כדין של התובע עצמו.',
    'הנחה שניתן לקבל סעדים מצטברים משתי עילות שונות בגין אותו אירוע, או אי-הבנה של עקרון איסור כפל פיצוי.', '["צירוף עילות", "כפל פיצוי", "עשיית עושר ולא במשפט", "דיני נזיקין", "סעדים חלופיים"]'::jsonb, '**וריאציה 1 — הסגת גבול ונזק:** ראובן הסיג גבול במקרקעין של שמעון וגרם נזק של 10,000 ש"ח. ההתעשרות של ראובן הייתה 15,000 ש"ח. כמה יקבל שמעון? ← 15,000 ש"ח, הגבוה מבין השניים (ת"א (מחוזי חי'') 47154-06-14 ויקטור שושן יחיאל נ'' י.ו טירת הכרמל בע"מ).
**וריאציה 2 — הפרת חוזה והתעשרות:** האם ניתן לתבוע פיצויי קיום בגין הפרת חוזה וגם השבה בעשיית עושר? ← לא, פיצויי קיום והשבה הם סעדים סותרים, וקיים חשש לכפל פיצוי (ד"נ 20/82 אדרס חמרי בנין בע"מ נ'' הרלו אנד גונ''ס).
**וריאציה 3 — מניעת התעשרות התובע:** מהי התכלית של איסור כפל פיצוי? ← למנוע התעשרות שלא כדין של התובע על חשבון המפר (גבריאלה שלו, יהודה אדר, דיני חוזים - התרופות, 2009).', 'עילות נזיקין ועשיית עושר ← ניתן לצרף ← אסור כפל פיצוי ← יזכה בגבוה מבין הסעדים.',
    '["ד\"נ 20/82 אדרס חמרי בנין בע\"מ נ'' הרלו אנד גונ''ס ג.מ.ב.ה., מב(1) 221 (1988)", "ע\"א 290/80 ש.ג.מ. חניונים בע\"מ נ'' מדינת ישראל, לז(2) 633 (1983)", "ע\"א 126/89 רו\"ח עובדיה בלס, מפרק קופל טורס בע\"מ נ'' חברת מלונות דן בע\"מ, מו(3) 441 (1992)", "ת\"א (מחוזי חי'') 47154-06-14 ויקטור שושן יחיאל נ'' י.ו טירת הכרמל בע\"מ (3.4.2024)", "גבריאלה שלו, יהודה אדר דיני חוזים - התרופות (2009) | פרק 3: צירוף תרופות והתנאה על דין התרופות"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'התובע חייב לבחור באחת העילות בלבד, ואינו רשאי לצרף אותן.', false, 'התובע רשאי לצרף עילות תביעה שונות, אך כפוף לאיסור כפל פיצוי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'התובע רשאי לצרף את שתי העילות, אך לא יזכה בכפל פיצוי, ויקבל את הסעד הגבוה מבין השניים.', true, 'הלכה פסוקה היא כי אין מניעה לצרף עילות שונות, אך יש למנוע כפל פיצוי. התובע יזכה בסעד הגבוה מבין הפיצוי הנזיקי וההשבה בעשיית עושר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'התובע יזכה תמיד בסעדים מצטברים, שכן מדובר בעילות נפרדות.', false, 'אף שמדובר בעילות נפרדות, איסור כפל פיצוי מונע זכייה בסעדים מצטברים בגין אותו נזק או אותה התעשרות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'התובע יזכה בסעדים מצטברים רק אם יוכיח שהנזק הנזיקי וההתעשרות בעשיית עושר אינם חופפים.', false, 'גם אם הנזק וההתעשרות אינם חופפים במדויק, הכלל הוא למנוע התעשרות שלא כדין של התובע. לרוב, בית המשפט יפסוק את הסכום הגבוה מבין השניים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'השבה הרתעתית',
    3, 'עובד ציבור קיבל שוחד בסך 50,000 ש"ח במסגרת תפקידו. המדינה תובעת ממנו השבה של כספי השוחד לפי חוק עשיית עושר ולא במשפט. האם המדינה צריכה להוכיח כי נגרם לה נזק או שהיא התעשרה על חשבונה?', 'שאלה זו בוחנת את הרחבת עילת עשיית עושר ולא במשפט למקרים של ''השבה הרתעתית'' או ''השבת רווחים'', במיוחד בהקשר של הפרת חובת אמון ולקיחת שוחד, כאשר ההתעשרות אינה בהכרח ''על חשבון'' המזכה באופן ישיר.', 'הכלל הבסיסי בעשיית עושר ולא במשפט הוא שהזוכה התעשר ''על חשבון המזכה''. אולם, הפסיקה הכירה במקרים חריגים, במיוחד בהקשר של הפרת חובת אמון חמורה (כמו לקיחת שוחד על ידי עובד ציבור), באפשרות להורות על ''השבה הרתעתית'' או ''השבת רווחים''. במקרים אלו, המטרה היא למנוע מחוטא לצאת נשכר ממעשיו, גם אם לא ניתן להוכיח שההתעשרות הייתה ישירות ''על חשבון'' המזכה. המדינה, כנציגת הציבור, יכולה לתבוע השבה זו, גם אם לא נגרם לה נזק ממון ישיר.',
    'הנחה שחייבים להוכיח את כל שלושת יסודות עשיית עושר (התעשרות, שלא כדין, על חשבון המזכה) באופן דווקני, גם במקרים חמורים של הפרת חובת אמון.', '["השבה הרתעתית", "עשיית עושר ולא במשפט", "שוחד", "הפרת חובת אמון", "אין חוטא יוצא נשכר"]'::jsonb, '**וריאציה 1 — עובד ציבור ושוחד:** האם עובד ציבור שלקח שוחד חייב בהשבה למדינה? ← כן, מטעמים של השבה הרתעתית ועקרון ''אין חוטא יוצא נשכר'' (ע"א 6266/19 מדינת ישראל המינהל האזרחי באיו"ש נ'' צבי אבנון).
**וריאציה 2 — רווח ללא נזק:** האם ניתן לתבוע השבה של רווח שהופק ללא גרימת נזק ישיר? ← כן, במקרים מסוימים, במיוחד בהפרת חובת אמון (ע"א 6266/19 מדינת ישראל המינהל האזרחי באיו"ש נ'' צבי אבנון).
**וריאציה 3 — קנס פלילי מול השבה:** האם קנס פלילי שנגזר על לוקח שוחד שולל תביעת השבה אזרחית? ← לא, הקנס הוא עונש, והשבה היא הפקעת רווחים שלא כדין, והן משרתות תכליות שונות (ע"א 6266/19 מדינת ישראל המינהל האזרחי באיו"ש נ'' צבי אבנון).', 'שוחד/הפרת אמון ← השבה הרתעתית ← גם ללא נזק ישיר ← ''אין חוטא יוצא נשכר''.',
    '["חוק עשיית עושר ולא במשפט, תשל\"ט-1979, סעיף 1", "ע\"א 6266/19 מדינת ישראל המינהל האזרחי באיו\"ש נ'' צבי אבנון (25.8.2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, המדינה חייבת להוכיח נזק ממון שנגרם לה כתוצאה מלקיחת השוחד.', false, 'עילת עשיית עושר אינה דורשת הוכחת נזק. במקרים של שוחד, המדינה לא בהכרח סובלת נזק ממון ישיר, אך העובד מתעשר שלא כדין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, המדינה חייבת להוכיח שהעובד התעשר ''על חשבונה'' באופן ישיר.', false, 'במקרים של שוחד, הפסיקה הכירה באפשרות להשבה הרתעתית, גם אם ההתעשרות לא הייתה ''על חשבון'' המדינה באופן ישיר, אלא על חשבון הציבור או כתוצאה מהפרת חובת אמון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, במקרים של שוחד, ניתן להורות על השבה הרתעתית גם אם ההתעשרות לא הייתה ''על חשבון'' המדינה באופן ישיר, מטעמים של ''אין חוטא יוצא נשכר''.', true, 'הפסיקה קבעה כי במקרים חמורים של הפרת חובת אמון, כמו לקיחת שוחד, ניתן להורות על השבה הרתעתית, גם אם ההתעשרות לא הייתה ישירות ''על חשבון'' המזכה, מתוך עקרון ש''אין חוטא יוצא נשכר''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אך רק אם העובד הורשע בפלילים ונגזר עליו קנס כספי.', false, 'ההליך הפלילי והקנס הם עונש, ומטרתם שונה מהשבה אזרחית. השבה הרתעתית יכולה להיפסק גם ללא הרשעה פלילית, והיא אינה תלויה בקנס שנגזר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'פטור מהשבה מטעמי צדק',
    4, 'בנק גבה עמלה גבוהה מהרגיל מלקוח בסניף מסוים, ובית המשפט קבע כי מדובר בהתעשרות שלא כדין. הבנק טוען כי פעל בתום לב ובהסתמך על הנחיית הפיקוח על הבנקים. האם בית המשפט רשאי לפטור את הבנק מחובת ההשבה, כולה או מקצתה?', 'שאלה זו עוסקת בסמכותו של בית המשפט לפטור זוכה מחובת השבה, כולה או מקצתה, מטעמי צדק, לפי סעיף 2 לחוק עשיית עושר ולא במשפט, ובשיקולים הרלוונטיים להפעלת סמכות זו, כגון תום לב והסתמכות על רשות.', 'סעיף 2 לחוק עשיית עושר ולא במשפט קובע כי ''בית המשפט רשאי לפטור את הזוכה מחובת ההשבה לפי סעיף 1, כולה או מקצתה, אם ראה שהזכיה לא היתה כרוכה בחסרון המזכה או שראה נסיבות אחרות העושות את ההשבה בלתי צודקת''. סעיף זה מעניק לבית המשפט שיקול דעת רחב. במקרה של בנק שגבה עמלה גבוהה בהסתמך על הנחיה שכשלה או הייתה מדומה, בית המשפט יבחן האם ההסתמכות הייתה סבירה, האם הבנק פעל בתום לב, והאם השבת הרווח תהיה בלתי צודקת בנסיבות העניין. ההגנה הנזיקית של ''מעשה לפי חיקוק'' (סעיף 6 לפקודת הנזיקין) אינה חלה על עילות עשיית עושר, אך שיקולי תום לב והסתמכות יכולים להשפיע על היקף ההשבה מטעמי צדק.',
    'הנחה שפעולה ''לפי חיקוק'' או בתום לב פוטרת אוטומטית מחובת השבה, מבלי להתחשב בשיקולי הצדק הספציפיים של סעיף 2.', '["פטור מהשבה", "שיקולי צדק", "סעיף 2 לחוק עשיית עושר", "תום לב", "הסתמכות"]'::jsonb, '**וריאציה 1 — הסתמכות על הנחיה:** האם הסתמכות על הנחיה שגויה יכולה להצדיק פטור מהשבה? ← כן, זהו שיקול במסגרת סעיף 2 לחוק עשיית עושר, אך לא פטור אוטומטי (רע"א 969/23 בנק הפועלים בע"מ נ'' רון סמוחה).
**וריאציה 2 — התעשרות כפויה:** האם התעשרות כפויה (שלא נתבקשה) יכולה להצדיק פטור? ← כן, זהו שיקול מרכזי לפטור מטעמי צדק (סעיף 2 לחוק עשיית עושר).
**וריאציה 3 — שינוי מצב לרעה:** האם שינוי מצב לרעה של הזוכה יכול להצדיק פטור? ← כן, אם הזוכה שינה את מצבו לרעה בהסתמך בתום לב על ההתעשרות (סעיף 2 לחוק עשיית עושר ולא במשפט, רע"א 5768/94 א.ש.י.ר. יבוא יצור והפצה נ'' פורום אביזרים ומוצרי צריכה בע"מ).', 'פטור מהשבה (סעיף 2) ← שיקול דעת ביהמ"ש ← נסיבות עושות השבה בלתי צודקת ← (תום לב, הסתמכות, התעשרות כפויה).',
    '["חוק עשיית עושר ולא במשפט, תשל\"ט-1979, סעיף 2", "רע\"א 969/23 בנק הפועלים בע\"מ נ'' רון סמוחה (3.7.2023)", "רע\"א 5768/94 א.ש.י.ר. יבוא יצור והפצה נ'' פורום אביזרים ומוצרי צריכה בע\"מ, נב(4) 289 (1998)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, כי מרגע שנקבעה התעשרות שלא כדין, חובת ההשבה היא מוחלטת.', false, 'חובת ההשבה אינה מוחלטת. סעיף 2 לחוק עשיית עושר ולא במשפט מעניק לבית המשפט שיקול דעת לפטור מהשבה מטעמי צדק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, בית המשפט רשאי לפטור את הבנק מחובת ההשבה, כולה או מקצתה, אם ראה שההשבה בלתי צודקת בנסיבות העניין.', true, 'סעיף 2 לחוק עשיית עושר ולא במשפט מעניק לבית המשפט סמכות לפטור זוכה מחובת השבה, כולה או מקצתה, אם ההשבה בלתי צודקת. תום לב והסתמכות על הנחיה רשמית הם שיקולים רלוונטיים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, אלא אם כן הבנק יוכיח שהלקוח לא סבל כל נזק מהגבייה העודפת.', false, 'היעדר נזק למזכה הוא שיקול אחד מבין שיקולי הצדק, אך אינו תנאי בלעדי לפטור מהשבה. בית המשפט בוחן מכלול נסיבות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם הבנק יוכיח שהלקוח ידע על העמלה הגבוהה ולא התנגד לה.', false, 'ידיעת הלקוח היא שיקול, אך אינה תנאי הכרחי לפטור. גם אם הלקוח ידע, עדיין ייתכן שהגבייה הייתה שלא כדין, ובית המשפט יבחן את מכלול שיקולי הצדק.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 25, '2023-S-S-Q25';
END
$$;

