-- Q26 — 2023-S-S-Q26 — chapter=family_inheritance subtopic=inheritance_will
-- classifier_note: Cohabitee (ידועה בציבור) inheritance rights re shared apartment — sec. 55 חוק הירושה
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'e6574a1d-8605-4b30-8d4e-ff6bc6335a7a'::uuid;
  v_group_id uuid := '29f13829-588b-4cda-9303-954a4392d7b1'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '0f15ec86-c250-4080-ae94-3031d0aceec8'::uuid;
  v_ang_1 uuid := '778e08d6-2473-4411-8e73-5092ee3a49c3'::uuid;
  v_ang_2 uuid := 'aba3bba7-4a41-4445-9a66-3eae5dbe1832'::uuid;
  v_ang_3 uuid := 'e89f4dbe-b8a9-41f4-8939-2d79edc6332d'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q26';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 26, '2023-S-S-Q26';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'family_inheritance';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'family_inheritance';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'inheritance_will' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'inheritance_will', 'family_inheritance';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q26', v_chapter_id, v_subtopic_id, 'האם זכותה של הידועה בציבור לרשת את בן זוגה על פי דין כוללת גם את דירת המגורים שבה חיו יחד 3 שנים, ובהנחה שנותרו למוריש אחים בלבד?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 26}'::jsonb, 'השאלה עוסקת בזכות הירושה של ידועים בציבור, ובפרט בזכותם לדירת המגורים של המוריש, בהתאם לסעיפים 11 ו-55 לחוק הירושה. הפסיקה השוותה את מעמדם של ידועים בציבור לבני זוג נשואים לעניין זה, בכפוף לעמידה בתנאים מסוימים.', 'סעיף 55 לחוק הירושה, התשכ"ה-1965, קובע כי ''איש ואישה החיים חיי משפחה במשק בית משותף אך אינם נשואים זה לזה, ומת אחד מהם ובשעת מותו אף אחד מהם לא היה נשוי לאדם אחר, רואים את הנשאר בחיים כאילו המוריש ציווה לו מה שהנשאר בחיים היה מקבל בירושה על-פי דין אילו היו נשואים זה לזה''. סעיף 11(א)(2) לחוק קובע כי אם המוריש הותיר אחים או צאצאיהם או הורי הורים, בן זוגו יורש שני שלישים מהעיזבון, ובלבד שאם ערב מותו של המוריש היה בן הזוג נשוי לו שלוש שנים או יותר וגר עמו באותה שעה בדירה הכלולה בעיזבון, יטול בן הזוג את כל חלקו של המוריש בדירה האמורה. פסק הדין בע"א 714/88 שנצר נ'' ריבלין קבע במפורש כי הוראת סעיף 11(א)(2) חלה גם על ידועים בציבור, ואין להבחין בעניין זה בין נשוי לידוע בציבור, כל עוד עומדים בתנאי סעיף 55 ובתנאי המגורים המשותפים של 3 שנים בדירה.', 'הטעות הנפוצה היא לחשוב שמעמד הידוע בציבור אינו זהה למעמד בן זוג נשוי בכל היבטי הירושה, ובפרט לעניין דירת המגורים, או אי-הבנת תנאי הסף להחלת סעיף 11(א)(2).',
    '["ידועים בציבור", "חוק הירושה", "סעיף 11 לחוק הירושה", "סעיף 55 לחוק הירושה", "דירת מגורים", "ירושה על פי דין", "השוואת מעמד"]'::jsonb, '**וריאציה 1 — תנאי סף:** מהם התנאים להכרה כידועים בציבור לצורך ירושה? ← חיי משפחה, משק בית משותף, אינם נשואים זה לזה, ובשעת מות אחד מהם לא היה בן זוגו נשוי לאחר (ע"א 714/88 שנצר נ'' ריבלין).
**וריאציה 2 — משך המגורים:** כמה זמן נדרש לגור יחד בדירה כדי לרשת אותה? ← 3 שנים לפחות (סעיף 11(א)(2) לחוק הירושה, ע"א 714/88 שנצר נ'' ריבלין).
**וריאציה 3 — יורשים אחרים:** מה קורה אם למוריש יש ילדים? ← בן הזוג יורש חצי מהעיזבון, והילדים את החצי השני, וסעיף 11(א)(2) לא חל (סעיף 11(א)(1) לחוק הירושה).', 'ידוע בציבור ← יורש כדין ← כולל דירת מגורים ← אם חיו 3 שנים ← ואין ילדים.', '["חוק הירושה, התשכ\"ה-1965, סעיפים 11, 55", "ע\"א 714/88 נירה שנצר נ'' יובל ריבלין, מה(2) 089 (1991)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''family_inheritance'' subtopic=''inheritance_will'' | classifier_note: Cohabitee (ידועה בציבור) inheritance rights re shared apartment — sec. 55 חוק הירושה | source_review_note: השאלה עוסקת בדיני ירושה מהותיים ואינה משתלבת באופן ישיר באף אחד מהפרקים או תתי-הנושאים הקיימים בדין הדיוני. סווגה תחת ''סדר דין אזרחי'' ו''הליכים'' כהצבת מקום זמנית.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'כן. אין להבחין בעניין זה בין נשוי לידוע בציבור.', true, 'הפסיקה קבעה כי סעיף 55 לחוק הירושה משווה את מעמדו של הידוע בציבור למעמד בן זוג נשוי לעניין ירושה על פי דין, וכי הוראת סעיף 11(א)(2) לחוק, המעניקה לבן הזוג את חלקו של המוריש בדירת המגורים, חלה גם על ידועים בציבור, בכפוף לתנאים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לא. היא זכאית לשני שלישים מהעיזבון, ועל כן היא זכאית לשני שלישים מדירת המגורים.', false, 'אף שהידועה בציבור זכאית לשני שלישים מהעיזבון כאשר למוריש נותרו אחים, היא זכאית לכל חלקו של המוריש בדירת המגורים אם התקיימו התנאים הקבועים בסעיף 11(א)(2) לחוק הירושה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'הידועה בציבור זכאית לרשת את המיטלטלין ואת מכונית הנוסעים השייכים למשק הבית המשותף אך לא את הדירה.', false, 'הידועה בציבור אכן יורשת את המיטלטלין ומכונית הנוסעים, אך הפסיקה הרחיבה את זכותה גם לדירת המגורים, בכפוף לתנאים מסוימים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'ביחס לדירת המגורים הדבר תלוי בשיקול דעת בית משפט למשפחה אשר יבחן את טיב מערכת יחסיהם ומשכה.', false, 'הזכות לדירת המגורים אינה נתונה לשיקול דעת בית המשפט, אלא קבועה בחוק (סעיף 11(א)(2) לחוק הירושה) ובהלכה הפסוקה, בכפוף לעמידה בתנאים אובייקטיביים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תנאי הכרה כידועים בציבור',
    1, 'ראובן ושמעונה חיו יחד במשך 10 שנים, ניהלו משק בית משותף וראו עצמם כבני זוג לכל דבר ועניין. אולם, ראובן היה נשוי לאישה אחרת, ממנה לא התגרש מעולם. לאחר מותו של ראובן, האם שמעונה תיחשב ל''ידועה בציבור'' לצורך ירושה על פי דין?', 'שאלה זו בוחנת את התנאים המצטברים להכרה בזוג כ''ידועים בציבור'' לצורך חוק הירושה, ובפרט את הדרישה ששני בני הזוג לא יהיו נשואים לאחרים.', 'על פי סעיף 55 לחוק הירושה, התשכ"ה-1965, ותוך יישום הפסיקה בעניין (כגון ע"א 714/88 שנצר נ'' ריבלין), כדי שזוג ייחשב כידועים בציבור לצורך ירושה, עליהם לקיים ארבעה תנאים מצטברים: חיי משפחה, משק בית משותף, אינם נשואים זה לזה, ובשעת מות אחד מהם, בן הזוג השני לא היה נשוי לאדם אחר. במקרה זה, העובדה שראובן היה נשוי לאישה אחרת שוללת את מעמדו כידוע בציבור לצורך ירושה, גם אם הוא ושמעונה קיימו חיי משפחה ומשק בית משותף במשך תקופה ארוכה.',
    'הנחה שקיום חיי משפחה ומשק בית משותף מספיקים להכרה כידועים בציבור, ללא התייחסות למצבם האישי (נשואים לאחר).', '["ידועים בציבור", "חוק הירושה", "סעיף 55 לחוק הירושה", "תנאי סף", "חיי משפחה", "משק בית משותף"]'::jsonb, '**וריאציה 1 — נשואים לאחר:** האם זוג שחי יחד אך אחד מהם נשוי לאחר יכול להיחשב כידוע בציבור לצורך ירושה? ← לא, זהו תנאי סף שלילי (סעיף 55 לחוק הירושה, ע"א 714/88 שנצר נ'' ריבלין).
**וריאציה 2 — חיי משפחה:** מה כוללים ''חיי משפחה''? ← קשר אינטימי, יחסי קרבה, נאמנות, דאגה הדדית (ע"א 714/88 שנצר נ'' ריבלין).
**וריאציה 3 — משק בית משותף:** מהו ''משק בית משותף''? ← ניהול משק בית משותף, קופה משותפת, מגורים תחת קורת גג אחת (ע"א 714/88 שנצר נ'' ריבלין).', 'ידוע בציבור ← תנאים מצטברים ← כולל אי-נישואין לאחר.',
    '["חוק הירושה, התשכ\"ה-1965, סעיף 55", "ע\"א 714/88 נירה שנצר נ'' יובל ריבלין, מה(2) 089 (1991)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, כי הם קיימו חיי משפחה ומשק בית משותף במשך תקופה ארוכה.', false, 'אף שחיי משפחה ומשק בית משותף הם תנאים הכרחיים, הם אינם מספיקים. תנאי נוסף הוא ששני בני הזוג לא יהיו נשואים לאחרים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, כי אחד התנאים להכרה כידועים בציבור לצורך ירושה הוא ששני בני הזוג לא יהיו נשואים לאחרים.', true, 'על פי סעיף 55 לחוק הירושה והפסיקה, תנאי סף להכרה כידועים בציבור לצורך ירושה הוא ששני בני הזוג לא יהיו נשואים לאחרים בעת מות אחד מהם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם שמעונה לא ידעה שראובן נשוי לאישה אחרת.', false, 'ידיעתה של שמעונה אינה משנה את העובדה שראובן היה נשוי לאחרת, עובדה השוללת את מעמדם כידועים בציבור לצורך ירושה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן ראובן הותיר צוואה מפורשת המזכה את שמעונה.', false, 'צוואה מפורשת יכולה לזכות את שמעונה, אך היא אינה הופכת אותה ל''ידועה בציבור'' לצורך ירושה על פי דין, אלא מעניקה לה זכות מכוח הצוואה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'נטל ההוכחה למעמד ידוע בציבור',
    2, 'לאחר מותה של יונה, טען יובל כי הוא היה ''ידוע בציבור'' שלה במשך 3 שנים לפחות, ועל כן הוא זכאי לדירת המגורים שלה. אחותה של יונה חלקה על טענה זו. מי נושא בנטל ההוכחה לקיום יחסים אלו ולמשך תקופת המגורים המשותפים?', 'שאלה זו מתמקדת בנטל ההוכחה המוטל על הטוען למעמד של ''ידוע בציבור'' לצורך ירושה, ובפרט לגבי משך תקופת המגורים המשותפים הנדרשת לזכות בדירת המגורים.', 'על פי הפסיקה, ובהתאם לכלל ''המוציא מחברו עליו הראיה'', נטל ההוכחה בדבר קיום יחסים הדומים לקשר נישואים עם בן הזוג במשך שלוש שנים לפחות לפני פטירתו של המוריש, רובץ על הטוען למעמד של ''ידוע בציבור''. קביעה זו חלה גם על הוכחת משך המגורים המשותפים בדירה, הנדרש בסעיף 11(א)(2) לחוק הירושה, התשכ"ה-1965. במקרה זה, יובל הוא הטוען למעמד ולזכות, ולכן עליו מוטל נטל ההוכחה.',
    'הנחה שנטל ההוכחה קל יותר במקרים של ידועים בציבור, או אי-הבנה של הכלל ''המוציא מחברו עליו הראיה''.', '["נטל הוכחה", "ידועים בציבור", "חוק הירושה", "המוציא מחברו עליו הראיה", "משך מגורים"]'::jsonb, '**וריאציה 1 — הוכחת מעמד:** מי צריך להוכיח שהוא ''ידוע בציבור''? ← הטוען למעמד זה (ע"א 714/88 שנצר נ'' ריבלין).
**וריאציה 2 — הוכחת משך:** מי צריך להוכיח את משך המגורים המשותפים בדירה? ← הטוען לזכות בדירה (ע"א 714/88 שנצר נ'' ריבלין).
**וריאציה 3 — קשיי הוכחה:** האם קשיי הוכחה שוללים את הזכות? ← לא בהכרח, אך נטל ההוכחה עדיין על הטוען (ע"א 714/88 שנצר נ'' ריבלין).', 'נטל הוכחה ← על הטוען ← למעמד ידוע בציבור ← ומשך המגורים.',
    '["חוק הירושה, התשכ\"ה-1965, סעיף 11(א)(2)", "ע\"א 714/88 נירה שנצר נ'' יובל ריבלין, מה(2) 089 (1991)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'אחותה של יונה, שכן היא זו שמתנגדת לטענת יובל.', false, 'נטל ההוכחה מוטל על הטוען לקיום עובדה מסוימת, ולא על המתנגד לה, אלא אם כן מדובר בטענת הגנה או בטענה המעבירה את הנטל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'יובל, שכן הוא הטוען למעמד של ''ידוע בציבור'' ולזכות בדירת המגורים.', true, 'על פי הכלל ''המוציא מחברו עליו הראיה'', נטל ההוכחה לקיום יחסים של ידועים בציבור ולמשך תקופת המגורים המשותפים מוטל על הטוען למעמד זה ולזכות הנובעת ממנו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'נטל ההוכחה מתחלק בין הצדדים באופן שווה.', false, 'נטל ההוכחה אינו מתחלק באופן שווה, אלא מוטל על הצד המבקש להוכיח את העובדות המקימות את זכותו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'בית המשפט יקבע את נטל ההוכחה בהתאם לנסיבות המקרה.', false, 'אף שבית המשפט בוחן את הנסיבות, הכלל הבסיסי לגבי נטל ההוכחה הוא קבוע: על הטוען לזכות להוכיח את העובדות המקימות אותה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פרשנות צוואה סתומה',
    3, 'המנוחה כתבה בכתב ידה מסמך מבולבל ומעורפל, שבו חתימתה הופיעה באמצע המסמך. שמו של המשיב הוזכר רק בחלק האחרון של המסמך, לאחר החתימה, ובהקשר לא ברור שאינו מתייחס במפורש להורשת רכוש. האם ניתן לקיים מסמך זה כצוואה?', 'שאלה זו עוסקת בדרישות הצורניות והמהותיות לצוואה, ובפרט במקרה של צוואה סתומה שאינה מבהירה את זהות היורש או את תוכן הציווי, וכיצד בית המשפט מתייחס למסמך כזה.', 'סעיף 33 לחוק הירושה, התשכ"ה-1965, קובע כי ''הוראת צוואה שאין לראות מתוכה למי ציווה המצווה או מה ציווה או שאין להבין משמעותה - בטלה''. אמנם הפסיקה נוטה להקל בדרישות הצורה הפורמליות של צוואה (כגון מיקום החתימה, כפי שנדון בע"א 714/88 שנצר נ'' ריבלין), כל עוד משוכנע בית המשפט באותנטיות המסמך, אך הקלה זו אינה חלה על דרישות מהותיות. כאשר הצוואה סתומה ואינה מאפשרת לזהות את היורש או את תוכן הציווי, היא בטלה. בית המשפט רשאי להיעזר בנסיבות חיצוניות לצורך פירוש צוואה (סעיף 54(א) לחוק הירושה), אך לא כדי לקבוע את כל תוכנה המהותי של הצוואה כאשר בצוואה עצמה אינו מצוין במפורש מיהו היורש שהמצווה מתכוון להוריש לו את רכושו.',
    'בלבול בין הקלה בדרישות צורניות לבין דרישות מהותיות של צוואה, או הנחה שניתן לפרש כל צוואה סתומה באמצעות נסיבות חיצוניות.', '["צוואה בכתב יד", "צוואה סתומה", "חוק הירושה", "סעיף 33 לחוק הירושה", "פרשנות צוואה", "דרישות צורניות", "דרישות מהותיות"]'::jsonb, '**וריאציה 1 — חתימה באמצע:** האם חתימה באמצע צוואה בכתב יד פוסלת אותה? ← לא בהכרח, אם אותנטיות המסמך ברורה (ע"א 714/88 שנצר נ'' ריבלין).
**וריאציה 2 — יורש לא ברור:** מה קורה אם זהות היורש אינה ברורה מהצוואה? ← הוראת הצוואה בטלה (סעיף 33 לחוק הירושה).
**וריאציה 3 — נסיבות חיצוניות:** האם ניתן להשתמש בנסיבות חיצוניות כדי להשלים צוואה סתומה? ← לא כדי לקבוע את כל תוכנה המהותי, אלא רק לצורך פירוש (סעיף 54(א) לחוק הירושה, ע"א 714/88 שנצר נ'' ריבלין).', 'צוואה סתומה ← בטלה (סעיף 33) ← גם אם אותנטית ← נסיבות רק לפירוש.',
    '["חוק הירושה, התשכ\"ה-1965, סעיפים 19, 25, 33, 54(א)", "ע\"א 714/88 נירה שנצר נ'' יובל ריבלין, מה(2) 089 (1991)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, כי הפסיקה נוטה להקל בדרישות הצורה הפורמליות של צוואה, כל עוד המסמך אותנטי.', false, 'אף שהפסיקה מקלה בדרישות הצורה, הקלה זו אינה חלה על דרישות מהותיות. צוואה סתומה שאינה מבהירה את זהות היורש או את תוכן הציווי, בטלה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, כי צוואה שאינה מציינת במפורש מיהו היורש או מהו הציווי, בטלה על פי חוק הירושה.', true, 'סעיף 33 לחוק הירושה קובע כי הוראת צוואה שאין לראות מתוכה למי ציווה המצווה או מה ציווה, או שאין להבין משמעותה, בטלה. במקרה זה, המסמך סתום ואינו מבהיר את זהות היורש או את תוכן הציווי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם בית המשפט יוכל להיעזר בנסיבות חיצוניות כדי לפרש את כוונת המנוחה.', false, 'בית המשפט רשאי להיעזר בנסיבות חיצוניות לצורך פירוש צוואה, אך לא כדי לקבוע את כל תוכנה המהותי של הצוואה כאשר היא סתומה לחלוטין לגבי זהות היורש או תוכן הציווי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, כי חתימה באמצע המסמך מהווה פגם צורני מהותי שלא ניתן לתיקון.', false, 'הפסיקה נוטה להקל בעניין מיקום החתימה בצוואה בכתב יד, כל עוד אותנטיות המסמך אינה מוטלת בספק. הפגם המהותי כאן הוא סתמיות הצוואה, לא מיקום החתימה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הגשת ראיות באיחור',
    4, 'במהלך דיון בבית המשפט המחוזי, לאחר שלב הסיכומים, ביקשה אחותה של המנוחה להגיש ראיה חדשה (תעודת זהות של יובל) כדי להוכיח שיובל לא היה רווק. האם בית המשפט רשאי לקבל ראיה זו בשלב כה מאוחר של ההליך?', 'שאלה זו עוסקת בסמכותו של בית המשפט לקבל ראיות באיחור, ובשיקולים המנחים אותו בהפעלת סמכות זו, תוך איזון בין הצורך בשמירה על סדרי דין תקינים לבין עשיית צדק.', 'הכלל הוא שיש להקפיד על סדרי דין תקינים ולהגיש ראיות בשלב המיועד לכך. אולם, הפסיקה הכירה בכך שבהתמלא תנאים מסוימים, ניתן לקבל ראיות נוספות לעיתים אף בשלב הערעור, וקל וחומר בערכאה ראשונה, גם אם הוגשו בשלב מאוחר מאוד. בית המשפט ישקול את חשיבות הראיה, את הסיבה לאי-הגשתה במועד, ואת מידת הפגיעה בצד השני, תוך מתן משקל רב לצורך בעשיית צדק ומניעת עיוות דין. במקרה זה, כאשר הטענה בדבר רווקות עלתה רק בשלב הסיכומים, ואי-הוכחתה הייתה עלולה להכשיל את התביעה מטעמים פורמליים, בית המשפט רשאי לקבל את הראיה המאוחרת.',
    'הנחה שסדרי דין הם נוקשים ואינם מאפשרים גמישות, או אי-הבנה של שיקולי הצדק המנחים את בית המשפט בקבלת ראיות באיחור.', '["הגשת ראיות באיחור", "סדרי דין", "שיקול דעת בית המשפט", "עשיית צדק", "עיוות דין"]'::jsonb, '**וריאציה 1 — שלב הערעור:** האם ניתן לקבל ראיות חדשות בשלב הערעור? ← כן, במקרים חריגים ובהתמלא תנאים מסוימים (ע"א 714/88 שנצר נ'' ריבלין).
**וריאציה 2 — חשיבות הראיה:** מהו שיקול מרכזי בקבלת ראיה באיחור? ← חשיבות הראיה לעשיית צדק ומניעת עיוות דין (ע"א 714/88 שנצר נ'' ריבלין).
**וריאציה 3 — פגיעה בצד השני:** האם פגיעה בצד השני מונעת קבלת ראיה באיחור? ← לא בהכרח, בית המשפט יאזן בין השיקולים ויכול לפסוק הוצאות (ע"א 714/88 שנצר נ'' ריבלין).', 'ראיות באיחור ← ביהמ"ש רשאי לקבל ← גם בערעור ← לשם צדק ← איזון שיקולים.',
    '["ע\"א 714/88 נירה שנצר נ'' יובל ריבלין, מה(2) 089 (1991)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, כי יש להקפיד על סדרי דין תקינים, וראיות יש להגיש בשלב המיועד לכך.', false, 'אף שזהו הכלל, בית המשפט רשאי, בנסיבות מסוימות, לקבל ראיות באיחור, במיוחד אם הדבר נדרש לשם עשיית צדק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, בית המשפט רשאי לקבל ראיות נוספות לעיתים אף בשלב הערעור, וקל וחומר בערכאה ראשונה, אם הדבר נדרש לשם עשיית צדק.', true, 'הפסיקה קבעה כי בהתמלא תנאים מסוימים, ניתן לקבל ראיות נוספות גם בשלב מאוחר מאוד של ההליך, כולל בשלב הערעור, וקל וחומר בערכאה ראשונה, אם הדבר נדרש לשם עשיית צדק ומניעת עיוות דין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, אלא אם כן הראיה התגלתה רק לאחר שלב הסיכומים ולא ניתן היה להגישה קודם לכן.', false, 'גילוי מאוחר של הראיה הוא שיקול חשוב, אך לא התנאי היחיד. בית המשפט בוחן את מכלול הנסיבות, כולל חשיבות הראיה והצורך בעשיית צדק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם הצד השני מסכים לקבלת הראיה באיחור.', false, 'הסכמת הצד השני היא שיקול, אך בית המשפט אינו כבול לה, ויכול לקבל ראיה גם ללא הסכמה, אם הדבר נדרש לשם עשיית צדק.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 26, '2023-S-S-Q26';
END
$$;

