-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '126b9ee4-7c1a-469a-b933-5b30715c2b21'::uuid;
  v_group_id uuid := '346ba603-8430-47fb-ab65-ed463298229a'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '6feacb5a-3bbf-4e95-8efe-fe4064e9b099'::uuid;
  v_ang_1 uuid := '81cc194e-f4b1-48af-96a8-e08de9e3e9b7'::uuid;
  v_ang_2 uuid := 'c72d87ae-b285-4439-a1f6-48f2b06855a7'::uuid;
  v_ang_3 uuid := '3d1caeb3-0265-4123-abfe-31f2a7008dbb'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q27';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 27, '2023-S-S-Q27';
