  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q27', v_chapter_id, v_subtopic_id, 'יעקב ורחל, בני זוג, כתבו יחד במסמך אחד צוואה שבה נקבע כי העיזבון של מי מביניהם שילך ראשון לעולמו יעבור בשלמותו לשני, והוסיפו כי: "אף אחד מאיתנו אינו רשאי לבטל או לשנות צוואה זו". לאחר שנים, בעודם בחיים, יעקב מעוניין להוריש חלק מעזבונו לאחיו הערירי. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 27}'::jsonb, 'השאלה עוסקת בצוואות הדדיות ובמנגנון ביטולן בחיי שני בני הזוג, כפי שנקבע בסעיף 8א לחוק הירושה. היא בוחנת את האיזון בין עקרון החופש לצוות לבין אינטרס ההסתמכות ההדדית של בני הזוג, ואת תוקפן של הוראות המגבילות את חופש הביטול.', 'סעיף 8א לחוק הירושה, התשכ"ה-1965, מסדיר את נושא הצוואות ההדדיות וביטולן. סעיף 8א(ב)(1) קובע כי בחייהם של שני בני הזוג, המצווה המבקש לבטל את צוואתו ימסור הודעה בכתב על ביטול הצוואה למצווה השני. נמסרה הודעה כאמור, בטלות הצוואות ההדדיות של שני המצווים. בנוסף, סעיף 8א(ג) קובע כי הוראה השוללת לחלוטין את הזכות לבטל את הצוואה בחיי שני בני הזוג – בטלה. במקרה הנדון, יעקב ורחל כללו בצוואתם הוראה השוללת לחלוטין את הזכות לבטל או לשנות את הצוואה. הוראה זו בטלה על פי סעיף 8א(ג). לכן, יעקב רשאי לבטל את צוואתו, אך עליו לעשות זאת באמצעות מסירת הודעה בכתב לרחל. מסירת הודעה זו תביא לבטלות אוטומטית של שתי הצוואות ההדדיות.', 'הטעות הנפוצה היא לחשוב שהוראה בצוואה השוללת ביטול היא תקפה, או שביטול צוואה הדדית בחיי שני בני הזוג אינו גורר ביטול אוטומטי של שתי הצוואות.',
    '["צוואות הדדיות", "ביטול צוואה", "סעיף 8א לחוק הירושה", "חופש הציווי", "אינטרס הסתמכות", "הודעה בכתב", "בטלות אוטומטית"]'::jsonb, '**וריאציה 1 — הוראה מגבילה:** האם הוראה בצוואה הדדית האוסרת ביטול בחיי שני בני הזוג תקפה? ← לא, הוראה כזו בטלה (סעיף 8א(ג) לחוק הירושה).
**וריאציה 2 — דרך הביטול:** איך מבטלים צוואה הדדית בחיי שני בני הזוג? ← על ידי מסירת הודעה בכתב למצווה השני (סעיף 8א(ב)(1) לחוק הירושה).
**וריאציה 3 — תוצאת הביטול:** מהי תוצאת מסירת הודעת הביטול? ← בטלות הצוואות ההדדיות של שני המצווים (סעיף 8א(ב)(1) לחוק הירושה).', 'צוואה הדדית ← הוראה שוללת ביטול בחיי בני הזוג בטלה ← ביטול בהודעה בכתב ← גורר בטלות הדדית.', '["חוק הירושה, תשכ\"ה-1965, סעיף 8א", "ת\"ע (משפחה תל אביב-יפו) 65652-12-22 ש'' א'' נ'' ה'' ל'' (01.09.2024)", "עמ\"ש (מחוזי נצרת) 12539-05-23 ע.ש נ'' מ.מ (31.01.2024)", "בע\"מ 10090/17 פלונית נ'' פלוני (25.01.2018)", "אילנית שבת (חלפון) ואורן שבת ירושה - עסקאות בירושה עתידה וצוואות הדדיות (2006) | 3. ביטול צוואה הדדית בחיי שני המצווים"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''family_inheritance'' subtopic=''inheritance_will'' | classifier_note: Mutual will (צוואה הדדית) + clause prohibiting unilateral revocation | source_review_note: השאלה עוסקת בדיני ירושה מהותיים ואינה משתלבת באופן ישיר באף אחד מהפרקים או תתי-הנושאים הקיימים בדין הדיוני. סווגה תחת ''סדר דין אזרחי'' ו''הליכים'' כהצבת מקום זמנית.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'יעקב רשאי לשנות את צוואתו בכל עת ללא תנאים מוקדמים.', false, 'טענה זו שגויה. אף שהחופש לצוות הוא עקרון יסוד, בצוואות הדדיות קיימים תנאים לביטול, במיוחד כאשר שני בני הזוג בחיים, כפי שקובע סעיף 8א(ב)(1) לחוק הירושה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על יעקב למסור לרחל הודעה בכתב על ביטול הצוואה, צוואתו תתבטל וצוואת רחל תישאר בתוקף אלא אם כן היא תשנה אותה.', false, 'טענה זו שגויה בחלקה. אמנם נדרשת הודעה בכתב, אך מסירת הודעה כזו גוררת בטלות אוטומטית של שתי הצוואות ההדדיות, ולא רק של צוואת המבטל.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על יעקב למסור לרחל הודעה בכתב על ביטול הצוואה, צוואתו תתבטל וצוואת רחל בטלה מאליה.', true, 'סעיף 8א(ב)(1) לחוק הירושה קובע כי בחייהם של שני בני הזוג, המצווה המבקש לבטל את צוואתו ימסור הודעה בכתב על ביטול הצוואה למצווה השני, ועם מסירת ההודעה, בטלות הצוואות ההדדיות של שני המצווים. כמו כן, הוראה השוללת לחלוטין את הזכות לבטל צוואה בחיי שני בני הזוג – בטלה (סעיף 8א(ג)).', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'יעקב אינו רשאי בשום מקרה לשנות את צוואתו לאור ההתחייבות לרחל הגלומה בה.', false, 'טענה זו שגויה. סעיף 8א(ג) לחוק הירושה קובע במפורש כי הוראה השוללת לחלוטין את הזכות לבטל צוואה בחיי שני בני הזוג – בטלה, ועל כן יעקב רשאי לבטל את צוואתו, בכפוף למנגנון הקבוע בחוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'ביטול צוואה הדדית לאחר מות בן הזוג',
    1, 'יעקב ורחל ערכו צוואה הדדית. רחל נפטרה, ויעקב ירש את כל עזבונה. כעת, יעקב מעוניין לבטל את צוואתו שלו ולהוריש את רכושו (כולל מה שירש מרחל) לאחיו. מה הדין?', 'שאלה זו בוחנת את מנגנון ביטול צוואה הדדית לאחר מות אחד מבני הזוג, כפי שנקבע בסעיף 8א(ב)(2) לחוק הירושה. מנגנון זה נועד לאזן בין חופש הציווי של בן הזוג הנותר בחיים לבין אינטרס ההסתמכות של המצווה שנפטר.', 'סעיף 8א(ב)(2) לחוק הירושה, התשכ"ה-1965, קובע שני מסלולים לביטול צוואה הדדית לאחר מות אחד מבני הזוג: (א) כל עוד לא חולק העיזבון – בן הזוג שנותר בחיים ומבקש לבטל את צוואתו יסתלק מכל מנה או חלק בעיזבון שהוא אמור לקבל לפי הצוואה ההדדית של המצווה שמת. (ב) לאחר חלוקת העיזבון – בן הזוג שנותר בחיים ומבקש לבטל את צוואתו ישיב את כל שירש לפי הצוואה ההדדית לעיזבון, ואם השבה בעין בלתי אפשרית או בלתי סבירה – ישיב את שוויה. תנאים אלו נועדו להבטיח כי בן הזוג הנותר בחיים לא ייהנה מהצוואה ההדדית של המנוח ובמקביל יבטל את צוואתו שלו, ובכך יפגע באינטרס ההסתמכות ההדדית.',
    'הנחה שביטול צוואה הדדית לאחר מות בן הזוג זהה לביטול בחיי שניהם, או שאין כלל אפשרות לבטל צוואה כזו לאחר מות בן הזוג.', '["צוואות הדדיות", "ביטול צוואה", "סעיף 8א לחוק הירושה", "הסתלקות מעיזבון", "השבת ירושה", "אינטרס הסתמכות"]'::jsonb, '**וריאציה 1 — לפני חלוקה:** רחל נפטרה, יעקב רוצה לבטל את צוואתו לפני חלוקת העיזבון. מה עליו לעשות? ← להסתלק מכל חלקו בעיזבון רחל (סעיף 8א(ב)(2)(א) לחוק הירושה).
**וריאציה 2 — אחרי חלוקה:** רחל נפטרה, יעקב רוצה לבטל את צוואתו אחרי חלוקת העיזבון. מה עליו לעשות? ← להשיב את כל שירש מרחל לעיזבון (סעיף 8א(ב)(2)(ב) לחוק הירושה).
**וריאציה 3 — מטרת התנאים:** מדוע קיימים תנאים אלו לביטול לאחר המוות? ← כדי לאזן בין חופש הציווי לאינטרס ההסתמכות ולמנוע התעשרות שלא כדין (ת"ע (משפחה תל אביב-יפו) 65652-12-22 ש'' א'' נ'' ה'' ל'').', 'ביטול צוואה הדדית לאחר מוות ← הסתלקות (לפני חלוקה) ← השבה (אחרי חלוקה).',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 8א(ב)(2)", "ת\"ע (משפחה תל אביב-יפו) 65652-12-22 ש'' א'' נ'' ה'' ל'' (01.09.2024)", "אילנית שבת (חלפון) ואורן שבת ירושה - עסקאות בירושה עתידה וצוואות הדדיות (2006) | 5.2. סעיף 8א(ב)(2)(א) לחוק הירושה — ביטול צוואה הדדית לאחר פטירת אחד מבני הזוג — כל עוד לא חולק העיזבון", "אילנית שבת (חלפון) ואורן שבת ירושה - עסקאות בירושה עתידה וצוואות הדדיות (2006) | 5.3. סעיף 8א''(ב)(2)(ב) לחוק הירושה – ביטול צוואה הדדית על ידי בן הזוג שנותר בחיים לאחר חלוקת העיזבון 5.3.1. כללי"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'יעקב רשאי לבטל את צוואתו ללא תנאי, שכן החופש לצוות גובר לאחר מות בן הזוג.', false, 'טענה זו שגויה. לאחר מות אחד מבני הזוג, ביטול צוואה הדדית כפוף לתנאים מחמירים יותר, המגנים על אינטרס ההסתמכות של המצווה שנפטר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'יעקב רשאי לבטל את צוואתו, אך עליו להסתלק מכל חלקו בעיזבון רחל אם העיזבון טרם חולק, או להשיב את כל שירש אם העיזבון כבר חולק.', true, 'סעיף 8א(ב)(2) לחוק הירושה קובע כי לאחר מות אחד מבני הזוג, בן הזוג שנותר בחיים ומבקש לבטל את צוואתו, חייב להסתלק מכל חלקו בעיזבון המנוח (אם טרם חולק) או להשיב את כל שירש (אם חולק), כתנאי לביטול צוואתו שלו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'יעקב אינו רשאי לבטל את צוואתו כלל, שכן ביטול לאחר מות בן הזוג אסור לחלוטין.', false, 'טענה זו שגויה. החוק מאפשר ביטול צוואה הדדית גם לאחר מות בן הזוג, אך זאת בכפוף לתנאים הקבועים בסעיף 8א(ב)(2) לחוק הירושה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'יעקב רשאי לבטל את צוואתו, אך רק אם רחל לא הותירה יורשים אחרים.', false, 'קיום יורשים אחרים אינו תנאי לביטול הצוואה. התנאים לביטול קבועים בסעיף 8א(ב)(2) לחוק הירושה ומתייחסים להסתלקות או השבה של מה שירש יעקב מרחל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תוקף הוראה השוללת ביטול צוואה',
    2, 'יעקב ורחל ערכו צוואה הדדית וכללו בה הוראה מפורשת: ''אף אחד מאיתנו אינו רשאי לבטל או לשנות צוואה זו, גם לא בחיי שנינו''. האם הוראה זו תקפה?', 'שאלה זו מתמקדת בהוראת סעיף 8א(ג) לחוק הירושה, הקובעת את בטלותה של הוראה בצוואה הדדית השוללת לחלוטין את הזכות לבטל את הצוואה בחיי שני בני הזוג. הוראה זו מבטאת את האיזון שקבע המחוקק בין חופש הציווי לאינטרס ההסתמכות.', 'סעיף 8א(ג) לחוק הירושה, התשכ"ה-1965, קובע במפורש כי ''הוראות סעיף קטן (ב) יחולו אם אין בצוואות ההדדיות הוראה אחרת, ואולם הוראה השוללת לחלוטין את הזכות לבטל את הצוואה בחיי שני בני הזוג – בטלה''. משמעות הדבר היא שהמחוקק לא מאפשר לבני זוג לכבול את עצמם באופן מוחלט מביטול צוואתם ההדדית כל עוד שניהם בחיים. הוראה כזו, גם אם נכללה בצוואה, תהיה בטלה. זאת, מתוך הכרה בחשיבות עקרון החופש לצוות, המאפשר לאדם לשנות את רצונו עד לרגע מותו, תוך איזון עם אינטרס ההסתמכות באמצעות מנגנון ההודעה בכתב.',
    'הנחה שרצון הצדדים, גם אם מפורש, גובר תמיד על הוראות חוק קוגנטיות, או אי-הבנה של היקף החופש לצוות בצוואות הדדיות.', '["צוואות הדדיות", "ביטול צוואה", "סעיף 8א(ג) לחוק הירושה", "חופש הציווי", "הוראה בטלה", "איזון אינטרסים"]'::jsonb, '**וריאציה 1 — כבילה מוחלטת:** האם בני זוג יכולים לכבול עצמם מביטול צוואה הדדית בחייהם? ← לא, הוראה כזו בטלה (סעיף 8א(ג) לחוק הירושה).

**וריאציה 2 — איזון אינטרסים:** מהו האיזון שקבע המחוקק? ← חופש לצוות מול אינטרס הסתמכות, עם מנגנון ביטול בחיי שני בני הזוג (ת"ע (משפחה תל אביב-יפו) 65652-12-22 ש'' א'' נ'' ה'' ל'').
**וריאציה 3 — ''הוראה אחרת'':** מה המשמעות של ''הוראה אחרת'' בסעיף 8א(ג)? ← הוראה אחרת יכולה להתנות על מנגנון הביטול, אך לא לשלול אותו לחלוטין בחיי שני בני הזוג (בע"מ 9353-01-25 פלונית נ'' פלונית).', 'הוראה השוללת ביטול צוואה הדדית בחיי בני הזוג ← בטלה (סעיף 8א(ג)).',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 8א(ג)", "ת\"ע (משפחה תל אביב-יפו) 65652-12-22 ש'' א'' נ'' ה'' ל'' (01.09.2024)", "בע\"מ 9353-01-25 פלונית נ'' פלונית (30.01.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, הוראה זו תקפה ומחייבת, שכן היא מבטאת את רצונם המשותף של בני הזוג.', false, 'טענה זו שגויה. סעיף 8א(ג) לחוק הירושה קובע במפורש כי הוראה השוללת לחלוטין את הזכות לבטל צוואה בחיי שני בני הזוג – בטלה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, הוראה זו בטלה, שכן היא שוללת לחלוטין את הזכות לבטל את הצוואה בחיי שני בני הזוג.', true, 'סעיף 8א(ג) לחוק הירושה קובע כי הוראה השוללת לחלוטין את הזכות לבטל את הצוואה בחיי שני בני הזוג – בטלה. המחוקק ביקש לאזן בין אינטרס ההסתמכות לבין החופש לצוות, ולא לאפשר כבילה מוחלטת בחיי שני בני הזוג.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, אך רק אם הצוואה נערכה לפני תיקון מס'' 12 לחוק הירושה.', false, 'הוראת סעיף 8א(ג) חלה על צוואות שנערכו לאחר תיקון מס'' 12. לגבי צוואות שקדמו לתיקון, הדין היה שונה, אך גם אז עקרון החופש לצוות היה חזק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, אלא אם כן יעקב ורחל הסכימו על כך בכתב בפני נוטריון.', false, 'צורת ההסכמה אינה משנה את העובדה שהוראה השוללת לחלוטין את הזכות לבטל צוואה בחיי שני בני הזוג – בטלה על פי חוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'צוואה הדדית לפני תיקון 12',
    3, 'יעקב ורחל ערכו צוואה הדדית בשנת 2000 (לפני תיקון מס'' 12 לחוק הירושה). בצוואה לא נכללה כל הוראה לגבי ביטולה. בשנת 2010, רחל לקתה בדמנציה ואינה כשירה קוגניטיבית. יעקב מעוניין לבטל את צוואתו שלו. מה הדין?', 'שאלה זו עוסקת בתחולת תיקון מס'' 12 לחוק הירושה על צוואות הדדיות שנערכו לפני כניסתו לתוקף, ובפרט במצב שבו אחד מבני הזוג אינו כשיר קוגניטיבית. היא בוחנת את הלכת בית המשפט העליון בעניין זה, המבחינה בין צוואות שקדמו לתיקון לבין אלו שלא.', 'בית המשפט העליון קבע בבע"מ 7884/23 פלוני נ'' פלונית כי הוראות סעיף 8א לחוק הירושה, המסדירות את ביטול הצוואות ההדדיות, אינן חלות על צוואות שנערכו לפני כניסתו לתוקף של תיקון מס'' 12 לחוק (1.8.2005). בצוואות שקדמו לתיקון, חל הדין שהיה קיים ערב התיקון, דהיינו הלכת זמיר (בע"מ 10807/03). הלכה זו קבעה כי עריכת צוואה הדדית כשלעצמה אינה שוללת את כוחו של צד לשנות מצוואתו, בחייו של הצד השני ואף לאחר מותו, וזאת בהיעדר ראיה לכוונה משותפת אחרת של הצדדים. במקרה זה, הצוואה נערכה בשנת 2000 ולא כללה הוראה מגבילה. לכן, יעקב רשאי לבטל את צוואתו באופן חד-צדדי, ואין מניעות לכך גם בשל מצבה הקוגניטיבי של רחל.',
    'הנחה שסעיף 8א חל על כל הצוואות ההדדיות, ללא קשר למועד עריכתן, או אי-הבנה של ההבחנה בין הדין שקדם לתיקון 12 לבין הדין שלאחריו.', '["צוואות הדדיות", "תיקון מס'' 12 לחוק הירושה", "תחולה בזמן", "הלכת זמיר", "חופש הציווי", "כשירות קוגניטיבית"]'::jsonb, '**וריאציה 1 — צוואה לפני 2005:** האם סעיף 8א חל על צוואה הדדית משנת 2000? ← לא, סעיף 8א חל רק על צוואות שנערכו החל מ-1.8.2005 (בע"מ 7884/23 פלוני נ'' פלונית).
**וריאציה 2 — ביטול חד-צדדי:** האם ניתן לבטל צוואה הדדית שנעשתה לפני 2005 באופן חד-צדדי? ← כן, בהיעדר הוראה מגבילה בצוואה עצמה (הלכת זמיר, בע"מ 7884/23 פלוני נ'' פלונית).
**וריאציה 3 — מצב קוגניטיבי:** האם מצב קוגניטיבי ירוד של בן הזוג השני מונע ביטול צוואה שנעשתה לפני 2005? ← לא, אלא אם כן הצוואה עצמה הגבילה זאת (בע"מ 7884/23 פלוני נ'' פלונית).', 'צוואה הדדית לפני תיקון 12 ← סעיף 8א לא חל ← ביטול חד-צדדי אפשרי ← גם אם בן הזוג לא כשיר.',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 8א", "בע\"מ 7884/23 פלוני נ'' פלונית (10.09.2024)", "בע\"מ 10807/03 אליקום זמיר נ'' רות גמליאל, סב(1) 601 (04.02.2007)", "בע\"מ 1857/24 פלונית נ'' פלונית (02.12.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'יעקב אינו רשאי לבטל את צוואתו, שכן מצבה הקוגניטיבי של רחל מונע ממנה להגיב לביטול, והדבר מהווה חוסר תום לב.', false, 'טענה זו שגויה. על פי הלכת בית המשפט העליון, בצוואות שקדמו לתיקון 12, בהיעדר הוראה מגבילה בצוואה עצמה, המצווה רשאי לבטל את צוואתו גם אם בן הזוג השני אינו כשיר קוגניטיבית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'יעקב רשאי לבטל את צוואתו ללא תנאי, שכן הוראות סעיף 8א לחוק אינן חלות על צוואות שנעשו לפני תיקון מס'' 12, ובהיעדר הוראה מגבילה בצוואה עצמה, החופש לצוות גובר.', true, 'הלכת בית המשפט העליון (בע"מ 7884/23) קבעה כי הוראות סעיף 8א לחוק הירושה אינן חלות על צוואות שנערכו לפני תיקון מס'' 12 (אוגוסט 2005). בצוואות כאלה, בהיעדר הוראה מפורשת בצוואה המגבילה את הביטול, החופש לצוות גובר, וניתן לבטל את הצוואה באופן חד-צדדי, גם אם בן הזוג השני אינו כשיר קוגניטיבית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'יעקב רשאי לבטל את צוואתו, אך עליו לקבל אישור מבית המשפט לענייני משפחה, שיבחן את נסיבות המקרה.', false, 'קבלת אישור מבית המשפט אינה נדרשת במקרה זה, שכן הדין שחל על צוואות שקדמו לתיקון 12, בהיעדר הוראה מגבילה, מאפשר ביטול חד-צדדי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'יעקב רשאי לבטל את צוואתו, אך עליו למסור הודעה בכתב לאפוטרופוס של רחל.', false, 'דרישת מסירת הודעה בכתב לאפוטרופוס רלוונטית לצוואות שנערכו לאחר תיקון 12, וגם אז, תוקף מסירה כזו לאדם שאינו כשיר קוגניטיבית נתון במחלוקת. במקרה זה, הוראות תיקון 12 אינן חלות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'דרכי ביטול צוואה רגילה',
    4, 'יעקב ערך צוואה רגילה (שאינה הדדית) שבה הוריש את כל רכושו לרחל. כעת, הוא מעוניין לבטל צוואה זו. מהן הדרכים שבהן יעקב יכול לבטל את צוואתו?', 'שאלה זו בוחנת את הדרכים לביטול צוואה רגילה (שאינה הדדית), כפי שנקבעו בסעיף 36 לחוק הירושה. היא מדגישה את הדרישות הצורניות לביטול צוואה, המבטאות את חשיבות גמירות דעתו של המצווה.', 'סעיף 36(א) לחוק הירושה, התשכ"ה-1965, קובע שתי דרכים עיקריות לביטול צוואה: (1) ביטול במפורש באחת הצורות לעשיית צוואה – כלומר, על ידי עריכת מסמך חדש (כגון צוואה חדשה, צוואה בעדים, צוואה בכתב יד, צוואה בפני רשות) שבו המצווה מצהיר במפורש על ביטול הצוואה הקודמת. (2) השמדת הצוואה – אם המצווה משמיד את הצוואה, חזקה עליו שהתכוון בכך לבטלה. סעיף 36(ב) מוסיף כי צוואה חדשה, גם ללא ביטול מפורש, מבטלת את הקודמת במידה שהוראותיה סותרות. חשוב לציין כי הפסיקה נוטה להקל בדרישות הצורניות לביטול צוואה לעומת עשייתה, אך עדיין נדרשת גמירות דעת ברורה של המצווה לבטל.',
    'הבלבול בין דרכי עשיית צוואה לדרכי ביטולה, או הנחה שניתן לבטל צוואה בכל דרך שאינה פורמלית.', '["ביטול צוואה", "צוואה רגילה", "סעיף 36 לחוק הירושה", "השמדת צוואה", "ביטול במפורש", "גמירות דעת"]'::jsonb, '**וריאציה 1 — ביטול מפורש:** איך מבטלים צוואה במפורש? ← באחת הצורות לעשיית צוואה, למשל בצוואה חדשה המצהירה על ביטול (סעיף 36(א) לחוק הירושה).
**וריאציה 2 — השמדה:** מה קורה אם המצווה משמיד את צוואתו? ← חזקה שהתכוון לבטלה (סעיף 36(א) לחוק הירושה).
**וריאציה 3 — צוואה חדשה סותרת:** האם צוואה חדשה שאינה מצהירה במפורש על ביטול מבטלת את הקודמת? ← כן, במידה שהוראותיה סותרות את הקודמת (סעיף 36(ב) לחוק הירושה).', 'ביטול צוואה רגילה ← ביטול מפורש (בצורת צוואה) ← או השמדה.',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 36", "דנ\"א 7818/00 יוסף אהרן נ'' אמנון אהרוני, נט(6) 653 (22.03.2005)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'רק על ידי עריכת צוואה חדשה הסותרת את הקודמת.', false, 'עריכת צוואה חדשה היא אחת הדרכים, אך לא היחידה. סעיף 36 לחוק הירושה מפרט דרכים נוספות לביטול צוואה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'רק על ידי השמדת הצוואה הפיזית.', false, 'השמדת הצוואה היא אחת הדרכים, אך לא היחידה. סעיף 36 לחוק הירושה מפרט דרכים נוספות לביטול צוואה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'על ידי ביטול במפורש באחת הצורות לעשיית צוואה, או על ידי השמדת הצוואה.', true, 'סעיף 36(א) לחוק הירושה קובע כי המצווה רשאי לבטל צוואתו ''אם על ידי ביטול במפורש באחת הצורות לעשיית צוואה, ואם על ידי השמדת הצוואה''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'על ידי הודעה בעל פה לשני עדים על רצונו לבטל את הצוואה.', false, 'הודעה בעל פה לשני עדים אינה דרך תקפה לביטול צוואה רגילה. ביטול במפורש חייב להיעשות באחת הצורות לעשיית צוואה, כגון צוואה בעדים או בכתב יד.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 27, '2023-S-S-Q27';
END
$$;

-- ============================================================
-- Q28 — 2023-S-S-Q28 — chapter=ethics subtopic=disciplinary_law
-- classifier_note: Lawyer-to-lawyer professional courtesy; mutual respect duty
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'dd3cc658-f645-4dc9-a70d-c8fd6ae46100'::uuid;
  v_group_id uuid := '2d9ba9b7-cd65-4a42-8b13-0646661406b4'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '5675946a-9b42-4e83-9357-49a1a5e41e6c'::uuid;
  v_ang_1 uuid := 'fd1a23c7-0f25-4b22-9ae0-e9a23d712a5d'::uuid;
  v_ang_2 uuid := '1af19cfd-0c78-411a-9fec-fb12f14847b9'::uuid;
  v_ang_3 uuid := 'b74cbac2-0800-4193-98ab-03589043c777'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q28';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 28, '2023-S-S-Q28';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'ethics';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'ethics';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'disciplinary_law' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'disciplinary_law', 'ethics';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q28', v_chapter_id, v_subtopic_id, 'במסגרת הליך משפטי שבו מייצגת עו"ד חני לקוח נקבע מועד לדיון. היות שהבת של עו"ד חני לקתה במחלה, שלחה עו"ד חני לעו"ד לבנה (באת כוח הצד שכנגד) בקשה לדחיית מועד דיון בהסכמה. עו"ד לבנה התעלמה ללא סיבה מפנייתה של עו"ד חני הגם שהפנייה הגיעה לידיה, ועל כן הגישה עו"ד חני תלונה לוועדת האתיקה המחוזית. עו"ד לבנה לא הגיבה לדרישת הוועדה להגיב לתלונה. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 28}'::jsonb, 'השאלה עוסקת בשני היבטים מרכזיים באתיקה המקצועית של עורכי דין: חובת הקולגיאליות בין עורכי דין (כלל 26 לכללי האתיקה) וחובת שיתוף הפעולה עם מוסדות לשכת עורכי הדין, ובפרט עם ועדת האתיקה (כלל 5 לכללי סדרי הדין בבתי הדין המשמעתיים). היא מדגישה כי הפרה של כל אחת מהחובות הללו מהווה עבירת משמעת.', 'השלכת עודפי עפר על מקרקעין פרטיים ללא הסכמה מהווה הן הסגת גבול במקרקעין (עוולה נזיקית לפי סעיף 29 לפקודת הנזיקין) והן התעשרות שלא כדין על חשבון בעל המקרקעין (עילה לפי סעיף 1 לחוק עשיית עושר ולא במשפט). הפסיקה קבעה כי כאשר אותה מסכת עובדתית מקימה לתובע עילות תביעה שונות, הוא רשאי לצרף אותן בתביעה אחת. עם זאת, קיים איסור על כפל פיצוי, כלומר, התובע לא יזכה בסעדים מצטברים בגין אותו נזק או אותה התעשרות. במקום זאת, הוא יוכל לבחור בסעד הגבוה מבין הפיצוי הנזיקי (בגין הנזק שנגרם לו) וההשבה בעשיית עושר (בגין הרווח שצמח לנתבע).', 'הטעות הנפוצה היא לחשוב שניתן לקבל פיצויים והשבה במצטבר, או שחייבים לבחור בעילה אחת בלבד. יש לזכור את עקרון איסור כפל פיצוי ואת האפשרות לצרף עילות ולבחור בסעד הגבוה.',
    '["אתיקה מקצועית", "חובת קולגיאליות", "חובת תגובה לוועדת האתיקה", "עבירת משמעת", "כללי לשכת עורכי הדין", "סדרי דין משמעתיים"]'::jsonb, '**וריאציה 1 — בקשת דחייה סבירה:** האם התעלמות מבקשת דחייה סבירה של עו"ד אחר היא עבירה אתית? ← כן, זו הפרה של חובת הקולגיאליות (כלל 26 לכללי האתיקה).
**וריאציה 2 — אי-תגובה לוועדה:** האם אי-תגובה לפניית ועדת האתיקה היא עבירה אתית? ← כן, זו הפרה של חובת שיתוף הפעולה עם מוסדות הלשכה (כלל 5 לכללי סדרי הדין בבתי הדין המשמעתיים).
**וריאציה 3 — שתי הפרות:** האם ניתן להפר שתי חובות אתיות באותו אירוע? ← כן, כפי שקרה במקרה זה, הפרה של חובת הקולגיאליות ושל חובת התגובה לוועדה.', 'התעלמות מבקשת דחייה סבירה + אי-תגובה לוועדת האתיקה ← שתי עבירות אתיות.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, כלל 26", "כללי לשכת עורכי הדין (סדרי הדין בבתי הדין המשמעתיים), התשע\"ה-2015, כלל 5"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''disciplinary_law'' | classifier_note: Lawyer-to-lawyer professional courtesy; mutual respect duty | source_review_note: סיווג השאלה תחת ''סדר דין פלילי'' ו''משמעת עורכי דין'' נובע מהמגבלות של רשימת הנושאים הסגורה, אף שהשאלה עוסקת באתיקה מקצועית של עורכי דין, שהיא תחום עצמאי.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עו"ד לבנה לא הפרה את חובות האתיקה.', false, 'טענה זו שגויה, שכן עו"ד לבנה הפרה הן את חובת הקולגיאליות כלפי עו"ד חני והן את חובתה להגיב לפניית ועדת האתיקה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עו"ד לבנה לא הפרה את חובות האתיקה שלה בהתעלמות מפנייתה של עו"ד חני, אך הפרה את חובות האתיקה שלה באי-הגשת תגובה לפניית הוועדה.', false, 'טענה זו שגויה בחלקה. התעלמות מבקשת דחייה סבירה של עו"ד אחר מהווה הפרה של חובת הקולגיאליות, בנוסף להפרת חובת התגובה לוועדת האתיקה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עו"ד לבנה הפרה את חובות האתיקה שלה בהתעלמות מפנייתה של עו"ד חני, אך לא באי-הגשת תגובה לפניית הוועדה.', false, 'טענה זו שגויה בחלקה. אי-הגשת תגובה לפניית ועדת האתיקה מהווה הפרה של חובה אתית מפורשת, בנוסף להפרת חובת הקולגיאליות.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עו"ד לבנה הפרה את חובות האתיקה הן בהתעלמות מפנייתה של עו"ד חני הן באי-הגשת תגובה לפניית הוועדה.', true, 'עו"ד לבנה הפרה את כלל 26 לכללי לשכת עורכי הדין (אתיקה מקצועית) בכך שהתעלמה מבקשת דחייה סבירה של עו"ד חני, וכן הפרה את כלל 5 לכללי לשכת עורכי הדין (סדרי הדין בבתי הדין המשמעתיים) בכך שלא הגיבה לפניית ועדת האתיקה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'התעלמות מבקשת דחייה',
    1, 'עו"ד דנה ביקשה מעו"ד יעל, באת כוח הצד שכנגד, לדחות דיון שנקבע לשבוע הבא, עקב אשפוז חירום של ילדה. עו"ד יעל, ללא כל סיבה עניינית, סירבה לבקשה והתעלמה מפניות חוזרות ונשנות של עו"ד דנה. האם עו"ד יעל הפרה חובה אתית?', 'שאלה זו בוחנת את היקף חובת הקולגיאליות בין עורכי דין, ובפרט את החובה להיענות לבקשות סבירות של עמיתים, גם אם אין חובה משפטית מפורשת לעשות כן, תוך התחשבות בנסיבות אישיות.', 'כלל 26 לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986, קובע כי "עורך דין ינהג כלפי חברו למקצוע בדרך ארץ, כבוד וחברות, וימנע מכל מעשה שיש בו כדי לפגוע בכבודו או במעמדו". הפסיקה מדגישה את חשיבות היחסים ההוגנים והמכבדים בין עורכי דין לצורך תפקוד יעיל של המערכת המשפטית (ראו ב"ש (מחוזי ירושלים) 5489/08 ליאורה ברקו נ'' מדינת ישראל). התעלמות מבקשת דחייה סבירה, במיוחד על רקע נסיבות אישיות קשות, נחשבת לפגיעה בחובת הקולגיאליות ומהווה עבירת משמעת.',
    'הנחה שחובת הקולגיאליות היא בגדר המלצה בלבד, או שאינה חלה על בקשות שאינן מחויבות בדין הפרוצדורלי, ובכך אי-הבנת מעמדה כחובה אתית מחייבת.', '["חובת קולגיאליות", "כללי אתיקה מקצועית", "דחיית דיון", "יחסים בין עורכי דין", "עבירת משמעת"]'::jsonb, '**וריאציה 1 — בקשה לא סבירה:** האם התעלמות מבקשת דחייה לא סבירה היא עבירה אתית? ← לא בהכרח, חובת הקולגיאליות חלה על בקשות סבירות (ב"ש (מחוזי ירושלים) 5489/08 ליאורה ברקו נ'' מדינת ישראל).
**וריאציה 2 — פגיעה בלקוח:** האם היענות לבקשת דחייה שפוגעת בלקוח מותרת? ← לא, חובת הנאמנות ללקוח גוברת על חובת הקולגיאליות במקרה של ניגוד אינטרסים (כלל 2 לכללי לשכת עורכי הדין (אתיקה מקצועית)).
**וריאציה 3 — סנקציה:** מהי הסנקציה על הפרת חובת קולגיאליות? ← עבירת משמעת, העלולה לגרור עונשים שונים (השעיה, נזיפה, קנס).', 'בקשת דחייה סבירה ← חובת קולגיאליות (כלל 26) ← התעלמות = עבירה אתית.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, כלל 26", "ב\"ש (מחוזי ירושלים) 5489/08 ליאורה ברקו נ'' מדינת ישראל (31.12.2008)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, עו"ד אינה חייבת להיענות לבקשות דחייה של הצד שכנגד.', false, 'טענה זו שגויה. חובת הקולגיאליות מחייבת התייחסות לבקשות סבירות של עמיתים, גם אם אין חובה משפטית מפורשת להיענות להן.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, התעלמות מבקשת דחייה סבירה של עו"ד אחר מהווה הפרה של חובת הקולגיאליות.', true, 'כלל 26 לכללי לשכת עורכי הדין (אתיקה מקצועית) מחייב עורך דין לנהוג כלפי חברו למקצוע בדרך ארץ, כבוד וחברות. התעלמות מבקשה סבירה, במיוחד על רקע נסיבות אישיות קשות, נחשבת להפרה של חובה זו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, אלא אם כן בית המשפט הורה לה להיענות לבקשה.', false, 'חובת הקולגיאליות היא חובה אתית עצמאית, שאינה תלויה בהוראת בית המשפט. הפרתה מתרחשת גם ללא התערבות שיפוטית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אך רק אם עו"ד דנה הגישה תלונה לוועדת האתיקה.', false, 'ההפרה מתרחשת בעצם ההתעלמות מהבקשה הסבירה. הגשת התלונה רק מביאה את ההפרה לידיעת ועדת האתיקה, אך אינה תנאי לקיומה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'חובת תגובה לוועדת האתיקה',
    2, 'עו"ד רמי קיבל מכתב מוועדת האתיקה המחוזית, המבקש את תגובתו לתלונה שהוגשה נגדו. עו"ד רמי סבור שהתלונה קנטרנית וחסרת בסיס, ולכן החליט להתעלם מהמכתב ולא להגיב. האם עו"ד רמי הפר חובה אתית?', 'שאלה זו מתמקדת בחובתו המפורשת של עורך דין להגיב לפניות ועדת האתיקה, ללא קשר לדעתו על מהות התלונה, ובכך מדגישה את חשיבות שיתוף הפעולה עם מוסדות הלשכה.', 'כלל 5 לכללי לשכת עורכי הדין (סדרי הדין בבתי הדין המשמעתיים), התשע"ה-2015, קובע כי "עורך דין שמוגשת נגדו תלונה, יגיש את תגובתו בכתב לוועדת האתיקה בתוך המועד שנקבע לכך". חובה זו היא מוחלטת ואינה תלויה בטיב התלונה או בדעתו של עורך הדין עליה. אי-תגובה מהווה עבירת משמעת בפני עצמה, שכן היא פוגעת ביכולתה של ועדת האתיקה למלא את תפקידה בבירור תלונות ובשמירה על טוהר המקצוע. הפסיקה עקבית בעניין זה ומדגישה את חשיבות שיתוף הפעולה של עורכי הדין עם מוסדות הלשכה (ראו בג"ץ 208/08 יהודה זהבי, עו"ד נ'' לשכת עורכי הדין בישראל).',
    'הנחה שניתן להתעלם מתלונה אם היא נראית קנטרנית, או אי-הבנה של החובה המוחלטת להגיב לפניית ועדת האתיקה.', '["חובת תגובה", "ועדת אתיקה", "עבירת משמעת", "כללי סדרי הדין בבתי הדין המשמעתיים", "שיתוף פעולה עם הלשכה"]'::jsonb, '**וריאציה 1 — תלונה אנונימית:** האם חובה להגיב לתלונה אנונימית? ← כן, אם ועדת האתיקה החליטה לברר אותה ופנתה לעורך הדין (כלל 5 לכללי סדרי הדין בבתי הדין המשמעתיים).
**וריאציה 2 — אי-צירוף מסמכים:** האם אי-צירוף מסמכים נדרשים לתגובה מהווה הפרה? ← כן, אם המסמכים רלוונטיים ונדרשו במפורש (בג"ץ 208/08 יהודה זהבי, עו"ד נ'' לשכת עורכי הדין בישראל).
**וריאציה 3 — סנקציה על אי-תגובה:** מהי הסנקציה על אי-תגובה? ← עבירת משמעת, העלולה לגרור עונשים שונים, כולל השעיה (סעיף 61(3) לחוק לשכת עורכי הדין, התשכ"א-1961).', 'פניית ועדת אתיקה ← חובה להגיב (כלל 5) ← אי-תגובה = עבירת משמעת.',
    '["כללי לשכת עורכי הדין (סדרי הדין בבתי הדין המשמעתיים), התשע\"ה-2015, כלל 5", "בג\"ץ 208/08 יהודה זהבי, עו\"ד נ'' לשכת עורכי הדין בישראל (18.08.2008)", "חוק לשכת עורכי הדין, התשכ\"א-1961, סעיף 61(3)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'לא, אם התלונה אכן קנטרנית וחסרת בסיס, אין חובה להגיב עליה.', false, 'טענה זו שגויה. חובת התגובה לפניית ועדת האתיקה אינה תלויה בטיב התלונה או בדעתו של עורך הדין עליה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כן, חובה על עו"ד להגיב לפניית ועדת האתיקה, גם אם הוא סבור שהתלונה קנטרנית.', true, 'כלל 5 לכללי לשכת עורכי הדין (סדרי הדין בבתי הדין המשמעתיים) קובע חובה מפורשת להגיב לפניית ועדת האתיקה. אי-תגובה מהווה עבירת משמעת, ללא קשר למהות התלונה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'לא, אלא אם כן ועדת האתיקה הוציאה נגדו צו המחייב תגובה.', false, 'חובת התגובה היא חובה סטטוטורית המוטלת על עורך הדין מכוח הכללים, ואינה דורשת צו ספציפי מוועדת האתיקה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'כן, אך רק אם אי-התגובה מנעה מוועדת האתיקה להמשיך בבירור התלונה.', false, 'ההפרה היא בעצם אי-התגובה לפניית הוועדה, ללא קשר לתוצאותיה על המשך הבירור. אי-התגובה עצמה מהווה עבירת משמעת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הצדקה לאי-תגובה או התעלמות',
    3, 'עו"ד שרה קיבלה בקשה מעו"ד משה לדחיית דיון. עו"ד שרה סירבה לבקשה והתעלמה מפניותיו, בטענה כי היענות לבקשה תפגע באופן מהותי ובלתי הפיך באינטרסים של לקוחה. האם עו"ד שרה הפרה חובה אתית?', 'שאלה זו בוחנת את גבולות חובת הקולגיאליות אל מול חובת הנאמנות והמסירות ללקוח, ומתי אינטרס הלקוח מצדיק סירוב לבקשת עמית, מבלי שהדבר ייחשב להפרה אתית.', 'חובת הנאמנות והמסירות ללקוח, הקבועה בכלל 2 לכללי לשכת עורכי הדין (אתיקה מקצועית), היא חובה עליונה וגוברת על חובת הקולגיאליות (כלל 26). כאשר היענות לבקשת דחייה עלולה לפגוע באופן מהותי ובלתי הפיך באינטרסים של הלקוח, עורך הדין רשאי ואף חייב לסרב לבקשה. במקרה כזה, הסירוב אינו מהווה הפרה אתית, שכן עורך הדין פועל בהתאם לחובתו העיקרית כלפי לקוחו. עם זאת, גם במקרים כאלה, ראוי שעורך הדין יסביר את סיבת הסירוב לעמיתו, כדי לשמור על יחסים מקצועיים תקינים ככל הניתן.',
    'הנחה שחובת הקולגיאליות היא חובה מוחלטת, או אי-הבנה של היררכיית החובות האתיות במקרה של התנגשות אינטרסים.', '["חובת נאמנות ללקוח", "חובת קולגיאליות", "התנגשות אינטרסים", "כללי אתיקה מקצועית", "שיקול דעת אתי"]'::jsonb, '**וריאציה 1 — ניגוד אינטרסים:** האם חובת הקולגיאליות גוברת על ניגוד אינטרסים עם הלקוח? ← לא, חובת הנאמנות ללקוח עליונה (כלל 2 לכללי האתיקה).
**וריאציה 2 — הסבר לסירוב:** האם עורך דין המסרב לבקשת דחייה חייב להסביר את סירובו? ← כן, מטעמי קולגיאליות ושקיפות, ככל הניתן (ב"ש (מחוזי ירושלים) 5489/08 ליאורה ברקו נ'' מדינת ישראל).
**וריאציה 3 — בקשה לא סבירה:** האם בקשה לדחייה ללא סיבה מוצדקת מחייבת היענות? ← לא, חובת הקולגיאליות חלה על בקשות סבירות (ב"ש (מחוזי ירושלים) 5489/08 ליאורה ברקו נ'' מדינת ישראל).', 'חובת נאמנות ללקוח ← גוברת על קולגיאליות ← סירוב מוצדק ← אינו הפרה אתית.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, כלל 2", "כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, כלל 26", "ב\"ש (מחוזי ירושלים) 5489/08 ליאורה ברקו נ'' מדינת ישראל (31.12.2008)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, חובת הקולגיאליות גוברת על כל אינטרס אחר, גם של הלקוח.', false, 'טענה זו שגויה. חובת הנאמנות והמסירות ללקוח היא חובה עליונה, ובמקרים של התנגשות אינטרסים, היא גוברת על חובת הקולגיאליות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, חובת הנאמנות ללקוח גוברת על חובת הקולגיאליות, ופגיעה מהותית בלקוח מצדיקה סירוב לבקשה.', true, 'חובת הנאמנות והמסירות ללקוח (כלל 2 לכללי האתיקה) היא חובה עליונה. כאשר היענות לבקשת דחייה עלולה לפגוע באופן מהותי ובלתי הפיך באינטרסים של הלקוח, עורך הדין רשאי ואף חייב לסרב לבקשה, ואין בכך הפרה אתית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן קיבלה אישור מבית המשפט לסרב לבקשה.', false, 'החלטה לסרב לבקשה בשל פגיעה בלקוח היא החלטה מקצועית ואתית של עורך הדין, ואינה דורשת אישור מוקדם מבית המשפט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אך רק אם עו"ד משה לא הגיש תלונה לוועדת האתיקה.', false, 'השאלה היא האם הייתה הפרה אתית מלכתחילה. אם הסירוב מוצדק בשל חובת הנאמנות ללקוח, אין הפרה, ללא קשר להגשת תלונה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סמכויות ועדת האתיקה וביקורת שיפוטית',
    4, 'עו"ד יוסף הגיש תלונה לוועדת האתיקה המחוזית נגד עו"ד דוד. ועדת האתיקה החליטה לגנוז את התלונה. עו"ד יוסף אינו מרוצה מההחלטה ומעוניין לערער עליה. לאיזו ערכאה עליו לפנות?', 'שאלה זו עוסקת בסמכויות ועדות האתיקה של לשכת עורכי הדין ובמסלול הביקורת השיפוטית על החלטותיהן, ובפרט על החלטות גניזה של תלונות.', 'החלטות ועדות האתיקה של לשכת עורכי הדין, לרבות החלטות גניזה של תלונות, נחשבות להחלטות של רשות מינהלית. על כן, הביקורת השיפוטית עליהן מתבצעת באמצעות עתירה מינהלית לבית המשפט לעניינים מינהליים, בהתאם לסעיף 5(1) לחוק בתי משפט לעניינים מינהליים, התש"ס-2000, ובצירוף פרט 21(5) לתוספת הראשונה לחוק זה. בית המשפט העליון קבע כי קיומו של סעד חלופי זה בבית המשפט לעניינים מינהליים שולל בדרך כלל את האפשרות לפנות לבג"ץ (ראו בג"ץ 5901/15 בניטה נ'' ועד מחוז דרום של לשכת עורכי הדין, ובג"ץ 4519/93 סעדיה נ'' לשכת עורכי הדין).',
    'בלבול בין הערכאות השיפוטיות השונות (בתי דין משמעתיים, בית משפט לעניינים מינהליים, בג"ץ) והסמכות הייחודית של כל אחת מהן לדון בהליכים משמעתיים של עורכי דין.', '["ועדת אתיקה", "ביקורת שיפוטית", "בית משפט לעניינים מינהליים", "עתירה מינהלית", "סעד חלופי", "חוק לשכת עורכי הדין"]'::jsonb, '**וריאציה 1 — סמכות בג"ץ:** האם בג"ץ ידון בהחלטת גניזה של ועדת אתיקה? ← לא, קיים סעד חלופי בבית המשפט לעניינים מינהליים (בג"ץ 5901/15 בניטה נ'' ועד מחוז דרום של לשכת עורכי הדין).
**וריאציה 2 — עילות התערבות:** באילו מקרים יתערב בית המשפט בהחלטת גניזה? ← רק אם נפלו בה פגמים מינהליים קיצוניים, כגון חוסר סבירות קיצונית או שיקולים זרים (עע"מ 7640/13 רפאל שטוב נ'' ועדת האתיקה הארצית).
**וריאציה 3 — תפקיד ועדת האתיקה הארצית:** מה תפקידה של ועדת האתיקה הארצית בהקשר זה? ← היא יכולה לשמש כקובל נוסף, אך אינה ערכאת ערעור על החלטות גניזה מחוזיות (בג"ץ 6940/12 אברהים סמיר נ'' משרד המשפטים).', 'החלטת גניזה של ועדת אתיקה ← עתירה מינהלית ← לבית המשפט לעניינים מינהליים.',
    '["חוק בתי משפט לעניינים מינהליים, התש\"ס-2000, סעיף 5(1)", "חוק בתי משפט לעניינים מינהליים, התש\"ס-2000, התוספת הראשונה, פרט 21(5)", "בג\"ץ 5901/15 מוטי מאיר בניטה נ'' ועד מחוז דרום של לשכת עורכי הדין (15.12.2015)", "בג\"ץ 4519/93 שמואל סעדיה נ'' לשכת עורכי הדין בישראל - ועד מחוז תל-אביב-יפו, מט(5) 646 (25.02.1996)", "עע\"מ 7640/13 רפאל שטוב נ'' ועדת האתיקה הארצית (11.11.2014)", "בג\"ץ 6940/12 אברהים סמיר נ'' משרד המשפטים (18.10.2012)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לבית הדין המשמעתי הארצי של לשכת עורכי הדין.', false, 'בית הדין המשמעתי הארצי דן בערעורים על החלטות בתי הדין המשמעתיים המחוזיים, ולא על החלטות גניזה של ועדות האתיקה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לבית המשפט לעניינים מינהליים.', true, 'החלטות ועדות האתיקה של לשכת עורכי הדין, לרבות החלטות גניזה, נתונות לביקורת שיפוטית של בית המשפט לעניינים מינהליים, בהתאם לחוק בתי משפט לעניינים מינהליים, התש"ס-2000 (ראו בג"ץ 5901/15 בניטה נ'' ועד מחוז דרום של לשכת עורכי הדין).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לבית המשפט העליון בשבתו כבג"ץ.', false, 'בג"ץ אינו הערכאה המתאימה לדון בהשגות על החלטות ועדות האתיקה, שכן קיים סעד חלופי יעיל בבית המשפט לעניינים מינהליים (ראו בג"ץ 4919/93 סעדיה נ'' לשכת עורכי הדין).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לוועדת האתיקה הארצית של לשכת עורכי הדין.', false, 'ועדת האתיקה הארצית יכולה לשמש כקובל נוסף, אך אינה ערכאת ערעור על החלטות גניזה של ועדות אתיקה מחוזיות.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 28, '2023-S-S-Q28';
END
$$;

-- ============================================================
-- Q29 — 2023-S-S-Q29 — chapter=criminal_substantive subtopic=general_part_elements
-- classifier_note: Strict-liability offense (אחריות קפידה) — element of criminal general part
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'e4279991-526e-4c91-961c-62f75865becd'::uuid;
  v_group_id uuid := '06afce27-0f3f-4c3c-84ba-788611944da2'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '957cfe82-b3d3-4c2d-9445-f4a293be5369'::uuid;
  v_ang_1 uuid := '80cd0f3c-7f31-43cb-9c9d-e0f90c06e9e0'::uuid;
  v_ang_2 uuid := 'b390d2d9-60d5-4bbe-8283-f7f2ee942320'::uuid;
  v_ang_3 uuid := '0310e11a-c899-4d0e-a307-06fd540a4185'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q29';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 29, '2023-S-S-Q29';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part_elements' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part_elements', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q29', v_chapter_id, v_subtopic_id, 'מה מבין המשפטים הבאים נכון בנוגע לעבירה של אחריות קפידה?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 29}'::jsonb, 'השאלה עוסקת במהותן של עבירות אחריות קפידה במשפט הפלילי הישראלי, ובפרט בהיבט היסוד הנפשי. היא מדגישה כי לצורך הרשעה בעבירות אלו, התביעה פטורה מהוכחת יסוד נפשי, אך אין משמעות הדבר שהעבירה נעדרת יסוד נפשי לחלוטין, אלא שקיימת חזקה בדבר קיומו של יסוד נפשי מינימלי של רשלנות, הניתן לסתירה על ידי הנאשם.', 'עבירות אחריות קפידה מוגדרות בסעיף 22(א) לחוק העונשין, התשל"ז-1977, כעבירות שנקבע בחיקוק שאינן טעונות הוכחת מחשבה פלילית או רשלנות. עם זאת, הפטור מהוכחת היסוד הנפשי על ידי התביעה אינו מבטל את הדרישה לקיומו של יסוד נפשי בעבירה. למעשה, קמה חזקה בדבר קיומו של יסוד נפשי מינימלי של רשלנות, הניתנת לסתירה על ידי הנאשם (ע"פ 4783/09 שולשטיין נ'' רשות ההגבלים העסקיים, סעיף 22 לפסק דינה של השופטת ארבל). הנאשם יכול להיפטר מאחריות אם יוכיח שפעל ללא מחשבה פלילית וללא רשלנות ועשה כל שניתן למנוע את העבירה (סעיף 22(ב) לחוק העונשין). תכליתן של עבירות אלו היא להבטיח אכיפה יעילה ולהעלות את רמת הזהירות בתחומים מסוימים בחיי החברה (רע"פ 26/97 לקס נ'' מדינת ישראל, עמ'' 693).', 'הטעות הנפוצה היא לחשוב שעבירות אחריות קפידה הן עבירות ללא יסוד נפשי כלל, או לבלבל בין הפטור של התביעה מהוכחת היסוד הנפשי לבין היעדר קיומו של יסוד נפשי בעבירה.',
    '["אחריות קפידה", "יסוד נפשי", "יסוד עובדתי", "חוק העונשין", "סעיף 22 לחוק העונשין", "חזקת רשלנות", "הגנות"]'::jsonb, '**וריאציה 1 — יסוד נפשי:** האם עבירת אחריות קפידה דורשת יסוד נפשי? ← כן, לפחות רשלנות, אך התביעה פטורה מהוכחתו (סעיף 22(א) לחוק העונשין, ע"פ 4783/09 שולשטיין).
**וריאציה 2 — נטל הוכחה:** מי צריך להוכיח את היסוד הנפשי באחריות קפידה? ← התביעה פטורה מהוכחתו להרשעה, אך הנאשם יכול לסתור את חזקת הרשלנות (סעיף 22(ב) לחוק העונשין).
**וריאציה 3 — ענישת מאסר:** מתי ניתן להטיל מאסר בעבירת אחריות קפידה? ← רק אם הוכחה מחשבה פלילית או רשלנות (סעיף 22(ג) לחוק העונשין).', 'אחריות קפידה ← תביעה לא צריכה להוכיח יסוד נפשי ← אך יסוד נפשי קיים בחזקה ← ניתן לסתור.', '["חוק העונשין, תשל\"ז-1977, סעיפים 19, 22", "ע\"פ 4783/09 ראובן שולשטיין נ'' רשות ההגבלים העסקיים (16.09.2010)", "רע\"פ 26/97 חיים לקס נ'' מדינת ישראל (22.06.1998)", "רע\"פ 3515/12 מדינת ישראל נ'' דוד שבתאי (10.09.2013)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 15 - אחריות קפידה"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Strict-liability offense (אחריות קפידה) — element of criminal general part | source_review_note: השאלה עוסקת בדיני עונשין מהותיים (אחריות קפידה) ואינה משתלבת באופן ישיר באף אחד מתתי-הנושאים הקיימים תחת ''סדר דין פלילי''. סווגה תחת ''משמעת עורכי דין'' כהצבת מקום זמנית, אך יש לשקול הוספת תת-נושא מתאים יותר לדיני עונשין מהותיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא נדרש קיומו של יסוד נפשי כלשהו.', false, 'טענה זו אינה מדויקת. אף שהתביעה פטורה מהוכחת היסוד הנפשי, עבירות אחריות קפידה אינן נעדרות יסוד נפשי לחלוטין, אלא מניחות את קיומו של יסוד נפשי מינימלי של רשלנות, הניתן לסתירה על ידי הנאשם.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'נדרש קיומו של יסוד נפשי של מחשבה פלילית לכל הפחות.', false, 'טענה זו שגויה. עבירות אחריות קפידה אינן דורשות הוכחת מחשבה פלילית או רשלנות לצורך הרשעה, אלא רק לצורך הטלת עונש מאסר.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'התביעה לא נדרשת להוכיח קיומו של יסוד נפשי כלשהו.', true, 'לצורך הרשעה בעבירת אחריות קפידה, התביעה נדרשת להוכיח את היסוד העובדתי בלבד, והיא פטורה מהוכחת היסוד הנפשי, שכן קמה חזקה בדבר קיומו של יסוד נפשי מינימלי של רשלנות.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'כדי להיות פטור מאחריות לעבירה על הנאשם להוכיח שנקט אמצעים סבירים כדי להימנע מביצועה.', false, 'טענה זו חלקית ואינה מדויקת. כדי להיות פטור מאחריות, על הנאשם להוכיח שני תנאים מצטברים: שפעל ללא מחשבה פלילית וללא רשלנות, וכן שעשה כל שניתן למנוע את העבירה, כאשר הסטנדרט של ''כל שניתן'' גבוה יותר מ''אמצעים סבירים''.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'סיווג עבירות אחריות קפידה',
    1, 'חוק חדש נחקק ובו עבירה פלילית שאינה מציינת במפורש את היסוד הנפשי הנדרש. האם עבירה זו תיחשב לעבירת אחריות קפידה?', 'שאלה זו עוסקת בקריטריונים לסיווג עבירה כעבירת אחריות קפידה, תוך הבחנה בין עבירות שנחקקו לפני תיקון 39 לחוק העונשין לבין אלו שנחקקו לאחריו, כפי שנקבע בסעיף 22(א) לחוק העונשין.', 'סעיף 22(א) לחוק העונשין, התשל"ז-1977, קובע כי עבירה תיחשב לאחריות קפידה אם נקבע בחיקוק שהיא אינה טעונה הוכחת מחשבה פלילית או רשלנות. הוראה זו חלה על עבירות שנחקקו לאחר תיקון 39 לחוק העונשין (1994). לעומת זאת, לגבי עבירות שנחקקו טרם כניסתו לתוקף של תיקון זה, ניתן להכיר בהן כעבירות אחריות קפידה גם אם נקבע כך ''בדין'', לרבות בהלכה פסוקה (ראו רע"פ 4184/02 שאול לוי נ'' מדינת ישראל, ורע"פ 2929/04 מדינת ישראל נ'' רפאל אוחנה). לפיכך, עבירה חדשה שאינה מציינת יסוד נפשי מפורש, לא תיחשב אוטומטית לאחריות קפידה אלא אם כן נקבע כך במפורש בחיקוק.',
    'הבלבול בין הכללים לסיווג עבירות אחריות קפידה לפני ואחרי תיקון 39 לחוק העונשין, והנחה שניתן להכיר בעבירה חדשה כאחריות קפידה מכוח הפסיקה.', '["אחריות קפידה", "סעיף 22(א) לחוק העונשין", "תיקון 39 לחוק העונשין", "סיווג עבירות", "יסוד נפשי", "הלכה פסוקה"]'::jsonb, '**וריאציה 1 — עבירה חדשה:** איך מסווגים עבירה חדשה כעבירת אחריות קפידה? ← רק אם נקבע במפורש בחיקוק (סעיף 22(א) לחוק העונשין).
**וריאציה 2 — עבירה ישנה:** איך מסווגים עבירה שנחקקה לפני תיקון 39 כעבירת אחריות קפידה? ← אם נקבע בדין, לרבות בהלכה פסוקה, שאינה טעונה הוכחת יסוד נפשי (סעיף 22(א) לחוק העונשין, רע"פ 2929/04 אוחנה).
**וריאציה 3 — עבירה שותקת:** מהו הכלל לעבירה שאינה מציינת יסוד נפשי? ← הכלל הוא מחשבה פלילית, אלא אם כן חל חריג של רשלנות או אחריות קפידה (סעיף 19 לחוק העונשין).', 'סיווג אחריות קפידה ← חדש: חיקוק מפורש ← ישן: חיקוק או הלכה פסוקה.',
    '["חוק העונשין, תשל\"ז-1977, סעיפים 19, 22(א)", "רע\"פ 4184/02 שאול לוי נ'' מדינת ישראל (30.06.2002)", "רע\"פ 2929/04 מדינת ישראל נ'' רפאל אוחנה (25.06.2007)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 15 - אחריות קפידה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, כל עבירה שאינה מציינת יסוד נפשי מפורש היא עבירת אחריות קפידה.', false, 'טענה זו שגויה. הכלל הוא שעבירה שותקת ליסוד הנפשי דורשת מחשבה פלילית, אלא אם כן נקבע במפורש שהיא אחריות קפידה או רשלנות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, אלא אם כן נקבע בחיקוק במפורש שהעבירה אינה טעונה הוכחת מחשבה פלילית או רשלנות.', true, 'סעיף 22(א) לחוק העונשין קובע כי עבירה תיחשב לאחריות קפידה אם נקבע בחיקוק שהיא אינה טעונה הוכחת מחשבה פלילית או רשלנות. זאת, בניגוד לעבירות שנחקקו לפני תיקון 39, לגביהן ניתן היה להכיר באחריות קפידה גם בהלכה פסוקה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אם הפסיקה תכיר בה כעבירת אחריות קפידה, בדומה לעבירות דומות שנחקקו לפני תיקון 39.', false, 'האפשרות להכיר בעבירה כאחריות קפידה מכוח הלכה פסוקה רלוונטית לעבירות שנחקקו לפני תיקון 39 לחוק העונשין. לגבי עבירות חדשות, נדרשת קביעה מפורשת בחיקוק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן מדובר בעבירה בתחום רגולטורי שנועדה להבטיח תקנת הציבור.', false, 'אף שעבירות אחריות קפידה רבות הן בתחומים רגולטוריים, זהו אינו תנאי מספיק לסיווג עבירה חדשה כאחריות קפידה. נדרשת קביעה מפורשת בחיקוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הטלת מאסר בעבירת אחריות קפידה',
    2, 'ראובן הורשע בעבירת אחריות קפידה. האם ניתן להטיל עליו עונש מאסר?', 'שאלה זו עוסקת בהבחנה בין שלב ההרשעה לשלב הענישה בעבירות אחריות קפידה, ובפרט בתנאים להטלת עונש מאסר, כפי שנקבעו בסעיף 22(ג) לחוק העונשין.', 'סעיף 22(ג) לחוק העונשין, התשל"ז-1977, קובע כי ''לעניין אחריות לפי סעיף זה, לא יידון אדם למאסר, אלא אם כן הוכחה מחשבה פלילית או רשלנות''. משמעות הדבר היא שלצורך הרשעה בעבירת אחריות קפידה, די בהוכחת היסוד העובדתי, והתביעה פטורה מהוכחת היסוד הנפשי. אולם, אם התביעה מבקשת להטיל על הנאשם עונש מאסר, עליה להוכיח באופן פוזיטיבי קיומו של יסוד נפשי של מחשבה פלילית או רשלנות. כל עוד התביעה מסתמכת על חזקת הרשלנות בלבד, לא ניתן לגזור עונש מאסר (ע"פ 4783/09 שולשטיין נ'' רשות ההגבלים העסקיים, סעיפים 22, 25 לפסק דינה של השופטת ארבל).',
    'הבלבול בין הדרישות להרשעה לבין הדרישות לענישה בעבירות אחריות קפידה, והנחה שדי בהרשעה כדי להטיל כל עונש, כולל מאסר.', '["אחריות קפידה", "סעיף 22(ג) לחוק העונשין", "עונש מאסר", "הוכחת יסוד נפשי", "מחשבה פלילית", "רשלנות"]'::jsonb, '**וריאציה 1 — הרשעה מול ענישה:** מה ההבדל בין הרשעה לענישה באחריות קפידה? ← להרשעה די ביסוד עובדתי; לענישת מאסר נדרשת הוכחת יסוד נפשי (סעיף 22(ג) לחוק העונשין, ע"פ 4783/09 שולשטיין).
**וריאציה 2 — חזקת רשלנות:** האם חזקת הרשלנות מספיקה למאסר? ← לא, היא מספיקה להרשעה, אך לא למאסר (ע"פ 4783/09 שולשטיין).
**וריאציה 3 — תכלית סעיף 22(ג):** מהי תכלית סעיף 22(ג)? ← למנוע שלילת חירות ללא הוכחת אשם (ע"פ 4783/09 שולשטיין, סעיף 24).', 'מאסר באחריות קפידה ← רק אם הוכח יסוד נפשי ← מחשבה פלילית או רשלנות.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 22(ג)", "ע\"פ 4783/09 ראובן שולשטיין נ'' רשות ההגבלים העסקיים (16.09.2010)", "רע\"פ 3515/12 מדינת ישראל נ'' דוד שבתאי (10.09.2013)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'לא, עבירות אחריות קפידה אינן מאפשרות הטלת עונש מאסר כלל.', false, 'טענה זו שגויה. סעיף 22(ג) לחוק העונשין קובע מתי ניתן להטיל מאסר בעבירת אחריות קפידה, ולא שולל זאת לחלוטין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כן, אם התביעה הוכיחה מחשבה פלילית או רשלנות.', true, 'סעיף 22(ג) לחוק העונשין קובע במפורש כי לא יידון אדם למאסר בעבירת אחריות קפידה, אלא אם כן הוכחה מחשבה פלילית או רשלנות. כלומר, לצורך הטלת מאסר, נדרשת הוכחה פוזיטיבית של יסוד נפשי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, אם הנאשם לא הצליח להוכיח שפעל ללא מחשבה פלילית וללא רשלנות.', false, 'אי-הוכחת הגנה על ידי הנאשם מובילה להרשעה, אך לא בהכרח מאפשרת הטלת מאסר. לצורך מאסר, התביעה צריכה להוכיח יסוד נפשי באופן פוזיטיבי, ולא רק שהנאשם לא סתר את החזקה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, אלא אם כן העבירה היא מסוג פשע.', false, 'סיווג העבירה כפשע אינו התנאי היחיד להטלת מאסר בעבירת אחריות קפידה. התנאי המכריע הוא הוכחת יסוד נפשי של מחשבה פלילית או רשלנות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הגנת טעות במצב דברים באחריות קפידה',
    3, 'יוסי הורשע בעבירת אחריות קפידה לאחר שביצע מעשה מסוים מתוך טעות במצב דברים. האם טעות זו יכולה לשמש לו הגנה מפני אחריות פלילית?', 'שאלה זו בוחנת את תחולתה של הגנת טעות במצב דברים (סעיף 34יח לחוק העונשין) על עבירות אחריות קפידה, ואת התנאים המיוחדים הנדרשים לשם כך, כפי שנקבעו בסעיף 22(ב) לחוק העונשין.', 'סעיף 34יח(ב) לחוק העונשין, התשל"ז-1977, קובע כי סעיף קטן (א) (העוסק בטעות במצב דברים) יחול גם על עבירה של אחריות קפידה, ''בכפוף לאמור בסעיף 22(ב)''. סעיף 22(ב) לחוק העונשין קובע כי אדם לא יישא באחריות קפידה אם נהג ללא מחשבה פלילית וללא רשלנות ועשה כל שניתן למנוע את העבירה. כלומר, כדי שטעות במצב דברים תשמש הגנה בעבירת אחריות קפידה, על הנאשם להוכיח את שני התנאים המצטברים שבסעיף 22(ב) (יורם רבין, יניב ואקי, דיני עונשין - כרך א, פרק 15, עמ'' 21).',
    'הנחה שטעות במצב דברים אינה רלוונטית כלל לעבירות אחריות קפידה, או אי-הבנה של התנאים המצטברים הנדרשים להחלתה.', '["טעות במצב דברים", "אחריות קפידה", "סעיף 34יח לחוק העונשין", "סעיף 22(ב) לחוק העונשין", "הגנות", "נטל הוכחה"]'::jsonb, '**וריאציה 1 — תנאי ההגנה:** מהם התנאים לשימוש בטעות במצב דברים באחריות קפידה? ← פעל ללא מחשבה פלילית וללא רשלנות, ועשה כל שניתן למנוע את העבירה (סעיפים 34יח(ב) ו-22(ב) לחוק העונשין).
**וריאציה 2 — נטל ההוכחה:** מי נושא בנטל ההוכחה להגנה זו? ← הנאשם (סעיף 22(ב) לחוק העונשין).
**וריאציה 3 — סטנדרט ''כל שניתן'':** מה המשמעות של ''כל שניתן למנוע את העבירה''? ← סטנדרט גבוה יותר מאמצעים סבירים (ע"פ 4783/09 שולשטיין, סעיף 23).', 'טעות במצב דברים באחריות קפידה ← הגנה אם הוכח היעדר אשם + נקיטת כל האמצעים.',
    '["חוק העונשין, תשל\"ז-1977, סעיפים 22(ב), 34יח(ב)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 15 - אחריות קפידה", "ע\"פ 4783/09 ראובן שולשטיין נ'' רשות ההגבלים העסקיים (16.09.2010)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, טעות במצב דברים אינה רלוונטית בעבירות אחריות קפידה, שאינן דורשות יסוד נפשי.', false, 'טענה זו שגויה. סעיף 34יח(ב) לחוק העונשין קובע במפורש שטעות במצב דברים יכולה לחול גם על עבירות אחריות קפידה, בכפוף לתנאים מסוימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, אם יוכיח שפעל ללא מחשבה פלילית וללא רשלנות ועשה כל שניתן למנוע את העבירה.', true, 'סעיף 34יח(ב) לחוק העונשין קובע כי טעות במצב דברים תחול על עבירת אחריות קפידה בכפוף לאמור בסעיף 22(ב) לחוק. סעיף 22(ב) מאפשר לנאשם להיפטר מאחריות אם יוכיח שפעל ללא מחשבה פלילית וללא רשלנות ועשה כל שניתן למנוע את העבירה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם הטעות הייתה סבירה, בדומה לעבירות רשלנות.', false, 'הדרישה לטעות סבירה רלוונטית לעבירות רשלנות. בעבירות אחריות קפידה, בנוסף לכך שפעל ללא רשלנות, נדרש גם להוכיח שעשה כל שניתן למנוע את העבירה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן הטעות נבעה מכוח עליון.', false, 'כוח עליון יכול להיות רלוונטי להגנת ''היעדר שליטה'', אך אינו תנאי לשימוש בהגנת טעות במצב דברים בעבירות אחריות קפידה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'אחריות נושאי משרה בעבירות קפידה',
    4, 'חברת ''אלפא בע"מ'' הורשעה בעבירת אחריות קפידה לפי חוק הגנת הסביבה. מנהל החברה, מר כהן, הואשם גם הוא באותה עבירה מכוח תפקידו. מהם התנאים לפיהם מר כהן יכול להיפטר מאחריות פלילית?', 'שאלה זו עוסקת באחריות הפלילית של נושאי משרה בתאגיד בגין עבירות אחריות קפידה שבוצעו על ידי התאגיד, ובפרט בהגנות העומדות לרשותם, המשלבות את היעדר הידיעה עם נקיטת אמצעי מניעה סבירים.', 'סעיפים רבים בחקיקה, כגון סעיף 48 לחוק התחרות הכלכלית (לשעבר חוק ההגבלים העסקיים) או סעיף 222 לפקודת הבטיחות בעבודה, קובעים אחריות פלילית לנושאי משרה בתאגיד בגין עבירות שבוצעו על ידי התאגיד. סעיפים אלו כוללים לרוב מנגנון הגנה ספציפי, המאפשר לנושא המשרה להיפטר מאחריות אם יוכיח שהעבירה נעברה שלא בידיעתו וכי נקט כל אמצעים סבירים להבטחת שמירת החוק (ע"פ 4783/09 שולשטיין נ'' רשות ההגבלים העסקיים, סעיף 48 לחוק ההגבלים העסקיים המצוטט בפסק הדין). מנגנון זה נועד לתמרץ נושאי משרה לנקוט אמצעי זהירות ולפקח על פעילות התאגיד, תוך איזון עם עקרון האשם.',
    'הנחה שאחריות נושאי משרה היא מוחלטת ואינה ניתנת לסתירה, או אי-הבנה של התנאים המצטברים הנדרשים להגנה זו.', '["אחריות נושאי משרה", "אחריות קפידה", "הגנות", "חוק התחרות הכלכלית", "פקודת הבטיחות בעבודה", "נטל הוכחה"]'::jsonb, '**וריאציה 1 — תנאי ההגנה לנושא משרה:** מהם התנאים להגנה של נושא משרה בעבירת אחריות קפידה? ← העבירה נעברה שלא בידיעתו + נקט כל אמצעים סבירים למניעתה (סעיף 48 לחוק התחרות הכלכלית, ע"פ 4783/09 שולשטיין).
**וריאציה 2 — נטל ההוכחה:** מי נושא בנטל ההוכחה להגנה זו? ← נושא המשרה (סעיף 48 לחוק התחרות הכלכלית, ע"פ 4783/09 שולשטיין).
**וריאציה 3 — תכלית האחריות:** מהי תכלית הטלת אחריות על נושאי משרה בעבירות קפידה? ← להגביר פיקוח, השגחה ותמרוץ נקיטת אמצעי זהירות (ע"פ 4783/09 שולשטיין, סעיף 2).', 'אחריות נושא משרה ← אחריות קפידה ← הגנה: לא ידע + נקט אמצעים סבירים.',
    '["חוק התחרות הכלכלית, תשמ\"ח-1988, סעיף 48", "פקודת הבטיחות בעבודה [נוסח חדש], תש\"ל-1970, סעיף 222", "ע\"פ 4783/09 ראובן שולשטיין נ'' רשות ההגבלים העסקיים (16.09.2010)", "רע\"פ 2525545 חברת נמלי ישראל- פיתוח ונכסים בע\"מ נ'' מדינת ישראל - המשרד להגנת הסביבה (23.10.2012)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'מר כהן ייפטר מאחריות אם יוכיח שהעבירה נעברה שלא בידיעתו.', false, 'טענה זו חלקית. בנוסף לכך שהעבירה נעברה שלא בידיעתו, על נושא המשרה להוכיח גם שנקט את כל האמצעים הסבירים למניעת העבירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'מר כהן ייפטר מאחריות אם יוכיח שהעבירה נעברה שלא בידיעתו וכי נקט כל אמצעים סבירים להבטחת שמירת החוק.', true, 'סעיפים רבים בחקיקה (כגון סעיף 48 לחוק התחרות הכלכלית, או סעיף 222 לפקודת הבטיחות בעבודה) קובעים אחריות לנושאי משרה בעבירות תאגיד, ומאפשרים להם להיפטר מאחריות אם יוכיחו שהעבירה נעברה שלא בידיעתם וכי נקטו כל אמצעים סבירים למניעתה. זהו מנגנון הגנה ספציפי לנושאי משרה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'מר כהן ייפטר מאחריות אם יוכיח שהעבירה נעברה ללא מחשבה פלילית וללא רשלנות.', false, 'אף שזהו חלק מהגנת סעיף 22(ב) לחוק העונשין, הוראות ספציפיות לנושאי משרה דורשות גם נקיטת אמצעים סבירים למניעת העבירה, ולעיתים גם היעדר ידיעה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'מר כהן אינו יכול להיפטר מאחריות, שכן אחריות נושאי משרה בעבירות קפידה היא מוחלטת.', false, 'טענה זו שגויה. גם בעבירות אחריות קפידה של נושאי משרה קיימות הגנות המאפשרות להם להיפטר מאחריות, בכפוף לעמידה בתנאים מסוימים.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 29, '2023-S-S-Q29';
END
$$;

-- ============================================================
-- Q30 — 2023-S-S-Q30 — chapter=ethics subtopic=disciplinary_law
-- classifier_note: Lawyer's ethics rules re anti-money-laundering reporting
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'd5c05227-8c2d-43fc-9cdc-c381e02b50f0'::uuid;
  v_group_id uuid := '22fcda97-1e2e-4f03-b915-1edd54e84ee8'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '890c7196-505e-4379-ab20-2168f384dd9f'::uuid;
  v_ang_1 uuid := 'b8b2b3cf-0105-491c-81c9-286fa658a6ae'::uuid;
  v_ang_2 uuid := '64c973f6-6bc6-402a-bbf5-8f0376f6dcaa'::uuid;
  v_ang_3 uuid := '658ec761-c1c7-4fd4-9797-170d03a39676'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q30';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 30, '2023-S-S-Q30';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'ethics';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'ethics';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'disciplinary_law' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'disciplinary_law', 'ethics';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q30', v_chapter_id, v_subtopic_id, 'מה מהאמור להלן לא ייחשב להפרה של כללי האתיקה של לשכת עורכי הדין במקרה של חשד להלבנת הון?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 30}'::jsonb, 'השאלה עוסקת בחובות האתיות של עורכי דין בהקשר של מניעת הלבנת הון, ובפרט בהגדרת ''פעולה מחייבת'' לפי כללי לשכת עורכי הדין (אתיקה מקצועית). היא מדגישה כי עורך דין אינו רשאי לבצע פעולות מסוימות בעלות אופי עסקי-פיננסי אם הוא מעריך שקיים סיכון גבוה להלבנת הון, אך לא כל פעולה משפטית נכללת בהגדרה זו.', 'כלל 44ב לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986, קובע כי עורך דין לא יבצע ''פעולה מחייבת'' שהתבקשה בשביל לקוח אם הוא מעריך, לפי סעיף 2(ג) לצו, שרמת הסיכון להלבנת הון או מימון טרור גבוהה. כלל 44א מגדיר ''פעולה מחייבת'' כרשימה סגורה של פעולות בעלות אופי עסקי-פיננסי, הכוללת: קנייה ומכירה של נכסי דלא-ניידי או של עסקים; ניהול נכסי הלקוח; גיוס כספים לצורך הקמה או ניהול של תאגידים; הקמה או ניהול של נאמנות; והקמה או ניהול של תאגידים. עריכת הסכמי עבודה אינה נכללת ברשימה זו, ולכן אינה נחשבת ל''פעולה מחייבת'' לעניין זה. לפיכך, ביצוע פעולה זו, גם במקרה של חשד להלבנת הון, לא ייחשב להפרה של כללי האתיקה הספציפיים למניעת הלבנת הון.', 'הטעות הנפוצה היא להרחיב את הגדרת ''פעולה מחייבת'' לכל פעולה משפטית הקשורה לענייני כספים או עסקים של הלקוח, ובכך להטיל על עורכי דין חובות רחבות יותר מאלו שנקבעו בחוק ובכללי האתיקה.',
    '["אתיקה מקצועית", "הלבנת הון", "פעולה מחייבת", "כללי לשכת עורכי הדין", "חוק איסור הלבנת הון", "סיכון להלבנת הון"]'::jsonb, '**וריאציה 1 — הגדרת ''פעולה מחייבת'':** מהי ''פעולה מחייבת'' לפי כללי האתיקה? ← רשימה סגורה של פעולות עסקיות-פיננסיות (כלל 44א לכללי האתיקה).
**וריאציה 2 — איסור ביצוע:** מתי אסור לבצע ''פעולה מחייבת''? ← אם עורך הדין מעריך שרמת הסיכון להלבנת הון גבוהה (כלל 44ב לכללי האתיקה).
**וריאציה 3 — פעולות שאינן אסורות:** אילו פעולות אינן נכללות ב''פעולה מחייבת''? ← פעולות משפטיות שאינן בעלות אופי עסקי-פיננסי מובהק, כגון עריכת הסכמי עבודה.', '''פעולה מחייבת'' ← רשימה סגורה של פעולות עסקיות-פיננסיות ← עריכת הסכמי עבודה אינה כלולה ← ולכן אינה הפרה אתית בהקשר זה.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, סעיפים 44א, 44ב", "רע\"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל (09.12.2015)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''disciplinary_law'' | classifier_note: Lawyer''s ethics rules re anti-money-laundering reporting | source_review_note: השאלה עוסקת באתיקה מקצועית של עורכי דין בהקשר של איסור הלבנת הון, תחום שאינו משתלב באופן ישיר באף אחד מתתי-הנושאים הקיימים תחת ''סדר דין פלילי''. סווגה תחת ''משמעת עורכי דין'' כהצבת מקום זמנית, אך יש לשקול הוספת תת-נושא מתאים יותר לאתיקה מקצועית.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ניהול הטיפול בבתי המלון בבעלות הלקוח.', false, 'טענה זו שגויה. ניהול נכסי הלקוח, ובכלל זה ניהול כספים, ניירות ערך או נכסים אחרים, נחשב ל''פעולה מחייבת'' לפי כלל 44א(2) לכללי האתיקה, ואסור לבצעה אם קיים חשש גבוה להלבנת הון.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ניהול מכירת אחד מבתי המלון בבעלות הלקוח.', false, 'טענה זו שגויה. קנייה ומכירה של נכסי דלא-ניידי או של עסקים נחשבת ל''פעולה מחייבת'' לפי כלל 44א(1) לכללי האתיקה, ואסור לבצעה אם קיים חשש גבוה להלבנת הון.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עריכת הסכמי עבודה למנהלי המלון בבעלות הלקוח.', true, 'עריכת הסכמי עבודה אינה נכללת בהגדרת ''פעולה מחייבת'' המפורטת בכלל 44א לכללי לשכת עורכי הדין (אתיקה מקצועית), ולכן ביצועה אינו מהווה הפרה של כלל 44ב, גם אם קיים חשש להלבנת הון.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'הקמת קרן נאמנות לבתי המלון בבעלות הלקוח.', false, 'טענה זו שגויה. הקמה או ניהול של נאמנות נחשבת ל''פעולה מחייבת'' לפי כלל 44א(4) לכללי האתיקה, ואסור לבצעה אם קיים חשש גבוה להלבנת הון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חשיפת שכר טרחה בחקירת הלבנת הון',
    1, 'עורך דין נדרש על ידי רשויות החקירה לחשוף את סכום שכר הטרחה שקיבל מלקוחו, החשוד בעבירות הלבנת הון, ואת חשבוניות המס שהוציא. עורך הדין טוען לחסיון עורך דין-לקוח. מה הדין?', 'שאלה זו עוסקת בהיקף תחולתו של חסיון עורך דין-לקוח על רכיב שכר הטרחה וחשבוניות המס, במיוחד בהקשר של חקירות פליליות ועבירות הלבנת הון. היא בוחנת את עמדת בית המשפט העליון בנושא זה.', 'בית המשפט העליון ברע"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל קבע כי ככלל, סכום שכר הטרחה ששולם לעורך הדין או חשבוניות המס שנמסרו על ידו ללקוחו בגין תשלום שכר הטרחה, אינם חוסים תחת חסיון עורך דין-לקוח. זאת, משום שפרטים אלו אינם מהווים חלק מהתקשורת בין עורך הדין ללקוחו, עליה מבקש החסיון להגן, ואינם בעלי ''קשר ענייני'' לשירות המקצועי. רק במקרים חריגים ביותר, מקום בו עורך הדין ישכנע כי שכר הטרחה או פרטי חשבונית המס, משקפים, כשלעצמם, את פרטי התקשורת המקצועית בינו לבין לקוחו ועלולים לחשוף מידע הנוגע לתוכן השירות המקצועי, ניתן יהיה לחרוג מהכלל ולהורות על חיסיון המידע או המסמך.',
    'הנחה שכל מידע המצוי בידי עורך דין לגבי לקוחו חסוי, כולל פרטים פיננסיים כמו שכר טרחה, ובכך אי-הבנה של גבולות החסיון.', '["חסיון עורך דין-לקוח", "שכר טרחה", "חשבוניות מס", "חקירה פלילית", "הלבנת הון", "קשר ענייני לשירות המקצועי"]'::jsonb, '**וריאציה 1 — כלל אצבע:** האם שכר טרחה חסוי? ← ככלל לא, אלא אם כן הוא חושף תוכן שירות מקצועי (רע"פ 751/15 אברג''יל).
**וריאציה 2 — תכלית החסיון:** מהי תכלית החסיון? ← לאפשר ללקוח לשוחח בחופשיות עם עורך הדין, לא להגן על פרטיות פיננסית (רע"פ 751/15 אברג''יל, פסקה 31).
**וריאציה 3 — זהות הלקוח:** האם זהות הלקוח חסויה? ← ככלל לא, בדומה לשכר הטרחה (רע"פ 751/15 אברג''יל, פסקה 8).', 'שכר טרחה וחשבוניות ← ככלל לא חסויים ← אלא אם חושפים תוכן שירות מקצועי.',
    '["רע\"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל (09.12.2015)", "פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 48(א)", "חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 90"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'סכום שכר הטרחה וחשבוניות המס חוסים תחת חסיון עורך דין-לקוח באופן מוחלט.', false, 'טענה זו שגויה. הפסיקה קבעה כי ככלל, סכום שכר הטרחה וחשבוניות המס אינם חוסים תחת חסיון עורך דין-לקוח.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'ככלל, סכום שכר הטרחה וחשבוניות המס אינם חסויים, אלא אם כן עורך הדין יוכיח כי הם משקפים את תוכן השירות המקצועי.', true, 'בית המשפט העליון קבע כי סכום שכר הטרחה וחשבוניות המס אינם מהווים חלק מהתקשורת בין עורך הדין ללקוחו, ולכן אינם חסויים, למעט במקרים חריגים ביותר בהם עורך הדין ישכנע כי הם משקפים את פרטי התקשורת המקצועית ועלולים לחשוף מידע הנוגע לתוכן השירות המקצועי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'סכום שכר הטרחה חסוי, אך חשבוניות המס אינן חסויות.', false, 'טענה זו שגויה. הפסיקה מתייחסת לסכום שכר הטרחה ולחשבוניות המס באופן דומה לעניין תחולת החסיון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'החסיון חל רק אם הלקוח אינו חשוד בעבירות הלבנת הון.', false, 'טענה זו שגויה. שאלת תחולת החסיון אינה תלויה בשאלה אם הלקוח חשוד בעבירות הלבנת הון, אלא בטיב המידע המבוקש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגדרת ''פעולה מחייבת'' למניעת הלבנת הון',
    2, 'מהי ''פעולה מחייבת'' לעניין חובות עורך דין למניעת הלבנת הון, כפי שמוגדרת בכללי האתיקה?', 'שאלה זו מתמקדת בהגדרת המונח ''פעולה מחייבת'' בהקשר של חובות עורכי דין למניעת הלבנת הון, כפי שמופיעה בכללי לשכת עורכי הדין (אתיקה מקצועית). הבנת הגדרה זו חיונית ליישום נכון של כללי האתיקה הרלוונטיים.', 'כלל 44א לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986, מגדיר ''פעולה מחייבת'' כרשימה סגורה של פעולות בעלות אופי עסקי-פיננסי. רשימה זו כוללת: (1) קנייה ומכירה של נכסי דלא-ניידי או של עסקים; (2) ניהול נכסי הלקוח, ובכלל זה ניהול כספים, ניירות ערך או נכסים אחרים, לרבות ניהול חשבונות של לקוח במוסד פיננסי; (3) גיוס כספים לצורך הקמה או ניהול של תאגידים; (4) הקמה או ניהול של נאמנות; (5) הקמה או ניהול של תאגידים. רק פעולות אלו, ולא כל פעולה משפטית אחרת, נכנסות לגדר ''פעולה מחייבת'' לעניין חובות עורך הדין למניעת הלבנת הון.',
    'הכללה שגויה של פעולות משפטיות רגילות תחת ההגדרה של ''פעולה מחייבת'', ובכך הרחבת יתר של חובות עורך הדין למניעת הלבנת הון מעבר לכוונת המחוקק והמחוקק המשנה.', '["פעולה מחייבת", "הלבנת הון", "כללי אתיקה מקצועית", "חוק איסור הלבנת הון", "שירות עסקי"]'::jsonb, '**וריאציה 1 — רשימה סגורה:** האם הגדרת ''פעולה מחייבת'' היא רשימה פתוחה? ← לא, זו רשימה סגורה של פעולות עסקיות-פיננסיות (כלל 44א לכללי האתיקה).
**וריאציה 2 — דוגמאות:** מהן דוגמאות ל''פעולה מחייבת''? ← קנייה/מכירה של נדל"ן, ניהול נכסים, הקמת נאמנות (כלל 44א לכללי האתיקה).
**וריאציה 3 — ייצוג פלילי:** האם ייצוג בהליך פלילי הוא ''פעולה מחייבת''? ← לא, ייצוג פלילי אינו נכלל בהגדרת ''שירות עסקי'' או ''פעולה מחייבת'' (רע"פ 751/15 אברג''יל, פסקה 9).', '''פעולה מחייבת'' ← רשימה סגורה ← פעולות עסקיות-פיננסיות ← לא כל פעולה משפטית.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, סעיף 44א", "רע\"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל (09.12.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כל פעולה משפטית שעורך דין מבצע עבור לקוחו.', false, 'טענה זו שגויה. ההגדרה צרה יותר ומתייחסת לפעולות בעלות אופי עסקי-פיננסי ספציפי, ולא לכל פעולה משפטית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'פעולות הכוללות ייצוג בבתי משפט או עריכת מסמכים משפטיים.', false, 'טענה זו שגויה. ייצוג בבתי משפט או עריכת מסמכים משפטיים אינם נכללים בהגדרת ''פעולה מחייבת'' לעניין זה, אלא אם כן הם חלק מפעולה עסקית-פיננסית מוגדרת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'פעולות בעלות אופי עסקי-פיננסי, כגון קנייה ומכירה של נכסי דלא-ניידי או ניהול נכסי לקוח.', true, 'כלל 44א לכללי לשכת עורכי הדין (אתיקה מקצועית) מגדיר ''פעולה מחייבת'' כרשימה סגורה של פעולות בעלות אופי עסקי-פיננסי, הכוללת קנייה ומכירה של נכסי דלא-ניידי או עסקים, ניהול נכסי לקוח, גיוס כספים להקמה או ניהול תאגידים, הקמה או ניהול נאמנות או תאגידים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'כל פעולה שבה מעורבים סכומי כסף גבוהים.', false, 'טענה זו שגויה. הגדרת ''פעולה מחייבת'' אינה תלויה בסכום הכסף המעורב, אלא בסוג הפעולה ובאופייה העסקי-פיננסי המפורט בכלל 44א.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חובת דיווח על חשד להלבנת הון',
    3, 'עורך דין מעריך שקיימת רמת סיכון גבוהה להלבנת הון בפעולה מסוימת שהלקוח מבקש ממנו לבצע. האם עורך הדין חייב לדווח על כך לרשויות?', 'שאלה זו בוחנת את היקף חובותיו של עורך דין בהקשר של מניעת הלבנת הון, ובפרט את ההבחנה בין איסור ביצוע ''פעולה מחייבת'' לבין חובת דיווח אקטיבית לרשויות, תוך התייחסות לחסיון עורך דין-לקוח.', 'סעיף 8ב לחוק איסור הלבנת הון, התש"ס-2000, וצו איסור הלבנת הון שהוצא מכוחו, מטילים על עורכי דין המעניקים ''שירות עסקי'' חובות זיהוי והכרה של הלקוח. עם זאת, סעיף 8ב(ו) לחוק קובע כי אין בהוראותיו כדי לפגוע בחסיון לפי סעיף 48 לפקודת הראיות. המחוקק נמנע מלהטיל על עורכי דין חובת דיווח אקטיבית על פעולות של הלקוח שיש בהן סיכון להלבנת הון, והסתפק באיסור על עורך הדין לבצע ''פעולה מחייבת'' אם הוא מעריך שרמת הסיכון גבוהה (כלל 44ב לכללי לשכת עורכי הדין (אתיקה מקצועית)). זאת, מתוך חשש לפגיעה בחסיון עורך דין-לקוח (רע"פ 751/15 אברג''יל, פסקה 41).',
    'הנחה שחובות עורכי דין למניעת הלבנת הון זהות לחובות המוטלות על מוסדות פיננסיים, ובכך אי-הבנה של ההגנה הייחודית הניתנת לחסיון עורך דין-לקוח.', '["הלבנת הון", "חובת דיווח", "פעולה מחייבת", "חסיון עורך דין-לקוח", "כללי אתיקה מקצועית", "חוק איסור הלבנת הון"]'::jsonb, '**וריאציה 1 — חובת דיווח:** האם עורך דין חייב לדווח על חשד להלבנת הון? ← לא, אין חובת דיווח אקטיבית (כלל 44ב לכללי האתיקה, רע"פ 751/15 אברג''יל).
**וריאציה 2 — איסור ביצוע פעולה:** מהי החובה במקרה של חשד גבוה? ← איסור לבצע ''פעולה מחייבת'' (כלל 44ב לכללי האתיקה).
**וריאציה 3 — הגנה על חסיון:** מדוע אין חובת דיווח? ← כדי להגן על חסיון עורך דין-לקוח (סעיף 8ב(ו) לחוק איסור הלבנת הון, רע"פ 751/15 אברג''יל, פסקה 41).', 'חשד להלבנת הון ← אין חובת דיווח ← יש איסור לבצע ''פעולה מחייבת''.',
    '["חוק איסור הלבנת הון, התש\"ס-2000, סעיף 8ב(ו)", "כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, סעיף 44ב", "רע\"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל (09.12.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, חלה עליו חובת דיווח אקטיבית לרשות לאיסור הלבנת הון.', false, 'טענה זו שגויה. המחוקק נמנע מלהטיל חובת דיווח אקטיבית על עורכי דין, בניגוד למוסדות פיננסיים, כדי לא לפגוע בחסיון עורך דין-לקוח.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, עורך דין אינו חייב לדווח על חשד להלבנת הון, אך אסור לו לבצע פעולה מחייבת אם הוא מעריך שרמת הסיכון גבוהה.', true, 'כלל 44ב לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע כי עורך דין לא יבצע ''פעולה מחייבת'' שהתבקשה בשביל לקוח אם הוא מעריך שרמת הסיכון להלבנת הון או מימון טרור גבוהה. המחוקק נמנע מלהטיל חובת דיווח אקטיבית על עורכי דין, כדי לא לפגוע בחסיון עורך דין-לקוח.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם מדובר בעבירה חמורה במיוחד.', false, 'טענה זו שגויה. חובת הדיווח אינה תלויה בחומרת העבירה, ובכל מקרה, אין חובת דיווח אקטיבית על עורכי דין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן הלקוח ויתר על חסיון עורך דין-לקוח.', false, 'טענה זו שגויה. חובת הדיווח אינה קשורה לויתור על חסיון, ובכל מקרה, אין חובת דיווח אקטיבית על עורכי דין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'אי-הפקדת כספי נאמנות בחשבון נפרד',
    4, 'עו"ד דני קיבל מלקוחו סכום כסף גדול בנאמנות לצורך רכישת נכס. במקום להפקיד את הכסף בחשבון נאמנות ספציפי, הפקיד אותו עו"ד דני בחשבונו הפרטי. האם עו"ד דני הפר חובה אתית?', 'שאלה זו עוסקת בחובת עורך דין להחזיק כספי נאמנות בחשבון בנק נפרד, כפי שנקבע בכללי לשכת עורכי הדין (אתיקה מקצועית). חובה זו נועדה להגן על כספי הלקוחות ולמנוע ערבוב נכסים.', 'כלל 39 לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986, קובע כי ''עורך דין יפקיד כספי נאמנות בחשבון בנק נפרד, שייקרא ''חשבון נאמנות'', ובו יוחזקו כספי נאמנות בלבד''. אי-הפקדת כספי נאמנות בחשבון נפרד מהווה הפרה חמורה של כללי האתיקה, שכן היא פוגעת בעקרון ההפרדה בין כספי עורך הדין לכספי הלקוח, ומעמידה את כספי הלקוח בסיכון. הפרה זו נחשבת לעבירת משמעת, כפי שניתן לראות במקרים רבים בבתי הדין המשמעתיים של לשכת עורכי הדין (ראו לדוגמה, בד"מ (ועדת משמעת לשכת עוה"ד ירושלים) 9/24 וועדת האתיקה של לשכת עורכי הדין נ'' עו#ד אימן דאהוד, סעיף 5(ה) לכתב הקובלנה).',
    'הנחה שכל עוד הכסף לא נגנב או נוצל לרעה, אין הפרה אתית, ובכך אי-הבנה של החובה הפורמלית להפריד בין כספי נאמנות לכספים פרטיים.', '["כספי נאמנות", "חשבון נאמנות", "כללי אתיקה מקצועית", "הפרת נאמנות", "עבירת משמעת"]'::jsonb, '**וריאציה 1 — חובת ההפקדה:** היכן יש להפקיד כספי נאמנות? ← בחשבון בנק נפרד שייקרא ''חשבון נאמנות'' (כלל 39 לכללי האתיקה).
**וריאציה 2 — תוצאת ההפרה:** מהי התוצאה של אי-הפקדה בחשבון נאמנות? ← עבירת משמעת (בד"מ 9/24 דאהוד, סעיף 5(ה)).
**וריאציה 3 — מטרת הכלל:** מהי מטרת כלל 39? ← להגן על כספי הלקוחות ולמנוע ערבוב נכסים (בד"מ 9/24 דאהוד, סעיף 3(ג)).', 'כספי נאמנות ← חובה להפקיד בחשבון נפרד ← אי-הפקדה = הפרה אתית.',
    '["בד\"מ (ועדת משמעת לשכת עוה\"ד ירושלים) 9/24 וועדת האתיקה של לשכת עורכי הדין נ'' עו#ד אימן דאהוד (12.02.2024)", "כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, סעיף 39"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, זוהי הפרה של חובת עורך הדין להחזיק כספי נאמנות בחשבון נפרד.', true, 'כלל 39 לכללי לשכת עורכי הדין (אתיקה מקצועית) מחייב עורך דין להפקיד כספי נאמנות בחשבון בנק נפרד. אי-הפקדה כזו מהווה עבירת משמעת חמורה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, כל עוד הכסף נשמר בנאמנות ולא נעשה בו שימוש אישי.', false, 'טענה זו שגויה. עצם אי-ההפקדה בחשבון נפרד מהווה הפרה, ללא קשר לשאלה אם נעשה שימוש אישי בכסף.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם נגרם נזק ללקוח כתוצאה מאי-ההפקדה.', false, 'טענה זו שגויה. ההפרה היא פורמלית ומתרחשת בעצם אי-ההפקדה בחשבון נפרד, ללא צורך בהוכחת נזק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן מדובר בסכום כסף קטן.', false, 'טענה זו שגויה. חובת ההפקדה בחשבון נפרד חלה על כל סכום כסף המתקבל בנאמנות, ללא קשר לגודלו.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 30, '2023-S-S-Q30';
END
$$;

