-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '06a0293a-cc21-4699-aa24-8a7f176f75c4'::uuid;
  v_group_id uuid := 'ca6a6509-b584-4802-999f-5a66ac34d607'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'c740fe63-98ef-40cb-94b4-5bd39e37e765'::uuid;
  v_ang_1 uuid := '1d823d15-b78c-470f-af34-468847916c70'::uuid;
  v_ang_2 uuid := 'b8daa394-2892-43e2-b169-e5f07c46e9a6'::uuid;
  v_ang_3 uuid := 'f4102f6d-0b2d-4a63-a7cd-441347b41219'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q31';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 31, '2023-S-S-Q31';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'ethics';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'ethics';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'disciplinary_law' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'disciplinary_law', 'ethics';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q31', v_chapter_id, v_subtopic_id, 'עו"ד גל ביקשה מבית המשפט לדחות את מועד הדיון בעניינה של לקוחה, בטענה כי עליה לעבור הליך רפואי באותו היום. בפועל, ההליך הרפואי התקיים יום קודם לכן, אולם דרש החלמה של יום. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 31}'::jsonb, 'השאלה עוסקת בחובות האתיות של עורכי דין, ובפרט בחובה שלא להטעות את בית המשפט, כפי שמעוגנת בכלל 34(א) לכללי לשכת עורכי הדין (אתיקה מקצועית). חובה זו היא אבן יסוד במערכת המשפט, שכן היא מבטיחה את טוהר ההליך השיפוטי, את יעילותו ואת אמון הציבור בו.', 'כלל 34(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986, קובע במפורש כי ''לא יעלה עורך דין, בין בעל פה ובין בכתב, טענה עובדתית או משפטית ביודעו שאינה נכונה''. במקרה הנדון, עו"ד גל טענה בפני בית המשפט כי עליה לעבור הליך רפואי באותו היום, בעוד שההליך כבר התקיים יום קודם לכן. זוהי טענה עובדתית שאינה נכונה, והיא הועלתה ביודעין. גם אם הצורך בהחלמה היה אמיתי, הצגת מצג שווא לגבי מועד ההליך מהווה הפרה של חובה אתית זו. בית המשפט העליון הדגיש את החומרה שבהגשת כתבי בית דין שאינם מדויקים או המכילים מידע כוזב, וקבע כי הדבר מועל בחובות עורך הדין כלפי לקוחו, בית המשפט, הצד שכנגד וכבוד המקצוע.', 'הטעות הנפוצה היא לחשוב שכל עוד הכוונה הכללית היא לגיטימית (למשל, צורך בהחלמה), ניתן להשתמש בטענות עובדתיות לא מדויקות. אולם, כלל 34(א) אוסר על הטעיה ביודעין, ללא קשר למניע.',
    '["אתיקה מקצועית", "איסור הטעיה", "כלל 34(א) לכללי האתיקה", "חובת עורך דין כלפי בית המשפט", "נאמנות לבית המשפט", "דין משמעתי"]'::jsonb, '**וריאציה 1 — הטעיה ביודעין:** האם טענה עובדתית לא נכונה ביודעין מותרת? ← לא, אסורה לפי כלל 34(א) לכללי האתיקה. סעיף 34 לכללי לשכת עורכי הדין (אתיקה מקצועית)
**וריאציה 2 — חשיבות האמת:** מדוע אסור להטעות את בית המשפט? ← לשמור על טוהר ההליך, יעילותו ואמון הציבור. בג"ץ 38379-12-24 פלונית נ'' בית הדין השרעי לערעורים ירושלים (23.02.2025)
**וריאציה 3 — הטעיה חלקית:** האם הצגת תמונה חלקית נחשבת להטעיה? ← כן, גם טענה עובדתית חסרה או הטעיה במחדל נחשבת להפרה. ת"פ (שלום הרצליה) 951/98 מדינת ישראל נ'' כרמי מיקי (09.01.2005)', 'עו"ד גל טענה טענה עובדתית לא נכונה ביודעין ← הפרה את כלל 34(א) ← חובה לא להטעות את בית המשפט.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, סעיף 34", "בג\"ץ 38379-12-24 פלונית נ'' בית הדין השרעי לערעורים ירושלים (23.02.2025)", "ת\"פ (שלום הרצליה) 951/98 מדינת ישראל נ'' כרמי מיקי (09.01.2005)", "תת\"ע (תעבורה ת\"א) 11965-11-17 בוריס קושמקוב נ'' מדינת ישראל (03.01.2018)", "ע\"ח (מחוזי ב\"ש) 56496-06-19 מחמוד נמר נ'' מדינת ישראל (06.07.2019)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''disciplinary_law'' | classifier_note: Lawyer misleading the court re medical-procedure date | source_review_note: השאלה עוסקת באתיקה מקצועית של עורכי דין, תחום שאינו משתלב באופן ישיר באף אחד מתתי-הנושאים הקיימים תחת ''סדר דין פלילי''. סווגה תחת ''משמעת עורכי דין'' כהצבת מקום זמנית, אך יש לשקול הוספת תת-נושא מתאים יותר לאתיקה מקצועית.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עו"ד גל הפרה את חובת האתיקה שלה בכך שקבעה לכאורה הליך רפואי למועד הדיון.', false, 'טענה זו אינה מדויקת. ההפרה אינה נעוצה בעצם קביעת ההליך הרפואי, אלא בהצגת עובדה לא נכונה לבית המשפט ביודעין, גם אם מטרתה הייתה לגיטימית.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עו"ד גל הפרה את חובת האתיקה שלה בכך שטענה בפני בית המשפט טענה לא נכונה ביודעין.', true, 'כלל 34(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) אוסר על עורך דין להעלות טענה עובדתית או משפטית ביודעו שאינה נכונה. הצגת מצג שווא לגבי מועד ההליך הרפואי, גם אם הצורך בהיעדרות היה קיים, מהווה הפרה של חובה זו.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עו"ד גל הפרה את חובת האתיקה שלה בכך שהציבה את האינטרס האישי שלה על פני זה של הלקוחה שלה.', false, 'טענה זו שגויה. השאלה אינה עוסקת בניגוד אינטרסים בין עורך הדין ללקוחה, אלא בהטעיית בית המשפט. ייתכן שהאינטרס של הלקוחה היה לדחות את הדיון, אך הדרך שבה פעלה עורכת הדין הייתה פסולה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עו"ד גל הפרה את חובת האתיקה שלה רק משום שלא ביקשה את הסכמת עורך הדין שכנגד בטרם הגישה בקשת דחיית דיון לבית המשפט.', false, 'טענה זו שגויה. אמנם יש חשיבות לבקשת הסכמת הצד שכנגד, אך ההפרה העיקרית במקרה זה היא הטעיית בית המשפט בטענה עובדתית לא נכונה ביודעין, ולא היעדר הסכמה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הטעיה במחדל',
    1, 'עו"ד דני ייצג לקוח בתביעה אזרחית. במהלך הדיון, התברר לעו"ד דני כי קיימת עובדה מהותית שיכולה להשפיע באופן דרמטי על תוצאות המשפט לרעת לקוחו, אך הוא בחר שלא לגלותה לבית המשפט, מתוך מחשבה שאינה רלוונטית לטענותיו. האם עו"ד דני הפר חובה אתית?', 'שאלה זו בוחנת את הרחבת תחולתו של איסור ההטעיה על עורכי דין, כך שיכלול גם הטעיה במחדל, כלומר אי-גילוי עובדות מהותיות לבית המשפט. היא מדגישה את חובת הגילוי של עורך הדין ואת עדיפותה על פני חובת הנאמנות ללקוח במקרים מסוימים.', 'הפסיקה בישראל קבעה כי איסור ההטעיה הקבוע בכלל 34(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) חל לא רק על הטעיה אקטיבית, אלא גם על הטעיה במחדל. כלומר, עורך דין המודע לעובדה מהותית שיש בה כדי להשפיע על החלטת בית המשפט, ונמנע מלגלותה, עלול להיחשב כמי שהטעה את בית המשפט. חובה זו נגזרת מחובתו הכללית של עורך הדין לסייע לבית המשפט לעשות משפט, המעוגנת בסעיף 54 לחוק לשכת עורכי הדין, והיא גוברת על חובת הנאמנות ללקוח במקרים של התנגשות.',
    'הנחה שאיסור ההטעיה מתייחס רק לאמירת שקרים מפורשים, ולא כולל אי-גילוי מידע רלוונטי, ובכך אי-הבנה של היקף חובת הגילוי של עורך הדין.', '["הטעיה במחדל", "חובת גילוי", "כלל 34(א) לכללי האתיקה", "חובת עורך דין כלפי בית המשפט", "חובת נאמנות ללקוח", "דין משמעתי"]'::jsonb, '**וריאציה 1 — מחדל כהטעיה:** האם אי-גילוי עובדה רלוונטית נחשב להטעיה? ← כן, גם הטעיה במחדל אסורה. מ"ח 2298/18 דן כוכבי נ'' בית הדין הארצי של לשכת עורכי הדין (07.10.2019)
**וריאציה 2 — חובת הגילוי:** מהי חובת הגילוי של עו"ד? ← לסייע לבית המשפט לעשות משפט ולהציג תמונה מלאה. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | החובה כלפי הלקוח וכלפי בית המשפט
**וריאציה 3 — יסוד נפשי:** האם נדרש יסוד נפשי למחדל? ← כן, ידיעה או עצימת עיניים. אבישי אדד טיעון בלתי-עקיב: סופיות, מניעות ‏והשתק (2021) | פרק חמישי: מיחזור הליכים או ניהול הליכים מקבילים לצרכי שינוי או הרחבת הטיעון', 'הטעיה במחדל ← אי-גילוי עובדה מהותית ביודעין ← הפרה אתית.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, סעיף 34", "חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 54", "מ\"ח 2298/18 דן כוכבי נ'' בית הדין הארצי של לשכת עורכי הדין (07.10.2019)", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | החובה כלפי הלקוח וכלפי בית המשפט", "אבישי אדד טיעון בלתי-עקיב: סופיות, מניעות ‏והשתק (2021) | פרק חמישי: מיחזור הליכים או ניהול הליכים מקבילים לצרכי שינוי או הרחבת הטיעון"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, כל עוד לא טען טענה עובדתית שקרית באופן אקטיבי.', false, 'טענה זו שגויה. איסור ההטעיה חל גם על הטעיה במחדל, כלומר אי-גילוי עובדה מהותית ביודעין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, הטעיה במחדל, קרי אי-גילוי עובדה מהותית ביודעין, מהווה הפרה של חובת האתיקה.', true, 'הפסיקה קבעה כי איסור ההטעיה לפי כלל 34(א) לכללי האתיקה כולל גם הטעיה במחדל, כאשר עורך דין נמנע מלגלות עובדה מהותית שיש לו ידיעה עליה, ובכך מונע מבית המשפט תמונה מלאה ואמיתית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם אי-הגילוי נבע ממחשבה פלילית ולא מרשלנות.', false, 'טענה זו שגויה. אף שנדרש יסוד נפשי של ידיעה או עצימת עיניים, אי-הגילוי עצמו, אם הוא מהותי, יכול להוות הפרה גם אם לא נבע ממחשבה פלילית במובן הצר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, שכן חובת הנאמנות ללקוח גוברת על חובת הגילוי לבית המשפט.', false, 'טענה זו שגויה. חובת עורך הדין כלפי בית המשפט, ובכללה החובה שלא להטעות, גוברת על חובת הנאמנות ללקוח במקרים של התנגשות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'יסוד הידיעה בהטעיה',
    2, 'מהו היסוד הנפשי הנדרש מעורך דין כדי שייחשב כמי שהפר את כלל 34(א) לכללי האתיקה, האוסר על הטעיית בית המשפט?', 'שאלה זו מתמקדת ביסוד הנפשי הנדרש להוכחת הפרה של כלל 34(א) לכללי לשכת עורכי הדין (אתיקה מקצועית), האוסר על הטעיית בית המשפט. היא מבחינה בין ידיעה בפועל, עצימת עיניים ורשלנות, ומבהירה את הסטנדרט הגבוה הנדרש להרשעה בעבירה זו.', 'כלל 34(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע כי ''לא יעלה עורך דין, בין בעל פה ובין בכתב, טענה עובדתית או משפטית ביודעו שאינה נכונה''. היסוד הנפשי הנדרש הוא ''ידיעה'' שהטענה אינה נכונה. הפסיקה הרחיבה את מושג הידיעה גם למקרים של ''עצימת עיניים'', כלומר מצב שבו עורך הדין חשד באמיתות הטענה אך נמנע במכוון מלברר את העובדות. רשלנות גרידא, ללא ידיעה או עצימת עיניים, אינה מספיקה להרשעה לפי כלל 34(א), אך עשויה להוות עבירת משמעת אחרת, כגון מעשה שאינו הולם את מקצוע עריכת הדין.',
    'הבלבול בין רשלנות לבין ידיעה או עצימת עיניים. סטנדרט הידיעה הוא גבוה יותר מרשלנות, ודורש מודעות מסוימת לאי-אמיתות הטענה או הימנעות מכוונת מבירור.', '["יסוד נפשי", "ידיעה", "עצימת עיניים", "רשלנות", "כלל 34(א) לכללי האתיקה", "דין משמעתי", "חוק העונשין"]'::jsonb, '**וריאציה 1 — יסוד הידיעה:** מה נדרש ליסוד ''ביודעין'' בכלל 34(א)? ← ידיעה בפועל או עצימת עיניים. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | איסור הטעיה
**וריאציה 2 — רשלנות:** האם רשלנות מספיקה להפרת כלל 34(א)? ← לא, אך עלולה להוות עבירת משמעת אחרת. ע"פ 9644/09 רוני א. אילן נ'' הועד המחוזי של לשכת עורכי הדין בתל אביב (30.06.2010)
**וריאציה 3 — חובת בדיקה:** האם יש חובה לבדוק עובדות? ← כן, חובה אתית לשמור על כבוד המקצוע ולעזור לבית המשפט. בג"ץ 38379-12-24 פלונית נ'' בית הדין השרעי לערעורים ירושלים (23.02.2025)', 'הטעיה ביודעין ← דורשת ידיעה או עצימת עיניים ← לא מספיקה רשלנות גרידא.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, סעיף 34", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | איסור הטעיה", "ע\"פ 9644/09 רוני א. אילן נ'' הועד המחוזי של לשכת עורכי הדין בתל אביב (30.06.2010)", "בג\"ץ 38379-12-24 פלונית נ'' בית הדין השרעי לערעורים ירושלים (23.02.2025)", "אבישי אדד טיעון בלתי-עקיב: סופיות, מניעות ‏והשתק (2021) | פרק חמישי: מיחזור הליכים או ניהול הליכים מקבילים לצרכי שינוי או הרחבת הטיעון"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'רשלנות, כלומר אי-בדיקה סבירה של העובדות או הדין.', false, 'טענה זו שגויה. כלל 34(א) דורש ידיעה בפועל או עצימת עיניים. רשלנות, אף שהיא עשויה להוות עבירת משמעת אחרת, אינה מספקת להפרת כלל 34(א).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'ידיעה בפועל שהטענה אינה נכונה, או עצימת עיניים לאמיתותה.', true, 'כלל 34(א) דורש שעורך הדין ידע שהטענה אינה נכונה. הפסיקה הרחיבה זאת גם למקרים של ''עצימת עיניים'', בהם עורך הדין נמנע במכוון מלברר את אמיתות הטענה כשיש לו יסוד לחשוד בהיותה כוזבת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כוונה להטעות את בית המשפט, גם אם הטענה הייתה נכונה בסופו של דבר.', false, 'טענה זו שגויה. היסוד הנפשי מתייחס לידיעה שהטענה אינה נכונה, ולא לכוונה להטעות כשלעצמה. אם הטענה נכונה, אין הטעיה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'די בכך שהטענה הייתה לא נכונה, ללא קשר לידיעתו של עורך הדין.', false, 'טענה זו שגויה. כלל 34(א) דורש יסוד נפשי של ''ביודעין'', ולכן עצם אי-נכונות הטענה אינה מספיקה ללא ידיעה או עצימת עיניים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חריג לאיסור הטעיה: הכחשה בכתב טענות',
    3, 'עו"ד רות הגישה כתב הגנה בהליך אזרחי, ובו הכחישה עובדה מסוימת שנטענה על ידי התובע, אף שידעה שהעובדה נכונה. האם עו"ד רות הפרה את כלל 34(א) לכללי האתיקה?', 'שאלה זו עוסקת בחריג מפורש לאיסור ההטעיה הקבוע בכללי האתיקה, המאפשר לעורך דין להכחיש עובדות בכתבי טענות בהליך אזרחי או לכפור בעובדות בהליך פלילי, גם אם הוא יודע שהן נכונות. חריג זה משקף את אופיו האדברסרי של ההליך המשפטי.', 'כלל 34(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) אוסר על עורך דין להעלות טענה עובדתית או משפטית ביודעו שאינה נכונה. אולם, כלל 34(ב) קובע סייג מפורש לאיסור זה: ''האמור בסעיף קטן (א) אין בו כדי למנוע הכחשה בכתב טענות בהליך אזרחי, או כפירה בעובדה בהליך פלילי''. הרציונל מאחורי חריג זה הוא שהכחשת עובדות בכתב טענות אינה מהווה הצהרה על אי-אמיתותן, אלא קריאת תיגר על הצד שכנגד להוכיח את טענותיו. זהו כלי דיוני לגיטימי במערכת משפט אדברסרית, ואינו נחשב להטעיה אתית.',
    'הבלבול בין הטעיה אסורה לבין הכחשה מותרת בכתבי טענות. יש להבין שהכחשה היא כלי לגיטימי לאתגר את נטל ההוכחה של הצד שכנגד, ולא הצהרה על עובדה שקרית.', '["כלל 34(ב) לכללי האתיקה", "הכחשה בכתב טענות", "הליך אזרחי", "הליך פלילי", "חריג לאיסור הטעיה", "שיטה אדברסרית"]'::jsonb, '**וריאציה 1 — הכחשה מותרת:** האם מותר להכחיש עובדה בכתב הגנה ביודעין? ← כן, כלל 34(ב) מתיר זאת בהליך אזרחי או כפירה בהליך פלילי. סעיף 34 לכללי לשכת עורכי הדין (אתיקה מקצועית)
**וריאציה 2 — רציונל החריג:** מדוע קיים חריג זה? ← כדי לאפשר לצדדים לאתגר את הראיות של הצד שכנגד בשיטה האדברסרית. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | איסור הטעיה
**וריאציה 3 — הבחנה:** מה ההבדל בין הכחשה להטעיה? ← הכחשה היא טענה שאין די ראיות, הטעיה היא הצגת שקר כאמת. ת"פ (תעבורה ת"א) 11965-11-17 בוריס קושמקוב נ'' מדינת ישראל (03.01.2018)', 'הכחשה בכתב טענות ← מותרת גם ביודעין ← חריג לכלל איסור הטעיה.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, סעיף 34", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | איסור הטעיה", "ת\"פ (תעבורה ת\"א) 11965-11-17 בוריס קושמקוב נ'' מדינת ישראל (03.01.2018)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, שכן אסור לעורך דין לטעון טענה עובדתית ביודעו שאינה נכונה.', false, 'טענה זו שגויה. כלל 34(ב) קובע חריג מפורש לאיסור ההטעיה במקרה של הכחשה בכתב טענות בהליך אזרחי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, שכן כלל 34(ב) קובע במפורש כי איסור ההטעיה אינו חל על הכחשה בכתב טענות בהליך אזרחי.', true, 'כלל 34(ב) לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע סייג לכלל 34(א), ולפיו אין בו כדי למנוע הכחשה בכתב טענות בהליך אזרחי, או כפירה בעובדה בהליך פלילי. זאת, מתוך הבנה שהכחשה כזו אינה בגדר הטעיה אלא חלק מהליך אדברסרי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן קיבלה אישור מבית המשפט להכחיש את העובדה.', false, 'טענה זו שגויה. אין צורך באישור מבית המשפט להכחשה בכתב טענות, שכן זוהי זכות דיונית המעוגנת בכללי האתיקה עצמם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אך רק אם הכחשת העובדה הייתה הכרחית להגנת הלקוח.', false, 'טענה זו שגויה. החריג שבכלל 34(ב) אינו מותנה בהכרחיות ההכחשה, אלא בעצם היותה הכחשה בכתב טענות בהליך אזרחי או כפירה בהליך פלילי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סנקציות על הטעיית בית המשפט',
    4, 'עו"ד שרון הגישה לבית המשפט כתב טענות המבוסס על אסמכתאות משפטיות בדויות, שנוצרו באמצעות כלי בינה מלאכותית. מהן הסנקציות שבית המשפט יכול להטיל עליה, בנוסף לדין משמעתי?', 'שאלה זו עוסקת בסנקציות השיפוטיות שבית המשפט יכול להטיל על עורך דין שהטעה אותו, ובפרט על הגשת כתבי טענות המבוססים על מידע כוזב או בדוי. היא מדגישה את הכלים העומדים לרשות בית המשפט לשמירה על טוהר ההליך המשפטי.', 'הגשת כתב טענות המבוסס על מידע כוזב או אסמכתאות בדויות, לרבות כאלו שנוצרו על ידי כלי בינה מלאכותית, נחשבת להפרה חמורה של חובות עורך הדין. בית המשפט העליון קבע כי במקרים כאלה, לבית המשפט עומדים מספר כלים: ראשית, ביכולתו לסלק על הסף הליך המבוסס על כתב טענות מטעה. שנית, בית המשפט רשאי להטיל הוצאות אישיות על עורך הדין שהגיש את כתב הטענות הבדוי. בנוסף לסנקציות שיפוטיות אלו, הפרת חובתו של עורך דין שלא להטעות את בית המשפט עלולה לעלות כדי עבירת משמעת לפי סעיף 61 לחוק לשכת עורכי הדין.',
    'הנחה שסנקציות על הטעיית בית המשפט מוגבלות לדין משמעתי בלבד, ובכך אי-הבנה של סמכויות בית המשפט להגן על טוהר ההליך השיפוטי.', '["סנקציות שיפוטיות", "הוצאות אישיות", "סילוק על הסף", "דין משמעתי", "הטעיית בית המשפט", "חובת עורך דין כלפי בית המשפט", "בינה מלאכותית"]'::jsonb, '**וריאציה 1 — סנקציות שיפוטיות:** אילו סנקציות יכול בית המשפט להטיל? ← סילוק על הסף, הטלת הוצאות אישיות. בג"ץ 38379-12-24 פלונית נ'' בית הדין השרעי לערעורים ירושלים (23.02.2025)
**וריאציה 2 — סנקציות משמעתיות:** אילו סנקציות יכולה לשכת עורכי הדין להטיל? ← עבירת משמעת לפי סעיף 61 לחוק לשכת עורכי הדין. בג"ץ 38379-12-24 פלונית נ'' בית הדין השרעי לערעורים ירושלים (23.02.2025)
**וריאציה 3 — חומרת המעשה:** מדוע הטעיה חמורה? ← פוגעת באמון, בטוהר ההליך וביעילותו. בג"ץ 38379-12-24 פלונית נ'' בית הדין השרעי לערעורים ירושלים (23.02.2025)', 'הטעיית בית המשפט ← סילוק על הסף, הוצאות אישיות, דין משמעתי ← פגיעה באמון וביעילות.',
    '["בג\"ץ 38379-12-24 פלונית נ'' בית הדין השרעי לערעורים ירושלים (23.02.2025)", "חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 61", "כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, סעיף 34", "יעקב שקד סדר הדין האזרחי (2026) | פרק ה כתבי טענות - סילוק ותיקון"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בית המשפט יכול רק להפנות את העניין ללשכת עורכי הדין לטיפול משמעתי.', false, 'טענה זו שגויה. לבית המשפט יש כלים נוספים להתמודדות עם הטעיה, מעבר להפניה לדין משמעתי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בית המשפט רשאי לסלק את ההליך על הסף ולהטיל על עו"ד שרון הוצאות אישיות.', true, 'הפסיקה קבעה כי במקרים של הגשת כתבי טענות מטעים או המכילים אסמכתאות בדויות, בית המשפט רשאי לסלק את ההליך על הסף ואף להטיל הוצאות אישיות על עורך הדין שהגישם. זאת, בנוסף לאפשרות לדין משמעתי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בית המשפט רשאי להטיל עליה קנס כספי בלבד, ללא סילוק ההליך.', false, 'טענה זו שגויה. הטלת הוצאות אישיות היא סנקציה אפשרית, אך בית המשפט יכול גם לסלק את ההליך על הסף, והקנס הכספי הוא סנקציה משמעתית ולא שיפוטית ישירה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית המשפט רשאי להורות על פסילת עורך הדין מלהופיע בפניו בעתיד.', false, 'טענה זו שגויה. פסילת עורך דין מלהופיע בפני בית המשפט היא סנקציה חמורה שאינה נכללת בסמכויות הישירות של בית המשפט במקרה כזה, אלא בסמכות בתי הדין המשמעתיים של לשכת עורכי הדין.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 31, '2023-S-S-Q31';
END
$$;

