  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q32', v_chapter_id, v_subtopic_id, 'יעקב ויצחק קשרו קשר לפרוץ לדירת מגורים בחולון. השניים תכננו והחליטו לפני צאתם לביצוע הפריצה כי יעקב יצטייד במפתח מותאם לדירה, בכפפות ובמברג, ימסור אותם ליצחק כשיגיעו לדירה, יצחק יפרוץ לדירה, ויעקב ישמש כמתצפת - וכך עשו. יצחק לא הצליח לפרוץ לדירה, ולאחר זמן מה עזב את הבניין, חבר ליעקב ושניהם עזבו את המקום. הוגש נגדם כתב אישום על קשירת קשר לביצוע פשע וניסיון לגנבה. כתב האישום הסתיים בהרשעה. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 32}'::jsonb, 'השאלה עוסקת בהבחנה בין ''מבצע בצוותא'' ל''מסייע'' בדיני העונשין, נושא מרכזי בפרק השותפות לדבר עבירה. היא בוחנת את יישום המבחנים שפותחו בפסיקה, כגון מבחן השליטה הפונקציונלית ומבחן המעגלים, על מנת לקבוע את מידת האחריות הפלילית של כל אחד מהמעורבים באירוע עברייני.', 'סעיף 29(ב) לחוק העונשין מגדיר ''מבצעים בצוותא'' כ''המשתתפים בביצוע עבירה תוך עשיית מעשים לביצועה, ואין נפקה מינה אם כל המעשים נעשו ביחד, או אם נעשו מקצתם בידי אחד ומקצתם בידי אחר''. הפסיקה קבעה כי סיווגם של הצדדים לעבירה נעשה על פי תפקידם בתכנית העבריינית ומידת קרבתם ל''גרעין הקשה'' של ביצוע העבירה. מבצע בצוותא הוא מי שלוקח חלק בביצוע עבירה על ידי עשיית מעשה הדרוש להגשמת התכנית הפלילית, כאשר היסוד הנפשי הנדרש זהה ליסוד הנדרש בעבירה העיקרית ומודעות לפעולה בצוותא עם האחרים. במקרה זה, יעקב ויצחק תכננו יחד את הפריצה, חילקו ביניהם תפקידים (יעקב סיפק כלים ושימש מתצפת, יצחק ניסה לפרוץ), ופעלו להגשמת התוכנית המשותפת. תרומתו של כל אחד מהם הייתה מהותית ו''פנימית'' לביצוע העבירה, ולכן שניהם ייחשבו למבצעים בצוותא של ניסיון הגנבה וקשירת הקשר.', 'הטעות הנפוצה היא להבחין בין מבצע למסייע על בסיס מידת התרומה הפיזית הישירה בלבד, מבלי להתחשב בתכנון המשותף, חלוקת התפקידים, והשליטה הפונקציונלית של כל אחד מהשותפים על התוכנית העבריינית הכוללת.',
    '["מבצע בצוותא", "מסייע", "קשירת קשר", "ניסיון עבירה", "חוק העונשין", "מבחן השליטה הפונקציונלית", "מעגל פנימי"]'::jsonb, '**וריאציה 1 — הגדרת מבצע בצוותא:** מהו מבצע בצוותא? ← משתתפים בביצוע עבירה תוך עשיית מעשים לביצועה, גם אם לא כל המעשים נעשו ביחד. סעיף 29(ב) לחוק העונשין, תשל"ז-1977
**וריאציה 2 — תפקיד המתצפת:** האם מתצפת הוא מבצע בצוותא? ← כן, אם תפקידו מהותי לתוכנית העבריינית המשותפת. ע"פ 4514/10 מוחמד דיבה נ'' מדינת ישראל (03.09.2012)
**וריאציה 3 — יסוד נפשי:** מהו היסוד הנפשי הנדרש ממבצע בצוותא? ← היסוד הנפשי של העבירה העיקרית ומודעות לפעולה בצוותא. ע"פ 8107/09 אמג''ד דענא נ'' מדינת ישראל (27.06.2011)', 'יעקב ויצחק ← תכנון וחלוקת תפקידים ← מעורבות מהותית ← מבצעים בצוותא ← ניסיון גנבה וקשירת קשר.', '["חוק העונשין, תשל\"ז-1977, סעיפים 29, 31", "ע\"פ 4389/93 מחמוד אבו סרור נ'' מדינת ישראל (28.05.1998)", "ע\"פ 7477/08 איתן גץ נ'' מדינת ישראל (14.11.2011)", "ע\"פ 2505578 מוחמד דיבה נ'' מדינת ישראל (03.09.2012)", "ע\"פ 1764345 אמג''ד דענא נ'' מדינת ישראל (27.06.2011)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Co-conspirators (שותפות לדבר עבירה) — accessories vs principals | source_review_note: השאלה עוסקת בדיני עונשין מהותיים (שותפות לדבר עבירה), תחום שאינו משתלב באופן ישיר באף אחד מתתי-הנושאים הקיימים תחת ''סדר דין פלילי''. סווגה תחת ''משמעת עורכי דין'' כהצבת מקום זמנית, אך יש לשקול הוספת תת-נושא מתאים יותר לדיני עונשין מהותיים.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'יעקב ויצחק יורשעו כמבצעים בצוותא בעבירות של קשירת קשר לביצוע פשע ובניסיון לגנבה.', true, 'התכנון המשותף, חלוקת התפקידים, והמעורבות המהותית של כל אחד מהם בקידום התוכנית העבריינית, גם אם לא ביצעו את כל רכיבי העבירה בפועל, הופכים אותם למבצעים בצוותא. יעקב, בתפקידו כמתצפת וכמי שסיפק את הכלים, ויצחק, כמי שניסה לפרוץ, שניהם נחשבים לחלק מהמעגל הפנימי של ביצוע העבירה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'יצחק יורשע כמבצע בעבירות של קשירת קשר לביצוע פשע וניסיון לגנבה, ויעקב יורשע כמסייע בעבירות של קשירת קשר לביצוע פשע וניסיון לגנבה.', false, 'טענה זו שגויה. יעקב לא היה מסייע בלבד. תפקידו כמתצפת וכמי שסיפק את הכלים היה מהותי לביצוע העבירה, והוא נטל חלק פעיל בתוכנית העבריינית המשותפת, מה שהופך אותו למבצע בצוותא.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'יעקב יורשע כמבצע בעבירות של קשירת קשר לביצוע פשע וניסיון לגנבה, ויצחק יורשע כמסייע בעבירות של קשירת קשר לביצוע פשע וניסיון לגנבה.', false, 'טענה זו שגויה. יצחק, שניסה לפרוץ לדירה, הוא בוודאי מבצע. יעקב, בתפקידו כמתצפת וכמי שסיפק את הכלים, נחשב גם הוא למבצע בצוותא בשל מעורבותו המהותית בתוכנית העבריינית.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'יצחק יורשע בעבירות של קשירת קשר לביצוע פשע וניסיון לגנבה, ויעקב יורשע בקשירת קשר לביצוע פשע ויזוכה מניסיון גנבה.', false, 'טענה זו שגויה. יעקב לא יזוכה מניסיון גנבה. מעורבותו בתכנון, אספקת הכלים ותפקידו כמתצפת הופכים אותו למבצע בצוותא של ניסיון הגנבה, גם אם לא ביצע את הפריצה בפועל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תפקיד פסיבי בביצוע בצוותא',
    1, 'ראובן ושמעון תכננו לשדוד בנק. ראובן נכנס לבנק וביצע את השוד בפועל, בעוד שמעון המתין ברכב מילוט מחוץ לבנק, מוכן להימלט עם ראובן לאחר השוד. האם שמעון ייחשב למבצע בצוותא של השוד?', 'שאלה זו בוחנת את היקף האחריות של ''מבצע בצוותא'' במקרים בהם התרומה הפיזית לעבירה אינה ישירה או ''אקטיבית'' במובן המצומצם, אלא מתבטאת בתפקיד עזר חיוני לתוכנית העבריינית הכוללת. היא מדגישה את מבחן השליטה הפונקציונלית ואת תפיסת המבצעים בצוותא כ''גוף אחד''.', 'הפסיקה קבעה כי מבצעים בצוותא הם מי שנטלו חלק ישיר ומהותי בביצוע העיקרי של העבירה, ומהווים חלק מן ''המעגל הפנימי'' של ביצוע העבירה. הם נתפסים כ''גוף אחד'' הפועל באמצעות זרועות שונות, כאשר לכל אחת מהן תפקיד מהותי בביצוע העבירה. תפקידו של נהג מילוט, אף שאינו כרוך בכניסה לזירת העבירה, הוא חיוני להגשמת התוכנית העבריינית המשותפת ומעיד על שליטה פונקציונלית על האירוע. לכן, גם מי שמשמש כנהג מילוט ייחשב למבצע בצוותא של השוד, ולא למסייע בלבד, שכן תרומתו היא ''פנימית'' ומהותית להגשמת התוכנית המשותפת.',
    'הטעות הנפוצה היא להגביל את הגדרת ''מבצע בצוותא'' רק למי שמבצע את הרכיב הפיזי המרכזי של העבירה, ובכך להתעלם מתפקידים חיוניים אחרים בתוכנית העבריינית המשותפת.', '["מבצע בצוותא", "מסייע", "שליטה פונקציונלית", "מעגל פנימי", "תכנית משותפת", "יסוד עובדתי"]'::jsonb, '**וריאציה 1 — נהג מילוט:** האם נהג מילוט הוא מבצע בצוותא או מסייע? ← מבצע בצוותא, תפקידו חיוני לתוכנית העבריינית. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | ב. מבצע בצוותא
**וריאציה 2 — מבחן השליטה:** מהו מבחן השליטה הפונקציונלית? ← שליטה רעיונית על הביצוע כולו, היותו ''אדון'' לפעילות העבריינית. ע"פ 2103/07 אביהו הורוביץ נ'' מדינת ישראל (31.12.2008)
**וריאציה 3 — גוף אחד:** כיצד נתפסים מבצעים בצוותא? ← כ''גוף אחד'' בעל זרועות שונות, שכל אחת מהן תורמת לביצוע. ע"פ 275/09 עאהד ע''ולמה נ'' מדינת ישראל (28.07.2011)', 'נהג מילוט ← חלק מהותי מתוכנית ← מבצע בצוותא ← לא מסייע.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 29(ב)", "ע\"פ 2103/07 אביהו הורוביץ נ'' מדינת ישראל (31.12.2008)", "ע\"פ 1853155 עאהד ע''ולמה נ'' מדינת ישראל (28.07.2011)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | ב. מבצע בצוותא"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, שמעון ייחשב כמסייע בלבד, שכן לא נכנס לבנק ולא ביצע את השוד בפועל.', false, 'טענה זו שגויה. הפסיקה קבעה כי תפקיד נהג המילוט, גם אם אינו כרוך בכניסה לזירת העבירה, הוא חלק מהותי מהתוכנית העבריינית המשותפת, ולכן נחשב לביצוע בצוותא.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, שמעון ייחשב למבצע בצוותא, שכן תפקידו כנהג מילוט הוא חלק מהותי מהתוכנית העבריינית המשותפת.', true, 'הפסיקה רואה במבצעים בצוותא ''גוף אחד'' הפועל באמצעות זרועות שונות. תפקידו של שמעון כנהג מילוט, אף שאינו כרוך בביצוע הפיזי של השוד בתוך הבנק, הוא חיוני להגשמת התוכנית העבריינית המשותפת ומעיד על שליטה פונקציונלית על האירוע, ולכן הוא ייחשב למבצע בצוותא.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם היה מודע לפרטי השוד המדויקים ולסכום הכסף שייגנב.', false, 'טענה זו שגויה. היסוד הנפשי הנדרש הוא מודעות לביצוע העבירה בצוותא ולרכיביה העיקריים, ולאו דווקא לכל הפרטים המדויקים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן היה חמוש ומוכן להשתמש בנשק בעת הצורך.', false, 'טענה זו שגויה. היות שמעון חמוש אינה תנאי הכרחי לסיווגו כמבצע בצוותא במקרה זה, שכן תפקידו כנהג מילוט כבר מהווה תרומה מהותית לביצוע העבירה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני ההבחנה בין מבצע למסייע',
    2, 'מהם מבחני העזר המרכזיים שפותחו בפסיקה לצורך הבחנה בין ''מבצע בצוותא'' ל''מסייע''?', 'שאלה זו סוקרת את מכלול מבחני העזר שפותחו בפסיקה הישראלית לצורך הבחנה בין ''מבצע בצוותא'' ל''מסייע''. הבנה מעמיקה של מבחנים אלו חיונית ליישום נכון של דיני השותפות לדבר עבירה, שכן לסיווג יש השלכות משמעותיות על מידת העונש.', 'ההבחנה בין מבצע בצוותא למסייע אינה פשוטה, ולכן הפסיקה פיתחה מספר מבחני עזר. המבחן המרכזי הוא ''מבחן השליטה הפונקציונלית'', לפיו המבצע בצוותא הוא ''אדון'' לפעילות העבריינית ובידיו שליטה מהותית על הביצוע כולו, יחד עם האחרים. מבחן נוסף הוא ''מבחן המעגלים'', המבחין בין ''מעגל פנימי'' של מבצעים בצוותא ל''מעגל חיצוני'' של מסייעים. לבסוף, ''המבחן המשולב'' מתאר את היחס בין היסוד העובדתי ליסוד הנפשי כ''מקבילית כוחות'', לפיה ככל שהיסוד הנפשי חזק יותר, ניתן להסתפק ביסוד עובדתי חלש יותר, ולהיפך. מבחנים אלו אינם קונקלוסיביים בפני עצמם, אלא משמשים כמבחני עזר משלימים.',
    'הטעות היא לחשוב שיש מבחן אחד ויחיד ומכריע להבחנה, או להתמקד רק באחד המבחנים תוך התעלמות מהאחרים ומהצורך בבחינה משולבת.', '["מבחן השליטה הפונקציונלית", "מבחן המעגלים", "מבחן משולב", "מקבילית כוחות", "יסוד נפשי", "יסוד עובדתי"]'::jsonb, '**וריאציה 1 — מבחנים עיקריים:** מהם מבחני העזר המרכזיים? ← שליטה פונקציונלית, מעגלים (פנימי/חיצוני), מבחן משולב (מקבילית כוחות). תפ"ח (מחוזי נצרת) 3556-11-23 מדינת ישראל נ'' מוחמד סביחי (13.01.2026)
**וריאציה 2 — מבחן השליטה:** מה מאפיין את מבחן השליטה הפונקציונלית? ← המבצע בצוותא הוא ''אדון'' לפעילות העבריינית, בעל שליטה מהותית. ע"פ 9716/02 מחמד רימאוי נ'' מדינת ישראל (15.02.2010)
**וריאציה 3 — המבחן המשולב:** כיצד פועל המבחן המשולב? ← כמקבילית כוחות: יסוד נפשי חזק מאזן יסוד עובדתי חלש, ולהיפך. ע"פ 4186/13 ע''אלב מחמד ע''נאים נ'' מדינת ישראל (13.04.2015)', 'מבחני הבחנה ← שליטה פונקציונלית, מעגלים, מבחן משולב ← לא מבחן יחיד.',
    '["ע\"פ 9716/02 מחמד רימאוי נ'' מדינת ישראל (15.02.2010)", "ע\"פ 3378176 ע''אלב מחמד ע''נאים נ'' מדינת ישראל (13.04.2015)", "ע\"פ 11191678 מדינת ישראל נ'' מוחמד סביחי (13.01.2026)", "ע\"פ 2549/19 מדינת ישראל נ'' עאמר זעאתרה (25.01.2022)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | ב. על ההבחנה בין מבצע בצוותא לבין מסייע"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מבחן הסנקציה הפלילית ומבחן התכנון המוקדם בלבד.', false, 'טענה זו שגויה. מבחן הסנקציה הפלילית לא התקבל כמבחן קונקלוסיבי, ומבחן התכנון המוקדם הוא רק אחד ממבחני העזר, ולא היחיד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'מבחן השליטה הפונקציונלית, מבחן המעגלים (פנימי/חיצוני) והמבחן המשולב (מקבילית כוחות).', true, 'הפסיקה אימצה ופיתחה מספר מבחני עזר מרכזיים להבחנה בין מבצע בצוותא למסייע: מבחן השליטה הפונקציונלית, הבוחן את מידת השליטה של השותף על הביצוע; מבחן המעגלים, המבחין בין מעורבות ''פנימית'' ל''חיצונית''; והמבחן המשולב, המאזן בין היסוד העובדתי ליסוד הנפשי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מבחן הנוכחות בזירת העבירה ומבחן היסוד הנפשי בלבד.', false, 'טענה זו שגויה. נוכחות בזירת העבירה אינה תנאי הכרחי או מספיק לביצוע בצוותא, והיסוד הנפשי הוא רק אחד ממרכיבי המבחן המשולב, ולא מבחן יחיד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מבחן התרומה הפיזית הישירה ומבחן הכוונה הספציפית לביצוע העבירה.', false, 'טענה זו שגויה. תרומה פיזית ישירה אינה תמיד נדרשת לביצוע בצוותא, והכוונה הספציפית היא חלק מהיסוד הנפשי, אך אינה מבחן יחיד להבחנה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שותפות ספונטנית בביצוע בצוותא',
    3, 'יוסי ודוד נקלעו לקטטה אלימה. יוסי החל להכות את הקורבן, ודוד, ללא תכנון מוקדם, הצטרף אליו והחל גם הוא להכות את הקורבן. האם דוד יכול להיחשב כמבצע בצוותא של התקיפה, אף שלא היה תכנון מוקדם?', 'שאלה זו בוחנת את גבולות מושג ''ביצוע בצוותא'' בהקשר של שותפות ספונטנית, כלומר, מצבים בהם אין תכנון מוקדם או חלוקת תפקידים פורמלית. היא מדגישה כי גם במקרים כאלה, ניתן להרשיע אדם כמבצע בצוותא אם תרומתו לעבירה מהותית והוא פועל עם היסוד הנפשי הנדרש.', 'הפסיקה הכירה בכך כי לא בכל ביצוע בצוותא נדרשת היוועדות מוקדמת או תכנון מראש. לעיתים, שותפות ספונטנית יכולה להפוך עבריינים למבצעים בצוותא. המבחן המרכזי הוא בחינת מהות העשייה של הנאשם ויחסו הנפשי לביצוע העבירה, במסגרת ''מבחן משולב''. אם דוד הצטרף באופן אקטיבי לביצוע התקיפה, ותרומתו הפיזית הייתה מהותית, וכן התקיים אצלו היסוד הנפשי של העבירה (מודעות לטיב המעשה ולאפשרות גרימת התוצאות), הוא ייחשב למבצע בצוותא, גם אם לא היה תכנון מוקדם עם יוסי.',
    'הנחה שביצוע בצוותא מחייב תמיד תכנון מוקדם ומפורט. יש לזכור שהפסיקה הרחיבה את המושג גם למקרים של שותפות ספונטנית, תוך התמקדות בתרומה המהותית וביסוד הנפשי.', '["ביצוע בצוותא", "שותפות ספונטנית", "תכנון מוקדם", "מבחן משולב", "יסוד נפשי", "יסוד עובדתי"]'::jsonb, '**וריאציה 1 — תכנון מוקדם:** האם תכנון מוקדם הכרחי לביצוע בצוותא? ← לא, שותפות ספונטנית אפשרית. ע"פ 2067/16 פלוני נ'' מדינת ישראל (08.02.2018)
**וריאציה 2 — מבחן התרומה:** מה נדרש בשותפות ספונטנית? ← תרומה מהותית לביצוע העבירה ויסוד נפשי מתאים. אסף הרדוף אשמים: טרילוגיה של משפט פלילי ‏- כרך ‏I דיני עונשין (2025) | 4. פרשת פלוני: עימות שהפך לרצח

**וריאציה 3 — יסוד נפשי:** מהו היסוד הנפשי הנדרש? ← היסוד הנפשי של העבירה העיקרית ומודעות לפעולה בצוותא. ע"פ 275/09 עאהד ע''ולמה נ'' מדינת ישראל (28.07.2011)', 'שותפות ספונטנית ← אפשרית לביצוע בצוותא ← דורשת תרומה מהותית ויסוד נפשי.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 29(ב)", "ע\"פ 2067/16 פלוני נ'' מדינת ישראל (08.02.2018)", "ע\"פ 275/09 עאהד ע''ולמה נ'' מדינת ישראל (28.07.2011)", "אסף הרדוף אשמים: טרילוגיה של משפט פלילי ‏- כרך ‏I דיני עונשין (2025) | 4. פרשת פלוני: עימות שהפך לרצח"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, ביצוע בצוותא דורש תמיד תכנון מוקדם וחלוקת תפקידים ברורה.', false, 'טענה זו שגויה. הפסיקה הכירה באפשרות של שותפות ספונטנית בביצוע בצוותא, ללא צורך בתכנון מוקדם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, שכן הפסיקה הכירה באפשרות של שותפות ספונטנית בביצוע בצוותא, גם ללא תכנון מוקדם.', true, 'הפסיקה קבעה כי לא בכל ביצוע בצוותא נדרשת היוועדות או תכנון מראש, ושותפות ספונטנית יכולה גם היא להפוך עבריינים למבצעים בצוותא, ובלבד שמתקיימים היסוד הנפשי והעובדתי הנדרשים לביצוע בצוותא.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם דוד היה מודע לכוונה של יוסי לגרום חבלה חמורה לקורבן.', false, 'טענה זו שגויה חלקית. מודעות ליסוד הנפשי של העבירה נדרשת, אך היא אינה תנאי מספיק בפני עצמה לביצוע בצוותא ללא מעורבות עובדתית מהותית, גם אם ספונטנית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, דוד ייחשב כמסייע בלבד, שכן הצטרף למעשה שכבר החל.', false, 'טענה זו שגויה. עצם ההצטרפות האקטיבית לביצוע העבירה, גם אם היא ספונטנית, יכולה להפוך את דוד למבצע בצוותא, ולא למסייע בלבד.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'אחריות לעבירה שונה או נוספת',
    4, 'שלושה עבריינים תכננו לבצע שוד מזוין. במהלך השוד, אחד מהם, ללא תכנון מוקדם עם האחרים, ירה בקורבן וגרם למותו. האם שני השותפים האחרים יישאו באחריות למותו של הקורבן?', 'שאלה זו עוסקת באחריותם של שותפים לעבירה (מבצעים בצוותא) כאשר אחד מהם מבצע עבירה שונה או נוספת במהלך ביצוע העבירה המקורית. היא מתייחסת לסעיף 34א לחוק העונשין, המטיל אחריות על השותפים הנותרים בתנאים מסוימים, גם אם העבירה הנוספת לא תוכננה מראש.', 'סעיף 34א(א)(1) לחוק העונשין קובע כי אם מבצע, אגב עשיית העבירה המקורית, עבירה שונה ממנה או נוספת לה, כאשר בנסיבות העניין אדם מן היישוב יכול היה להיות מודע לאפשרות עשייתה, יישאו באחריות לה גם המבצעים בצוותא הנותרים. במקרה כזה, אם העבירה השונה או הנוספת נעברה בכוונה על ידי המבצע, יישאו המבצעים הנותרים באחריות לה כעל עבירה של אדישות בלבד. הרציונל הוא שמי שמשתתף בשוד מזוין צריך לצפות אפשרות של הידרדרות לאלימות קטלנית, גם אם לא תכנן אותה מראש.',
    'הנחה ששותפים אחראים רק לעבירות שתכננו במפורש. יש לזכור את הרחבת האחריות לפי סעיף 34א, המטילה אחריות גם על עבירות נלוות שניתן היה לצפותן באופן אובייקטיבי.', '["עבירה שונה או נוספת", "סעיף 34א לחוק העונשין", "מבצע בצוותא", "אחריות פלילית", "אדישות", "צפיות אובייקטיבית"]'::jsonb, '**וריאציה 1 — תנאי האחריות:** מתי שותפים אחראים לעבירה נוספת? ← אם אדם מן היישוב יכול היה לצפותה אגב העבירה המקורית. סעיף 34א לחוק העונשין, תשל"ז-1977
**וריאציה 2 — יסוד נפשי:** מהו היסוד הנפשי של השותפים לעבירה הנוספת? ← אדישות, אם העבירה הנוספת נעברה בכוונה. סעיף 34א לחוק העונשין, תשל"ז-1977
**וריאציה 3 — דוגמה:** שוד מזוין שהידרדר לרצח? ← השותפים אחראים לרצח באדישות, אם צפוי. נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | שאלת האחריות של השותפים האחרים', 'עבירה נוספת ← צפיות אובייקטיבית ← אחריות באדישות ← סעיף 34א.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34א", "נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | שאלת האחריות של השותפים האחרים", "ע\"פ 3328/14 סמר אבו חאמד נ'' מדינת ישראל (07.12.2017)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, שכן מותו של הקורבן לא היה חלק מהתכנון המקורי ולא נצפה על ידם בפועל.', false, 'טענה זו שגויה. סעיף 34א לחוק העונשין קובע אחריות לעבירה שונה או נוספת גם אם לא הייתה חלק מהתכנון המקורי, בתנאים מסוימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, אם אדם מן היישוב יכול היה להיות מודע לאפשרות שמעשה כזה ייעשה אגב השוד המזוין, והם יישאו באחריות כעל עבירה של אדישות.', true, 'סעיף 34א(א)(1) לחוק העונשין קובע כי אם מבצע עבר, אגב עשיית העבירה המקורית, עבירה שונה או נוספת, כאשר בנסיבות העניין אדם מן היישוב יכול היה להיות מודע לאפשרות עשייתה, יישאו באחריות לה גם המבצעים בצוותא הנותרים, כעל עבירה של אדישות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם הם היו נוכחים בזירת הירי וראו את המעשה מתרחש.', false, 'טענה זו שגויה. האחריות לפי סעיף 34א אינה מותנית בנוכחות פיזית בזירת העבירה הנוספת, אלא במודעות פוטנציאלית של אדם מן היישוב לאפשרות התרחשותה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן הם שידלו או סייעו באופן אקטיבי למעשה הירי.', false, 'טענה זו שגויה. סעיף 34א מטיל אחריות על מבצעים בצוותא גם ללא שידול או סיוע אקטיבי לעבירה הנוספת, אלא על בסיס צפיות אובייקטיבית.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 32, '2023-S-S-Q32';
END
$$;

