-- classifier_note: Avoidance of conviction for minors — youth law, post-Phase 4 subtopic
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '7fc09574-12c9-4b2b-93fb-5e6c20a3bd3a'::uuid;
  v_group_id uuid := '2fd88f52-5e70-4477-9ebb-be0cc0844414'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '0c234561-993b-4cbe-bd56-6210df69742c'::uuid;
  v_ang_1 uuid := 'b5db6c00-42a8-4199-99a7-83165e4d75cc'::uuid;
  v_ang_2 uuid := 'f27f5b81-dd46-46c3-bdc9-68dc145aee96'::uuid;
  v_ang_3 uuid := 'a9c870c8-787f-46f6-8612-fec9e1684e40'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q33';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 33, '2023-S-S-Q33';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'youth_law' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'youth_law', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q33', v_chapter_id, v_subtopic_id, 'מה הדין לעניין הימנעות מהרשעה של קטינים?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 33}'::jsonb, 'השאלה עוסקת בהבחנה המהותית בין הימנעות מהרשעה של קטינים לזו של בגירים. היא מדגישה כי אף שהמתווה הכללי לבחינת אי-הרשעה דומה, מערך האיזונים שונה באופן ניכר, תוך מתן משקל יתר לשיקולי שיקום וטובת הקטין, בהתאם לרוח חוק הנוער (שפיטה, ענישה ודרכי טיפול).', 'הכלל הוא שבית משפט שקבע כי נאשם ביצע עבירה ירשיעו בדין. אולם, לכלל זה קיימים חריגים, ובאשר לקטינים, סעיף 24 לחוק הנוער (שפיטה, ענישה ודרכי טיפול) מקנה לבית המשפט סמכות להימנע מהרשעה או להטיל אמצעים טיפוליים ללא הרשעה. הפסיקה קבעה כי המתווה הכללי להכרעה בשאלת הימנעות מהרשעה דומה במקרה של קטינים ובגירים (הלכת כתב), אך מערך האיזונים שונה. בעניינם של קטינים, ניתנים משקל יתר לנסיבותיהם האישיות, לגילם, לנזק הצפוי להם מההרשעה, לאפשרויות הטיפול בהם ולסיכויי שיקומם. לכך מצטרף גם האינטרס הציבורי בהשבת הקטין לתפקוד נורמטיבי בחברה בעודו בתחילת דרכו בחיים. הנכונות לסטות מחובת מיצוי הדין בעניינם של קטינים היא גדולה יותר מאשר אצל בגירים, שם הימנעות מהרשעה תיעשה במקרים חריגים ויוצאי דופן בלבד (ע"פ 3069/22 מדינת ישראל נ'' פלוני; ע"פ 8378/22 פלוני נ'' מדינת ישראל).', 'הטעות הנפוצה היא לחשוב שאמות המידה להימנעות מהרשעה של קטינים שונות לחלוטין מאלו של בגירים, או לחילופין, שהן זהות. ההבחנה המדויקת היא באמות מידה דומות אך מערך איזונים שונה.',
    '["הימנעות מהרשעה", "קטינים", "חוק הנוער", "הלכת כתב", "שיקום", "אינטרס ציבורי", "מערך איזונים"]'::jsonb, '**וריאציה 1 — כלל מול חריג:** מהו הכלל לגבי הרשעה? ← הרשעה, למעט חריגים. ע"פ 7993/10 פלוני נ'' מדינת ישראל (22.07.2013)
**וריאציה 2 — קטינים מול בגירים:** מה ההבדל העיקרי בין קטינים לבגירים בהימנעות מהרשעה? ← אצל קטינים, נכונות גדולה יותר להימנע מהרשעה ומשקל יתר לשיקום. ע"פ 8378/22 פלוני נ'' מדינת ישראל (26.07.2023)
**וריאציה 3 — סעיף רלוונטי:** איזה סעיף בחוק הנוער עוסק בכך? ← סעיף 24. סעיף 24 לחוק הנוער (שפיטה, ענישה ודרכי טיפול)', 'קטינים ← אמות מידה דומות לבגירים ← אך איזונים שונים ← משקל יתר לשיקום.', '["חוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל\"א-1971, סעיף 24", "ע\"פ 3069/22 מדינת ישראל נ'' פלוני (20.12.2022)", "ע\"פ 7993/10 פלוני נ'' מדינת ישראל (22.07.2013)", "ע\"פ 8378/22 פלוני נ'' מדינת ישראל (26.07.2023)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''criminal_substantive'' subtopic=''youth_law'' | classifier_note: Avoidance of conviction for minors — youth law, post-Phase 4 subtopic | source_review_note: השאלה עוסקת בהימנעות מהרשעה של קטינים, נושא מרכזי בדיני עונשין וסדר דין פלילי הנוגע לקטינים. תת-הנושא ''משמעת עורכי דין'' אינו מתאים. יש לשקול הוספת תת-נושא כגון ''ענישת קטינים'' או ''הליכים בענייני נוער''.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא ניתן להימנע מהרשעה כאשר מדובר בקטין.', false, 'טענה זו שגויה. חוק הנוער (שפיטה, ענישה ודרכי טיפול) מאפשר לבית המשפט להימנע מהרשעת קטין, וזאת בניגוד לכלל הרחב החל על בגירים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על קטינים נשקלות אמות מידה דומות להימנעות מהרשעה כמו אלה של בגירים, וגם מערך האיזונים הוא דומה.', false, 'טענה זו שגויה. אמנם אמות המידה דומות, אך מערך האיזונים שונה באופן מהותי, כאשר לקטינים ניתן משקל יתר לשיקולי שיקום.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על קטינים נשקלות אמות מידה דומות להימנעות מהרשעה כמו אלה של בגירים, ואולם מערך האיזונים הוא שונה.', true, 'הפסיקה קבעה כי המתווה הכללי להכרעה בשאלת הימנעות מהרשעה דומה בין קטינים לבגירים (הלכת כתב), אך מערך האיזונים שונה. בעניינם של קטינים, ניתנים משקל יתר לנסיבותיהם האישיות, לסיכויי שיקומם ולאינטרס הציבורי בהשבתם לתפקוד נורמטיבי, והנכונות לסטות מחובת מיצוי הדין גדולה יותר.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'על קטינים נשקלות אמות מידה שונות להימנעות מהרשעה מאלה של בגירים, וגם מערך האיזונים הוא שונה.', false, 'טענה זו שגויה. אמות המידה הבסיסיות (הלכת כתב) דומות, אך הדגשים ומשקלי האיזון שונים באופן מהותי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הימנעות מהרשעה בעבירות חמורות',
    1, 'קטין בן 16 ביצע עבירת אלימות חמורה, אך לאחר מכן עבר תהליך שיקום מוצלח, והביע חרטה כנה. שירות המבחן המליץ להימנע מהרשעתו. האם בית המשפט מחויב לאמץ את ההמלצה ולהימנע מהרשעה?', 'שאלה זו בוחנת את האיזון העדין בין שיקולי שיקום קטינים לבין אינטרס הציבור במיצוי הדין, במיוחד כאשר מדובר בעבירות חמורות. היא מדגישה כי אף שחוק הנוער מעניק משקל יתר לשיקום, קטינות אינה חסינות מפני הרשעה בעבירות חמורות.', 'הפסיקה קבעה כי אף שבעניינם של קטינים ניתנים משקל יתר לנסיבותיהם האישיות ולסיכויי שיקומם, ''קטינות אינה יוצרת חסינות'' (ע"פ 7993/10 פלוני נ'' מדינת ישראל). במקרים של עבירות חמורות במיוחד, כגון עבירות מין או אלימות קשה, אינטרס הציבור (הרתעה, מניעה, גמול והגנה על הציבור) עשוי לגבור על השיקול השיקומי, ולהצדיק הרשעה, גם אם הקטין עבר תהליך שיקום מוצלח וקיימת המלצה חיובית של שירות המבחן (ע"פ 3069/22 מדינת ישראל נ'' פלוני; ע"פ 6123/23 מדינת ישראל נ'' פלוני). בית המשפט יבחן את מכלול הנסיבות, כולל חומרת העבירה, נסיבות ביצועה, הפגיעה בקורבן, ורקע הקטין, ויאזן ביניהם.',
    'הטעות הנפוצה היא להניח ששיקולי שיקום תמיד יגברו על אינטרס הציבור בעניינם של קטינים, ובכך להתעלם מחומרת העבירה ומעקרון ''קטינות אינה יוצרת חסינות''.', '["הימנעות מהרשעה", "קטינים", "עבירות חמורות", "שיקום", "אינטרס ציבורי", "קטינות אינה חסינות", "שירות המבחן"]'::jsonb, '**וריאציה 1 — חומרת העבירה:** האם חומרת העבירה משפיעה על הימנעות מהרשעה של קטין? ← כן, ככל שהעבירה חמורה יותר, אינטרס הציבור גובר. ע"פ 3069/22 מדינת ישראל נ'' פלוני (20.12.2022)
**וריאציה 2 — קטינות וחסינות:** האם קטינות יוצרת חסינות? ← לא, ''קטינות אינה יוצרת חסינות''. ע"פ 7993/10 פלוני נ'' מדינת ישראל (22.07.2013)
**וריאציה 3 — עבירות מין:** מה הדין בעבירות מין חמורות של קטינים? ← לרוב הרשעה, גם עם שיקום. ע"פ 3069/22 מדינת ישראל נ'' פלוני (20.12.2022)', 'קטין + עבירה חמורה ← אינטרס ציבורי גובר ← לרוב הרשעה.',
    '["ע\"פ 3069/22 מדינת ישראל נ'' פלוני (20.12.2022)", "ע\"פ 6266407 מדינת ישראל נ'' פלוני (22.02.2024)", "ע\"פ 7993/10 פלוני נ'' מדינת ישראל (22.07.2013)", "ע\"פ 2669/00 מדינת ישראל נ'' פלוני, נד(3) 685 (17.08.2000)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, שכן שיקום קטינים הוא שיקול מכריע, במיוחד כאשר קיימת המלצה חיובית של שירות המבחן.', false, 'טענה זו שגויה. אף ששיקום קטינים חשוב, הוא אינו שיקול מכריע בכל מקרה, ובית המשפט אינו מחויב לאמץ את המלצת שירות המבחן.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, במקרים של עבירות חמורות במיוחד, אינטרס הציבור במיצוי הדין גובר על שיקולי השיקום, גם אצל קטינים.', true, 'הפסיקה קבעה כי ''קטינות אינה יוצרת חסינות'', ובמקרים של עבירות חמורות, שיקולי הרתעה, מניעה וגמול עשויים לגבור על השיקול השיקומי, גם אם הקטין עבר תהליך שיקום מוצלח.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אלא אם כן לקטין עבר פלילי קודם בעבירות דומות.', false, 'טענה זו שגויה. אף שעבר פלילי הוא שיקול, חומרת העבירה הנוכחית לבדה יכולה להצדיק הרשעה, גם ללא עבר פלילי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אך רק אם הקטין לא הביע חרטה כנה על מעשיו.', false, 'טענה זו שגויה. חרטה כנה היא שיקול חשוב לזכות הקטין, אך היא אינה מבטיחה הימנעות מהרשעה במקרים של עבירות חמורות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחני הלכת כתב לקטינים',
    2, 'מהם שני התנאים המרכזיים שבית המשפט בוחן כאשר הוא שוקל הימנעות מהרשעה של קטין, וכיצד הם שונים מבגירים?', 'שאלה זו מתמקדת ביישום הלכת כתב, המתווה את אמות המידה להימנעות מהרשעה, על קטינים. היא מדגישה את ההבדל המהותי במערך האיזונים בין קטינים לבגירים, תוך מתן משקל יתר לשיקולי שיקום וטובת הקטין.', 'הלכת כתב קבעה שני תנאים מצטברים להימנעות מהרשעה: (1) האם סוג העבירה מאפשר להימנע מהרשעה, מבלי שיהיה בכך משום פגיעה מהותית בשיקולי ענישה אחרים; ו-(2) האם ההרשעה צפויה להביא לכדי פגיעה חמורה בסיכויי שיקומו של הנאשם. בעניינם של קטינים, אמות מידה אלו נשקלות, אך מערך האיזונים משתנה באופן מהותי. בעוד שאצל בגירים הימנעות מהרשעה היא חריג נדיר, אצל קטינים הנכונות לסטות מחובת מיצוי הדין גדולה יותר. זאת, תוך מתן משקל יתר לנסיבותיו האישיות של הקטין, לגילו, לנזק הצפוי לו מההרשעה, לאפשרויות הטיפול בו ולסיכויי שיקומו, וכן לאינטרס הציבורי בהשבתו לתפקוד נורמטיבי בחברה (ע"פ 3069/22 מדינת ישראל נ'' פלוני; ע"פ 9431949 מדינת ישראל נ'' פלוני).',
    'הטעות היא לחשוב שהלכת כתב אינה חלה על קטינים כלל, או לחילופין, ליישם אותה באופן זהה לבגירים, מבלי להתחשב בשינוי במערך האיזונים.', '["הלכת כתב", "הימנעות מהרשעה", "קטינים", "שיקום", "נזק מהרשעה", "אינטרס ציבורי", "מערך איזונים"]'::jsonb, '**וריאציה 1 — שתי שאלות:** מהן שתי השאלות המנחות בהלכת כתב? ← סוג העבירה והנזק לשיקום. תפח"ע (מחוזי תל אביב-יפו) 34379-09-24 מדינת ישראל נ'' פלוני (15.07.2025)
**וריאציה 2 — שינוי איזונים:** כיצד משתנה מערך האיזונים אצל קטינים? ← נכונות גדולה יותר להימנע מהרשעה, משקל יתר לנסיבות אישיות ושיקום. ע"פ 821/16 פלוני נ'' מדינת ישראל (19.07.2016)
**וריאציה 3 — אינטרס ציבורי:** איזה אינטרס ציבורי נוסף קיים אצל קטינים? ← השבת הקטין לתפקוד נורמטיבי. ע"פ 821/16 פלוני נ'' מדינת ישראל (19.07.2016)', 'הלכת כתב לקטינים ← שתי שאלות + איזונים שונים ← משקל יתר לשיקום.',
    '["ע\"פ 3069/22 מדינת ישראל נ'' פלוני (20.12.2022)", "תפח\"ע (מחוזי תל אביב-יפו) 34379-09-24 מדינת ישראל נ'' פלוני (15.07.2025)", "ע\"פ 8378/22 פלוני נ'' מדינת ישראל (26.07.2023)", "ע\"פ 2906/19 פלוני נ'' מדינת ישראל (14.07.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'האם הקטין הודה במעשיו, והאם יש לו עבר פלילי קודם.', false, 'טענה זו שגויה. אלו שיקולים רלוונטיים, אך אינם התנאים המרכזיים של הלכת כתב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'האם סוג העבירה מאפשר להימנע מהרשעה מבלי לפגוע בשיקולי ענישה אחרים, והאם ההרשעה תפגע קשה בשיקום הנאשם. אצל קטינים, הנכונות לסטות מחובת מיצוי הדין גדולה יותר.', true, 'הלכת כתב קבעה שני תנאים אלו. בעניינם של קטינים, מערך האיזונים משתנה, וניתן משקל יתר לנסיבותיהם האישיות, לגילם, לנזק הצפוי מההרשעה, לאפשרויות הטיפול ולסיכויי השיקום, והנכונות להימנע מהרשעה גדולה יותר מאשר אצל בגירים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'האם הקטין שיתף פעולה עם שירות המבחן, והאם יש לו תמיכה משפחתית.', false, 'טענה זו שגויה. אלו שיקולים חשובים בהערכת סיכויי שיקום, אך אינם התנאים המרכזיים של הלכת כתב.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'האם הקטין ביצע את העבירה תחת השפעה של אחרים, והאם הוא הביע חרטה.', false, 'טענה זו שגויה. אלו נסיבות מקלות אפשריות, אך אינן התנאים המרכזיים של הלכת כתב.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'המלצת שירות המבחן וסטייה ממנה',
    3, 'קטין ביצע עבירה, ושירות המבחן המליץ לבית המשפט להימנע מהרשעתו לאור תהליך שיקום מוצלח. האם בית המשפט מחויב לאמץ את המלצת שירות המבחן?', 'שאלה זו בוחנת את מעמדה של המלצת שירות המבחן בהליכים פליליים נגד קטינים. היא מדגישה את חשיבותה של המלצה זו ככלי מרכזי להערכת סיכויי שיקום, אך גם את סמכותו של בית המשפט לסטות ממנה מטעמים כבדי משקל, תוך איזון בין שיקולי שיקום לאינטרס הציבורי.', 'תסקיר שירות המבחן הוא כלי מרכזי בידי בית המשפט להערכת סיכויי שיקומו של נאשם, ובפרט בעניינם של קטינים, שם המחוקק התווה במפורש כי לשיקול השיקום יינתן משקל מיוחד (סעיף 1א לחוק הנוער). הפסיקה קבעה כי יש ליתן משנה תוקף להמלצת שירות המבחן, וכי אל לו לבית המשפט לסטות ממנה כאשר יש בנמצא אופק שיקומי, אלא מטעמים כבדי משקל (ע"פ 9813/16 פלוני נ'' מדינת ישראל; ע"פ 8717/16 פלוני נ'' מדינת ישראל). עם זאת, ההכרעה הסופית מוטלת על כתפי בית המשפט, ועליו לאזן את שיקול השיקום אל מול שיקולים נוספים, כגון חומרת העבירה ואינטרס הציבור (ע"פ 8378/22 פלוני נ'' מדינת ישראל).',
    'הנחה שקיימת חובה מוחלטת לאמץ את המלצת שירות המבחן, ובכך התעלמות מסמכותו של בית המשפט לאזן בין השיקולים השונים.', '["שירות המבחן", "המלצת שירות המבחן", "הימנעות מהרשעה", "קטינים", "שיקום", "אינטרס ציבורי", "טעמים כבדי משקל"]'::jsonb, '**וריאציה 1 — מעמד ההמלצה:** האם המלצת שירות המבחן מחייבת? ← לא, אך יש ליתן לה משקל רב. ע"פ 8378/22 פלוני נ'' מדינת ישראל (26.07.2023)
**וריאציה 2 — סטייה מהמלצה:** מתי ניתן לסטות מהמלצה חיובית? ← מטעמים כבדי משקל. ע"פ 8717/16 פלוני נ'' מדינת ישראל (25.06.2017)
**וריאציה 3 — איזון שיקולים:** מה בית המשפט מאזן? ← שיקום מול חומרת העבירה ואינטרס ציבורי. ע"פ 8378/22 פלוני נ'' מדינת ישראל (26.07.2023)', 'המלצת שירות המבחן ← אינה מחייבת ← סטייה מטעמים כבדי משקל.',
    '["ע\"פ 8378/22 פלוני נ'' מדינת ישראל (26.07.2023)", "ע\"פ 9813/16 פלוני נ'' מדינת ישראל (15.06.2017)", "ע\"פ 8717/16 פלוני נ'' מדינת ישראל (25.06.2017)", "חוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל\"א-1971, סעיף 1א"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, המלצת שירות המבחן מחייבת את בית המשפט בעניינם של קטינים, אלא אם כן היא בלתי סבירה בעליל.', false, 'טענה זו שגויה. המלצת שירות המבחן אינה מחייבת את בית המשפט, אף שהיא בעלת משקל רב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, המלצת שירות המבחן אינה מחייבת את בית המשפט, אך סטייה ממנה דורשת טעמים כבדי משקל.', true, 'הפסיקה קבעה כי תסקיר שירות המבחן הוא כלי מרכזי להערכת סיכויי שיקום, ובעניינם של קטינים יש ליתן לו משקל רב. עם זאת, ההכרעה הסופית נתונה לבית המשפט, וסטייה מהמלצה חיובית דורשת טעמים כבדי משקל.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם המלצת שירות המבחן נתמכת בחוות דעת פסיכולוגית או פסיכיאטרית.', false, 'טענה זו שגויה. אף שחוות דעת נוספות יכולות לחזק את ההמלצה, הן אינן תנאי הכרחי למעמדה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, בית המשפט רשאי לסטות מהמלצת שירות המבחן ללא צורך בטעמים מיוחדים, שכן הוא הריבון.', false, 'טענה זו שגויה. אף שבית המשפט הוא הריבון, סטייה מהמלצת שירות המבחן, במיוחד בענייני קטינים, דורשת טעמים כבדי משקל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'דרכי טיפול חלופיות לקטינים',
    4, 'בית המשפט לנוער קבע כי קטין ביצע עבירה, אך החליט שלא להרשיעו. אילו דרכי טיפול חלופיות, מבין הבאות, יכול בית המשפט לצוות עליו?', 'שאלה זו מתמקדת באפשרויות הטיפול והענישה החלופיות העומדות בפני בית המשפט לנוער כאשר הוא מחליט שלא להרשיע קטין שביצע עבירה. היא מדגישה את הגמישות והמגוון של הכלים הטיפוליים הקבועים בחוק הנוער, המאפשרים התאמה לנסיבותיו הייחודיות של כל קטין.', 'סעיף 24 לחוק הנוער (שפיטה, ענישה ודרכי טיפול) קובע כי לאחר שבית המשפט לנוער קבע שקטין ביצע עבירה, הוא רשאי להחליט על אחת משלוש חלופות: להרשיע ולגזור דין, לצוות על אמצעים ודרכי טיפול ללא הרשעה, או לפטור את הקטין ללא צו כלל. דרכי הטיפול שניתן לצוות עליהן ללא הרשעה מפורטות בסעיף 26 לחוק הנוער, וכוללות בין היתר: העמדת הקטין במבחן, שהייה במעון יומי, קבלת התחייבות מהקטין או הורהו, וחיוב הקטין או הורהו בתשלום פיצוי לאדם שניזוק באותה עבירה. אפשרויות אלו משקפות את הגישה השיקומית המודגשת בחוק הנוער.',
    'הבלבול בין עונשים המוטלים לאחר הרשעה (כגון מאסר) לבין דרכי טיפול חלופיות המוטלות במקרה של אי-הרשעה.', '["חוק הנוער", "הימנעות מהרשעה", "דרכי טיפול", "צו מבחן", "פיצויים", "מעון יומי", "סעיף 24 לחוק הנוער", "סעיף 26 לחוק הנוער"]'::jsonb, '**וריאציה 1 — סמכות בית המשפט:** מהן האפשרויות של בית המשפט לאחר קביעת ביצוע עבירה על ידי קטין? ← הרשעה, דרכי טיפול ללא הרשעה, או פטור ללא צו. סעיף 24 לחוק הנוער (שפיטה, ענישה ודרכי טיפול)
**וריאציה 2 — דרכי טיפול לדוגמה:** אילו דרכי טיפול ניתן לצוות ללא הרשעה? ← צו מבחן, שהייה במעון יומי, התחייבות, פיצויים. סעיף 26 לחוק הנוער (שפיטה, ענישה ודרכי טיפול)
**וריאציה 3 — פיצוי ללא הרשעה:** האם ניתן לחייב בפיצוי ללא הרשעה? ← כן, אך לא כעונש יחיד. יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | ח. העונשים שניתן להטיל על נאשם שבית משפט נמנע מהרשעתו', 'אי-הרשעה לקטין ← דרכי טיפול (סעיף 26) ← צו מבחן, מעון יומי, פיצוי.',
    '["חוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל\"א-1971, סעיפים 24, 26", "יורם רבין, יניב ואקי דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 12 אי הרשעה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'מאסר בפועל.', false, 'טענה זו שגויה. מאסר בפועל הוא עונש המוטל לאחר הרשעה, ולא כדרך טיפול חלופית לאי-הרשעה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'צו מבחן, שהייה במעון יומי, או חיוב בפיצויים.', true, 'סעיף 24(2) לחוק הנוער, יחד עם סעיף 26, מאפשרים לבית המשפט לצוות על דרכי טיפול שונות ללא הרשעה, כגון העמדה במבחן, שהייה במעון יומי, קבלת התחייבות, או חיוב בפיצויים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'קנס כספי בלבד, ללא כל אמצעי טיפולי נוסף.', false, 'טענה זו שגויה. אף שניתן לחייב בקנס, לרוב הוא יוטל לצד אמצעי טיפולי אחר, ואינו מהווה את מכלול דרכי הטיפול האפשריות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'שליחת הקטין למאסר על תנאי.', false, 'טענה זו שגויה. מאסר על תנאי הוא עונש המוטל לאחר הרשעה, ולא כדרך טיפול חלופית לאי-הרשעה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 33, '2023-S-S-Q33';
END
$$;

