  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q34', v_chapter_id, v_subtopic_id, 'ביום 5.3.2021 נפצעה סילביה בתאונת דרכים ואושפזה בבית-חולים כשנשקפת סכנה לחייה. בעודה בבית החולים ציוותה סילביה בעל פה את אדמותיה שבנצרת לשתי בנותיה בפני שני עדים בעת שבאו לבקרה ולדרוש בשלומה. סילביה ציינה בפני העדים כי היא חשה שימיה ספורים. העדים רשמו זיכרון דברים והפקידו אותו אצל הרשם לענייני ירושה כעבור שבוע ממועד ביקורם אצל סילביה. תחושותיה של סילביה התבררו כנכונות, מצבה המשיך להידרדר, והיא הלכה לעולמה ביום 25.4.2021. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 34}'::jsonb, 'השאלה עוסקת בתנאים המצטברים הנדרשים לקיומה של צוואה בעל פה (צוואת שכיב מרע) לפי סעיף 23 לחוק הירושה. היא בוחנת את הדרישות הפורמליות והמהותיות, ובפרט את חובת רישום והפקדת זיכרון הדברים ''ככל האפשר בסמוך'' למועד עשיית הצוואה, ואת השלכות אי-העמידה בדרישה זו על תוקף הצוואה.', 'סעיף 23 לחוק הירושה, התשכ"ה-1965, קובע את התנאים לעריכת צוואה בעל פה. תנאים אלו כוללים, בין היתר, כי המצווה יהיה ''שכיב מרע'' או ''מי שרואה עצמו, בנסיבות המצדיקות זאת, מול פני המוות'', וכי דברי המצווה ייאמרו בפני שני עדים השומעים לשונו. במקרה של סילביה, נראה כי תנאים אלו התקיימו. אולם, סעיף 23(ב) מוסיף ודורש כי ''דברי המצווה... יירשמו בזכרון דברים שייחתם בידי שני העדים ויופקד על ידיהם אצל רשם לעניני ירושה; רישום, חתימה והפקדה כאמור ייעשו ככל האפשר בסמוך לאחר שניתן לעשותם''. הפסיקה מפרשת דרישה זו באופן קפדני, וקבעה כי גם איחור קצר בהעלאת הצוואה על הכתב והפקדתה אינו עומד בדרישות הסעיף. איחור של שבוע ברישום והפקדת זיכרון הדברים, כאשר ניתן היה לעשות זאת קודם לכן, מהווה פגם מהותי. אף שסעיף 25 לחוק הירושה מאפשר לבית המשפט לרפא פגמים צורניים שאינם ''מרכיבי יסוד'' (כמו דרישת הרישום וההפקדה), זאת רק אם ''לא היה לבית המשפט ספק כי היא משקפת את רצונו החופשי והאמיתי של המצווה''. בהיעדר נסיבות מיוחדות המצדיקות את האיחור, ובהתחשב בזהירות היתרה בה בוחנים בתי המשפט צוואות בעל פה, סביר להניח שהצוואה לא תקוים.', 'הטעות הנפוצה היא להתמקד רק בתנאי היסוד של מצב המצווה והעדים, ולהתעלם מהדרישה הקפדנית לרישום והפקדת זיכרון הדברים ''ככל האפשר בסמוך''. יש לזכור שצוואה בעל פה היא חריג לכלל, ודרישותיה מפורשות ומצטברות.',
    '["צוואה בעל פה", "שכיב מרע", "מול פני המוות", "זיכרון דברים", "הפקדת צוואה", "סעיף 23 לחוק הירושה", "סעיף 25 לחוק הירושה", "פגמים בצוואה"]'::jsonb, '**וריאציה 1 — דרישת הסמיכות:** מהי דרישת ''ככל האפשר בסמוך''? ← רישום, חתימה והפקדה של זיכרון הדברים בסמוך ככל הניתן. סעיף 23(ב) לחוק הירושה, תשכ"ה-1965
**וריאציה 2 — איחור קצר:** האם איחור קצר פוסל? ← כן, איחור קצר בהרבה אינו עומד בדרישות סעיף 23. ת"ע (משפחה תל אביב-יפו) 36776-06-18 ש'' ב'' נ'' האפוטרופוס הכללי במחוז תל-אביב (27.12.2021)
**וריאציה 3 — ריפוי פגמים:** האם ניתן לרפא פגם זה? ← כן, מכוח סעיף 25, אם אין ספק ברצון המצווה, אך דרישת הסמיכות חשובה. ע"א 631/88 חנה קהא נ'' שלום לוי (06.08.1990)', 'צוואה בעל פה ← דורשת רישום והפקדה ''ככל האפשר בסמוך'' ← איחור של שבוע פוגם בתוקף.', '["חוק הירושה, תשכ\"ה-1965, סעיפים 23, 25", "ת\"ע (משפחה תל אביב-יפו) 36776-06-18 ש'' ב'' נ'' האפוטרופוס הכללי במחוז תל-אביב (27.12.2021)", "ע\"א 631/88 חנה קהא נ'' שלום לוי (06.08.1990)", "תלה\"מ (משפחה קריות) 37373-10-20 מ.א.ז נ'' האפוטרופוס הכללי מחוז חיפה והצפון (10.03.2024)", "בני דון-יחייא תורת דיני הירושה (2024) | צוואה בעל פה - צוואת \"שְׁכיב מְרַע\""]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''family_inheritance'' subtopic=''inheritance_will'' | classifier_note: Oral deathbed will (צוואה בעל פה) after road accident — sec. 23 חוק הירושה | source_review_note: השאלה עוסקת בדיני ירושה, תחום שאינו משתלב באופן ישיר באף אחד מתתי-הנושאים הקיימים תחת ''סדר דין אזרחי''. סווגה תחת ''הליכים'' כהצבת מקום זמנית, אך יש לשקול הוספת תת-נושא מתאים יותר לדיני ירושה.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'סילביה לא הייתה רשאית לערוך את הצוואה משום שנטתה למות.', false, 'טענה זו שגויה. סעיף 23(א) לחוק הירושה מאפשר במפורש למי ש''שכיב מרע'' או ''רואה עצמו מול פני המוות'' לצוות בעל פה, וזהו בדיוק המצב בו הייתה סילביה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'סילביה הייתה רשאית לערוך את הצוואה, אך הצוואה אינה בתוקף.', true, 'סילביה הייתה רשאית לערוך את הצוואה שכן עמדה בתנאי היסוד של ''שכיב מרע'' או ''מול פני המוות''. אולם, הצוואה אינה בתוקף בשל אי-עמידה בדרישת סעיף 23(ב) לחוק הירושה, המחייבת רישום, חתימה והפקדה של זיכרון הדברים ''ככל האפשר בסמוך'' לאחר עשיית הצוואה. איחור של שבוע נחשב לפגם מהותי שאינו עומד בדרישה זו, ובהיעדר נסיבות מיוחדות, עלול להביא לפסילת הצוואה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'סילביה הייתה רשאית לערוך את הצוואה, והצוואה תקפה.', false, 'טענה זו שגויה. אף שסילביה הייתה רשאית לערוך את הצוואה, הפגם ברישום והפקדת זיכרון הדברים ''ככל האפשר בסמוך'' הופך את הצוואה ללא תקפה, אלא אם כן בית המשפט יחליט לרפא את הפגם מכוח סעיף 25 לחוק הירושה, דבר שאינו מובטח.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'סילביה לא הייתה רשאית לערוך את הצוואה כי אין נסיבות שמצדיקות זאת.', false, 'טענה זו שגויה. מצבה של סילביה, שנפצעה בתאונת דרכים ונשקפה סכנה לחייה, וכן תחושתה כי ימיה ספורים, מצדיקים בהחלט את עשיית הצוואה בעל פה לפי סעיף 23(א) לחוק הירושה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הבחנה בין ''שכיב מרע'' ל''מול פני המוות''',
    1, 'ראובן סובל ממחלה כרונית קשה מזה שנים, אך מצבו יציב ואינו נשקפת סכנה מיידית לחייו. הוא חש חולשה כללית וקשיי תפקוד, ובעקבות זאת ציווה בעל פה את רכושו בפני שני עדים. האם ראובן עומד בתנאי ''שכיב מרע'' או ''מול פני המוות'' לצורך עריכת צוואה בעל פה?', 'שאלה זו עוסקת בפרשנות המונחים ''שכיב מרע'' ו''מי שרואה עצמו, בנסיבות המצדיקות זאת, מול פני המוות'' בסעיף 23 לחוק הירושה. הפסיקה מפרשת דרישות אלו באופן מצמצם, כדי להבטיח שצוואה בעל פה תוכר רק במצבים חריגים וייחודיים, בהם המצווה נעדר יכולת או זמן לערוך צוואה בכתב.', 'סעיף 23(א) לחוק הירושה קובע כי צוואה בעל פה יכולה להיעשות על ידי ''שכיב מרע'' או ''מי שרואה עצמו, בנסיבות המצדיקות זאת, מול פני המוות''. הפסיקה פירשה את המונח ''שכיב מרע'' כמתייחס לאדם הלוקה במחלה קשה ונמצא על ערש דווי, במצב אובייקטיבי של סכנת חיים מיידית. החלופה השנייה, ''מול פני המוות'', דורשת הן יסוד סובייקטיבי (תחושת המצווה) והן יסוד אובייקטיבי (נסיבות מצדיקות). מחלה כרונית קשה, גם אם היא גורמת לחולשה וקשיי תפקוד, אינה מספיקה כשלעצמה כדי לעמוד בדרישות אלו, אם אין סכנה מיידית לחיי המצווה. המטרה היא לצמצם את המקרים בהם תוכר צוואה בעל פה, שכן היא צורה פחות מהימנה של צוואה.',
    'הטעות הנפוצה היא להרחיב את הפרשנות של ''שכיב מרע'' או ''מול פני המוות'' למצבים רפואיים שאינם כוללים סכנת חיים מיידית, ובכך לרוקן מתוכן את הדרישה המצמצמת של החוק.', '["צוואה בעל פה", "שכיב מרע", "מול פני המוות", "יסוד אובייקטיבי", "יסוד סובייקטיבי", "פרשנות מצמצמת"]'::jsonb, '**וריאציה 1 — הגדרת שכיב מרע:** מהו ''שכיב מרע'' לפי הפסיקה? ← אדם הלוקה במחלה קשה ונמצא על ערש דווי, במצב אובייקטיבי של סכנת חיים מיידית. ת"ע (משפחה תל אביב-יפו) 36776-06-18 ש'' ב'' נ'' האפוטרופוס הכללי במחוז תל-אביב (27.12.2021)
**וריאציה 2 — מול פני המוות:** מה נדרש ל''מול פני המוות''? ← יסוד סובייקטיבי (תחושה) ויסוד אובייקטיבי (נסיבות מצדיקות). ע"א 631/88 חנה קהא נ'' שלום לוי (06.08.1990)
**וריאציה 3 — פרשנות מצמצמת:** מדוע הפרשנות מצמצמת? ← כדי להבטיח את אמינות הצוואה בעל פה. תלה"מ (משפחה קריות) 37373-10-20 מ.א.ז נ'' האפוטרופוס הכללי מחוז חיפה והצפון (10.03.2024)', '''שכיב מרע''/''מול פני המוות'' ← דורש סכנה מיידית אובייקטיבית וסובייקטיבית ← פרשנות מצמצמת.',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 23(א)", "ת\"ע (משפחה תל אביב-יפו) 36776-06-18 ש'' ב'' נ'' האפוטרופוס הכללי במחוז תל-אביב (27.12.2021)", "ע\"א 631/88 חנה קהא נ'' שלום לוי (06.08.1990)", "תלה\"מ (משפחה קריות) 37373-10-20 מ.א.ז נ'' האפוטרופוס הכללי מחוז חיפה והצפון (10.03.2024)", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | צוואה בעל-פה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, שכן מחלה כרונית קשה, גם אם אינה מסכנת חיים מיידית, יכולה להיחשב כ''שכיב מרע''.', false, 'טענה זו שגויה. הפסיקה מפרשת את המונח ''שכיב מרע'' באופן מצמצם, ודורשת מצב אובייקטיבי של סכנת חיים מיידית, ולא רק מחלה כרונית קשה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, ''שכיב מרע'' דורש מצב אובייקטיבי של סכנת חיים מיידית, ו''מול פני המוות'' דורש גם תחושה סובייקטיבית של מוות קרוב בנסיבות מצדיקות.', true, 'הפסיקה מפרשת את המונחים ''שכיב מרע'' ו''מול פני המוות'' באופן מצמצם. ''שכיב מרע'' מתייחס למצב רפואי אובייקטיבי של אדם הלוקה במחלה קשה ונמצא על ערש דווי. ''מול פני המוות'' דורש הן יסוד אובייקטיבי (נסיבות מצדיקות) והן יסוד סובייקטיבי (תחושה של מוות קרוב). מחלה כרונית יציבה, ללא סכנה מיידית, אינה עונה על דרישות אלו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אם ראובן חש סובייקטיבית שהוא מול פני המוות, די בכך לעריכת צוואה בעל פה.', false, 'טענה זו שגויה. החלופה של ''מול פני המוות'' דורשת גם יסוד אובייקטיבי של ''נסיבות מצדיקות'', ולא רק תחושה סובייקטיבית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן מצבו הרפואי אושר על ידי חוות דעת רפואית כ''שכיב מרע''.', false, 'טענה זו שגויה. אף שחוות דעת רפואית חשובה, היא אינה תנאי בלעדיו אין, וההכרעה היא משפטית על בסיס מכלול הנסיבות והמבחנים שנקבעו בפסיקה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'דרישת גמירות דעת ונטל ההוכחה',
    2, 'מהי דרישת ''גמירות הדעת'' בצוואה בעל פה, ועל מי מוטל נטל ההוכחה לקיומה?', 'שאלה זו מתמקדת בדרישת גמירות הדעת בצוואה בעל פה, שהיא דרישה מהותית שנוספה בפסיקה לדרישות הצורניות הקבועות בחוק. היא מדגישה את החשיבות של הוכחת כוונת המצווה שהאמירה תשמש כצוואה, ואת נטל ההוכחה הכבד המוטל על המבקש לקיים צוואה מסוג זה.', 'הפסיקה הוסיפה דרישה שישית בסיסית לצוואה בעל פה, הנדרשת גם ביחס ליתר סוגי הצוואות, והיא הוכחת גמירות דעתו של המצווה בשני היבטים: (1) אמירת המצווה הייתה מכוונת לשמש כצוואה; (2) הייתה למצווה גמירות דעת באשר לתוכן הציווי. על בית המשפט להשתכנע מעל לכל ספק כי מדובר בצוואה אמיתית המשקפת את רצונו החופשי והאמיתי של המצווה. נטל ההוכחה בדבר קיומן של דרישות אלו, כמו גם יתר הדרישות המצטברות שבסעיף 23 לחוק הירושה, מוטל על המבקש לקיים את הצוואה שבעל פה. מדובר בנטל כבד, בשל הצורך להוכיח את רצון המצווה ואת נסיבות עריכת הצוואה, ונוכח העדר רמת הביטחון הקיימת בצוואה בכתב.',
    'הטעות היא להניח שדי בעמידה בדרישות הצורניות של סעיף 23 לחוק הירושה, מבלי להבין שדרישת גמירות הדעת היא דרישה מהותית ועצמאית, וכי נטל ההוכחה בצוואה בעל פה הוא כבד במיוחד.', '["גמירות דעת", "צוואה בעל פה", "נטל הוכחה", "רצון המצווה", "אמיתות הצוואה", "דרישות יסוד"]'::jsonb, '**וריאציה 1 — דרישת גמירות דעת:** מהם שני היבטי גמירות הדעת? ← האמירה נועדה לשמש כצוואה, וגמירות דעת לתוכן הציווי. ת"ע (משפחה נצרת) 19103-02-20 פלוניות נ'' פלונית (31.03.2025)
**וריאציה 2 — נטל ההוכחה:** על מי מוטל נטל ההוכחה? ← על המבקש לקיים את הצוואה, בנטל כבד. ת"ע (משפחה תל אביב-יפו) 36776-06-18 ש'' ב'' נ'' האפוטרופוס הכללי במחוז תל-אביב (27.12.2021)

**וריאציה 3 — זהירות יתרה:** כיצד בית המשפט בוחן צוואה בעל פה? ← בזהירות יתרה ומעל לכל ספק. ת"ע (משפחה נצרת) 19103-02-20 פלוניות נ'' פלונית (31.03.2025)', 'גמירות דעת כפולה ← נטל הוכחה כבד על המבקש ← בית המשפט בוחן בזהירות יתרה.',
    '["ת\"ע (משפחה נצרת) 19103-02-20 פלוניות נ'' פלונית (31.03.2025)", "ת\"ע (משפחה תל אביב-יפו) 36776-06-18 ש'' ב'' נ'' האפוטרופוס הכללי במחוז תל-אביב (27.12.2021)", "ע\"א 115258 יוסף אהרן נ'' אמנון אהרוני (22.03.2005)", "ת\"ע (משפחה טבריה) 56416-05-14 פלונים נ'' פלונית (31.01.2018)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'גמירות דעת אינה נדרשת בצוואה בעל פה, שכן היא נעשית בנסיבות חירום.', false, 'טענה זו שגויה. דרישת גמירות הדעת היא דרישת יסוד בכל סוגי הצוואות, ובצוואה בעל פה אף ביתר שאת, בשל אופייה הפחות פורמלי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'נדרשת גמירות דעת שהאמירה תשמש כצוואה וגמירות דעת לתוכן הציווי, ונטל ההוכחה מוטל על המבקש לקיים את הצוואה.', true, 'הפסיקה הוסיפה דרישה שישית לצוואה בעל פה, והיא הוכחת גמירות דעתו של המצווה בשני היבטים: שהאמירה נועדה לשמש כצוואה, ושהייתה גמירות דעת באשר לתוכן הציווי. נטל ההוכחה לקיומן של דרישות אלו, כמו גם יתר הדרישות, מוטל על המבקש לקיים את הצוואה, והוא נטל כבד במיוחד.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'נדרשת גמירות דעת לתוכן הציווי בלבד, ונטל ההוכחה מוטל על המתנגד לקיום הצוואה.', false, 'טענה זו שגויה. נדרשת גמירות דעת כפולה (למעמד האמירה ולתוכן), ונטל ההוכחה מוטל על המבקש לקיים את הצוואה, בניגוד לצוואה בכתב.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'נדרשת גמירות דעת שהאמירה תשמש כצוואה בלבד, ונטל ההוכחה מוטל על בית המשפט.', false, 'טענה זו שגויה. נדרשת גמירות דעת כפולה, ונטל ההוכחה מוטל על המבקש לקיים את הצוואה, לא על בית המשפט.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'עדים זוכים בצוואת שכיב מרע',
    3, 'יוסף, שהיה ''שכיב מרע'', ציווה בעל פה את רכושו לשני חבריו, ראובן ושמעון, בפניהם. ראובן ושמעון הם גם העדים לצוואה. האם העובדה שראובן ושמעון הם גם הזוכים בצוואה פוסלת אותם מלשמש כעדים?', 'שאלה זו בוחנת את החריג הקבוע בסעיף 35 לחוק הירושה, המאפשר לעדים לצוואה בעל פה להיות גם זוכים בה, בניגוד לכלל החל על יתר סוגי הצוואות. חריג זה נובע מהנסיבות הייחודיות של עריכת צוואה בעל פה, בהן לעיתים קרובות אין אפשרות למצוא עדים שאינם בעלי עניין.', 'סעיף 35 לחוק הירושה קובע כלל לפיו הוראת צוואה המזכה את מי שערך אותה או היה עד לעשייתה – בטלה. אולם, הסעיף קובע חריג מפורש לצוואה בעל פה, וקובע כי איסור זה אינו חל עליה. המשמעות היא שעדי צוואת שכיב מרע יכולים להיות גם זוכים בצוואה. חריג זה נובע מההכרה בכך שבנסיבות של ''שכיב מרע'' או ''מול פני המוות'', לעיתים קרובות אין למצווה ברירה אלא לצוות בפני מי שנמצא לידו, גם אם הם בעלי עניין בצוואה. עם זאת, בית המשפט יבחן צוואה כזו בזהירות יתרה, כדי לוודא את אמיתות רצון המצווה ואת היעדר השפעה בלתי הוגנת.',
    'הטעות היא להחיל את הכלל הכללי שבסעיף 35 לחוק הירושה (פסילת עד זוכה) על צוואה בעל פה, מבלי לזכור את החריג המפורש הקבוע באותו סעיף.', '["צוואה בעל פה", "עדים זוכים", "סעיף 35 לחוק הירושה", "חריג לכלל", "השפעה בלתי הוגנת", "אמיתות הצוואה"]'::jsonb, '**וריאציה 1 — עד זוכה:** האם עד לצוואה בעל פה יכול להיות זוכה? ← כן, סעיף 35 לחוק הירושה מחריג צוואה בעל פה. סעיף 35 לחוק הירושה, תשכ"ה-1965
**וריאציה 2 — ניגוד לצוואה בעדים:** מה ההבדל מול צוואה בעדים? ← בצוואה בעדים, עד זוכה נפסל. ת"ע (משפחה נצרת) 19103-02-20 פלוניות נ'' פלונית (31.03.2025)
**וריאציה 3 — רציונל החריג:** מדוע קיים חריג זה? ← בנסיבות חירום, אין ברירה אלא לצוות בפני מי שנמצא. בני דון-יחייא תורת דיני הירושה (2024) | צוואה בעל פה - צוואת "שְׁכיב מְרַע"', 'עד זוכה בצוואה בעל פה ← מותר לפי סעיף 35 ← חריג לכלל הכללי.',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 35", "ת\"ע (משפחה נצרת) 19103-02-20 פלוניות נ'' פלונית (31.03.2025)", "בני דון-יחייא תורת דיני הירושה (2024) | צוואה בעל פה - צוואת \"שְׁכיב מְרַע\""]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, סעיף 35 לחוק הירושה פוסל עדים שהם גם זוכים בכל סוגי הצוואות.', false, 'טענה זו שגויה. סעיף 35 לחוק הירושה קובע חריג מפורש לצוואה בעל פה, המאפשר לעדים להיות גם זוכים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, סעיף 35 לחוק הירושה קובע במפורש כי איסור זה אינו חל על צוואה בעל פה.', true, 'סעיף 35 לחוק הירושה קובע כי הוראת צוואה המזכה את מי שהיה עד לעשייתה – בטלה. אולם, הסעיף קובע חריג מפורש לצוואה בעל פה, וקובע כי איסור זה אינו חל עליה. לכן, עדי צוואת שכיב מרע יכולים להיות גם זוכים בצוואה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן בית המשפט השתכנע מעל לכל ספק באמיתות הצוואה.', false, 'טענה זו שגויה. אף ששכנוע בית המשפט באמיתות הצוואה הוא תמיד נדרש, החריג בסעיף 35 לצוואה בעל פה הוא מוחלט ואינו מותנה בשכנוע נוסף.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אך רק אם העדים אינם קרובי משפחה של המצווה.', false, 'טענה זו שגויה. הקרבה המשפחתית אינה רלוונטית לחריג שבסעיף 35 לחוק הירושה, המאפשר לעדים בצוואה בעל פה להיות זוכים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'בטלות צוואה בעל פה',
    4, 'משה, שהיה ''שכיב מרע'', ציווה בעל פה את רכושו בפני שני עדים. שבוע לאחר מכן, מצבו השתפר באופן משמעותי, והוא שוחרר מבית החולים. חודש וחצי לאחר שחרורו, בעודו בחיים, נפטר משה מסיבה אחרת. מה דינה של הצוואה בעל פה?', 'שאלה זו עוסקת בתנאי הבטלות האוטומטית של צוואה בעל פה, הקבוע בסעיף 23(ג) לחוק הירושה. היא מדגישה את אופייה הזמני של צוואה זו, ואת חשיבות חלוף הנסיבות שהצדיקו את עשייתה כטריגר לבטלותה, אם המצווה נותר בחיים.', 'סעיף 23(ג) לחוק הירושה קובע כי ''צוואה בעל-פה בטלה כעבור חודש ימים לאחר שחלפו הנסיבות שהצדיקו עשייתה והמצווה עודנו בחיים''. במקרה הנדון, משה היה ''שכיב מרע'' וציווה בעל פה. שבוע לאחר מכן, מצבו השתפר והוא שוחרר מבית החולים – זהו המועד שבו ''חלפו הנסיבות שהצדיקו עשייתה''. מאותו מועד, עבר חודש וחצי (יותר מחודש), ובמהלך תקופה זו משה עודנו היה בחיים. לכן, הצוואה בטלה באופן אוטומטי מכוח סעיף 23(ג), ללא קשר לסיבת מותו המאוחרת יותר.',
    'הטעות היא להתעלם מהתנאי הכפול של סעיף 23(ג) – חלוף הנסיבות *וגם* חלוף חודש ימים *וגם* היות המצווה בחיים. יש להבין שצוואה בעל פה היא בעלת תוקף זמני בלבד.', '["צוואה בעל פה", "בטלות צוואה", "סעיף 23(ג) לחוק הירושה", "חלוף נסיבות", "תוקף זמני", "שכיב מרע"]'::jsonb, '**וריאציה 1 — תנאי בטלות:** מהם תנאי הבטלות של צוואה בעל פה? ← חלפו הנסיבות, עבר חודש, המצווה עודנו בחיים. סעיף 23(ג) לחוק הירושה, תשכ"ה-1965
**וריאציה 2 — מועד חלוף הנסיבות:** מתי חלפו הנסיבות במקרה זה? ← עם שיפור מצבו ושחרורו מבית החולים. ת"ע (משפחה תל אביב-יפו) 36776-06-18 ש'' ב'' נ'' האפוטרופוס הכללי במחוז תל-אביב (27.12.2021)

**וריאציה 3 — תוקף זמני:** מה אופייה של צוואה בעל פה? ← תוקף זמני, מוגבל בזמן. שמואל שילה פירוש לחוק הירושה כרך א (1995) | א. כללי', 'צוואה בעל פה ← בטלה אוטומטית ← חודש לאחר חלוף נסיבות + מצווה חי.',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 23(ג)", "ת\"ע (משפחה תל אביב-יפו) 36776-06-18 ש'' ב'' נ'' האפוטרופוס הכללי במחוז תל-אביב (27.12.2021)", "שמואל שילה פירוש לחוק הירושה כרך א (1995) | א. כללי", "נבו - המתמחה ירושה וברירת הדין | התיישנות | שטרות (2026) | צוואה בעל-פה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'הצוואה תקפה, שכן משה נפטר בטרם חלפו הנסיבות שהצדיקו את עשייתה.', false, 'טענה זו שגויה. הנסיבות שהצדיקו את עשיית הצוואה חלפו עם שיפור מצבו ושחרורו מבית החולים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'הצוואה בטלה, שכן חלפו הנסיבות שהצדיקו את עשייתה ועבר חודש ימים מאז, בעוד המצווה עודנו בחיים.', true, 'סעיף 23(ג) לחוק הירושה קובע כי צוואה בעל פה בטלה כעבור חודש ימים לאחר שחלפו הנסיבות שהצדיקו את עשייתה, ובתנאי שהמצווה עודנו בחיים. במקרה זה, הנסיבות חלפו עם שיפור מצבו של משה, ולאחר חודש וחצי (יותר מחודש) הוא עדיין היה בחיים, ולכן הצוואה בטלה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'הצוואה תקפה, שכן משה נפטר בסופו של דבר, ורצונו האחרון צריך להתקיים.', false, 'טענה זו שגויה. אף שכיבוד רצון המת הוא עקרון חשוב, הוא כפוף לדרישות הפורמליות של החוק, ובמקרה זה, הצוואה בטלה מכוח סעיף 23(ג).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'הצוואה בטלה, שכן לא הופקדה אצל הרשם לענייני ירושה במועד.', false, 'טענה זו שגויה. אף שאי-הפקדה במועד היא פגם, במקרה זה הצוואה בטלה מכוח סעיף 23(ג) בשל חלוף הזמן לאחר חלוף הנסיבות, ולאו דווקא בשל פגם ההפקדה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 34, '2023-S-S-Q34';
END
