  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q35', v_chapter_id, v_subtopic_id, 'מרק, תושב קנדה, נפטר והניח קרקעות וכן מיטלטלין וכספים בחשבונות בנק בישראל, בקנדה, בצרפת ובספרד. הדין בספרד אינו מאפשר הורשת מקרקעין שבתחומה והורשת כספים בחשבונות בנק ספרדיים אלא לפי הדין הספרדי, ואילו הדין שבצרפת אינו מחייב להחיל על קרקע צרפתית וכן על נכסים שבתחומה את דין צרפת באופן בלעדי. הוגשה בקשה לצו ירושה בישראל. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 35}'::jsonb, 'השאלה עוסקת בכללי ברירת הדין במשפט הבינלאומי הפרטי לעניין ירושה, כפי שנקבעו בפרק השביעי לחוק הירושה, התשכ"ה-1965. היא בוחנת את יישום סעיף 137 (דין מושבו של המוריש) וסעיף 138 (דין מקום הימצאם של מקרקעין), תוך התייחסות למקרים בהם דין זר קובע כללים ספציפיים או מאפשר הפניה (Renvoi).', 'על פי סעיף 137 לחוק הירושה, הכלל הוא שעל הירושה יחול דין מושבו של המוריש בשעת מותו. ''מקום מושב'' נקבע לפי מבחן ''מירב הזיקות'' (מרכז החיים). במקרה זה, מרק הוא תושב קנדה, ולכן דין מושבו הוא הדין הקנדי. אולם, סעיף 137 מסייג את הכלל וקובע ''חוץ מהאמור בסעיפים 138 עד 140''. סעיף 138 קובע כי ''על ירושת מקרקעין יחול דין מקום הימצאם''. כלל זה הוא קוגנטי. עם זאת, יש לבחון את כלל ההפניה (Renvoi). כאשר דין הפורום (ישראל) מפנה לדין זר (למשל, דין מקום הימצאם של מקרקעין), והדין הזר מפנה בחזרה לדין מושבו של המוריש (קנדה), והפורום הישראלי מקבל הפניה זו, יחול דין מושבו. במקרה זה, הדין הצרפתי אינו מחייב להחיל את דין צרפת באופן בלעדי, מה שמאפשר הפניה לדין הקנדי. לגבי ספרד, הדין הספרדי קוגנטי ואינו מאפשר הפניה, ולכן יחול הדין הספרדי על המקרקעין והכספים שם. על מיטלטלין וכספים (למעט חשבונות בנק בספרד) יחול דין מושבו של המוריש (קנדה) מכוח סעיף 137. לכן, על הקרקע בישראל, בקנדה ובצרפת יחולו דיני הירושה הקנדיים (בהנחה של קבלת הפניה), על הקרקע בספרד יחולו דיני הירושה הספרדיים, על הכספים והמיטלטלין בישראל, בקנדה ובצרפת ועל המיטלטלין בספרד יחולו דיני הירושה הקנדיים, ועל חשבונות הבנק בספרד יחולו דיני הירושה הספרדיים.', 'הטעות הנפוצה היא ליישם את סעיף 138 (דין מקום הימצאם למקרקעין) באופן גורף ללא התחשבות בכלל ההפניה (Renvoi), או להתעלם מהוראות ספציפיות של דינים זרים כפי שצוינו בשאלה.',
    '["ברירת דין", "חוק הירושה סעיף 137", "חוק הירושה סעיף 138", "מקום מושב", "מירב הזיקות", "כלל ההפניה (Renvoi)", "מקרקעין", "מיטלטלין"]'::jsonb, '**וריאציה 1 — כלל ברירת הדין הכללי:** מהו הכלל הכללי לברירת דין בירושה? ← דין מושבו של המוריש בשעת מותו (סעיף 137). ת"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)
**וריאציה 2 — חריג למקרקעין:** מהו החריג למקרקעין? ← על ירושת מקרקעין יחול דין מקום הימצאם (סעיף 138). ת"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)
**וריאציה 3 — כלל ההפניה (Renvoi):** מתי כלל ההפניה רלוונטי? ← כאשר דין זר מפנה בחזרה לדין מושבו של המוריש, והפורום מקבל זאת. בני דון-יחייא תורת דיני הירושה (2024) | כלל ההפניה (Renvoi)', 'ירושה ← דין מושב (סעיף 137) ← מקרקעין דין מקום הימצאם (סעיף 138) ← רנוואה אפשרית.', '["חוק הירושה, תשכ\"ה-1965, סעיפים 137, 138", "ת\"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)", "בני דון-יחייא תורת דיני הירושה (2024) | כלל ההפניה (Renvoi)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''חוקתי + בינלאומי פרטי'' subtopic=''אכיפת פסק חוץ'' → mapped chapter=''family_inheritance'' subtopic=''inheritance_will'' | classifier_note: Cross-border inheritance / private-international choice of law (Israel/Canada/France/Spain); no dedicated subtopic. Inheritance is the substantive subject | source_review_note: הסיווג לתת-נושא ''אכיפת פסק חוץ'' אינו מדויק, שכן השאלה עוסקת בברירת דין בירושה ולא באכיפה. יש לשקול הוספת תת-נושא מתאים יותר ל''ברירת דין בירושה'' או ''משפט בינלאומי פרטי - ירושה''. בנוסף, התשובה הנכונה (א) סותרת לכאורה את סעיף 138 לחוק הירושה כפי שצוטט בפסיקה, בכך שהיא מחילה את דין המושב (קנדה) על מקרקעין בישראל, קנדה וצרפת. ייתכן שהיא מבוססת על פרשנות רנוואה מורכבת שאינה מפורטת במקורות שסופקו, או שהיא שגויה. נדרשת בדיקה נוספת של הלכת כהנא (שלא סופקה) או פרשנות סעיפים 137-138 בהקשר רנוואה.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'על הקרקע בישראל, בקנדה ובצרפת יחולו דיני הירושה הקנדיים, על הקרקע בספרד יחולו דיני הירושה הספרדיים, על הכספים והמיטלטלין בישראל, בקנדה ובצרפת ועל המיטלטלין בספרד יחולו דיני הירושה הקנדיים, על חשבונות הבנק בספרד יחולו דיני הירושה הספרדיים.', true, 'התשובה הנכונה משקפת את יישום כללי ברירת הדין הישראליים (סעיפים 137 ו-138 לחוק הירושה) תוך התחשבות בכלל ההפניה (Renvoi) במקרים מסוימים. על פי סעיף 137, דין מושבו של המוריש (קנדה) חל על הירושה, למעט מקרקעין. סעיף 138 קובע כי על ירושת מקרקעין יחול דין מקום הימצאם. אולם, כאשר דין מקום הימצאם (למשל צרפת) מפנה בחזרה לדין מושבו של המוריש (קנדה), והדין הקנדי מקבל הפניה זו, יחול הדין הקנדי. לגבי ספרד, הדין הספרדי הוא קוגנטי ואינו מאפשר הפניה, ולכן יחול הדין הספרדי על המקרקעין והכספים שם. על מיטלטלין וכספים (למעט חשבונות בנק בספרד) יחול דין מושבו של המוריש (קנדה).', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על המקרקעין בכל מדינה יחול דין מקום הימצאם, על הכספים והמיטלטלין בישראל, בקנדה ובצרפת ועל המיטלטלין בספרד יחולו דיני הירושה הקנדיים, על חשבונות הבנק בספרד יחולו דיני הירושה הספרדיים.', false, 'טענה זו שגויה בחלקה. היא מיישמת את סעיף 138 באופן ישיר ללא התחשבות בכלל ההפניה (Renvoi) שעשוי להחזיר את הדין החל לדין מושבו של המוריש במדינות מסוימות (כמו צרפת, ואף ישראל וקנדה אם נניח שהן מקבלות הפניה כזו).', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על המקרקעין בכל מדינה יחול דין מקום הימצאם, על הכספים והמיטלטלין בישראל, בקנדה ובצרפת יחולו דיני הירושה הקנדיים, על המיטלטלין וחשבונות הבנק בספרד יחולו דיני הירושה הספרדיים.', false, 'טענה זו שגויה בחלקה. היא מיישמת את סעיף 138 באופן ישיר ללא התחשבות בכלל ההפניה (Renvoi) שעשוי להחזיר את הדין החל לדין מושבו של המוריש במדינות מסוימות. בנוסף, היא טוענת שעל מיטלטלין בספרד יחול הדין הספרדי, בעוד שהשאלה מציינת זאת רק לגבי חשבונות בנק בספרד, ומיטלטלין ככלל כפופים לדין מושבו של המוריש.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'על הקרקע בישראל, בקנדה ובצרפת יחולו דיני הירושה בישראל, על הקרקע בספרד יחולו דיני הירושה הספרדיים, על הכספים והמיטלטלין בישראל, בקנדה ובצרפת ועל המיטלטלין בספרד יחולו דיני הירושה הקנדיים, על חשבונות הבנק בספרד יחולו דיני הירושה הספרדיים.', false, 'טענה זו שגויה. היא טוענת שעל קרקע בישראל, קנדה וצרפת יחול הדין הישראלי, דבר שאינו עולה בקנה אחד עם כללי ברירת הדין הישראליים (סעיף 138 לחוק הירושה) או עם כלל ההפניה (Renvoi) במקרה זה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'קביעת ''מקום מושב'' המוריש',
    1, 'יוסף, אזרח צרפת, התגורר בצרפת במשך 40 שנה. לפני שנתיים עלה לישראל כעולה חדש, אך שמר על אזרחותו הצרפתית, ורוב נכסיו וקשריו המשפחתיים נותרו בצרפת. הוא נפטר בישראל. מהו ''מקום מושבו'' של יוסף לצורך קביעת הדין החל על ירושתו?', 'שאלה זו בוחנת את מבחן ''מירב הזיקות'' לקביעת ''מקום מושבו'' של המוריש, כפי שנקבע בסעיף 137 לחוק הירושה וכפי שפורש בפסיקה. היא מדגישה כי ''מקום מושב'' אינו בהכרח מקום המגורים האחרון או מקום המוות, אלא המקום בו רוכז מרכז חייו של המוריש, על בסיס מכלול זיקות אובייקטיביות.', 'סעיף 137 לחוק הירושה קובע כי ''על הירושה יחול דין מושבו של המוריש בשעת מותו''. הפסיקה פירשה את המונח ''מקום מושב'' כמקום בו נמצא מרכז חייו של המוריש טרם מותו, ולאו דווקא מקום מותו הפיזי או מקום מגוריו האחרון. קביעת מקום המושב נעשית באמצעות מבחן ''מירב הזיקות'', שהוא מבחן עובדתי-משפטי מעורב. בין הזיקות הנבחנות נמנות: אזרחות, תושבות, מיקום רוב הנכסים, קשרים חברתיים ומשפחתיים, מרכז עסקים ועבודה, משך שהות במקומות שונים, מידת השליטה בשפה וההתערות במנהגים המקומיים, ומקור ההכנסה. במקרה של יוסף, אף שעלה לישראל ונפטר בה, רוב נכסיו וקשריו המשפחתיים נותרו בצרפת, שם התגורר 40 שנה. לכן, סביר שמרכז חייו ומקום מושבו ייקבעו בצרפת.',
    'הטעות הנפוצה היא לבלבל בין ''מקום מושב'' לבין ''מקום מגורים אחרון'' או ''מקום מוות'', או לתת משקל יתר לזיקה אחת (כמו אזרחות) על פני מכלול הזיקות.', '["מקום מושב", "מירב הזיקות", "חוק הירושה סעיף 137", "ברירת דין", "משפט בינלאומי פרטי", "מרכז חיים"]'::jsonb, '**וריאציה 1 — הגדרת מקום מושב:** מהו ''מקום מושב'' לצורך חוק הירושה? ← המקום בו נמצא מרכז חייו של המוריש טרם מותו, לפי מבחן מירב הזיקות. ת"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)
**וריאציה 2 — מבחן מירב הזיקות:** אילו זיקות נבחנות? ← אזרחות, נכסים, קשרים חברתיים/משפחתיים, משך שהות, שפה, מקור הכנסה. ת"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)
**וריאציה 3 — קוגנטיות הכלל:** האם ניתן להתנות על כלל ברירת הדין? ← לא, זהו עיקרון קוגנטי. ת"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)', 'מקום מושב ← מרכז חיים ← מירב הזיקות ← לאו דווקא מקום מוות.',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 137", "ת\"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'ישראל, שכן הוא נפטר בישראל והיה עולה חדש.', false, 'טענה זו שגויה. מקום מושב אינו נקבע רק לפי מקום המוות הפיזי או היותו עולה חדש, אלא לפי מבחן ''מירב הזיקות'' ומרכז החיים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'צרפת, שכן שם היה מרכז חייו ורוב זיקותיו, על אף שעלה לישראל ונפטר בה.', true, 'הפסיקה קבעה כי ''מקום מושב'' הוא המקום בו נמצא מרכז חייו של המוריש טרם מותו, ולאו דווקא מקום מותו הפיזי או מקום מגוריו האחרון. מבחן זה נקבע לפי ''מירב הזיקות'', הכולל זיקות פורמליות, מיקום נכסים, קשרים חברתיים ומשפחתיים, משך שהות, שפה ומקור הכנסה. במקרה זה, רוב הזיקות מצביעות על צרפת כמרכז חייו של יוסף.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'ישראל, שכן אזרחותו הישראלית החדשה קובעת את מקום מושבו.', false, 'טענה זו שגויה. אזרחות היא רק אחת הזיקות הנבחנות, ואינה מכרעת לבדה בקביעת מקום מושב, במיוחד כאשר קיימות זיקות חזקות יותר למדינה אחרת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'הדין הישראלי יחול על נכסיו בישראל, והדין הצרפתי על נכסיו בצרפת.', false, 'טענה זו שגויה. זוהי ברירת דין לפי סוג הנכס (מקרקעין מול מיטלטלין), אך השאלה מתייחסת לקביעת ''מקום מושב'' לצורך סעיף 137 לחוק הירושה, החל על מיטלטלין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הוכחת הדין הזר',
    2, 'ראובן הגיש בקשה לצו ירושה בישראל, וטען כי על הירושה חל דין זר. כיצד עליו להוכיח את הדין הזר בפני בית המשפט הישראלי?', 'שאלה זו עוסקת בכלל המרכזי במשפט הבינלאומי הפרטי, לפיו הדין הזר נחשב כעובדה שיש להוכיחה. היא מדגישה את הנטל המוטל על הצד הטוען לתחולת הדין הזר, ואת הדרך המקובלת להוכחתו, לרוב באמצעות חוות דעת מומחה.', 'הלכה פסוקה היא כי על הטוען לתחולתו של דין זר להוכיח אותו ככל עניין שבעובדה. בית המשפט הישראלי אינו בקיא בדינים זרים, ואינו מחויב לחפש אותם בעצמו. הדרך המקובלת והיעילה להוכחת הדין הזר היא באמצעות הגשת חוות דעת של מומחה לדין הזר. חוות דעת זו צריכה לפרט את הוראות הדין הזר הרלוונטיות, את פרשנותן ואת יישומן על נסיבות המקרה. בית המשפט רשאי, אך אינו חייב, לקבל את חוות הדעת, והוא יכול גם להסתייע במקורות נוספים. במקרים מסוימים, אם לא הוכח הדין הזר, בית המשפט עשוי להניח כי הוא זהה לדין הישראלי.',
    'הטעות היא לחשוב שבית המשפט יחפש בעצמו את הדין הזר, או שדי בהצגת סעיפי חוק מהדין הזר ללא פרשנות מומחה.', '["הוכחת דין זר", "דין זר כעובדה", "חוות דעת מומחה", "נטל הוכחה", "משפט בינלאומי פרטי", "הנחת זהות הדינים"]'::jsonb, '**וריאציה 1 — דין זר כעובדה:** כיצד מוכח דין זר? ← ככל עניין שבעובדה, לרוב באמצעות מומחה. רמ"ש (מחוזי תל אביב-יפו) 33913-07-19 א.ג נ'' מיר.ג (23.09.2019)
**וריאציה 2 — סמכות בית המשפט לענייני משפחה:** האם נדרשת רשות להגשת חוות דעת מומחה לדין זר בבית המשפט לענייני משפחה? ← כן, לפי תקנה 258יב(ז) לתקנות סדר הדין האזרחי (הישנות). רמ"ש (מחוזי תל אביב-יפו) 33913-07-19 א.ג נ'' מיר.ג (23.09.2019)
**וריאציה 3 — היעדר הוכחה:** מה קורה אם הדין הזר לא הוכח? ← בית המשפט עשוי להניח כי הוא זהה לדין הישראלי. ע"מ (מחוזי מרכז) 26342-01-16 ברודקום סמיקונדקטור בע״מ נ'' פקיד שומה כפר סבא (09.12.2019)', 'דין זר ← עובדה שיש להוכיח ← לרוב מומחה ← נטל על הטוען.',
    '["רמ\"ש (מחוזי תל אביב-יפו) 33913-07-19 א.ג נ'' מיר.ג (23.09.2019)", "ע\"מ (מחוזי מרכז) 26342-01-16 ברודקום סמיקונדקטור בע״מ נ'' פקיד שומה כפר סבא (09.12.2019)", "תקנות סדר הדין האזרחי, תשמ\"ד-1984, תקנה 258יב(ז) (הערה: תקנות אלו בוטלו והוחלפו בתקנות סדר הדין האזרחי, תשע\"ט-2018)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'בית המשפט יחפש בעצמו את הדין הזר הרלוונטי, שכן הוא בקיא בכללי המשפט הבינלאומי הפרטי.', false, 'טענה זו שגויה. הדין הזר נחשב כעובדה שיש להוכיחה, ובית המשפט אינו מחויב לחפש אותו בעצמו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'על הטוען לתחולתו של הדין הזר להוכיח אותו ככל עניין שבעובדה, לרוב באמצעות חוות דעת מומחה לדין הזר.', true, 'הלכה פסוקה היא כי על הטוען לתחולתו של דין זר להוכיח אותו ככל עניין שבעובדה, וזאת לרוב באמצעות הגשת חוות דעת של מומחה לדין הזר. בית המשפט אינו בקיא בדינים זרים ואינו מחויב לחפש אותם בעצמו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'די בהצגת אסמכתאות חקיקתיות מהדין הזר, ואין צורך בחוות דעת מומחה.', false, 'טענה זו שגויה. הצגת אסמכתאות חקיקתיות אינה מספיקה, שכן נדרשת גם פרשנות והבנה של הדין הזר, וזאת מסופקת על ידי מומחה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הדין הזר יוכח רק אם הצדדים הסכימו על תחולתו בכתב.', false, 'טענה זו שגויה. הוכחת הדין הזר אינה תלויה בהסכמת הצדדים, אלא בחובת ההוכחה של הטוען לתחולתו. כללי ברירת הדין הם קוגנטיים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'כלל ההפניה (Renvoi) בירושה',
    3, 'מוריש, אזרח ישראל ותושב גרמניה, נפטר והותיר מקרקעין בישראל. הדין הישראלי (דין הפורום) מפנה לדין מושבו של המוריש (גרמניה) עבור מיטלטלין, ולדין מקום הימצאם (ישראל) עבור מקרקעין. הדין הגרמני (דין המושב) מפנה בחזרה לדין אזרחותו של המוריש (ישראל). כיצד יחולו כללי ברירת הדין במקרה זה?', 'שאלה זו בוחנת את כלל ההפניה (Renvoi) במשפט הבינלאומי הפרטי, ובפרט את יישומו בהקשר של דיני ירושה. היא מדגישה את ההבחנה בין הפניה לדין מושב המוריש (לגבי מיטלטלין) לבין דין מקום הימצאם (לגבי מקרקעין), ואת האופן שבו הפורום הישראלי מתמודד עם הפניות הדדיות בין שיטות משפט שונות.', 'כלל ההפניה (Renvoi) מתעורר כאשר כלל ברירת הדין של הפורום מפנה לדין זר, והדין הזר מפנה בחזרה לדין הפורום (Remission) או לדין של מדינה שלישית (Transmission). במשפט הישראלי, כלל ההפניה אינו מיושם באופן אחיד. לגבי ירושת מקרקעין, סעיף 138 לחוק הירושה קובע באופן קוגנטי כי יחול דין מקום הימצאם. לכן, אם המקרקעין נמצאים בישראל, הדין הישראלי יחול עליהם ישירות, ללא קשר לדין מושבו של המוריש או להפניות הדדיות. כלל ההפניה עשוי להיות רלוונטי יותר לגבי ירושת מיטלטלין, שם הדין הישראלי מפנה לדין מושבו של המוריש (סעיף 137), ואז יש לבחון אם דין המושב מקבל את ההפניה או מפנה הלאה.',
    'הטעות היא להחיל את כלל ההפניה באופן אוטומטי על כל סוגי הנכסים, מבלי להבחין בין מקרקעין למיטלטלין, ומבלי להתחשב בכללים הקוגנטיים של דין הפורום.', '["כלל ההפניה (Renvoi)", "Remission", "Transmission", "חוק הירושה סעיף 137", "חוק הירושה סעיף 138", "מקרקעין", "מיטלטלין", "דין הפורום"]'::jsonb, '**וריאציה 1 — מקרקעין ורנוואה:** האם רנוואה משנה את דין מקום הימצאם למקרקעין? ← לא, סעיף 138 קוגנטי. ת"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)
**וריאציה 2 — דין קוגנטי:** האם כללי ברירת הדין קוגנטיים? ← כן, לא ניתן להתנות עליהם. ת"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)
**וריאציה 3 — הפניה לדין זר:** מה קורה אם הדין הזר מפנה בחזרה? ← יש לבחון אם הפורום מקבל את ההפניה. בני דון-יחייא תורת דיני הירושה (2024) | כלל ההפניה (Renvoi)', 'מקרקעין ← דין מקום הימצאם (סעיף 138) ← רנוואה לא משנה.',
    '["חוק הירושה, תשכ\"ה-1965, סעיפים 137, 138", "ת\"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)", "בני דון-יחייא תורת דיני הירושה (2024) | כלל ההפניה (Renvoi)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'הדין הישראלי יחול על המקרקעין, שכן הוא דין מקום הימצאם, וכלל ההפניה אינו רלוונטי למקרקעין.', true, 'על פי סעיף 138 לחוק הירושה, על ירושת מקרקעין יחול דין מקום הימצאם. כלל ההפניה (Renvoi) אינו משנה את הכלל הקוגנטי של דין מקום הימצאם למקרקעין, אלא אם כן דין מקום הימצאם עצמו מפנה לדין אחר ומדינת הפורום מקבלת זאת. במקרה זה, הדין הישראלי הוא דין מקום הימצאם, והוא יחול ישירות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'הדין הגרמני יחול על המקרקעין, שכן הוא דין מושבו של המוריש, וכלל ההפניה מחזיר את הדין החל לדין מושבו.', false, 'טענה זו שגויה. סעיף 138 לחוק הירושה קובע במפורש כי על ירושת מקרקעין יחול דין מקום הימצאם, וכלל ההפניה אינו משנה זאת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'הדין הישראלי יחול על המקרקעין, שכן הדין הגרמני מפנה בחזרה לדין אזרחותו של המוריש (ישראל), וזוהי הפניה מקובלת.', false, 'טענה זו שגויה. אף שהדין הגרמני מפנה בחזרה לדין אזרחותו של המוריש (ישראל), הדין הישראלי (דין הפורום) מפנה לדין מקום הימצאם (ישראל) עבור מקרקעין, ולכן הדין הישראלי חל ישירות מכוח סעיף 138, ללא צורך בכלל ההפניה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'הדין הגרמני יחול על המקרקעין, שכן הדין הישראלי מפנה לדין מושבו של המוריש, והדין הגרמני הוא הדין המוסמך.', false, 'טענה זו שגויה. הדין הישראלי מפנה לדין מושבו של המוריש רק לגבי מיטלטלין (סעיף 137), אך לגבי מקרקעין הוא מפנה לדין מקום הימצאם (סעיף 138).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סמכות בינלאומית לדון בירושה',
    4, 'מוריש, אזרח זר ותושב זר, נפטר בחו"ל והותיר נכסים בישראל. האם לבית המשפט הישראלי יש סמכות בינלאומית לדון בירושתו?', 'שאלה זו עוסקת בסמכות הבינלאומית של בתי המשפט בישראל לדון בענייני ירושה, כפי שנקבעה בסעיף 136 לחוק הירושה. היא מדגישה את הכלל לפיו עצם קיומם של נכסים בישראל מקנה סמכות לבית המשפט הישראלי, ללא קשר לאזרחות או תושבות המוריש.', 'סעיף 136 לחוק הירושה, שכותרתו ''סמכות בתי המשפט הישראליים'', קובע כי ''בית המשפט בישראל מוסמך לדון בירושתו של כל אדם שהניח נכסים בישראל''. הוראה זו מקנה סמכות בינלאומית לבית המשפט הישראלי לדון בירושה, גם אם המוריש לא היה אזרח או תושב ישראל, ומרכז חייו לא היה בישראל. הרציונל הוא להבטיח שניתן יהיה לטפל בנכסים המצויים בתחומי המדינה. חשוב להבחין בין סמכות בינלאומית (האם בית משפט בישראל יכול לדון) לבין ברירת דין (איזה דין יחול על הירושה). במקרה זה, קיומו של חשבון בנק בישראל מספיק להקניית סמכות בינלאומית לבית המשפט הישראלי.',
    'הטעות היא לבלבל בין סמכות בינלאומית לבין ברירת דין, או לחשוב שסמכות בינלאומית תלויה באזרחות או תושבות המוריש או היורשים.', '["סמכות בינלאומית", "חוק הירושה סעיף 136", "נכסים בישראל", "ברירת דין", "משפט בינלאומי פרטי", "צו ירושה"]'::jsonb, '**וריאציה 1 — תנאי לסמכות:** מהו התנאי לסמכות בינלאומית לדון בירושה בישראל? ← המוריש הניח נכסים בישראל. ת"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)
**וריאציה 2 — אזרחות ותושבות:** האם אזרחות או תושבות המוריש משפיעות על הסמכות? ← לא, קיומם של נכסים מספיק. בני דון-יחייא תורת דיני הירושה (2024) | סמכות בינלאומית
**וריאציה 3 — הבחנה בין סמכות לברירת דין:** מה ההבדל בין סמכות בינלאומית לברירת דין? ← סמכות קובעת אם ניתן לדון, ברירת דין קובעת איזה דין יחול. ע"ר (מחוזי מרכז) 41917-05-19 Royal philips Electronic N.V נ'' איתי לנואל (11.12.2019)', 'נכסים בישראל ← סמכות בינלאומית (סעיף 136) ← ללא קשר לאזרחות/תושבות.',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 136", "ת\"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)", "ע\"ר (מחוזי מרכז) 41917-05-19 Royal philips Electronic N.V נ'' איתי לנואל (11.12.2019)", "בני דון-יחייא תורת דיני הירושה (2024) | סמכות בינלאומית"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, שכן המוריש לא היה אזרח או תושב ישראל, ומרכז חייו לא היה בישראל.', false, 'טענה זו שגויה. סעיף 136 לחוק הירושה מקנה סמכות לבית המשפט הישראלי גם אם המוריש לא היה אזרח או תושב ישראל, ובלבד שהותיר נכסים בישראל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, אם המוריש הניח נכסים בישראל, לבית המשפט הישראלי יש סמכות לדון בירושתו, גם אם לא היה אזרח או תושב ישראל.', true, 'סעיף 136 לחוק הירושה קובע כי ''בית המשפט בישראל מוסמך לדון בירושתו של כל אדם שהניח נכסים בישראל''. סמכות זו קמה גם אם המוריש לא היה אזרח או תושב ישראל, ומרכז חייו לא היה בישראל. קיומם של נכסים בישראל הוא תנאי מספיק להקניית סמכות בינלאומית לבית המשפט הישראלי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם היורשים הם אזרחי ישראל או תושביה.', false, 'טענה זו שגויה. סמכות בית המשפט הישראלי לדון בירושה אינה תלויה באזרחות או תושבות היורשים, אלא בקיומם של נכסים בישראל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן הוגשה בקשה לצו ירושה גם במדינת מושבו של המוריש.', false, 'טענה זו שגויה. סמכות בית המשפט הישראלי אינה מותנית בהגשת בקשה מקבילה במדינה אחרת.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 35, '2023-S-S-Q35';
END
$$;

-- ============================================================
-- Q36 — 2023-S-S-Q36 — chapter=property subtopic=real_estate  [needs_review]
-- classifier_note: Real-estate joint venture between two developers + landowners — partition aspects implied. Closest fit is real_estate; could also belong under corporate/partnerships
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '9d616dbd-4833-4779-9ec3-4f8e7fdfb44a'::uuid;
  v_group_id uuid := 'bb9aa2af-993c-4492-8742-b3d89a62ce85'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '36ee5e5b-d3d1-48d1-9bf6-5999fb7f87ad'::uuid;
  v_ang_1 uuid := '72c79807-7a27-4c44-a272-4b13489a7b9e'::uuid;
  v_ang_2 uuid := '52996679-3429-4c6c-a35b-7012284e6b8e'::uuid;
  v_ang_3 uuid := 'dd9ccefc-4b43-401e-9ce3-80ee0d105db1'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q36';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 36, '2023-S-S-Q36';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'property';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'property';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'real_estate' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'real_estate', 'property';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q36', v_chapter_id, v_subtopic_id, 'ביום 1.1.2022 התקשרו יחד ראובן ושמעון, שותפים יזמי נדל"ן, בהסכם עם בעלי מקרקעין, שעל פיו יעניקו ראובן ושמעון לבעלי המקרקעין את השירותים הבאים: קבלת זכויות בנייה במקרקעין, בניית בניין דירות עליהם ומכירת הדירות. ראובן ושמעון התקשרו בינם לבין עצמם בהסכם שלפיו ראובן יפעל לקידום קבלת הזכויות ואישורי הבנייה בנכס, ושמעון יבצע את הבנייה בפועל ואת שיווק הדירות. כמו כן, נקבע בהסכם בין ראובן לשמעון ששניהם מתחייבים להישאר בפרויקט לפחות ל-24 החודשים הקרובים ללא אפשרות יציאה לפני כן. לאחר כ-12 חודשים ב-1.1.2023 רכשו ראובן ושמעון בעסקה אחרת מקרקעין בדרום הארץ, ובהסכם השיתוף שנכרת ביניהם נכתב שלא ניתן לדרוש פירוק שיתוף. כעבור 15 חודשים מיום הרכישה הראשונה נתגלעו סכסוכים בין השניים. ראובן מבקש לפרק את השותפויות. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 36}'::jsonb, 'השאלה עוסקת בכללי פירוק שיתוף במקרקעין ובזכויות, תוך התייחסות להבחנה בין שני סוגי הנכסים ולמעמד הסכמי שיתוף המגבילים את הזכות לפירוק. היא בוחנת את תחולת סעיף 37 לחוק המקרקעין וסעיף 10 לחוק המיטלטלין, ואת ההבדלים ביניהם לעניין מגבלות זמן על פירוק שיתוף.', 'עקרון העל בדיני השיתוף הוא שכל שותף זכאי לדרוש פירוק שיתוף בכל עת (סעיף 37(א) לחוק המקרקעין וסעיף 10(א) לחוק המיטלטלין). עם זאת, קיימים חריגים לכלל זה, בעיקר כאשר נכרת הסכם שיתוף המגביל את הזכות לפירוק. במקרה של שותפות ב''זכויות'' (כמו בפרויקט היזמות הראשון), חל חוק המיטלטלין. סעיף 10(א) לחוק המיטלטלין קובע כי אם בהסכם שיתוף יש תניה המגבילה את הזכות לפירוק, בית המשפט רשאי לצוות על פירוק השיתוף ''בכל עת'', על אף התניה, אם נראה לו הדבר צודק בנסיבות העניין. לכן, לגבי השותפות הראשונה, בית המשפט רשאי לצוות על פירוק כבר ב-1.4.2023, אם ימצא זאת צודק. לעומת זאת, במקרה של שותפות ב''מקרקעין'' (כמו ברכישת המקרקעין בדרום), חל חוק המקרקעין. סעיף 37(ב) לחוק המקרקעין קובע כי אם בהסכם שיתוף יש תניה המגבילה את הזכות לפירוק לתקופה העולה על שלוש שנים, בית המשפט רשאי לצוות על פירוק השיתוף ''כעבור שלוש שנים'', על אף התניה, אם נראה לו הדבר צודק בנסיבות העניין. רכישת המקרקעין הייתה ב-1.1.2023, ולכן שלוש שנים יחלפו ב-1.1.2026. לפיכך, בית המשפט יוכל לצוות על פירוק השותפות השנייה רק החל ממועד זה, אם ימצא זאת צודק.', 'הטעות הנפוצה היא לבלבל בין כללי פירוק שיתוף במקרקעין לבין כללי פירוק שיתוף במיטלטלין ובזכויות, ובפרט להתעלם מההבדל במגבלות הזמן על פירוק שיתוף כאשר קיים הסכם המגביל זאת.',
    '["פירוק שיתוף", "חוק המקרקעין סעיף 37", "חוק המיטלטלין סעיף 10", "הסכם שיתוף", "מקרקעין", "זכויות", "מגבלת זמן", "סמכות בית המשפט"]'::jsonb, '**וריאציה 1 — פירוק שיתוף במקרקעין:** מה הדין לגבי הסכם המגביל פירוק שיתוף במקרקעין? ← בית המשפט רשאי לצוות על פירוק רק כעבור 3 שנים. סעיף 37(ב) לחוק המקרקעין, תשכ"ט-1969
**וריאציה 2 — פירוק שיתוף בזכויות:** מה הדין לגבי הסכם המגביל פירוק שיתוף בזכויות? ← בית המשפט רשאי לצוות על פירוק בכל עת. סעיף 10(א) לחוק המיטלטלין, תשל"א-1971
**וריאציה 3 — רציונל פירוק שיתוף:** מהו הרציונל לפירוק שיתוף? ← מניעת קיפאון, עידוד ניצול יעיל של נכסים, והימנעות מיחסים עכורים. ת"א (שלום ת"א) 50951-06-20 טי. אנ. טי לימיטד בע"מ נ'' עיריית רמת השרון (09.01.2022)', 'פירוק שיתוף ← מקרקעין (סעיף 37) מגבלת 3 שנים ← זכויות (סעיף 10) בכל עת.', '["חוק המקרקעין, תשכ\"ט-1969, סעיף 37", "חוק המיטלטלין, תשל\"א-1971, סעיף 10", "ת\"א (שלום ת\"א) 50951-06-20 טי. אנ. טי לימיטד בע\"מ נ'' עיריית רמת השרון (09.01.2022)", "רע\"א 1017/97 יצחק רידלביץ נ'' יצחק מודעי (25.10.1998)", "אבי וינרוט דיני קניין - פרקי יסוד (2024) | א. עקרון העל"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''property'' subtopic=''real_estate'' | classifier_note: Real-estate joint venture between two developers + landowners — partition aspects implied. Closest fit is real_estate; could also belong under corporate/partnerships | source_review_note: הסיווג לתת-נושא ''הליכים'' אינו מדויק, שכן השאלה עוסקת בעיקרה בדיני קניין ובפירוק שיתוף. יש לשקול הוספת תת-נושא מתאים יותר ל''דיני קניין - פירוק שיתוף'' או ''מקרקעין - פירוק שיתוף''.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ראובן אינו רשאי לפרק את השותפויות, אולם בית המשפט רשאי בכל עת לצוות על הפירוק אם נראה לו צודק בנסיבות העניין.', false, 'טענה זו שגויה. היא מתעלמת מההבחנה בין פירוק שיתוף במקרקעין לבין פירוק שיתוף בזכויות, ומההבדלים בהגבלת הזכות לפירוק בין שני הסוגים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ראובן רשאי לפרק את השותפות הראשונה אבל לא את השנייה.', false, 'טענה זו שגויה. אף שראובן רשאי לדרוש פירוק, בית המשפט הוא זה שמחליט על הפירוק, ובשותפות השנייה (מקרקעין) קיימת הגבלה בחוק המקרקעין על מועד הפירוק.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המשפט רשאי בכל עת לצוות על פירוק השותפות הראשונה אם הדבר נראה לו צודק בנסיבות העניין, אבל לא על פירוק השותפות השנייה.', false, 'טענה זו שגויה. בית המשפט רשאי לצוות על פירוק השותפות השנייה (מקרקעין), אך רק לאחר שחלפו שלוש שנים ממועד ההסכם המגביל, אם הדבר נראה לו צודק בנסיבות העניין.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המשפט רשאי בכל עת לצוות על פירוק השותפות הראשונה אם הדבר נראה לו צודק בנסיבות העניין, ולצוות על פירוק השותפות השנייה רק החל מיום 1.1.2026 אם הדבר נראה לו צודק בנסיבות העניין.', true, 'השותפות הראשונה היא שותפות בזכויות, עליה חל סעיף 10(א) לחוק המיטלטלין, המאפשר לבית המשפט לצוות על פירוק בכל עת, על אף תניה מגבילה, אם נראה לו צודק. השותפות השנייה היא שותפות במקרקעין, עליה חל סעיף 37(ב) לחוק המקרקעין, הקובע כי אם הסכם השיתוף מגביל את הפירוק לתקופה העולה על שלוש שנים, בית המשפט רשאי לצוות על פירוק רק כעבור שלוש שנים. רכישת המקרקעין הייתה ב-1.1.2023, ולכן שלוש שנים יחלפו ב-1.1.2026.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פירוק שיתוף בזכויות אובליגטוריות',
    1, 'חברה א'' וחברה ב'' התקשרו בהסכם שיתוף לקידום פרויקט בנייה, במסגרתו רכשו זכויות אובליגטוריות במקרקעין שטרם נרשמו על שמן. בהסכם השיתוף נקבע כי לא ניתן לדרוש פירוק שיתוף במשך 5 שנים. לאחר שנתיים, חברה א'' מבקשת לפרק את השיתוף. מה הדין?', 'שאלה זו עוסקת בפירוק שיתוף בזכויות אובליגטוריות הקשורות למקרקעין שטרם נרשמו. היא מדגישה את תחולת חוק המיטלטלין על זכויות אלו, ואת ההבדל המהותי בין הגבלת פירוק שיתוף במקרקעין לבין הגבלת פירוק שיתוף בזכויות, במיוחד לעניין סמכות בית המשפט לצוות על פירוק על אף תניה מגבילה.', 'כאשר מדובר בזכויות אובליגטוריות במקרקעין שטרם נרשמו, הן נחשבות כ''זכויות'' לעניין חוק המיטלטלין, תשל"א-1971, מכוח סעיף 13(א) לחוק זה. סעיף 10(א) לחוק המיטלטלין קובע כי ''כל שותף זכאי בכל עת לדרוש פירוק השיתוף; היתה בהסכם שיתוף תניה השוללת או מגבילה זכות זו, רשאי בית המשפט לצוות על פירוק השיתוף, על אף התניה, אם נראה לו הדבר צודק בנסיבות הענין''. בניגוד לסעיף 37(ב) לחוק המקרקעין, אין בחוק המיטלטלין מגבלת זמן של שלוש שנים. לכן, בית המשפט רשאי לצוות על פירוק השיתוף בכל עת, גם בתוך תקופת ההגבלה שנקבעה בהסכם, אם נראה לו הדבר צודק בנסיבות העניין.',
    'הטעות הנפוצה היא להחיל את כללי פירוק השיתוף במקרקעין (ובפרט את מגבלת שלוש השנים) על זכויות אובליגטוריות, מבלי להבחין בין הסוגים השונים של נכסים ודיני הפירוק החלים עליהם.', '["פירוק שיתוף בזכויות", "חוק המיטלטלין סעיף 10", "חוק המיטלטלין סעיף 13(א)", "זכויות אובליגטוריות", "הסכם שיתוף", "סמכות בית המשפט"]'::jsonb, '**וריאציה 1 — תחולת חוק המיטלטלין:** על מה חל חוק המיטלטלין? ← על מיטלטלין ועל זכויות. סעיף 9(א) לחוק המיטלטלין, תשל"א-1971
**וריאציה 2 — הגבלת פירוק בזכויות:** מהי מגבלת פירוק שיתוף בזכויות? ← בית המשפט רשאי לצוות על פירוק בכל עת, על אף תניה מגבילה. סעיף 10(א) לחוק המיטלטלין, תשל"א-1971
**וריאציה 3 — השוואה למקרקעין:** מה ההבדל בין מיטלטלין למקרקעין בהגבלת פירוק? ← במקרקעין יש מגבלת 3 שנים, במיטלטלין אין. יהושע ויסמן דיני קניין - בעלות ושיתוף (1997) | 11. הסכם להגכלת הזכות לפירוק השיתוף', 'זכויות אובליגטוריות ← חוק המיטלטלין ← בית משפט רשאי לפרק בכל עת.',
    '["חוק המיטלטלין, תשל\"א-1971, סעיפים 9(א), 10(א), 13(א)", "יהושע ויסמן דיני קניין - בעלות ושיתוף (1997) | 11. הסכם להגכלת הזכות לפירוק השיתוף", "יעקב שקד פירוק שיתוף במקרקעין (2020) | 4.10 דרך פירוק שיתוף בזכויות בעלות זיקה למקרקעין שטרם נרשמו ופירוק שיתוף במיטלטלין"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'חברה א'' אינה יכולה לדרוש פירוק שיתוף לפני תום 5 השנים, שכן זהו תנאי מחייב בהסכם.', false, 'טענה זו שגויה. אף שההסכם מגביל, חוק המיטלטלין מאפשר לבית המשפט לצוות על פירוק בכל עת, ללא מגבלת זמן.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'בית המשפט רשאי לצוות על פירוק השיתוף בכל עת, על אף התניה המגבילה, אם נראה לו הדבר צודק בנסיבות העניין.', true, 'שותפות בזכויות אובליגטוריות נחשבת כשותפות במיטלטלין, ועליה חל סעיף 10(א) לחוק המיטלטלין. סעיף זה קובע כי בית המשפט רשאי לצוות על פירוק השיתוף בכל עת, על אף תניה בהסכם שיתוף המגבילה זכות זו, אם נראה לו הדבר צודק בנסיבות העניין, ללא מגבלת זמן של שלוש שנים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'בית המשפט רשאי לצוות על פירוק השיתוף רק לאחר שלוש שנים ממועד ההסכם, אם נראה לו הדבר צודק.', false, 'טענה זו שגויה. מגבלת שלוש השנים חלה על פירוק שיתוף במקרקעין (סעיף 37(ב) לחוק המקרקעין), ולא על פירוק שיתוף בזכויות אובליגטוריות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'היות שהזכויות טרם נרשמו, לא ניתן לדרוש פירוק שיתוף כלל.', false, 'טענה זו שגויה. ניתן לדרוש פירוק שיתוף בזכויות אובליגטוריות, גם אם הן טרם נרשמו במרשם המקרקעין, מכוח חוק המיטלטלין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגבלת פירוק שיתוף בשל חוסר תום לב',
    2, 'יוסי ודני הם שותפים במקרקעין. יוסי דורש פירוק שיתוף, אך דני טוען כי יוסי פועל בחוסר תום לב קיצוני, במטרה להכריח את דני למכור את חלקו במחיר נמוך. האם טענת חוסר תום לב קיצוני יכולה למנוע את פירוק השיתוף?', 'שאלה זו בוחנת את היחס בין הזכות היסודית לדרוש פירוק שיתוף לבין עקרון תום הלב ואיסור השימוש לרעה בזכות. היא מדגישה כי אף שעקרון תום הלב הוא עקרון על, הפסיקה מפרשת את תחולתו על פירוק שיתוף באופן מצומצם ביותר, ורק במקרים חריגים וקיצוניים ניתן יהיה לדחות תביעה לפירוק שיתוף על בסיס טענה זו.', 'הזכות לדרוש פירוק שיתוף במקרקעין, המעוגנת בסעיף 37(א) לחוק המקרקעין, היא זכות יסוד. עם זאת, זכות זו, כמו כל זכות משפטית, כפופה לעקרון תום הלב ולעקרון איסור השימוש לרעה בזכות (סעיף 14 לחוק המקרקעין). הפסיקה קבעה כי דחיית תביעה לפירוק שיתוף מכוח עקרון תום הלב תיעשה באופן מצומצם במיוחד, ורק במקרים חריגים וקיצוניים של שימוש לרעה בזכות. הרציונל לכך הוא שפירוק שיתוף נתפס כמעודד ניצול יעיל של הקרקע ומונע קיפאון, וכי שותפות הנגועה ביחסים עכורים אינה מצב רצוי. לכן, טענות בדבר חוסר תום לב או שימוש לרעה בזכות יתקבלו רק במקרים נדירים, כאשר הוכח שהדרישה לפירוק נובעת ממניעים פסולים ובלתי הוגנים באופן קיצוני.',
    'הטעות היא להניח שכל טענה לחוסר תום לב תספיק כדי למנוע פירוק שיתוף, מבלי להבין את הפרשנות המצמצמת של הפסיקה בהקשר זה ואת מעמדה של הזכות לפירוק כזכות יסוד.', '["פירוק שיתוף", "זכות יסוד", "תום לב", "שימוש לרעה בזכות", "סעיף 37(א) לחוק המקרקעין", "סעיף 14 לחוק המקרקעין", "פרשנות מצמצמת"]'::jsonb, '**וריאציה 1 — עקרון העל:** מהו עקרון העל בדיני שיתוף? ← כל שותף זכאי לדרוש פירוק שיתוף בכל עת. סעיף 37(א) לחוק המקרקעין, תשכ"ט-1969
**וריאציה 2 — תום לב ופירוק:** האם תום לב מגביל פירוק שיתוף? ← כן, אך רק במקרים חריגים וקיצוניים. ת"א (שלום תל אביב-יפו) 40637-04-19 פ.ט.ל בלגיה ישראל נדל"ן והשקעות בע"מ נ'' בנק דיסקונט לישראל בעמ (08.08.2023)
**וריאציה 3 — סעיף 14:** האם סעיף 14 לחוק המקרקעין רלוונטי? ← כן, אך בזהירות רבה ורק לשימוש לרעה בזכות. ת"א (שלום חי'') 27495-08-25 סמאח חלבי נ'' רביע חמיד (15.10.2025)', 'פירוק שיתוף ← זכות יסוד ← כפוף לתום לב ← רק במקרים קיצוניים.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיפים 14, 37(א)", "ת\"א (שלום חי'') 27495-08-25 סמאח חלבי נ'' רביע חמיד (15.10.2025)", "ת\"א (שלום תל אביב-יפו) 40637-04-19 פ.ט.ל בלגיה ישראל נדל\"ן והשקעות בע\"מ נ'' בנק דיסקונט לישראל בעמ (08.08.2023)", "רע\"א 1017/97 יצחק רידלביץ נ'' יצחק מודעי (25.10.1998)", "אבי וינרוט דיני קניין - פרקי יסוד (2024) | ב. חריגים לעקרון העל של פירוק שיתוף"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'לא, הזכות לדרוש פירוק שיתוף היא זכות יסוד ואינה כפופה לעקרון תום הלב.', false, 'טענה זו שגויה. אף שהזכות לפירוק היא זכות יסוד, היא כפופה לעקרון תום הלב, אך רק במקרים חריגים וקיצוניים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כן, עקרון תום הלב הוא עקרון על, ודחיית תביעה לפירוק שיתוף מכוחו תיעשה במקרים חריגים וקיצוניים במיוחד.', true, 'הזכות לדרוש פירוק שיתוף היא זכות יסוד, אך היא כפופה לעקרון תום הלב. הפסיקה קבעה כי דחיית תביעה לפירוק שיתוף מכוח עקרון תום הלב תיעשה באופן מצומצם במיוחד, רק במקרים חריגים וקיצוניים של שימוש לרעה בזכות, שכן מדובר בדיני קניין ונוכח עקרון העל של פירוק שיתוף.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, כל טענה לחוסר תום לב מצד שותף הדורש פירוק שיתוף תתקבל ותמנע את הפירוק.', false, 'טענה זו שגויה. לא כל טענה לחוסר תום לב תתקבל, אלא רק במקרים חריגים וקיצוניים, ובית המשפט יבחן זאת בזהירות רבה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, סעיף 14 לחוק המקרקעין אינו רלוונטי להליך של פירוק שיתוף.', false, 'טענה זו שגויה. אף שסעיף 14 לחוק המקרקעין פורש באופן מצמצם בהקשר של פירוק שיתוף, הוא עדיין רלוונטי במקרים חריגים של שימוש לרעה בזכות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פירוק שיתוף בדירת מגורים של בני זוג',
    3, 'אבי ודנה, בני זוג גרושים, הם בעלים משותפים של דירת מגורים בה מתגוררים ילדיהם הקטינים עם דנה. אבי דורש פירוק שיתוף בדירה בדרך של מכירה. האם בית המשפט יורה על ביצוע המכירה באופן מיידי?', 'שאלה זו עוסקת בחריג מיוחד לכלל פירוק השיתוף, הנוגע לדירת מגורים של בני זוג עם ילדים קטינים. היא מתמקדת בסעיף 40א לחוק המקרקעין (ובמקבילו סעיף 10א לחוק המיטלטלין), המעגן את ההגנה על מדורם של הקטינים ובן הזוג המחזיק בהם, ומעכב את ביצוע פירוק השיתוף עד למציאת הסדר מגורים חלופי.', 'סעיף 40א(א) לחוק המקרקעין, תשכ"ט-1969, קובע חריג לכלל פירוק השיתוף במקרקעין. כאשר בית המשפט מחליט על פירוק שיתוף בדירת מגורים של בני זוג המשמשת להם למגורים, בדרך של מכירה, הוא לא יורה על ביצועה והמכירה תעוכב. העיכוב יימשך כל עוד לא נוכח בית המשפט כי לילדי בני הזוג הקטינים ולבן הזוג המחזיק בהם (במקרה זה דנה), נמצא הסדר מגורים אחר המתאים לצרכיהם, לרבות הסדר ביניים למגורים זמניים. הוראה זו נועדה להגן על זכויות המדור של הקטינים ושל ההורה המשמורן, ומשקפת את העדיפות שניתנת לשיקולי דיני המשפחה על פני דיני הקניין במקרים אלו. סעיף 40א(ב) אף קובע כי הוראות סעיף 33 לחוק הגנת הדייר לא יחולו במקרה זה.',
    'הטעות היא להתעלם מההוראה הספציפית של סעיף 40א לחוק המקרקעין, המהווה חריג חשוב לכלל פירוק השיתוף, ולהניח שהזכות לפירוק היא מוחלטת גם במקרים אלו.', '["פירוק שיתוף", "דירת מגורים", "בני זוג", "ילדים קטינים", "סעיף 40א לחוק המקרקעין", "הסדר מגורים חלופי", "הגנת מדור"]'::jsonb, '**וריאציה 1 — עיכוב מכירה:** מתי תעוכב מכירת דירת בני זוג? ← עד למציאת הסדר מגורים חלופי לילדים הקטינים ולבן הזוג המחזיק בהם. סעיף 40א(א) לחוק המקרקעין, תשכ"ט-1969
**וריאציה 2 — חוק הגנת הדייר:** האם סעיף 33 לחוק הגנת הדייר חל? ← לא, סעיף 40א(ב) קובע שלא יחול. סעיף 40א(ב) לחוק המקרקעין, תשכ"ט-1969
**וריאציה 3 — זכויות אובליגטוריות:** האם יש הוראה מקבילה לזכויות אובליגטוריות? ← כן, סעיף 10א לחוק המיטלטלין. סעיף 10א לחוק המיטלטלין, תשל"א-1971', 'פירוק דירת בני זוג ← עיכוב מכירה ← עד הסדר מגורים חלופי לילדים.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 40א", "חוק המיטלטלין, תשל\"א-1971, סעיף 10א", "אבי וינרוט דיני קניין - פרקי יסוד (2024) | ב. חריגים לעקרון העל של פירוק שיתוף", "רע\"א 8233/08 מרגלית כובשי נ'' עו\"ד איל שוורץ (10.10.2010)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, הזכות לפירוק שיתוף היא זכות יסוד, ואין להגבילה.', false, 'טענה זו שגויה. קיימים חריגים לזכות לפירוק שיתוף, ובמיוחד בדירת מגורים של בני זוג עם ילדים קטינים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, בית המשפט יעכב את ביצוע המכירה כל עוד לא נמצא הסדר מגורים חלופי המתאים לצרכי הילדים הקטינים ולדנה.', true, 'סעיף 40א(א) לחוק המקרקעין קובע כי במקרה של פירוק שיתוף בדירת מגורים של בני זוג המשמשת להם למגורים, בדרך של מכירה, בית המשפט לא יורה על ביצועה והמכירה תעוכב, כל עוד לא נוכח בית המשפט כי לילדי בני הזוג הקטינים ולבן הזוג המחזיק בהם, נמצא הסדר מגורים אחר המתאים לצרכיהם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן דנה תוכיח כי המכירה תגרום לה הפסד ניכר.', false, 'טענה זו שגויה. שיקול של ''הפסד ניכר'' רלוונטי להחלטה אם לפרק בדרך של מכירה או חלוקה בעין (סעיף 40(א) לחוק המקרקעין), אך אינו מעכב את ביצוע המכירה בדירת מגורים של בני זוג.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אך רק אם דנה היא דיירת מוגנת בדירה.', false, 'טענה זו שגויה. סעיף 40א(ב) לחוק המקרקעין קובע במפורש כי הוראות סעיף 33 לחוק הגנת הדייר לא יחולו במקרה זה, ולכן מעמד של דייר מוגן אינו רלוונטי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'דרישת צירוף כל בעלי הזכויות לפירוק שיתוף',
    4, 'ראובן הגיש תביעה לפירוק שיתוף במקרקעין. בדיון התברר כי לא כל בעלי הזכויות הרשומים במקרקעין צורפו כצד להליך. מהי השלכת אי-צירוף כל בעלי הזכויות על התביעה?', 'שאלה זו עוסקת בדרישה המהותית לצירוף כל בעלי הזכויות הרשומים כצדדים להליך פירוק שיתוף במקרקעין. היא מדגישה כי פירוק שיתוף משפיע על כלל המקרקעין ועל כלל השותפים, ולכן אי-צירוף כל בעלי הזכויות מונע מבית המשפט לדון בתביעה במתכונתה הנוכחית, אך לרוב יאפשר תיקון הפגם על ידי השלמת הצדדים.', 'סעד של פירוק שיתוף במקרקעין יכול להינתן רק כאשר כל בעלי הזכויות הרשומים במקרקעין צורפו כצד להליך. הסיבה לכך היא שמשמעות פירוק השיתוף היא קביעה של חלוקה ושווי של כל חלקי המקרקעין ביחס לכל אחד מהשותפים, ומשכך כל אחד מהשותפים הוא בעל דין נדרש. אי-צירוף של כל בעלי הזכויות הרשומים מונע מבית המשפט לדון בתביעה לפירוק שיתוף במתכונתה הנוכחית. עם זאת, המדיניות השיפוטית היא להעדיף דיון ענייני על פני סילוק על הסף, ולכן בית המשפט יורה לרוב על השלמת הצד החסר, כלומר, על התובע לצרף את כל בעלי הזכויות הרשומים כצדדים להליך, ורק אם לא יעשה כן, התביעה תימחק.',
    'הטעות היא לחשוב שניתן לפרק שיתוף באופן חלקי או שאי-צירוף כל בעלי הזכויות הוא פגם טכני שאינו משפיע על הדיון.', '["פירוק שיתוף", "בעלי זכויות רשומים", "צירוף צדדים", "סילוק על הסף", "השלמת צדדים", "זכות קניינית"]'::jsonb, '**וריאציה 1 — תנאי לפירוק:** מתי ניתן לפרק שיתוף במקרקעין? ← רק כאשר כל בעלי הזכויות הרשומים צורפו כצד להליך. ת"א (שלום חי'') 27495-08-25 סמאח חלבי נ'' רביע חמיד (15.10.2025)
**וריאציה 2 — השלכת אי-צירוף:** מה קורה אם לא צורפו כל בעלי הזכויות? ← לא ניתן לדון בתביעה במתכונתה הנוכחית, ויוזמן תיקון. ת"א (שלום חי'') 27495-08-25 סמאח חלבי נ'' רביע חמיד (15.10.2025)
**וריאציה 3 — סילוק על הסף:** האם יסולק על הסף? ← לרוב לא, אלא תינתן אפשרות לתיקון. ת"א (שלום חי'') 27495-08-25 סמאח חלבי נ'' רביע חמיד (15.10.2025)', 'פירוק שיתוף ← דורש צירוף כל בעלי הזכויות ← אי-צירוף ימנע דיון עד לתיקון.',
    '["ת\"א (שלום חי'') 27495-08-25 סמאח חלבי נ'' רביע חמיד (15.10.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בית המשפט יורה על סילוק התביעה על הסף, שכן אי-צירוף הוא פגם מהותי שלא ניתן לתיקון.', false, 'טענה זו שגויה. אף שאי-צירוף הוא פגם מהותי, בית המשפט יעדיף לרוב לאפשר תיקון הפגם על פני סילוק על הסף.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בית המשפט לא יוכל לדון בתביעה במתכונתה הנוכחית, ויורה לתובע לצרף את כל בעלי הזכויות הרשומים.', true, 'סעד של פירוק שיתוף במקרקעין יכול להינתן רק כאשר כל בעלי הזכויות הרשומים במקרקעין צורפו כצד להליך. אי-צירוף של כל בעלי הזכויות הרשומים מונע מבית המשפט לדון בתביעה במתכונתה הנוכחית, ולכן בית המשפט יורה על השלמת הצדדים החסרים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בית המשפט ידון בתביעה, אך פסק הדין יחייב רק את השותפים שצורפו להליך.', false, 'טענה זו שגויה. פירוק שיתוף משפיע על כלל המקרקעין ועל כלל השותפים, ולכן לא ניתן לדון בו באופן חלקי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית המשפט יורה על פירוק השיתוף בדרך של מכירה פומבית, ללא צורך בצירוף כל השותפים.', false, 'טענה זו שגויה. גם במכירה פומבית, יש צורך בצירוף כל בעלי הזכויות הרשומים, שכן התמורה תחולק ביניהם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 36, '2023-S-S-Q36';
END
$$;

