-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '8fc407a1-0386-4420-8916-fdd7d95afb53'::uuid;
  v_group_id uuid := '6e145bb4-5894-4695-9041-b72f3b59ed77'::uuid;
