  v_ang_0 uuid := 'f388cd86-ec1e-44f8-9770-8ede68e2b707'::uuid;
  v_ang_1 uuid := '94bb1bf0-53b1-431c-b94f-e7c4e6894390'::uuid;
  v_ang_2 uuid := '019e1cad-6834-458d-9f59-ca482bb41905'::uuid;
  v_ang_3 uuid := '3bbd780e-3c21-402b-b1f0-e56eb12d6a85'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q37';
