  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q37', v_chapter_id, v_subtopic_id, 'באחרית ימיו החליט ראובן, אביהם של דוד ויונתן שהם יורשיו היחידים, לחלק את נכסי הנדל"ן שבבעלותו המלאה ורשומים על שמו במרשם המקרקעין באופן הבא: בניין מגורים בבעלותו נתן לדוד במתנה עוד בחייו. בצוואה שכתב מיום 1.2.2022 הוריש ליונתן וילה בכפר שמריהו שבבעלותו. באשר לדירת מגורים באילת וקניון בהרצליה לא נתן ראובן כל הוראה. ביום 1.2.2023 נפטר ראובן. יונתן, שאינו מעוניין בקניון, הסכים להעביר את חלקו בקניון לדוד תמורת ויתור של דוד על חלקו בדירה באילת בתוספת סך של 1,000,000 ש"ח שישלם לו דוד שלא מתוך נכסי העיזבון. אילו מבין הפעולות במקרקעין המתוארות לעיל הן מכירת מקרקעין לעניין דיני מיסוי מקרקעין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 37}'::jsonb, 'השאלה עוסקת בהגדרת ''מכירה'' לעניין חוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963, וביישום הגדרה זו על פעולות שונות במקרקעין, לרבות מתנה, ירושה, ועסקאות בין יורשים. היא בוחנת את ההבחנה בין אירועים החייבים במס לבין אלו הפטורים ממנו או שאינם נחשבים ''מכירה'' כלל.', 'חוק מיסוי מקרקעין (שבח ורכישה) מגדיר ''מכירה'' באופן רחב בסעיף 1, הכולל ''העברה או ויתור על זכות במקרקעין... אף אם לא נקבע לה תמורה''. מכאן:
1. **נתינת בניין המגורים במתנה לדוד**: מתנה נחשבת ''מכירה'' לעניין החוק, ולכן פעולה זו היא מכירה.
2. **הורשת וילה ליונתן בצוואה**: סעיף 4 לחוק קובע במפורש כי ''הורשה אינה מכירה''. לכן, פעולה זו אינה מכירה.
3. **דירת מגורים באילת וקניון בהרצליה**: נכסים אלו יורשים דוד ויונתן בחלקים שווים על פי דין, שכן לא ניתנה לגביהם הוראה בצוואה. עצם הירושה אינה מכירה.
4. **הסכם בין יונתן לדוד**: יונתן מעביר את חלקו בקניון לדוד תמורת ויתור של דוד על חלקו בדירה באילת בתוספת 1,000,000 ש"ח. זוהי עסקת חליפין, שבה כל צד מעביר זכות במקרקעין בתמורה לזכות אחרת (או כסף).
* **העברת חלק יונתן בקניון לדוד**: זוהי ''מכירה'' שכן יונתן מקבל תמורה (חלק דוד בדירה באילת + 1,000,000 ש"ח).
* **העברת חלק דוד בדירה באילת ליונתן**: זוהי גם ''מכירה'' שכן דוד מקבל תמורה (חלק יונתן בקניון).
התשובה הנכונה (ג) כוללת את נתינת המתנה לדוד ואת העברת חלקו של יונתן בקניון לדוד. היא אינה כוללת את העברת חלקו של דוד בדירה באילת ליונתן. ייתכן שהניסוח בשאלה או בתשובה ג'' מתייחס רק לצד אחד של עסקת החליפין, או שקיימת פרשנות ספציפית לפיה ''ויתור'' בהקשר זה אינו נחשב מכירה נפרדת אלא חלק מהתמורה. עם זאת, על פי ההגדרה הרחבה של ''מכירה'' בחוק, עסקת חליפין היא מכירה דו-צדדית.', 'הטעות הנפוצה היא לבלבל בין הגדרת ''מכירה'' בדיני החוזים לבין הגדרתה הרחבה בחוק מיסוי מקרקעין, ולהתעלם מהחריגים הספציפיים הקבועים בחוק (כגון ירושה או חלוקת עיזבון בין יורשים ללא תמורה חיצונית).',
    '["מס שבח מקרקעין", "מס רכישה", "מכירה", "ירושה", "מתנה במקרקעין", "עסקת חליפין", "חוק מיסוי מקרקעין סעיפים 1, 4, 5"]'::jsonb, '**וריאציה 1 — מתנה כ''מכירה'':** האם מתנה במקרקעין היא ''מכירה'' לעניין מס? ← כן, סעיף 1 לחוק מיסוי מקרקעין. סעיף 1 לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963
**וריאציה 2 — ירושה כ''מכירה'':** האם ירושה היא ''מכירה'' לעניין מס? ← לא, סעיף 4 לחוק מיסוי מקרקעין. סעיף 4 לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963
**וריאציה 3 — עסקת חליפין:** האם עסקת חליפין במקרקעין היא ''מכירה''? ← כן, כל צד בעסקה נחשב כמוכר ורוכש. בני דון-יחייא תורת דיני הירושה (2024) | עסקאות חליפין', 'מתנה ← מכירה. ירושה ← לא מכירה. עסקת חליפין ← מכירה דו-צדדית.', '["חוק מיסוי מקרקעין (שבח ורכישה), התשכ\"ג-1963, סעיפים 1, 4, 5", "בני דון-יחייא תורת דיני הירושה (2024) | עסקאות חליפין"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''tax'' subtopic=''real_estate_tax'' | classifier_note: Inheritance + gift + real-estate transfer — primary subject is real-estate taxation per the source review_note | source_review_note: הסיווג לתת-נושא ''הליכים'' אינו מדויק, שכן השאלה עוסקת בעיקרה בדיני מיסוי מקרקעין. יש לשקול הוספת תת-נושא מתאים יותר ל''דיני מיסוי מקרקעין'' או ''קניין - מיסוי''. בנוסף, יש לבדוק את הניסוח של תשובה ג'' וד'' מול השאלה, שכן נראה כי גם ''ויתור דוד על חלקו בדירה באילת'' (כחלק מעסקת חליפין) צריך להיחשב ''מכירה'', מה שהיה הופך את תשובה ד'' לנכונה יותר. ייתכן שיש פרשנות ספציפית ל''ויתור'' בהקשר זה שאינה מפורטת במקורות שסופקו.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'אף אחת מן הפעולות האמורות.', false, 'טענה זו שגויה. מתנה במקרקעין נחשבת ''מכירה'' לעניין חוק מיסוי מקרקעין, וכך גם עסקת חליפין או העברה בתמורה בין יורשים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'העברת אותו חלק של יונתן בקניון לדוד שבגינו שילם דוד ליונתן את הכסף.', false, 'טענה זו חלקית. היא מזהה נכון את אחת העסקאות כ''מכירה'', אך מתעלמת מפעולות נוספות הנחשבות ''מכירה'' לעניין מיסוי מקרקעין.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'נתינת בניין המגורים במתנה לדוד והעברת אותו חלק של יונתן בקניון לדוד שבגינו שילם דוד ליונתן את הכסף.', true, 'נתינת בניין המגורים במתנה לדוד היא ''מכירה'' לעניין חוק מיסוי מקרקעין (סעיף 1). העברת חלקו של יונתן בקניון לדוד בתמורה לכסף (1,000,000 ש"ח) היא גם ''מכירה'' לעניין החוק. העברת חלקו של דוד בדירה באילת ליונתן, כחלק מעסקת החליפין, היא גם ''מכירה'' לעניין החוק, אך התשובה מתייחסת רק לחלק של יונתן בקניון בתמורה לכסף, וזו מכירה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'נתינת בניין המגורים במתנה לדוד, ויתור דוד על חלקו בדירה באילת והעברת אותו חלק של יונתן בקניון לדוד שבגינו שילם דוד ליונתן את הכסף.', false, 'טענה זו כוללת את נתינת המתנה ואת העברת חלק יונתן בקניון לדוד (שניהם מכירה). אולם, הניסוח ''ויתור דוד על חלקו בדירה באילת'' אינו מדויק. אם הכוונה היא שדוד העביר את חלקו בדירה באילת ליונתן בתמורה לחלקו של יונתן בקניון, זו אכן מכירה. אך אם הכוונה היא לויתור על חלק בירושה ללא תמורה, זה אינו מכירה. בהינתן שהתשובה ג'' היא הנכונה, יש להניח שהניסוח בתשובה ד'' אינו מתאר מכירה נוספת באופן חד משמעי, או שהיא מתייחסת לאותו אירוע של העברת חלק יונתן בקניון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הבחנה בין ירושה למכירה לעניין מס',
    1, 'ראובן נפטר והוריש את דירתו היחידה לבנו יונתן. יונתן, שאינו מעוניין בדירה, מכר אותה לצד שלישי כחודשיים לאחר קבלת צו הירושה. אילו מבין הפעולות המתוארות לעיל חייבות במס שבח מקרקעין?', 'שאלה זו בוחנת את ההבחנה הבסיסית בין ירושה לבין מכירה לעניין חוק מיסוי מקרקעין. היא מדגישה כי ירושה אינה אירוע מס, בעוד שמכירה של נכס שהתקבל בירושה, גם אם נעשית זמן קצר לאחר מכן, נחשבת ''מכירה'' החייבת במס שבח, בכפוף לתנאי פטור.', 'סעיף 4 לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963, קובע במפורש כי ''הורשה אינה מכירה''. משמעות הדבר היא כי העברת זכות במקרקעין מכוח ירושה אינה אירוע מס, ואינה חייבת במס שבח או במס רכישה. לעומת זאת, סעיף 1 לחוק מגדיר ''מכירה'' באופן רחב, הכולל ''העברה או ויתור על זכות במקרקעין''. כאשר יונתן, היורש, מוכר את הדירה לצד שלישי, זוהי עסקת מכירה לכל דבר ועניין, והיא חייבת במס שבח מקרקעין, אלא אם כן יונתן עומד בתנאים לקבלת פטור ממס שבח (למשל, פטור לדירת מגורים מזכה, בכפוף לתנאים הקבועים בחוק).',
    'הטעות הנפוצה היא לבלבל בין אירוע הירושה עצמו לבין מכירה של נכס שהתקבל בירושה, ולחשוב שגם הירושה חייבת במס שבח.', '["מס שבח מקרקעין", "ירושה", "מכירה", "חוק מיסוי מקרקעין סעיף 4", "חוק מיסוי מקרקעין סעיף 1", "פטור ממס שבח"]'::jsonb, '**וריאציה 1 — ירושה כאירוע מס:** האם ירושה היא אירוע מס? ← לא, סעיף 4 לחוק מיסוי מקרקעין קובע ''הורשה אינה מכירה''. סעיף 4 לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963
**וריאציה 2 — מכירה לאחר ירושה:** האם מכירה של נכס שהתקבל בירושה חייבת במס? ← כן, זו ''מכירה'' רגילה החייבת במס שבח, בכפוף לפטורים. ת"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)

**וריאציה 3 — פטור לדירת מגורים מזכה:** האם יורש יכול ליהנות מפטור ממס שבח לדירת מגורים מזכה? ← כן, בכפוף לתנאים הקבועים בסעיף 49ב(5) לחוק. סעיף 49ב(5) לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963', 'ירושה ← לא מכירה (פטור ממס) ← מכירה לאחר ירושה ← חייבת במס (בכפוף לפטורים).',
    '["חוק מיסוי מקרקעין (שבח ורכישה), התשכ\"ג-1963, סעיפים 1, 4, 49ב(5)", "ת\"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'הורשת הדירה ליונתן בלבד.', false, 'טענה זו שגויה. ירושה אינה נחשבת ''מכירה'' לעניין חוק מיסוי מקרקעין, ולכן אינה חייבת במס שבח.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'מכירת הדירה לצד שלישי בלבד.', true, 'הורשת הדירה ליונתן אינה ''מכירה'' לעניין חוק מיסוי מקרקעין (סעיף 4). לעומת זאת, מכירת הדירה על ידי יונתן לצד שלישי, גם אם נעשתה זמן קצר לאחר הירושה, נחשבת ''מכירה'' החייבת במס שבח, אלא אם כן יונתן עומד בתנאים לפטור ממס שבח.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'הורשת הדירה ליונתן ומכירתה לצד שלישי.', false, 'טענה זו שגויה. ירושה אינה חייבת במס שבח, רק המכירה שלאחר מכן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'אף אחת מן הפעולות האמורות.', false, 'טענה זו שגויה. מכירת הדירה לצד שלישי היא ''מכירה'' החייבת במס שבח, בכפוף לתנאי פטור.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מתנה במקרקעין לעניין מס רכישה',
    2, 'אב העביר לבנו דירת מגורים במתנה. האם הבן יהיה חייב במס רכישה בגין קבלת המתנה?', 'שאלה זו עוסקת במיסוי מתנות במקרקעין, ובפרט במס רכישה. היא מדגישה כי אף שמתנה נחשבת ''מכירה'' לעניין חוק מיסוי מקרקעין, קיימות הוראות ספציפיות המעניקות הנחות משמעותיות במס רכישה כאשר המתנה ניתנת לקרוב משפחה, כגון בין הורים לילדים.', 'סעיף 1 לחוק מיסוי מקרקעין (שבח ורכישה) מגדיר ''מכירה'' באופן רחב, הכולל גם ''העברה או ויתור על זכות במקרקעין... אף אם לא נקבע לה תמורה''. לכן, מתנה במקרקעין נחשבת ''מכירה'' לעניין החוק. כתוצאה מכך, מקבל המתנה חייב במס רכישה. אולם, תקנה 20 לתקנות מיסוי מקרקעין (שבח ורכישה) (מס רכישה), התשל"ה-1974, קובעת שיעורי מס רכישה מופחתים במקרה של העברת זכות במקרקעין ללא תמורה לקרוב. ''קרוב'' מוגדר בסעיף 1 לחוק כ''בן-זוג, הורה, הורי הורה, צאצא, בן-זוגו של צאצא, אח ואחות''. במקרה של העברה בין הורים לילדים, שיעור מס הרכישה הוא שליש ממס הרכישה שהיה משולם בעסקה רגילה.',
    'הטעות היא לחשוב שמתנה פטורה ממס רכישה לחלוטין, או לבלבל בין הפטור ממס שבח (המותנה בתקופת צינון) לבין ההנחה במס רכישה.', '["מס רכישה", "מתנה במקרקעין", "קרוב", "תקנות מיסוי מקרקעין", "העברה ללא תמורה", "שיעור מס מופחת"]'::jsonb, '**וריאציה 1 — מתנה כ''מכירה'':** האם מתנה היא ''מכירה'' לעניין חוק מיסוי מקרקעין? ← כן, סעיף 1 לחוק. סעיף 1 לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963
**וריאציה 2 — מס רכישה לקרוב:** מהו שיעור מס הרכישה במתנה לקרוב? ← שליש ממס הרכישה הרגיל. תקנה 20 לתקנות מיסוי מקרקעין (שבח ורכישה) (מס רכישה), התשל"ה-1974
**וריאציה 3 — הגדרת קרוב:** מי נחשב ''קרוב'' לעניין זה? ← בן-זוג, הורה, צאצא, בן-זוגו של צאצא, אח ואחות. סעיף 1 לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963', 'מתנה במקרקעין ← חייבת במס רכישה ← הנחה משמעותית לקרוב (שליש).',
    '["חוק מיסוי מקרקעין (שבח ורכישה), התשכ\"ג-1963, סעיף 1", "תקנות מיסוי מקרקעין (שבח ורכישה) (מס רכישה), התשל\"ה-1974, תקנה 20"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'לא, קבלת מתנה במקרקעין פטורה ממס רכישה באופן מוחלט.', false, 'טענה זו שגויה. קבלת מתנה במקרקעין אינה פטורה ממס רכישה באופן מוחלט, אלא ניתנת הנחה משמעותית בתנאים מסוימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כן, אך הוא יהיה זכאי להנחה משמעותית במס רכישה, בהתאם לקרבת המשפחה.', true, 'קבלת מתנה במקרקעין נחשבת ''רכישה'' לעניין חוק מיסוי מקרקעין. אולם, תקנות מיסוי מקרקעין (שבח ורכישה) (מס רכישה), התשל"ה-1974, קובעות שיעורי מס רכישה מופחתים במקרה של העברת זכות במקרקעין ללא תמורה לקרוב. במקרה של העברה בין הורים לילדים, שיעור המס הוא שליש ממס הרכישה הרגיל.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, הוא יהיה חייב במס רכישה מלא, שכן מתנה נחשבת מכירה לכל דבר ועניין.', false, 'טענה זו שגויה. אף שמתנה היא ''מכירה'', קיימת הוראת חוק ספציפית המעניקה הנחה במס רכישה לקרובים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לא, אלא אם כן הבן ימכור את הדירה תוך שנה מיום קבלת המתנה.', false, 'טענה זו שגויה. תקופת צינון רלוונטית לפטור ממס שבח במכירת דירה שהתקבלה במתנה, ולא למס רכישה על קבלת המתנה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'העברת זכויות בין יורשים לעניין מס',
    3, 'ראובן נפטר והותיר אחריו דירה ושני בנים, שמעון ולוי, כיורשים על פי דין. שמעון ולוי הסכימו ביניהם כי שמעון יקבל את הדירה במלואה, ולוי יקבל את כל יתרת העיזבון (כספים ומיטלטלין). האם הסכם זה בין היורשים מהווה ''מכירה'' לעניין חוק מיסוי מקרקעין?', 'שאלה זו בוחנת את החריג הקבוע בסעיף 5(ג) לחוק מיסוי מקרקעין, לפיו העברת זכות במקרקעין על פי הסכם בין יורשים שבמסגרת חלוקת עיזבון אינה נחשבת ''מכירה''. היא מדגישה את הרציונל שמאחורי חריג זה, המאפשר ליורשים לחלק את נכסי העיזבון ביניהם ללא חיוב במס, כל עוד אין תמורה חיצונית לעיזבון.', 'סעיף 5(ג) לחוק מיסוי מקרקעין (שבח ורכישה) קובע חריג חשוב לכלל הרחב של ''מכירה'', וקובע כי ''העברה על פי הסכם בין יורשים שבמסגרת חלוקת עיזבון, אינה נחשבת ''מכירה''''. מטרת הסעיף היא לאפשר ליורשים לחלק את נכסי העיזבון ביניהם באופן שונה מחלוקתם על פי דין או צוואה, מבלי שייווצר אירוע מס. התנאי המרכזי לתחולת החריג הוא שהחלוקה תהיה ''במסגרת חלוקת עיזבון'', כלומר, שהיא תכלול רק נכסים מתוך העיזבון, וכי לא תהיה תמורה חיצונית לעיזבון. במקרה זה, שמעון מקבל את הדירה (נכס עיזבון) ולוי מקבל את יתרת העיזבון (כספים ומיטלטלין). זוהי חלוקה ''במסגרת חלוקת עיזבון'', ולכן העברת הדירה משמעון ללוי (או להיפך, בהתאם לחלוקה המקורית) לא תיחשב ''מכירה'' לעניין חוק מיסוי מקרקעין.',
    'הטעות היא לחשוב שכל העברת זכות במקרקעין בין יורשים חייבת במס, מבלי לזכור את החריג המיוחד של סעיף 5(ג) לחוק מיסוי מקרקעין.', '["חלוקת עיזבון", "הסכם בין יורשים", "חוק מיסוי מקרקעין סעיף 5(ג)", "אירוע מס", "תמורה חיצונית", "יורשים על פי דין"]'::jsonb, '**וריאציה 1 — חלוקת עיזבון:** האם חלוקת עיזבון בין יורשים היא מכירה? ← לא, סעיף 5(ג) לחוק מיסוי מקרקעין. סעיף 5(ג) לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963
**וריאציה 2 — תמורה חיצונית:** מה קורה אם יש תמורה חיצונית לעיזבון? ← אז החריג לא יחול, וזה ייחשב מכירה. ת"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)

**וריאציה 3 — רציונל החריג:** מה הרציונל מאחורי סעיף 5(ג)? ← לאפשר ליורשים לחלק את נכסי העיזבון ביניהם ללא חיוב במס. בני דון-יחייא תורת דיני הירושה (2024) | חלוקת עיזבון', 'חלוקת עיזבון בין יורשים ← לא מכירה (סעיף 5(ג)) ← בתנאי שאין תמורה חיצונית.',
    '["חוק מיסוי מקרקעין (שבח ורכישה), התשכ\"ג-1963, סעיף 5(ג)", "ת\"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)", "בני דון-יחייא תורת דיני הירושה (2024) | חלוקת עיזבון"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, כל העברת זכות במקרקעין בין יורשים, גם אם היא במסגרת חלוקת עיזבון, נחשבת ''מכירה''.', false, 'טענה זו שגויה. סעיף 5(ג) לחוק מיסוי מקרקעין קובע חריג מפורש לעניין חלוקת עיזבון בין יורשים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, חלוקת נכסי עיזבון בין יורשים אינה נחשבת ''מכירה'', כל עוד היא נעשית בין היורשים עצמם ואינה כוללת תמורה חיצונית לעיזבון.', true, 'סעיף 5(ג) לחוק מיסוי מקרקעין קובע כי ''העברת זכות במקרקעין מנאמן לנהנה, וכן העברה על פי הסכם בין יורשים שבמסגרת חלוקת עיזבון, אינן נחשבות ''מכירה''''. כל עוד החלוקה נעשית בין היורשים עצמם, ואינה כוללת תמורה חיצונית לעיזבון, היא לא תהווה אירוע מס.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן הדירה היא דירת מגורים מזכה, ואז היא פטורה ממס.', false, 'טענה זו שגויה. הפטור לדירת מגורים מזכה רלוונטי למכירה רגילה, אך כאן השאלה היא האם מדובר במכירה מלכתחילה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אך רק אם הסכם החלוקה אושר על ידי בית המשפט לענייני משפחה.', false, 'טענה זו שגויה. אישור בית המשפט אינו תנאי לכך שהעברה במסגרת חלוקת עיזבון לא תיחשב ''מכירה'' לעניין מס.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'העברת זכויות במקרקעין ללא תמורה',
    4, 'ראובן העביר את זכותו במקרקעין לחברו שמעון ללא כל תמורה. האם העברה זו נחשבת ''מכירה'' לעניין חוק מיסוי מקרקעין?', 'שאלה זו מתמקדת בהגדרה הרחבה של ''מכירה'' בחוק מיסוי מקרקעין, הכוללת גם העברות זכויות ללא תמורה. היא מדגישה כי גם פעולות שאינן נחשבות ''מכירה'' בדיני החוזים הרגילים, עשויות להיחשב ''מכירה'' לעניין דיני המס, ולגרור חיוב במס שבח ובמס רכישה (בכפוף לפטורים והנחות).', 'סעיף 1 לחוק מיסוי מקרקעין (שבח ורכישה) קובע הגדרה רחבה למונח ''מכירה''. ההגדרה כוללת ''העברה או ויתור על זכות במקרקעין... אף אם לא נקבע לה תמורה''. משמעות הדבר היא כי גם העברת זכות במקרקעין ללא תמורה, כגון מתנה, נחשבת ''מכירה'' לעניין חוק מיסוי מקרקעין. כתוצאה מכך, העברה כזו עשויה להיות חייבת במס שבח (על המעביר) ובמס רכישה (על המקבל), אלא אם כן קיימים פטורים או הנחות ספציפיים בחוק או בתקנות (למשל, הנחה במס רכישה לקרוב, או פטור ממס שבח במכירת דירת מגורים מזכה שהתקבלה במתנה לאחר תקופת צינון).',
    'הטעות היא להחיל את ההגדרה הצרה של ''מכירה'' מדיני החוזים על דיני מיסוי מקרקעין, ולהתעלם מההגדרה הרחבה של ''מכירה'' בחוק מיסוי מקרקעין, הכוללת גם העברות ללא תמורה.', '["מכירה", "העברה ללא תמורה", "חוק מיסוי מקרקעין סעיף 1", "מס שבח", "מס רכישה", "מתנה"]'::jsonb, '**וריאציה 1 — הגדרת מכירה:** מה כוללת הגדרת ''מכירה'' בחוק מיסוי מקרקעין? ← העברה או ויתור על זכות במקרקעין, גם ללא תמורה. סעיף 1 לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963
**וריאציה 2 — השלכות מס:** מהן השלכות המס של העברה ללא תמורה? ← חיוב במס שבח ובמס רכישה, בכפוף לפטורים והנחות. בני דון-יחייא תורת דיני הירושה (2024) | מיסוי מתנות
**וריאציה 3 — פטורים והנחות:** אילו פטורים והנחות קיימים? ← הנחה במס רכישה לקרוב, פטור ממס שבח לדירת מגורים מזכה לאחר תקופת צינון. סעיף 49ב(5) לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963', 'העברה ללא תמורה ← מכירה לעניין מס ← חייבת במס שבח ורכישה ← בכפוף לפטורים/הנחות.',
    '["חוק מיסוי מקרקעין (שבח ורכישה), התשכ\"ג-1963, סעיפים 1, 49ב(5)", "בני דון-יחייא תורת דיני הירושה (2024) | מיסוי מתנות"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, שכן לא שולמה תמורה בגין העברת הזכות.', false, 'טענה זו שגויה. הגדרת ''מכירה'' בחוק מיסוי מקרקעין כוללת גם העברה ללא תמורה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, סעיף 1 לחוק מיסוי מקרקעין מגדיר ''מכירה'' באופן רחב הכולל גם העברה ללא תמורה.', true, 'סעיף 1 לחוק מיסוי מקרקעין (שבח ורכישה) מגדיר ''מכירה'' כ''העברה או ויתור על זכות במקרקעין... אף אם לא נקבע לה תמורה''. לכן, העברת זכות במקרקעין ללא תמורה, כגון מתנה, נחשבת ''מכירה'' לעניין החוק, והיא חייבת במס שבח ובמס רכישה (בכפוף לפטורים והנחות).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, אלא אם כן שמעון הוא קרוב משפחה של ראובן.', false, 'טענה זו שגויה. קרבת משפחה רלוונטית להנחות ופטורים, אך לא לעצם הגדרת הפעולה כ''מכירה''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם שמעון ימכור את המקרקעין תוך תקופת צינון מסוימת.', false, 'טענה זו שגויה. תקופת צינון רלוונטית לפטור ממס שבח במכירה עתידית, ולא לעצם הגדרת העברה ללא תמורה כ''מכירה''.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 37, '2023-S-S-Q37';
END
$$;

