  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q38', v_chapter_id, v_subtopic_id, 'שון מתמחה של עו"ד ורדי במשרד עורכי הדין הלל ושות'' והחל את התמחותו לפני כחצי שנה. בזמן היעדרותו של עו"ד ורדי מהמשרד לצורך נסיעה עסקית לחו"ל, נוצר צורך לאמת את חתימתו של לקוח חדש של עו"ד ורדי על ייפוי כוח שערך עו"ד ורדי בטרם נסיעתו לחו"ל. שון התקשר לעו"ד ורדי ועדכן אותו כי יש לאמת בדחיפות את חתימתו של הלקוח על ייפוי הכוח לטובת הגשתו בהליך משפטי וכי הדבר אינו סובל דיחוי. מפאת הבהילות הציע שון לעו"ד ורדי כי הוא (שון) יאמת את חתימתו של הלקוח על גבי ייפוי הכוח. עו"ד ורדי נתן את הסכמתו להצעה זו של שון. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 38}'::jsonb, 'השאלה עוסקת בסמכויותיו של מתמחה בעריכת דין, ובפרט באיסור עליו לבצע פעולות השמורות לעורך דין מוסמך, כגון אימות חתימה על ייפוי כוח. היא בוחנת את תחולת סעיפים 20 ו-41 לחוק לשכת עורכי הדין, התשכ"א-1961, ומדגישה כי לא ניתן להתגבר על איסורים אלו באמצעות אישור המאמן או דחיפות העניין.', 'חוק לשכת עורכי הדין, התשכ"א-1961, קובע את סמכויות המתמחה. סעיף 20(א) מפרט את הפעולות שמותר למתמחה לבצע, ואימות חתימה על ייפוי כוח אינו נכלל ברשימה זו. יתרה מכך, סעיף 41 לחוק קובע איסור מוחלט על מי שאינו עורך דין לעסוק בעריכת דין. אימות חתימה על ייפוי כוח נחשב ''עיסוק בעריכת דין'' במובנו הרחב, שכן הוא מהווה פעולה משפטית פורמלית המטילה אחריות מקצועית. לכן, מתמחה, שאינו עורך דין מוסמך, אינו רשאי לבצע פעולה זו. אישור המאמן או דחיפות העניין אינם יכולים להכשיר פעולה האסורה על פי חוק. המאמן, עו"ד ורדי, אף הוא עלול לשאת באחריות משמעתית בגין מתן אישור למתמחה לבצע פעולה שאינו מוסמך לה.', 'הטעות הנפוצה היא לחשוב שאישור המאמן או דחיפות העניין יכולים להכשיר פעולות האסורות על מתמחה על פי חוק, או לבלבל בין סמכויות המתמחה לייצג בבתי משפט מסוימים לבין פעולות אחרות השמורות לעורך דין מוסמך.',
    '["מתמחה", "חוק לשכת עורכי הדין סעיף 20", "חוק לשכת עורכי הדין סעיף 41", "אימות חתימה", "ייפוי כוח", "עיסוק בעריכת דין", "אחריות מקצועית"]'::jsonb, '**וריאציה 1 — סמכות מתמחה:** האם מתמחה רשאי לאמת חתימה על ייפוי כוח? ← לא, זו פעולה השמורה לעורך דין מוסמך. סעיף 20(א) לחוק לשכת עורכי הדין, התשכ"א-1961
**וריאציה 2 — איסור עיסוק בעריכת דין:** מדוע אסור למתמחה לאמת חתימה? ← אימות חתימה הוא ''עיסוק בעריכת דין'' האסור על מי שאינו עו"ד. סעיף 41 לחוק לשכת עורכי הדין, התשכ"א-1961
**וריאציה 3 — אישור מאמן ודחיפות:** האם אישור מאמן או דחיפות מכשירים את הפעולה? ← לא, חוק לשכת עורכי הדין קובע איסור מוחלט. בני דון-יחייא תורת דיני הירושה (2024) | סמכויות מתמחה', 'מתמחה ← אינו עו"ד מוסמך ← אינו רשאי לאמת חתימה ← גם לא באישור או דחיפות.', '["חוק לשכת עורכי הדין, התשכ\"א-1961, סעיפים 20, 41", "בני דון-יחייא תורת דיני הירושה (2024) | סמכויות מתמחה"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''licensing_bar_membership'' | classifier_note: Intern (מתמחה) authority to authenticate signatures — falls under licensing/bar rules | source_review_note: הסיווג לתת-נושא ''משמעת עורכי דין'' אינו מדויק, שכן השאלה עוסקת בסמכות מתמחה ולא בהליך משמעתי. יש לשקול הוספת תת-נושא מתאים יותר ל''הסמכה ורישוי עורכי דין'' או ''סמכויות מתמחה'' תחת פרק רחב יותר של ''דיני לשכת עורכי הדין''.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'שון לא רשאי לאמת את חתימת הלקוח על גבי ייפוי הכוח היות שמדובר במסמך משפטי.', true, 'אימות חתימה על ייפוי כוח נחשב ''עיסוק בעריכת דין'' הדורש רישיון עורך דין. מתמחה אינו עורך דין מוסמך, ולכן אינו רשאי לבצע פעולה זו, גם אם קיבל אישור מהמאמן וגם אם קיים דחיפות.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'שון רשאי לאמת את חתימת הלקוח על גבי ייפוי הכוח, שכן די בכך שעו"ד ורדי אישר זאת.', false, 'טענה זו שגויה. אישור המאמן אינו מקנה למתמחה סמכות לבצע פעולות השמורות לעורך דין מוסמך, כגון אימות חתימה על ייפוי כוח.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'שון לא רשאי לאמת את חתימת הלקוח על גבי ייפוי הכוח רק משום שטרם חלפו 8 חודשים מאז החלה התמחותו.', false, 'טענה זו שגויה. מגבלת הזמן של 6 חודשים (ולא 8) רלוונטית לייצוג בבתי משפט מסוימים, אך אינה קשורה לאימות חתימה על ייפוי כוח, שהיא פעולה האסורה על מתמחה בכל עת.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'שון רשאי לאמת את חתימתו של הלקוח על גבי ייפוי הכוח היות שהדבר אינו סובל דיחוי ובנוסף עו"ד ורדי אישר זאת.', false, 'טענה זו שגויה. דחיפות או אישור המאמן אינם מכשירים פעולה האסורה על מתמחה מכוח חוק לשכת עורכי הדין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'סמכות מתמחה לייצג בבית משפט',
    1, 'מתמחה, שחלפו 7 חודשים מתחילת התמחותו, מבקש לייצג לקוח בבית משפט השלום בתביעה אזרחית. האם המתמחה רשאי לייצג את הלקוח בבית משפט השלום?', 'שאלה זו בוחנת את סמכויות המתמחה לייצג בבתי משפט, כפי שנקבעו בחוק לשכת עורכי הדין. היא מדגישה את מגבלות הזמן והערכאות בהן מותר למתמחה להופיע, ומבחינה בין פעולות אלו לבין פעולות אחרות השמורות לעורך דין מוסמך.', 'סעיף 20(א)(4) לחוק לשכת עורכי הדין, התשכ"א-1961, קובע כי מתמחה רשאי ''להופיע בבית משפט השלום, בבית הדין לעבודה ובבית הדין הרבני, וכן בפני רשם ההוצאה לפועל, רשם המקרקעין, רשם החברות ורשם האגודות השיתופיות, ובלבד שחלפו ששה חודשים מתחילת התמחותו''. במקרה זה, חלפו 7 חודשים מתחילת ההתמחות, ולכן המתמחה רשאי לייצג את הלקוח בבית משפט השלום. חשוב לזכור כי פעולות אלו נעשות תחת פיקוחו ואחריותו של המאמן.',
    'הטעות הנפוצה היא לחשוב שמתמחה אינו רשאי לייצג כלל בבתי משפט, או לבלבל בין תקופת ההכשרה הנדרשת לייצוג בערכאות שונות.', '["מתמחה", "ייצוג בבית משפט", "חוק לשכת עורכי הדין סעיף 20(א)(4)", "תקופת התמחות", "סמכויות מתמחה"]'::jsonb, '**וריאציה 1 — ייצוג בבית משפט השלום:** מתי מתמחה רשאי לייצג בבית משפט השלום? ← לאחר 6 חודשי התמחות. סעיף 20(א)(4) לחוק לשכת עורכי הדין, התשכ"א-1961
**וריאציה 2 — ייצוג בבית משפט מחוזי:** האם מתמחה רשאי לייצג בבית משפט מחוזי? ← לא, רק עורך דין מוסמך. סעיף 20(ב) לחוק לשכת עורכי הדין, התשכ"א-1961
**וריאציה 3 — אחריות המאמן:** מי נושא באחריות למעשי המתמחה? ← המאמן. סעיף 20(ג) לחוק לשכת עורכי הדין, התשכ"א-1961', 'מתמחה ← ייצוג בבית משפט השלום ← לאחר 6 חודשים.',
    '["חוק לשכת עורכי הדין, התשכ\"א-1961, סעיף 20"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, מתמחה אינו רשאי לייצג לקוחות בבית משפט כלל.', false, 'טענה זו שגויה. חוק לשכת עורכי הדין מאפשר למתמחה לייצג בבתי משפט מסוימים לאחר תקופה מסוימת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, מתמחה רשאי לייצג בבית משפט השלום לאחר שחלפו שישה חודשים מתחילת התמחותו.', true, 'סעיף 20(א)(4) לחוק לשכת עורכי הדין קובע כי מתמחה רשאי להופיע בבית משפט השלום, בבית הדין לעבודה ובבית הדין הרבני, וכן בפני רשם ההוצאה לפועל, רשם המקרקעין, רשם החברות ורשם האגודות השיתופיות, ובלבד שחלפו שישה חודשים מתחילת התמחותו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם המאמן נוכח באולם בית המשפט ומפקח על הייצוג.', false, 'טענה זו שגויה. נוכחות המאמן אינה תנאי לייצוג בבית משפט השלום לאחר שחלפו שישה חודשים, אם כי המתמחה פועל תחת פיקוחו הכללי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן קיבל אישור מיוחד מלשכת עורכי הדין.', false, 'טענה זו שגויה. האישור לייצוג בבתי משפט אלו לאחר 6 חודשים הוא סטטוטורי ואינו דורש אישור מיוחד נוסף.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגדרת ''עיסוק בעריכת דין''',
    2, 'אדם שאינו עורך דין מוסמך, מציע שירותי ייעוץ משפטי בתחום המקרקעין תמורת תשלום, ומנסח עבור לקוחותיו הסכמי מכר. האם פעולות אלו נחשבות ''עיסוק בעריכת דין''?', 'שאלה זו עוסקת בהגדרת ''עיסוק בעריכת דין'' על פי חוק לשכת עורכי הדין, ובאיסור על מי שאינו עורך דין מוסמך לעסוק בו. היא מדגישה את רוחב ההגדרה, הכוללת ייעוץ משפטי ועריכת מסמכים משפטיים, ולא רק ייצוג בבתי משפט.', 'סעיף 1 לחוק לשכת עורכי הדין, התשכ"א-1961, מגדיר ''עיסוק בעריכת דין'' באופן רחב, וכולל בו: ''ייצוג אדם אחר וכל פעולה אחרת בשמו, בפני כל בית משפט, בית דין, בורר, רשם או פקיד, וכן בפני כל אדם או גוף אחר, אם הם בעלי סמכות שיפוטית או מעין שיפוטית, או אם הם בעלי סמכות על פי דין לברר עניינים משפטיים; ייעוץ וחיווי דעת משפטיים; עריכת מסמכים בעלי אופי משפטי, לרבות חוזים, צוואות, תצהירים, כתבי טענות, בקשות, הודעות, ערעורים, וכל מסמך אחר הדרוש להליך משפטי או לביצוע פעולה משפטית''. ייעוץ משפטי בתחום המקרקעין וניסוח הסכמי מכר נכללים במפורש בהגדרה זו, ולכן הם שמורים לעורכי דין מוסמכים בלבד. סעיף 41 לחוק אוסר על מי שאינו עורך דין לעסוק בעריכת דין.',
    'הטעות היא לצמצם את הגדרת ''עיסוק בעריכת דין'' רק לייצוג בבתי משפט, ולהתעלם מפעולות כמו ייעוץ ועריכת מסמכים.', '["עיסוק בעריכת דין", "חוק לשכת עורכי הדין סעיף 1", "חוק לשכת עורכי הדין סעיף 41", "ייעוץ משפטי", "עריכת מסמכים משפטיים", "איסור עיסוק בעריכת דין"]'::jsonb, '**וריאציה 1 — הגדרת עיסוק בעריכת דין:** מה כוללת הגדרת ''עיסוק בעריכת דין''? ← ייצוג, ייעוץ ועריכת מסמכים משפטיים. סעיף 1 לחוק לשכת עורכי הדין, התשכ"א-1961

**וריאציה 2 — איסור עיסוק:** מי רשאי לעסוק בעריכת דין? ← רק עורך דין מוסמך. סעיף 41 לחוק לשכת עורכי הדין, התשכ"א-1961
**וריאציה 3 — חריגים:** האם יש חריגים לאיסור? ← כן, למשל מתמחה בפעולות מסוימות, או ייצוג עצמי. סעיף 20 לחוק לשכת עורכי הדין, התשכ"א-1961', 'עיסוק בעריכת דין ← ייצוג, ייעוץ, מסמכים ← שמור לעו"ד מוסמך.',
    '["חוק לשכת עורכי הדין, התשכ\"א-1961, סעיפים 1, 20, 41"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'לא, רק ייצוג בבית משפט נחשב ''עיסוק בעריכת דין''.', false, 'טענה זו שגויה. הגדרת ''עיסוק בעריכת דין'' רחבה וכוללת פעולות רבות מעבר לייצוג בבית משפט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כן, ייעוץ משפטי ועריכת מסמכים משפטיים נחשבים ''עיסוק בעריכת דין'' השמור לעורכי דין מוסמכים.', true, 'סעיף 1 לחוק לשכת עורכי הדין מגדיר ''עיסוק בעריכת דין'' באופן רחב, הכולל בין היתר ייצוג בפני בתי משפט ורשויות, ייעוץ משפטי ועריכת מסמכים בעלי אופי משפטי. פעולות אלו שמורות לעורכי דין מוסמכים בלבד.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'רק ניסוח הסכמי מכר נחשב ''עיסוק בעריכת דין'', אך לא ייעוץ משפטי.', false, 'טענה זו שגויה. גם ייעוץ משפטי הוא חלק מ''עיסוק בעריכת דין'' על פי החוק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'רק אם האדם מציג עצמו כעורך דין, ייחשבו פעולותיו כ''עיסוק בעריכת דין''.', false, 'טענה זו שגויה. עצם ביצוע הפעולות המוגדרות בחוק כ''עיסוק בעריכת דין'' הוא הקובע, ללא קשר להצגה עצמית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'אימות חתימה על ידי עורך דין',
    3, 'עורך דין מוסמך מתבקש לאמת חתימה של לקוח על ייפוי כוח כללי. מהם התנאים שעל עורך הדין לקיים כדי לאמת את החתימה כדין?', 'שאלה זו מתמקדת בתנאים הנדרשים מעורך דין מוסמך בעת אימות חתימה על ייפוי כוח. היא מדגישה את חובותיו של עורך הדין לוודא את זהות החותם, את חתימתו בפניו ואת הבנתו ורצונו החופשי, כחלק מהאחריות המקצועית הכרוכה בפעולה זו.', 'אימות חתימה על ייפוי כוח הוא פעולה משפטית מהותית, המטילה אחריות כבדה על עורך הדין המאמת. על עורך הדין לוודא מספר תנאים: ראשית, שהחותם הוא אכן האדם הנכון, כלומר, עליו לזהות את הלקוח באופן ודאי (לרוב באמצעות תעודת זהות). שנית, עליו לוודא שהלקוח חותם על המסמך בפניו, או מאשר בפניו כי החתימה המופיעה על המסמך היא חתימתו. שלישית, עליו לוודא שהלקוח מבין את מהות המסמך ואת ההשלכות המשפטיות של ייפוי הכוח, וכי הוא חותם עליו מרצונו החופשי וללא כפייה. אי עמידה בתנאים אלו עלולה לגרור אחריות משמעתית ואף אזרחית על עורך הדין.',
    'הטעות היא להקל ראש בחובות עורך הדין בעת אימות חתימה, או לחשוב שדי באישור טלפוני או בדיעבד.', '["אימות חתימה", "ייפוי כוח", "עורך דין", "זיהוי חותם", "חתימה בפני עורך דין", "אחריות מקצועית"]'::jsonb, '**וריאציה 1 — חובות עורך דין:** מהם התנאים לאימות חתימה על ידי עו"ד? ← זיהוי החותם, חתימה בפניו, הבנת המסמך ורצון חופשי. בני דון-יחייא תורת דיני הירושה (2024) | אימות חתימה
**וריאציה 2 — ייפוי כוח כללי:** האם ייפוי כוח כללי דורש אימות נוטריוני? ← לא בהכרח, גם עו"ד רשאי לאמת. סעיף 1 לחוק לשכת עורכי הדין, התשכ"א-1961
**וריאציה 3 — השלכות אי-עמידה בתנאים:** מהן ההשלכות של אי-עמידה בתנאים? ← אחריות משמעתית ואזרחית. ת"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)', 'אימות חתימה ← עו"ד מוסמך ← זיהוי, חתימה בפניו, הבנה ורצון.',
    '["חוק לשכת עורכי הדין, התשכ\"א-1961, סעיף 1", "בני דון-יחייא תורת דיני הירושה (2024) | אימות חתימה", "ת\"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'עורך הדין צריך לוודא שהלקוח חתם בפניו, וכי הוא מזהה את הלקוח.', true, 'כדי לאמת חתימה על ייפוי כוח, עורך הדין חייב לוודא שהלקוח חתם בפניו, וכי הוא מזהה את הלקוח באופן ודאי. בנוסף, עליו לוודא שהלקוח מבין את משמעות ייפוי הכוח וחותם עליו מרצונו החופשי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'עורך הדין צריך רק לוודא שהלקוח מבין את משמעות ייפוי הכוח, ואין חובה לזהות אותו.', false, 'טענה זו שגויה. זיהוי הלקוח הוא תנאי מהותי לאימות חתימה, בנוסף להבנת משמעות המסמך.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'עורך הדין יכול לאמת את החתימה גם אם הלקוח לא חתם בפניו, ובלבד שהלקוח אישר שהחתימה שלו.', false, 'טענה זו שגויה. אימות חתימה מחייב שהחתימה תבוצע בפני עורך הדין המאמת, או שהחותם יאשר בפניו כי זו חתימתו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'רק נוטריון רשאי לאמת חתימה על ייפוי כוח כללי, ולא עורך דין.', false, 'טענה זו שגויה. אף שנוטריון מוסמך לאמת חתימות, גם עורך דין רשאי לאמת חתימה על ייפוי כוח כללי, בכפוף לתנאים הקבועים בחוק ובפסיקה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השלכות אימות חתימה שלא כדין',
    4, 'מתמחה אימת חתימה על ייפוי כוח, פעולה שאינו מוסמך לבצע. מהן ההשלכות המשפטיות האפשריות של פעולה זו?', 'שאלה זו בוחנת את ההשלכות המשפטיות של פעולה שבוצעה על ידי מתמחה בחוסר סמכות, ובפרט אימות חתימה על ייפוי כוח. היא מדגישה את הפגיעה האפשרית בתוקף המסמך, ואת האחריות המשמעתית והאזרחית המוטלת הן על המתמחה והן על המאמן.', 'פעולה של אימות חתימה על ייפוי כוח, שבוצעה על ידי מתמחה שאינו מוסמך לכך, עלולה להביא לבטלות ייפוי הכוח, שכן מדובר בפגם מהותי בסמכות המאמת. בנוסף, המתמחה, שביצע פעולה האסורה עליו מכוח סעיף 41 לחוק לשכת עורכי הדין (עיסוק בעריכת דין ללא רישיון), חשוף להליכים משמעתיים בלשכת עורכי הדין. גם המאמן, עו"ד ורדי במקרה זה, חשוף להליכים משמעתיים בגין אחריותו לפיקוח על המתמחה (סעיף 20(ג) לחוק) ומתן אישור לפעולה אסורה. כמו כן, שני הצדדים עלולים להיות חשופים לתביעות אזרחיות בגין נזקים שנגרמו כתוצאה מפעולה זו.',
    'הטעות היא להמעיט בחומרת ההשלכות של פעולה שבוצעה בחוסר סמכות, או לחשוב שרק המתמחה או רק המאמן יישאו באחריות.', '["בטלות מסמך", "הליכים משמעתיים", "אחריות מתמחה", "אחריות מאמן", "חוק לשכת עורכי הדין סעיף 41", "חוסר סמכות"]'::jsonb, '**וריאציה 1 — תוקף המסמך:** מה תוקפו של ייפוי כוח שאומת שלא כדין? ← בטל מעיקרו. בני דון-יחייא תורת דיני הירושה (2024) | תוקף מסמכים
**וריאציה 2 — אחריות משמעתית:** מי חשוף להליכים משמעתיים? ← המתמחה והמאמן. סעיף 41 לחוק לשכת עורכי הדין, התשכ"א-1961
**וריאציה 3 — אחריות אזרחית:** האם קיימת אחריות אזרחית? ← כן, בגין נזקים שנגרמו. ת"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)', 'אימות שלא כדין ← בטלות מסמך ← אחריות משמעתית למתמחה ולמאמן ← אחריות אזרחית.',
    '["חוק לשכת עורכי הדין, התשכ\"א-1961, סעיפים 20(ג), 41", "בני דון-יחייא תורת דיני הירושה (2024) | תוקף מסמכים", "ת\"ע (משפחה ירושלים) 17687-06-17 ש.י.ח נ'' א.מ (22.09.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'ייפוי הכוח יהיה בטל מעיקרו, והמתמחה והמאמן יהיו חשופים להליכים משמעתיים.', true, 'פעולה שמתמחה אינו מוסמך לבצע, ובפרט אימות חתימה על ייפוי כוח, עלולה להביא לבטלות המסמך. בנוסף, המתמחה והמאמן (בגין אחריות לפיקוח) חשופים להליכים משמעתיים בלשכת עורכי הדין, ואף לתביעות אזרחיות בגין נזקים שנגרמו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'ייפוי הכוח יהיה תקף, אך המתמחה יהיה חשוף להליך משמעתי בלבד.', false, 'טענה זו שגויה. פעולה שבוצעה בחוסר סמכות מהותי עלולה לפגוע בתוקף המסמך, והמאמן גם הוא חשוף לאחריות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'ייפוי הכוח יהיה תקף, אך המאמן יהיה חשוף להליך משמעתי בלבד.', false, 'טענה זו שגויה. פעולה שבוצעה בחוסר סמכות מהותי עלולה לפגוע בתוקף המסמך, וגם המתמחה חשוף לאחריות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא תהיינה כל השלכות, שכן הפעולה בוצעה בתום לב ובאישור המאמן.', false, 'טענה זו שגויה. תום לב או אישור המאמן אינם מכשירים פעולה שבוצעה בחוסר סמכות סטטוטורית, ואינם מונעים השלכות משפטיות.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 38, '2023-S-S-Q38';
END
$$;

