-- classifier_note: Lawyer's duty when authenticating signatures + admissibility 5 years later — straddles ethics/disciplinary and evidence law
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '1d487f4f-ef40-403e-b4f5-1e1cea8b5365'::uuid;
  v_group_id uuid := 'fe545b5e-5f6b-48c3-80c4-da011d8d7b90'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '371fb76f-ee09-4a8c-a059-760cfb0a63fc'::uuid;
  v_ang_1 uuid := '81b0d804-329e-470b-aafb-86a9b4c7d915'::uuid;
  v_ang_2 uuid := '566b67f9-20ca-4e51-870a-af3c3b44106f'::uuid;
  v_ang_3 uuid := '3614b69a-35e8-4602-9f53-f644783b571b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2023-S-S-Q39';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 39, '2023-S-S-Q39';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'ethics';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'ethics';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'disciplinary_law' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'disciplinary_law', 'ethics';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q39', v_chapter_id, v_subtopic_id, 'במהלך עבודתו של עו"ד הלוי אימת האחרון חתימות שני ערבים על כתבי ערבות להסכם שכירות. בחלוף 5 שנים נפתח הליך משפטי בגין הפרת הסכם השכירות שבו נתבעו, בין היתר, שני הערבים האמורים. במסגרת ההליך המשפטי טען אחד הערבים כי לא חתם על כתב הערבות וכי עו"ד הלוי זייף את חתימתו. לנוכח טענה זו שהעלה הערב הוגשה תביעה גם נגד עו"ד הלוי. לצורכי הגנתו של עו"ד הלוי הוא מבקש לעשות שימוש בראיות שברשותו למען הוכחת הטענה כי הערב אכן חתם בפניו על כתב הערבות ולצורכי הפרכת גרסתו של הערב. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 39}'::jsonb, 'השאלה עוסקת בחיסיון עורך דין-לקוח, המעוגן בסעיף 48 לפקודת הראיות ובסעיף 90 לחוק לשכת עורכי הדין. היא בוחנת את החריג לחיסיון זה, המאפשר לעורך דין לגלות מידע חסוי לצורך הגנתו מפני תביעה שהוגשה נגדו על ידי הלקוח, תביעת רשלנות מקצועית, או הליכים משמעתיים. חריג זה נובע מהאיזון בין זכות הלקוח לחיסיון לבין זכותו של עורך הדין להגן על שמו הטוב וחופש עיסוקו.', 'חיסיון עורך דין-לקוח הוא חיסיון סטטוטורי מוחלט, שנועד להבטיח תקשורת פתוחה וגלויה בין עורך הדין ללקוחו, ובכך לאפשר ייצוג הולם והוגן. החיסיון הוא של הלקוח, ורק הוא רשאי לוותר עליו. עם זאת, הפסיקה הכירה בחריג חשוב לכלל זה: כאשר עורך הדין נתבע על ידי הלקוח (או נגדו ננקטים הליכים משמעתיים או פליליים), הוא רשאי לגלות מידע חסוי לצורך הגנתו. חריג זה חל במקרים של תביעת שכר טרחה, תביעת רשלנות מקצועית, או הליכים משמעתיים. הרציונל הוא שזכותו של עורך הדין להגן על עצמו גוברת על הערך המוגן העומד ביסוד החיסיון, וכי אין לאפשר ללקוח לנצל את החיסיון כדי לפגוע בעורך הדין שלו. במקרה הנדון, הערב טען שעו"ד הלוי זייף את חתימתו והוגשה תביעה נגד עו"ד הלוי. בנסיבות אלו, עו"ד הלוי רשאי להשתמש בראיות שברשותו לצורך הגנתו, שכן זכותו להגן על עצמו גוברת על החיסיון.', 'הטעות הנפוצה היא להתייחס לחיסיון עורך דין-לקוח כאל חיסיון מוחלט ובלתי ניתן להסרה בכל מצב, מבלי להכיר את החריגים המאפשרים לעורך הדין להגן על עצמו כאשר הוא נתבע על ידי הלקוח.',
    '["חיסיון עורך דין-לקוח", "פקודת הראיות סעיף 48", "חוק לשכת עורכי הדין סעיף 90", "חריגים לחיסיון", "הגנה עצמית של עורך דין", "אחריות מקצועית", "תביעת רשלנות"]'::jsonb, '**וריאציה 1 — חיסיון מוחלט:** האם חיסיון עו"ד-לקוח הוא מוחלט? ← כן, אך עם חריגים. ת"א (שלום ת"א) 14016-10-21 בומבך שיף- רואי חשבון ע"מ נ'' עו"ד ליאור פיק (26.03.2024)
**וריאציה 2 — חריג הגנה עצמית:** מתי עו"ד רשאי לגלות מידע חסוי? ← לצורך הגנתו מפני תביעת רשלנות, שכר טרחה או הליכים משמעתיים. ת"א (שלום ת"א) 14016-10-21 בומבך שיף- רואי חשבון ע"מ נ'' עו"ד ליאור פיק (26.03.2024)
**וריאציה 3 — רציונל החריג:** מה הרציונל לחריג זה? ← זכותו של עו"ד להגן על עצמו גוברת על הערך המוגן של החיסיון. ת"א (שלום ת"א) 14016-10-21 בומבך שיף- רואי חשבון ע"מ נ'' עו"ד ליאור פיק (26.03.2024)', 'חיסיון עו"ד-לקוח ← מוחלט אך עם חריגים ← עו"ד רשאי להגן על עצמו ← זכותו גוברת על החיסיון.', '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 48", "חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 90", "כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, כלל 19", "ת\"א (שלום ת\"א) 14016-10-21 בומבך שיף- רואי חשבון ע\"מ נ'' עו\"ד ליאור פיק (26.03.2024)", "רע\"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל (09.12.2015)", "על\"ע 5160/04 אילן אשד, עו\"ד נ'' הוועד המחוזי של לשכת עורכי-הדין בירושלים, נט(6) 223 (22.03.2005)", "יניב ואקי דיני ראיות כרך ג (2021) | ב. הסרת החיסיון לצורך הגנה על עורך הדין"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''דיני ראיות'' subtopic=''קבילות ראיות'' → mapped chapter=''ethics'' subtopic=''disciplinary_law'' | classifier_note: Lawyer''s duty when authenticating signatures + admissibility 5 years later — straddles ethics/disciplinary and evidence law', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עו"ד הלוי אינו רשאי להעלות טענות אלה ולהציג מסמכים שתומכים בכך היות שחל עליו חיסיון במסגרת יחסי עורך דין - לקוח אלא אם כן הלקוח (הערב) ויתר על חיסיון זה.', false, 'טענה זו שגויה. אף שהחיסיון הוא של הלקוח, במקרים בהם עורך הדין נתבע על ידי הלקוח או נגדו ננקטים הליכים, הוא רשאי להשתמש במידע חסוי לצורך הגנתו, ואין צורך בויתור מפורש של הלקוח.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עו"ד הלוי רשאי להעלות טענות כאמור ולתמוך זאת גם במסמכים היות שהטענות והמסמכים האמורים נדרשים לצורכי הגנתו במסגרת הליך משפטי.', true, 'החיסיון עורך דין-לקוח הוא חיסיון מוחלט, אך הפסיקה הכירה בחריג לפיו עורך דין רשאי לגלות מידע חסוי לצורך הגנתו מפני תביעה שהוגשה נגדו על ידי הלקוח, תביעת רשלנות מקצועית, או הליכים משמעתיים. במקרה זה, עו"ד הלוי נתבע על ידי הערב, ולכן זכותו להגן על עצמו גוברת על החיסיון.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עו"ד הלוי אינו רשאי להעלות טענות אלה ולהציג מסמכים שתומכים בכך היות שחל עליו חיסיון במסגרת יחסי עורך דין - לקוח, גם אם הלקוח (הערב) ויתר עליו.', false, 'טענה זו שגויה. החיסיון הוא של הלקוח, והלקוח רשאי לוותר עליו. בנוסף, קיים חריג המאפשר לעורך הדין להגן על עצמו גם ללא ויתור הלקוח.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עו"ד הלוי רשאי להעלות טענות כאמור ולתמוך זאת גם במסמכים היות שהטענות והמסמכים האמורים נדרשים לצורכי הגנתו במסגרת הליך משפטי, ובלבד שהוגשה נגדו גם תלונה למשטרה בגין זיוף מסמך.', false, 'טענה זו שגויה. החריג המאפשר לעורך הדין להגן על עצמו אינו מותנה בהגשת תלונה למשטרה, אלא בתביעה או הליך משפטי נגדו, כפי שאירע במקרה זה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חיסיון עורך דין-לקוח על זהות הלקוח',
    1, 'עורך דין נדרש לחשוף את זהותו של לקוח שפנה אליו בבקשה לייעוץ משפטי בנוגע לעבירה שביצע, אך ביקש להישאר אנונימי בשלב זה. האם זהותו של הלקוח חסויה?', 'שאלה זו עוסקת בהיקף תחולתו של חיסיון עורך דין-לקוח על זהות הלקוח. היא בוחנת את הכלל לפיו זהות הלקוח אינה חסויה, ואת החריגים לכלל זה, במיוחד כאשר חשיפת הזהות עלולה לפגוע בלב החיסיון או לחשוף את תוכן ההתקשרות המקצועית.', 'ככלל, חיסיון עורך דין-לקוח אינו חל על זהותו של הלקוח. סעיף 48(א) לפקודת הראיות וסעיף 90 לחוק לשכת עורכי הדין מתייחסים ל''דברים ומסמכים'' שהוחלפו. עם זאת, הפסיקה הכירה בכך שכלל זה ''אינו הרמטי''. במקרים חריגים, כאשר זהותו של הלקוח עשויה לחשוף את תוכן ההתקשרות בין עורך הדין ללקוח, או להעמידו במצב ממנו ביקש להימנע באמצעות השימוש בחיסיון, ייתכן כי החיסיון יורחב גם על זהות הלקוח. דוגמה לכך היא מצב שבו עורך דין פונה בשם לקוח המבקש להסגיר את עצמו ולהתוודות על פשע, אך מבקש שלא להזדהות בשלב זה. חשיפת זהותו של הלקוח במקרה כזה פוגעת בלב החיסיון של עורך דין-לקוח.',
    'הטעות הנפוצה היא להניח שזהות הלקוח חסויה תמיד, או לחלופין, שאינה חסויה לעולם, מבלי להכיר את הכלל ואת החריגים המצומצמים לו.', '["חיסיון עורך דין-לקוח", "זהות הלקוח", "פקודת הראיות סעיף 48", "חוק לשכת עורכי הדין סעיף 90", "חריגים לחיסיון", "לב החיסיון"]'::jsonb, '**וריאציה 1 — הכלל:** האם חיסיון עו"ד-לקוח חל על זהות הלקוח? ← ככלל, לא. ע"א 7876/17 הכונסת הרשמית נ'' עו"ד שאול קוטלר, נאמן לנכסי החייב (18.02.2018)
**וריאציה 2 — החריג:** מתי החיסיון יחול על זהות הלקוח? ← כאשר חשיפת הזהות תפגע בלב החיסיון או תחשוף את תוכן ההתקשרות. יניב ואקי דיני ראיות כרך ג (2021) | ב. חיסיון על זהות הלקוח
**וריאציה 3 — דוגמה לחריג:** מהי דוגמה למקרה בו זהות הלקוח חסויה? ← לקוח המבקש להסגיר עצמו ולהתוודות על פשע, אך מבקש שלא להזדהות בשלב זה. יניב ואקי דיני ראיות כרך ג (2021) | ב. חיסיון על זהות הלקוח', 'זהות לקוח ← ככלל לא חסויה ← חריג: אם פוגע בלב החיסיון.',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 48(א)", "חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 90", "ע\"א 7876/17 הכונסת הרשמית נ'' עו\"ד שאול קוטלר, נאמן לנכסי החייב (18.02.2018)", "ע\"א 5739/18 מפעילי האתר www.oligarchescorts.com נ'' מדינת ישראל (15.10.2018)", "יניב ואקי דיני ראיות כרך ג (2021) | ב. חיסיון על זהות הלקוח"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'ככלל, זהות הלקוח אינה חסויה, אלא אם חשיפתה תפגע בלב החיסיון של עורך דין-לקוח.', true, 'הכלל הוא שחיסיון עורך דין-לקוח אינו חל על זהות הלקוח. עם זאת, הפסיקה הכירה בחריג לפיו במקרים חריגים, כאשר חשיפת זהות הלקוח עלולה לחשוף את תוכן ההתקשרות או לפגוע בלב החיסיון, ניתן להרחיב את החיסיון גם על זהות הלקוח.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'זהות הלקוח חסויה באופן מוחלט, שכן היא חלק בלתי נפרד מיחסי עורך דין-לקוח.', false, 'טענה זו שגויה. הגישה המקובלת היא שזהות הלקוח אינה חסויה ככלל, אלא אם מתקיים חריג ספציפי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'זהות הלקוח אינה חסויה, שכן החיסיון חל רק על ''דברים ומסמכים'' שהוחלפו, ולא על פרטים מזהים.', false, 'טענה זו שגויה חלקית. אף שהחיסיון חל על ''דברים ומסמכים'', הפסיקה הכירה באפשרות להרחיב את החיסיון גם לזהות הלקוח במקרים חריגים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'זהות הלקוח חסויה רק אם עורך הדין קיבל אישור מיוחד מבית המשפט לחסותה.', false, 'טענה זו שגויה. החריג לתחולת החיסיון על זהות הלקוח אינו מותנה באישור מיוחד מבית המשפט, אלא מתקיים מכוח נסיבות העניין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאים מצטברים לתחולת חיסיון עו"ד-לקוח',
    2, 'מהם התנאים המצטברים הנדרשים לתחולת חיסיון עורך דין-לקוח על פי פקודת הראיות וחוק לשכת עורכי הדין?', 'שאלה זו מתמקדת בתנאים המהותיים לתחולת חיסיון עורך דין-לקוח, כפי שהם מעוגנים בפקודת הראיות ובחוק לשכת עורכי הדין. היא מדגישה את הצורך בקשר ענייני לשירות המקצועי ואת סוג המידע המוגן (דברים ומסמכים).', 'חיסיון עורך דין-לקוח הוא חיסיון סטטוטורי המעוגן בסעיף 48 לפקודת הראיות [נוסח חדש], תשל"א-1971, ובסעיף 90 לחוק לשכת עורכי הדין, תשכ"א-1961. שני הסעיפים קובעים שני תנאים מצטברים לתחולת החיסיון: ראשית, שיהיו אלה ''דברים ומסמכים'' שהוחלפו בין עורך דין לבין לקוחו (או אדם אחר מטעמו). שנית, שלדברים ולמסמכים אלה יהיה ''קשר ענייני לשירות המקצועי'' שניתן על ידי עורך הדין ללקוח. רק בהתקיים שני תנאים אלו יחול החיסיון, ויאסר על עורך הדין למסור את המידע כראיה או לגלותו בכל הליך משפטי, חקירה או חיפוש, אלא אם הלקוח ויתר על החיסיון.',
    'הטעות היא להניח שהחיסיון חל על כל תקשורת בין עורך דין ללקוח, מבלי לבחון את הקשר הענייני לשירות המקצועי ואת סוג המידע.', '["חיסיון עורך דין-לקוח", "פקודת הראיות סעיף 48", "חוק לשכת עורכי הדין סעיף 90", "דברים ומסמכים", "קשר ענייני לשירות מקצועי", "תנאים מצטברים"]'::jsonb, '**וריאציה 1 — תנאי 1:** מהו התנאי הראשון לתחולת החיסיון? ← ''דברים ומסמכים'' שהוחלפו בין עו"ד ללקוח. סעיף 48(א) לפקודת הראיות [נוסח חדש], תשל"א-1971
**וריאציה 2 — תנאי 2:** מהו התנאי השני לתחולת החיסיון? ← קשר ענייני לשירות המקצועי. סעיף 48(א) לפקודת הראיות [נוסח חדש], תשל"א-1971
**וריאציה 3 — חובת הסודיות האתית:** האם חובת הסודיות האתית רחבה יותר? ← כן, היא חלה על כל דבר שהובא לידיעת עו"ד, גם ללא קשר ענייני לשירות המקצועי. כלל 19 לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986', 'חיסיון עו"ד-לקוח ← דברים ומסמכים + קשר ענייני לשירות מקצועי.',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 48(א)", "חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 90", "כללי לשכת עורכי הדין (אתיקה מקצועית), התשמ\"ו-1986, כלל 19", "ת\"א (מחוזי ת\"א) 57625-01-13 פלוני קטין ואח'' נ'' בית חולים ביקור חולים (06.04.2016)", "יניב ואקי דיני ראיות כרך ג (2021) | א. חיסיון עורך דין-לקוח, מהו?"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'החיסיון חל על כל מידע שהועבר בין עורך דין ללקוחו, ללא קשר לטיב המידע או למטרתו.', false, 'טענה זו שגויה. החיסיון אינו חל באופן גורף על כל מידע, אלא רק על מידע בעל קשר ענייני לשירות המקצועי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'החיסיון חל על ''דברים ומסמכים'' שהוחלפו בין עורך דין ללקוחו, ושיש להם קשר ענייני לשירות המקצועי שניתן על ידי עורך הדין ללקוח.', true, 'סעיף 48(א) לפקודת הראיות וסעיף 90 לחוק לשכת עורכי הדין קובעים במפורש שני תנאים מצטברים לתחולת החיסיון: האחד, שהמידע יהיה בגדר ''דברים ומסמכים'' שהוחלפו בין עורך דין ללקוחו (או מי מטעמו); והשני, שלמידע זה יהיה ''קשר ענייני לשירות המקצועי'' שניתן על ידי עורך הדין ללקוח.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'החיסיון חל רק אם המידע הועבר בכתב, ולא בעל פה.', false, 'טענה זו שגויה. החיסיון חל גם על ''דברים'' (מידע בעל פה) שהוחלפו בין עורך דין ללקוחו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'החיסיון חל רק אם המידע נוגע להליך משפטי תלוי ועומד, ולא לייעוץ כללי.', false, 'טענה זו שגויה. החיסיון חל על ''שירות מקצועי'' באופן כללי, הכולל גם ייעוץ משפטי שאינו קשור בהכרח להליך משפטי ספציפי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חיסיון על מידע הנוגע לביצוע עבירה',
    3, 'לקוח פנה לעורך דין וביקש ייעוץ משפטי בנוגע לתוכניתו לבצע עבירה פלילית בעתיד. האם המידע שמסר הלקוח לעורך הדין חוסה תחת חיסיון עורך דין-לקוח?', 'שאלה זו עוסקת בחריג חשוב לתחולת חיסיון עורך דין-לקוח, הנוגע למידע שמסר לקוח לעורך דינו בקשר לביצוע עבירה עתידית. היא מדגישה כי החיסיון נועד להגן על שירות מקצועי לגיטימי, ולא לשמש מגן לפעילות עבריינית.', 'החיסיון עורך דין-לקוח נועד להבטיח תקשורת פתוחה וחופשית בין עורך דין ללקוחו לצורך קבלת שירות משפטי הולם והוגן. עם זאת, הפסיקה קבעה כי חיסיון זה אינו חל כאשר הלקוח מודיע לעורך הדין על כוונתו לבצע עבירה פלילית בעתיד, או כאשר הוא מבקש לשתף את עורך הדין עצמו בביצוע העבירה. במקרים אלו, אין מדובר במידע בעל קשר ענייני לשירות המקצועי הלגיטימי, ולכן אין תחולה לחיסיון. הרציונל הוא שהחיסיון אינו יכול לשמש מגן לביצוע עבירות עתידיות, וכי משרדו של עורך הדין אינו יכול להפוך ל''בית מחסה לפעילויות עברייניות''.',
    'הטעות היא להניח שהחיסיון הוא מוחלט בכל מצב, מבלי להכיר את החריג החשוב הנוגע לייעוץ לביצוע עבירה עתידית.', '["חיסיון עורך דין-לקוח", "ביצוע עבירה עתידית", "חריגים לחיסיון", "שירות מקצועי לגיטימי", "קשר ענייני"]'::jsonb, '**וריאציה 1 — חריג לחיסיון:** מתי חיסיון עו"ד-לקוח אינו חל? ← כאשר הלקוח מיידע את עו"ד על כוונתו לבצע עבירה בעתיד. רע"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל (09.12.2015)
**וריאציה 2 — רציונל החריג:** מה הרציונל מאחורי חריג זה? ← אין מדובר במידע בעל קשר ענייני לשירות המקצועי הלגיטימי. רע"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל (09.12.2015)
**וריאציה 3 — משרד עו"ד כבית מחסה:** האם משרד עו"ד יכול לשמש בית מחסה לפעילות עבריינית? ← לא, קיים חשש שאם יורחב החיסיון, משרד עו"ד יהפוך לבית מחסה לפעילויות עברייניות. יניב ואקי דיני ראיות כרך ג (2021) | ג. חיסיון על שכר הטרחה ועל חשבוניות מס', 'ייעוץ לביצוע עבירה עתידית ← לא חסוי ← אין קשר לשירות מקצועי לגיטימי.',
    '["רע\"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל (09.12.2015)", "על\"ע 17/86 פלונית נ'' לשכת עורכי הדין, פ\"ד מא(4) 770 (14.12.1987)", "יניב ואקי דיני ראיות כרך ג (2021) | ג. חיסיון על שכר הטרחה ועל חשבוניות מס"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, כל מידע שנמסר לעורך דין במסגרת יחסי עורך דין-לקוח חסוי באופן מוחלט.', false, 'טענה זו שגויה. החיסיון אינו חל על מידע שאינו קשור לשירות מקצועי לגיטימי, כגון ייעוץ לביצוע עבירה עתידית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, מידע הנוגע לכוונת הלקוח לבצע עבירה פלילית בעתיד אינו חסוי, שכן אין לו קשר ענייני לשירות המקצועי הלגיטימי.', true, 'הפסיקה קבעה כי חיסיון עורך דין-לקוח אינו חל כאשר הלקוח מודיע לעורך הדין על כוונתו לבצע עבירה פלילית בעתיד, או כאשר הוא מבקש לשתף את עורך הדין בביצוע העבירה. במקרים אלו, אין מדובר במידע בעל קשר ענייני לשירות המקצועי הלגיטימי, ולכן אין תחולה לחיסיון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן עורך הדין קיבל אישור מבית המשפט להסיר את החיסיון.', false, 'טענה זו שגויה. במקרים אלו, החיסיון אינו חל מלכתחילה, ואין צורך בהסרה על ידי בית המשפט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אך רק אם עורך הדין דיווח על כך לרשויות החוק.', false, 'טענה זו שגויה. אי הדיווח לרשויות אינו הופך את המידע לחסוי. המידע אינו חסוי מלכתחילה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'ויתור על חיסיון עורך דין-לקוח',
    4, 'לקוח מעוניין לוותר על חיסיון עורך דין-לקוח החל על מסמכים מסוימים. כיצד יכול הלקוח לוותר על החיסיון, והאם עורך הדין רשאי לוותר עליו במקומו?', 'שאלה זו עוסקת בזהות בעל החיסיון עורך דין-לקוח ובאופן שבו ניתן לוותר עליו. היא מדגישה כי החיסיון הוא זכותו של הלקוח בלבד, ורק הוא רשאי לוותר עליו, במפורש או במשתמע, וכי עורך הדין אינו רשאי לעשות זאת במקומו.', 'החיסיון עורך דין-לקוח הוא חיסיון של הלקוח, ולא של עורך הדין. עובדה זו עולה במפורש מהוראות סעיף 48 לפקודת הראיות וסעיף 90 לחוק לשכת עורכי הדין, הקובעים כי עורך הדין אינו חייב למסור מידע חסוי ''אלא אם ויתר הלקוח על החיסיון''. לכן, רק הלקוח רשאי לוותר על החיסיון. ויתור זה יכול להיות מפורש (למשל, בהצהרה בכתב או בעל פה) או משתמע (למשל, כאשר הלקוח מעביר את המסמך או המידע לצד שלישי בידיעתו ובהסכמתו, ובלבד שהצד השלישי אינו איש אמון או שנוכחותו אינה חיונית לייעוץ המשפטי). עורך הדין, לעומת זאת, מנוע מלגלות את תוכן ההתקשרות בינו לבין לקוחו אם הלקוח לא ויתר על החיסיון, והפרה של חובה זו עלולה לגרור אחריות משמעתית ואף אזרחית.',
    'הטעות היא לחשוב שעורך הדין יכול לוותר על החיסיון, או לבלבל בין ויתור על חיסיון לבין מקרים בהם החיסיון אינו חל מלכתחילה (כמו הגנת עורך הדין על עצמו).', '["חיסיון עורך דין-לקוח", "בעל החיסיון", "ויתור על חיסיון", "ויתור מפורש", "ויתור משתמע", "אחריות עורך דין"]'::jsonb, '**וריאציה 1 — בעל החיסיון:** מי הוא בעל החיסיון? ← הלקוח בלבד. יניב ואקי דיני ראיות כרך ג (2021) | ג. מיהו בעל החיסיון?
**וריאציה 2 — ויתור:** כיצד ניתן לוותר על החיסיון? ← במפורש או במשתמע. רע"א 6171/17 פלוני נ'' קופת חולים מאוחדת (04.09.2017)
**וריאציה 3 — אחריות עו"ד:** מה קורה אם עו"ד מגלה מידע ללא ויתור? ← עובר עבירה משמעתית וחשוף לתביעת רשלנות. יניב ואקי דיני ראיות כרך ג (2021) | ג. מיהו בעל החיסיון?', 'חיסיון ← של הלקוח בלבד ← ויתור מפורש/משתמע ← עו"ד אינו רשאי לוותר.',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 48", "חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 90", "רע\"א 6171/17 פלוני נ'' קופת חולים מאוחדת (04.09.2017)", "יניב ואקי דיני ראיות כרך ג (2021) | ג. מיהו בעל החיסיון?"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'רק הלקוח רשאי לוותר על החיסיון, במפורש או במשתמע, ועורך הדין אינו רשאי לוותר עליו.', true, 'החיסיון עורך דין-לקוח הוא חיסיון של הלקוח בלבד, ולכן רק הלקוח רשאי לוותר עליו. ויתור זה יכול להיות מפורש או משתמע, למשל על ידי מסירת המידע לצד שלישי בידיעתו ובהסכמתו. עורך הדין אינו בעל החיסיון ואינו רשאי לוותר עליו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'עורך הדין רשאי לוותר על החיסיון במקום הלקוח, אם הדבר נחוץ לצורך הגנתו של עורך הדין.', false, 'טענה זו שגויה. במקרים בהם עורך הדין נדרש להגן על עצמו, החיסיון אינו חל מלכתחילה, אך עורך הדין אינו ''מוותר'' על חיסיון של הלקוח.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'הלקוח יכול לוותר על החיסיון רק בכתב ובאישור בית המשפט.', false, 'טענה זו שגויה. ויתור על חיסיון אינו דורש בהכרח אישור בית משפט, והוא יכול להיות גם משתמע.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'החיסיון הוא מוחלט ואינו ניתן לויתור על ידי הלקוח או עורך הדין.', false, 'טענה זו שגויה. אף שהחיסיון מוחלט במובן שבית המשפט אינו יכול להסירו, הלקוח בהחלט רשאי לוותר עליו.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 39, '2023-S-S-Q39';
END
$$;

