  v_ang_1 uuid := '8d2a672c-cfe3-4fd2-bed9-feb5962b748e'::uuid;
  v_ang_2 uuid := '93e80f8c-a84d-41f6-b663-8a908d2e8d35'::uuid;
  v_ang_3 uuid := '1a48d85f-987d-4f4f-9f5e-fe329341eaf1'::uuid;
BEGIN
