  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2023-S-S-Q40', v_chapter_id, v_subtopic_id, 'עו"ד משעלי החליט לשלוח בדיוור ישיר למאות עמותות בישראל ניוזלטר על משרדו והשירותים המשפטיים שהוא מעניק לעמותות בישראל וללא אזכור תעריפי שכר הטרחה שהוא גובה בגין שירותים אלה. את רשימת העמותות שלף ממאגר העמותות הישראלי, ועל פיה יצר רשימת תפוצה פנימית של המשרד. כמה עמותות שקיבלו פרסום זה זעמו על כך שהן מוצפות בהודעות ובפרסומים שלא ביקשו ואינן חפצות בהם, ולפיכך הגישו בגין כך תלונה לוועדת האתיקה נגד עו"ד משעלי. מה הדין?',
    '{"exam_year": 2023, "exam_season": "summer", "exam_part": 2, "exam_question_number": 40}'::jsonb, 'השאלה עוסקת בסמכויותיו של מתמחה בעריכת דין, ובפרט באיסור עליו לבצע פעולות השמורות לעורך דין מוסמך, כגון אימות חתימה על ייפוי כוח. היא בוחנת את תחולת סעיפים 20 ו-41 לחוק לשכת עורכי הדין, התשכ"א-1961, ומדגישה כי לא ניתן להתגבר על איסורים אלו באמצעות אישור המאמן או דחיפות העניין.', 'חוק לשכת עורכי הדין, התשכ"א-1961, קובע את סמכויות המתמחה. סעיף 20(א) מפרט את הפעולות שמותר למתמחה לבצע, ואימות חתימה על ייפוי כוח אינו נכלל ברשימה זו. יתרה מכך, סעיף 41 לחוק קובע איסור מוחלט על מי שאינו עורך דין לעסוק בעריכת דין. אימות חתימה על ייפוי כוח נחשב ''עיסוק בעריכת דין'' במובנו הרחב, שכן הוא מהווה פעולה משפטית פורמלית המטילה אחריות מקצועית. לכן, מתמחה, שאינו עורך דין מוסמך, אינו רשאי לבצע פעולה זו. אישור המאמן או דחיפות העניין אינם יכולים להכשיר פעולה האסורה על פי חוק. המאמן, עו"ד ורדי, אף הוא עלול לשאת באחריות משמעתית בגין מתן אישור למתמחה לבצע פעולה שאינו מוסמך לה.', 'הטעות הנפוצה היא לחשוב שאישור המאמן או דחיפות העניין יכולים להכשיר פעולות האסורות על מתמחה על פי חוק, או לבלבל בין סמכויות המתמחה לייצג בבתי משפט מסוימים לבין פעולות אחרות השמורות לעורך דין מוסמך.',
    '["מתמחה", "חוק לשכת עורכי הדין סעיף 20", "חוק לשכת עורכי הדין סעיף 41", "אימות חתימה", "ייפוי כוח", "עיסוק בעריכת דין", "אחריות מקצועית"]'::jsonb, '**וריאציה 1 — סמכות מתמחה:** האם מתמחה רשאי לאמת חתימה על ייפוי כוח? ← לא, זו פעולה השמורה לעורך דין מוסמך. סעיף 20(א) לחוק לשכת עורכי הדין, התשכ"א-1961
**וריאציה 2 — איסור עיסוק בעריכת דין:** מדוע אסור למתמחה לאמת חתימה? ← אימות חתימה הוא ''עיסוק בעריכת דין'' האסור על מי שאינו עו"ד. סעיף 41 לחוק לשכת עורכי הדין, התשכ"א-1961
**וריאציה 3 — אישור מאמן ודחיפות:** האם אישור מאמן או דחיפות מכשירים את הפעולה? ← לא, חוק לשכת עורכי הדין קובע איסור מוחלט. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה', 'מתמחה ← אינו עו"ד מוסמך ← אינו רשאי לאמת חתימה ← גם לא באישור או דחיפות.', '["חוק לשכת עורכי הדין, התשכ\"א-1961, סעיפים 20, 41", "כללי לשכת עורכי הדין (פרסומת), התשס\"א-2001, כלל 3(יג)", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''fees_client_funds_advertising'' | classifier_note: Lawyer direct-mail / newsletter advertising rules | source_review_note: הסיווג לתת-נושא ''משמעת עורכי דין'' אינו מדויק, שכן השאלה עוסקת בעיקר בכללי פרסומת ושידול. יש לשקול הוספת תת-נושא מתאים יותר ל''אתיקה מקצועית'' או ''פרסומת עורכי דין'' תחת פרק רחב יותר של ''דיני לשכת עורכי הדין''.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עו"ד משעלי לא עבר עבירה אתית בהתנהלותו המתוארת היות שהפיץ פרסום לעמותות הממוקד בפעילות משפטית שרלוונטית לעמותות.', false, 'טענה זו שגויה. אף שהפרסום ממוקד, עצם שליחתו ללא בקשה מוקדמת מהווה שידול אסור, ללא קשר לתוכן או לרלוונטיות.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עו"ד משעלי עבר עבירה אתית בהתנהלותו המתוארת, רק בשל שליפת המידע על העמותות ממאגר העמותות בישראל.', false, 'טענה זו שגויה. שליפת המידע ממאגר ציבורי אינה העבירה האתית העיקרית, אלא השימוש במידע זה לשליחת פרסום לא מבוקש.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עו"ד משעלי לא עבר עבירה אתית כלשהי היות שאין מניעה להפיץ פרסום כאמור כל זמן שלא מצוינים תעריפי שכר טרחה במסגרת הפרסום.', false, 'טענה זו שגויה. איסור השידול חל גם אם לא מצוינים תעריפי שכר טרחה, והוא מתייחס לעצם הפנייה היזומה והלא מבוקשת.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עו"ד משעלי עבר עבירה אתית היות שאותן העמותות אינן נמנות בלקוחות משרדו והן גם לא ביקשו לקבל מידע או פרסום כאמור.', true, 'סעיף 56 לחוק לשכת עורכי הדין אוסר על שידול לשם השגת עבודה. כלל 3(יג) לכללי לשכת עורכי הדין (פרסומת) מתיר שליחת ניוזלטר רק לרשימת תפוצה של לקוחות המשרד שביקשו זאת, או של אחרים שביקשו זאת. שליחת ניוזלטר לעמותות שלא ביקשו זאת, גם אם רשימתן נשלפה ממאגר ציבורי, מהווה שידול אסור.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פרסומת מותרת באתר אינטרנט',
    1, 'עו"ד כהן פרסם באתר האינטרנט של משרדו תמונות שבהן הוא מופיע עם לקוחותיו, לאחר שקיבל מהם הצהרה בכתב כי הבינו שהם חופשיים לסרב לכך וכי מתן שירותיו לא הותנה בפרסום שמם. בנוסף, הוסיף עו"ד כהן קישור לאתר אינטרנט של חברה מסחרית שאינה עוסקת בתחום המשפט. האם פעולותיו של עו"ד כהן מותרות על פי כללי לשכת עורכי הדין (פרסומת)?', 'שאלה זו בוחנת את כללי הפרסומת הספציפיים החלים על עורכי דין באתרי אינטרנט, ובפרט את התנאים לפרסום תמונות לקוחות ואת המגבלות על הוספת קישורים לאתרים חיצוניים. היא מדגישה את האיזון בין חופש הפרסום לבין שמירה על כבוד המקצוע.', 'כלל 3(ה) לכללי לשכת עורכי הדין (פרסומת), התשס"א-2001, קובע כי עורך דין רשאי לפרסם תמונות שבהן הוא מופיע עם לקוחותיו, ובלבד שאלו הצהירו בכתב כי הבינו שהם חופשיים לסרב לכך וכי מתן שירותיו של עורך הדין לא הותנה בפרסום שמם, וכל עוד ההסכמה תקפה. במקרה זה, עו"ד כהן עמד בתנאים אלו, ולכן פרסום תמונות הלקוחות מותר. לעומת זאת, כלל 3(ו) לכללים אלו קובע כי עורך דין רשאי להוסיף באתר האינטרנט שלו קישור (link) לאתר אינטרנט אחר, ובלבד שהקישור נוגע באופן ישיר לעיסוקו המקצועי של עורך הדין. קישור לאתר של חברה מסחרית שאינה עוסקת בתחום המשפט אינו עונה על דרישה זו, ולכן הוא אסור.',
    'הטעות היא להניח שכל פרסום באתר אינטרנט מותר, או שכל קישור מותר, מבלי לבחון את התנאים הספציפיים הקבועים בכללי הפרסומת.', '["פרסומת מותרת", "כללי לשכת עורכי הדין (פרסומת)", "אתר אינטרנט", "פרסום תמונות לקוחות", "קישורים לאתרים אחרים", "כבוד המקצוע"]'::jsonb, '**וריאציה 1 — פרסום תמונות לקוחות:** מתי מותר לפרסם תמונות עם לקוחות? ← בהסכמה בכתב ובתנאים מסוימים. כלל 3(ה) לכללי לשכת עורכי הדין (פרסומת), התשס"א-2001
**וריאציה 2 — קישורים באתר:** אילו קישורים מותר להוסיף לאתר עו"ד? ← רק קישורים הנוגעים באופן ישיר לעיסוקו המקצועי. כלל 3(ו) לכללי לשכת עורכי הדין (פרסומת), התשס"א-2001
**וריאציה 3 — פרסומת של אחרים:** האם מותר לכלול פרסומות של אחרים באתר עו"ד? ← לא, אתר אינטרנט של עורך דין לא יכלול פרסומות של אחרים. כלל 3(ח) לכללי לשכת עורכי הדין (פרסומת), התשס"א-2001', 'פרסום תמונות לקוחות ← מותר בהסכמה. קישור לאתר אחר ← רק אם קשור מקצועית.',
    '["כללי לשכת עורכי הדין (פרסומת), התשס\"א-2001, כללים 3(ה), 3(ו), 3(ח)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'שתי הפעולות מותרות, שכן הן עומדות בכללי הפרסומת.', false, 'טענה זו שגויה. אף שפרסום תמונות לקוחות מותר בתנאים מסוימים, קישור לאתר שאינו משפטי אסור.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'פרסום תמונות הלקוחות מותר, אך הוספת קישור לאתר חברה מסחרית שאינה משפטית אסורה.', true, 'כלל 3(ה) לכללי לשכת עורכי הדין (פרסומת) מתיר פרסום תמונות עם לקוחות בהסכמה בכתב ובתנאים מסוימים. לעומת זאת, כלל 3(ו) מתיר הוספת קישור לאתר אינטרנט אחר רק אם הקישור נוגע באופן ישיר לעיסוקו המקצועי של עורך הדין, ולכן קישור לאתר חברה מסחרית שאינה משפטית אסור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'פרסום תמונות הלקוחות אסור, אך הוספת קישור לאתר חברה מסחרית מותרת.', false, 'טענה זו שגויה. פרסום תמונות לקוחות מותר בתנאים שצוינו, ואילו קישור לאתר שאינו משפטי אסור.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'שתי הפעולות אסורות, שכן הן פוגעות בכבוד המקצוע.', false, 'טענה זו שגויה. פרסום תמונות לקוחות בהסכמה אינו פוגע בכבוד המקצוע, אך קישור לאתר שאינו משפטי אסור.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגדרת שידול אסור',
    2, 'מהם המאפיינים העיקריים של ''שידול אסור'' על פי חוק לשכת עורכי הדין וכללי האתיקה?', 'שאלה זו מתמקדת בהגדרת ''שידול אסור'' על פי חוק לשכת עורכי הדין וכללי האתיקה. היא בוחנת את המאפיינים המרכזיים של פעולה זו, הכוללים פנייה יזומה, כוונה להשגת עבודה, ואת האפשרות שהפנייה תהיה במישרין או בעקיפין.', 'סעיף 56 לחוק לשכת עורכי הדין, התשכ"א-1961, קובע במפורש: ''לא ישדל עורך דין, בעצמו או על ידי אחר, כל אדם למסור לידיו עבודה מקצועית''. הגדרת ה''שידול'' בספרות המקצועית ובפסיקה היא רחבה וכוללת כל פנייה יזומה של עורך הדין או מי מטעמו ללקוח פוטנציאלי, במישרין או בעקיפין, מתוך כוונה שזה ימסור לידיו עבודה. המטרה היא למנוע לחץ בלתי הוגן על לקוחות פוטנציאליים ולשמור על כבוד המקצוע. דוגמאות לשידול אסור כוללות חלוקת כרטיסי ביקור יזומה, גיוס כספים למימון שכר טרחה, או פנייה לא מבוקשת באמצעות דיוור ישיר.',
    'הטעות היא לצמצם את הגדרת השידול רק לפעולות מסוימות, או להתעלם מיסוד הפנייה ה''יזומה'' וה''לא מבוקשת''.', '["שידול אסור", "חוק לשכת עורכי הדין סעיף 56", "אתיקה מקצועית", "פנייה יזומה", "השגת עבודה", "כבוד המקצוע"]'::jsonb, '**וריאציה 1 — הגדרת שידול:** מהו שידול אסור? ← פנייה יזומה ללקוח פוטנציאלי מתוך כוונה שימסור עבודה. סעיף 56 לחוק לשכת עורכי הדין, התשכ"א-1961
**וריאציה 2 — דוגמאות לשידול:** אילו פעולות נחשבות שידול? ← חלוקת כרטיסי ביקור יזומה, גיוס המונים לשכר טרחה, פנייה לא מבוקשת. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה
**וריאציה 3 — רציונל האיסור:** מהי מטרת איסור השידול? ← למנוע לחץ בלתי הוגן ולשמור על כבוד המקצוע. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה', 'שידול אסור ← פנייה יזומה + כוונה להשגת עבודה ← במישרין/עקיפין.',
    '["חוק לשכת עורכי הדין, התשכ\"א-1961, סעיף 56", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כל פנייה של עורך דין ללקוח פוטנציאלי, גם אם היא מבוקשת, נחשבת שידול אסור.', false, 'טענה זו שגויה. שידול אסור מתייחס לפניה יזומה ולא מבוקשת, ולא לכל פניה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'פנייה יזומה של עורך הדין או מי מטעמו ללקוח פוטנציאלי, במישרין או בעקיפין, מתוך כוונה שימסור לידיו עבודה.', true, 'הגדרה זו משקפת את מהות השידול האסור כפי שנקבע בסעיף 56 לחוק לשכת עורכי הדין וכפי שפורש בספרות המקצועית. היא כוללת את יסוד הפנייה היזומה, את מטרת השגת העבודה ואת האפשרות שהפנייה תהיה עקיפה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'רק פנייה הכוללת הבטחה להנחה בשכר טרחה נחשבת שידול אסור.', false, 'טענה זו שגויה. הבטחה להנחה היא אסורה בפני עצמה, אך שידול יכול להתקיים גם ללא אזכור שכר טרחה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'רק פנייה המבוצעת באופן פיזי (כגון חלוקת כרטיסי ביקור) נחשבת שידול אסור.', false, 'טענה זו שגויה. שידול יכול להתבצע גם באמצעים אלקטרוניים, כגון דיוור ישיר או פרסום ברשתות חברתיות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פרסום תפקידים בלשכה',
    3, 'עו"ד לוי פרסם מודעה בעיתון ובה ציין את שמו, תחומי עיסוקו, וכן את העובדה שהוא יו"ר ועדה בלשכת עורכי הדין. האם פרסום זה מותר על פי כללי לשכת עורכי הדין (פרסומת)?', 'שאלה זו בוחנת את הכללים הנוגעים לפרסום תפקידים וחברות בלשכת עורכי הדין במסגרת פרסומת. היא מדגישה את השינויים בכללי הפרסומת לאורך השנים ואת ההיתר הקיים כיום לכלול מידע זה, בכפוף לעמידה ביתר דרישות הכללים.', 'על פי כלל 3(ב)(17) לכללי לשכת עורכי הדין (פרסומת), התשס"א-2001, כפי שתוקנו בשנת תשע"ח-2018, מותר לכלול בפרסומת ''תפקידים וחברות בלשכת עורכי הדין או בארגונים משפטיים בארץ או בחוץ לארץ''. הוראה זו מאפשרת לעורך דין לציין את היותו יו"ר ועדה בלשכה. יש לציין כי בעבר, כלל 3(ג)(3) (בנוסחו הקודם) הגביל את ציון התפקידים הללו במודעות בעיתון, אך נוסח הכללים העדכני מאפשר זאת. כמובן, הפרסומת כולה צריכה לעמוד ביתר תנאי הכללים, כגון מגבלות על גודל המודעה, איסור על תוכן מטעה או פוגע בכבוד המקצוע.',
    'הטעות היא להסתמך על נוסחים קודמים של כללי הפרסומת, או לבלבל בין סוגי המידע השונים המותרים לפרסום באמצעי פרסום שונים.', '["פרסומת מותרת", "כללי לשכת עורכי הדין (פרסומת)", "תפקידים בלשכה", "כבוד המקצוע", "שינויים בחקיקה"]'::jsonb, '**וריאציה 1 — פרסום תפקידים בלשכה:** האם מותר לציין תפקידים בלשכה בפרסומת? ← כן, על פי כלל 3(ב)(17) לכללי הפרסומת. כלל 3(ב)(17) לכללי לשכת עורכי הדין (פרסומת), התשס"א-2001
**וריאציה 2 — מגבלות על פרסום תפקידים:** האם יש מגבלות על פרסום תפקידים? ← כן, למעט תפקיד שיפוטי או מעין שיפוטי שהוא ממלא על פי דין. כלל 3(ב)(18) לכללי לשכת עורכי הדין (פרסומת), התשס"א-2001
**וריאציה 3 — שינוי הכללים:** האם הכללים השתנו בעניין זה? ← כן, בעבר היו מגבלות רחבות יותר על ציון תפקידים בעיתון. בג"ץ 6250/05 איציק לוי נ'' לשכת עורכי הדין בישראל (20.10.2005)', 'פרסום תפקידים בלשכה ← מותר (כלל 3(ב)(17)) ← בכפוף למגבלות כלליות.',
    '["כללי לשכת עורכי הדין (פרסומת), התשס\"א-2001, כללים 3(ב)(17), 3(ב)(18)", "בג\"ץ 6250/05 איציק לוי נ'' לשכת עורכי הדין בישראל (20.10.2005)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, אסור לציין תפקידים וחברות בלשכת עורכי הדין בפרסומת בעיתון.', false, 'טענה זו שגויה. על פי הכללים העדכניים, מותר לציין תפקידים וחברות בלשכה בפרסומת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, מותר לציין תפקידים וחברות בלשכת עורכי הדין בפרסומת, ובלבד שהפרסומת עומדת ביתר תנאי הכללים.', true, 'כלל 3(ב)(17) לכללי לשכת עורכי הדין (פרסומת) מתיר לכלול בפרסומת ''תפקידים וחברות בלשכת עורכי הדין או בארגונים משפטיים בארץ או בחוץ לארץ''. לכן, ציון תפקיד יו"ר ועדה בלשכה מותר, בכפוף לעמידה ביתר תנאי הכללים (כגון גודל המודעה, תוכן שאינו מטעה וכד'').', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, אלא אם כן התפקיד אינו שיפוטי או מעין שיפוטי.', false, 'טענה זו שגויה. המגבלה על תפקידים שיפוטיים או מעין שיפוטיים מתייחסת לתפקידים שאדם ממלא על פי דין, ולא לתפקידים בלשכה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, אך רק אם הפרסומת מופיעה באתר האינטרנט של עורך הדין ולא בעיתון.', false, 'טענה זו שגויה. הכללים העדכניים מאפשרים ציון תפקידים בלשכה גם בפרסומת בעיתון, בכפוף למגבלות אחרות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'פרסומת קופצת באינטרנט',
    4, 'עו"ד דניאל פרסם את משרדו באמצעות ''פרסומת קופצת'' (Pop Up) באתר אינטרנט כללי. האם פעולה זו מותרת על פי כללי לשכת עורכי הדין (פרסומת)?', 'שאלה זו עוסקת במגבלות הספציפיות על פרסומת באינטרנט לעורכי דין, ובפרט באיסור על שימוש ב''פרסומות קופצות''. היא מדגישה את הפירוט הקיים בכללי לשכת עורכי הדין (פרסומת) לגבי אמצעי הפרסום המותרים והאסורים.', 'כללי לשכת עורכי הדין (פרסומת), התשס"א-2001, מפרטים באופן מדויק את אמצעי הפרסום המותרים לעורכי דין. כלל 3(א)(5) מתיר פרסומת באתרי אינטרנט, ברשתות חברתיות ובישומונים ייעודיים לעורכי דין, אך קובע מספר סייגים. אחד הסייגים המפורשים הוא בסעיף קטן (ד) לכלל 3(א)(5), הקובע כי ''פרסומת קופצת (Pop Up)'' אסורה. לכן, פעולתו של עו"ד דניאל אסורה על פי הכללים.',
    'הטעות היא להניח שכל פרסום באינטרנט מותר, או להתעלם מהסייגים הספציפיים הקבועים בכללי הפרסומת לגבי אמצעים מסוימים.', '["פרסומת אסורה", "כללי לשכת עורכי הדין (פרסומת)", "פרסומת קופצת (Pop Up)", "אתר אינטרנט", "אתיקה מקצועית"]'::jsonb, '**וריאציה 1 — איסור פרסומת קופצת:** האם מותר לפרסם ב''פרסומת קופצת''? ← לא, אסור על פי כלל 3(א)(5)(ד) לכללי הפרסומת. כלל 3(א)(5)(ד) לכללי לשכת עורכי הדין (פרסומת), התשס"א-2001
**וריאציה 2 — אמצעי פרסום מותרים:** אילו אמצעי פרסום מותרים באינטרנט? ← אתרי אינטרנט, רשתות חברתיות, יישומונים ייעודיים (למעט תכנים אסורים). כלל 3(א)(5) לכללי לשכת עורכי הדין (פרסומת), התשס"א-2001

**וריאציה 3 — פרסומת באתר של אחרים:** האם מותר לפרסם באתר של אחרים? ← לא, אתר אינטרנט של עורך דין לא יכלול פרסומות של אחרים. כלל 3(ח) לכללי לשכת עורכי הדין (פרסומת), התשס"א-2001', 'פרסומת קופצת ← אסורה. פרסומת באינטרנט ← מותרת בתנאים.',
    '["כללי לשכת עורכי הדין (פרסומת), התשס\"א-2001, כללים 3(א)(5), 3(א)(5)(ד), 3(ח)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, פרסומת באינטרנט מותרת בכל צורה שהיא, כל עוד אינה מטעה.', false, 'טענה זו שגויה. קיימות מגבלות ספציפיות על פרסומת באינטרנט, כולל איסור על פרסומות קופצות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, פרסומת קופצת (Pop Up) אסורה על פי כללי לשכת עורכי הדין (פרסומת).', true, 'כלל 3(א)(5)(ד) לכללי לשכת עורכי הדין (פרסומת) קובע במפורש כי ''פרסומת קופצת (Pop Up)'' אסורה כאמצעי פרסום לעורכי דין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם הפרסומת מופיעה באתר אינטרנט ייעודי לעורכי דין.', false, 'טענה זו שגויה. האיסור על פרסומת קופצת הוא גורף ואינו תלוי בסוג האתר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן הפרסומת כוללת מלל קולי או מוזיקה.', false, 'טענה זו שגויה. מלל קולי או מוזיקה מותרים בפרסומת באתר אינטרנט של עורך הדין, אך אינם מכשירים פרסומת קופצת.', 4);

